P.entries["item:99-year-old-port"] = {n="99年波尔多陈酿",s="99年波尔多陈酿是一瓶极为罕见的陈年烈酒，由藏宝海湾运出，作为送给加兹鲁维的私人礼物。在棘齿城的码头发生货运事故后，它被一个名叫Mad Magglish的疯子抢走，此人随后逃进了哀嚎洞穴外扭曲的隧道中。",h="99年波尔多陈酿是一瓶极为罕见的陈年烈酒，由藏宝海湾运出，作为送给加兹鲁维的私人礼物。在棘齿城的码头发生货运事故后，它被一个名叫Mad Magglish的疯子抢走，此人随后逃进了哀嚎洞穴外扭曲的隧道中。",kw={"99年波尔多陈酿","比戈弗兹","加兹鲁维","mad magglish","波尔多陈酿","棘齿城","里维加兹","哀嚎洞穴"},ang={["class:Rogue"]="Mad Magglish依靠业余的潜行技巧躲藏在哀嚎洞穴外的黑暗中，但一个技术娴熟的潜行者可以轻易地将他从阴影中逼出来。"},sec={{t="高价值货物的倾覆",b="跨越无尽之海运输珍贵货物总是伴随着风险，但在棘齿城的一次例行清晨卸货中，起重机操作员比戈弗兹却让情况变得糟糕透顶。为了清理来自藏宝海湾堆积如山的货物，这名地精超负荷操作他的起重机，导致如山般的板条箱砸落在码头上。在混乱之中，镇上的怪人——一个名叫Mad Magglish的麻烦人物——抢走了一瓶极为陈年的99年波尔多陈酿，并逃向了哀嚎洞穴方向的山丘。"},{t="外交陈酿",b="被盗的波尔多陈酿并非普通的烈酒；它是Blackwater Raiders的大财主里维加兹送给棘齿城总工程师兼统治者加兹鲁维的一份受人尊敬的外交礼物。丢失了如此珍贵的货物威胁到了比戈弗兹的生计，并加剧了与码头管理员之间的紧张关系。那个难以捉摸的窃贼逃进了洞穴黑暗的外部石窟中，带着未开封的奖品潜伏在阴影里，迫使码头工人不得不招募外来的雇佣兵，赶在加兹鲁维发现这一失误之前将其取回。"}},faq={{q="99年波尔多陈酿最初是送给谁的？",a="这瓶酒是由藏宝海湾的主人大财主里维加兹寄出的，作为送给棘齿城老板加兹鲁维的一份高价值私人礼物。",al={"波尔多陈酿是给谁的","谁得到了波尔多陈酿","加兹鲁维的礼物"}},{q="Mad Magglish是如何得到这瓶波尔多陈酿的？",a="起重机操作员比戈弗兹试图卸下的货物超出了他设备的承受能力，导致板条箱散落在棘齿城的码头上。Mad Magglish趁乱抢走了这瓶陈年佳酿并逃之夭夭。",al={"它如何被盗","谁偷了波尔多陈酿","码头事故"}},{q="Mad Magglish把酒带到了哪里？",a="Magglish穿过贫瘠之地逃往内陆，躲进了通往哀嚎洞穴的岩石前厅和外部隧道中。",al={"mad magglish在哪里","波尔多陈酿藏在哪里","波尔多陈酿位置"}},{q="为什么比戈弗兹没有亲自去取回波尔多陈酿？",a="比戈弗兹一直追着窃贼到了哀嚎洞穴的入口，但因为惧怕洞穴中出没的野兽和堕落的德鲁伊，他拒绝进入其中。",al={"为什么比戈弗兹不去追","起重机操作员是个胆小鬼"}}},fx={["5b0242c9"]={q="99年波尔多陈酿是什么？",a="这瓶波尔多陈酿非常罕见，且年份久远，它是从藏宝海湾千里迢迢运来的。这是大财主里维加兹作为一份尊贵的个人礼物送给棘齿城的总工程师兼领袖加兹鲁维的，这瓶陈年佳酿代表了地精贸易大亨之间无价的敬意。",al={"99年波尔多陈酿是什么","99年波尔多陈酿","波尔多陈酿"}}},fp="16,288,24.521.0,18.522.1,50.122.0,42.205.0,39.130.0,48.164.0"}
P.entries["item:a-bloodstained-journal-page"] = {n="一张染血的日记书页",s="一张在调查斯塔文·密斯特曼托时发现的破损且染血的羊皮纸。厚重的血迹中依稀能辨认出几个字，指挥官阿尔泰娅·埃伯洛克请求对上面的字迹进行鉴定。",h="一张在调查斯塔文·密斯特曼托时发现的破损且染血的羊皮纸。厚重的血迹中依稀能辨认出几个字，指挥官阿尔泰娅·埃伯洛克请求对上面的字迹进行鉴定。",kw={"染血的","达尔塔","夜色镇","暮色森林","埃伯洛克","字迹","日记","斯塔文"},ang={["faction:Alliance"]="对于王国的保卫者来说，这份可怕的文件是夜色镇守夜人在调查期间所审查的证据。"},sec={{t="一份可怕的证据",b="指挥官阿尔泰娅·埃伯洛克时刻警惕着夜色镇的安全，她请求对这张破损且溅满血迹的纸页上的字迹进行检查。尽管血迹很厚，但仍有一些文字清晰可辨，足够让书记员达尔塔将其与城镇登记册进行比对。"},{t="字迹与罪行",b="为了在执行正义之前消除任何疑虑，指挥官埃伯洛克求助于夜色镇市政厅的登记员——书记员达尔塔。多年来归档市政签名的经历，让达尔塔成为了当地笔迹鉴定方面的权威。在将这张染血的书页与市政记录进行比对后，达尔塔最终证实这确实是斯塔文的笔迹，从而坐实了这位家庭教师的罪行。"}},faq={{q="这张染血的日记书页是什么？",a="这是一张与调查斯塔文·密斯特曼托有关的破损且染血的书页。指挥官阿尔泰娅·埃伯洛克请求书记员达尔塔鉴定上面的字迹。",al={"染血的日记书页","斯塔文日记书页","染血书页"}},{q="谁能确认是谁写了这张书页？",a="夜色镇市政厅的书记员达尔塔。作为城镇登记册的保管员，他通过将书页上的笔迹与存档的旧签名进行比对，从而验证了这是斯塔文的笔迹。",al={"谁阅读书页","书记员达尔塔日记","谁鉴定字迹"}},{q="为什么阿尔泰娅·埃伯洛克需要检查这张书页？",a="指挥官阿尔泰娅监视斯塔文已经有一段时间了，她希望书记员达尔塔能将这张书页与城镇登记册进行比对。她需要确定两者是否出自同一人之手。",al={"为什么阿尔泰娅需要书页","为什么检查字迹"}},{q="这张书页在调查中起什么作用？",a="这张书页被送到夜色镇交给书记员达尔塔，以便他将上面的字迹与登记册进行比对。在他鉴定完毕后，调查将在指挥官埃伯洛克的带领下继续进行。",al={"书页之后发生了什么","斯塔文后续任务"}}},fx={e0fa872a={q="染血的日记书页来自哪里，是谁制作的？",a="这张书页是Stalvan Mistmantle个人日记的残页。上面残留的文字描述了他的绝望以及他想要血债血偿的意图。",al={"谁写了染血的日记书页","stalvan日记书页来源","染血的书页来自哪里"}}},fp="27,210,24.255.0,21.376.1,39.163.0,36.173.0,50.184.0,47.175.1"}
P.entries["item:a-clue-to-sanders-treasure"] = {n="A Clue to Sanders' Treasure",s="A Clue to Sanders' Treasure是一张由臭名昭著的海盗桑德斯船长留下的风化羊皮纸。它是分散在西部荒野的断崖和海岸线上的寻宝活动的第二步。",h="A Clue to Sanders' Treasure是一张由臭名昭著的海盗桑德斯船长留下的风化羊皮纸。它是分散在西部荒野的断崖和海岸线上的寻宝活动的第二步。",kw={"木桶","烟囱","线索","海盗","桑德斯","宝藏","西部荒野"},sec={{t="海盗的谜题",b="这张羊皮纸是在跟随桑德斯船长的第一份藏宝图后发现的，它提供了通往西部荒野内陆的进一步指引。潦草的字迹指引寻宝者从海岸向正东方向前进，敦促他们爬上断崖，朝主路走去。桑德斯将他的下一个标记藏在了一个旧木桶里，木桶就放在一座废弃烟囱的破败石堆旁，这引导着寻宝者深入这片动荡的农田。"}},faq={{q="这是什么线索？",a="这是一张由桑德斯船长留下的手写便条，指引着任何足够聪明能追踪他足迹的人，找到他在西部荒野的另一个隐藏容器。",al={"桑德斯的线索","a clue to sanders' treasure","什么是a clue to sanders' treasure"}},{q="这条线索指向哪里？",a="这条线索指引寻宝者向正东方向爬上沿海断崖，前往西部荒野的大路，在那里，一个旧木桶被放置在一座废弃的烟囱旁边。",al={"我该去哪","线索目的地","烟囱位置"}},{q="谁是桑德斯船长？",a="桑德斯船长是一位海盗，他的遗产通过他隐藏在西部荒野海岸和乡村各处的宝藏和谜题流传至今。",al={"谁是桑德斯船长","桑德斯传说","桑德斯船长"}}},fx={e66b6229={q="这条线索来自哪里，是谁制作的？",a="这份书面笔记是由Captain Sanders留下的，他是一位臭名昭著的剑客，在西部荒野各处埋藏了他的非法战利品。这位狡猾的船长并没有留下一张直接指向他财宝的地图，而是写下了一连串谜题和指示，将每条信息隐藏在海岸各处的地标中，以考验任何胆大心细、足以追踪他遗产的人。",al={"谁制作了桑德斯的线索","线索来自哪里","线索的起源"}},["4dc920ed"]={q="为什么这条线索对寻宝者很有价值？",a="单看这张羊皮纸，它只是一首晦涩难懂的打油诗，但对于一位立志发财的人来说，它是揭开Captain Sanders传说中的隐藏宝藏的关键一步。按照上面的指示是找到他精心设计的寻宝游戏中下一个线索的唯一途径，并最终获得这位海盗船长私藏的所有财宝。",al={"为什么要桑德斯的线索","为什么线索很重要","桑德斯的线索有什么用"}}},fp="27,167,17.361.0,18.134.0,26.124.0,24.133.0"}
P.entries["item:a-dusty-unsent-letter"] = {n="一封覆满灰尘的信",s="“一封覆满灰尘的信”是从西部荒野的一个旧脚踏箱里发现的一张被遗忘的羊皮纸。它提供了至关重要的证据，证明了难以捉摸的斯塔文·密斯特曼托在失踪前曾居住在月溪镇。",h="“一封覆满灰尘的信”是从西部荒野的一个旧脚踏箱里发现的一张被遗忘的羊皮纸。它提供了至关重要的证据，证明了难以捉摸的斯塔文·密斯特曼托在失踪前曾居住在月溪镇。",kw={"书记员达尔塔","夜色镇","一封覆满灰尘的信","弃灵","月溪镇","斯塔文·密斯特曼托","斯塔文的传说"},ang={["faction:Alliance"]="拼凑起斯塔文的踪迹有助于夜色镇准确记录那些从西部荒野到暮色森林流浪在人类定居点之间的旅行者和流放者。"},sec={{t="尘封的线索",b="在调查神秘的斯塔文·密斯特曼托的过去时，调查人员在月溪镇的一个旧脚踏箱里发现了这封未寄出的信。夜色镇的城镇登记册上仍将他的最后住址记录为Moonbrook Schoolhouse，书记员达尔塔一直想知道他是否真的在那里住过。这封未寄出的信件提供了缺失的环节，证实斯塔文确实在西部荒野的小镇上居住过一段时间。然而，它的出现也引发了令人不安的疑问，因为取走它会惊动一个复仇心切的弃灵，它带着怨毒守护着斯塔文过去的残迹。"},{t="更新登记册",b="将这封信带到夜色镇市政厅交给书记员达尔塔，它便成了更新城镇登记册的确凿证据。达尔塔注意到这封信从未寄出显得十分蹊跷，这暗示了斯塔文在联盟南方王国所留下的匆忙离去和秘密踪迹。"}},faq={{q="这封信在哪里可以找到？",a="这封信是从西部荒野月溪镇内的一个废弃脚踏箱中寻回的，它被藏在如今已被迪菲亚潜行者占领的破败房屋中。",al={"信件位置","哪里获得覆满灰尘的信","月溪镇的信"}},{q="为什么这封信从未寄出？",a="确切原因尚不明确，但书记员达尔塔觉得非常可疑。这表明斯塔文·密斯特曼托可能匆忙逃离了月溪镇，或者在离开前遗弃了他的信件。",al={"为什么未寄出","斯塔文未寄出的信","信是给谁的"}},{q="谁需要看这封信？",a="这封信必须交给书记员达尔塔，他在夜色镇市政厅内管理着城镇登记册。",al={"把信交给谁","书记员达尔塔的信","上交信件"}},{q="为什么发现它时会有鬼魂攻击？",a="翻动脚踏箱会召唤出一个与斯塔文令人难忘的遗产相连的弃灵。它会攻击任何窥探他被遗忘的生活的人，并用斯塔文的诅咒折磨入侵者。",al={"弃灵","为什么会有鬼魂产生","斯塔文的诅咒"}}},fx={f7d2f799={q="“一封覆满灰尘的信”是什么？",a="这块破旧的羊皮纸是月溪镇一个旧脚箱里未寄出的信件。它是Stalvan Mistmantle曾居住在西部荒野，随后从当地历史中销声匿迹的有力证据。",al={"一封覆满灰尘的信","什么是覆满灰尘的信","月溪镇的覆满灰尘的信"}},["9d1bfc16"]={q="“一封覆满灰尘的信”来自哪里，是谁制作的？",a="这封信被留在了月溪镇，存放在这座荒废城镇的一个脚箱里。它是在Stalvan Mistmantle在西部荒野逗留期间写的，是他写给村外联系人的，但出于某种未知的原因，它在发出之前就被遗弃了。",al={"谁写了覆满灰尘的信","这封信来自哪里","覆满灰尘的信的起源"}},ab0e7a8a={q="为什么有人想要“一封覆满灰尘的信”？",a="夜色镇的书记员达尔塔需要官方证据来更新关于Stalvan Mistmantle的城镇登记记录。由于城镇记录存在缺失，这封信提供了Stalvan曾居住在月溪镇的必要核实信息，使达尔塔能够妥善记录他过去的行踪。",al={"谁想要覆满灰尘的信","为什么要留着覆满灰尘的信","为什么要带信给达尔塔"}}},fp="21,195,18.599.0,21.306.1,27.165.0,30.197.0,29.110.0,41.202.0"}
P.entries["item:a-faded-journal-page"] = {n="一张褪色的日记书页",s="“一张褪色的日记书页”是从艾尔文森林中Marshal Haggard隐居住所楼上的箱子里找到的一份旧羊皮纸。它是揭开围绕Stalvan Mistmantle黑暗历史的关键线索。",h="“一张褪色的日记书页”是从艾尔文森林中Marshal Haggard隐居住所楼上的箱子里找到的一份旧羊皮纸。它是揭开围绕Stalvan Mistmantle黑暗历史的关键线索。",kw={"夜色镇","艾尔文森林","一张褪色的日记书页","marshal haggard","斯密茨","stalvan"},ang={["faction:Alliance"]="发掘这份被遗忘的记录有助于解决一个长期困扰着艾尔文森林和暮色森林河流两岸居民的悬案。"},sec={{t="箱子里的羊皮纸",b="当退休的Marshal Haggard在艾尔文森林东部边界定居时，这张饱经风霜的羊皮纸被遗留在一个旧箱子里，多年来无人问津。由于Haggard视力衰退，无法解读其内容，这张书页一直被搁置，直到探索Stalvan Mistmantle传说的冒险者将其找回。"},{t="通往夜色镇的线索",b="虽然Haggard无法阅读那模糊的文字，但他指引调查者穿过河流，前往暮色森林的Scarlet Raven Tavern。旅店老板斯密茨在检查书页时，一眼就认出了那独特的笔迹，直接将这段日记内容与萦绕该地区的阴郁传说联系了起来。"}},faq={{q="在哪里可以找到一张褪色的日记书页？",a="这张书页是在艾尔文森林东部，靠近与暮色森林交界河流处的Marshal Haggard住所楼上的箱子里发现的。",al={"书页位置","一张褪色的日记书页在哪里","箱子位置"}},{q="为什么Marshal Haggard自己读不了这张书页？",a="Marshal Haggard是一位年迈的老兵，视力严重衰退，几乎已经失明，无法解读羊皮纸上褪色的字迹。",al={"为什么haggard读不了它","marshal haggard视力受损"}},{q="谁认出了日记书页上的笔迹？",a="夜色镇Scarlet Raven Tavern的旅店老板斯密茨在看到这张书页时，立刻认出了上面的笔迹。",al={"谁认识这笔迹","谁读了这张书页"}},{q="守护着装有书页的箱子的东西是什么？",a="打开楼上的箱子会惊动一个充满敌意的弃灵，它会在调查者能安全查看书页前发动攻击。",al={"箱子里的鬼魂","箱子处有什么在攻击"}}},fx={["6378278c"]={q="“褪色的日记书页”是什么？",a="这是一张陈旧、风化的羊皮纸，是从Marshal Haggard家中的一个箱子里找到的。上面的文字随着时间的推移已经变得模糊不清，但它保留了一段真实的条目，详细记录了Stalvan Mistmantle的个人想法和行踪，是揭开他黑暗历史的一条重要线索。",al={"什么是褪色的日记书页","褪色的日记书页","褪色的日记书页信息"}},["0f9a7ce9"]={q="“褪色的日记书页”来自哪里？",a="这张书页是Stalvan Mistmantle本人作为其个人日记的一部分书写的。它最终出现在Marshal Haggard后来居住在艾尔文森林和暮色森林交界处附近的住宅楼上，被放在一个装有废弃羊皮纸的箱子里。",al={"褪色的日记书页起源","谁写了褪色的日记书页","褪色的日记书页来自哪里"}},["200aee1d"]={q="为什么要寻找“褪色的日记书页”？",a="寻找被称为Stalvan Mistmantle这一神秘人物背后真相的调查员需要这张书页来拼凑他的过去。因为上面的笔迹非常独特，将其展示给夜色镇的旅店老板斯密茨等见多识广的当地人，可以获得关于Stalvan历史和行踪的重要线索。",al={"为什么要寻找褪色的日记书页","为什么要用到褪色的日记书页","褪色的日记书页目的"}}},fp="20,215,22.343.0,22.315.1,38.153.0,51.165.0,51.141.0,44.127.0"}
P.entries["item:a-letter-to-grelin-whitebeard"] = {n="给格瑞林·白须的信",s="这份封好的信件收件人是格瑞林·白须，一位驻扎在寒脊山谷冰雪荒野中的资深矮人。信件从山中都城铁炉堡寄出，这份罕见的公文为偏远的边境送去了消息和指令。",h="这份封好的信件收件人是格瑞林·白须，一位驻扎在寒脊山谷冰雪荒野中的资深矮人。信件从山中都城铁炉堡寄出，这份罕见的公文为偏远的边境送去了消息和指令。",kw={"寒脊山谷","丹莫罗","格瑞林·白须","铁炉堡","信件","邮件投递"},ang={["race:Dwarf"]="在丹莫罗寒冷的山口传递公文，是年轻的矮人登山者和想要建立功勋的新兵们的一项基本职责。"},sec={{t="来自山中的公文",b="寒脊山谷雪盆地中的生活十分孤立，对于那些驻扎在安威玛尔安全区之外的人来说更是如此。像这样的信件构成了连接前线侦察兵、学者与铁炉堡大厅的关键纽带。这封信件沿着山路被送往南方，将来自首都的消息带到了格瑞林·白须的荒野营地。"}},faq={{q="格瑞林·白须是谁？",a="格瑞林·白须是一位矮人侦察兵和探险家，驻扎在寒脊山谷的东南部。他依靠从安威玛尔来的信使来获知铁炉堡的事宜和指令。",al={"格瑞林·白须","格瑞林是谁","收件人"}},{q="这封信来自哪里？",a="这份信件源自矮人首都铁炉堡，经由寒脊山谷当地的邮递员转发，并最终被送往野外。",al={"信件来源","谁寄的信","信从哪来"}},{q="信里写了什么？",a="这是国王麦格尼·铜须写的一张简短字条。国王公务繁忙，授权格瑞林可以使用他的权威来处理巨魔问题，无论他认为合适的方式是什么，特别是如果他能找到一个快速的解决方案。格瑞林对此表示欢迎，因为他已经有一段时间没有收到铁炉堡的消息了。",al={"信件内容","信上说了什么","信件文本"}}},fx={["163f292d"]={q="“给格瑞林·白须的信”是什么？",a="这是一封从铁炉堡发出的密封信函，经过寒脊山谷，准备送达在路边营地的格瑞林·白须手中。",al={"什么是给格瑞林·白须的信","给格瑞林·白须的信","这封信是什么"}},b0fcb20c={q="为什么格瑞林·白须想要这封信？",a="格瑞林在他的寒脊山谷营地驻扎已久，一直没有收到来自主城的消息。他渴望收到铁炉堡的消息。",al={"为什么要送给格瑞林的信","为什么格瑞林想要这封信","谁想要格瑞林的信"}}},fp="29,270,28.367.0,25.210.0,32.165.0,26.286.0"}
P.entries["item:a-mysterious-message"] = {n="神秘的信件",s="神秘的信件是从一名穿行在西部荒野的信使身上截获的一份通信。这封发给共谋者的密函为人民民兵提供了关键证据，揭示了在幕后指挥迪菲亚潜行者在当地行动的核心首脑。",h="神秘的信件是从一名穿行在西部荒野的信使身上截获的一份通信。这封发给共谋者的密函为人民民兵提供了关键证据，揭示了在幕后指挥迪菲亚潜行者在当地行动的核心首脑。",kw={"blacknails","迪菲亚信使","艾德温·范克里夫","格里安·斯托曼","月溪镇","神秘的信件","西部荒野"},ang={["class:Rogue"]="被截获的密函让潜行者得以一窥迪菲亚地下势力所使用的行动安全、信使路径和加密通讯。",["faction:Alliance"]="对于协助西部荒野的联盟勇士来说，截获这份文件证明了困扰该王国农田的动乱并非简单的随机土匪行为，而是由艾德温·范克里夫领导的一场有预谋的叛乱。"},sec={{t="关于Blacknails的低语",b="这封神秘的密函不仅证实了范克里夫的最高领导权，还提到了阴谋中涉及的其他人物，包括一个被称为“Blacknails”的神秘同伙。虽然他们的地下网络的全貌仍未可知，但解读这份文件为人民民兵提供了必要的筹码，让他们得以策反被俘的切窃贼，并定位该兄弟会的真正据点。"},{t="被截获的命令",b="这封信由一名往返于月溪镇、金海岸矿洞和詹戈洛德矿洞之间执行迪菲亚任务的信使携带，是格里安·斯托曼调查中的关键突破。数周以来，人民民兵一直怀疑土匪暴乱背后有组织在指挥，但苦于没有确凿证据。截获这封密函无疑证实了艾德温·范克里夫指挥着该地区兄弟会的行动，并通过暗号等级和中间人来管理其网络。"}},faq={{q="这封信向人民民兵揭示了什么？",a="这封信为格里安·斯托曼提供了确凿的证据，证明艾德温·范克里夫正在积极指挥迪菲亚潜行者在西部荒野的行动，这证实了民兵对于究竟是谁在指挥这些不法之徒的最坏猜想。",al={"字条上写了什么","神秘的信件背景故事","信里有什么内容"}},{q="Blacknails是谁？",a="Blacknails是截获的信件中提到的一个同伙或特工。关于他们的身份或下落几乎没有其他记录，这使他们成为在迪菲亚网络深处活动的神秘人物之一。",al={"blacknails是谁","blacknails背景故事","迪菲亚blacknails"}},{q="谁携带了这封信？",a="这封信由一名迪菲亚信使携带，他在月溪镇、金海岸矿洞和詹戈洛德矿洞之间西部荒野尘土飞扬的道路上穿行，以协调土匪的行动。",al={"谁有这封信","谁掉落神秘的信件","迪菲亚信使"}},{q="格里安·斯托曼读过之后发生了什么？",a="随着范克里夫的参与得到证实，民兵将重点转向寻找迪菲亚的总部。一名被俘的窃贼同意以自己的性命为交换，带领侦察兵直接前往他们的秘密藏身处。",al={"what comes next","斯托曼的反应","神秘的信件之后"}}},fx={["9bec86bb"]={q="“神秘的信件”是什么？",a="这是一封由迪菲亚信使携带穿过西部荒野的密封信件。信是寄给一个名叫Blacknails的操作员的，包含着在该地区活动的阴谋分子之间的关键通信。",al={"神秘的信件","这封信是什么","迪菲亚便条"}},ea5b5889={q="“神秘的信件”来自哪里，是谁制作的？",a="这封信件出自迪菲亚潜行者的高层，写给他们的操作员Blacknails的指示，并通过连接月溪镇、金海岸矿洞和詹戈洛德矿洞的信使路线进行传送。",al={"谁写了神秘的信件","谁发了神秘的信件","神秘的信件起源"}},f3ab4b79={q="为什么格里安·斯托曼想要“神秘的信件”？",a="格里安·斯托曼和人民民兵团急于找到迪菲亚潜行者的秘密藏身处，并了解他们的指挥结构。截获这封信件为他们提供了确凿的书面证据，证明艾德温·范克里夫直接策划了迪菲亚潜行者的叛乱。",al={"为什么要神秘的信件","斯托曼为什么要信件","为什么获取神秘的信件"}}},fp="20,115,22.270.1,18.436.1,54.201.1,18.205.0,25.169.0,46.173.1"}
P.entries["item:a-simple-compass"] = {n="简易罗盘",s="简易罗盘是属于暴风城城市建筑师巴隆斯·阿历克斯顿的一件旧私人物品。它被存放在他在西部荒野被烧毁的家族农场里的一个小箱子里，是他早年成名于首都之前的一件珍贵纪念品。",h="简易罗盘是属于暴风城城市建筑师巴隆斯·阿历克斯顿的一件旧私人物品。它被存放在他在西部荒野被烧毁的家族农场里的一个小箱子里，是他早年成名于首都之前的一件珍贵纪念品。",kw={"阿历克斯顿","巴隆斯","出身","箱子","罗盘","农场","暴风城","西部荒野"},ang={["faction:Alliance"]="帮助巴隆斯·阿历克斯顿找回他丢失的纪念品，展现了迪菲亚起义所造成的人道代价，揭示了即使是暴风城中显赫的领导者，也因为西部荒野的动荡而失去了家族家园。",["race:Human"]="对于王国的国民来说，这只罗盘象征着暴风城内安全、镀金的庭院与西部荒野被遗弃、无法无天的边境之间那鲜明的对比。"},sec={{t="童年纪念品",b="在巴隆斯·阿历克斯顿成为指挥Cathedral Square大型工程的建筑大师之前，他从小在西部荒野的家族农场里劳作。这件简易罗盘是他人生中第一个导航仪器，很可能激发了他早年对几何、制图和探险的兴趣。当阿历克斯顿农场在迪菲亚潜行者的袭击中被烧毁时，这只罗盘被遗留在了废墟中一个结实的箱子里，即使周围的农田被强盗占领，它依然保存完好。"},{t="情感价值",b="巴隆斯的父亲设法从被毁的农场逃了出来，但没能带走家里的财物逃生。虽然这件仪器对于在暴风城石墙内工作的建筑大师来说几乎没有实际用途，但它的情感意义却极其重大。把它交还给巴隆斯，能让他难得地保留下一段与其卑微出身和童年宁静乡村生活相连的完好记忆。"}},faq={{q="简易罗盘是什么？",a="这是一件朴素的、非魔法的袖珍罗盘，属于巴隆斯·阿历克斯顿小时候在西部荒野家族农场生活时所有。",al={"简易罗盘","阿历克斯顿罗盘","巴隆斯罗盘"}},{q="罗盘在哪里？",a="它藏在阿历克斯顿的箱子里，位于西部荒野哨兵岭以西的阿历克斯顿农场的废墟中。",al={"哪里找到罗盘","罗盘位置","阿历克斯顿的箱子位置"}},{q="谁想要回这个罗盘？",a="这个罗盘属于暴风城的城市建筑师巴隆斯·阿历克斯顿，可以在Cathedral Square的市政厅附近找到他。",al={"谁需要罗盘","罗盘交还","罗盘主人"}},{q="为什么罗盘被遗弃在农场里？",a="阿历克斯顿家族农场遭到袭击、被焚毁，并被迪菲亚潜行者不法分子占领。巴隆斯的父亲不得不逃命，无法带走较重的财物，只能将箱子藏在废墟中。",al={"为什么留下罗盘","农场发生了什么"}}},fp="16,161,18.336.0,17.336.0,25.117.0,29.129.0,32.127.0,44.177.0"}
P.entries["item:a-stack-of-letters"] = {n="一摞信件",s="一摞信件是一小捆穿过山口被带入寒脊山谷的信件。虽然最初人们认为这些信件全都是给塔林·锐眼的，但实际上这捆信件中还包含着给驻扎在这片冰天雪地中的多名侦察兵的通信。",h="一摞信件是一小捆穿过山口被带入寒脊山谷的信件。虽然最初人们认为这些信件全都是给塔林·锐眼的，但实际上这捆信件中还包含着给驻扎在这片冰天雪地中的多名侦察兵的通信。",kw={"安威玛尔","寒脊山谷","寒脊山谷邮件投递","格瑞林·白须","一摞信件","塔林·锐眼"},ang={["race:Dwarf"]="对于在寒脊山谷开始旅程的年轻登山者来说，在雪地营地之间传递邮件是他们了解崎岖道路以及保卫丹莫罗的哨兵工作的初步体验。"},sec={{t="穿过山口",b="抵达丹莫罗崎岖山脉中偏远的营地是一项艰苦的工作，信使往往依靠路过的旅行者将邮件从安威玛尔送出。这捆信件穿过山口送达，原本是目的地为寒脊山谷更深处的侦察兵。虽然人们认为这些信件都是给湖畔营地的塔林·锐眼的，但仔细整理后发现，包裹中还有写给遍布雪原的其他哨所的信件，其中包括登山者格瑞林·白须。"}},faq={{q="这一摞信件里有什么？",a="这捆信件包含给驻扎在寒脊山谷的矮人们的私人信件和公文。虽然人们认为这些信件全都是给冰封湖泊附近的塔林·锐眼的，但整理后发现至少有一封信是写给格瑞林·白须的。",al={"信里写了什么","一摞信件的内容","信是给谁的"}},{q="谁把这些信寄到了寒脊山谷？",a="这些信件穿过山口进入寒脊山谷，在抵达安威玛尔后，被交给了愿意沿路运送它们的旅行者。",al={"信件是从哪里来的","谁寄出的信"}},{q="谁接收这些信件？",a="这个包裹首先由矮人侦察兵塔林·锐眼在他冰封湖泊旁的营地直接接收。在查看过这摞信件后，他发现了一封属于格瑞林·白须的信。",al={"谁收到了信","信件投递目标"}}},fx={["6f17116a"]={q="“一摞信件”是什么？",a="这是一捆通过山道抵达寒脊山谷的邮件。在安威玛尔交给你时，这叠信件包含了寄给驻扎在冰雪荒野当地登山者的通信。",al={"什么是一摞信件","一摞信件物品","信件是什么"}},["9fce371d"]={q="为什么有人想要“一摞信件”？",a="生活和巡逻在寒冷地带的登山者依赖常规邮寄来保持信息畅通。塔林·锐眼在冰冻的湖边等待这些公文已经有一段时间了，尽管检查后发现，这捆信件中并非每一封都是他的。",al={"为什么要递送信件","为什么塔林想要这些信件","一摞信件的用途"}}},fp="18,270,16.459.0,36.251.0,44.162.0,25.187.0"}
P.entries["item:a-torn-journal-page"] = {n="一张被撕破的日记书页",s="一张被撕破的日记书页是一块从暴风城运河边一个旧货运箱中找回的破损羊皮纸。它是了解斯塔文·密斯特曼特身份及其黑暗历史的一个重要物证，将暮色森林中发生的惨剧与保存在艾尔文森林的记录联系了起来。",h="一张被撕破的日记书页是一块从暴风城运河边一个旧货运箱中找回的破损羊皮纸。它是了解斯塔文·密斯特曼特身份及其黑暗历史的一个重要物证，将暮色森林中发生的惨剧与保存在艾尔文森林的记录联系了起来。",kw={"运河","暮色森林","斯塔文的传说","哈格德警官","密封的箱子","斯塔文·密斯特曼特","暴风城","一张被撕破的日记书页"},ang={["faction:Alliance"]="这张日记书页说明了暴风城和艾尔文森林内未解决的罪行和被遗忘的记录是如何向外延伸，并困扰着暮色森林那艰难的边境地区的。"},sec={{t="运河中的线索",b="这张书页被发现藏在暴风城运河边一个密封的储存箱底部，夹在旧书、传家宝和陶瓶之间，是在那些被遗忘的私人物品中被留下的。尽管它已经破损不堪，但页面上的笔迹特征明显，直接指向了斯塔文·密斯特曼特的过去，促使调查者去寻找那些可能仍能认出这笔迹的人。"},{t="追踪密斯特曼特的线索",b="由于文字已经风化，难以辨认，必须将书页带给熟悉王国旧档案的人。这一发现将调查者从暴风城引向了住在艾尔文森林的哈格德警官，这位老迈的军官视力虽已衰退，却仍记得密斯特曼特悲剧往事中那独特的字迹。"}},faq={{q="在哪里可以找到那张被撕破的日记书页？",a="这张书页是在暴风城运河边的一个密封储存箱中被发现的，它被埋在被遗忘的家庭杂物、狩猎战利品和一个旧陶瓶之下。",al={"被撕破的日记书页位置","哪里能找到被撕破的日记书页","密封的箱子 暴风城"}},{q="这页日记出自谁的日记本？",a="这张书页是斯塔文·密斯特曼特个人笔记的一部分。他曾是一位家庭教师，他那黑暗的过去和突然的失踪成为了暮色森林和艾尔文森林各地调查的对象。",al={"谁写了这张日记书页","被撕破的书页作者","谁是斯塔文"}},{q="谁能辨认那张被撕破的书页上的笔迹？",a="哈格德警官，一位住在大艾尔文森林东谷伐木场附近、年事已高且几近失明的退休军官，他认出了这笔迹，那是他在视力受损前曾见过的风格。",al={"我该把被撕破的书页带给谁","谁能读懂被撕破的日记书页","哈格德警官 日记"}},{q="为什么找到这张书页对暮色森林很重要？",a="夜色镇议会正在拼凑斯塔文·密斯特曼特的历史，以揭开他名字背后那些令人不安的事件和被埋藏已久的罪行的真相。",al={"为什么暮色森林关心日记","斯塔文与暮色森林的联系"}}},fx={["8b619691"]={q="“撕裂的日记书页”是什么？",a="撕裂的日记书页是一张在暴风城的一个密封储物箱里，被旧家传宝、书籍和狩猎战利品掩盖住的破烂书页。它是关于Stalvan Mistmantle的一份重要书面证据，提供了独特的笔迹样本，将他安静的过去生活与困扰暮色森林的黑暗谜团联系在了一起。",al={"撕裂的日记书页背景","什么是撕裂的日记书页","这本日记书页是什么"}}},fp="19,302,20.446.0,28.370.1,37.176.0,38.191.0,46.204.0,45.175.0"}
P.entries["item:abercrombie-s-crate"] = {n="亚伯克隆比的箱子",s="亚伯克隆比的箱子是古怪的隐士亚伯克隆比丢失的一个容器，里面装着精密的工具和收集的草药。在老头被掠夺成性的食人魔赶走后，它就被丢弃在暮色森林南部的沃古尔食人魔山入口附近。",h="亚伯克隆比的箱子是古怪的隐士亚伯克隆比丢失的一个容器，里面装着精密的工具和收集的草药。在老头被掠夺成性的食人魔赶走后，它就被丢弃在暮色森林南部的沃古尔食人魔山入口附近。",kw={"亚伯克隆比","亚伯克隆比的箱子","暮色森林","食人魔山","食人魔窃贼","沃古尔"},ang={["faction:Alliance"]="直接闯入沃古尔食人魔山的核心取回丢失的货物，揭示了威胁着暮色森林南部日益增长的怪物威胁。",["profession:Herbalism"]="亚伯克隆比表面上是为了稀有的植物群而冒险进入森林最黑暗的深处，这使得取回他的植物学家工具包成为了当地草药师熟悉的工作。"},sec={{t="丢失在食人魔手中",b="亚伯克隆比在远离他位于暮色森林西部的棚屋去采集植物时，遇到了一伙充满敌意的食人魔。为了保命，这位老隐士丢下了他装满珍贵仪器和采集草药的箱子。食人魔把他的财物拖回了位于沃古尔食人魔山的据点，随手将这个沉重的箱子丢在了他们的洞口附近。"},{t="奇怪的内容物",b="虽然亚伯克隆比声称这个箱子里装的仅仅是无害的工具和收集的植物，但他在箱子失而复得时那欣喜若狂且疑点重重的反应暗示着某种更加黑暗的东西。在一次口误中，这位隐士差点说出“感谢‘死灵……’”，随后立刻改口，这引发了人们对那些被盗工具究竟意图用于何种技艺的令人不安的疑问。"}},faq={{q="箱子位于何处？",a="这个箱子被遗弃在沃古尔食人魔山洞口旁边的户外，这是一个位于暮色森林南部丘陵地带、被食人魔盘踞的营地。",al={"箱子位置","亚伯克隆比的箱子在哪里","沃古尔箱子"}},{q="亚伯克隆比为什么会丢掉它？",a="亚伯克隆比在远离家园的地方采集草药时遭到了食人魔的伏击。手无寸铁且惊恐万分的他徒步逃离并丢弃了物资，随后被食人魔搬回了巢穴。",al={"食人魔是如何得到箱子的","为什么箱子在食人魔那里"}},{q="箱子里装着什么？",a="亚伯克隆比形容里面的东西是稀有草药和专业的采集工具。然而，他在收到箱子时那种奇怪的兴奋和口误表明，里面可能装有比普通的园艺剪刀邪恶得多的工具。",al={"箱子内容物","亚伯克隆比丢了什么"}},{q="为什么亚伯克隆比差点说出“感谢‘死灵……’”？",a="在拿回箱子后，亚伯克隆比脱口而出“感谢死灵……”然后匆忙改口感谢冒险者。他从未说明他差点要感谢谁或什么东西。",al={"亚伯克隆比死灵口误","感谢死灵的含义"}}},fx={["7a42047e"]={q="“亚伯克隆比的箱子”是什么？",a="这是一个属于亚伯克隆比的木制补给箱，他是一位住在暮色森林北路边破败棚屋里的隐士。亚伯克隆比声称箱子里装着他那孤独手艺所必需的稀有草药和精巧工具，尽管他古怪的行为和无意中泄露的只言片语暗示他看重箱子里的东西是出于更黑暗的目的。",al={"亚伯克隆比的箱子","箱子是什么","亚伯克隆比的箱子物品"}},c6e454ed={q="为什么亚伯克隆比想要找回他的箱子？",a="亚伯克隆比在觅食时被来自南部山丘的食人魔伏击，为了逃命被迫丢弃了他的补给品。他非常想念他的设备，声称没有它就无法继续他的草药研究，并承诺找回箱子能确保未来有快乐、高效的工作之夜。",al={"为什么要取回亚伯克隆比的箱子","为什么亚伯克隆比想要箱子","为什么要箱子"}}},fp="19,261,17.387.0,17.355.1,27.151.0,28.200.0,25.239.1,45.175.1"}
P.entries["item:admiral-proudmoore-s-orders"] = {n="普罗德摩尔将军的命令",s="普罗德摩尔将军的命令是库尔提拉斯军队在杜隆塔尔海岸线加固防线时留下的书面作战计划。这些文件是在大元帅在塞拉摩战败前撰写的，概述了持续不断的军事战略，这些战略至今仍在威胁着初生的兽人故土。",h="普罗德摩尔将军的命令是库尔提拉斯军队在杜隆塔尔海岸线加固防线时留下的书面作战计划。这些文件是在大元帅在塞拉摩战败前撰写的，概述了持续不断的军事战略，这些战略至今仍在威胁着初生的兽人故土。",kw={"本尼迪克特","杜隆塔尔","库尔提拉斯","纳兹格雷尔","命令","奥格瑞玛","普罗德摩尔","提拉加德"},ang={["faction:Horde"]="这些文件证明了部落中那些认为人类休战永远不会持久的人是对的，它们表明库尔提拉斯军队从登陆的那一刻起就打算发动一场灭绝战争。",["race:Troll"]="对于同样居住在这片海岸沿线的暗矛巨魔来说，这些命令证实了人类在杜隆塔尔海岸的存在仍然是一个紧迫的危险。"},sec={{t="仇恨的遗产",b="即使在大元帅戴林·普罗德摩尔在塞拉摩战死之后，他的远征军依然拒绝投降。这些战术指令是从提拉加德城堡的本尼迪克特中尉驻军处缴获的，详细描述了旨在削弱部落的长期机动和防御工事。这些命令证明，大元帅在杜隆塔尔的进攻并非仓促的突袭，而是一场旨在在他死后依然持续下去的有组织的战役。对于部落而言，这些缴获的文件提供了关于库尔提拉斯行动和威胁其边境的潜在增援部队的重要情报。"},{t="送往Grommash Hold",b="部落侦察兵认识到这些计划中所述的战略危险，将缴获的文件直接送往奥格瑞玛的Grommash Hold。这些命令被送到萨尔房间里的纳兹格雷尔手中，证实了他一直以来对大酋长的警告：人类永远不可信任，他们的侵略仍然是一个现实的威胁。这份情报敦促部落领导层为沿海可能发生的进一步入侵做好准备。"}},faq={{q="什么是普罗德摩尔将军的命令？",a="这是大元帅戴林·普罗德摩尔在塞拉摩战败前制定的军事指令。它们指挥着留在杜隆塔尔的残余库尔提拉斯士兵加固沿海立足点，并对部落发动战争。",al={"普罗德摩尔的命令","这些命令是什么","将军的命令物品"}},{q="这些命令是在哪里找到的？",a="这些命令是在针对驻扎在东南海岸附近的提拉加德城堡的库尔提拉斯残部的持续战斗中，在杜隆塔尔获得的。",al={"在哪里可以找到命令","命令位置","谁掉落命令"}},{q="谁需要看到这些命令？",a="这些文件被带给了纳兹格雷尔，他是奥格瑞玛智慧谷Grommash Hold内大酋长萨尔的顾问。",al={"我应该把这个交给谁","谁想要这些命令","命令上交"}},{q="为什么库尔提拉斯士兵还在杜隆塔尔作战？",a="尽管普罗德摩尔将军在战斗中阵亡，但他手下的军官（如本尼迪克特中尉）依然致力于执行他消灭兽人的使命。这些命令为驻军提供了预先制定的战略，使他们即使在没有大元帅直接指挥的情况下，也能继续骚扰杜隆塔尔。",al={"为什么人类在杜隆塔尔","为什么提拉加德城堡充满敌意","戴林已死为何还要战斗"}}},fp="27,299,18.577.0,25.423.1,37.219.0,34.150.0,30.111.0,53.286.0"}
P.entries["item:ados-fragment"] = {n="阿度斯碎片",s="阿度斯碎片是一块刻有文字的石板，出土于湿地的维尔加挖掘场。它与另外三块碎片一同构成了戈阿兹之石，这是一件刻有神秘泰坦铭文的远古遗物。",h="阿度斯碎片是一块刻有文字的石板，出土于湿地的维尔加挖掘场。它与另外三块碎片一同构成了戈阿兹之石，这是一件刻有神秘泰坦铭文的远古遗物。",kw={"阿度斯碎片","挖掘","戈阿兹之石","上古之神","遗物","泰坦","湿地","维尔加"},ang={["race:Dwarf"]="对于探险者协会而言，回收像阿度斯碎片这样的泰坦遗物，对于发掘矮人种族及其远古创造者的真正起源至关重要。"},sec={{t="戈阿兹之石碎片",b="阿度斯碎片出土于维尔加挖掘场泥泞的沟壑中，它是重建戈阿兹之石所需的四块缺失碎片之一。在迅猛龙占领挖掘场之前，勘察员维尔加就开始翻译那块主要石板，却发现铭文在关键时刻中断了。这些散落的碎片——分别命名为阿度斯、莫德、戈尔姆和内鲁——散落在废墟各处，隐藏在徘徊的野兽之间，被埋在古老的容器和土堆里。"},{t="泰坦铭文",b="将阿度斯碎片与其他三块碎片重新拼合，勘察员维尔加就能解读刻在戈阿兹之石上的完整泰坦铭文。拼凑出的文字提到了一项伟大的神圣计划和一条注定失败的预言，最终揭示了一个不祥的宣告：“上古之神……被锁在土地之下。”这一发现暗示泰坦在很久以前将原始实体囚禁在艾泽拉斯地底。"}},faq={{q="什么是阿度斯碎片？",a="它是被称为戈阿兹之石的远古石板上断裂的一部分，发现于湿地的维尔加挖掘场。上面刻有塑造世界的泰坦所留下的文字。",al={"阿度斯碎片","什么是阿度斯","戈阿兹之石碎片阿度斯"}},{q="这块碎片在哪里可以找到？",a="它埋藏在湿地米奈希尔港以东的整个挖掘场中，通常藏在被领地意识极强的迅猛龙包围的古老遗物或松散的土堆里。",al={"阿度斯碎片在哪里","阿度斯位置","如何寻找阿度斯"}},{q="这块碎片上写着什么？",a="单独来看，这块碎片是不完整的。勘察员维尔加还需要莫德、戈尔姆和内鲁碎片，才能继续翻译这块石板。",al={"阿度斯碎片文字","阿度斯上写了什么","戈阿兹之石翻译"}},{q="谁需要这块碎片？",a="负责监管这处废弃挖掘场的探险者协会矮人勘察员维尔加，他需要用它来完成戈阿兹之石的翻译工作。",al={"谁需要阿度斯碎片","阿度斯碎片上交","维尔加阿度斯"}}},fx={f3ac27ac={q="阿度斯碎片来自何处，又是谁制作了它？",a="阿度斯碎片是戈阿兹之石的碎片，这是一件在湿地挖掘场发现的远古圣物。在它于废墟中碎裂成四块之前，泰坦曾在这块石头上刻下了神秘的铭文。",al={"阿度斯碎片来源","谁制作了阿度斯碎片","阿度斯碎片来自哪里"}}},fp="13,228,25.475.0,16.417.1,26.177.0,28.173.0,27.154.1,24.132.0"}
P.entries["item:agamand-family-axe"] = {n="阿加曼德家传战斧",s="阿加曼德家传战斧是一件保存在提瑞斯法林地北部的阿加曼德家族墓穴中的祖传遗物。这曾经是富有的磨坊主家族的武力象征，现在库勒曼·法席恩试图夺走它，以剥夺这亡灵家族仅存的尊严。",h="阿加曼德家传战斧是一件保存在提瑞斯法林地北部的阿加曼德家族墓穴中的祖传遗物。这曾经是富有的磨坊主家族的武力象征，现在库勒曼·法席恩试图夺走它，以剥夺这亡灵家族仅存的尊严。",kw={"阿加曼德","阿加曼德墓穴","阿加曼德家传战斧","阿加曼德磨坊","库勒曼·法席恩","传家宝","提瑞斯法林地"},ang={["class:Warrior"]="保存在墓穴中的传家宝武器表明，阿加曼德家族在拥有财富和粮食储备的同时，也拥有尚武的传统。",["race:Undead"]="对于被遗忘者来说，掠夺阿加曼德家族的传家宝是对洛丹伦旧贵族的一种彻底的清算，这些贵族在瘟疫面前同样不堪一击。"},sec={{t="阿加曼德家族的武器",b="在第三次战争之前，阿加曼德王朝作为富有的地主统治着提瑞斯法林地的北部丘陵，拥有广阔的磨坊和一座私人的家族墓穴。阿加曼德家传战斧与已故的族长和战士们一同陪葬在祖先的武器库中，即使天灾军团蹂躏了这处庄园并屠杀了居住者，它依然完好地保存在地下的武器架上。"},{t="恶意的报复",b="当亡灵天灾将堕落的阿加曼德家族成员复活为巫妖王麾下的无脑奴仆时，他们以前的仆人库勒曼·法席恩却以亡灵的身份幸存了下来，并对他的旧主人怀有刻骨的仇恨。法席恩将自己的死亡归咎于这个家族，他委托被遗忘者的流浪者进入墓穴，剥下武器架上的战斧、长剑、锤和匕首，抹去阿加曼德家族传承的最后遗迹。"}},faq={{q="阿加曼德家传战斧在哪里？",a="战斧位于阿加曼德家族墓穴内的一个武器架上，该墓穴位于提瑞斯法林地北部的阿加曼德磨坊北侧边缘。",al={"战斧位置","战斧在哪里","阿加曼德战斧地点"}},{q="谁想要阿加曼德家传战斧？",a="居住在布瑞尔的被遗忘者库勒曼·法席恩正在寻找这把武器，以及家族的匕首、锤和长剑，以此来剥夺他旧主人的荣誉。",al={"谁需要战斧","库勒曼·法席恩任务","谁想要阿加曼德传家宝"}},{q="为什么库勒曼·法席恩痛恨阿加曼德家族？",a="阿加曼德家族生前雇佣了法席恩，据他所述，正是他们直接导致了他的死亡。当他们作为亡灵爪牙在庄园里游荡时，他通过洗劫他们的墓穴来复仇。",al={"为什么法席恩想要传家宝","库勒曼·法席恩背景故事","法席恩的怨恨"}},{q="阿加曼德家传战斧是可用武器吗？",a="不是。这把战斧只是一件祖传遗物，纯粹作为任务物品被取回，以证明对该家族墓穴的亵渎。",al={"我可以装备这把战斧吗","战斧属性"}}},fx={e4f67fe3={q="什么是阿加曼德家传战斧？",a="阿加曼德家传战斧是提瑞斯法林地显赫的阿加曼德家族的传家武器。它与家族其他的珍贵武器一同保存在祖传的墓穴中，代表了该家族在天灾军团席卷洛丹伦、将活着的家族成员变成毫无意识的亡灵奴仆之前的尚武传承与遗产。",al={"阿加曼德战斧","什么是阿加曼德家传战斧","阿加曼德传家战斧"}}},fp="18,264,24.391.0,20.398.0,40.143.0,33.155.0,50.183.0,42.119.0"}
P.entries["item:agamand-family-dagger"] = {n="阿加曼德家传匕首",s="阿加曼德家传匕首是陨落的阿加曼德王朝的祖传遗物，安放在提瑞斯法林地北部的家族墓穴中的武器架上。库勒曼·法席恩想要得到这把刀，以及他们家族兵器库里的其余武器，以此剥夺他曾经的主人所剩下的最后遗产和荣誉。",h="阿加曼德家传匕首是陨落的阿加曼德王朝的祖传遗物，安放在提瑞斯法林地北部的家族墓穴中的武器架上。库勒曼·法席恩想要得到这把刀，以及他们家族兵器库里的其余武器，以此剥夺他曾经的主人所剩下的最后遗产和荣誉。",kw={"阿加曼德","阿加曼德磨坊","库勒曼·法席恩","墓穴","匕首","家传遗物","天灾军团","提瑞斯法林地"},ang={["class:Rogue"]="潜入墓穴越过复生的亡灵，从武器架上窃取珍贵的家族利刃，这不仅是经典的地下盗窃，更是一种冷酷的复仇行为。",["race:Undead"]="阿加曼德家传遗物代表了幸存的洛丹伦被遗忘者与他们曾经屈服于天灾军团无脑奴役的前主人之间苦涩的分歧。"},sec={{t="墓穴中的遗产",b="在第三次战争之前，阿加曼德家族在提瑞斯法林地的起伏草地上拥有广阔的地产和谷物磨坊。就像他们家族血脉的其他兵器一样，阿加曼德家传匕首在天灾军团造成的浩劫中幸存了下来，被锁在阿加曼德磨坊北部的家族墓穴中。这把匕首受到家族中躁动不安的亡灵残骸和巫妖王的无脑爪牙的守护，代表着曾经使这个家族凌驾于仆人和佃户之上的威望与武力传承。"},{t="恶意的征收",b="对于居住在布瑞尔、死前曾为阿加曼德家族效力的被遗忘者库勒曼·法席恩来说，这把刀代表的是苦涩的怨恨，而非高贵的血统。法席恩将自己的死亡直接归咎于这个家族，他指引冒险者进入阿加曼德家族墓穴，去取回这把匕首以及家族的长剑、战斧和钉锤。通过从他们的陵墓中掠夺这些祖传兵器，法席恩旨在剥夺那些现已成为天灾爪牙的家主们最后的一丝尊严，并确保阿加曼德的记忆被彻底抹去。"}},faq={{q="什么是阿加曼德家传匕首？",a="这是一件属于提瑞斯法林地富裕的阿加曼德家族的祖传武器。它和其他兵器一起被安葬在家族墓穴中，而该墓穴此后落入了天灾军团的控制之下。",al={"阿加曼德匕首","阿加曼德匕首是什么","提瑞斯法家族匕首"}},{q="在哪里可以找到阿加曼德家传匕首？",a="它位于提瑞斯法林地阿加曼德磨坊北端，阿加曼德家族墓穴深处的一个阿加曼德武器架上。",al={"在哪里寻找阿加曼德匕首","阿加曼德匕首位置","匕首武器架位置"}},{q="为什么库勒曼·法席恩想要这把匕首？",a="库勒曼·法席恩生前曾受雇于阿加曼德家族，并将自己的死归咎于他们。他要求得到这把匕首和其他家传遗物，是为了剥夺他前主人的荣誉并彻底摧毁他们。",al={"法席恩为什么要匕首","法席恩阿加曼德任务","为什么劫掠阿加曼德墓穴"}},{q="这套家传遗物中还有哪些武器？",a="除了匕首之外，这套家传遗物还包括阿加曼德家传长剑、阿加曼德家传战斧和阿加曼德家传钉锤，它们都散落在家族墓穴的武器架中。",al={"其他阿加曼德家传遗物","阿加曼德武器列表","墓穴里还有什么"}}},fp="21,305,21.520.0,22.524.0,34.194.0,41.139.0,43.193.0,47.181.0"}
P.entries["item:agamand-family-mace"] = {n="阿加曼德家传钉锤",s="阿加曼德家传钉锤是一件代代相传的传家宝，保存在提瑞斯法林地北部的阿加曼德家族墓穴中。它曾是洛丹伦北部一个富有王朝引以为傲的象征，如今却成了他们昔日的仆人库勒曼·法席恩为了泄愤而搜寻的目标。",h="阿加曼德家传钉锤是一件代代相传的传家宝，保存在提瑞斯法林地北部的阿加曼德家族墓穴中。它曾是洛丹伦北部一个富有王朝引以为傲的象征，如今却成了他们昔日的仆人库勒曼·法席恩为了泄愤而搜寻的目标。",kw={"阿加曼德家族墓穴","阿加曼德家传钉锤","阿加曼德传家宝","阿加曼德磨坊","库勒曼·法席恩","提瑞斯法林地"},ang={["race:Undead"]="阿加曼德墓穴遭受的亵渎表明，凡人残留的怨恨和不满往往会驱使被遗忘者去清算生前的旧账。"},sec={{t="毁灭的遗产",b="第三次战争前，阿加曼德家族在提瑞斯法林地的北部拥有广阔的农田和风车。和该地区其他的贵族一样，他们倒在了亡灵瘟疫之下。阿加曼德家族的成员被复活，成为了巫妖王的无脑奴仆，游荡在他们那满目疮痍的庄园里，而他们古老的家族珍宝则被锁在家族墓穴的深处。阿加曼德家传钉锤就存放在这些武器之中，它是这个被遗忘的家族如今沦为行尸走肉般的天灾军团的象征。"},{t="仆人的复仇",b="这把钉锤是库勒曼·法席恩想要夺取的四件家族传家宝之一。法席恩曾是该家族的雇员，他将自己的死亡归咎于这个家族。复活成为被遗忘者一员后，法席恩试图剥夺这些神志不清的阿加曼德人所剩的每一丝尊严与荣耀。通过找回这把钉锤，以及家族的剑、斧和匕首，法席恩旨在确保他曾经的主人们的记忆和骄傲从他们曾经统治的土地上彻底抹去。"}},faq={{q="阿加曼德家传钉锤在哪里？",a="这把钉锤存放在阿加曼德家族墓穴内的一个武器架上，该墓穴位于提瑞斯法林地阿加曼德磨坊的最北端。",al={"钉锤在哪里","阿加曼德钉锤位置","寻找阿加曼德钉锤"}},{q="谁想要阿加曼德家传钉锤？",a="居住在布瑞尔的被遗忘者库勒曼·法席恩需要这把钉锤以及其他家族传家宝，以清算他与昔日主人们的旧账。",al={"谁需要这把钉锤","谁拿走了阿加曼德钉锤","库勒曼·法席恩传家宝"}},{q="库勒曼·法席恩为什么要偷走这些传家宝？",a="法席恩生前曾为阿加曼德家族效力，并将自己的死亡直接归咎于他们。从他们的墓穴中夺走珍贵的武器，是他抹除他们家族最后一点荣誉痕迹的方式。",al={"为什么要偷传家宝","库勒曼·法席恩动机","为什么要仇视阿加曼德家族"}},{q="阿加曼德家族发生了什么事？",a="阿加曼德家族曾统治着洛丹伦北部繁荣的阿加曼德磨坊，直到瘟疫降临。现在，他们复活的尸体作为天灾军团的无脑奴仆，游荡在庄园和墓穴之中。",al={"阿加曼德家族是什么人","阿加曼德家族发生了什么","阿加曼德背景知识"}}},fx={["0ef93592"]={q="什么是阿加曼德家传钉锤？",a="阿加曼德家传钉锤是提瑞斯法林地曾经繁荣一时的阿加曼德家族的祖传遗物。这件武器与家族的其他武装宝藏一同存放在家族墓穴中，代表了该家族在被天灾军团毁灭之前，其曾经的地位与荣耀所留下的最后痕迹。",al={"阿加曼德钉锤","什么是阿加曼德家传钉锤","阿加曼德传家钉锤"}}},fp="19,284,16.528.0,21.453.1,41.137.0,34.153.0,52.186.0,36.205.0"}
P.entries["item:agamand-family-sword"] = {n="阿加曼德家传长剑",s="阿加曼德家传长剑是一把放置在提瑞斯法林地北部的阿加曼德家族墓穴中的蒙尘祖传利刃。它曾是这个富有磨坊主王朝引以为傲的象征，如今却被被遗忘者库勒曼·法席恩所追寻，旨在抹去他昔日主人们留下的最后痕迹。",h="阿加曼德家传长剑是一把放置在提瑞斯法林地北部的阿加曼德家族墓穴中的蒙尘祖传利刃。它曾是这个富有磨坊主王朝引以为傲的象征，如今却被被遗忘者库勒曼·法席恩所追寻，旨在抹去他昔日主人们留下的最后痕迹。",kw={"阿加曼德","墓穴","farthing","传家宝","磨坊","天灾军团","长剑","提瑞斯法"},ang={["class:Warrior"]="尽管这把利刃曾是洛丹伦贵族阶层的光辉象征，但如今它却被遗弃在一座被亵渎的坟墓中，成为了一件诉说着破碎武勋的遗物。",["race:Undead"]="对于被遗忘者来说，从提瑞斯法的昔日贵族那里收回遗物，意味着要与那段未能保护他们的过去进行清算。"},sec={{t="墓穴中的遗产",b="在第三次战争之前，阿加曼德王朝在提瑞斯法林地北部的连绵磨坊中拥有巨大的财富和影响力。当亡灵天灾席卷洛丹伦时，这个家族遭遇了惨烈的结局，他们的尸体被复活，成为了巫妖王麾下毫无思想的奴仆。他们的祖传武器，包括那把礼仪用的家传长剑，都被封存在磨坊北侧边缘的阿加曼德家族墓穴中。从墓穴架上夺走这些利刃，不仅仅是搜刮战利品，更是一种为了彻底摧毁这个陨落家族残存的记忆与贵族地位的蓄意之举。"},{t="跨越坟墓的复仇",b="这把剑是定居在布瑞尔的被遗忘者库勒曼·法席恩垂涎之物，他生前曾为阿加曼德家族工作。法席恩对他昔日的主人怀恨在心，将自己的死亡归咎于他们。通过派遣冒险者去取回这把剑以及该家族的祖传斧头、匕首和锤子，法席恩试图剥夺那些行尸走肉般的阿加曼德成员最后的一丝荣誉，确保他们家族的尊严被彻底抹除。"}},faq={{q="什么是阿加曼德家传长剑？",a="这是属于阿加曼德家族的一件祖传武器。在洛丹伦沦陷之前，这个显赫的贵族家庭曾在提瑞斯法林地北部经营着庞大的谷物磨坊。",al={"阿加曼德家传长剑背景故事","什么是阿加曼德家传长剑"}},{q="这把剑位于何处？",a="这把剑安放在阿加曼德家族墓穴内的一个武器架上，墓穴位于提瑞斯法林地阿加曼德磨坊的北缘，由天灾军团的奴仆和阿加曼德血脉的复活者守卫。",al={"阿加曼德家传长剑在哪里","阿加曼德长剑位置"}},{q="库勒曼·法席恩为什么要这把剑？",a="库勒曼·法席恩生前受雇于阿加曼德家族，并将自己的英年早逝归咎于他们。他寻找这些家族传家宝武器，是为了剥夺他们残存的荣誉，并抹去关于这个王朝的记忆。",al={"谁想要这把长剑","法席恩为什么想要传家宝"}},{q="阿加曼德家族发生了什么事？",a="阿加曼德家族在亡灵天灾入侵洛丹伦期间惨遭屠杀。与拥有自由意志的被遗忘者不同，家族中已故的成员仍被困在巫妖王的无脑奴役之下，徘徊在他们祖传的庄园和墓穴中。",al={"阿加曼德家族是谁","阿加曼德磨坊的故事"}}},fp="20,282,20.584.0,31.435.1,33.175.0,27.203.0,42.213.0,36.230.0"}
P.entries["item:ahanu-s-leather-goods"] = {n="安哈努的皮货",s="“安哈努的皮货”是一批在雷霆崖台地上制作完成的皮革护甲和补给品。这些货物由制皮师安哈努准备，目的地是贫瘠之地的十字路口，旨在为四处游荡的猎人和冒险者提供补给。",h="“安哈努的皮货”是一批在雷霆崖台地上制作完成的皮革护甲和补给品。这些货物由制皮师安哈努准备，目的地是贫瘠之地的十字路口，旨在为四处游荡的猎人和冒险者提供补给。",kw={"安哈努","十字路口","迪弗拉克","加翰·鹰翼","皮革制品","塔尔","雷霆崖","双足飞龙"},ang={["race:Tauren"]="这次运送展示了连接莫高雷祖地与贫瘠之地更广阔的部落领土之间日益发展的贸易网络。"},sec={{t="台地间的贸易",b="部落的补给线依赖于既定据点与边境哨所之间务实的贸易往来。在雷霆崖，工匠安哈努将生皮加工成成品服装和装备，并专门为莫高雷之外的贸易准备了这批货物。这捆货物的主人是加翰·鹰翼，一位在贫瘠之地中心地带十字路口经营的商人。由于穿过平原的陆路旅行十分缓慢，运送这批货物让信使们接触到了牛头人维护的空中快递网络，依靠塔尔和迪弗拉克训练的双足飞龙将货物迅速运往远方。"}},faq={{q="“安哈努的皮货”里有什么？",a="包裹里装的是安哈努在雷霆崖用生皮制作的皮革成品。它们是实用的护甲和装备，可以直接出售给旅行者。",al={"皮革制品是什么","安哈努的包裹内容","捆绑包里有什么"}},{q="谁会收到这个包裹？",a="这个包裹会被送到十字路口的加翰·鹰翼手中。他会将这些成品卖给往来于贫瘠之地中部的猎人、战士和冒险者。",al={"谁收到了皮革制品","它去哪里","加翰的皮革运送"}},{q="为什么这个包裹要用双足飞龙运送？",a="步行携带沉重的贸易品下电梯并穿越贫瘠之地需要很长时间。安哈努指引信使前往雷霆崖的双足飞龙管理员塔尔那里，演示了有翼信使如何能迅速地将货物运送到像十字路口这样遥远的哨所。",al={"为什么要空运包裹","雷霆崖双足飞龙运送","飞行管理员包裹"}}},fx={["32785653"]={q="什么是安哈努的皮货？",a="这是一捆在雷霆崖制作的成品皮货。这批货物将被运往贫瘠之地的十字路口定居点，旨在供应那里日益增多的聚集的旅行者。",al={"什么是安哈努的皮货","安哈努的皮货物品"}},["962e36b1"]={q="安哈努的皮货来自何处，又是谁制作的？",a="这些货物由安哈努准备，他是一位在雷霆崖高耸的平顶山上从事皮匠工艺的制皮师。他利用从贫瘠之地送来的生皮制作了这些成品。",al={"谁制作了安哈努的皮货","安哈努的皮货来源"}},["6d92aaf6"]={q="为什么会有人需要安哈努的皮货？",a="加翰·鹰翼订购了这批货物，以便卖给途经贫瘠之地的顾客。十字路口已经变成了一个充斥着漫游猎人和冒险者的繁忙枢纽，对优质、新鲜制作的皮革装备产生了热烈的需求。",al={"为什么运送安哈努的皮货","谁需要安哈努的皮货"}}},fp="21,262,22.627.0,37.172.0,25.174.0,41.251.0"}
P.entries["item:alaric-s-remains"] = {n="奥拉瑞克的遗骸",s="奥拉瑞克的遗骸是曾被埋在银松森林一处浅坟中的某人的遗骨。他萦绕不去的灵魂恳求过路的旅人将他残存的遗骸带出腐皮豺狼人的领地，送入芬里斯城堡的塔楼。",h="奥拉瑞克的遗骸是曾被埋在银松森林一处浅坟中的某人的遗骨。他萦绕不去的灵魂恳求过路的旅人将他残存的遗骸带出腐皮豺狼人的领地，送入芬里斯城堡的塔楼。",kw={"奥拉瑞克","奥拉瑞克的遗骸","芬里斯城堡","腐皮豺狼人","浅坟","银松森林","隐蔽的壁龛","图勒·鸦爪"},ang={["class:Mage"]="奥拉瑞克所揭示的隐藏宝藏中包含着与图勒·鸦爪以及曾经在芬里斯城堡内学习和密谋的达拉然受训奥术师有关的遗物。",["race:Undead"]="被遗忘者旅人往往会对那些生前安息被打扰的灵魂产生同情，尽管奥拉瑞克追求的是和平的隐居，而非侍奉黑暗女王。"},sec={{t="最后的请求",b="这些遗骸从银松森林一处不起眼的浅坟中被挖掘出来，属于曾居住在芬里斯岛的奥拉瑞克。他的灵魂不愿在这露天的土坑中徘徊，而是渴望回到他生前珍视的地方。他请求挖掘出他遗骨的人留下他不合脚的靴子，将他的骸骨直接带入城堡，在远离潜伏在大陆上的拾荒者的地方寻找宁静的安息之所。"},{t="城堡中的壁龛",b="奥拉瑞克指引搬运者前往芬里斯城堡西南方的塔楼，穿过那些被侵扰的低地，进入一间安静的房间。在尘封的书架后藏着一个隐蔽的小隔间，里面存放着图勒·鸦爪和他的法师同僚们曾经视若珍宝的文物。为了换取这处避开贪婪的腐皮豺狼人、无人打扰的安息之地，奥拉瑞克将藏匿的饰品交给了将他遗骨送回家乡的人。"}},faq={{q="奥拉瑞克是谁？",a="奥拉瑞克在芬里斯城堡荒废前曾是这里的居民，他在城堡大厅中度过了他人生中最美好的时光。死后，他被匆忙草草地埋在了银松森林的一座浅坟中，直到他的灵魂指引一名过路人将他的遗骨带回家乡。",al={"奥拉瑞克是谁","奥拉瑞克背景故事","这个人是谁"}},{q="奥拉瑞克的遗骸应该被送到哪里？",a="他的遗骸应该被放置在位于芬里斯岛上的芬里斯城堡西南方塔楼内，尘封书架后的一个隐蔽壁龛里。",al={"我该把奥拉瑞克带到哪里","尘封书架位置","壁龛在哪里"}},{q="为什么奥拉瑞克想要把他的遗骸封在书架后面？",a="芬里斯城堡在他生前给了他极大的慰藉，他希望安息在石墙之内，而不是泥土沟壑中。将隐蔽的壁龛封死也能保护他的遗骸不被城堡中游荡的腐皮豺狼人吞食或亵渎。",al={"为什么是芬里斯城堡","为什么是壁龛","为什么要把遗体藏起来"}},{q="他为什么要说留下靴子？",a="在指引取回他在浅坟中的遗骨时，奥拉瑞克漫不经心地提到，他的靴子生前就不合脚，将它们留下只是无用的杂物。",al={"留下靴子","奥拉瑞克的靴子","靴子不合脚"}},{q="隐蔽的壁龛里除了安息之所还有什么？",a="这个秘密隔间里存放着一件曾经被图勒·鸦爪和他的前合伙人所珍视的物品，以及奥拉瑞克愿意赠予任何愿意将他遗骸送回安息之所的人的魔法财物。",al={"隐藏壁龛宝藏","书架后面有什么","图勒的物品"}}},fx={["7c652925"]={q="什么是奥拉瑞克的遗骸？",a="这是奥拉瑞克的骨骸和身体残余，他曾是芬里斯城堡的居民，死后被匆忙掩埋在银松森林。他徘徊的灵魂依然附着在骨头上保持着意识，敦促旅行者将他从泥土中挖掘出来，以便他能获得最终平静的安息之所。",al={"什么是奥拉瑞克的遗骸","奥拉瑞克的尸体","奥拉瑞克的遗骸物品"}},["6447c1c8"]={q="奥拉瑞克的遗骸来自哪里？",a="你从银松森林荒野中一个粗陋、浅显的坟墓里将它们挖掘出来，没包括他下葬时穿着的那双不合脚的靴子。奥拉瑞克死在远离他故居的荒野中，他那不得安息的遗骸被困在泥土中，直到被人挖掘出来。",al={"奥拉瑞克死在哪里","奥拉瑞克的浅坟","谁制造了奥拉瑞克的遗骸"}},["5f3dd52d"]={q="为什么奥拉瑞克希望找回他的遗骸？",a="奥拉瑞克在芬里斯城堡度过了他一生中最快乐的时光，在荒野中长眠让他无法安宁。他希望自己的遗骸能被带回城堡，安放在书架后面一个积满灰尘的隐蔽壁龛里，这样就可以避开在城堡领地上肆虐的烂皮豺狼人的搜刮。",al={"为什么要拿走奥拉瑞克的遗骸","为什么奥拉瑞克想移动他的遗体","为什么移动奥拉瑞克"}}},fp="16,237,15.426.0,22.424.1,15.280.0,42.146.0,55.256.0,41.171.0,57.194.0"}
P.entries["item:alien-egg"] = {n="异型卵",s="异型卵是一枚不同寻常且神秘的卵，人们在千针石林的峡谷中发现，当地的风蛇正守护着它。尽管外表陌生，但当地的风蛇却像对待自己的后代一样，拼命地保护着这枚卵。它的出现引起了驻扎在乱风岗的牛头人斥候们的好奇与担忧。",h="异型卵是一枚不同寻常且神秘的卵，人们在千针石林的峡谷中发现，当地的风蛇正守护着它。尽管外表陌生，但当地的风蛇却像对待自己的后代一样，拼命地保护着这枚卵。它的出现引起了驻扎在乱风岗的牛头人斥候们的好奇与担忧。",kw={"异型卵","乱风岗","哈加尔·雷蹄","千针石林","风蛇"},ang={["class:Hunter"]="风蛇是卡利姆多贫瘠之地上最受尊崇的野兽之一，追踪它们最稀有且守卫最严密的卵，是对狩猎直觉的全面考验。",["race:Tauren"]="乱风岗的牛头人时刻警惕着下方的峡谷，他们将未知生物的出现视为某种征兆，或是对其摇摇欲坠的悬崖定居点的直接威胁。"},sec={{t="蛇类之卵",b="异型卵被发现静置在乱风岗南面和东北面高耸岩柱的底部，它与峡谷地带常见的动物群落格格不入。当地的风蛇并没有遗弃或摧毁这枚奇怪的卵，反而将其与自己的巢穴一并严加看守。身为乱风岗瞭望哨的一名牛头人勇士，哈加尔·雷蹄试图取回样本，以判断它究竟是对台地聚居地构成了威胁，还是仅仅是当地爬行动物的一种罕见变种。"},{t="阿里克拉的后代",b="当被带回乱风岗并接受近距离检查时，这层神秘的外壳立刻破裂了。它里面装的并不是什么外星入侵者：从里面孵化出的是牛头人传说中的红色风蛇——阿里克拉，人们认为它是复仇之灵。这条幼蛇迅速飞走，惊魂未定的哈加尔宣称复仇本身已经降临千针石林，这一事件引发了一连串后续，促使当地的守卫们前去面对它。"}},faq={{q="为什么这枚卵被称为“异型（alien）”？",a="“异型”一词是基于传统的含义，即对当地牛头人斥候来说完全陌生和不熟悉，并非暗示它来自外太空。它的颜色和斑纹与千针石林中普通的风蛇卵完全不同。",al={"异型卵名称","为何叫异型","是否来自太空"}},{q="在哪里可以找到异型卵？",a="这枚卵位于千针石林中，在乱风岗南面和东北面的台地墙壁底部。它总是被敌对的风蛇所包围和守护。",al={"卵的位置","异型卵在哪里","寻找异型卵"}},{q="为什么当地的风蛇要守护这枚卵？",a="没有人确切知道原因。风蛇们像守护自己的孩子一样守护着这枚卵，而那些报告发现它的人甚至无法靠近到足以对其进行检查的地步。",al={"为何风蛇保护它","风蛇守卫卵"}},{q="当你把卵带给哈加尔·雷蹄时会发生什么？",a="在将卵送到乱风岗的哈加尔·雷蹄手中后，卵在他眼前孵化了。飞出来的东西让哈加尔大受震撼，他立即派人去寻求莫特加·火鬃的建议。",al={"哈加尔交任务","孵化出什么"}}},fx={["9259de71"]={q="什么是异型卵？",a="异型卵是人们在千针石林的野生风蛇群中发现的一窝不同寻常、神秘的卵。与该地区典型的蛇卵不同，它奇怪的外观引起了乱风岗的斥候和萨满的注意。尽管它来历不明，当地的风蛇却像保护自己的后代一样激烈地守护着它。",al={"什么是异型卵","异型卵信息","关于异型卵"}},e10e9f00={q="为什么哈加尔·雷蹄想要这枚异型卵？",a="乱风岗的哈加尔·雷蹄听说了关于一枚被当地风蛇守护的怪卵的传闻，他的斥候无法靠近进行研究。出于好奇和警惕，他请求勇敢的冒险者找回这枚蛋，以便他能亲自检查并弄清楚从中孵化出来的会是什么生物。",al={"为什么要找异型卵","为什么哈加尔想要那枚蛋","异型卵的用途"}}},fp="9,333,17.548.0,20.462.1,30.274.0,33.201.0,40.167.1,59.188.1"}
P.entries["item:alterac-granite"] = {n="奥特兰克花岗岩",s="奥特兰克花岗岩是一种珍贵的耐用石材，开采自洛丹伦北部的山区，具体位于希尔斯布莱德丘陵的达隆山一带。由于其卓越的韧性和纹理，这种石材深受石匠大师的推崇，并被国王麦格尼·铜须的皇家石匠选中，用于为阵亡士兵雕刻一座永恒的纪念碑。",h="奥特兰克花岗岩是一种珍贵的耐用石材，开采自洛丹伦北部的山区，具体位于希尔斯布莱德丘陵的达隆山一带。由于其卓越的韧性和纹理，这种石材深受石匠大师的推崇，并被国王麦格尼·铜须的皇家石匠选中，用于为阵亡士兵雕刻一座永恒的纪念碑...",kw={"奥特兰克花岗岩","达隆山","希尔斯布莱德","铁炉堡","玛布勒斯坦","萨利·巴洛","萨多尔大桥"},ang={["profession:Mining"]="矿工和勘探者看重奥特兰克花岗岩，因为它的断口整齐且密度极高，这使其区别于普通的岩石。",["race:Dwarf"]="矮人石匠将材料质量置于一切之上，使得这种坚固的山地石材成为缅怀铁炉堡之子的必备之选。"},sec={{t="纪念之石",b="当国王麦格尼·铜须下令建造一座纪念碑来缅怀萨利·巴洛——一位在萨多尔大桥惨剧中牺牲的勇敢矮人卫士——时，普通的采石场石料显然不够格。负责在铁炉堡雕刻这座纪念碑的大石匠玛布勒斯坦坚持要获得奥特兰克花岗岩。作为东部王国公认的最优质石材之一，其传奇般的耐用性确保了阵亡英雄的形象和记忆能够历久弥新，永世长存。"},{t="险境开采",b="采集奥特兰克花岗岩绝非易事。这种石材位于希尔斯布莱德丘陵北部的达隆山附近，毗邻被毁的奥特兰克领地。该地区充斥着充满敌意的野生生物、潜伏的辛迪加暴徒以及挥之不去的战乱，想要获取这种原始石材的无瑕板岩，就需要勇敢的冒险者深入争议领土，为铁炉堡的工匠们寻得石料。"}},faq={{q="奥特兰克花岗岩有什么用途？",a="奥特兰克花岗岩受铁炉堡的大石匠玛布勒斯坦委托，用于雕刻一座皇家纪念碑，以纪念在萨多尔大桥防守战中牺牲的矮人战士萨利·巴洛。",al={"奥特兰克花岗岩用途","为什么选择奥特兰克花岗岩","玛布勒斯坦石材"}},{q="奥特兰克花岗岩在哪里可以找到？",a="它采集于希尔斯布莱德丘陵北部，奥特兰克边界附近的达隆山的矿点。",al={"奥特兰克花岗岩位置","哪里获得奥特兰克花岗岩","达隆山花岗岩"}},{q="为什么大石匠玛布勒斯坦特别需要这种石材？",a="大石匠玛布勒斯坦认为奥特兰克花岗岩是现存最优质、最坚韧的雕刻石材之一，认为它是国王麦格尼下令建造的永久性皇家纪念碑唯一相称的材料。",al={"为什么玛布勒斯坦需要花岗岩","为什么选择奥特兰克石材"}},{q="萨利·巴洛是谁？",a="萨利·巴洛是一位在萨多尔大桥战斗中阵亡的矮人战士。国王麦格尼·铜须下令建造了一座纪念碑，以缅怀他为联盟所作的牺牲。",al={"萨利·巴洛","谁在萨多尔大桥牺牲"}}},fx={["9814170d"]={q="什么是奥特兰克花岗岩？",a="奥特兰克花岗岩是一种在北方丘陵发现的珍贵优质采石。它在石匠大师中享有盛誉，被认为是现存最好的雕刻石料之一，拥有打造值得皇家委托的史诗般、永恒纪念碑所需的耐久性和完美的纹理。",al={"什么是奥特兰克花岗岩","奥特兰克花岗岩物品","奥特兰克花岗岩信息"}},["842d3593"]={q="奥特兰克花岗岩来自何处，又是谁制作的？",a="奥特兰克花岗岩是从邻近奥特兰克崎岖山脉的希尔斯布莱德丘陵地区的达隆山开采出来的天然石料。它并非由工匠制造，而是直接从丘陵的古老岩石中开凿出来的，等待着熟练的石匠将其塑造成不朽的作品。",al={"奥特兰克花岗岩来源","奥特兰克花岗岩在哪里开采","谁制造了奥特兰克花岗岩"}}},fp="15,339,18.494.0,17.442.0,33.174.0,35.134.0,60.203.0,21.191.0"}
P.entries["item:altered-snapjaw-shell"] = {n="变异的钳嘴龟壳",s="变异的钳嘴龟壳是居住在贫瘠之地葱郁绿洲中的淡水龟的甲壳。研究该地区的德鲁伊通过检查这些变异的甲壳，以了解奇异的地下裂隙是如何扭曲当地野生动物的。",h="变异的钳嘴龟壳是居住在贫瘠之地葱郁绿洲中的淡水龟的甲壳。研究该地区的德鲁伊通过检查这些变异的甲壳，以了解奇异的地下裂隙是如何扭曲当地野生动物的。",kw={"变异生物","变异的钳嘴龟壳","贫瘠之地","甜水绿洲","绿洲钳嘴龟","死水绿洲","图加·符文图腾"},ang={["class:Druid"]="对于德鲁伊来说，研究绿洲野兽扭曲的甲壳是识别扰乱贫瘠之地水域的隐藏失衡的重要一步。"},sec={{t="腐蚀的迹象",b="栖息在甜水绿洲和死水绿洲中的淡水龟发生了明显的、非自然的改变。人们认为它们饮用了被神秘地下裂隙供水的泉水，这些绿洲钳嘴龟表现出变异的甲壳，引起了十字路口研究人员的兴趣。图加·符文图腾，一位试图预测土地健康的牛头人德鲁伊，正在收集这些甲壳，以确定从深层大地涌出的能量是一种非自然的枯萎，还是某种更奇怪的东西。"}},faq={{q="是什么导致这些龟壳变异的？",a="这些钳嘴龟栖息在甜水绿洲和死水绿洲的泉水中，这些泉水由深层的地下裂隙供水。冒入绿洲水域的奇异能量改变了饮用这些水的生物的生理构造，导致了可见的甲壳扭曲。",al={"为什么甲壳会变异","什么是变异的钳嘴龟壳","钳嘴龟壳变异"}},{q="谁需要这些甲壳，为什么？",a="驻扎在十字路口的德鲁伊图加·符文图腾请求猎人们收集这些甲壳。他认为，检查原生野兽的生理变化是诊断什么样的力量或腐蚀正在影响贫瘠之地水源的关键。",al={"谁需要变异的钳嘴龟壳","图加·符文图腾的甲壳","变异生物任务上交"}},{q="这些钳嘴龟在哪里可以找到？",a="绿洲钳嘴龟栖息在位于十字路口南部和东南部的甜水绿洲和死水绿洲的水域和泥泞岸边。",al={"绿洲钳嘴龟位置","去哪里获取变异的甲壳","钳嘴龟壳位置"}}},fx={["1549c45f"]={q="变异的钳嘴龟壳来自哪里？",a="这些龟壳属于栖息在贫瘠之地淡水泉周围的绿洲钳嘴龟，特别是滋水绿洲和死水绿洲。与普通的龟壳不同，它们之所以呈现出奇异的状态，是因为饮用了被绿洲下方神秘裂隙污染或赋予力量的水，从而导致生活在那里的生物发生了物理变异。",al={"变异的钳嘴龟壳来自哪里","变异的钳嘴龟壳来源","谁制造了变异的钳嘴龟壳"}}},fp="21,241,19.495.0,39.279.0,31.238.0,31.150.0"}
P.entries["item:ambercorn"] = {n="琥珀颗粒",s="琥珀谷物是一种神圣的坚果，从散布在莫高雷各处的参天古树上落下。它蕴含着自然的魔力，是牛头人萨满祭司酿造药剂的重要试剂，最常用于在年轻人的试炼中引导灵视。",h="琥珀谷物是一种神圣的坚果，从散布在莫高雷各处的参天古树上落下。它蕴含着自然的魔力，是牛头人萨满祭司酿造药剂的重要试剂，最常用于在年轻人的试炼中引导灵视。",kw={"琥珀谷物","血蹄村","莫高雷","幻象试炼","牛头人试炼","先知之水","扎尔曼·双月"},ang={["class:Shaman"]="萨满传统尊崇琥珀谷物这类天然催化剂，认为大地母亲将精神魔法植入了她树木和土壤的自然产物中。",["race:Tauren"]="每一个正在经历传统大地母亲试炼的年轻牛头人，都会学习将琥珀谷物视为揭示其精神道路的幻象任务的必备材料。"},sec={{t="树冠的馈赠",b="从莫高雷大树那粗壮的枝桠下采集而来，对于牛头人来说，琥珀谷物不仅仅是普通的坚果。它富含这片土地的精神活力，蕴藏着牛头人秘法师世代领悟并利用的潜藏魔法。年轻的猎人和漫游者很早就学会了留意树冠下的草丛，尊崇大地母亲从上方自由赐予的礼物。"},{t="先知药水",b="在血蹄村，先知扎尔曼·双月在为年轻的牛头人准备幻象试炼时，需要依赖琥珀谷物。将琥珀谷物与从平原纯净水井中收集的石头混合，浸泡后即可制成强效的先知之水。在祖先之火前饮用这种仪式灵药，可以使试炼者的感官发生转变，从而揭示指引他们前往下一目的地的灵兽。"}},faq={{q="什么是琥珀谷物？",a="琥珀谷物是一种从莫高雷巨大的古树上落下的种荚或坚果。它带有与这片土地的精神相契合的先天自然魔法。",al={"琥珀谷物","琥珀谷物是什么"}},{q="在哪里可以找到琥珀谷物？",a="它们散布在莫高雷草原上那些参天大树的树冠下的地面上，特别是在血蹄村周围的区域。",al={"琥珀谷物位置","哪里寻找琥珀谷物","如何获得琥珀谷物"}},{q="琥珀谷物有什么用途？",a="牛头人先知将琥珀谷物与井石混合，酿造出先知之水。这是一种在幻象试炼期间饮用的仪式性液体，用于揭示精神向导。",al={"琥珀谷物用途","琥珀谷物作用"}},{q="血蹄村里谁需要琥珀谷物？",a="扎尔曼·双月是居住在血蹄村的一位受人尊敬的先知，他会将收集琥珀谷物的任务交给试炼者，作为证明其与大地母亲联系的试炼的一部分。",al={"谁需要琥珀谷物","琥珀谷物任务发布者"}}},fx={af22a474={q="Ambercorn来自何处，又是谁制作的？",a="Ambercorn并非凡人所造；它是生长在莫高雷平原上的巨树所结出的天然坚果或松果。牛头人将这些种子视为神圣大地的恩赐，其中蕴含着直接交织在这片土地上的魔法元素。",al={"ambercorn来自哪里","ambercorn来源","谁制造了ambercorn","在哪里可以找到关于ambercorn的传说"}},c9693aa2={q="为什么有人需要Ambercorn？",a="像扎尔曼·双月这样的牛头人萨满寻找Ambercorn是因为它所蕴含的潜在魔法属性。当它与神圣的井石结合并酿制成强大的先知之水时，它能在部落篝火前诱发精神恍惚，从而使年轻的牛头人获得完成神圣幻象仪式所需的幻象。",al={"为什么要用到ambercorn","为什么要收集ambercorn","谁需要ambercorn","ambercorn的用途"}}},fp="9,241,19.422.0,15.425.0,21.150.0,29.181.0,27.162.0,44.185.0"}
P.entries["item:amethyst-phial"] = {n="紫水晶瓶",s="紫水晶瓶是一件精致的礼仪容器，由多兰纳尔的科瑞萨斯·月怒托付给年轻的暗夜精灵冒险者。它是专门为采集并保存The Oracle Tree下首屈一指的月井水而制作的。",h="紫水晶瓶是一件精致的礼仪容器，由多兰纳尔的科瑞萨斯·月怒托付给年轻的暗夜精灵冒险者。它是专门为采集并保存The Oracle Tree下首屈一指的月井水而制作的。",kw={"紫水晶瓶","科瑞萨斯·月怒","crown of the earth","多兰纳尔","月井","神谕林地","the oracle tree","泰达希尔"},ang={["class:Druid"]="德鲁伊们将该容器视为监测威胁世界之树生态系统的生命能量和蔓延腐蚀的关键工具。",["race:NightElf"]="对于卡多雷来说，装满这个瓶子是一项庄严的职责，直接面对泰达希尔在未受祝福的情况下被创造所带来的令人担忧的缺陷。"},sec={{t="神圣之水的容器",b="紫水晶瓶被托付给泰达希尔的初学者，它是Crown of the Earth朝圣之旅中使用的最后一个容器。科瑞萨斯·月怒指派旅行者携带它前往树枝西北部的深处，即神谕林地。在那里，在The Oracle Tree古老的树冠之下，坐落着岛上最初也是最强大的月井。人们将瓶子小心地浸入这些散发着光芒的水中，以汲取艾露恩恩典的精华，使德鲁伊和女祭司们能够研究并照料世界之树那难以预测的生长情况。"},{t="未受祝福之生长的重负",b="采集这些样本不仅仅是一种常规的虔诚仪式。泰达希尔是在大德鲁伊范达尔·鹿盔的指导下培育的，并没有得到守护巨龙的祝福，因为他们拒绝支持这种被他们认为是傲慢行为的举动。结果，树枝遭受了令人不安的腐蚀，而卡多雷依然保持着凡人之躯。装满紫水晶瓶既是一种精神仪式，也是一项持续的调查，让多兰纳尔的研究人员能够细致检查泰达希尔圣水的纯度。"}},faq={{q="紫水晶瓶有什么用？",a="这个瓶子是由科瑞萨斯·月怒交给冒险者的，用于从泰达希尔第一个也是最强大的月井中采集井水，该月井位于巨大的The Oracle Tree下方的神谕林地中。",al={"紫水晶瓶用途","如何使用紫水晶瓶","紫水晶瓶用法"}},{q="我该在哪里装满紫水晶瓶？",a="它必须被浸入多兰纳尔西北方深处，To Darnassus入口以北，那片被称为神谕林地的幽静树林中的月井里。",al={"在哪里装满紫水晶瓶","紫水晶瓶位置","神谕林地月井"}},{q="为什么神谕林地的水如此重要？",a="位于The Oracle Tree下的月井被认为是世界之树上建立的第一个也是最强大的水井。其井水深深浸润着艾露恩的精华，对于监测泰达希尔的精神和物理健康至关重要。",al={"为什么要神谕林地的水","the oracle tree月井的力量","神谕之井的意义"}},{q="是谁派你去使用这个瓶子的？",a="多兰纳尔的暗夜精灵德鲁伊科瑞萨斯·月怒提供了这个瓶子，作为旨在了解泰达希尔生长困境的仪式任务的一部分。",al={"谁提供紫水晶瓶","科瑞萨斯·月怒的瓶子","谁需要紫水晶瓶"}}},fx={f821d918={q="什么是紫水晶瓶？",a="紫水晶瓶是泰达希尔给予旅行者的一种空仪式容器。它专为盛装纯净的附魔液体而打造，其用途是从古老的神谕之树下的月亮井中汲取并保存井水。",al={"紫水晶瓶","这个瓶子是什么"}},af37ef60={q="为什么科瑞萨斯·月怒想要装满紫水晶瓶？",a="科瑞萨斯·月怒寻求神谕林地中优质月亮井的水，以研究泰达希尔的奇怪状态。由于这棵伟大的世界之树缺乏巨龙军团的祝福，其生长过程依然存在缺陷且不可预测，这促使德鲁伊们对其最神圣的水域进行审视。",al={"为什么要装满紫水晶瓶","为什么科瑞萨斯想要这个瓶子","紫水晶瓶的用途"}}},fp="14,241,23.550.0,28.517.1,36.187.0,35.158.0,52.258.0,32.174.0"}
P.entries["item:an-undelivered-letter"] = {n="一封未寄出的信",s="《一封未寄出的信》是一件被遗忘在闪金镇Lion's Pride Inn里的旧邮件。它由神秘的Stalvan Mistmantle在多年前写下，是揭开他过去那段黑暗往事的关键线索。",h="《一封未寄出的信》是一件被遗忘在闪金镇Lion's Pride Inn里的旧邮件。它由神秘的Stalvan Mistmantle在多年前写下，是揭开他过去那段黑暗往事的关键线索。",kw={"运河区","信使","弗索姆","闪金镇","lion's pride inn","送信人","mistmantle","stalvan"},ang={["faction:Alliance"]="追寻这位送信人被遗忘的足迹，将引导调查员从田园诗般的闪金镇中心进入暴风城的上流住宅区。"},sec={{t="午夜逃亡",b="多年前，一场暴风雨迫使一名旅行送信人进入Lion's Pride Inn寻求避雨休息。午夜时分，这名惊恐的送信人穿着睡衣冲下楼梯，消失在倾盆大雨中，再也没有回来。他在二楼丢下了一个装满行李的箱子，其中就包括一封Stalvan Mistmantle写给暴风城运河区某处庄园的信。"},{t="追寻学者",b="这封未拆封的信一直静静地躺在旅店的客房里，直到现代的调查员开始在艾尔文森林中追寻Stalvan的足迹。将这份遗失已久的信件送到首都管理员弗索姆手中，便将这个谜团从旅店静谧的大厅直接引向了暴风城的核心。"}},faq={{q="哪里可以找到这封未寄出的信？",a="它放在闪金镇Lion's Pride Inn二楼的一个储物箱里，就在其中一间客房床脚处。",al={"哪里有信","储物箱位置","lion's pride inn箱子"}},{q="为什么这封信没能寄出？",a="携带信件的送信人在Lion's Pride Inn躲避暴风雨。午夜时分，他突然惊慌失措，穿着睡衣冲下楼梯，跑进风雨中，丢下了他的箱子和里面的东西。",al={"为什么未寄出","信使发生了什么","信使逃跑"}},{q="谁写了这封信？",a="这封信是由Stalvan Mistmantle寄出的，他在那个受惊的送信人留宿旅店的同一时期，也曾在旅店住过几晚。",al={"谁寄的信","stalvan作者","发件人"}},{q="这封信原本应该寄往哪里？",a="信的地址是暴风城的运河区，可以把它交给公园附近的管理员弗索姆。",al={"谁接收信件","暴风城目的地","运河区信件"}}},fx={["72dbe9c7"]={q="什么是“一封未寄出的信”？",a="这是一封多年前由斯塔文·密斯曼德亲笔写下的被遗忘的信件。一名携带此信的信使在一个暴风雨之夜在闪金镇的Lion's Pride Inn避雨，却在午夜时分因极度恐惧而逃入黑暗之中。这封信被遗留在信使的储物箱里，至今仍处于密封未读状态，其中隐藏着斯塔文过去的线索。",al={"什么是“一封未寄出的信”","“一封未寄出的信”物品","斯塔文的信"}},e9e7c880={q="为什么需要“一封未寄出的信”？",a="你需要它来揭开斯塔文·密斯曼德那段黑暗的历史。随着他在暮色森林和艾尔文森林的踪迹变得模糊，这封被遗忘的信件——收件人是暴风城运河区的一位居民——成为了拼凑他究竟是谁以及他结局如何的关键线索。",al={"为什么我需要这封未寄出的信","谁想要这封未寄出的信","“一封未寄出的信”的用途"}}},fp="21,222,17.401.0,19.307.1,38.150.0,35.223.0,22.140.0,35.115.0"}
P.entries["item:anaya-s-pendant"] = {n="安娜雅的坠饰",s="安娜雅的坠饰是安娜雅·Dawnrunner那不安的幽灵在亚米萨兰废墟中携带的遗物。对于她的爱人塞瑞利恩·白爪来说，这件饰品是一份悲剧性的纪念物，他在大裂变中幸存下来，却发现她的灵魂在几千年后依然饱受折磨。",h="安娜雅的坠饰是安娜雅·Dawnrunner那不安的幽灵在亚米萨兰废墟中携带的遗物。对于她的爱人塞瑞利恩·白爪来说，这件饰品是一份悲剧性的纪念物，他在大裂变中幸存下来，却发现她的灵魂在几千年后依然饱受折磨。",kw={"亚米萨兰","安娜雅·dawnrunner","奥伯丁","塞瑞利恩·白爪","黑海岸","为了永恒的爱","坠饰","永恒之井"},ang={["class:Druid"]="像许多追随珊多·怒风进入翡翠梦境的德鲁伊一样，塞瑞利恩沉睡了数千年，希望能逃避悲伤，却在苏醒后的世界里再次面对徘徊不去的幽灵。",["race:NightElf"]="这枚坠饰令人心酸地提醒着人们上古之战所留下的持久创伤，在那场大裂变中，无数的生命和恋情被无情撕碎。"},sec={{t="跨越千年的纪念",b="一万年前，在永恒之井那场灾难性的毁灭中，古老的卡多雷城市亚米萨兰沦为废墟。塞瑞利恩·白爪以为他心爱的安娜雅已经丧生，便带着深重的悲痛，与珊多·玛法里奥·怒风一同进入了长眠。当他最终苏醒并徘徊于黑海岸时，却发现安娜雅那受尽折磨的幻影依然在亚米萨兰飘荡，并随身携带着这枚坠饰。由于不忍亲自对她痛下杀手，塞瑞利恩请求路过的旅者解脱她的灵魂，并取回这件传家宝。"},{t="离别与安息",b="将坠饰交还给奥伯丁的塞瑞利恩，可以让安娜雅·Dawnrunner那徘徊不去的灵魂在最后一次在他面前短暂现身。她从束缚自己于亚米萨兰闹鬼废墟的痛苦中解脱出来，幽灵平静地消散在夜色中，只留下塞瑞利恩独自守着坠饰，以及他对那段古老恋情的永恒记忆。"}},faq={{q="安娜雅的坠饰从何而来？",a="这枚坠饰是从安娜雅·Dawnrunner的幽灵身上获得的，她徘徊在黑海岸南部的亚米萨兰古老卡多雷废墟中。",al={"安娜雅的坠饰在哪里获得","我该如何获得安娜雅的坠饰","安娜雅的坠饰由谁掉落"}},{q="谁需要安娜雅的坠饰？",a="它属于塞瑞利恩·白爪，一位居住在黑海岸沿海城镇奥伯丁的悲伤暗夜精灵。",al={"我该把安娜雅的坠饰交给谁","塞瑞利恩·白爪任务","提交安娜雅的坠饰"}},{q="为什么塞瑞利恩不能亲自取回坠饰？",a="塞瑞利恩在亚米萨兰的废墟中发现了失落爱人的灵魂，但即使经历了万年的悲伤，他仍无法忍受亲手向她动武的碎心之痛。",al={"为什么塞瑞利恩不杀安娜雅","为什么塞瑞利恩需要帮助"}},{q="将坠饰交还给塞瑞利恩会发生什么？",a="当坠饰被带回奥伯丁交给塞瑞利恩时，安娜雅的灵魂会短暂地在他面前现身告别，随后平静地消散，让塞瑞利恩终于能够为纪念她而哀悼。",al={"安娜雅的结局是什么","塞瑞利恩的反应"}}},fx={["2379a09f"]={q="安娜雅的坠饰是什么？",a="安娜雅的坠饰是一件古老的纪念品，属于一位名叫安娜雅·黎行者的卡多雷。她在数千年前亚米萨兰毁灭时丧生。她的灵魂在废墟中徘徊，坠饰是她与塞瑞利恩·白爪在天崩地裂撕裂他们的世界之前那段美好往昔与永恒之爱的真切见证。",al={"安娜雅的坠饰是什么","安娜雅的坠饰背景故事","坠饰属于谁"}}},fp="15,273,27.579.0,17.343.1,37.136.0,26.111.0,52.191.0,54.193.1"}
P.entries["item:ancient-moonstone-seal"] = {n="远古月亮石封印",s="远古月亮石封印是一件强大的上层精灵魔法圣物，在大分裂发生前很久就已经锻造而成。它被灌注了强效的奥术束缚魔法，作为锚点将阿斯特利安的灵魂囚禁在巴莎兰的废墟之中。",h="远古月亮石封印是一件强大的上层精灵魔法圣物，在大分裂发生前很久就已经锻造而成。它被灌注了强效的奥术束缚魔法，作为锚点将阿斯特利安的灵魂囚禁在巴莎兰的废墟之中。",kw={"亚米萨兰","远古月亮石封印","阿斯特利安","阿斯瑞克斯","巴莎兰","黑海岸","戴斯瑞尔","上层精灵","月亮石"},ang={["class:Mage"]="这块月亮石展现了古老精灵防护魔法的持久力量，使其束缚场在超过一万年的时间里从未中断。",["race:NightElf"]="这枚封印是上层精灵在大分裂之前肆无忌惮的奥术威能和残酷奴役行为的令人心悸的遗物。"},sec={{t="上层精灵的魔法牢笼",b="远古月亮石封印由阿斯特利安的前主人，强大的上层精灵法师阿斯瑞克斯·纳拉辛锻造，旨在作为一种不可摧毁的形而上学锚点。在永恒之井尚存且艾萨拉女王统治时期，阿斯瑞克斯利用这件神器将阿斯特利安的灵魂束缚在巴莎兰的支柱上。一万多年后，阿斯特利安依然是其魔法下的无形囚徒，无法用他所拥有的任何力量或法术打破结界。"},{t="亚米萨兰的毁灭",b="大分裂浩劫过后，这枚封印最终落入了占据黑海岸周边荒野的戴斯瑞尔萨特之爪中。由于普通力量无法破坏上层精灵的附魔之石，因此摧毁这件神器需要将其暴露在南部亚米萨兰双子废墟中经久不息的古老蓝焰之下。在这种奥术之火中焚毁封印将永久粉碎阿斯瑞克斯的束缚结界，最终使阿斯特利安的灵魂重获自由，回归凡世领域。"}},faq={{q="什么是远古月亮石封印？",a="这是一件由上层精灵法师阿斯瑞克斯·纳拉辛制作的古老魔法圣物。它是一把奥术钥匙，将阿斯特利安的鬼魂束缚在巴莎兰废墟中的神龛内。",al={"什么是月亮石封印","阿斯特利安的封印","巴莎兰封印"}},{q="在被回收之前，是谁拥有这枚封印？",a="这枚封印落入了居住在黑海岸巴莎兰周边废墟中的戴斯瑞尔萨特手中，他们利用这枚封印来指挥低等的格雷尔仆从。",al={"谁拥有封印","哪里能找到月亮石封印","谁掉落月亮石封印"}},{q="如何摧毁这枚封印？",a="普通的武器或当代魔法无法伤害这件圣物。必须将其投入到南部亚米萨兰双子废墟中至今仍燃烧着的古老永恒之火里。",al={"如何打破封印","摧毁月亮石封印","在哪里摧毁封印"}},{q="摧毁封印后会发生什么？",a="在亚米萨兰的火焰中焚毁封印可以打破束缚阿斯特利安的古老咒语，使他的灵魂在被囚禁数千年后获得游荡于世间的自由。",al={"打破封印有什么作用","阿斯特利安获释"}}},fx={bc236585={q="远古月亮石封印来自哪里，是谁制作的？",a="远古月亮石封印是在数千年前卡多雷帝国鼎盛时期，大分裂发生前制作的。它是由当时最强大的上层精灵领主之一——埃瑟里克斯·纳拉辛通过巫术锻造而成，用作一种神秘的束缚装置。",al={"谁制作了远古月亮石封印","远古月亮石封印起源","远古月亮石封印的创造者"}},a13d6402={q="为什么阿斯特利安想要远古月亮石封印？",a="阿斯特利安寻找这个封印，是因为它正是将他的灵魂禁锢在巴莎兰废墟神殿中的枷锁。只要封印保持完整，他就会被困在无形的牢笼之后，无法离开这座古老的监狱，也无法安息。通过取回封印，他希望能在亚米萨兰的远古烈焰中将其摧毁，从而最终获得自由。",al={"为什么阿斯特利安想要封印","为什么要寻找远古月亮石封印","谁想要远古月亮石封印"}}},fp="22,238,29.469.0,25.498.1,35.190.0,46.165.0,30.180.0,40.186.1"}
P.entries["item:ancient-statuette"] = {n="古代雕像",s="古代雕像是一件从灰谷西北部的佐拉姆海岸回收的沉没圣物。暗夜精灵塔尔伦一直在寻找它，这座小型雕像源自佐拉姆古城的淹没遗迹。",h="古代雕像是一件从灰谷西北部的佐拉姆海岸回收的沉没圣物。暗夜精灵塔尔伦一直在寻找它，这座小型雕像源自佐拉姆古城的淹没遗迹。",kw={"古代雕像","灰谷","娜迦","佐拉姆遗迹","雕像","塔尔伦","佐拉姆","佐拉姆海岸"},ang={["faction:Alliance"]="回收这件文物有助于塔尔伦记录和从灰谷海岸日益猖獗的娜迦手中夺回暗夜精灵的遗产。",["race:NightElf"]="这座雕像是大分裂之前古代卡多雷文明罕见的幸存碎片，在海底保存了数千年。"},sec={{t="浅滩中的圣物",b="灰谷西北部的海域隐藏着佐拉姆沉没的遗迹，这是一座在一万年前的大分裂中沉入波涛之下的暗夜精灵城市。近日，探险家塔尔伦乘坐一艘小船勘测了这些淹没的遗迹，试图寻找失落的历史遗物。当娜迦发起的凶猛袭击将他逼上岸时，塔尔伦在逃跑过程中丢弃了大部分随身物品，将他打捞上来的古代雕像遗落在了他那艘搁浅小船附近的潮间沙滩上。"},{t="佐拉姆的秘密",b="塔尔伦视这座雕像为他最珍贵的财产，也是他冒着生命危险探索这片怪物出没的海岸的唯一理由。他认为这尊雕像不仅仅是一件装饰性的石雕，更是解读被封锁在佐拉姆海岸波涛之下的建筑、历史和奥术秘密的关键。"}},faq={{q="什么是古代雕像？",a="这是一件从位于灰谷西北海岸外的暗夜精灵古城佐拉姆的沉没遗迹中打捞出来的文物。",al={"什么是雕像","古代雕像背景故事","这是什么物品"}},{q="谁在寻找这座雕像？",a="暗夜精灵学者塔尔伦正在寻找它。他当时正乘船在淹没的遗迹上空掠过，随后遭到娜迦伏击，被迫弃船逃命，并在逃亡途中将这件圣物遗落在了沙滩上。",al={"谁想要雕像","塔尔伦的雕像","谁弄丢了雕像"}},{q="为什么这座雕像很重要？",a="塔尔伦认为这座雕像掌握着佐拉姆古城的秘密，并可能成为解开埋藏在波涛之下遗迹中历史的关键。",al={"塔尔伦为什么想要它","雕像的用途"}},{q="为什么娜迦会在发现它的地方徘徊？",a="娜迦已经占领了佐拉姆海岸的沿海水域和遗迹，疯狂地攻击任何敢于接近其水下领地残骸的岸上居民。",al={"为什么沙滩上有娜迦","佐拉姆海岸的娜迦"}}},fp="17,226,23.470.0,16.340.0,30.140.0,33.180.0,31.165.0,48.178.0"}
P.entries["item:andron-s-ledger"] = {n="安德隆的账本",s="安德隆的账本是一份从幽暗城的安德隆·甘特手中获取的情报文件。死影卫队将其作为特工为被遗忘者收集信息初期工作的一部分。",h="安德隆的账本是一份从幽暗城的安德隆·甘特手中获取的情报文件。死影卫队将其作为特工为被遗忘者收集信息初期工作的一部分。",kw={"奥特兰克","安德隆·甘特","安德隆的账本","死影卫队","曼内特·卡卡德","rogues' quarter","辛迪加","瓦里玛萨斯"},ang={["class:Rogue"]="取回并解读安德隆的账本是你的试炼场，标志着你正式被曼内特·卡卡德引入死影卫队，并赢得了瓦里玛萨斯的个人认可。",["race:Undead"]="这份账本显示了被遗忘者为收集新领地周围威胁的情报所做的努力。"},sec={{t="揭露辛迪加",b="这份账本是从幽暗城安德隆·甘特的书架上取回的，其中包含的情报远远超出了死影卫队最初的预期。其内容揭示了辛迪加——奥特兰克陨落的人类贵族残党——正在该地区积极活动。在审阅了这些条目后，死影卫队成员曼内特·卡卡德立即意识到了这份文件的战略价值，认识到这些奥特兰克的没落贵族正在再次密谋。这份账本为被遗忘者的领导层提供了辛迪加行动的具体证据，将一次例行的差事变成了一次重大的情报政变。"},{t="恐惧魔王之事",b="由于该披露涉及被遗忘者领地所面临的区域性威胁，曼内特·卡卡德派遣携带者将账本直接送交皇家区的瓦里玛萨斯。作为希尔瓦娜斯·风行者的恐惧魔王大管家，瓦里玛萨斯通过死影卫队监督内部安全和间谍活动。这份账本赢得了瓦里玛萨斯的嘉奖，证明了死影卫队网络的能力，也证明了将其公之于众的特工的可靠性。"}},faq={{q="什么是安德隆的账本？",a="这是一本从幽暗城安德隆·甘特的书架上取回的记录簿，其中包含死影卫队所寻求的情报。",al={"安德隆的账本","这本书是什么","安德隆账本"}},{q="安德隆·甘特是谁？",a="安德隆·甘特是一名被遗忘者，在幽暗城的Apothecarium附近开了一家店。瓦里玛萨斯领主怀疑他暗中协助外部组织，因此死影卫队派出一名特工伪装成他预期的信使，以获取他的账本。",al={"安德隆是谁","安德隆·甘特"}},{q="为什么死影卫队想要这份账本？",a="曼内特·卡卡德想要审查安德隆的信息，以寻找对被遗忘者有用的情报。",al={"账本为何重要","死影卫队为何想要账本"}},{q="谁来接收这份账本？",a="它首先被带到盗贼区的曼内特·卡卡德那里，他评估了其内容，然后指示将其直接送到黑暗女王之厅的瓦里玛萨斯领主手中。",al={"谁接收安德隆的账本","我该把账本交给谁"}},{q="递交账本对盗贼意味着什么？",a="递交账本完成了特工加入死影卫队的初试，从而正式进入了被遗忘者隐秘的刺客公会。",al={"死影卫队入会","加入死影卫队"}}},fx={["83ea0415"]={q="安德隆的账本来自哪里？",a="账本属于幽暗城的线人安德隆·甘特，他详细记录了自己的秘密交易。在被死亡猎手派出的特工取回之前，它一直放在他住处的书架上。",al={"谁制作了安德隆的账本","安德隆的账本起源","账本来自哪里"}},["45ae6031"]={q="为什么死亡猎手要安德隆的账本？",a="梅内特·卡卡德和死亡猎手寻找这本账本，是为了获取有关威胁被遗忘者的情报。梅内特在将账本送给瓦里玛萨斯领主之前，会先查阅其中的内容。",al={"为什么安德隆的账本遭到搜寻","谁想要安德隆的账本","为什么梅内特·卡卡德想要账本"}}},fp="15,190,24.613.1,26.462.1,24.129.0,19.240.0,41.92.0,24.186.0,52.153.0"}
P.entries["item:another-clue-to-sanders-treasure"] = {n="Another Clue to Sanders' Treasure",s="“Another Clue to Sanders' Treasure”是一张饱经风霜的羊皮纸条，由臭名昭著的海盗桑德斯船长遗留。它是从一个旧木桶里找出来的，上面写着指引寻宝者前往西部荒野悬崖上一处孤立地标的诗句。",h="“Another Clue to Sanders' Treasure”是一张饱经风霜的羊皮纸条，由臭名昭著的海盗桑德斯船长遗留。它是从一个旧木桶里找出来的，上面写着指引寻宝者前往西部荒野悬崖上一处孤立地标的诗句。",kw={"悬崖","桑德斯船长","线索","羊皮纸","桑德斯的财宝","西部荒野","风车"},ang={["class:Rogue"]="对于任何觊觎隐藏财宝的人来说，解读晦涩的指引并搜寻遗忘在海边的藏宝点是标准的基本功。"},sec={{t="海岸悬崖上的线索",b="桑德斯船长从不将他偷来的财宝放在显眼的地方。他没有绘制一张会被人一举夺走的完整地图，而是将藏宝指引拆分成了连串的谜题和埋藏的标记。这张羊皮纸残片延续了这条线索，指示持有者从上一个藏宝处向北走，去寻找那个屹立在海边悬崖之上、孤零零的风车旁的一个废弃水罐。"}},faq={{q="这张线索上写着什么？",a="羊皮纸指示发现者从藏宝木桶处面向北方，直行直到在海边悬崖的一座孤风车旁发现一个空水罐。",al={"线索的内容","桑德斯的线索文本","线索上的方向指引"}},{q="桑德斯船长是谁？",a="桑德斯船长是一名海盗，他的事迹使他偷来的财宝散落在西部荒野的海岸和悬崖各处。他没有留下一张完整的地图，而是在该地区制造了一场藏有标记的寻宝游戏。",al={"桑德斯是谁","桑德斯船长的背景","西部荒野的海盗桑德斯"}},{q="这张线索接下来指向哪里？",a="沿着线索的指引向北，沿着海岸悬崖走到矗立在崖边的一座孤风车，那里有一个装有“The Next Step”的空水罐。",al={"接下来去哪里","桑德斯的风车线索","水罐在哪里"}}},fx={b0e51eff={q="\"Another Clue to Sanders' Treasure\"是什么？",a="这是一张手写的羊皮纸残片，是在西部荒野海岸的一个旧木桶里被发现的。纸上写着桑德斯船长留下的另一组航海方向，指引那些有胆量追寻他踪迹的人前往他留下的下一个隐藏宝藏。",al={"\"another clue to sanders' treasure\"是什么","桑德斯的线索羊皮纸","这张线索羊皮纸是什么"}},["37a7a825"]={q="这个线索来自哪里，是谁制作的？",a="该线索是由桑德斯船长书写并隐藏的，他是一位老水手，在西部荒野的海岸和乡村各地留下了一连串的线索。你从一个他很久以前藏匿它的废弃木桶中找回了这张羊皮纸残片。",al={"谁写了\"another clue to sanders' treasure\"","谁制作了桑德斯的线索","这条线索来自哪里"}},["632540c2"]={q="为什么有人会想要\"Another Clue to Sanders' Treasure\"？",a="沿着桑德斯的足迹是找到他埋藏的宝箱的唯一途径。每一条线索都以前一条为基础，提供了追踪这位船长在西部荒野各处行踪所需的准确地标，直至最终找到他藏匿的财宝。",al={"为什么要寻找桑德斯的线索","我为什么要桑德斯的宝藏线索","桑德斯的线索有什么用"}}},fp="33,92,29.299.0,29.143.0,24.163.0,31.145.0"}
P.entries["item:arikara-serpent-skin"] = {n="阿利卡拉蛇皮",s="阿利卡拉蛇皮是取自黑云峰顶神话中的风蛇阿利卡拉的鳞甲兽皮。将其带回白沙岗哨，作为这头寻求复仇的野兽已被召唤并击杀的有力证据。",h="阿利卡拉蛇皮是取自黑云峰顶神话中的风蛇阿利卡拉的鳞甲兽皮。将其带回白沙岗哨，作为这头寻求复仇的野兽已被召唤并击杀的有力证据。",kw={"阿利卡拉","凯恩·血蹄","黑云峰","火岩粉","莫特加·火鬃","蛇皮","白沙岗哨"},ang={["class:Shaman"]="利用附魔粉末在圣火上强迫先祖灵魂野兽实体化的仪式，展示了雷霆崖所施展的强大且具有操纵性的仪式技艺。",["race:Tauren"]="这张蛇皮代表了古老神话与当前领导层之间的冲突，玛加萨·野性图腾关于凯恩·血蹄的言论在各个部落中引发了不安。"},sec={{t="被召唤的愤怒之战利品",b="阿利卡拉是一头与古老的牛头人传说紧密相连的强大风蛇，据传它在文化变迁中寻求向凯恩·血蹄复仇。在玛加萨·野性图腾长老的指引下，勇士们使用附魔的火岩粉，在黑云峰的埋骨荒地顶端点燃神圣之火，迫使这头灵魂野兽显现于物质位面。剥下蛇皮即可获得阿利卡拉蛇皮——这头野兽死亡的明确遗物。"},{t="令人不安的启示",b="当这张皮被带到白沙岗哨交给莫特加·火鬃时，它证明了这条蛇的死亡，但也引发了令人不安的疑问。玛加萨·野性图腾坚称阿利卡拉是因为先祖的愤怒而专门追猎凯恩·血蹄，然而对被杀生物的检查让莫特加困惑不已：这样的一种灵魂为何会真正威胁到他们的大酋长。虽然这张兽皮消除了迫在眉睫的危险，但它却让人们对玛加萨的真实解读留下了挥之不去的怀疑。"}},faq={{q="什么是阿利卡拉蛇皮？",a="它是从阿利卡拉身上获取的鳞甲兽皮。阿利卡拉是一头传说中的风蛇，在千针石林的黑云峰顶被召唤并击败。",al={"蛇皮","阿利卡拉蛇皮","这张皮是什么"}},{q="谁想要阿利卡拉蛇皮？",a="白沙岗哨的莫特加·火鬃需要这张蛇皮以及剩余的火岩粉，以证明这条蛇不再构成威胁。",al={"谁剥取蛇皮","找谁交任务","谁需要阿利卡拉蛇皮"}},{q="当初为什么要召唤阿利卡拉？",a="玛加萨·野性图腾声称牛头人传统的改变激怒了先祖风蛇阿利卡拉，导致它开始跟踪大酋长凯恩·血蹄。她指示必须在凯恩受到伤害之前将这头野兽引出并击杀。",al={"为何召唤阿利卡拉","为何击杀阿利卡拉"}},{q="在哪里可以获得这张蛇皮？",a="在黑云峰内的一根埋骨石柱上，通过将附魔的火岩粉扔进生命之圣火中召唤出阿利卡拉后，可直接从它身上拾取。",al={"哪里获得阿利卡拉蛇皮","阿利卡拉的位置"}}},fx={d099bc06={q="阿利卡拉蛇皮来自哪里？",a="这张皮是直接从阿利卡拉的尸体上剥下来的，这是一种在千针石林的黑云峰被召唤出来的邪恶风蛇之灵。玛加萨·野性图腾对火岩粉进行了附魔，当这种粉末撒在埋葬死者的生命圣火上时，就能召唤出阿利卡拉，以便将其击杀并剥下她的皮。",al={"阿利卡拉皮起源","阿利卡拉蛇皮来自哪里","阿利卡拉蛇皮的来源"}}},fp="20,231,26.474.0,22.458.1,33.136.0,35.152.0,44.245.0,31.176.0"}
P.entries["item:arnak-s-hoof"] = {n="阿纳克的蹄子",s="阿纳克的蹄子是从罪犯阿纳克·恐怖图腾身上割下的死亡证明，令人毛骨悚然。阿纳克在黑云峰的悬崖上被追捕，因谋杀了一位牛头人同胞并绑架了他的妹妹，被乱风岗的保卫者判处死刑。",h="阿纳克的蹄子是从罪犯阿纳克·恐怖图腾身上割下的死亡证明，令人毛骨悚然。阿纳克在黑云峰的悬崖上被追捕，因谋杀了一位牛头人同胞并绑架了他的妹妹，被乱风岗的保卫者判处死刑。",kw={"阿纳克","阿纳克·恐怖图腾","阿纳克的蹄子","峭壁卫兵图林·长角","黑云峰","乱风岗","拉克塔·风歌","千针石林"},ang={["faction:Horde"]="消灭阿纳克巩固了乱风岗在千针石林的权威，并削弱了威胁部落补给路线的背信弃义的恐怖图腾势力的影响力。",["race:Tauren"]="对于平原上的牛头人来说，取下阿纳克的蹄子是对一个叛徒的部落正义，他的谋杀行径为千针石林带来了耻辱和流血。"},sec={{t="流放者的悬赏",b="阿纳克·恐怖图腾在千针石林臭名昭著，作为一个残暴程度甚至跨越了牛头人氏族政治界线的亡命之徒，他的恶名传遍各地。在谋杀了一位牛头人并绑架了受害者的妹妹拉克塔·风歌后，官方对他发出了悬赏令。阿纳克躲在黑云峰的高处，周围被恐怖图腾的卫兵包围。击杀他并拿走他被切下的蹄子，对于乱风岗的峭壁卫兵图林·长角来说，是这个杀人凶手终于为自己的罪行付出代价的确凿证明。"}},faq={{q="阿纳克的蹄子有什么用？",a="阿纳克的蹄子是亡命之徒阿纳克·恐怖图腾死亡的实物证明。它需要被上交给乱风岗的峭壁卫兵图林·长角，以完成悬赏任务并领取承诺的奖励。",al={"阿纳克的蹄子交任务","阿纳克的蹄子怎么用","谁要阿纳克的蹄子"}},{q="阿纳克·恐怖图腾是谁？",a="阿纳克是一个因谋杀和绑架而被通缉的恐怖图腾叛徒。他杀害了一名牛头人部落成员，并将受害者的妹妹拉克塔·风歌囚禁在黑云峰的悬崖上。",al={"阿纳克是谁","阿纳克·恐怖图腾背景故事","为什么要通缉阿纳克"}},{q="阿纳克·恐怖图腾在哪里？",a="阿纳克位于千针石林北部的黑云峰悬崖上，可以通过靠近剃刀高地山脊的绳桥前往。他将人质拉克塔·风歌囚禁在同一个悬崖上。",al={"阿纳克·恐怖图腾位置","阿纳克在哪里","如何找到阿纳克"}}},fx={["8804d903"]={q="阿纳克的蹄子是什么？",a="这只断蹄是亡命之徒牛头人阿纳克·野性图腾已被击杀的铁证。它直接取自千针石林风蚀台地上的尸体，被带回乱风岗以证明正义终究追上了这个被放逐的恶棍。",al={"阿纳克的蹄子","这是什么蹄子"}},a4f2e55c={q="阿纳克的蹄子来自哪里？",a="它取自阿纳克·野性图腾，一个潜伏在黑云峰附近悬崖上的叛徒牛头人。它不是锻造或制造出来的，而是在他俯瞰峡谷的藏身处与其对峙并将其击杀后获得的一件战利品。",al={"在哪能得到阿纳克的蹄子","阿纳克的蹄子来源","阿纳克的蹄子起源"}},ffececdb={q="为什么有人想要阿纳克的蹄子？",a="乱风岗的峭壁卫兵图林·长角发布了悬赏，要求提供阿纳克死亡的证明。阿纳克犯下了令人发指的罪行——杀害了一名无辜的牛头人并绑架了他的妹妹拉克塔·风歌。上交他的蹄子即完成了悬赏，并赢得了乱风岗守护者的感激与赏金。",al={"谁想要阿纳克的蹄子","为什么要上交阿纳克的蹄子","为什么要阿纳克的蹄子"}}},fp="12,256,20.533.0,30.200.0,24.183.0,31.211.0"}
P.entries["item:astor-s-letter-of-introduction"] = {n="阿斯托的介绍信",s="阿斯托的介绍信是阿斯托·哈德伦携带的一份文件，他是一名往返于银松森林和幽暗城的信使。这份信被渴望加入死亡猎手的学徒们截获，用作潜入涉及店主安德隆·甘特的疑似阴谋的掩护。",h="阿斯托的介绍信是阿斯托·哈德伦携带的一份文件，他是一名往返于银松森林和幽暗城的信使。这份信被渴望加入死亡猎手的学徒们截获，用作潜入涉及店主安德隆·甘特的疑似阴谋的掩护。",kw={"安德隆·甘特","apothecarium","阿斯托·哈德伦","死亡猎手","梅内特·卡卡德","银松森林","幽暗城","瓦里玛萨斯"},ang={["class:Rogue"]="获取并利用阿斯托的信件是寻求加入死亡猎手的被遗忘者潜行者的基础实地演练，旨在测试他们在暗杀、盗窃和伪装方面的专业技能。",["race:Undead"]="围绕这封信的阴谋凸显了幽暗城内部的猜疑，瓦里玛萨斯领主利用死亡猎手来清除被遗忘者民众中的颠覆分子。"},sec={{t="信使的凭证",b="阿斯托·哈德伦曾是一名在银松森林和首都之间往返的谨慎信使。他个人的介绍信可以向城中的非法联络人证明持有者的身份。当死亡猎手联络员梅内特·卡卡德需要调查幽暗城内可疑的泄密事件时，阿斯托的行程使他立刻成为了目标。通过消灭哈德伦或抢走他的文件，特工可以冒用他的身份，并拦截原本只送往阿斯托手中的秘密通讯。"},{t="Apothecarium的诱捕行动",b="梅内特·卡卡德利用找回的信件欺骗了位于Apothecarium附近的店主安德隆·甘特。瓦里玛萨斯领主怀疑甘特向不明第三方泄露被遗忘者的情报。身怀阿斯托的信件，一名卧底特工便可以伪装成他所期待的联络人，利用甘特毫无戒心的信任来揭露其同谋的身份，并获得他叛国的证据。"}},faq={{q="阿斯托的介绍信有什么用？",a="它被用作欺骗商人安德隆·甘特的身份证明。通过出示这封信，特工可以假冒信使阿斯托·哈德伦，从而揭露甘特的秘密交易。",al={"信件的用途","信件的作用","阿斯托的信件用法"}},{q="阿斯托·哈德伦是谁？",a="阿斯托·哈德伦是一名使者和信使，在被死亡猎手特工拦截之前，他经常往返于银松森林和幽暗城之间的道路上，为私人客户运送信件。",al={"阿斯托是谁","阿斯托·哈德伦背景故事","谁持有这封信"}},{q="为什么梅内特·卡卡德想要这封信？",a="梅内特·卡卡德需要这封信来测试希望加入死亡猎手的应募者，并针对被瓦里玛萨斯领主怀疑叛国的安德隆·甘特进行诱捕行动。",al={"为什么梅内特需要它","卡卡德的计划"}},{q="安德隆·甘特怀疑这封信是偷来的吗？",a="不。梅内特指出甘特没有足够的智慧去怀疑有诈，甘特很轻易地就接受了送信人作为他的同谋派来的常规信使。",al={"甘特察觉了吗","安德隆被骗了吗"}}},fx={da9b0b54={q="阿斯托的介绍信是什么？",a="这是阿斯托·哈德伦携带的证明文件，他是一位往返于银松森林和幽暗城之间的旅行信使。该文件表明持有人是安德隆·甘特的预期联络人，安德隆是一位涉嫌与不知名的外部势力勾结的幽暗城商人。",al={"阿斯托的信是什么","阿斯托的介绍信","这封信是什么"}}},fp="30,269,23.494.0,29.418.1,48.178.0,21.203.0,40.174.0,46.158.1"}
P.entries["item:ataeric-s-staff"] = {n="阿塔瑞克之杖",s="阿塔瑞克之杖是一件由达拉然大法师阿塔瑞克所持有的强大魔法介质，他是一位身处银松森林的高级达拉然法师。它既是操纵当地地脉的焦点，也是大法师被瑟伯切尔的被遗忘者击败的有力证据。",h="阿塔瑞克之杖是一件由达拉然大法师阿塔瑞克所持有的强大魔法介质，他是一位身处银松森林的高级达拉然法师。它既是操纵当地地脉的焦点，也是大法师被瑟伯切尔的被遗忘者击败的有力证据。",kw={"大法师阿塔瑞克","阿塔瑞克之杖","达拉然","地脉节点","瑟伯切尔","暗影牧师奥利斯特","银松森林","编织者"},ang={["class:Mage"]="这根法杖是达拉然大法师用来接入并唤醒沉睡地脉节点的焦点工具的典范。",["race:Undead"]="取回法杖阻止了达拉然对银松森林魔法储备的进一步控制，确保了被遗忘者西部边境的安全。"},sec={{t="瑟伯切尔的战利品",b="由于对达拉然的魔法扩张感到担忧，暗影牧师奥利斯特下令暗杀阿塔瑞克，并要求取回这根法杖。随着阿塔瑞克被杀、法杖被收缴，聚集的地脉能量重新陷入了休眠。将法杖带回瑟伯切尔标志着在对抗达拉然的野心方面取得了决定性的胜利，尽管被遗忘者仍对大地上残留的潜在力量保持警惕。"},{t="地脉魔法的介质",b="这根由大法师阿塔瑞克携带的法杖，曾被用于引导和利用银松森林南部的地脉能量。在达拉然的指示下，阿塔瑞克试图重新激活靠近该魔法王国边界的一处古老地脉节点。这根法杖是编织这些巨大环境能量流的关键工具，使这位大法师对附近的被遗忘者聚居点构成了巨大的威胁。"}},faq={{q="阿塔瑞克之杖属于谁？",a="这根法杖属于大法师阿塔瑞克，他是一位驻扎在银松森林的高阶达拉然法师，负责监督一处强大地脉节点的重新激活工作。",al={"阿塔瑞克之杖的主人","阿塔瑞克的主人","谁掉落了这根法杖"}},{q="为什么暗影牧师奥利斯特想要阿塔瑞克之杖？",a="位于瑟伯切尔的暗影牧师奥利斯特需要这根法杖作为大法师阿塔瑞克死亡的证明，并确保达拉然操纵该地区地脉的企图被彻底粉碎。",al={"为什么奥利斯特想要法杖","法杖在瑟伯切尔的作用","谁拿走了法杖"}},{q="从大法师阿塔瑞克手中夺走法杖后会发生什么？",a="一旦阿塔瑞克被杀且法杖被夺走，达拉然正在编织的地脉能量就会消散并陷入休眠，从而消除了对被遗忘者的直接魔法威胁。",al={"地脉会发生什么","击败阿塔瑞克之后"}},{q="在哪里可以找到阿塔瑞克之杖？",a="它直接从大法师阿塔瑞克的尸体上取回，他就在银松森林南部达拉然据点附近，与其他达拉然法师和守卫在一起。",al={"在哪获得阿塔瑞克之杖","阿塔瑞克的位置"}}},fp="15,258,23.409.0,22.398.1,35.149.1,53.196.0,59.170.1,31.165.0"}
P.entries["item:athrikus-narassin-s-head"] = {n="埃瑟里克斯·纳拉辛的头颅",s="这颗被砍下的头颅是证明阿斯利库斯·纳拉辛死亡的证据，这名古老的术士曾在黑海岸北部主持黑暗仪式。这颗头颅取自残破塔楼的顶端，它证实了以奥萨拉克斯之塔为中心的恶魔活动已被瓦解。",h="这颗被砍下的头颅是证明阿斯利库斯·纳拉辛死亡的证据，这名古老的术士曾在黑海岸北部主持黑暗仪式。这颗头颅取自残破塔楼的顶端，它证实了以奥萨拉克斯之塔为中心的恶魔活动已被瓦解。",kw={"奥萨拉克斯之塔","阿斯利库斯·纳拉辛","邪教徒","黑海岸","邪能","被砍下的头颅","术士"},ang={["class:Warlock"]="阿斯利库斯对邪能力量的掌握使他成为了一名可怕的施法者，但他在此处那种鲁莽的显眼行为最终导致了他的毁灭。",["race:NightElf"]="铲除阿斯利库斯·纳拉辛消除了一处位于卡利姆多北部海岸古代卡多雷遗迹中的恶魔毒瘤。"},sec={{t="奥萨拉克斯的枯萎",b="阿斯利库斯·纳拉辛盘踞在奥萨拉克斯之塔的顶端，指挥着一群在黑海岸沿岸操练邪能魔法的黑暗法师。纳拉辛古老而根深蒂固，他协调的恶魔召唤仪式威胁着周围的荒野。取下他的首级能粉碎这个集会的领导层，击退他们在该地区的直接据点，尽管挥之不去的腐化意味着未来仍需保持警惕。"}},faq={{q="阿斯利库斯·纳拉辛是谁？",a="阿斯利库斯·纳拉辛是一位古老而强大的术士，统领着盘踞在黑海岸北部奥萨拉克斯之塔中的邪教徒。他在塔尖主持着该集会的恶魔仪式。",al={"阿斯利库斯是谁","阿斯利库斯背景","术士是谁"}},{q="为什么需要他的头颅？",a="监视奥萨拉克斯之塔的联盟斥候需要确凿的证据来证明这位术士大师已被击杀。呈上他被砍下的头颅不仅证实了他的死亡，也标志着针对恶魔势力的打击行动取得了成功。",al={"为什么要取下头颅","阿斯利库斯的头颅有什么用","头颅是做什么用的"}},{q="阿斯利库斯·纳拉辛在哪里？",a="他居住在奥萨拉克斯之塔的最高处，该塔位于黑海岸北部，由他忠诚的邪教徒和召唤出的恶魔严密守卫。",al={"去哪里找阿斯利库斯","阿斯利库斯的位置","奥萨拉克斯之塔塔顶"}},{q="杀了他能彻底消除恶魔威胁吗？",a="虽然阿斯利库斯的死是对黑暗仪式施法者的一次沉重打击并导致他们目前的行动陷入混乱，但斥候认为恶魔势力终将重组，黑海岸仍需持续防守。",al={"恶魔消失了吗","塔被净化了吗","我们击败邪教徒了吗"}}},fx={["5ecacf9e"]={q="埃瑟里克斯·纳拉辛的头颅是什么？",a="这是埃瑟里克斯·纳拉辛被砍下的头颅，他是一位古老的暗夜精灵术士，指挥着奥萨拉克斯之塔内的黑暗势力。你以此作为当地邪教领袖已被击杀的不可辩驳的证据。",al={"埃瑟里克斯的头颅是什么","埃瑟里克斯·纳拉辛的头颅"}},["639f8902"]={q="埃瑟里克斯·纳拉辛的头颅来自哪里？",a="它直接取自黑海岸北部的奥萨拉克斯之塔顶端。埃瑟里克斯·纳拉辛盘踞在废墟结构的巅峰，周围环绕着他最危险的术士和邪能召唤爪牙，直到被击倒。",al={"埃瑟里克斯的头颅来自哪里","在哪能得到埃瑟里克斯的头颅","埃瑟里克斯的头颅来源"}}},fp="24,282,21.439.1,26.213.1,23.225.0,35.149.1,57.203.0"}
P.entries["item:bag-of-empty-ooze-containers"] = {n="一包空的软泥怪采样瓶",s="一包空的软泥怪采样瓶是铁炉堡的侏儒研究员拉里斯·空轮提供的一套无菌玻璃器具。这套器具为精细的实地采集而准备，里面装着空的样本瓶，旨在采集艾泽拉斯各地原始、未受腐蚀的软泥怪样本。",h="一包空的软泥怪采样瓶是铁炉堡的侏儒研究员拉里斯·空轮提供的一套无菌玻璃器具。这套器具为精细的实地采集而准备，里面装着空的样本瓶，旨在采集艾泽拉斯各地原始、未受腐蚀的软泥怪样本。",kw={"一包空的软泥怪采样瓶","空的纯净采样瓶","铁炉堡","拉里斯·空轮","软泥怪容器","纯净采样瓶","软泥"},ang={["faction:Alliance"]="拉里斯·空轮在铁炉堡协调他的生态研究，派遣联盟冒险者深入安戈洛环形山等未被驯服的领土，带回关键的实地样本。",["race:Gnome"]="包内耐用且抗化学腐蚀的瓶子体现了标准侏儒的独创性，使实地研究人员能够安全地运输危险的腐蚀性野生动物样本。"},sec={{t="实地研究设备",b="在调查艾泽拉斯软泥怪奇特的生物学特性时，拉里斯·空轮意识到软泥生物会迅速吸收并反映其周围环境的腐蚀。在研究了诸如费伍德森林等地的受污染残留物后，这位侏儒科学家定制了这些坚固的样本瓶，既能承受酸性样本，又能保持其自然状态。这只背包里装有足够的瓶子，供探险者从野外未受触及的区域收集纯净、未受污染的软泥——最著名的是安戈洛环形山的原始荒野，那里古老的胶状软泥怪在没有恶魔腐蚀的情况下繁衍生息。"}},faq={{q="一包空的软泥怪采样瓶里有什么？",a="包里装有十个空的纯净采样瓶，这是专门制作的玻璃容器，旨在安全存储腐蚀性软泥怪样本，而不会导致样本降解或污染。",al={"包里有什么","背包内容物","软泥怪容器内容物"}},{q="是谁提供了这些容器？",a="它们是由拉里斯·空轮提供的，他是一位在铁炉堡的Hall of Explorers工作的古怪侏儒研究员，专门研究软泥怪的环境适应性。",al={"谁提供软泥怪背包","拉里斯·空轮背包","谁提供一包空的软泥怪采样瓶"}},{q="这些瓶子是用来收集哪种软泥怪的？",a="这些瓶子是用于纯净、未受腐蚀的软泥怪样本的。与在费伍德森林发现的受枯萎影响的样本不同，纯净的软泥可以从居住在安戈洛环形山的胶状软泥怪身上收集到。",al={"什么软泥可以装入瓶中","纯净采样瓶的目标","在哪里装满瓶子"}},{q="拉里斯为什么需要纯净的软泥怪样本？",a="拉里斯意识到软泥怪像生物海绵一样吸收其环境的特质。为了了解这种适应性是如何运作的，他需要一个未受腐蚀的基准样本，以便与来自受枯萎影响地区的受污染软泥进行比较。",al={"为什么要收集纯净软泥","空轮的研究目标","为什么需要纯净的软泥怪"}}},fx={["9a2213f5"]={q="一包空的软泥怪采样瓶是什么？",a="这个袋子是一套专门的野外装备，由铁炉堡的拉里斯·空轮提供给你。里面有十个空的样品瓶，旨在安全地盛放和运输不稳定的软泥怪标本回他的工作室，而不会泄漏或污染其中的内容物。",al={"一包空的软泥怪采样瓶","什么是软泥怪采样瓶","拉里斯的软泥怪袋子"}}},fp="28,267,24.585.0,48.171.0,30.176.0,51.186.0,38.235.0"}
P.entries["item:balnir-snapdragons"] = {n="巴尼尔金鱼草",s="巴尼尔金鱼草是生长在提瑞斯法林地东部巴尼尔农场的一种鲜艳花朵。它们对魔法流非常敏感，因此被遗忘者将其视为检测瘟疫之地蔓延而来的天灾腐蚀的精密预警器。",h="巴尼尔金鱼草是生长在提瑞斯法林地东部巴尼尔农场的一种鲜艳花朵。它们对魔法流非常敏感，因此被遗忘者将其视为检测瘟疫之地蔓延而来的天灾腐蚀的精密预警器。",kw={"安娜斯塔西娅·哈特威尔","巴尼尔农场","巴尼尔金鱼草","mage quarter","瘟疫之地","提瑞斯法林地"},ang={["class:Mage"]="被遗忘者法师将巴尼尔金鱼草作为原始的魔法导管进行研究，利用它们天然的敏感性来量化魔法瘟疫如何扭曲周围的魔网能量。",["race:Undead"]="对于被遗忘者来说，这些花朵为他们的东部边界提供了实际的监控手段，如果巫妖王的腐蚀正在吞噬提瑞斯法的土地，它们会向幽暗城的研究人员发出预警。"},sec={{t="废墟中的花朵",b="这些色彩斑斓的花朵至今仍生长在巴尼尔农场的花园里。随着洛丹伦的陷落和天灾军团的崛起，这座位于提瑞斯法林地东部的家园已沦为废墟。由于紧邻东部的瘟疫之地，这片花园恰好处于巫妖王的瘟疫侵蚀提瑞斯法的前线，这也使得这里的花朵成为了观察腐蚀扩散情况的理想指标。"},{t="魔法气压计",b="由于金鱼草对大气中的魔法异常敏感，它们成为了检测魔法瘟疫的活体气压计。安娜斯塔西娅·哈特威尔和幽暗城的被遗忘者法师们正在搜寻农场窗台花箱中的新鲜样本。通过将这些植物移交给皇家药剂师学会，幽暗城希望能借此分析植物样本，并测量巫妖王的瘟疫到底有多深地渗透到了提瑞斯法的土地边界之内。"}},faq={{q="在哪里可以找到巴尼尔金鱼草？",a="它们生长在巴尼尔农场的废墟周围的花箱和花坛中，该农场位于提瑞斯法林地东部，靠近西瘟疫之地的边界。",al={"巴尼尔金鱼草位置","花朵在哪里","巴尼尔花朵位置"}},{q="为什么安娜斯塔西娅·哈特威尔需要这些金鱼草？",a="金鱼草能够轻易吸收潜藏的魔法能量。安娜斯塔西娅·哈特威尔需要将新鲜样本送往幽暗城的药剂师那里，以测量瘟疫之地的魔法污染是否正在积极向提瑞斯法林地扩散。",al={"为什么要收集金鱼草","巴尼尔农场任务目标","安娜斯塔西娅·哈特威尔金鱼草"}},{q="最初是谁种植了这些花？",a="它们生长在巴尼尔农场的花园里，这片以其命名的家庭家园在天灾军团席卷洛丹伦乡村时与其他地方一同化为了废墟。",al={"谁种植了巴尼尔金鱼草","巴尼尔家族金鱼草"}},{q="天灾军团摧毁了巴尼尔的花朵吗？",a="没有。金鱼草依然生长在农场的花园里，这正是安娜斯塔西娅·哈特威尔派人去收集的原因：通过研究这些紧邻瘟疫之地的样本，可以观测到瘟疫是否已经侵入了提瑞斯法林地。",al={"瘟疫是否杀死了金鱼草"}}},fx={ebe2752a={q="巴尼尔金鱼草是什么？",a="巴尼尔金鱼草是一种独特的花卉，种植在提瑞斯法林地东部的巴尼尔农场的花箱里。它们天生敏感且对魔法能量异常容易接受，能够吸收周围潜伏的魔法流，这使它们成为探测附近环境腐化程度的主要指示物。",al={"什么是巴尼尔金鱼草","巴尼尔金鱼草花","巴尼尔金鱼草背景故事"}}},fp="18,267,15.384.0,18.429.0,38.171.0,51.228.0,34.196.0,43.208.0"}
P.entries["item:baron-longshore-s-head"] = {n="巴隆·朗绍尔的头颅",s="这颗断头是巴隆·朗绍尔死亡的证明，他是南海海盗船只“无畏号”的船长。加兹鲁维为这名海盗的遗骸悬赏，以保护棘齿城在商旅海岸的商业航运。",h="这颗断头是巴隆·朗绍尔死亡的证明，他是南海海盗船只“无畏号”的船长。加兹鲁维为这名海盗的遗骸悬赏，以保护棘齿城在商旅海岸的商业航运。",kw={"巴隆·朗绍尔","悬赏","加兹鲁维","吉尔尼斯","无畏号","商旅海岸","棘齿城","南海海盗"},ang={["race:Human"]="加兹鲁维的悬赏令指出，朗绍尔在加入南海海盗从事海上劫掠之前，来自孤立的吉尔尼斯王国。"},sec={{t="海盗的赏金",b="巴隆·朗绍尔在棘齿城以南的商旅海岸沿线的营地进行活动，他代表南海海盗指挥了针对区域内商船的突袭。他的旗舰“无畏号”直接威胁到了连接卡利姆多与东部王国的地精贸易航线。棘齿城的首席工程师加兹鲁维悬赏朗绍尔的人头，要求提供确凿的死亡证明。上交这颗海盗的头颅即可履行契约，并从港口管理部门获得金币奖励。"}},faq={{q="巴隆·朗绍尔是谁？",a="他是一位来自人类王国吉尔尼斯的船长。他率领着南海海盗在棘齿城以南的商旅海岸沿线的营地活动，并在他的船只“无畏号”上对航运路线进行骚扰。",al={"巴隆·朗绍尔","朗绍尔是谁","朗绍尔船长"}},{q="谁想要巴隆·朗绍尔的头颅？",a="棘齿城的地精领袖加兹鲁维发布了悬赏通告。南海海盗劫掠了棘齿城的商船，这促使加兹鲁维要求获得朗绍尔的遗骸以确保港口的贸易畅通无阻。",al={"谁要这颗头颅","交给谁","加兹鲁维的悬赏"}},{q="巴隆·朗绍尔在哪里？",a="朗绍尔在棘齿城以南的海岸线上，即商旅海岸北部的三个南海海盗营地巡逻，位置在北方城堡的北侧。",al={"朗绍尔在哪里","朗绍尔位置","巴隆·朗绍尔刷新"}},{q="巴隆·朗绍尔指挥哪艘船？",a="他指挥的是“无畏号”，这艘令人生畏的船只在贫瘠之地外海的无尽之海中袭击商船。",al={"朗绍尔的船","无畏号","无畏号船只"}}},fx={["0986c9c0"]={q="巴隆·朗绍尔的头颅是什么？",a="这是巴隆·朗绍尔那颗可怕的断头，他是一位来自吉尔尼斯的臭名昭著的海盗船长，指挥着南海海盗的船只。你将其作为他死亡的铁证，以完成在棘齿城发布的针对他的悬赏，确保热砂港知道这位臭名昭著的劫掠者将不再困扰他们的商运航线。",al={"巴隆·朗绍尔的头颅物品","这是什么头颅","朗绍尔的头颅背景故事"}}},fp="22,247,22.499.0,24.211.0,33.242.0,31.151.0,38.128.0"}
P.entries["item:barrel-of-barleybrew-scalder"] = {n="一大桶热麦酒",s="一大桶热麦酒是麦酒家族为了向主要竞争对手证明其酿酒实力而精心酿制的一桶烈性麦酒。它被托付给秘密信使，任务是潜入卡拉诺斯的雷酒酿制厂，进行一场狡黠的试饮破坏活动。",h="一大桶热麦酒是麦酒家族为了向主要竞争对手证明其酿酒实力而精心酿制的一桶烈性麦酒。它被托付给秘密信使，任务是潜入卡拉诺斯的雷酒酿制厂，进行一场狡黠的试饮破坏活动。",kw={"麦酒","麦酒家族","酿酒厂","丹莫罗","卡拉诺斯","马莱斯","热麦酒","雷酒家族"},ang={["class:Rogue"]="引开地窖守卫并将贵重违禁品潜入守卫森严的藏酒处，是一场经典的矮人式诡计，既有趣又没有太大风险。",["race:Dwarf"]="对于矮人来说，酿酒既是艺术，也是一种血腥运动；参与到有关谁的配方更胜一筹的地窖阴谋中，几乎已经成为了丹莫罗的一种消遣。"},sec={{t="丹莫罗的苦涩宿怨",b="对于丹莫罗的矮人来说，酿酒是一项严肃的事业，而雷酒家族与麦酒家族之间的宿怨比任何竞争都要激烈。虽然雷酒家族凭借其在卡拉诺斯繁忙的酿酒厂享有盛誉并引以为傲，但马莱斯·麦酒拒绝一直活在他们的阴影之下。马莱斯并没有单纯地依靠公开酒馆，而是酿造了这种火辣的“热麦酒”来证明他的配方绝不逊色于任何人——他希望那些不知情的顾客在品尝后能意识到，雷酒家族并非垄断了矮人的精品美酒。"},{t="地窖里的诡计",b="这桶酒本应直接偷运到雷酒酿制厂下方的地窖中，替换掉那里的一桶当地人最爱的雷霆麦酒。此举并非为了投毒或破坏，而是一个旨在挫伤对方傲气的矮人式恶作剧：确保楼上供应的下一批酒实际上是麦酒家族强劲的热麦酒。"}},faq={{q="一大桶热麦酒里装的是什么？",a="里面装的是马莱斯·麦酒招牌式的热麦酒，这是一种为了与雷酒家族著名的配方一较高下而酿制的强劲矮人麦酒。",al={"热麦酒成分","麦酒种类","什么是热麦酒"}},{q="为什么马莱斯想把这桶酒换掉？",a="马莱斯承认雷酒家族酿的酒确实不错，但他想给他们一个教训，让他们学会谦虚。他想让地窖里的顾客无意中品尝到他自己的杰作，从而发现麦酒家族的工艺同样出色，甚至更好。",al={"为什么要替换酒桶","宿怨原因","马莱斯为什么要偷偷酿酒"}},{q="这桶酒要送到哪里？",a="它会被带到卡拉诺斯的雷酒酿制厂下方的地窖，并放入那些即将开桶供应的雷霆麦酒货架中。",al={"我该把酒桶放在哪里","热麦酒位置","酿酒厂地窖"}},{q="这种麦酒会伤害任何人吗？",a="不会。这只是一种强劲的矮人麦酒，用于竞争而已。这两个家族之间的竞争虽然激烈，但这仅仅是专业荣誉的问题，而非出于恶意。",al={"热麦酒有毒吗","是否为毒药","会伤人吗"}}},fx={["9f414f7e"]={q="一大桶热麦酒是什么？",a="这是一桶由马莱斯·麦酒酿造的烈性麦酒。这桶酒并非通过常规贸易出售，而是作为酿酒竞争中的一种手段，意在秘密替换竞争对手的库存，以赢得不知情的饮用者的青睐。",al={"什么是热麦酒","热麦酒木桶","一大桶热麦酒"}},["00d1bcdd"]={q="一大桶热麦酒来自哪里，是谁制作的？",a="这桶酒是由马莱斯·麦酒酿造并提供的。作为对家族技艺的自豪，马莱斯调制了这个配方，旨在证明麦酒家族能够匹敌甚至超越竞争对手雷酒家族的声望。",al={"谁制作了热麦酒","热麦酒来自哪里","热麦酒起源"}}},fp="28,287,27.543.0,24.337.1,48.135.0,42.215.0,26.155.0,33.171.0"}
P.entries["item:barrel-of-shimmer-stout"] = {n="一大桶微光酒",s="这是一桶刚酿好的雷杰德·麦酒实验性矮人麦芽酒，产自寒冷的丹莫罗。这种酒以给饮用者带来强烈的冲击感、据说能让视力变得更敏锐而闻名，旨在作为礼物送给在高山隘口值守的卫兵。",h="这是一桶刚酿好的雷杰德·麦酒实验性矮人麦芽酒，产自寒冷的丹莫罗。这种酒以给饮用者带来强烈的冲击感、据说能让视力变得更敏锐而闻名，旨在作为礼物送给在高山隘口值守的卫兵。",kw={"一大桶微光酒","丹莫罗","矮人麦芽酒","洛克莫丹","巡山人维拉特·麦酒","雷杰德·麦酒","微光酒"},ang={["profession:Cooking"]="矮人麦芽酒经常挑战烹饪实验的极限，将强效发酵与耐寒的山地原料相结合，以抵御刺骨的天气。",["race:Dwarf"]="酿造是铁炉堡社会文化的一块基石，将新酿成的黑啤酒送给值守的族人是一种光荣的山地传统。"},sec={{t="酿酒师的骄傲",b="微光酒由雷杰德·麦酒在搜集了遍布丹莫罗的稀有原料后酿制而成，代表了传奇的麦酒家族最新的胜利。矮人酿酒师对自己的手艺极其重视，他们不断竞争，力求酿造出足以抵御高山严寒的烈性饮品。雷杰德的最新配方不仅旨在温暖脾胃，还能让那些在寒风中驻守的人感官更加敏锐。"},{t="守望者的补给",b="这桶酒是专门为威尔特·麦酒山地探险队员准备的，他正守卫在通往洛克莫丹的隘口南侧塔楼。在荒凉的边境，山地探险队员们不仅要忍受刺骨的严寒，还要在与穴居人和野生动物的冲突间隙进行漫长的值守。一桶新鲜的家族麦芽酒既是令人欣慰的家乡味道，也是一种强效的活力补给，足以让疲惫的哨兵感觉自己在黑暗中也能看清前方。"}},faq={{q="一大桶微光酒里装的是什么？",a="里面装的是微光酒，这是雷杰德·麦酒新研发的一种矮人配方。这种酒以其极其强劲的后劲而闻名，任何尝试过它的人都会感到精力充沛，双眼甚至会闪烁着光芒。",al={"什么是微光酒","这是什么麦芽酒","微光酒饮品"}},{q="是谁酿造了这桶黑啤酒？",a="这麦芽酒是由雷杰德·麦酒酿造的，他是丹莫罗著名的麦酒氏族的一员，曾花时间完善配方以令他的族人印象深刻。",al={"谁酿造了微光酒","微光酒酿造者","雷杰德·麦酒"}},{q="这桶酒是为谁准备的？",a="这是为雷杰德的兄弟，威尔特·麦酒山地探险队员准备的，他驻守在通往洛克莫丹道路旁的南侧岗哨塔楼。",al={"谁能得到这桶酒","这桶酒送往何处","威尔特·麦酒"}},{q="微光酒对饮用者有什么影响？",a="除了带来强烈的醉意，这种黑啤酒还会给饮用者带来一种强烈的震颤感，使他们的眼睛闪闪发光，感觉仿佛能在漆黑中视物，这使它在警惕的山地探险队员中颇受欢迎。",al={"微光酒的效果","喝了能夜视吗","微光酒有什么用"}}},fp="23,272,16.452.0,22.454.0,39.221.0,30.150.0,29.145.0,61.208.0"}
P.entries["item:barrel-of-thunder-ale"] = {n="一大桶雷霆麦酒",s="“一大桶雷霆麦酒”是卡拉诺斯招牌佳酿的一桶珍品，是从雷酒酿制厂的地窖中被偷运出来的。它被调换成了马莱斯·麦酒的“大麦酒烫喉酒”，成为了酿酒竞争升级过程中发生卑劣行径的确凿证据。",h="“一大桶雷霆麦酒”是卡拉诺斯招牌佳酿的一桶珍品，是从雷酒酿制厂的地窖中被偷运出来的。它被调换成了马莱斯·麦酒的“大麦酒烫喉酒”，成为了酿酒竞争升级过程中发生卑劣行径的确凿证据。",kw={"一大桶雷霆麦酒","烈酒村","丹莫罗","卡拉诺斯","马莱斯·麦酒","雷霆麦酒","雷酒家族"},ang={["class:Rogue"]="潜入守卫森严的地窖并替换沉重的麦酒桶而不惊动任何人，这是潜行和技巧的一次经典且实用的展示。",["race:Dwarf"]="对于矮人来说，酿酒是严肃的事业和高级的政治；在竞争对手自己的地窖里调换他们珍贵的酒桶，这是一种极其大胆的侮辱。"},sec={{t="苦涩的交易",b="在丹莫罗，酿酒大师之间的竞争由来已久，其中最激烈的争端莫过于卡拉诺斯的雷酒家族与烈酒村的麦酒家族之间的世仇。马莱斯·麦酒试图将他自己的一桶“大麦酒烫喉酒”偷运进对手的地窖，好让雷酒家族的顾客能喝到他的酒，而不是他们自己的。这桶沉重的雷霆麦酒就是在这次交换中被截获的，它在当地卫兵的眼皮底下被拖了出来，作为调换成功的实物证据。"}},faq={{q="这桶里装的是什么？",a="它里面装的是雷霆麦酒，这是雷酒家族在卡拉诺斯酿造的著名黑啤。它在整个丹莫罗都被视为一种浓烈、劲道的矮人麦酒。",al={"雷霆麦酒内容物","什么是雷霆麦酒"}},{q="这桶酒是从哪里来的？",a="它是直接从卡拉诺斯酿制厂的地窖储藏室中偷出来的，是在马莱斯运送他的竞争酒品时趁机窃取的。",al={"如何获得","雷霆麦酒位置"}},{q="谁想要这桶酒？",a="位于西面烈酒村的马莱斯·麦酒。他希望这桶酒能被带给他，作为他的“烫喉酒”成功混入雷酒家族酒桶中的证据。",al={"雷霆麦酒交给谁","马莱斯·麦酒任务"}},{q="为什么要偷这桶酒？",a="马莱斯想要有力的证据，证明有人成功潜入了雷酒地窖，溜过了酿制厂守卫，并破坏了他竞争对手的供应。",al={"为什么要偷雷霆麦酒","苦涩的竞争故事"}}},fp="21,266,14.510.0,27.154.0,32.140.0,22.181.0,25.158.0"}
P.entries["item:barrow-key"] = {n="古墓钥匙",s="古墓钥匙是隐藏在石爪峰猛禽洞穴内的三把德鲁伊钥匙之一。它被锁在一个古墓宝箱中，以守护封印在洞穴宝库中的古代财宝。",h="古墓钥匙是隐藏在石爪峰猛禽洞穴内的三把德鲁伊钥匙之一。它被锁在一个古墓宝箱中，以守护封印在洞穴宝库中的古代财宝。",kw={"古墓钥匙","利爪钥匙","守门人的钥匙","沉睡者的钥匙","石爪峰","猛禽洞穴","猛禽洞穴宝库","大兽穴"},ang={["class:Druid"]="这把钥匙是猛禽洞穴德鲁伊设计的一项古老安全仪式的一部分，旨在保护他们地下圣所内的神圣物品。",["faction:Horde"]="石爪山脉的部落特工从被俘的暗夜精灵口中套取情报，以定位这把钥匙并掠夺德鲁伊的私人宝库。"},sec={{t="守护者的保障",b="在猛禽洞穴的地下古墓中，暗夜精灵德鲁伊建立了精巧的结界，以保护他们的圣物免受入侵者的侵害。古墓钥匙是这道多重锁的一部分，藏在地下通道中一个特制的宝箱里。获取它需要守门人的钥匙，确保只有那些了解德鲁伊防御网络的人才有希望将其据为己有。"},{t="解锁宝库",b="古墓钥匙与利爪钥匙和沉睡者的钥匙一起，对应着猛禽洞穴深处石祭坛上三个雕刻精美的锁孔。当三把钥匙同时转动时，保护性的附魔就会消散，向设法破解结界的人展示隐藏的德鲁伊圣物宝库。"}},faq={{q="古墓钥匙有什么用途？",a="古墓钥匙与利爪钥匙和沉睡者的钥匙一起使用，可以解锁猛禽洞穴宝库，这是一个位于石爪峰深处、存放着受保护的德鲁伊圣物的石箱。",al={"古墓钥匙用途","古墓钥匙开启什么","古墓钥匙的使用"}},{q="古墓钥匙藏在哪里？",a="它被锁在一个古墓宝箱里——看起来像一个隐藏的壁挂火把——位于石爪峰猛禽洞穴蜿蜒的隧道深处。",al={"古墓钥匙位置","古墓钥匙在哪","寻找古墓钥匙"}},{q="如何打开装有古墓钥匙的宝箱？",a="你必须先找到守门人的钥匙，德鲁伊将其藏在猛禽洞穴主入口附近的一个小灯笼里。",al={"打开古墓宝箱","解锁古墓钥匙","守门人的钥匙 古墓"}},{q="是谁将古墓钥匙藏在猛禽洞穴中的？",a="居住在石爪峰的暗夜精灵德鲁伊设计了这套精巧的安全系统，以防止他们强大的神器落入敌手，并将各个钥匙隐藏在洞穴的不同角落。",al={"谁制造了古墓钥匙","谁把钥匙藏在了猛禽洞穴"}}},fx={["6b9fc30c"]={q="古墓钥匙是什么？",a="古墓钥匙是石爪峰顶猛禽洞穴中的暗夜精灵德鲁伊所制作的三把附魔钥匙之一。它是复杂安保结界的一部分，旨在保护他们最珍贵和强大的遗物不落入敌手。",al={"古墓钥匙是什么","古墓钥匙信息","猛禽洞穴古墓钥匙"}},["17616df0"]={q="为什么有人想要古墓钥匙？",a="石爪山脉的部落势力正在寻找古墓钥匙，以及它的同系钥匙：利爪钥匙和沉睡者的钥匙。这三把钥匙合在一起可以破解封印猛禽洞穴宝库的德鲁伊结界，打开古墓深处封存的强大物品的宝库。",al={"为什么要找古墓钥匙","为什么想要古墓钥匙","谁想要古墓钥匙"}}},fp="10,195,22.413.0,19.315.1,32.174.0,31.149.0,52.136.0,43.205.0"}
P.entries["item:bartleby-s-mug"] = {n="巴特莱比的酒杯",s="巴特莱比的酒杯是暴风城中固执的格斗家巴特莱比的私人酒杯。只有在酒馆斗殴后，且杯中酒被一饮而尽时，它才会作为证明，彰显战士强行说服不配合对手的能力。",h="巴特莱比的酒杯是暴风城中固执的格斗家巴特莱比的私人酒杯。只有在酒馆斗殴后，且杯中酒被一饮而尽时，它才会作为证明，彰显战士强行说服不配合对手的能力。",kw={"巴特莱比","巴特莱比的酒杯","burlguard","暴风城","酒馆斗殴","战士训练"},ang={["class:Warrior"]="从巴特莱比手中夺取这个酒杯是年轻联盟战士早期的一种成年仪式，教导他们在言语无用时依靠纯粹的意志与武力。"},sec={{t="格斗家的奖品",b="对于普通的酒馆常客来说，巴特莱比的酒杯不过是那名臭名昭著的顽固酒鬼紧抓在手中的普通器皿。然而，对于一名在暴风城训练的新手战士来说，从巴特莱比手中夺过这个酒杯是对其纯粹身体统治力的一场考验。巴特莱比绝不会轻易交出他心爱的酒杯，除非被打到屈服——即便如此，他也坚持要喝干杯中最后一滴酒，才会将其作为战利品交出。"}},faq={{q="巴特莱比的酒杯有什么用途？",a="巴特莱比的酒杯是战士试炼中取得胜利的证明。将它带回给教官，证明了这名战士有能力应付顽固的酒馆斗殴者，并迫使其交出最珍贵的物品。",al={"巴特莱比的酒杯用途","为什么我需要巴特莱比的酒杯","酒杯有什么用"}},{q="这个酒杯最初是谁的？",a="这个酒杯属于巴特莱比，一个整天酗酒斗殴的好战酒鬼。他拒绝交出酒杯，除非有立志成为战士的人在肉搏战中击败他，且即便在那之后，也要等他喝完酒才行。",al={"谁是巴特莱比","巴特莱比的酒杯拥有者","谁拥有这个酒杯"}},{q="是谁要求获取巴特莱比的酒杯？",a="这个酒杯被带给暴风城的战士训练师Burlguard，他会观察这场斗殴，并要求以酒杯作为证明，然后才会继续战士的武技训练。",al={"谁想要这个酒杯","我要把巴特莱比的酒杯交给谁","巴特莱比的酒杯上交"}}},fx={["481c5411"]={q="巴特莱比的酒杯是什么？",a="巴特莱比的酒杯是暴风城酒馆中一位喜欢斗殴的常客巴特莱比的个人酒具。这只酒杯是年轻战士勇武的有力证明——只有在战斗中彻底击败巴特莱比，并且等他喝完杯中最后的一滴酒之后，他才会交出这只酒杯。",al={"巴特莱比的酒杯是什么","巴特莱比的酒杯"}},a3659338={q="伯尔加德为什么想要巴特莱比的酒杯？",a="伯尔加德要求你拿到这只酒杯，以此作为你在酒馆斗殴中站稳脚跟并击败巴特莱比的实物证明。拿走一个嗜酒者的心爱酒杯绝非易事；交出这只酒杯证明了你已经用拳头说服了巴特莱比，并已准备好继续你的战士训练。",al={"为什么要巴特莱比的酒杯","为什么伯尔加德要这只酒杯","伯尔加德要酒杯的用途"}}},fp="14,162,17.249.0,32.191.0,28.185.0,28.166.0"}
P.entries["item:bathran-s-hair"] = {n="巴斯兰的头发",s="巴斯兰的头发是一种珍稀而娇嫩的草药，生长在灰谷西北部的巴斯兰鬼屋废墟中。在暗夜精灵的传说中，这种植物因其强大的恢复功效而闻名，据说它不仅能治愈肉体的创伤，还能抚平精神上的痛苦。",h="巴斯兰的头发是一种珍稀而娇嫩的草药，生长在灰谷西北部的巴斯兰鬼屋废墟中。在暗夜精灵的传说中，这种植物因其强大的恢复功效而闻名，据说它不仅能治愈肉体的创伤，还能抚平精神上的痛苦。",kw={"灰谷","巴斯兰的头发","巴斯兰鬼屋","迈斯特拉岗哨","奥雷迪尔·阔叶","植物束"},ang={["profession:Herbalism"]="受过训练的草药师在定位巴斯兰的头发时具有明显的优势，因为他们对野生植物敏锐的眼光使他们能够感知到残骸中隐藏的植物束。",["race:NightElf"]="对于卡多雷来说，在巴斯兰的头发这种具有疗效的植物依然生长的地方出现被遗忘者，是一个令人不安的迹象，这关乎他们古老家园的存续。"},sec={{t="精神的疗法",b="巴斯兰的头发长在迈斯特拉岗哨以北的古老废墟阴影中，长期以来一直受到暗夜精灵治疗者的珍视。与那些只能舒缓普通外伤的常见药用植物不同，这种草药拥有据说能治愈深层精神疾病的恢复特性。当阿斯特兰纳的一位年轻暗夜精灵遭受某种阴险且顽固的疾病折磨时，草药师奥雷迪尔·阔叶就会寻找这种珍稀植物的枝条，用以调配一种关键的药剂。"},{t="在废墟中采集",b="寻找巴斯兰的头发变得越来越危险了。这种草药通常成束地散落在巴斯兰鬼屋各处，被丢弃在叶堆之下，靠近黑海岸的边界。更危险的是，有人在废墟中发现了被遗忘者的踪迹，这个消息让奥雷迪尔·阔叶感到非常不安。"}},faq={{q="巴斯兰的头发有什么用途？",a="这种草药被暗夜精灵治疗者用来治疗超出普通疾病范围的严重病症。具体来说，奥雷迪尔·阔叶会将它配制成一种治疗药剂，旨在救治一个精神正在衰竭、生命垂危的孩子。",al={"巴斯兰的头发有什么用","巴斯兰的头发用途","巴斯兰的头发使用"}},{q="巴斯兰的头发在哪里生长？",a="它只生长在巴斯兰鬼屋——一个位于灰谷北部、通往黑海岸的主路东侧的古老废墟定居点。",al={"哪里寻找巴斯兰的头发","巴斯兰的头发位置","巴斯兰的头发在哪里"}},{q="为什么被遗忘者对巴斯兰鬼屋感兴趣？",a="奥雷迪尔·阔叶只了解到有被遗忘者出现在巴斯兰鬼屋，并对此感到非常不安；他们在那里的目的从未被解释清楚。在灰谷的其他地方，暗夜精灵报告称有被遗忘者潜伏在他们的废墟和古墓中，他们担心这些人企图在森林中散布瘟疫。",al={"为什么亡灵在巴斯兰鬼屋","巴斯兰鬼屋里的被遗忘者","亡灵巴斯兰"}},{q="奥雷迪尔·阔叶是谁？",a="奥雷迪尔·阔叶是一位驻扎在灰谷西部迈斯特拉岗哨的草药师。他致力于研究当地植物，并调配药物来治疗旅行者和受伤的森林守卫者。",al={"奥雷迪尔·阔叶","谁需要巴斯兰的头发"}}},fx={b940f392={q="巴斯兰的头发是什么？",a="巴斯兰的头发是一种稀有而娇嫩的草药，生长在灰谷北部的巴斯兰鬼屋的古老废墟之中。这种植物在暗夜精灵草药师中非常有名，具有强大的恢复能力，既能治愈精神上的创伤，也能缓解身体上的病痛。",al={"巴斯兰的头发是什么","巴斯兰的头发草药"}}},fp="14,252,23.451.0,24.302.1,32.224.0,31.151.0,51.279.0,25.201.0"}
P.entries["item:battleboar-flank"] = {n="斗猪肋排",s="斗猪肋排是取自莫高雷刺鬃野猪人训练的凶猛斗猪身上的结实肉块。它们由纳拉其营地附近的年轻猎手们收集，既是铲除威胁的证明，也是牛头人部落的滋补食物。",h="斗猪肋排是取自莫高雷刺鬃野猪人训练的凶猛斗猪身上的结实肉块。它们由纳拉其营地附近的年轻猎手们收集，既是铲除威胁的证明，也是牛头人部落的滋补食物。",kw={"斗猪","斗猪肋排","刺刃峡谷","刺鬃","纳拉其营地","格鲁尔·鹰风","莫高雷","红云台地"},ang={["profession:Cooking"]="虽然这些为了战斗而饲养的野兽肉质粗糙且腥味较重，但如果将其慢火炖煮成营地共享的炖菜，也能提供大量浓郁、饱腹的肉食。",["race:Tauren"]="狩猎这些入侵的斗猪教会了年轻的牛头人：保卫家园与尊重并利用大地母亲的馈赠，这两项神圣职责是相辅相成的。"},sec={{t="来自刺鬃威胁的补给",b="潜伏在刺刃峡谷的刺鬃野猪人训练了凶猛的斗猪，以侵占牛头人的狩猎地。虽然这些充满侵略性的野兽对在纳拉其营地进行Coming of Age的年轻牛头人构成了直接威胁，但取之于自然的资源绝不会被浪费。格鲁尔·鹰风指示新手猎手在收获这些野兽的吻部时，也要收集它们的肋排。肋排肉质肥厚，可烹饪成供部落年轻人食用的浓汤，将野猪人的战争武器转化为部落赖以生存的营养来源。"}},faq={{q="斗猪肋排有什么用途？",a="斗猪肋排由纳拉其营地的年轻猎手在格鲁尔·鹰风的命令下收集。这些肉会被烹制成炖菜，喂养村里的牛头人幼崽，确保被击败的敌人也能为部落提供补给。",al={"斗猪肋排用途","什么是斗猪肋排","为何收集斗猪肉"}},{q="在哪里可以找到斗猪肋排？",a="它们是从徘徊在纳拉其营地以东、红云台地的刺刃峡谷附近的斗猪和刺鬃斗猪身上切割下来的。",al={"斗猪肋排来源","斗猪肋排掉落地点","斗猪肋排掉落者"}},{q="为什么斗猪要入侵牛头人的土地？",a="这些斗猪由刺鬃野猪人饲养和训练，生性凶残恶毒。随着刺鬃野猪人与牛头人之间关系的紧张，野猪人驱使这些训练有素的野兽进入传统的部落狩猎地，以骚扰这些新来者。",al={"斗猪为何袭击","野猪人 斗猪 莫高雷","刺刃峡谷斗猪"}}},fx={c29b6530={q="什么是斗猪肋排？",a="这是一种从莫高雷的红色平原和峡谷中游荡的斗猪身上获取的鲜美肉块。虽然这些凶猛的猪是被为了战争而非食用而繁育和训练的，但在猎物匮乏时，它们的肉足够充实，足以养活部落。",al={"什么是斗猪肋排","斗猪肋排信息","斗猪肉"}},["4a352cac"]={q="斗猪肋排从哪儿来？",a="这些肋排是从在刺刃峡谷附近潜行的斗猪和刺背斗猪身上切割下来的。这些生物被敌对的刺背野猪人饲养和训练得充满攻击性，将原本的野生猎物变成了凶猛的领地野兽。",al={"斗猪肋排来源","斗猪肋排从哪儿来","谁有斗猪肉"}},f9e62759={q="格鲁尔·鹰风为什么想要斗猪肋排？",a="格鲁尔·鹰风收集这些肋排是为了喂养纳拉其营地的部落年轻后辈。将这些肉烹饪成营养丰富的炖肉，确保了狩猎所得没有任何浪费，同时也惩罚了将这些极具攻击性的野兽赶进牛头人祖传猎场的刺背野猪人。",al={"为什么要收集斗猪肋排","为什么格鲁尔要肋排","谁要斗猪肋排"}}},fp="16,266,38.545.0,36.226.0,34.149.0,51.256.0"}
P.entries["item:battleboar-snout"] = {n="斗猪头",s="斗猪头是从莫高雷的刺鬃野猪人训练的侵略性野猪身上收获的。这些斗猪头由年轻的牛头人猎人收集，既是减少外来威胁的证明，也是纳拉其营地部落烹饪的丰盛食材。",h="斗猪头是从莫高雷的刺鬃野猪人训练的侵略性野猪身上收获的。这些斗猪头由年轻的牛头人猎人收集，既是减少外来威胁的证明，也是纳拉其营地部落烹饪的丰盛食材。",kw={"斗猪","斗猪头","刺刃峡谷","刺鬃","纳拉其营地","格鲁尔·鹰风","红云台地"},ang={["profession:Cooking"]="像猪头这样坚硬的部位需要用火慢炖，因此它们成为了部落篝火炖菜中的主料。",["race:Tauren"]="在获取肉的同时带走猪头是对大地母亲的平衡的尊重，既确保了侵略性的掠食者得到遏制，又为纳拉其营地的年轻人们提供了食物。"},sec={{t="战利品与补给",b="在红云台地的阴影下，刺鬃野猪人在刺刃峡谷内训练凶残的斗猪，以试探牛头人的狩猎场。当格鲁尔·鹰风派遣年轻的勇士们出击以反击这种侵扰时，斗猪头便成了击杀野兽的确凿证据。牛头人不仅不会浪费猎物的任何部位，还会将这些猪头与侧腹肉一起炖煮，准备出浓郁且营养丰富的炖菜，以供部落的孩子们食用。"}},faq={{q="斗猪头有什么用途？",a="格鲁尔·鹰风要求纳拉其营地的年轻猎人们收集它们以及侧腹肉。它们既是这些威胁性的野猪已被击杀的证明，也会被扔进烹饪锅中，为部落的年轻人制作炖菜。",al={"斗猪头的用途","为什么要保留猪头","格鲁尔如何处理猪头"}},{q="这些猪头从哪里来？",a="它们是从在红云台地边缘和东部的整个刺刃峡谷中发现的斗猪和刺鬃斗猪身上切割下来的。",al={"哪里可以找到斗猪","谁掉落猪头","斗猪位置"}},{q="为什么这些斗猪会侵犯牛头人的土地？",a="这些斗猪受到了敌对的刺鬃野猪人的训练，变得异常凶猛，正从刺刃峡谷向传统的部落狩猎场扩张。",al={"为什么野猪在攻击","野猪人饲养的野猪","刺刃峡谷的斗猪"}}},fx={a852a9b9={q="什么是斗猪头？",a="这是刺背野猪人在刺刃峡谷附近饲养和训练的斗猪的被切下的头部。格鲁尔·鹰风和纳拉其营地的牛头人将这些肉块与猪的肋排一起，视为可以炖给部落年轻人吃的丰盛食材，同时也作为他们的猎人正在猎杀这些入侵野兽的实物证明。",al={"斗猪头","什么是斗猪头","这是什么物品"}}},fp="16,258,23.445.0,36.227.0,32.149.0,51.180.0"}
P.entries["item:battleworn-axe"] = {n="破斧",s="破斧是侵入赤脊山的黑石兽人所携带的一种粗糙且布满缺口的武器。治安官马瑞斯在湖畔镇收集这些缴获的利刃，以此作为杀死威胁当地民众的入侵者的物证。",h="破斧是侵入赤脊山的黑石兽人所携带的一种粗糙且布满缺口的武器。治安官马瑞斯在湖畔镇收集这些缴获的利刃，以此作为杀死威胁当地民众的入侵者的物证。",kw={"破斧","黑石","湖畔镇","马瑞斯","兽人","赤脊山","石堡","武器"},ang={["faction:Alliance"]="每带回湖畔镇一把斧头，就意味着少了一个威胁赤脊山手无寸铁的平民的入侵者，特别是在暴风城的主力部队身处他处的情况下。",["profession:Blacksmithing"]="尽管边缘锯齿且刀刃缺损，但这些粗糙的铁制武器展示了黑石装备所特有的坚韧、厚重的锻造工艺。"},sec={{t="入侵者的战利品",b="这些沉重且带有缺口的斧头是那些从燃烧平原向南推进至赤脊山的黑石掠夺者的制式装备。对于治安官马瑞斯和湖畔镇处境艰难的城镇卫兵来说，收集这些武器有两个目的：一是为了确认又一个掠夺的兽人倒下了，二是为了收集实物证据，证明这些入侵的战团到底武装到了什么程度。"},{t="山中的威胁",b="黑石入侵者已经加固了石堡要塞，并在赤脊山东南部的区域建立了据点，有效地将镇民困在了湖畔镇。剥夺袭击者手中的破斧不仅直接削弱了该战团可用的武装，还能为联盟的通行清理道路。"}},faq={{q="什么是破斧？",a="破斧是黑石兽人在赤脊山携带的一种粗犷且磨损严重的近战武器。冒险者收集这些武器作为击杀入侵者的凭证。",al={"破斧信息","这些斧头是什么","黑石之斧"}},{q="湖畔镇里谁需要这些斧头？",a="湖畔镇城镇卫兵指挥官治安官马瑞斯需要这些斧头，以核实黑石威胁是否正从城镇领土上被积极击退。",al={"谁会收走破斧","破斧任务发布者","治安官马瑞斯的斧头"}},{q="这些斧头是从哪里来的？",a="它们是从整个赤脊山的黑石兽人身上缴获的，尤其是北部的石堡要塞周围以及东南部的兽人营地。",al={"哪里会掉落破斧","破斧刷取","哪些兽人拥有这些斧头"}},{q="兽人为什么会出现在赤脊山？",a="黑石氏族从燃烧平原穿过山口向南进军，占领了石堡要塞，并在赤脊山的北部和东部进行掠夺，以围困湖畔镇。",al={"为什么黑石兽人在赤脊山","石堡入侵","黑石威胁的原因"}}},fp="14,237,20.358.0,23.317.0,25.171.0,34.151.0,30.164.0,48.186.0"}
P.entries["item:berard-s-journal"] = {n="伯纳德的日记",s="《伯纳德的日记》是药剂师伯纳德在成为大法师阿鲁高的诅咒的受害者之前所撰写的一系列研究笔记。这本书被遗弃在焚木村，记录了伯纳德对一种曾经灭绝洛丹米尔湖水生生物的古老瘟疫的研究，这使得它对皇家药剂师学会而言极具价值。",h="《伯纳德的日记》是药剂师伯纳德在成为大法师阿鲁高的诅咒的受害者之前所撰写的一系列研究笔记。这本书被遗弃在焚木村，记录了伯纳德对一种曾经灭绝洛丹米尔湖水生生物的古老瘟疫的研究，这使得它对皇家药剂师学会而言极具价值。",kw={"药剂师伯纳德","药剂师伦弗利尔","伯纳德的日记","洛丹米尔湖","大药剂师法拉尼尔","焚木村","皇家药剂师学会","银松森林"},ang={["faction:Horde"]="冒险进入焚木村找回失落的研究，有助于被遗忘者在银松森林建立稳固的防御据点。",["race:Undead"]="每一丝剧毒知识都有助于皇家药剂师学会获得一种能够保卫被遗忘者，抵御天灾军团和活物敌人的武器。"},sec={{t="洛丹米尔湖失落的研究",b="在大法师阿鲁高在银松森林释放他的暗影魔法之前，药剂师伯纳德被认为是皇家药剂师学会最有前途的成员之一。他驻扎在焚木村，专注于研究一种在几个世纪前消灭了洛丹米尔湖所有水生生物的古老致命枯萎病。当阿鲁高的诅咒笼罩这个定居点时，伯纳德的精神崩溃了，使他变成了又一个毫无思想的奴仆。他详细的实地考察笔记留在了焚木村旅店他住所的书架上。"},{t="The New Plague的燃料",b="虽然伯纳德本人对学会来说已经失去了，但他的研究完好无损地保存了下来。瑟伯切尔的药剂师伦弗利尔认识到了这本日记的战略价值，并指引被遗忘者特工进入那个充满敌意的村庄将其取回。这些关于古代湖泊毒素的收集笔记为大药剂师法拉尼尔和位于Apothecarium的学会提供了关键的基础工作，成为调配被遗忘者自身The New Plague的重要基石。"}},faq={{q="药剂师伯纳德是谁？",a="药剂师伯纳德是生活在焚木村的皇家药剂师学会的一名天才成员。当大法师阿鲁高向该地区施加诅咒时，他正在进行关于历史毒素的重要研究，这摧毁了伯纳德的精神并奴役了他。",al={"伯纳德是谁","伯纳德背景故事","药剂师伯纳德"}},{q="在哪里可以找到《伯纳德的日记》？",a="这本日记放在焚木村旅店楼上伯纳德旧书房的一个书架上，位于银松森林南部深处。",al={"寻找《伯纳德的日记》","日记位置","这本书在哪里"}},{q="日记中记录了什么研究？",a="这本日记详细记录了伯纳德对一种在远古时期彻底消灭了洛丹米尔湖所有水生生物的原始传染病的发现。皇家药剂师学会希望将这些毒性特征改良为他们自己的化学武器。",al={"日记里有什么","伯纳德的研究","日记内容"}},{q="药剂师伦弗利尔为什么想要这本日记？",a="伦弗利尔试图在任何有用的科学资产被摧毁或永远遗失之前将其收回。伯纳德对洛丹米尔湖传染病的独特见解，为大药剂师法拉尼尔在Undercity开发被遗忘者的The New Plague提供了所需的关键成分。",al={"为什么伦弗利尔想要它","伦弗利尔的日记任务"}}},fx={b3a0b77c={q="伯纳德的日记是什么？",a="伯纳德的日记是由皇家药剂师学会的前成员药剂师伯纳德编写的一本科学研究笔记。其中包含了关于很久以前消灭了洛丹米尔湖中所有水生生物的某种古代传染病的详细发现，被遗忘者希望研究它以用于自己的炼金术。",al={"伯纳德的日记","伯纳德的日记是什么"}},["719e9fe0"]={q="伯纳德的日记从哪儿来，是谁做的？",a="这本日记是由药剂师伯纳德在被大法师阿鲁高的暗影魔法控制而发疯之前撰写的。他把研究资料保存在焚木村的旅店里，在他变成没有思想的仆从后，这本大部头被遗留在了书架上。",al={"伯纳德的日记从哪儿来","谁写了伯纳德的日记","伯纳德的日记来源"}}},fp="16,331,31.542.0,23.440.1,26.248.0,32.154.0,41.247.0,47.272.0"}
P.entries["item:bernice-s-necklace"] = {n="波尼斯的项链",s="波尼斯的项链是艾尔文森林斯通菲尔德农场的波尼斯·斯通菲尔德姑妈所珍视的传家宝。最初，她已故的丈夫在服兵役期间将其作为护身符佩戴。这件饰品在法戈第矿洞附近丢失，被一只投机取巧的狗头人夺走。",h="波尼斯的项链是艾尔文森林斯通菲尔德农场的波尼斯·斯通菲尔德姑妈所珍视的传家宝。最初，她已故的丈夫在服兵役期间将其作为护身符佩戴。这件饰品在法戈第矿洞附近丢失，被一只投机取巧的狗头人夺走。",kw={"波尼斯姑妈","波尼斯的项链","比利·马科伦","法戈第矿洞","goldtooth","幸运护身符","斯通菲尔德"},ang={["faction:Alliance"]="这条项链无声地提醒着人们，暴风城长期的军事行动给艾尔文森林里普通的农户家庭带来了沉重的代价。"},sec={{t="一名士兵丢失的护身符",b="虽然在当地被称为波尼斯的项链，但这件物品最初属于波尼斯·斯通菲尔德姑妈已故的丈夫。作为暴风城军队的一名老兵，他曾带着这个护身符上战场，视其为好运的象征。据波尼斯所说，他唯一一次遭遇不幸是在他最后一次出征时——那是他唯一一次忘记带上这枚幸运项链的远征。在他去世后，这件纪念品成为了波尼斯在斯通菲尔德农场最珍视的财产之一。"},{t="被拾荒者偷走",b="年轻的比利·马科伦在法戈第矿洞附近玩耍时弄丢了这个闪亮的饰物，这件传家宝因此下落不明。那个闪光点引起了潜伏在矿洞里的著名狗头人Goldtooth的注意。和其他同类一样，Goldtooth喜欢闪亮而值钱的小玩意，他把项链藏在了自己地下的拾荒堆里，直到有人能帮这位悲伤的遗孀寻回它。"}},faq={{q="这条项链最初是谁的？",a="这条项链最初属于波尼斯·斯通菲尔德姑妈已故的丈夫，他在为暴风城服役时将它作为护身符佩戴。",al={"项链的主人","波尼斯项链主人","丈夫的项链"}},{q="项链是怎么落到狗头人手里的？",a="比利·马科伦说他看到一只长着大金牙的狗头人在法戈第矿洞附近捡走了项链并带走了它。波尼斯姑妈希望能找回它。",al={"项链是如何丢失的","为什么goldtooth会有它","谁拿走了项链"}},{q="为什么这条项链对波尼斯姑妈如此重要？",a="这是她对他已故丈夫的珍贵回忆。波尼斯悲伤地提到，他一直认为它在战场上保护着他，而他唯一一次在战争中倒下，就是他意外把项链落下的那一天。",al={"为什么波尼斯想要它","波尼斯丈夫的故事","项链有魔法吗"}},{q="Goldtooth是谁？",a="Goldtooth是一个著名的狗头人拾荒者，在艾尔文森林的法戈第矿洞内筑巢。他以收集闪亮饰品而闻名，在项链在附近掉落后，他据为己有。",al={"goldtooth是什么","goldtooth的背景故事","谁有项链"}}},fp="18,85,22.376.0,20.291.1,35.138.0,45.154.0,51.165.0,17.181.0"}
P.entries["item:besseleth-s-fang"] = {n="贝瑟莱斯的牙齿",s="贝瑟莱斯的牙齿是从希塞尔山谷的巨型蜘蛛贝瑟莱斯身上收获的巨大毒牙。它被作为她死亡的证明而携带，代表着消除了潜伏在石爪山脉小径上的致命威胁。",h="贝瑟莱斯的牙齿是从希塞尔山谷的巨型蜘蛛贝瑟莱斯身上收获的巨大毒牙。它被作为她死亡的证明而携带，代表着消除了潜伏在石爪山脉小径上的致命威胁。",kw={"恐蛛症","贝瑟莱斯","贝瑟莱斯的牙齿","马格兰","希塞尔山谷","石爪山脉","烈日石居","蛛网小径"},ang={["class:Hunter"]="收获这颗顶级蛛母两英尺长的毒牙，是猎人追踪和战斗能力的有力证明。",["faction:Horde"]="清理峡谷蜘蛛有助于保护连接贫瘠之地边界与烈日石居之间崎岖的山路。"},sec={{t="峡谷潜行者的战利品",b="希塞尔山谷长期以来一直深受具有攻击性的蜘蛛困扰，但没有谁比贝瑟莱斯更让旅行者感到恐惧了。她长到了巨大的体型，她和她的后代将峡谷变成了在夜间穿过蛛网小径的漫游者的死亡陷阱。这颗牙齿长近两英尺，滴着强效毒液，是这位蛛母被杀的明确标志。呈上这一可怕的战利品，让那些遭受过她毒液袭击的当地守卫者们感到一丝宽慰。"}},faq={{q="贝瑟莱斯的牙齿有什么用？",a="这颗牙齿是蜘蛛蛛母贝瑟莱斯已被杀死的实物证明。烈日石居的马格兰在亲身经历过一次几乎致命的毒牙袭击后，对这只野兽发出了悬赏，并奖励任何将这件战利品带给他的人。",al={"贝瑟莱斯的牙齿用途","谁想要贝瑟莱斯的牙齿","牙齿上交"}},{q="这颗牙齿来自哪里？",a="这颗牙齿直接从贝瑟莱斯身上收获，她是一只居住在希塞尔山谷的巨型掠食蜘蛛，位于石爪山脉狂风峭壁以南的主路以西。",al={"如何获得贝瑟莱斯的牙齿","贝瑟莱斯在哪里","贝瑟莱斯位置"}},{q="为什么马格兰希望贝瑟莱斯死？",a="贝瑟莱斯和她的后代经常捕食沿着道路前往烈日石居的旅行者，尤其是在夜幕掩护下。马格兰曾亲自遭到她毒牙的伏击并受伤，促使他发布了一项悬赏以确保道路安全。",al={"为什么要杀死贝瑟莱斯","马格兰蜘蛛悬赏","为什么悬赏贝瑟莱斯"}},{q="是谁发布了这颗牙齿的悬赏？",a="该悬赏由马格兰授权，并张贴在位于狂风峭壁岔路以南主路沿线的悬赏告示板上，警告过往的旅行者注意希塞尔山谷的危险。",al={"石爪山脉蜘蛛悬赏公告","恐蛛症任务发放者"}}},fx={f0d9a9a7={q="贝瑟莱斯的牙齿是什么？",a="贝瑟莱斯的牙齿是从掠食性蜘蛛贝瑟莱斯身上取下的一颗两英尺长的巨大牙齿。它和它的巢穴潜伏在希塞尔山谷，在夜间捕食蛛网小径上的旅行者。这颗牙齿是那个在石爪山脉的小径上恐吓行人的可怕蛛形纲生物终于被击杀的无可辩驳的实物证明。",al={"贝瑟莱斯的牙齿是什么","贝瑟莱斯的牙齿"}}},fp="16,228,28.512.0,34.256.0,31.185.0,48.259.0,35.196.0"}
P.entries["item:bethor-s-scroll"] = {n="比索的卷轴",s="比索的卷轴包含着由比索·埃斯沙德亲手书写的魔法咒语，旨在对抗他昔日的同事Thule Ravenclaw所施展的黑暗巫术。这张卷轴是为了协助药剂师伦弗利尔酿制一种防护药水而创作的，对于在守卫芬里斯岛的Scourge死灵法术中存活下来至关重要。",h="比索的卷轴包含着由比索·埃斯沙德亲手书写的魔法咒语，旨在对抗他昔日的同事Thule...",kw={"药剂师伦弗利尔","比索·埃斯沙德","比索的卷轴","芬里斯岛","rot hide","银松森林","瑟伯切尔","thule ravenclaw"},ang={["class:Mage"]="这张卷轴展现了肯瑞托破碎的过去，揭示了如何将对同僚招牌法术的深刻了解转化为一种有效的应对措施。",["race:Undead"]="被遗忘者施法者和药剂师们通过这份羊皮纸结合了他们独特的才能，将达拉然古老的奥术训练与瑟伯切尔新的炼金工艺融合在了一起。"},sec={{t="对抗死灵法师",b="卷轴中蕴含着强大的奥术公式，它并非作为进攻性武器，而是作为皇家药剂师学会的酿造指南。这张卷轴被交给瑟伯切尔的药剂师伦弗利尔，提供了合成恢复药水所需的精确反制咒语，这些药水能够驱散Thule在他堡垒周围编织的削弱性妖术。"},{t="同事的背叛",b="在检查了从Rot Hide豺狼人身上回收的受污染脓液后，比索·埃斯沙德认出了这是Thule Ravenclaw的手笔。Thule曾是肯瑞托一位前途无量的年轻法师，在Scourge崛起时，他背叛了自己的同胞，转而效忠于Lich King。在得知Thule还活着，并且从芬里斯岛指挥Rot Hide对银松森林发动攻击后，比索利用他对昔日同事法术的深刻了解，撰写了这张卷轴。"}},faq={{q="比索的卷轴上写了什么？",a="卷轴详细记录了由比索·埃斯沙德构思的专业奥术咒语。由于曾与Thule Ravenclaw一同学习，比索了解这位死灵法师偏好的法术，并刻下了酿制炼金反制药水所需的精确公式。",al={"卷轴上写了什么","比索的卷轴的内容","卷轴上有什么"}},{q="谁会收到这张卷轴？",a="这张卷轴必须交给驻扎在银松森林瑟伯切尔的药剂师伦弗利尔。伦弗利尔利用其中蕴含的魔法来制造一种防护药水。",al={"我要把卷轴交给谁","比索的卷轴交付","谁会得到卷轴"}},{q="为什么药剂师伦弗利尔需要药水用的魔法咒语？",a="药剂师伦弗利尔擅长的是炼金术而非传统的巫术，他也承认自己很少将这种显性的力量融入他的药剂中。然而，普通的抗毒剂无法穿透保护Thule的Scourge诅咒，因此需要比索的奥术公式才能使药剂生效。",al={"为什么药剂师需要咒语","魔法药水伦弗利尔"}},{q="在投靠Scourge之前，Thule Ravenclaw是什么人？",a="在第三次战争之前，Thule是一位前途无量的年轻人类法师，也是比索·埃斯沙德的同僚。当Lich King集结他的亡灵大军时，Thule抛弃了他的施法者同胞，向Scourge宣誓效忠。",al={"谁是thule ravenclaw","thule背景故事","thule和比索"}}},fx={["31160c67"]={q="比索的卷轴从哪儿来，是谁做的？",a="这份卷轴是由幽暗城魔法区中为被遗忘者效力的亡灵法师比索·埃斯沙德撰写的。通过识别从烂皮豺狼人身上找到的邪恶脓液上的魔法印记，比索意识到他以前的同事图勒·鸦爪还活着，并且已经投靠了天灾军团。基于对比索·鸦爪奥术技巧的深刻了解，比索将反咒语抄写在这张羊皮纸上，以帮助击败他那堕落的前同事。",al={"谁写了比索的卷轴","谁制作了比索的卷轴","比索的卷轴从哪儿来"}},["64d2974c"]={q="为什么需要比索的卷轴？",a="药剂师伦弗利尔需要卷轴上铭刻的魔法咒语来酿制一种防御性的解毒剂。图勒·鸦爪在他位于芬里斯岛的要塞中施展强大且令人虚弱的诅咒。通过将比索的奥术配方注入炼金药剂，皇家药剂师学会可以制造出一种专门的药水，让你在对抗图勒时免受其邪恶巫术的侵害。",al={"为什么想要比索的卷轴","比索的卷轴为什么重要","比索的卷轴有什么用"}}},fp="15,290,26.368.1,22.461.1,35.255.0,25.175.0,69.286.0,54.225.0"}
P.entries["item:bingles-blastencapper"] = {n="宾格斯的气压炸弹",s="宾格斯的气压炸弹是由侏儒飞行员宾格斯·雷管设计的一种特殊爆炸装置。当他的旋翼机坠入洛克湖时，这件装备随之遗失，并被当地的穴居人偷走，这危及了宾格斯支持收复诺莫瑞根的计划。",h="宾格斯的气压炸弹是由侏儒飞行员宾格斯·雷管设计的一种特殊爆炸装置。当他的旋翼机坠入洛克湖时，这件装备随之遗失，并被当地的穴居人偷走，这危及了宾格斯支持收复诺莫瑞根的计划。",kw={"宾格斯","气压炸弹","雷管","爆炸物","诺莫瑞根","旋翼机","洛克莫丹","穴居人"},ang={["profession:Engineering"]="气压炸弹展现了典型的侏儒工程学风格：结构复杂，极易爆炸，且从高空投下时具有毁灭性的威力。",["race:Gnome"]="在收复诺莫瑞根的斗争中，每一件工具和弹药都至关重要，回收宾格斯的爆炸物可以确保侏儒的空中奇思妙想能够回击穴居人入侵者。"},sec={{t="一项危险的发明",b="宾格斯的气压炸弹代表了飞行员宾格斯·雷管个人军械的巅峰之作。这种炸弹旨在对占领诺莫瑞根的穴居人和麻风侏儒进行决定性的空中打击，但在机械故障导致他的旋翼机坠入洛克湖时，它正装载在机上。虽然宾格斯幸存了下来，但盘踞在湖泊北岸岛屿上的穴居人掠夺了他的残骸，并将这件危险的武器拖回了他们的营地。"},{t="为诺莫瑞根提供空中支援",b="对宾格斯来说，气压炸弹不仅仅是简单的打捞品。流亡的侏儒们正在积极准备夺回他们那充满放射性的家园，而宾格斯认为他的旋翼机和标志性弹药是即将到来的空中突袭中至关重要的组成部分。回收这些军械不仅可以防止洛克莫丹本土的穴居人意外引发灾难，还能为侏儒抵抗军保留一件宝贵的武器。"}},faq={{q="什么是宾格斯的气压炸弹？",a="这是由宾格斯·雷管发明的一种特殊且威力强大的爆炸物，旨在用于空中打击，以协助侏儒对抗占领诺莫瑞根的穴居人和麻风侏儒。",al={"什么是气压炸弹","气压炸弹","宾格斯的爆炸物"}},{q="气压炸弹是如何落入洛克湖的？",a="宾格斯的旋翼机坠入了洛克湖中。在他还没来得及保护好自己的装备之前，从附近岛屿涌出的穴居人就洗劫了他坠毁的飞行器，并将他的工具连同爆炸装置一起抢走了。",al={"为什么它在洛克湖","宾格斯是怎么弄丢的","坠机"}},{q="谁现在持有气压炸弹？",a="居住在洛克湖北岸岛屿上的穴居人从坠机现场掠夺了该装置，并将其守卫在他们简陋的营地中。",al={"谁偷走了气压炸弹","谁持有它","穴居人"}},{q="为什么宾格斯需要找回气压炸弹？",a="没有了他的工具和标志性弹药，宾格斯就无法修理他的旋翼机，也无法发起空中轰炸突袭来支持收复诺莫瑞根的行动。",al={"为什么需要找回","为什么气压炸弹很重要","为了诺莫瑞根"}}},fp="22,254,20.451.0,26.421.0,31.197.0,45.217.0,36.140.0,49.157.0"}
P.entries["item:bingles-hammer"] = {n="宾格斯的榔头",s="宾格斯的榔头是属于宾格斯·雷管的一件工程学工具，他是一位困在洛克莫丹的古怪侏儒飞行员。在飞行器坠入洛克湖后，敌对的石腭怪拾走了他的榔头以及其他专用装备。宾格斯需要找回它，以便修理飞行器并协助解放诺莫瑞根的战争。",h="宾格斯的榔头是属于宾格斯·雷管的一件工程学工具，他是一位困在洛克莫丹的古怪侏儒飞行员。在飞行器坠入洛克湖后，敌对的石腭怪拾走了他的榔头以及其他专用装备。宾格斯需要找回它，以便修理飞行器并协助解放诺莫瑞根的战争。",kw={"宾格斯","雷管","诺莫瑞根","榔头","洛克莫丹","工具桶","石腭怪"},ang={["profession:Engineering"]="任何工匠都知道，一把精良的侏儒手工制作的榔头是无可替代的，尤其是在荒野中重建一架实验性直升机的时候。",["race:Gnome"]="每找回一件工具，诺莫瑞根的空中攻势就离对那些窃取你祖居之地的入侵者发动进攻更近了一步。"},sec={{t="一名受困飞行员的工具包",b="当飞行员宾格斯·雷管坠入洛克湖的湖水中时，幸存只是他麻烦的开始。居住在淡水岛屿上的石腭怪很快就袭击了坠机现场，掠夺了他的专用工具包和高效炸药。被窃走的装备中就包括了他的榔头，这是修理受损机身和校准直升机机械装置不可或缺的工具。失去了这件关键工具以及其他装备，宾格斯只能彻底搁浅，无法为努力收复诺莫瑞根的侏儒解放军提供空中支援。"}},faq={{q="哪里可以找到宾格斯的榔头？",a="这把榔头位于散落在洛克湖北部岛屿上、被石腭怪占据的宾格斯的工具桶中。",al={"榔头位置","宾格斯的榔头在哪里","如何找到榔头"}},{q="这把榔头属于谁？",a="它属于宾格斯·雷管，一位充满冒险精神的侏儒工程师兼飞行员，他在洛克莫丹的岸边坠毁了他的飞行器。",al={"榔头的主人是谁","宾格斯的榔头主人"}},{q="为什么这件工具对宾格斯如此重要？",a="宾格斯需要他全套的工具来重建他坠毁的直升机，他打算驾驶它投入战斗，以支援针对占领诺莫瑞根的石腭怪和麻风侏儒的空中突袭。",al={"为什么需要榔头","宾格斯的榔头用途"}},{q="是谁偷走了宾格斯的榔头？",a="居住在湖中岛屿上的当地石腭怪伏击了坠机现场，并抢走了飞行员的工具桶和他定制的雷管炸药。",al={"谁拿走了榔头","石腭怪窃贼"}}},fp="15,353,28.599.0,35.147.0,31.139.0,41.198.0,26.145.0"}
P.entries["item:bingles-screwdriver"] = {n="宾格斯的螺丝起子",s="宾格斯的螺丝起子是宾格斯·雷管的关键工程工具，他是一位侏儒飞行员，驾驶着旋翼机坠毁在洛克莫丹的水域中。坠毁后，当地的穴居人掠夺了残骸，将宾格斯的工具桶和专业装备散落在洛克湖的北侧岛屿上。",h="宾格斯的螺丝起子是宾格斯·雷管的关键工程工具，他是一位侏儒飞行员，驾驶着旋翼机坠毁在洛克莫丹的水域中。坠毁后，当地的穴居人掠夺了残骸，将宾格斯的工具桶和专业装备散落在洛克湖的北侧岛屿上。",kw={"宾格斯","雷管","旋翼机","洛克莫丹","螺丝起子","工具桶","穴居人"},ang={["profession:Engineering"]="任何修理工都知道，一把精密校准的螺丝起子对于复杂的旋翼机转子和精细的触发装置是不可或缺的。",["race:Gnome"]="每找回一件工具，宾格斯就离重建他的飞行器、向将你们的族人从诺莫瑞根赶走的穴居人和麻风侏儒发动空中战争更近了一步。"},sec={{t="飞行员的重要工具包",b="当宾格斯·雷管坠入洛克湖时，他失去的不仅仅是他的飞行机器——他还失去了修理机器所需的专业设备。在散落的装备中，就有他那把值得信赖的螺丝起子，它被装在几个工具桶里，随后被居住在附近岛屿上的贪婪穴居人抢走了。对于一名困在荒野中的工程师来说，像这样精密的调节工具是不可替代的，尤其是在组装精密的旋翼机机械装置或处理易爆武器时。"},{t="收复计划的准备工作",b="宾格斯不仅仅是一名休闲飞行员；他还肩负着收复陷落的诺莫瑞根，将其从穴居人和麻风侏儒手中解放出来的伟大事业。他的任务是结合飞行力学与他的雷管爆破弹，对地下的威胁发起空中突击。找回这把螺丝起子，连同他的扳手和锤子，对于重新组装他的旋翼机并维持侏儒的空中反击至关重要。"}},faq={{q="宾格斯的螺丝起子在哪里能找到？",a="它可以在散落在洛克湖北部岛屿上的宾格斯的工具桶中找到，那里是当地穴居人在坠机后拖走飞行员残骸的地方。",al={"螺丝起子位置","寻找宾格斯的螺丝起子","螺丝起子在哪里"}},{q="为什么这把螺丝起子对宾格斯如此重要？",a="宾格斯需要他的核心工程工具来重建他坠毁的旋翼机，并为收复诺莫瑞根的战役准备他专业的爆炸物。",al={"为什么宾格斯需要它","它的用途"}},{q="是谁偷走了螺丝起子？",a="居住在洛克湖岛屿上的穴居人在宾格斯迫降后伏击了他，抢走了他的工具桶和雷管爆破弹。",al={"谁拿走了工具","谁偷了宾格斯的工具"}},{q="宾格斯在坠机中还丢失了哪些其他工具？",a="除了螺丝起子，宾格斯还丢失了他的扳手、锤子以及他那批不稳定的雷管爆破弹。",al={"宾格斯的其它工具","还有什么丢失了"}}},fx={f72526b7={q="宾格斯的螺丝起子是什么？",a="宾格斯的螺丝起子是属于宾格斯·雷管的工程工具，他是一位在洛克莫丹遇难的侏儒飞行员。这和他的扳手与锤子一样，是他随身携带在旋翼机上，用于维护他的飞行机器和为侏儒抵抗军制造军火的必要工具之一。",al={"宾格斯的螺丝起子是什么","宾格斯的螺丝起子信息","关于宾格斯的螺丝起子"}}},fp="20,310,19.507.0,29.476.0,36.162.0,47.151.0,45.148.0,47.130.0"}
P.entries["item:bingles-wrench"] = {n="宾格斯的扳手",s="宾格斯的扳手是一件极其重要的侏儒工程学装备，属于飞行员宾格斯·雷管。当宾格斯的飞行机器坠入洛克湖时，这件装备随之丢失，并被当地的石腭怪连同他的其他工具箱一起搜刮走了。",h="宾格斯的扳手是一件极其重要的侏儒工程学装备，属于飞行员宾格斯·雷管。当宾格斯的飞行机器坠入洛克湖时，这件装备随之丢失，并被当地的石腭怪连同他的其他工具箱一起搜刮走了。",kw={"宾格斯","雷管","旋翼机","洛克莫丹","工具桶","石腭怪","扳手"},ang={["profession:Engineering"]="任何技师都知道，没有趁手扳手的工程师寸步难行，尤其是在面对贪婪的石腭怪时。",["race:Gnome"]="每找回一件工具，侏儒抵抗军就离夺回诺莫瑞根辐射大厅的胜利更近了一步。"},sec={{t="岛屿打捞",b="宾格斯·雷管驾驶的旋翼机坠入洛克湖平静的湖水后，他的生存成了一场苦难。居住在北部小岛上的石腭怪洗劫了坠机地点，掠夺了他的专业补给，并将他的工具散落在各个营地的桶里。宾格斯的扳手是除了他那高威力的“雷管式”爆炸装置外，急需的三件关键手动工具之一。没有它，宾格斯就无法修复坠毁的旋翼机，从而延误了他计划中的空中攻势，无法支援那些为收复诺莫瑞根而战的流亡侏儒。"}},faq={{q="这把扳手的主人是谁？",a="这把扳手属于宾格斯·雷管，一位古怪的侏儒飞行员，他的旋翼机在洛克莫丹的洛克湖中坠毁了。",al={"宾格斯是谁","宾格斯所有者","扳手所有者"}},{q="为什么扳手对宾格斯如此重要？",a="宾格斯需要他的专业工具来修理受损的飞行机器并组装他的爆炸载荷，这样他才能对占据诺莫瑞根的石腭怪和麻风侏儒发动空中突袭。",al={"为什么宾格斯需要扳手","扳手用途","扳手是用来做什么的"}},{q="坠机后扳手去哪了？",a="这把扳手被当地的石腭怪捡走，并藏在散布在洛克湖北部岛屿上的宾格斯被盗工具桶中之一里。",al={"宾格斯的扳手在哪里","扳手位置","寻找宾格斯的扳手"}},{q="除了扳手，还有什么被偷了？",a="除了扳手，石腭怪还偷走了宾格斯的螺丝起子、宾格斯的榔头，以及他的实验性“雷管式”爆炸装置。",al={"其他补给","丢失的工具","石腭怪还拿走了什么"}}},fp="15,244,22.570.0,31.125.0,42.195.0,44.145.0,43.147.0"}
P.entries["item:black-claw-stout"] = {n="黑爪烈酒",s="黑爪烈酒是由黑爪加尔德斯在暴风城的街道下精心准备的一种特殊饮品。它是专门为一位爱管闲事的贵族调制而成的，以普通酒馆饮料为掩护进行投送。",h="黑爪烈酒是由黑爪加尔德斯在暴风城的街道下精心准备的一种特殊饮品。它是专门为一位爱管闲事的贵族调制而成的，以普通酒馆饮料为掩护进行投送。",kw={"黑爪烈酒","请愿大厅","威肖克勋爵","毒药","slaughtered lamb","stormwind keep","加尔德斯"},ang={["class:Warlock"]="这种酿造物是为暴风城隐藏的术士集会所执行的一项任务，因为一位爱管闲事的贵族想要关掉他们位于Slaughtered Lamb下方的避难所。",["faction:Alliance"]="将这种酒带入暴风城要塞，表明了位于Slaughtered Lamb下方的术士们的行动距离首都的贵族们有多近。"},sec={{t="一剂毒药",b="在Slaughtered Lamb阴暗的酒室后方，术士和阴谋家们就潜伏在暴风城卫兵的眼皮底下。当一位名叫威肖克勋爵的贵族反复威胁要关闭他们的地下行动，却又虚伪地在楼上拖欠酒账时，黑爪加尔德斯决定算一算这笔账。黑爪烈酒是专门为利用威肖克对烈酒的嗜好而制作的，里面暗藏着足以致命的毒药，却伪装成普通的酒馆饮品。"},{t="悄无声息的刺杀",b="这桶烈酒被直接送进了暴风城要塞的请愿大厅，利用了威肖克那傲慢自大的性格和对饮酒的渴求。这位贵族误以为这是侍从殷勤奉上的饮品，便欣然当场饮下。毒药几乎立即生效，在皇家法院的眼皮底下让这位教团最顽固、最令人讨厌的政治批评者永远闭了嘴。"}},faq={{q="什么是黑爪烈酒？",a="这是黑爪加尔德斯在暴风城Mage Quarter中Slaughtered Lamb下方的墓穴里调制的一种特殊酿造物，目标是威肖克勋爵。",al={"这种饮料是什么","黑爪烈酒背景故事","毒酒"}},{q="这种烈酒的目标是谁？",a="目标是威肖克勋爵，一位徘徊在请愿大厅里的傲慢贵族，他一边赊账喝酒，一边却花时间四处奔走，企图关闭这个术士避难所。",al={"谁喝了它","谁死于黑爪烈酒","威肖克目标"}},{q="谁酿造了这种酒？",a="它是由黑爪加尔德斯酿造的，这是一位在Slaughtered Lamb下方的地穴中活动的阴险人物。",al={"黑爪烈酒的制造者","谁制作了这个","加尔德斯的酿造物"}},{q="为什么要向威肖克勋爵提供这种烈酒？",a="加尔德斯将这桶烈酒送到请愿大厅交给威肖克勋爵，并要求信使去看看这位贵族喜不喜欢他的特殊酿造。",al={"威肖克会死吗","黑爪烈酒的效果"}}},fx={a6b6f1b7={q="扎德斯为什么要你把黑爪烈酒送给威肖克勋爵？",a="威肖克勋爵是一位虚伪的贵族，他整天游说关闭“屠宰场”，却在晚上跑到楼上喝酒并拖欠酒馆账单。为了让他彻底闭嘴，扎德斯调制了这种致命的特制酒，利用威肖克对酒精的嗜好，假借提供清凉饮料的名义将其除掉。",al={"为什么要运送黑爪烈酒","为什么给威肖克黑爪烈酒","扎德斯为什么要给威肖克烈酒"}}},fp="16,134,15.367.1,19.354.1,25.143.0,31.151.0,21.85.0,38.128.1"}
P.entries["item:black-feather-quill"] = {n="黑色羽毛",s="黑色羽毛是一件神圣的暗夜精灵圣物，被利爪德鲁伊用于他们的冬眠与苏醒仪式。它存放在班奈希尔兽穴中的一个专属宝箱里，是安全地从翡翠梦境中唤回沉睡德鲁伊所必需的几件关键聚能物之一。",h="黑色羽毛是一件神圣的暗夜精灵圣物，被利爪德鲁伊用于他们的冬眠与苏醒仪式。它存放在班奈希尔兽穴中的一个专属宝箱里，是安全地从翡翠梦境中唤回沉睡德鲁伊所必需的几件关键聚能物之一。",kw={"阿斯瑞达斯·熊皮","班奈希尔兽穴","黑色羽毛","黑色羽毛宝箱","多兰纳尔","利爪德鲁伊","苏醒圣物"},ang={["class:Druid"]="对于德鲁伊来说，这根羽毛代表了神圣的工具，在他们的灵魂与翡翠梦境进行交流时，将利爪的修行者与清醒世界联系在一起。",["race:NightElf"]="暗夜精灵将蓟皮熊怪对班奈希尔圣物宝箱的亵渎，视为泰达希尔受到的腐蚀不断加剧的又一个痛苦提醒。"},sec={{t="苏醒之器",b="暗夜精灵德鲁伊教义依赖于深度调和的神圣物品，以便在清醒世界与翡翠梦境之间的界限中穿行。黑色羽毛，连同鸦爪神符、天蓝宝石和筑巢符文，构成了打破利爪德鲁伊微妙冬眠状态所需的核心仪式物品组合。若没有这些聚能物，沉睡的德鲁伊就有可能永远被困在翡翠梦境中，无法回到他们的清醒躯体。"},{t="班奈希尔的威胁",b="当受到腐蚀的蓟皮熊怪侵占了班奈希尔兽穴时，存放这些宝物的神圣宝箱陷入了危险之中。这些圣物被遗弃在蜿蜒的深处无人看管，必须在多兰纳尔的阿斯瑞达斯·熊皮下令后迅速收回，以免被困的德鲁伊永远迷失在翡翠梦境中。"}},faq={{q="黑色羽毛有什么用途？",a="这根羽毛是四件苏醒圣物之一，对于安全地唤醒在翡翠梦境中进行仪式性冬眠的利爪德鲁伊来说是必不可少的。",al={"黑色羽毛用途","为什么要黑色羽毛","羽毛的作用"}},{q="黑色羽毛存放在哪里？",a="它存放在黑色羽毛宝箱中，该宝箱位于泰达希尔中部的班奈希尔兽穴深处。",al={"黑色羽毛位置","黑色羽毛宝箱在哪里","羽毛位置"}},{q="为什么德鲁伊没有羽毛和其他圣物就无法醒来？",a="德鲁伊冬眠涉及在微妙的魔法影响下进入翡翠梦境。解除那种沉睡法术需要特定的神圣聚能物；没有它们，沉睡的灵魂就无法准确地导航回到其物理躯体。",al={"德鲁伊为何需要圣物才能醒来","德鲁伊能自行醒来吗"}},{q="谁在寻找黑色羽毛？",a="多兰纳尔的阿斯瑞达斯·熊皮指示冒险者回收这根羽毛以及其他苏醒圣物，以拯救处于危险之中的德鲁伊。",al={"谁需要羽毛","黑色羽毛任务发布者"}}},fx={["8b872c36"]={q="黑色羽毛是什么？",a="黑色羽毛是泰达希尔班奈希尔兽穴中的暗夜精灵猛禽德鲁伊所保存的四件神圣觉醒圣物之一。它被存放在一个专门的箱子里，是一种必要的仪式组件，用于平静地唤醒沉睡在翡翠梦境中的德鲁伊。",al={"黑色羽毛是什么","黑色羽毛物品","黑色羽毛背景"}}},fp="19,297,20.476.0,23.306.0,41.144.0,38.117.0,64.227.0,37.144.0"}
P.entries["item:blackened-skull"] = {n="焦黑的颅骨",s="焦黑的颅骨是活跃在阿加曼德磨坊的黑眼骨法师的残存颅骨。布瑞尔的亡灵卫兵迪林格尔需要这些恐怖的战利品，以此作为削减威胁提瑞斯法林地的无脑天灾军团兵力的证明。",h="焦黑的颅骨是活跃在阿加曼德磨坊的黑眼骨法师的残存颅骨。布瑞尔的亡灵卫兵迪林格尔需要这些恐怖的战利品，以此作为削减威胁提瑞斯法林地的无脑天灾军团兵力的证明。",kw={"阿加曼德磨坊","焦黑的颅骨","布瑞尔","黑眼骨法师","亡灵卫兵迪林格尔","锯齿肋骨","天灾军团","磨坊的侵扰"},ang={["class:Mage"]="这些颅骨是黑眼骨法师的实体遗骸，这些骷髅施法者是阿加曼德磨坊的目标。",["race:Undead"]="对于被遗忘者来说，消灭黑眼骨法师关乎纯粹的生存，是为了防止他们曾经的主人在家门口建立集结地。"},sec={{t="黑眼骨法师的战利品",b="这些焦黑的颅骨是从徘徊在阿加曼德磨坊的黑眼骨法师身上搜刮来的。这些骷髅施法者将死灵恶意投向生者和被遗忘者，试图在提瑞斯法北部为巫妖王的军队建立一个前沿基地。将它们破损的颅骨呈交给亡灵卫兵迪林格尔，就是天灾军团的神秘先锋队正在被粉碎的确凿证据。"}},faq={{q="焦黑的颅骨从何而来？",a="它们是从黑眼骨法师的遗骸上收集的，这些骷髅施法者在提瑞斯法林地北部的阿加曼德磨坊周围的田野和建筑中徘徊。",al={"焦黑的颅骨来源","谁掉落焦黑的颅骨","在哪里获得焦黑的颅骨"}},{q="为什么亡灵卫兵迪林格尔想要焦黑的颅骨？",a="亡灵卫兵迪林格尔指派被遗忘者的防御者收集焦黑的颅骨和缺口的肋骨，作为与天灾军团积极作战的证明。被遗忘者决不允许巫妖王的无脑爪牙在如此靠近布瑞尔和幽暗城的地方建立立足点。",al={"迪林格尔的颅骨","为什么要收集颅骨","磨坊侵扰与颅骨"}},{q="为什么这些颅骨是焦黑的？",a="布瑞尔没人说得清是什么让它们变得焦黑。亡灵卫兵迪林格尔只想要它们作为阿加曼德磨坊的黑眼骨法师正在被消灭的证据。",al={"为什么是焦黑的","焦黑的颅骨背景故事"}},{q="天灾军团在阿加曼德磨坊做什么？",a="天灾军团正试图将废弃的阿加曼德磨坊加固为一个前沿集结地，利用它来对提瑞斯法林地发动更深入的攻击和突袭。",al={"阿加曼德磨坊的天灾军团","为什么天灾军团在磨坊"}}},fx={d39fbd85={q="什么是焦黑的颅骨？",a="焦黑的颅骨是从徘徊在阿加曼德磨坊的暗眼白骨法师身上收获的残酷战利品。这些黑暗的遗骸对于被遗忘者的死亡卫兵来说是实物证明，表明另一个天灾军团的施法者在还没来得及帮助建立敌方基地之前就已经被干掉了。",al={"什么是焦黑的颅骨","焦黑的颅骨物品","焦黑的颅骨背景"}}},fp="15,243,25.414.0,36.174.0,52.262.0,29.154.0,43.162.0"}
P.entries["item:bloodfeather-belt"] = {n="血羽腰带",s="血羽腰带是泰达希尔北部那些盘踞在此的血羽鹰身人所佩戴的一种简陋皮带。哨兵阿瑞尼亚·碎云收集这些腰带，以此作为清除侵扰神谕林地的鹰身人巢穴的凭证。",h="血羽腰带是泰达希尔北部那些盘踞在此的血羽鹰身人所佩戴的一种简陋皮带。哨兵阿瑞尼亚·碎云收集这些腰带，以此作为清除侵扰神谕林地的鹰身人巢穴的凭证。",kw={"阿瑞尼亚·碎云","血羽","血羽腰带","鹰身人","神谕林地","泰达希尔","魔法林地"},ang={["faction:Alliance"]="协助哨兵阿瑞尼亚·碎云可以确保来自泰达希尔古树的重要报告能够不受干扰地送达达纳苏斯的领导层手中。",["race:NightElf"]="血羽女巫团亵渎了泰达希尔的自然树冠，从这些聒噪的巢穴中收复神谕林地，是卡多雷家园每一位守护者的职责所在。"},sec={{t="巢穴战利品",b="血羽鹰身人在神谕林地周围的枝桠间疯狂筑巢，威胁着古老的神谕之树，并阻断了泰达希尔北部的通行。当一名携带报告前往达纳苏斯的信使遭到鹰身人伏击并杀害后，哨兵阿瑞尼亚·碎云号召旅行者们直接打击它们的巢穴。从倒下的鹰身人身上取下腰带，作为削减它们数量的实物证明，以此确保道路畅通，恢复与首都的通讯。"}},faq={{q="为什么哨兵阿瑞尼亚·碎云需要这些腰带？",a="阿瑞尼亚·碎云和她率领的一小队哨兵驻扎在此，旨在保护神圣的神谕之树免受周围血羽鹰身人巢穴的侵扰。由于鹰身人最近杀害了一名开往达纳苏斯的信使，阿瑞尼亚要求上交腰带作为实质凭证，以证明冒险者们正在清理巢穴并削减鹰身人的数量。",al={"阿瑞尼亚为什么需要腰带","血羽腰带的用途","为什么收集腰带"}},{q="血羽腰带是从哪里来的？",a="它们是从居住在泰达希尔北部神谕林地周围树木和岩缝中的血羽鹰身人身上获取的。该族群中的所有鹰身人，包括风巫师、女巫、潜行者和狂怒者，都会携带这种腰带。",al={"谁掉落血羽腰带","在哪里获取腰带","血羽腰带位置"}},{q="为什么鹰身人在神谕林地是个问题？",a="这些鹰身人在神谕之树附近筑巢，而神谕之树是一棵古老且受人敬仰的树木，监测着世界之树的健康状况。它们充满攻击性的存在使得守卫林地的哨兵陷入孤立，并暴力阻断了发往达纳苏斯的信件往来。",al={"神谕林地的鹰身人","为什么鹰身人在泰达希尔","鹰身人对神谕之树的威胁"}}},fx={["40b720b3"]={q="什么是血羽腰带？",a="血羽腰带是栖息在泰达希尔北部的神谕林地的血羽鹰身人所佩戴的个人装饰品。对于驻扎在林地的暗夜精灵来说，这些粗糙的腰带是战利品，也是另一个邪恶的鹰身人从神圣枝头被剔除的有力证明。",al={"血羽腰带信息","血羽腰带是什么","血羽腰带背景"}}},fp="17,234,23.505.0,54.329.0,38.237.0,46.263.0"}
P.entries["item:bloodfury-ripper-s-remains"] = {n="血怒撕裂者的遗体",s="血怒撕裂者的遗体是回收自焦炭谷血怒鹰身人首领的物理证据。马格兰在烈日石居寻求此物，以此确认该族群凶猛首领的死亡，这对威胁当地牛头人定居点的鹰身人势力造成了决定性打击。",h="血怒撕裂者的遗体是回收自焦炭谷血怒鹰身人首领的物理证据。马格兰在烈日石居寻求此物，以此确认该族群凶猛首领的死亡，这对威胁当地牛头人定居点的鹰身人势力造成了决定性打击。",kw={"血怒撕裂者","焦炭谷","鹰身人","马格兰","遗体","石爪山脉","烈日石居"},ang={["faction:Horde"]="清理像血怒女族长这样的野生威胁，可以确保部落商队和侦察兵在贫瘠之地和石爪山脉之间穿行时的安全。",["race:Tauren"]="血怒鹰身人直接威胁到烈日石居的安全，因此收集她们首领的遗体是对保护石爪山脉平静的牛头人定居点的一种奉献行为。"},sec={{t="切断血脉",b="栖息在焦炭谷焦黑废墟中的血怒鹰身人长期以来对石爪山脉的旅行者和萨满祭司构成了野蛮的威胁。虽然屠杀可以减少眼前的危险，但烈日石居的马格兰认识到，真正的缓解需要消灭她们的首领。血怒撕裂者几乎像女王一样统治着她的族群，引导着她们的领地侵略行为。带回她的遗体是她死亡的必要证明，这会让剩余的鹰身人陷入混乱，并让努力治愈和保卫这片崎岖土地的牛头人感到安心。"}},faq={{q="血怒撕裂者的遗体有什么用途？",a="它们是血怒撕裂者死亡的无可辩驳的物理证据。烈日石居的马格兰需要它们来确认当地鹰身人那女王般的首领已被永久铲除。",al={"遗体有什么用","遗体的目的","谁需要遗体"}},{q="血怒撕裂者在哪里可以找到？",a="血怒撕裂者在石爪山脉南部的焦炭谷西部和西北部的丘陵地带出没，她身上独特的蓝色羽毛使她与红白相间的族群成员区分开来。",al={"血怒撕裂者位置","撕裂者在哪里","寻找血怒撕裂者"}},{q="为什么马格兰要她死？",a="马格兰认为，仅仅宰杀普通的鹰身人永远无法阻止她们对周边地区的突袭。杀死她们的女族长会破坏她们的等级制度，并削弱她们联合起来对抗烈日石居的能力。",al={"为什么要杀血怒撕裂者","马格兰的动机","为什么要杀死撕裂者"}}},fx={ba88af47={q="血怒撕裂者的遗体是从哪里获得的？",a="这些遗体是在焦炭谷的西山击杀血怒撕裂者本人后采集的。与她那红白色的同类不同，这只蓝羽的鸟身人女王统治着焦炭谷荒凉悬崖上的血怒鸟身人部落，这使她成为了任何试图瓦解该鸟身人群体指挥权的人眼中的珍贵目标。",al={"血怒撕裂者的遗体来源","掉落血怒撕裂者遗体的怪物","血怒撕裂者遗体的背景"}},["81140692"]={q="马格兰为什么要血怒撕裂者的遗体？",a="烈日石居的马格兰需要这些遗体作为证明，证明血怒鸟身人的女族长确实已经死了。仅仅消减它们的数量是不够的；马格兰相信，击杀她们的女王会让幸存的鸟身人无所适从，导致她们的数量逐渐减少，从而让他从困扰他的苦涩愤怒中解脱出来。",al={"马格兰索要血怒撕裂者遗体的原因","为什么需要血怒撕裂者遗体","谁想要血怒撕裂者的遗体"}},ff70f27b={q="血怒撕裂者的遗体是什么？",a="这些可怕的遗骸是从血怒撕裂者的尸体上取下的实物证明，它是盘踞在焦炭谷的血怒鹰身人的族长兼首领。她几乎就像是鸟群的女王，引导着它们在石爪山脉大肆扩张。她被杀后的遗体无可辩驳地证明了她对山谷鹰身人的统治已经以血腥的终局告终。",al={"血怒撕裂者的遗体是什么","血怒撕裂者的遗体这是什么","谁是血怒撕裂者"}}},fp="26,326,22.609.0,45.216.0,36.194.0,43.218.0"}
P.entries["item:bloodstone-choker"] = {n="血石颈环",s="血石颈环是一件黑暗魔法护身符，由血石制成，最初属于术士导师黑暗缚灵者加科因。它被一名投靠迪菲亚潜行者的背信弃义的学徒偷走，它是能够穿透虚空以召唤并束缚虚空行者的强大仪式媒介。",h="血石颈环是一件黑暗魔法护身符，由血石制成，最初属于术士导师黑暗缚灵者加科因。它被一名投靠迪菲亚潜行者的背信弃义的学徒偷走，它是能够穿透虚空以召唤并束缚虚空行者的强大仪式媒介。",kw={"血石颈环","迪菲亚","黑暗缚灵者加科因","surena caledon","束缚","slaughtered lamb","虚空行者","术士"},ang={["class:Warlock"]="对于联盟术士来说，找回血石颈环是连接基础法术和指挥强大恶魔仆从的重要通过仪式。",["faction:Alliance"]="Surena Caledon逃往迪菲亚潜行者一事表明，艾尔文森林中的普通不法之徒是如何积极寻求危险的神秘遗物来支持他们反抗暴风城的。"},sec={{t="被窃的媒介",b="血石颈环曾存放在暴风城Slaughtered Lamb下方的隐藏密室中，是黑暗缚灵者加科因珍视的仪式工具之一。当加科因门下的初级术士Surena Caledon背叛导师并偷走这件护身符时，这种宁静被打破了。Surena Caledon逃入艾尔文森林，投靠了法外之徒迪菲亚潜行者，并将这件附魔颈环作为权力的象征和谈判的筹码随身携带。在强盗们利用其危险能量达成自己的企图之前，必须前往布莱克威尔南瓜田追捕她并将其收回。"},{t="驯服虚空",b="这件颈环由血石雕刻而成，拥有连接凡世与扭曲虚空深处暗影所需的潜在神秘权威。一旦归还给加科因，它便会立即在酒馆下方的地穴中接受测试。术士必须在地下召唤法阵引导颈环的魔法，从而从虚空中撕裂出一个敌对的虚空行者。只有在手持护身符与其进行直接战斗并制服这个狂暴的实体，修行者才能证明自己拥有指挥这类守护者所需的意志力。"}},faq={{q="什么是血石颈环？",a="它是一条由血石制成的附魔项链，被术士用作仪式媒介。它拥有足够穿透现实并将狂暴的虚空行者从虚空中召唤出来的魔法力量。",al={"血石颈环","什么是颈环","颈环的作用"}},{q="谁最初拥有这条颈环？",a="它属于黑暗缚灵者加科因，这是一位在暴风城Mage Quarter的Slaughtered Lamb下方的隐秘地下室里训练修行者的术士大师。",al={"颈环的所有者","加科因的颈环","颈环的来源"}},{q="为什么要偷走这件颈环？",a="Surena Caledon，加科因门下的一名学徒，放弃了学业并偷走了颈环，随后逃往并加入了迪菲亚潜行者。她寻求力量并与躲藏在艾尔文森林中的强盗结盟。",al={"谁偷了它","surena caledon偷它的原因","surena caledon的颈环"}},{q="颈环在术士训练中是如何使用的？",a="在找回后，颈环会在Slaughtered Lamb下方地穴的召唤法阵上被激活。它会引出一个虚空行者，有抱负的术士必须击败并制服它，才能获得指挥该恶魔的权力。",al={"如何使用颈环","虚空行者仪式颈环","束缚颈环"}}},fx={["9d3659ea"]={q="为什么需要血石颈环？",a="黑暗缚灵者加科因将血石颈环视为召唤并奴役虚空行者所需的强大魔法催化剂。在他以前的学徒苏雷娜·卡雷登为了帮助迪菲亚兄弟会偷走它之后，加科因寻求将其夺回，以恢复他的奥术权威，并以此在Slaughtered Lamb地下室中考验新的术士。",al={"为什么需要血石颈环","谁在找血石颈环","加科因想要颈环的原因"}}},fp="17,196,16.422.1,15.389.0,30.180.0,32.151.0,26.157.0,43.209.0"}
P.entries["item:blueleaf-tuber"] = {n="蓝叶薯",s="蓝叶块茎是一种极其稀有的根茎类蔬菜，生长在剃刀沼泽布满荆棘的地下。它们被全世界视为珍奇的美食，几乎无法用肉眼发现。",h="蓝叶块茎是一种极其稀有的根茎类蔬菜，生长在剃刀沼泽布满荆棘的地下。它们被全世界视为珍奇的美食，几乎无法用肉眼发现。",kw={"贫瘠之地","蓝叶薯","麦伯克·米希瑞克斯","棘齿城","剃刀沼泽","嗅鼻地鼠","块茎"},ang={["profession:Cooking"]="作为全球公认的珍贵美味，尽管生长在野猪人巢穴那样的恶劣土壤中，这些块茎仍受到最富有美食家的追捧。"},sec={{t="一种稀有的地下美味",b="虽然蓝叶块茎原产于贫瘠之地，但它们只生长在剃刀沼泽的地下深处。它们隐藏在茂密的根系和野猪人的荆棘之下，普通的采集者根本无法发现。尽管生长环境恶劣，但它们在世界各地的富裕美食家和商人眼中价值连城，因为大家都迷恋它们独特的风味。"},{t="地鼠协助采集",b="由于这种根茎不容易被地表居民发现，棘齿城的进取型地精麦伯克·米希瑞克斯发明了一种不同寻常的采集方法。通过训练当地的嗅鼻地鼠，让它们在五十步之外就能闻出块茎的气味，冒险者可以在特制指挥棒的引导下，在野猪人巡逻队发现入侵之前将这些根茎从土壤中挖掘出来。"}},faq={{q="蓝叶块茎有什么用途？",a="蓝叶块茎作为稀有的美味佳肴进行交易。富有的客户和异域商人为了追求它们独特的口感和稀有性，愿意支付高昂的价格。",al={"块茎用途","为什么要收集蓝叶块茎","块茎的作用"}},{q="蓝叶块茎可以在哪里找到？",a="它们只生长在南贫瘠之地的地下深处，位于剃刀沼泽的荆棘丛和地下巢穴中。",al={"蓝叶块茎生长在哪里","块茎位置","块茎在哪里"}},{q="为什么需要地鼠来挖掘它们？",a="块茎生长在表层土壤之下，人类或地精的肉眼无法看到。嗅鼻地鼠经过训练，可以在五十步外闻出它们的气味，并听从命令将其挖掘出来。",al={"为什么使用嗅鼻地鼠","地鼠的用途","为什么要用地鼠"}},{q="谁会购买这些块茎？",a="在棘齿城经营生意的地精企业家麦伯克·米希瑞克斯会收购它们，然后高价转卖给富有的买家和国际客户。",al={"谁想要蓝叶块茎","谁购买块茎","麦伯克的块茎"}}},fx={["9eab4987"]={q="什么是蓝叶薯？",a="蓝叶薯是一种极其罕见的可食用根茎，埋藏在剃刀沼泽的地下深处。它因其烹饪价值而备受推崇，在世界各地都被视为美味佳肴，尽管由于剃刀沼泽原生地中充斥着野猪人，采集它变得十分危险。",al={"蓝叶薯是什么","蓝叶薯背景知识","关于蓝叶薯的信息"}},["094c1930"]={q="蓝叶薯是从哪里来的？",a="蓝叶薯是南贫瘠之地特有的天然地下根茎，生长在剃刀沼泽错综复杂的根系深处。它们并非由人培育，而是使用训练有素的地穴地鼠嗅探出来，并直接从地下土壤中采集。",al={"蓝叶薯的起源","蓝叶薯的生长地","谁制作了蓝叶薯"}}},fp="14,233,27.355.0,26.381.0,34.143.0,35.122.0,40.188.0,22.146.0"}
P.entries["item:book-from-sven-s-farm"] = {n="斯温农场中的书",s="“斯温农场中的书”是一本沾满污垢、没有标题的日记，是从暮色森林中斯温·约根被洗劫后的家园废墟里挖掘出来的。书里支离破碎的记载揭示了一位不知名的旁观者目睹了斯温一家的惨案，这引发了在这片阴影笼罩的森林中一场无情的搜寻。",h="“斯温农场中的书”是一本沾满污垢、没有标题的日记，是从暮色森林中斯温·约根被洗劫后的家园废墟里挖掘出来的。书里支离破碎的记载揭示了一位不知名的旁观者目睹了斯温一家的惨案，这引发了在这片阴影笼罩的森林中一场无情的搜寻。",kw={"斯温农场中的书","夜色镇","迪菲亚潜行者","暮色森林","基特斯","阴影中的身影","斯温·约根","狼人"},ang={["faction:Alliance"]="对于联盟调查员来说，这本饱经风霜的书是解开导致暮色森林南部陷入瘫痪的诡异恐怖事件、并发现野性狼人部族如何获得立足之地的关键。"},sec={{t="泥土中的线索",b="这本毫不起眼、饱经风霜的日记埋在暮色森林南部斯温农场焦黑的残骸中，在一堆松软的土丘里，包含了某位匿名流浪者惊恐万状的笔记。这些记录断断续续地揭开了农场悲剧的一角，证实了斯温·约根心中最黑暗的猜测：当他的家人被屠杀时，有人潜伏在阴影之中。由于叙述戛然而止，这本书引发的问题比答案更多，促使调查者将其带回夜色镇，寻找任何能认出这笔迹或其神秘作者的人。"},{t="揭开黑影的真相",b="将这本日记带给夜色镇的秘法师和镇民看，揭示了其真正的主人并非夜色镇本地人，而是曾极度恐惧地逃入森林。追踪书页上褪色的痕迹最终引向了基特斯，一个躲在森林里的懦弱流浪汉。这卷缺失的篇章记录了迪菲亚潜行者是如何摆弄禁忌的神器，从而无意中将贪婪的狼人释放到暮色森林的。找到基特斯将叙述拼凑完整，最终形成了“基特斯的日记”。"}},faq={{q="在哪里可以找到“斯温农场中的书”？",a="这本书埋在斯温·约根位于暮色森林南部的废弃农场里，在一堆凌乱的土丘中。",al={"哪里可以找到斯温的书","斯温农场的土丘","斯温的书位置"}},{q="是谁写了在斯温农场发现的这本书？",a="这本书没有标题也没有署名。其作者是一个在暮色森林其他地方遭遇恐怖事件后逃跑的惊恐男子，他躲在斯温的谷仓里，目睹了斯温一家的屠杀，随后弄丢了他的日记。",al={"斯温的书作者","谁写了那本沾满污垢的书","谁写了日记"}},{q="为什么斯温·约根想要这本书？",a="斯温在他的家人遭到袭击后，看到一个不明人物潜伏在谷仓附近。这本书证明了那个旁观者的真实存在，为斯温提供了他寻找那晚真相的唯一线索。",al={"为什么斯温在意","斯温·约根对书的反应"}},{q="调查这本书后会发生什么？",a="在向夜色镇的各位居民展示这部分日记并追踪到它的主人后，这本残缺的书最终会被“基特斯的日记”所取代，后者讲述了完整的故事。",al={"什么取代了斯温的书","你会保留斯温的书吗"}},{q="与书的内容相关的更大秘密是什么？",a="完整的日记解释了作者为何躲藏，以及斯温一家为何遭到袭击，其故事的影响范围远超一个农场，直指笼罩在暮色森林之上的黑暗。",al={"斯温的书里有什么背景故事","与狼人的联系","与迪菲亚潜行者的联系"}}},fx={fd4c7f5f={q="什么是斯温农场中的书？",a="这是一本未标标题、沾满泥土的日记，从暮色森林斯温·约根破败的家园遗址中挖掘出来。尽管破旧且残缺不全，但其手写页面包含了一份关于斯温农场和家庭所遭遇恐怖事件的目击记录。更重要的是，它作为确凿的证据，表明在屠杀期间有一个身份不明的旁观者在场，这掌握着关于谁袭击了农场以及原因的关键答案。",al={"斯温农场中的书是什么","暮色森林沾满泥土的书","什么是沾满泥土的书"}}},fp="21,286,18.583.0,29.547.1,41.117.0,40.195.1,36.215.0,50.197.1,55.184.1"}
P.entries["item:book-stresses-of-iron"] = {n="《金属的延展性》",s="《铁的应力》是一本由玛格尔夫·布拉贡撰写的冶金学学术著作。它原本收藏于Stormwind Keep的Royal Library中，在被借出到Northshire Abbey进行抄录后，它成为了修士们之间一件差事的核心。",h="《铁的应力》是一本由玛格尔夫·布拉贡撰写的冶金学学术著作。它原本收藏于Stormwind Keep的Royal Library中，在被借出到Northshire Abbey进行抄录后，它成为了修士们之间一件差事的核心。",kw={"克里斯托弗修士","派克斯顿修士","玛格尔夫·布拉贡","冶金学","米尔顿·西弗","北郡修道院","royal library","铁的应力"},ang={["profession:Blacksmithing"]="此书由玛格尔夫·布拉贡撰写，深入探讨了铁的结构强度及其加工过程中的实际极限。"},sec={{t="借阅的书卷",b="《铁的应力》由玛格尔夫·布拉贡所著，涵盖了冶金学的实践与理论特性。这本书平时由米尔顿·西弗照管，存放于Stormwind Keep的Royal Library内。它被借出给Northshire Abbey，以便克里斯托弗修士的同僚派克斯顿修士能将其内容手抄一份，收入自己的藏书中。派克斯顿的抄写工作耗费的时间远超预期，这使得身处Cathedral Square的克里斯托弗修士焦急地等待着这本书归还到城中。"}},faq={{q="这本书是关于什么的？",a="《铁的应力》是一本关于冶金和金属加工的学术手册，由学者玛格尔夫·布拉贡撰写。",al={"什么是铁的应力","铁的应力主题","书籍内容"}},{q="为什么这本书会在北郡修道院？",a="派克斯顿修士从暴风城的Royal Library借阅了此书，以便在归还原件之前，为他的个人收藏精心地进行手抄。",al={"为什么派克斯顿会有这本书","为什么在北郡修道院"}},{q="谁想要这本书被归还？",a="身处Cathedral Square的克里斯托弗修士急切地要求归还此书，促使一名冒险者去追寻它在Royal Library和北郡修道院之间的去向。",al={"谁需要这本书","谁在等待它"}}},fx={["7d684098"]={q="Stresses of Iron来自哪里，是谁写的？",a="这本书是由Margulf Blaggon撰写的关于冶金学的学术论著。它的存放地是Royal Library内部，不过Paxton修士借走了这卷书并带到了北郡修道院，以便为自己的书架细心誊抄一份副本。",al={"谁写了stresses of iron","stresses of iron的作者","stresses of iron的起源"}}},fp="22,104,17.397.0,23.89.0,37.138.0,29.180.0"}
P.entries["item:bottle-of-disease"] = {n="一瓶病菌",s="“一瓶病菌”是活跃在灰谷的被遗忘者所酿造的剧毒药剂的瓶装样本。这些药瓶在靠近朵丹尼尔兽穴的一处营地中被发现，代表了亡灵试图将腐蚀性瘟疫引入纯净的暗夜精灵荒野的邪恶企图。",h="“一瓶病菌”是活跃在灰谷的被遗忘者所酿造的剧毒药剂的瓶装样本。这些药瓶在靠近朵丹尼尔兽穴的一处营地中被发现，代表了亡灵试图将腐蚀性瘟疫引入纯净的暗夜精灵荒野的邪恶企图。",kw={"灰谷","枯萎","一瓶病菌","朵丹尼尔兽穴","林歌神殿","被遗忘者","被遗忘者的病菌","kayneth stillwind"},ang={["class:Druid"]="枯萎的混合物和人造瘟疫代表了自然平衡的对立面，任何誓言保卫森林的德鲁伊都必须迅速采取干预措施。",["race:NightElf"]="亡灵传染物对灰谷土壤的亵渎是Kaldorei无法原谅的侮辱，尤其是当这些东西是在朵丹尼尔兽穴的家门口酿造时。"},sec={{t="神圣森林中的枯萎",b="在灰谷东部古老的树冠深处，被遗忘者已经悄然越过了战歌氏族的前线。亡灵炼金术师在朵丹尼尔兽穴附近建立了一处前哨站，他们在此酿造邪恶的传染物，并将其密封在玻璃瓶中。对于守卫林歌神殿的暗夜精灵来说，这些药瓶清晰地表明了一场安静而阴险的攻势：其目的并非通过正面作战，而是旨在让森林的土壤和野生生物患病。"},{t="Kayneth Stillwind的调查",b="Kayneth Stillwind，一名驻扎在林歌神殿的暗夜精灵哨兵，正在寻求被遗忘者险恶野心的证据。找回“一瓶病菌”可以让Stillwind直接分析其成分。暗夜精灵担心这些药剂不仅是针对武装哨兵的战争武器，更是旨在腐蚀神圣兽穴、摧毁森林守护者身心的精密试剂。"}},faq={{q="“一瓶病菌”里装着什么？",a="药瓶里装有由被遗忘者药剂师酿造的合成毒药和魔法传染物。这些邪恶的混合物旨在腐蚀活体血肉和土壤，反映了Royal Apothecary Society正在进行的关于剧毒瘟疫的广泛实验。",al={"药瓶里有什么","一瓶病菌的成分","被遗忘者药剂"}},{q="这些药瓶在哪里可以找到？",a="它们位于林歌神殿以南的一处孤立的被遗忘者营地中，就在灰谷东部朵丹尼尔兽穴的入口附近。",al={"哪里可以找到一瓶病菌","一瓶病菌的位置","灰谷的被遗忘者营地"}},{q="谁需要“一瓶病菌”？",a="驻扎在林歌神殿前哨站的暗夜精灵保卫者Kayneth Stillwind委托联盟的冒险者找回一个药瓶，以便他能分析其中的成分，推测部落的真实意图。",al={"谁需要一瓶病菌","上交一瓶病菌","kayneth stillwind的任务"}},{q="为什么被遗忘者要在灰谷酿造病菌？",a="暗夜精灵怀疑被遗忘者企图悄悄感染这片神圣的森林，并亵渎附近的兽穴，毒害自然生态系统，从内部瓦解暗夜精灵的抵抗。",al={"为什么被遗忘者会在灰谷","亡灵在灰谷的目标","被遗忘者与兽穴"}}},fx={["4091970d"]={q="什么是一瓶病菌？",a="这是一瓶密封的药剂，里面装有被遗忘者调制的剧毒和瘟疫。幽暗城的特工在灰谷各处的秘密营地中酿造这些邪恶的混合物，将其装瓶以便运输并蓄意传播到古老的精灵林地中。",al={"一瓶病菌是什么","一瓶病菌背景故事","一瓶病菌信息"}},["62494cf6"]={q="一瓶病菌来自哪里，是谁制作的？",a="这瓶药剂是由驻扎在林歌神殿以南，靠近朵丹尼尔兽穴的隐秘营地中的被遗忘者药剂师酿造的。这些不死炼金术士潜伏在神圣的暗夜精灵古墓附近，在卡利姆多大地上积极采集并提炼危险的毒药和瘟疫。",al={"谁制造了一瓶病菌","一瓶病菌的来源","一瓶病菌从何而来"}},["9d281de4"]={q="为什么凯内斯·静风想要一瓶病菌？",a="林歌神殿的凯内斯·静风需要一份完整的样本来分析被遗忘者在策划什么。通过测试这种药剂的炼金属性，暗夜精灵希望确认这些亡灵是否企图污染灰谷本身，并准备有效的应对措施。",al={"为什么要一瓶病菌","为什么要获取一瓶病菌","凯内斯想要病菌的原因"}}},fp="17,281,26.448.0,33.411.1,37.245.0,30.155.0,32.201.0,51.201.0"}
P.entries["item:bottle-of-moonshine"] = {n="一瓶月光酒",s="一瓶月光酒是出售于昏暗的夜色镇的一种烈性酒精饮料。湖畔镇的酒吧老板丹尼尔急需一瓶这种酒来补充镇上酒馆的库存，因为黑石兽人的入侵切断了正常的补给运输。",h="一瓶月光酒是出售于昏暗的夜色镇的一种烈性酒精饮料。湖畔镇的酒吧老板丹尼尔急需一瓶这种酒来补充镇上酒馆的库存，因为黑石兽人的入侵切断了正常的补给运输。",kw={"酒吧老板丹尼尔","一瓶月光酒","夜色镇","酒水短缺","暮色森林","湖畔镇","月光酒","scarlet raven tavern"},ang={["faction:Alliance"]="从夜色镇运送烈酒到湖畔镇，突显了在危机时刻，连接暴风城王国各个分散定居点的脆弱补给线。"},sec={{t="振奋精神",b="湖畔镇正遭受黑石氏族的围攻，导致当地旅店老板，也就是酒吧老板丹尼尔陷入了困境，因为常规的补给商队无法抵达。为了维持镇卫兵和被围困的镇民的士气，丹尼尔派遣信使前往南部的各个王国收集当地特产。其中就包括在邻近的暮色森林的Scarlet Raven Tavern酿造和出售的一瓶烈性月光酒，当地人喜欢用烈酒来驱散森林中日益逼近的恐惧。"}},faq={{q="我在哪里可以找到一瓶月光酒？",a="一瓶月光酒可以从位于暮色森林黑暗边界内的夜色镇，Scarlet Raven Tavern的酒保那里购买到。",al={"哪里购买月光酒","夜色镇月光酒位置","一瓶月光酒商人"}},{q="谁需要这瓶酒？",a="位于赤脊山湖畔镇的旅店老板，酒吧老板丹尼尔，请求获得这瓶酒以及其他几种地方饮品，以便在持续的兽人围攻期间保持他酒窖的库存。",al={"谁需要月光酒","月光酒任务上交","酒吧老板丹尼尔月光酒"}},{q="为什么湖畔镇会缺酒？",a="敌对的黑石兽人涌入了赤脊山，袭击道路并切断了贸易路线。常规的补给运输未能抵达，导致湖畔镇的酒馆货架几乎空空如也。",al={"为何酒水短缺","湖畔镇补给短缺","赤脊山酒精短缺"}}},fx={["1eb07341"]={q="什么是瓶装月光酒？",a="这是一种在暮色森林的夜色镇的Scarlet Raven Tavern出售的烈性酒。虽然在这种宁静的湖畔度假地中，非法或辛辣的烈酒似乎有些格格不入，但困难时期需要烈酒来支撑。",al={"什么是月光酒","月光酒的信息","关于瓶装月光酒"}},["5d3a7e66"]={q="这瓶月光酒来自哪里？",a="这种特定的烈酒来自暮色森林中阴暗的夜色镇，由Scarlet Raven Tavern提供。随着王国各地的本地供应线紧张，酒馆老板们只能四处寻找货源来填满他们的货架。",al={"谁制造月光酒","月光酒在哪里生产","月光酒起源"}},["08a7d809"]={q="为什么湖畔镇需要一瓶月光酒？",a="酒吧老板丹尼尔需要它来维持湖畔镇酒馆的运转。由于黑石兽人的入侵和贸易路线的中断，该镇的酒类供应几乎已经枯竭。丹尼尔派遣旅行者穿过人类领地去收集烈酒——包括这瓶来自夜色镇的月光酒——以满足他压力重重的客人们。",al={"为什么湖畔镇需要月光酒","为什么购买月光酒","谁需要月光酒"}}},fp="19,241,17.497.0,39.146.0,22.186.0,39.200.0"}
P.entries["item:bottle-of-zombie-juice"] = {n="一瓶僵尸酒",s="“一瓶僵尸酒”是一种烈性且气味刺鼻的酒，由暮色森林中生长的腐败之花酿制而成。这是从夜色镇的旅店中获得的，据说是隐居的隐士亚伯克隆比为了抵御阴郁森林中的寒冷而特意要求的。",h="“一瓶僵尸酒”是一种烈性且气味刺鼻的酒，由暮色森林中生长的腐败之花酿制而成。这是从夜色镇的旅店中获得的，据说是隐居的隐士亚伯克隆比为了抵御阴郁森林中的寒冷而特意要求的。",kw={"亚伯克隆比","一瓶僵尸酒","夜色镇","暮色森林","酒类配送","腐败之花","僵尸酒"},ang={["faction:Alliance"]="在夜色镇和阴影笼罩的荒野之间跑腿有助于维持暮色森林不安定的居民之间的联系，即使这些任务看起来很可疑。",["profession:Herbalism"]="熟悉暮色森林的草药师都知道腐败之花是不适合作为普通恢复性补剂的原料，这使得将其蒸馏成饮料的行为更加令人不安。"},sec={{t="刺鼻的混合物",b="僵尸酒由暮色森林阴暗土壤中采集的腐败之花酿制，是一种极其辛辣的酒。提供此酒的酒保警告说，这种酒烈到足以让死人复活。虽然普通人都会远离这种令人作呕的蒸馏酒，但古怪的隐士亚伯克隆比却声称这是唯一能让他在林中小屋潮湿寒冷的夜晚保持温暖的东西。"},{t="可疑的渴求",b="虽然亚伯克隆比坚称这种酒只是作为一种烈性睡前酒，但他在收到酒时的一句口误——差点赞扬了送信人的“愚蠢”而非好意——暗示这种混合物可能有着比简单的旅店取暖更黑暗、更邪恶的用途。"}},faq={{q="僵尸酒是用什么制成的？",a="僵尸酒是一种由腐败之花蒸馏而成的烈酒，这是一种生长在暮色森林受腐蚀土壤中的气味恶臭的植物。",al={"僵尸酒原料","僵尸酒里有什么"}},{q="谁要求运送这瓶酒？",a="这瓶酒是亚伯克隆比要求的，他是一位古怪的隐士，住在暮色森林西侧边缘的一间孤零零的小屋里。",al={"谁需要僵尸酒","僵尸酒是给谁的","僵尸酒运送"}},{q="为什么亚伯克隆比想要僵尸酒？",a="亚伯克隆比声称他需要这种烈酒来在暮色森林苦涩黑暗的夜晚温暖他那把老骨头，尽管他奇怪的举止暗示他对这种烈性混合物可能另有他用。",al={"为什么亚伯克隆比喝这个","亚伯克隆比僵尸酒理由"}},{q="玩家可以喝“一瓶僵尸酒”吗？",a="不能，这瓶特定的酒是一个仅用于交付给亚伯克隆比的任务物品，安全地将其送到他的小屋是你的主要任务。",al={"我可以喝僵尸酒吗","僵尸酒可以消耗吗"}}},fx={f1488eba={q="什么是僵尸酒？",a="僵尸酒是一种在暮色森林中混合了腐败之花的烈性酒。它被描述为味道恶臭且极其强烈——据说强烈到足以让死者复活——这是一种酒馆老板处理时必须格外谨慎的令人不悦的混合物。",al={"僵尸酒是什么","僵尸酒的背景知识","关于那种酒"}},b862f5ea={q="僵尸酒来自哪里，是谁制作的？",a="这种酒是在夜色镇由当地的酒馆老板，旅店老板斯密茨酿造的，他用腐败之花蒸馏而成。它是专门根据订单准备的，用于运送到暮色森林阴森荒野中的亚伯克隆比的小屋。",al={"谁制作了僵尸酒","僵尸酒从何而来","谁酿造僵尸酒"}}},fp="22,249,20.398.0,19.287.1,31.130.0,32.136.0,39.204.0,45.142.0"}
P.entries["item:bottom-of-gelkak-s-key"] = {n="基尔卡克钥匙的尾部",s="基尔卡克钥匙的尾部是遭难的侏儒海盗基尔卡克·旋杆破碎的机械发条钥匙上的三个碎片之一。在他的船只在黑海岸沉没后，这块碎片被海岸边土生土长的礁石爬行者所搜刮。",h="基尔卡克钥匙的尾部是遭难的侏儒海盗基尔卡克·旋杆破碎的机械发条钥匙上的三个碎片之一。在他的船只在黑海岸沉没后，这块碎片被海岸边土生土长的礁石爬行者所搜刮。",kw={"爬行者","黑海岸","大副","基尔卡克","旋杆","钥匙","回收","沉船"},ang={["profession:Engineering"]="工程师们会认出这块碎片是一种专门设计的发条工具的一部分，用于驱动复杂的钟表自动装置。",["race:Gnome"]="侏儒们会欣赏这一点：即便在充满敌意的海岸线遭遇海难并流落荒岛，旋杆依然依赖钟表工程学而非血肉之躯的船员。"},sec={{t="爬行者的战利品",b="当基尔卡克·旋杆的船只在黑海岸近海被巨牙海兽击沉时，这名侏儒和他的随身物品被抛到了岸上。他最珍视的财物之一就是用于激活他机械大副的发条钥匙。钥匙在海岸岩石上摔成了三个不同的碎片，当地的拾荒者随即涌向了残骸。钥匙的尾部被游荡在海浪中的好斗甲壳类生物抢走了——具体来说是那些在潮汐线沿岸翻找碎屑的礁石爬行者和潮汐爬行者。"},{t="重新组装",b="如果不能将这块尾部碎片与被海岸鱼人和内陆陆行鸟拖走的中段及顶段碎片重新结合，基尔卡克就无法激活他的机械船员。只有从海岸蟹类的甲壳中撬出这块沉重的碎片，这位侏儒海盗才有可能修复他的构装体，并为他毁掉的远征寻求复仇。"}},faq={{q="基尔卡克钥匙的尾部有什么用？",a="它是修复落难海盗基尔卡克·旋杆的发条钥匙所需的三块碎片之一，该钥匙是重新激活他的机械大副所必需的。",al={"基尔卡克钥匙的作用","基尔卡克钥匙的尾部用途","为什么要找基尔卡克钥匙的尾部"}},{q="这块钥匙碎片来自哪里？",a="它出现在黑海岸，被沿水边出没的当地蟹类，如结壳的潮汐爬行者和狂怒的礁石爬行者所搜刮。",al={"基尔卡克钥匙的尾部哪里找","基尔卡克钥匙的尾部掉落","基尔卡克钥匙的尾部位置"}},{q="钥匙为什么会断成三截？",a="当基尔卡克的船被巨牙海兽击毁时，他被冲上岸，钥匙撞击了海岸岩石，摔成了散落在当地野生动物之间的碎片。",al={"基尔卡克钥匙为何会断","钥匙怎么断的"}},{q="基尔卡克·旋杆是谁？",a="基尔卡克·旋杆是一位落难的侏儒海盗，在巨牙海兽攻击摧毁了他的船只并散落了他的装备后，他便在黑海岸的岸边扎营。",al={"基尔卡克是谁","基尔卡克·旋杆背景故事"}}},fx={bb7c59d0={q="什么是基尔卡克钥匙的尾部？",a="这是属于失事的地精海盗基尔卡克·旋杆的一把机械钥匙的最末端碎片。当他的船在黑海岸附近沉没时，钥匙在撞击锯齿状岩石时破碎，而这块碎片是由当地的海岸爬行者从残骸中搜寻到的。",al={"什么是基尔卡克钥匙的尾部","基尔卡克钥匙的尾部信息","这个钥匙碎片是什么"}}},fp="22,256,19.545.0,10.356.1,44.167.0,36.144.0,40.173.0,23.147.0"}
P.entries["item:branch-of-cenarius"] = {n="塞纳留斯的树枝",s="塞纳留斯的树枝是一件神圣的树妖圣物，被潜伏在灰谷东部的邪恶萨特Geltharis所窃。夺回这件传家宝是树妖安妮莉亚的临终遗愿，她在保卫这件圣物抵御森林腐蚀者时不幸牺牲。",h="塞纳留斯的树枝是一件神圣的树妖圣物，被潜伏在灰谷东部的邪恶萨特Geltharis所窃。夺回这件传家宝是树妖安妮莉亚的临终遗愿，她在保卫这件圣物抵御森林腐蚀者时不幸牺牲。",kw={"安妮莉亚","灰谷","塞纳留斯的树枝","树妖","林歌神殿","geltharis","伊莉亚娜","萨特"},ang={["class:Druid"]="作为塞纳留斯的信徒，德鲁伊们感到有个人义务去从恶魔萨特的玷污中夺回任何带有森林之王名号的神器。",["race:NightElf"]="对于灰谷的暗夜精灵而言，帮助树妖并找回她们失落的祖传宝物是侍奉自然的神圣职责。"},sec={{t="坠入阴影的神圣之枝",b="塞纳留斯的树枝深受塞纳留斯之女们的崇敬，它既代表了森林之王的祝福，也象征着树妖与灰谷之间深厚的联系。这根树枝一直受到树妖姐妹安妮莉亚和伊莉亚娜的珍视，直到一群堕落的萨特伏击了她们。萨特首领Geltharis抢走了圣物，并在灰谷东部那片被污染的废墟附近重创了安妮莉亚。安妮莉亚在弥留之际指向北方Geltharis潜伏的拱门处，恳求一位勇士从他的魔爪中夺回这根神圣的树枝，并将其送回林歌神殿交还给树妖们。"}},faq={{q="什么是塞纳留斯的树枝？",a="塞纳留斯的树枝是灰谷树妖们珍视的一件自然圣物。它承载着半神塞纳留斯的名号与祝福，是她们守护这座古老森林的神圣象征。",al={"塞纳留斯的树枝背景故事","这根树枝是什么","树妖的树枝"}},{q="是谁偷走了塞纳留斯的树枝？",a="这件圣物被邪恶的萨特Geltharis偷走了，他率领部队在灰谷东部伏击了树妖。Geltharis杀害了树妖安妮莉亚，带着树枝逃到了北方的一座石拱门后。",al={"谁拿走了树枝","谁偷了它","谁掉落塞纳留斯的树枝"}},{q="这根树枝属于谁？",a="这根树枝属于林歌神殿的树妖。随着安妮莉亚在保卫它时牺牲，这件圣物被送还给了她悲痛欲绝的姐妹伊莉亚娜，完成了安妮莉亚的临终遗愿。",al={"谁获得了树枝","谁想要这根树枝","我应该把它交给谁"}},{q="这根树枝是在哪里找回的？",a="这根树枝可以从Geltharis身上获得，他潜伏在灰谷东部安妮莉亚倒下的废墟以北，靠近与艾萨拉的边界。",al={"树枝位置","geltharis在哪里","去哪里找树枝"}}},fx={["4e4ec82f"]={q="为什么取回塞纳留斯的树枝如此重要？",a="灰谷的树妖们认为这根树枝是与她们的父亲塞纳留斯联系在一起的无价圣物。当树妖安妮莉亚在萨维亚附近被腐化的萨特重伤后，她临终的遗愿就是确保这根被偷走的树枝从Geltharis手中夺回，并安全地送回林歌神殿的树妖手中。",al={"为什么取回塞纳留斯的树枝","为什么树妖想要树枝","塞纳留斯的树枝的作用"}}},fp="18,222,31.608.0,31.220.0,33.224.0,30.178.1,30.140.0"}
P.entries["item:brass-collar"] = {n="黄铜项圈",s="黄铜项圈是一件坚固的颈饰，由布莱克威尔家族所饲养的获奖母猪“公主”佩戴。对于斯通菲尔德妈妈来说，它是这头贪吃的野兽在毁掉她农场的作物之前已被除掉的确实证据。",h="黄铜项圈是一件坚固的颈饰，由布莱克威尔家族所饲养的获奖母猪“公主”佩戴。对于斯通菲尔德妈妈来说，它是这头贪吃的野兽在毁掉她农场的作物之前已被除掉的确实证据。",kw={"布莱克威尔南瓜田","黄铜项圈","艾尔文森林","斯通菲尔德妈妈","公主","必须杀死公主","斯通菲尔德农场"},ang={["faction:Alliance"]="对于协助艾尔文森林乡民的年轻冒险者来说，取回“公主”的项圈是解决小镇农民纠纷的经典成人礼。"},sec={{t="农场竞争的战利品",b="“公主”并非普通的猪；它是布莱克威尔家族饲养的一头巨大的、足以参展的猪，在麦克罗雷宅地东侧的布莱克威尔南瓜田附近游荡。不幸的是，对于她的邻居来说，她之所以能长到能获奖的体型，全靠对斯通菲尔德农场作物的贪婪胃口。斯通菲尔德妈妈受够了珍贵的蔬菜被这头游荡的馋猪吃掉，于是寻找愿意杀死这头巨大母猪的人。因为“公主”脖子上戴着一条显眼的黄铜项圈，所以她的项圈成了这头掠食的猪再也不会袭击斯通菲尔德田地的确凿证据。"}},faq={{q="黄铜项圈从哪里来？",a="这个项圈取自“公主”，那是一头在艾尔文森林东部、经过麦克罗雷农场后的布莱克威尔南瓜田里拱地的巨大获奖母猪。",al={"黄铜项圈来源","谁掉落黄铜项圈","哪里获得黄铜项圈"}},{q="斯通菲尔德妈妈为什么要这个项圈？",a="“公主”经常溜到斯通菲尔德农场去吞食斯通菲尔德妈妈的获奖蔬菜。拿到项圈可以向斯通菲尔德妈妈证明，这头野兽在毁掉她余下的收成之前终于被除掉了。",al={"为什么斯通菲尔德想要项圈","斯通菲尔德妈妈项圈用途"}},{q="“公主”的主人是谁？",a="“公主”属于布莱克威尔家族，不过她被允许在他们的南瓜田里和她较小的野猪同伴们一起自由活动。",al={"公主的主人","谁拥有这头猪"}},{q="除了“公主”，还有其他生物掉落这个物品吗？",a="没有。黄铜项圈是“公主”独有的，专门为布莱克威尔家族这头珍贵的母猪那巨大的体型所打造。",al={"其他掉落项圈的怪物","哪里还能找到黄铜项圈"}}},fx={["92e34b72"]={q="什么是黄铜项圈？",a="黄铜项圈是Brackwell家族拥有的获奖母猪Princess所佩戴的独特颈圈。由于Princess体型庞大且有偷吃邻近庄稼的习惯，这个项圈成为了这头破坏性野兽终于被解决的确凿证据。",al={"黄铜项圈是什么","黄铜项圈的背景故事","谁戴着黄铜项圈"}}},fp="12,112,28.400.0,38.105.0,39.151.0,18.104.0,46.97.0"}
P.entries["item:bristleback-attack-plans"] = {n="刺背野猪人的进攻计划",s="刺背野猪人的进攻计划是刺刃峡谷的野猪人所绘制的粗糙地图和战术笔记。它们勾勒出了一场旨在直接攻占纳拉其营地这一牛头人定居点的协同围攻计划。",h="刺背野猪人的进攻计划是刺刃峡谷的野猪人所绘制的粗糙地图和战术笔记。它们勾勒出了一场旨在直接攻占纳拉其营地这一牛头人定居点的协同围攻计划。",kw={"进攻计划","刺刃峡谷","刺背野猪人","纳拉其营地","鹰风酋长","莫高雷","野猪人"},ang={["faction:Horde"]="挫败刺背野猪人的进攻确保了部落在莫高雷的神圣平原上拥有一个安全、不受威胁的立足点。",["race:Tauren"]="揭露这一阴谋捍卫了牛头人幼崽进行初次试炼的训练场，保护了你的长者和新手免受残酷的野猪人围攻。"},sec={{t="针对台地的阴谋",b="这些潦草的战术草图藏在刺刃峡谷深处的一个泥洞里，揭示了刺背野猪人已不再仅仅是在红云台地的边缘进行小规模冲突。相反，他们的领导层计划发起一场有组织、持续性的突袭，以攻入纳拉其营地，并消灭在那里进行训练的牛头人幼崽。将这张地图交给鹰风酋长，部落就能向血蹄村发出求援信号，从而在即将到来的入侵开始前将其扼杀在萌芽之中。"}},faq={{q="刺背野猪人的进攻计划中包含了什么内容？",a="这些计划包括一张战术地图和粗略的指令，详细说明了针对纳拉其营地的全面围攻，表明野猪人正在组织一场持久的袭击，而不仅仅是零星的劫掠。",al={"进攻计划是什么","地图上画了什么","刺背作战计划"}},{q="这些计划在哪里可以找到？",a="它们被遗弃在刺刃峡谷一个高处洞穴的泥地上，就在通往刺背野猪人酋长小屋的一条小路旁。",al={"计划在哪里","我在哪里能找到地图","刺背野猪人进攻计划位置"}},{q="鹰风酋长在收到这些计划后会做什么？",a="鹰风酋长认识到了台地所面临的紧迫危险，并利用这些情报从血蹄村召集援助和勇士，以加强纳拉其营地的防御。",al={"鹰风酋长会做什么","纳拉其营地的反应","鹰风酋长的反应"}},{q="为什么刺背野猪人要攻击纳拉其营地？",a="刺背部族声称对这些布满荆棘的峡谷拥有领土主权，并充满敌意地将台地上的牛头人视为入侵者，这驱使他们试图彻底将该定居点驱逐出去。",al={"为什么野猪人在攻击","刺背野猪人的动机"}}},fx={["166f21b1"]={q="刺背野猪人的进攻计划来自哪里？",a="这些计划源于刺刃峡谷深处，由刺背野猪人的战酋起草。它被放置在一张隐藏在洞穴网络中的粗糙地图上，详细记录了该部落对纳拉其营地的牛头人定居点发起长期围攻的协调计划。",al={"谁制作了刺背野猪人的进攻计划","刺背野猪人进攻计划的来源","谁写了刺背野猪人的进攻计划"}},aea2975f={q="为什么鹰风酋长需要刺背野猪人的进攻计划？",a="鹰风酋长需要这些计划，因为它们揭露了野猪人围攻纳拉其营地的阴谋。手握这一即将到来的威胁证据，酋长可以立即呼叫附近血蹄村的增援，以准备防御并在定居点被攻陷之前挫败这次攻击。",al={"为什么要刺背野猪人的进攻计划","鹰风酋长想要进攻计划的原因","刺背野猪人进攻计划的意图"}}},fp="24,212,23.494.0,45.200.0,28.143.0,55.171.1,47.208.0"}
P.entries["item:bristleback-belt"] = {n="刺背腰带",s="刺背腰带是那些盘踞在刺刃峡谷的野猪人所穿戴的粗制装备。对于在纳拉其营地成年的牛头人后辈来说，收集这些腰带是力量试炼中证明自己勇气的实物证据。",h="刺背腰带是那些盘踞在刺刃峡谷的野猪人所穿戴的粗制装备。对于在纳拉其营地成年的牛头人后辈来说，收集这些腰带是力量试炼中证明自己勇气的实物证据。",kw={"腰带","刺刃峡谷","刺背","纳拉其营地","鹰风酋长","野猪人","红云台地","力量试炼"},ang={["faction:Horde"]="遏制莫高雷好战的野猪人，可以确保部落在中部卡利姆多的核心地带南部边界的安全。",["race:Tauren"]="夺取倒下的刺背野猪人的腰带，是红云台地每一位年轻人的成年礼，标志着他们向获得雷霆崖长老认可迈出了第一步。"},sec={{t="试炼的证明",b="红云台地的部落会考验每一位渴望在雷霆崖赢得尊重的年轻人，考验的方式是古老的大地母亲试炼。第一项考验，即力量试炼，要求受试者保护部落免受现实威胁。由于充满敌意的刺背野猪人反复劫掠部落的粮食储备，并在纳拉其营地外伏击狩猎队，鹰风酋长要求带回这些入侵者的腰带。上交十二条腰带给酋长，证明了一位受试者能够直面危险，并为保卫部落做出贡献。"},{t="野猪人的工艺",b="这些腰带是从刺刃峡谷各处的刺背野猪人战士和萨满身上剥下的，由粗糙的兽皮、麻绳和废料制成。虽然对牛头人战士来说它们毫无穿着价值，但它们带有鲜明的野猪人特征，是击杀敌人的确凿证据。将它们带回营地中心即可满足试炼所需的证明。"}},faq={{q="刺背腰带有什么用？",a="纳拉其营地的鹰风酋长需要十二条刺背腰带，作为受试者已经完成力量试炼（大地母亲传统试炼的第一项）的实物证明。",al={"为什么我需要刺背腰带","刺背腰带的用途","这腰带有什么用"}},{q="刺背腰带从哪里获取？",a="它们是从居住在刺刃峡谷内的刺背野猪人和刺背萨满身上获取的，刺刃峡谷位于纳拉其营地以东的红云台地。",al={"哪里能获得刺背腰带","谁掉落刺背腰带","刺背腰带位置"}},{q="为什么鹰风酋长想要腰带，而不是脑袋或武器？",a="腰带是受试者已经击杀部落敌人的便携式证明。试炼特别要求提供腰带，但并没有解释为什么比起其他战利品，它们被选中了。",al={"为什么是腰带","鹰风酋长的证明"}},{q="为什么要针对刺背野猪人？",a="刺背野猪人从刺刃峡谷侵入了部落领地，它们趁夜色袭击纳拉其营地，并在台地各处伏击牛头人狩猎队。",al={"为什么要杀刺背野猪人","莫高雷的野猪人威胁"}}},fx={["69faf7fa"]={q="什么是刺背腰带？",a="刺背腰带是栖息在刺刃峡谷中的刺背野猪人所穿戴的简单服饰。这些粗糙的皮革或绳索腰带是从被击败的袭击者身上剥下来的，它们是无可辩驳的战斗战利品，向部落长老证明了入侵的威胁已经得到对抗并被消灭。",al={"刺背腰带","什么是刺背腰带","刺背腰带物品"}},d50579da={q="刺背腰带从何而来，由谁制作？",a="这些腰带是由在刺刃峡谷（纳拉其营地以东）建立了一处荆棘丛生定居点的刺背野猪人制作的。他们的前线战士和萨满在与红云台地的牛头人发生冲突时都会佩戴它们。",al={"刺背腰带从何而来","谁制作刺背腰带","刺背腰带的起源"}}},fp="16,239,17.547.0,14.362.0,36.190.0,37.150.0,63.182.0,40.168.0"}
P.entries["item:bristleback-quilboar-tusk"] = {n="刺背野猪人的獠牙",s="刺背野猪人的獠牙是从贫瘠之地北部和中部被杀死的刺背野猪人身上获取的。作为屠戮的证明被收集起来，对于悲痛的兽人战士曼科里克来说，这些是复仇的血腥信物。",h="刺背野猪人的獠牙是从贫瘠之地北部和中部被杀死的刺背野猪人身上获取的。作为屠戮的证明被收集起来，对于悲痛的兽人战士曼科里克来说，这些是复仇的血腥信物。",kw={"贫瘠之地","刺背","被仇恨吞噬","十字路口","曼科里克","野猪人","獠牙"},ang={["faction:Horde"]="野猪人威胁着十字路口和横穿贫瘠之地的补给路线；收集獠牙既有助于曼科里克的个人复仇，也支持了部落平定该地区的更广泛努力。",["race:Orc"]="兽人理解血债和战士的悲痛，这使得曼科里克收集六十根野猪人獠牙的残酷任务成为了一种共同的荣誉。"},sec={{t="复仇的战利品",b="刺背野猪人栖息在遍布贫瘠之地的灌木丛和荆棘巢穴中，激烈地守卫着它们的领地以抵御部落的扩张。它们的獠牙是突出的锯齿状象牙，在近战中被用作天然武器。对于驻守在十字路口、妻子在一次邪恶的野猪人伏击中失踪的资深战士曼科里克来说，这些獠牙不仅仅是简单的猎人战利品。收集数十个獠牙是一种纯粹的报复手段，是一种血腥的计数，旨在确保刺背野猪人承受和他一样深重的痛苦。"}},faq={{q="谁需要这些獠牙？",a="驻守在贫瘠之地十字路口的兽人战士曼科里克需要它们。在一次导致他与妻子失散的惨痛伏击之后，他寻求向刺背野猪人复仇。",al={"谁需要刺背獠牙","谁收集刺背野猪人獠牙","獠牙上交"}},{q="为什么曼科里克需要这么多獠牙？",a="曼科里克在被野猪人袭击者击败并被抛弃等死后，心中充满了悲痛和愤怒。收集六十根獠牙为他提供了切实的证据，证明刺背野猪人部落正在遭到无情的报复性屠杀。",al={"为什么要60根獠牙","曼科里克为什么想要獠牙","曼科里克复仇"}},{q="哪些野猪人携带这些獠牙？",a="它们是从在贫瘠之地北部和中部灌木丛和荆棘营地中游荡的刺背部落成员身上获取的。",al={"刺背獠牙掉落地点","谁掉落刺背野猪人獠牙"}},{q="除了曼科里克的复仇之外，这些獠牙还有其他用途吗？",a="没有。虽然野猪人的獠牙有时可以用于制作部落小饰品或作为贸易商品，但这些特定的战利品仅仅是为了满足曼科里克的复仇渴望而收集的。",al={"刺背獠牙用途","野猪人獠牙能用于制作吗"}}},fx={a893c973={q="什么是刺背野猪人的獠牙？",a="这些是从在贫瘠之地游荡的被杀死的刺背野猪人身上割下的獠牙。对于野猪人来说，这是天生的特征和凶猛的标志，但对于平原上的猎人来说，它们是证明又有一头野兽被杀死的惨烈实证。",al={"刺背野猪人的獠牙","什么是刺背野猪人的獠牙","刺背獠牙"}},fe8719fb={q="刺背野猪人的獠牙从何而来？",a="它们是直接从贫瘠之地各地刺背野猪人的下颚上收割的。野猪人天生就会长出这些尖锐的獠牙，要获取它们，就必须在战斗后从被击败的敌人身上割下来。",al={"刺背獠牙从何而来","谁掉落刺背野猪人的獠牙","刺背野猪人的獠牙来源"}}},fp="25,231,21.526.0,22.195.0,36.217.0,33.138.0,63.171.0"}
P.entries["item:brock-s-list"] = {n="布洛克的名单",s="“布洛克的名单”是一份由塞尔萨玛的采矿导师布洛克·寻石者编制的调度文件。名单中记载着那些赢得了铁炉堡公会大厅颁发的荣誉锄的顶尖采矿学员的名字。",h="“布洛克的名单”是一份由塞尔萨玛的采矿导师布洛克·寻石者编制的调度文件。名单中记载着那些赢得了铁炉堡公会大厅颁发的荣誉锄的顶尖采矿学员的名字。",kw={"布洛克的名单","高尼尔·石趾","great forge","铁炉堡","洛克莫丹","采矿","塞尔萨玛","索格拉姆·伯雷森"},ang={["profession:Mining"]="对于勘探者来说，布洛克的名单代表着学徒们正式超越了粗砺的碎石，跨入了深山采矿公会引以为傲的传统之中。",["race:Dwarf"]="这份羊皮纸反映了矮人的工艺传承，旨在表彰那些在卡兹莫丹地下展现出对十字镐和铁锹奉献精神的年轻人。"},sec={{t="矿工的殊荣",b="采矿是矮人文明的命脉，采矿学徒在被委以卡兹莫丹矿脉的重任之前，必须证明自己的技艺。在塞尔萨玛，当地的采矿训练师编制了这份羊皮纸，以奖励那些学业出众的学生。这份文件记录了那些赢得了“荣誉锄”——这种在首都锻造、象征着能力的抢手工具——的学生名单。"},{t="通往Great Forge之路",b="由于荣誉工具必须在首都刻字并进行分发，这份羊皮纸被托付给前往铁炉堡的旅人。布洛克的名单通过塞尔萨玛的狮鹫管理员，搭乘狮鹫直接送往Great Forge深山采矿公会的高尼尔·石趾手中，在那里，受表彰学员的名字会被镌刻在石材和钢铁之上。"}},faq={{q="什么是布洛克的名单？",a="这是一份由塞尔萨玛的采矿训练师布洛克·寻石者所写的花名册。它详细列出了那些在采矿教学中取得优异成绩并获得仪式用锄资格的学徒。",al={"布洛克的名单","这是什么物品","布洛克名单的用途"}},{q="我该把布洛克的名单交给谁？",a="首先你需要把名单出示给塞尔萨玛的狮鹫管理员索格拉姆·伯雷森以获得通行许可。然后，你要把它直接送到铁炉堡的Great Forge内部，交给深山采矿公会的高尼尔·石趾。",al={"我该把名单带到哪里","谁会收到布洛克的名单","布洛克的名单上交"}},{q="为什么高尼尔·石趾需要这份文件？",a="高尼尔负责管理铁炉堡深山采矿公会的工具。他准备了一箱荣誉锄，需要布洛克的书面花名册，以便将每位学生的名字凿刻在他们的奖品上。",al={"为什么是高尼尔","为什么铁炉堡需要这份名单"}},{q="为什么这份名单是用狮鹫运送而不是步行？",a="虽然穿过洛克莫丹的山路可以通往丹莫罗，但通过狮鹫管理员索格拉姆·伯雷森搭乘狮鹫，是将公会事务直接送达Great Forge最快且最安全的方式。",al={"为什么飞往铁炉堡","为什么乘坐狮鹫"}}},fx={bca439a3={q="布洛克的名单从何而来，由谁制作？",a="这份名单是由布洛克·寻石者书写的，他是一位在洛克莫丹的塞尔萨玛镇工作的资深矿工。当年轻的矮人来到他的门下学习手艺时，布洛克会评估他们的进步，并起草这份名册，记录下那些因辛勤工作而获得特别认可的杰出学生。",al={"谁制作了布洛克的名单","布洛克的名单从何而来","布洛克的名单创造者"}}},fp="12,201,21.384.0,27.365.0,21.191.0,33.217.0,46.199.0,49.221.0"}
P.entries["item:broken-and-battered-samophlange"] = {n="破碎的主动式负载平衡器",s="破碎的主动式负载平衡器是一个从荆棘谷地精在贫瘠之地的行动中回收的神秘机械装置。在一次拙劣的修补尝试将其结构完整性推向临界低点后，它必须被送往奥格瑞玛的地精专家那里，他们或许能真正理解它是如何运作的。",h="破碎的主动式负载平衡器是一个从荆棘谷地精在贫瘠之地的行动中回收的神秘机械装置。在一次拙劣的修补尝试将其结构完整性推向临界低点后，它必须被送往奥格瑞玛的地精专家那里，他们或许能真正理解它是如何运作的。",kw={"贫瘠之地","机械商店","诺格","奥格瑞玛","rilli greasygob","主动式负载平衡器","荆棘谷地精","wenikee boltbucket"},ang={["faction:Horde"]="管理从荆棘谷地精在贫瘠之地的开发行动中回收的工业废料，将宝贵的技术秘密直接带到了奥格瑞玛的地精机械商店。",["profession:Engineering"]="在不稳定的荆棘谷地精机制上草率地增加刻度盘和杠杆，这成为了一个教科书般的警告，提醒人们不要在没有蓝图的情况下进行随意的修改。"},sec={{t="修补得面目全非",b="主动式负载平衡器是一种晦涩的专利机械部件，由荆棘谷地精为他们在贫瘠之地北部的资源行动而设计。当Wenikee Boltbucket试图检查和修改其中一个时，她附加了无关的测量仪、杠杆和刻度盘来测量其稳定性。她的业余干预不仅没有稳定该机制，反而彻底破坏了它的结构完整性，使其破损不堪，濒临报废。意识到更多的装置只会导致彻底的故障，她将这个脆弱的组件打包送给了一个真正有工厂经验的人。"},{t="通往奥格瑞玛之路",b="回收这个破碎的装置需要那些曾直接在荆棘谷地精生产线上工作过的人的见解。这指引旅行者找到了Rilli Greasygob，一位前荆棘谷地精员工，现在在奥格瑞玛Valley of Honor的诺格的机械商店工作。交出这样一个破损的设备立刻引起了这位工程师的注意，并将任何敢于从地精行动中搜刮东西的人标记为非常大胆或愚蠢。"}},faq={{q="什么是主动式负载平衡器？",a="主动式负载平衡器是荆棘谷地精为他们在贫瘠之地的工业行动制造的一种专业机械部件。其确切的内部机械结构是奥术般的地精工程秘密，很少有局外人能完全理解。",al={"什么是该物品","主动式负载平衡器的功能","主动式负载平衡器的用途"}},{q="为什么主动式负载平衡器会破碎不堪？",a="Wenikee Boltbucket试图用额外的测量仪对其进行修改，以评估其结构完整性。她的添加完全适得其反，损害了设备的稳定性并损坏了其敏感的内部组件。",al={"谁弄坏了主动式负载平衡器","为什么它损坏了","wenikee弄坏的"}},{q="谁能修理这个受损的设备？",a="该设备需要有荆棘谷地精机械经验的人。它被带到了Rilli Greasygob那里，一位在奥格瑞玛Valley of Honor的诺格的机械商店工作的工程师。",al={"我该把它交给谁","主动式负载平衡器要去哪里","谁负责修理"}},{q="这个机械装置最初来自哪里？",a="它起源于荆棘谷地精在贫瘠之地北部的钻探和开采行动，那里的地精工程师用它来为重型开采机械提供动力。",al={"主动式负载平衡器的起源","它是在哪里被发现的","荆棘谷地精的起源"}}},fx={["35e2c2bf"]={q="为什么Rilli Greasygob想要破碎的主动式负载平衡器？",a="Wenikee Boltbucket试图通过增加额外的测量仪来修补这个精密设备，结果导致其结构完整性降到了历史最低点。由于承认进一步的修补可能会完全毁掉它，Wenikee派你去把这台损坏的装置送到奥格瑞玛的Nogg's Machine Shop交给Rilli Greasygob。作为荆棘谷地精的前员工，Rilli拥有修理其专业机器的技术专长。",al={"为什么要带负载平衡器给rilli","谁想要破碎的主动式负载平衡器","为什么rilli想要负载平衡器"}}},fp="31,309,27.565.0,21.445.0,22.229.0,43.222.0,35.182.0,46.169.0"}
P.entries["item:broken-samophlange"] = {n="损坏的主动式负载平衡器",s="损坏的主动式负载平衡器是一件从贫瘠之地北部回收而来的神秘机械装置。尽管它已经损坏，但其内部的齿轮和传动部件依然让那些好奇心十足、想要发掘其真实用途的工程师们着迷。",h="损坏的主动式负载平衡器是一件从贫瘠之地北部回收而来的神秘机械装置。尽管它已经损坏，但其内部的齿轮和传动部件依然让那些好奇心十足、想要发掘其真实用途的工程师们着迷。",kw={"贫瘠之地","损坏的主动式负载平衡器","齿轮","莫尔杉壁垒","主动式负载平衡器","安德麦","威尼基·爆桶"},ang={["faction:Horde"]="该装置在贫瘠之地的部落领地中浮出水面，促成了当地哨站、修补匠和中立贸易联络人之间的合作。",["profession:Engineering"]="主动式负载平衡器代表了工程师们无法抗拒的经典谜题：一台拥有精密内部齿轮结构的复杂机器，其目的只能通过拆解并使其运行来确定。"},sec={{t="令人困惑的装置",b="主动式负载平衡器仍然是贫瘠之地北部发现的众多奇异装置中最令人费解的一个。即使是在损坏的状态下，该装置也展现出了非凡的内部工艺，充满了活动的装配零件和精密的齿轮。棘齿城的侏儒斯布特瓦夫在还没来得及记录其完整运作过程之前，就意外损坏了这个精巧的设备。为了向安德麦那些好奇的同行们展示成果，发现者寻求能工巧匠来修复它，并找到了威尼基·爆桶——一位驻扎在莫尔杉壁垒边境前哨站附近的聪明修补匠。"},{t="寻找修补匠的援手",b="在检查了这个报废的设备后，即便是像威尼基这样善于钻研的人，也无法立刻推断出主动式负载平衡器究竟是用来做什么的。然而，内部发条装置发出的诱人声响和其动态的运转，立刻引起了她的兴趣。与其将这堆破烂丢弃，其设计的奥秘反而激发了她尝试修复它，并亲眼见证其机械结构全力运转的欲望。"}},faq={{q="什么是主动式负载平衡器？",a="它的确切功能至今仍是个谜，即使是对那些试图修理它的修补匠们来说也是如此。虽然它的名字让观察者感到困惑，但接触该设备后会发现，里面装有复杂的齿轮和活动部件，显然是为了某种未知的工业目的而设计。",al={"主动式负载平衡器的目的","主动式负载平衡器有什么用","主动式负载平衡器的定义"}},{q="为什么主动式负载平衡器会坏？",a="棘齿城的斯布特瓦夫在拿到它后，因胡乱摆弄而损坏了其精密的机械结构。在意识到该装置在将其秘密分享给安德麦的同事之前就已经卡死后，他们便寻求专家来让它重新运转。",al={"它是怎么坏的","损坏的主动式负载平衡器背景故事"}},{q="谁是威尼基·爆桶？",a="威尼基·爆桶是一位位于贫瘠之地北部的好奇修补匠，就在与灰谷接壤的莫尔杉壁垒以南。她拥有检查和重建奇异装置所需的工程好奇心。",al={"威尼基在哪里","爆桶的位置"}},{q="为什么安德麦的地精对它感兴趣？",a="地精工程师和企业家总是热衷于逆向工程独特的机械技术。关于这种奇怪装置的消息传到了安德麦的联络人耳中，促使他们对其可能带来的任何优势产生了即时的兴趣。",al={"安德麦的兴趣","为什么地精在意这个"}}},fp="18,223,20.570.0,24.409.0,22.209.0,30.263.0,26.230.0,46.234.0"}
P.entries["item:broken-tools"] = {n="损坏的工具",s="损坏的工具是矮人勘探员镐的破碎残骸，被人故意在铁砧上摧毁。它们是贝恩·血蹄手中实实在在的证据，证明威胁到莫高雷土地和野生动物的入侵性矮人挖掘行动已经遭到了破坏。",h="损坏的工具是矮人勘探员镐的破碎残骸，被人故意在铁砧上摧毁。它们是贝恩·血蹄手中实实在在的证据，证明威胁到莫高雷土地和野生动物的入侵性矮人挖掘行动已经遭到了破坏。",kw={"贝恩·血蹄","损坏的工具","挖掘点","矮人挖掘","熔炉","莫高雷","勘探员之镐"},ang={["profession:Blacksmithing"]="利用铁砧系统地销毁精致的矮人铁器，将工匠的熔炉变成了领土防御的工具。",["race:Tauren"]="对于牛头人来说，将损坏的工具带给贝恩，代表着为了保卫大地母亲而对抗那种折磨本土野兽的入侵性挖掘行为。"},sec={{t="破坏挖掘行动",b="在血蹄村西北方，矮人挖掘者们建立了一个营地，想要深入莫高雷的群山。虽然矮人们试图寻找埋藏的古代历史，但牛头人视其粗暴的挖掘行为为对大地母亲的直接亵渎。挖掘产生的噪音和破坏搅扰了当地的野生动物，尤其是游荡的科多兽群。年轻的贝恩·血蹄并没有选择简单地驱逐这些挖掘者，而是指示守卫们没收勘探员的铁镐，并将它们在熔炉上砸碎，使探险队无法继续挖掘土地。"}},faq={{q="这些“损坏的工具”是什么？",a="它们是勘探员之镐被损毁的镐头和断裂的柄，是从莫高雷的矮人挖掘者手中夺来的，并被人刻意在熔炉上摧毁。",al={"损坏的工具","什么是损坏的工具","破碎的镐"}},{q="为什么贝恩·血蹄想要摧毁它们？",a="贝恩认为，翻开土壤亵渎了大地，并激怒了莫高雷的野生动物，尤其是科多兽。砸碎他们的工具可以阻止挖掘，并传达一个明确的信息：这片土地不会向鲁莽的挖掘行为交出它的智慧。",al={"为什么要摧毁镐","为什么贝恩想要损坏的工具","贝恩与矮人挖掘"}},{q="在什么地方可以砸碎这些镐？",a="任何功能正常的铁匠熔炉都可以。你可以使用直接位于矮人挖掘点的熔炉，也可以前往血蹄村或雷霆崖的熔炉。",al={"如何砸碎镐","熔炉在哪里","砸碎勘探员之镐"}},{q="为什么矮人在莫高雷挖掘？",a="矮人们认为莫高雷的土壤下埋藏着深层的秘密和古代遗物。在对自身起源的执着探索中，他们经常不顾当地居民的感受，将异国土地挖得千疮百孔。",al={"为什么矮人在莫高雷","矮人挖掘点莫高雷"}}},fx={["76aab525"]={q="这些损坏的工具从何而来？",a="这些破损的工具原本是矮人勘探者锻造和携带的坚固矿工锄。为了寻找莫高雷地下的泰坦遗物和古老秘密，探险队带来了他们的铁制工具来开凿大地。通过将这些完好的锄头运到熔炉并砸成碎片，你将他们的采矿装备变成了无法使用的废料，然后将其交还给牛头人，作为挖掘活动已停止的证据。",al={"损坏的工具起源","谁制作了损坏的工具","损坏的工具从何而来"}}},fp="12,250,18.570.0,28.152.0,45.239.0,32.165.0,35.218.0"}
P.entries["item:bundle-of-crocolisk-skins"] = {n="一捆鳄鱼皮",s="“一捆鳄鱼皮”是从湿地危险的沼泽中采集的爬行动物皮经过处理后制成的包裹。它是为米奈希尔港的制皮师准备的，可作为制作坚固靴子和耐用港口装备的贵重交易物资。",h="“一捆鳄鱼皮”是从湿地危险的沼泽中采集的爬行动物皮经过处理后制成的包裹。它是为米奈希尔港的制皮师准备的，可作为制作坚固靴子和耐用港口装备的贵重交易物资。",kw={"鳄鱼","einar","詹姆斯·哈洛兰","皮革","米奈希尔港","塞达","兽皮","湿地"},ang={["faction:Alliance"]="偏远地区的猎人们提供了所需的材料，使米奈希尔港的驻军和公民能够装备齐全，以抵御恶劣的沼泽环境。"},sec={{t="湿地的商业与家庭纠纷",b="湿地辽阔的水道中鳄鱼横行，它们坚韧且防水的皮是米奈希尔港这个沿海定居点不可或缺的商品。敢于挑战沼泽的猎人们在采集并处理这些兽皮后，会将它们向西运送给詹姆斯·哈洛兰等当地工匠。然而，这捆特殊的兽皮意外落入了冒险者手中：猎人Einar寻找信使纯粹是为了避免回到镇上，面对他那满腹怨气的妻子塞达。"}},faq={{q="一捆鳄鱼皮有什么用？",a="这捆兽皮由粗制但已处理过的沼泽兽皮组成，目的地是米奈希尔港的制皮师詹姆斯·哈洛兰。哈洛兰会将这些粗糙的兽皮加工成耐用的靴子、腰带和皮甲，非常适合在湿地潮湿且被洪水淹没的地形中穿戴。",al={"鳄鱼皮用途","这些皮的用途","兽皮包裹的目的"}},{q="谁采集了这些鳄鱼皮？",a="这些兽皮是由在沼泽中活动的猎人Einar采集并捆扎的。虽然他通常会亲自将交易物资带进镇里，但他这次却请求路过的旅行者代劳，以避免与他的妻子塞达发生争吵。",al={"谁制作的包裹","谁采集的兽皮","einar 鳄鱼"}},{q="詹姆斯·哈洛兰是谁？",a="詹姆斯·哈洛兰是一位在港口城镇米奈希尔港工作的制皮师和鞣皮匠。他从当地的沼泽猎人那里购买生皮和熟皮，为水手、士兵和镇民制作靴子、鞣制皮革以及实用的装备。",al={"詹姆斯·哈洛兰的角色","哈洛兰是谁","米奈希尔鞣皮匠"}}},fx={["639d94c2"]={q="什么是“一捆鳄鱼皮”？",a="它是一包从潜伏在Wetlands的危险鳄鱼身上收割的生皮。埃纳尔·石钳将它们收集并捆在一起，打算卖给米奈希尔港的当地工匠，但个人的麻烦使他无法亲自交付这些货物。",al={"什么是“一捆鳄鱼皮”","一捆鳄鱼皮"}},["8cc4b9e1"]={q="为什么詹姆斯·哈洛兰想要“一捆鳄鱼皮”？",a="詹姆斯·哈洛兰在米奈希尔港担任制皮匠，依靠稳定的新鲜兽皮供应来为居民和旅行者制作优质的皮靴和硬化护甲。生鳄鱼皮提供了他进行交易和补充库存所需的坚韧、耐用的材料。",al={"为什么詹姆斯·哈洛兰需要兽皮","为什么想要“一捆鳄鱼皮”","詹姆斯·哈洛兰鳄鱼皮"}}},fp="25,265,37.497.0,47.262.0,35.234.0,22.239.0"}
P.entries["item:bundle-of-hides"] = {n="一捆兽皮",s="一捆兽皮包含从贫瘠之地的野兽身上收集并经过硝制的兽皮，为了横跨卡利姆多中部运输而被捆扎在一起。这些兽皮是送往雷霆崖皮匠们的货物，这是一次直接的快递运输，也向旅行者介绍了部落的双足飞龙飞行网络。",h="一捆兽皮包含从贫瘠之地的野兽身上收集并经过硝制的兽皮，为了横跨卡利姆多中部运输而被捆扎在一起。这些兽皮是送往雷霆崖皮匠们的货物，这是一次直接的快递运输，也向旅行者介绍了部落的双足飞龙飞行网络。",kw={"安哈努","贫瘠之地","一捆兽皮","十字路口","迪弗拉克","希瓦的军械库","加翰","制皮","雷霆崖","双足飞龙"},ang={["faction:Horde"]="像兽皮这样简单的货物通过空中运输，突显了部落如何利用双足飞龙飞行路线将孤立的沙漠前哨站与主权首都直接连接起来。",["race:Tauren"]="牛头人依靠天然材料和虔诚的狩猎，将邻近稀树草原上的兽皮转化为在莫高雷摊位上出售的护甲和工艺品。"},sec={{t="边境贸易",b="贫瘠之地的荒原上栖息着成群的科多兽、徘徊的狮子和游荡的迅猛龙。贸易路线上的猎人剥取这些生物的皮，不仅是为了获取肉食以求生存，也是为了供应城市的工匠。没有来自野外的生皮，像雷霆崖这样的定居点就难以支撑当地的制皮匠，这些工匠将干燥的兽皮转化为部落所需的必要装备、袋子、护甲和绑带。"},{t="天空货运",b="通过陆路在贫瘠之地运输重物并送往莫高雷既危险又缓慢，时刻受到游荡的野猪人和半人马劫掠者的威胁。为了加快十字路口和牛头人首都之间的交付速度，信使们依靠迪弗拉克的训练有素的双足飞龙。将一捆兽皮交给双足飞龙信使，展示了在卡利姆多崎岖地形上进行空中旅行的绝对效率。"}},faq={{q="一捆兽皮有什么用？",a="这些兽皮是从贫瘠之地的动物身上采集的，目的是交给雷霆崖的皮匠安哈努。他利用这些兽皮为牛头人和他们的部落盟友制作皮制品和装备。",al={"一捆兽皮的用途","为什么要运输兽皮","兽皮有什么用"}},{q="谁在雷霆崖接收货物？",a="安哈努接收这个包裹。他在雷霆崖双足飞龙管理员平台正下方的希瓦的军械库工作。",al={"谁接收兽皮","一捆兽皮的收件人","安哈努在哪里"}},{q="为什么要通过双足飞龙运送这捆兽皮？",a="穿越贫瘠之地并徒步登上莫高雷的平顶山需要数天时间，而且还要冒着被半人马或野猪人伏击的风险。骑着双足飞龙并与十字路口的飞行管理员迪弗拉克同行，可以确保货物迅速且安全地到达。",al={"为什么要用飞行运送兽皮","十字路口飞行运送兽皮","迪弗拉克 双足飞龙"}},{q="是谁在贫瘠之地准备了这捆兽皮？",a="这些兽皮是由十字路口的皮革与锁甲护甲商人，同时也是安哈努的同行加翰·鹰翼捆扎的，兽皮均来自贫瘠之地的动物。",al={"谁提供了兽皮","加翰 兽皮","谁收集了皮毛"}}},fx={["2b9c2280"]={q="什么是“一捆兽皮”？",a="“一捆兽皮”是从在贫瘠之地游荡的野生野兽身上收集的生皮包裹。它在十字路口附近收集并准备，是旨在出口到雷霆崖的关键制作材料，那里的熟练制皮师将坚韧的边疆兽皮转化为护甲、服装和基本的贸易商品。",al={"什么是“一捆兽皮”","“一捆兽皮”物品","“一捆兽皮”背景传说"}}},fp="15,302,14.424.0,15.402.0,37.204.0,43.131.0,38.239.0,39.148.0"}
P.entries["item:bundle-of-wood"] = {n="一捆木柴",s="一捆木柴是艾尔文森林东部东谷伐木场附近的工人们砍伐并捆扎好的木材。由于野生动物的侵扰，它们最近被遗弃在野外，这些木材是完成当地木材合同所需的关键物资。",h="一捆木柴是艾尔文森林东部东谷伐木场附近的工人们砍伐并捆扎好的木材。由于野生动物的侵扰，它们最近被遗弃在野外，这些木材是完成当地木材合同所需的关键物资。",kw={"一捆木柴","东谷","艾尔文","伐木场","木材","雷伦","原木"},ang={["faction:Alliance"]="每一捆找回的木材都直接支持着暴风城的重建工作，确保重要的木材运输能够按时送达艾尔文森林和西部荒野各地的定居点。"},sec={{t="废弃的木材",b="东谷伐木场是暴风城王国的主要木材来源，源源不断地向西运送新砍伐的木材，以维持城镇基础设施和建设项目的需求。最近，当地极具攻击性的野生动物——特别是森林熊和潜行的狼——闯入了伐木场西北侧的树林。惊恐的伐木工四散奔逃，将刚收集好的一捆木柴丢弃在树林中。面对紧迫的交付期限，伐木场监工只能依靠勇敢的旅行者溜过这些捕食者，在违约之前找回这些砍伐好的木材。"}},faq={{q="为什么这些木柴被遗弃在森林里？",a="在东谷伐木场西北侧采伐木材的工人们遭到了潜伏在林中的凶猛狼群和熊的伏击，被迫撤离，留下了散落在林地上的木捆。",al={"为什么地上有木头","为什么要放弃木材","艾尔文废弃木材"}},{q="谁需要收集这些木材？",a="东谷伐木场的监工雷伦急需收集这些木材，以赶上即将到来的木材运输截止日期。",al={"谁想要这些木材","雷伦木材","木材上交"}},{q="这些木捆在哪里能找到？",a="它们散落在东谷伐木场正西北方的地面上，位于艾尔文森林熊和狼出没的茂密林带之中。",al={"一捆木柴位置","木材在哪里","东谷木材点"}},{q="为什么城镇卫兵没有清除这些野兽？",a="雷伦曾就野兽侵扰一事联系过瑞尼尔副队长，但当地治安官和卫兵在整个艾尔文森林的人手捉襟见肘，迫使伐木工寻求外界帮助，以便尽快找回他们的原木。",al={"为什么没有卫兵","瑞尼尔副队长木材","东谷的卫兵"}}},fx={e892b12c={q="什么是“一捆木柴”？",a="这些是东谷伐木场的工人们砍伐并收集的新鲜木材堆。它们为运输和加工做好了准备，代表了伐木场在艾尔文森林东部的持续伐木作业。",al={"什么是“一捆木柴”","艾尔文森林的“一捆木柴”","这些木柴捆是什么"}}},fp="14,90,16.462.0,54.189.0,30.125.0,30.129.0,48.189.0"}
P.entries["item:burning-blade-medallion"] = {n="火刃奖章",s="火刃奖章是一个阴暗的护身符，由潜伏在试炼谷的邪教徒随身携带。它被火刃集会所深处的黑暗魔法所守护，是恶魔腐化试图颠覆杜隆塔尔年轻勇士的直接证据。",h="火刃奖章是一个阴暗的护身符，由潜伏在试炼谷的邪教徒随身携带。它被火刃集会所深处的黑暗魔法所守护，是恶魔腐化试图颠覆杜隆塔尔年轻勇士的直接证据。",kw={"火刃集会所","火刃奖章","杜隆塔尔","地狱犬","护身符","试炼谷","yarrog baneshadow","祖雷萨"},ang={["class:Warlock"]="虽然部落术士在严格的纪律下修习黑暗魔法，但这枚奖章代表了火刃氏族那种失控的、不受约束的邪能技艺，这威胁到了杜隆塔尔的稳定。",["race:Orc"]="这枚奖章代表了曾经奴役兽人种族的恶魔腐化所留下的阴影，如今在年轻的学徒甚至还没离开试炼谷之前，就已经威胁到了他们。"},sec={{t="腐化的印记",b="这枚奖章在火刃集会所蜿蜒的洞穴深处被发现，由邪恶的火刃氏族邪教特工Yarrog Baneshadow持有。通过祖雷萨的占卜确认，这个饰品在邪教的小鬼仆从和地狱犬之间引导着黑暗力量。击杀它的持有者并夺回奖章，可以阻止这一在杜隆塔尔内部破坏部落训练场的阴险企图。"}},faq={{q="火刃奖章是什么？",a="它是由隐藏在杜隆塔尔的火刃氏族邪教特工Yarrog Baneshadow随身携带的魔法护身符。这枚奖章是黑暗魔法的焦点，也是邪教徒之间效忠的象征。",al={"火刃护身符","集会所奖章","yarrog的奖章"}},{q="谁想要找回这枚奖章？",a="祖雷萨，一位驻扎在试炼谷大兽穴外的兽人预言者，她寻求夺回奖章以根除恶魔的影响，并研究该邪教在当地的阴谋。",al={"谁拿走了奖章","在哪里上交奖章","祖雷萨任务"}},{q="这枚奖章在哪里可以找到？",a="它位于火刃集会所的深处，这是一个坐落在试炼谷大兽穴西北方向的隐蔽洞穴。它由Yarrog Baneshadow守护，他潜伏在洞穴的上层岩架边。",al={"yarrog baneshadow在哪里","火刃奖章位置","如何找到奖章"}},{q="奖章的出现对杜隆塔尔意味着什么？",a="它的发现证实了火刃氏族邪教已经将特工安插进了部落的试炼场，预示着这些邪教徒在兽人故土上有着更广泛且更危险的野心。",al={"为什么邪教徒在试炼谷","火刃氏族在杜隆塔尔吗"}}},fp="23,268,20.452.0,36.208.0,34.171.0,29.192.0,52.215.0"}
P.entries["item:burning-blood-quest-item"] = {n="Burning Blood (quest item)",s="燃烧之血是一种从徘徊在暮色森林的凶猛Nightbane狼人身上采集到的非自然流体。暴风城的护甲商格里曼德·埃尔摩需要二十瓶这种炽热的精华，以便试验高级锻造技术。",h="燃烧之血是一种从徘徊在暮色森林的凶猛Nightbane狼人身上采集到的非自然流体。暴风城的护甲商格里曼德·埃尔摩需要二十瓶这种炽热的精华，以便试验高级锻造技术。",kw={"燃烧之血","暮色森林","弗伦·长须","格里曼德·埃尔摩","gutspill","nightbane","罗兰之墓","狼人"},ang={["class:Warrior"]="格里曼德·埃尔摩使用这种不稳定的试剂来测试尖端的锻造方法，并用耐用的定制板甲奖励采集这种试剂的有志战士。",["profession:Blacksmithing"]="锻造大师偶尔会跳出传统的煤炭和水，利用像燃烧的狼人血液这样异域试剂，在极端温度下对重金属进行淬火和回火处理。"},sec={{t="一种不稳定的试剂",b="盘踞在暮色森林的受诅咒的Nightbane狼人体内流淌着一股奇异且非自然的愤怒，它们的血液燃烧着真正的热量。这种灼热的流体可以从出没于闹鬼林地和罗兰之墓废弃挖掘场的野兽身上提取。虽然采集过程令人作呕，但这种炽热的物质拥有稀有的冶金特性，受到那些寻求淬火和锻造坚韧板甲的护甲大师们的垂涎。"},{t="埃尔摩的实验",b="格里曼德·埃尔摩，一位在暴风城Dwarven District工作的资深工匠，正试图测试由他的前学生弗伦·长须开创的新颖锻造方法。为了验证这些激进的锻造技术是否有效，埃尔摩需要燃烧之血，以及狼人酋长Gutspill手中那块致密的燃烧之石。那些愿意面对狼群并带回沸腾流体的人，将获得在他锻炉的高温下锻造出的坚固战士护甲。"}},faq={{q="什么是燃烧之血？",a="燃烧之血是一种从暮色森林的Nightbane狼人身上提取的灼热、不稳定的体液。其非自然的热量使其成为专门的护甲锻造实验中极有价值的试剂。",al={"燃烧之血背景故事","什么是燃烧之血","狼人血液"}},{q="燃烧之血来自哪里？",a="它从徘徊在暮色森林各处的Nightbane狼人身上采集，特别是那些聚集在罗兰之墓废弃矿坑周围的狼人。",al={"哪里获得燃烧之血","谁掉落燃烧之血","燃烧之血位置"}},{q="格里曼德·埃尔摩为什么需要它？",a="格里曼德·埃尔摩想要测试弗伦·长须开发的创新护甲制作技术。通过将沸腾的血液与燃烧之石结合，他打算为一位冒险的战士锻造一件卓越的防护锁甲。",al={"格里曼德为什么要燃烧之血","格里曼德·埃尔摩的血液任务"}},{q="为什么Nightbane的血液在燃烧？",a="暮色森林的狼人是通过黑暗且混乱的魔法召唤而来的非自然魔物。流淌在Nightbane狼群体内的诅咒扭曲了它们的生理机能，使它们的血管中充满了炽热、非自然的毒性。",al={"为什么狼人有燃烧之血","狼人血液是火吗"}}},fp="26,128,18.267.0,19.351.0,22.126.0,35.93.0,32.159.0,42.123.0"}
P.entries["item:burning-rock"] = {n="燃烧之石",s="燃烧之石是一种不同寻常的、持续闷烧的矿物，是从位于暮色森林罗兰之墓深处的夜祸狼人首领古特斯皮尔身上回收的。暴风城的铁匠大师格里曼德·艾尔莫需要这种稀有的奇物，以及炽热的狼人血液，来为极具潜力的战士锻造特制的附魔护甲。",h="燃烧之石是一种不同寻常的、持续闷烧的矿物，是从位于暮色森林罗兰之墓深处的夜祸狼人首领古特斯皮尔身上回收的。暴风城的铁匠大师格里曼德·艾尔莫需要这种稀有的奇物，以及炽热的狼人血液，来为极具潜力的战士锻造特制的附魔护甲。",kw={"燃烧之石","暮色森林","弗伦·长须","格里曼德·艾尔莫","古特斯皮尔","夜祸狼人","罗兰之墓"},ang={["class:Warrior"]="格里曼德·艾尔莫征召经验丰富的战士去罗兰之墓冒险以获取这块石头，并用它所产生的热量锻造出的定制护甲来奖励他们的英勇表现。",["profession:Blacksmithing"]="燃烧之石作为一种异域热源，展示了暴风城和铁炉堡的护甲师们所探索的非传统熔炼和淬火方法。"},sec={{t="闷烧的战利品",b="燃烧之石由潜伏在罗兰之墓破败矿井中的残暴夜祸狼人古特斯皮尔携带，是暮色森林地下恐怖生物中的一个异类。它散发着一种持续不断的超自然热量，引起了暴风城格里曼德·艾尔莫的注意。为了测试其同行弗伦·长须所开创的实验性锻造技术，格里曼德利用这块岩石固有的热量和当地狼人沸腾的血液，为老练的战士淬炼坚硬的护甲板。"}},faq={{q="在哪里可以找到燃烧之石？",a="它由古特斯皮尔持有，这是一只凶猛的狼人首领，栖息在位于暮色森林东部的罗兰之墓矿井中。",al={"燃烧之石位置","谁掉落燃烧之石","哪里获得燃烧之石"}},{q="谁需要燃烧之石？",a="格里曼德·艾尔莫，一位驻扎在暴风城Dwarven District的精湛矮人铁匠，需要这块岩石来测试实验性的冶金技术。",al={"谁需要燃烧之石","谁交付燃烧之石","格里曼德·艾尔莫燃烧之石"}},{q="为什么格里曼德·艾尔莫需要它？",a="格里曼德打算测试由弗伦·长须开发的锻造技术。将这块闷烧的石头与夜祸狼人沸腾的血液结合，能够提供锻造独特护甲套件所需的高温。",al={"燃烧之石用途","为什么需要燃烧之石","燃烧之石有什么用"}},{q="这块岩石与狼人有什么联系？",a="罗兰之墓的夜祸狼人拥有奇怪的炽热生理特征，比如燃烧的血液。他们的族群领袖古特斯皮尔将燃烧之石保存在矿井深处，但这块石头究竟是他们挖掘出来的，还是他们随身携带的，仍然是个谜。",al={"为什么狼人有燃烧之石","古特斯皮尔燃烧之石背景故事"}}},fx={a40de154={q="什么是燃烧之石？",a="燃烧之石是一种罕见、灼热的矿物，发现于暮色森林那闹鬼的树林深处。这块火热的石头由占据罗兰之墓的野性Nightbane狼人首领Gutspill持有，它保持着极高的温度，是专门锻造和冶金所追求的材料。",al={"什么是燃烧之石","燃烧之石物品","关于燃烧之石"}}},fp="12,234,18.265.0,32.71.0,27.130.0,32.170.0,50.220.0"}
P.entries["item:cache-of-zanzil-s-altered-mixture"] = {n="赞吉尔的改良药剂",s="“赞吉尔的改良药剂”是一批强效毒药的储备，存放在“荆棘谷地精”位于淤泥沼泽附近的塔楼内的一只锁着的箱子里。它以丛林巨魔巫医赞吉尔的名字命名，是奥格瑞玛的破碎之手氏族的一个关键目标。",h="“赞吉尔的改良药剂”是一批强效毒药的储备，存放在“荆棘谷地精”位于淤泥沼泽附近的塔楼内的一只锁着的箱子里。它以丛林巨魔巫医赞吉尔的名字命名，是奥格瑞玛的破碎之手氏族的一个关键目标。",kw={"改良药剂","加里威克斯","保险箱","毒药","破碎之手","申苏尔","淤泥沼泽","荆棘谷地精","赞吉尔"},ang={["class:Rogue"]="回收该药剂是部落盗贼的一个重要成人礼，证明了他们为破碎之手效力时在开锁、偷窃和毒药处理方面的精湛技艺。",["faction:Horde"]="荆棘谷地精在淤泥沼泽以北建立的布满毒药的塔楼，对杜隆塔尔和贫瘠之地构成了直接的环境和安全威胁。"},sec={{t="致命的企业",b="在贫瘠之地的淤泥沼泽以北，荆棘谷地精设有一座塔楼哨站。在塔楼顶端，总工头普兹克·加里威克斯的私人保险箱里锁着一份以臭名昭著的巨魔巫医赞吉尔的名字命名的改良药剂。某种毒药削弱了塔里的一切，使其地精居民极易受到任何大胆入侵者的攻击。"},{t="破碎之手的回收行动",b="在杜隆塔尔附近出现如此危险的炼金材料，立刻引起了破碎之手的注意，这是一个在奥格瑞玛地下运作的秘密盗贼公会。为了消除威胁并获得该药剂以供自己的情报研究，训练大师申苏尔派遣特工突袭了塔楼，处决了加里威克斯，并撬开了工头的保险箱。回收这种挥发性的药剂需要高超的潜入技巧，因为处理被污染的容器有使窃贼暴露在其致命、衰竭性毒素下的风险。"}},faq={{q="什么是赞吉尔的改良药剂？",a="这是一种以巨魔巫医赞吉尔的名字命名的强效毒药。它的一个储藏点被锁在淤泥沼泽附近的荆棘谷地精塔楼里，那里的毒药削弱了塔内的一切。",al={"什么是赞吉尔药剂","什么是储藏点","赞吉尔药水"}},{q="在哪里可以找到这个储藏点？",a="该药剂存放在荆棘谷地精塔楼的最顶层，位于贫瘠之地东北部的淤泥沼泽正北，也就是加里威克斯的保险箱内。",al={"药剂在哪里","赞吉尔储藏点在哪里","药剂位置"}},{q="为什么破碎之手想要这种药剂？",a="申苏尔和破碎之手希望消除部落家门口的一个危险的荆棘谷地精行动，同时回收这种稀有化合物以加深他们对毒药和战术毒素的了解。",al={"谁想要这种药剂","为什么申苏尔想要它","破碎之手任务"}},{q="如何打开装有该药剂的箱子？",a="该箱子需要高级的开锁专精才能绕过其物理机制，因此只有那些知道如何在危险条件下操作精密弹子锁的训练有素的特工才能打开它。",al={"如何打开加里威克斯的保险箱","打开赞吉尔箱子","撬锁赞吉尔储藏点"}}},fx={["83dd2f73"]={q="赞吉尔的混合药剂从何而来，由谁制作？",a="这种混合药剂源自巫医赞吉尔，但它落入了在贫瘠之地活动的荆棘谷地精手中。大工头Puzik Gallywix将剩余的变异供应品锁在了淤泥沼泽附近的钻井塔顶部的个人保险箱里。",al={"谁制作了赞吉尔的混合药剂","混合药剂的起源","赞吉尔混合药剂从何而来"}}},fp="33,265,18.395.0,31.565.1,33.198.0,25.155.0,45.218.0,47.204.0"}
P.entries["item:cactus-apple"] = {n="仙人掌果",s="仙人掌果是从杜隆塔尔试炼谷的崎岖植物群中采集而来的坚韧、多汁的水果。它们在干旱的沙漠酷热中生长，被当地的兽人视为一种稀有而清爽的补给来源。",h="仙人掌果是从杜隆塔尔试炼谷的崎岖植物群中采集而来的坚韧、多汁的水果。它们在干旱的沙漠酷热中生长，被当地的兽人视为一种稀有而清爽的补给来源。",kw={"仙人掌果","清凉果","沙漠水果","杜隆塔尔","戈加尔","试炼谷"},ang={["profession:Cooking"]="对于在杜隆塔尔求生的野外厨师来说，采集沙漠仙人掌是将棘手、荒凉的沙漠植被转化为补水餐食的首要一课。",["race:Orc"]="在杜隆塔尔接受试炼的年轻兽人很快就会明白，要在这红色的峡谷中生存下去，就必须利用大自然所提供的每一滴稀缺水分。"},sec={{t="沙漠收获",b="杜隆塔尔那被烈日炙烤的大地几乎没有物产，迫使这里的居民只能利用任何能在恶劣环境中生存的顽强植物。仙人掌果成簇地生长在试炼谷各处的厚实仙人掌周围。虽然在采集时难免会扎到刺，但这种果实在闷热的峡谷中提供了至关重要的水分。当地的一位兽人戈加尔会采集这些果实来制作他招牌的清凉果，这是一种清凉的甜点，能让正在进行严酷初步训练的新兵们感到些许慰藉。"}},faq={{q="仙人掌果生长在哪里？",a="它们野生生长在杜隆塔尔南部的试炼谷的红土地上，通常分布在盆地中散落的矮壮仙人掌根部。",al={"仙人掌果位置","哪里可以找到仙人掌果","仙人掌果产地"}},{q="什么是清凉果？",a="这是试炼谷当地人戈加尔制作的一道冰镇清爽菜肴。他使用新鲜采集的仙人掌果，烹制成一种甜蜜的零食，可以让人立刻从杜隆塔尔惩罚性的沙漠酷热中解脱出来。",al={"什么是戈加尔的清凉果","仙人掌果配方","戈加尔的零食"}},{q="谁需要这些苹果？",a="戈加尔是驻扎在试炼谷的一名兽人，他会用他制作的清凉甜点来奖励那些愿意冒险外出并带回六个新鲜苹果的年轻新兵。",al={"仙人掌果任务发布者","谁需要仙人掌果","戈加尔的苹果"}}},fx={["93b3f975"]={q="什么是仙人掌果？",a="仙人掌果是一种清脆、提神的野生水果，在杜隆塔尔试炼谷的带刺仙人掌下茁壮成长。尽管兽人家园条件恶劣、干旱，但这些韧性十足的植物结出的多汁果实在炙热的沙漠阳光下提供了急需的水分和营养。",al={"什么是仙人掌果","仙人掌果背景传说"}},e52e1b37={q="仙人掌果从何而来？",a="仙人掌果是原生的沙漠水果，自然生长在杜隆塔尔试炼谷各处的仙人掌根部。它们不是由任何人制作或培育的，而是直接从适应了该地区红色峡谷和干燥气候的韧性植物上长出来的。",al={"仙人掌果从何而来","仙人掌果起源","谁制作了仙人掌果"}},["0fea9150"]={q="为什么戈加尔想要仙人掌果？",a="戈加尔收集它们是为了制作他著名的清凉果。试炼谷的酷热对新兵和经验丰富的战士都造成了沉重的负担，而用这些苹果制成的甜美、清凉的甜点在残酷的正午阳光下提供了至关重要的提神作用。",al={"为什么要采集仙人掌果","为什么戈加尔想要仙人掌果","仙人掌果的用途"}}},fp="12,219,14.536.0,28.166.0,30.207.0,26.165.0"}
P.entries["item:calor-s-note"] = {n="卡洛尔的便笺",s="卡洛尔的便笺是伐木工卡洛尔写在一张褪色羊皮纸上的短笺，用于向乔纳森·卡尔文大师推荐一位经受过考验的冒险者。它是一块敲门砖，引荐你进入一个与夜色镇正式的城镇民兵组织并肩作战、却又截然不同的暗影组织。",h="卡洛尔的便笺是伐木工卡洛尔写在一张褪色羊皮纸上的短笺，用于向乔纳森·卡尔文大师推荐一位经受过考验的冒险者。它是一块敲门砖，引荐你进入一个与夜色镇正式的城镇民兵组织并肩作战、却又截然不同的暗影组织。",kw={"卡洛尔","卡洛尔的便笺","夜色镇","暮色森林","乔纳森·卡尔文","守夜人","推荐","狼人"},ang={["class:Paladin"]="乔纳森·卡尔文会以“愿圣光照耀你”来欢迎持信者，这标志着他与那些致力于将暮色森林从恶魔和亡灵手中净化出来的圣光战士有着相同的意识形态。",["faction:Alliance"]="由于暴风城的军队完全没有出现在暮色森林，像卡尔文的圈子和守夜人这样非官方的派系，成为了南部边境对抗黑暗的唯一堡垒。"},sec={{t="一份罕见的推荐",b="暮色森林对陌生人向来冷漠，而卡洛尔也是出了名的眼光挑剔。在林中出没的嗜血狼人的袭击下幸存下来赢得了他的尊重，促使他草拟了这份简短的信息。当这份褪色的便笺被带到夜色镇时，它就成了信誉的象征，直接将局外人引荐给乔纳森·卡尔文。"},{t="一场私人远征",b="虽然夜色镇依靠守夜人来进行公共防御，但卡洛尔和卡尔文却在进行着更冷酷、更秘密的战斗。卡洛尔公开感叹自己的人手比不上城镇卫兵，希望有足够多能干的战士来推进他们的私人战争。递交这份便笺意味着加入卡尔文针对恶魔、亡灵以及那些助长暮色森林衰败的隐秘同谋者的行动。"}},faq={{q="什么是卡洛尔的便笺？",a="这是一张由卡洛尔亲笔写在褪色羊皮纸上的便条。它是一封个人的推荐信，证明了一名冒险者在对抗暮色森林的恐怖时所展现出的战斗力和可靠性。",al={"卡洛尔的便笺","这是什么便笺","便笺上写了什么"}},{q="谁会收到这封信？",a="这封信是写给乔纳森·卡尔文的，他是一位驻扎在夜色镇的严厉人物，负责协调针对威胁该地区的黑暗势力所进行的专门行动。",al={"我应该把便笺给谁","谁收到了卡洛尔的便笺","乔纳森·卡尔文便笺"}},{q="卡洛尔如何看待守夜人？",a="卡洛尔认为守夜人不足以应对潜伏在暮色森林中的真正威胁。在递交便笺时，他表达了招募足够多有能力的盟友以在人数上胜过民兵的愿望，希望最终能完成他那支小团体独自承担的紧迫任务。",al={"卡洛尔与守夜人","为什么卡洛尔想在人数上超过守夜人"}},{q="乔纳森·卡尔文在进行什么样的战斗？",a="卡尔文大师正在对恶魔、亡灵以及在暮色森林中协助它们的凡人同谋者进行着毫不妥协的战斗。他珍视警惕和对圣光的奉献，只接纳经过考验的人进入他的核心圈子。",al={"卡尔文的事业","卡尔文在做什么","卡尔文在对抗谁"}}},fx={d10add4c={q="谁写了卡洛尔的便笺，它从何而来？",a="这张便笺是由卡洛尔书写的，他是一名驻扎在暮色森林闹鬼地带的冷酷战士。在你证明了自己对抗恐吓树林的凶猛狼人的勇气后，他将这条信息写在一张褪色的羊皮纸上，让你前往他的上级那里。",al={"卡洛尔的便笺起源","谁制作了卡洛尔的便笺","卡洛尔的便笺从何而来"}},fe7f9dd8={q="为什么乔纳森·卡尔文想要卡洛尔的便笺？",a="大师乔纳森·卡尔文在信任一个被阴影笼罩的土地上的人之前，需要证据。卡洛尔的便笺是一封正式的推荐信，让卡尔文知道你赢得了卡洛尔难得的尊重，并且有能力协助他们秘密对抗恶魔、亡灵和更黑暗的力量。",al={"为什么要带卡洛尔的便笺给卡尔文","为什么卡尔文想要卡洛尔的便笺","卡洛尔便笺给卡尔文的目的"}}},fp="12,256,21.344.0,17.383.0,21.218.0,22.163.0,38.272.0,48.227.0"}
P.entries["item:candle-of-beckoning"] = {n="诱灵蜡烛",s="诱灵蜡烛是隐居的死灵法师冈瑟尔·阿坎努斯在澈水湖上保存的一种附魔仪式蜡烛。将蜡烛放置并点燃在附近小岛的祭坛上，可以召唤出一个名为莉莉丝·内法拉的游荡之魂。",h="诱灵蜡烛是隐居的死灵法师冈瑟尔·阿坎努斯在澈水湖上保存的一种附魔仪式蜡烛。将蜡烛放置并点燃在附近小岛的祭坛上，可以召唤出一个名为莉莉丝·内法拉的游荡之魂。",kw={"澈水湖","诱灵蜡烛","冈瑟尔·阿坎努斯","莉莉丝·内法拉","证明忠诚","沉睡的阴影","提瑞斯法林地"},ang={["class:Mage"]="冈瑟尔将灵魂束缚在像这种蜡烛一样的仪式物品上的能力，展现了他对肯瑞托许可教义之外的死灵法术和咒法艺术的掌握。",["race:Undead"]="对于被幽暗城派来的被遗忘者特使来说，使用冈瑟尔的仪式蜡烛是说服这位极度独立的死灵法师你并非巫妖王奴仆的必要步骤。"},sec={{t="忠诚的考验",b="诱灵蜡烛存放在澈水湖冈瑟尔·阿坎努斯岛上那位孤独的法师身边的板条箱里，它是黑暗召唤仪式中的一种工具。冈瑟尔是一位极其独立的亡灵法师，他凭借自己的力量摆脱了巫妖王的控制，对天灾军团和被遗忘者都保持着警惕。为了证明你并不效忠于巫妖王，冈瑟尔指示你带着这些蜡烛前往西南方的一个较小岛屿。在那里，将蜡烛放置在一张古老的血迹斑斑的桌子上，蜡烛的火焰将刺破两个世界之间的帷幕，唤醒并引来沉睡的莉莉丝·内法拉的阴影，她是一位强大的天灾军团特工，你需要将她消灭。"}},faq={{q="诱灵蜡烛是用来做什么的？",a="这种蜡烛是用来召唤莉莉丝·内法拉的阴影的。通过将其放置并点燃在冈瑟尔·阿坎努斯营地西南方小岛上那张古老的血迹斑斑的仪式桌上，沉睡的灵魂就会被引诱到物质位面。",al={"诱灵蜡烛的作用","诱灵蜡烛的用途","如何使用诱灵蜡烛"}},{q="在哪里可以获得诱灵蜡烛？",a="在进行冈瑟尔·阿坎努斯的忠诚考验时，你可以从澈水湖（位于提瑞斯法林地东部）他岛屿上的一只板条箱里获得这种蜡烛。",al={"哪里可以找到诱灵蜡烛","如何获取诱灵蜡烛","蜡烛箱子的位置"}},{q="这种蜡烛召唤的是谁？",a="点燃蜡烛会召唤出莉莉丝·内法拉，她是一位强大的天灾军团特工，出没于岛屿南岸外那座血腥的祭坛。击败她是证明你不效忠于天灾军团的必要条件。",al={"它召唤了谁","蜡烛召唤目标","莉莉丝·内法拉是谁"}},{q="为什么冈瑟尔·阿坎努斯会有这些蜡烛？",a="冈瑟尔利用这些蜡烛及其相关的仪式作为一种考验。由于怀疑外来者，并且极力保护自己免受天灾军团的控制，他要求任何寻求与他结盟的人必须面对并消灭他所召唤的游荡之魂。",al={"为什么冈瑟尔有蜡烛","冈瑟尔的仪式蜡烛"}}},fx={["63af5e56"]={q="什么是诱灵蜡烛？",a="诱灵蜡烛是一种附魔的仪式蜡烛，发现于死灵法师冈瑟尔·阿坎努斯在澈水湖的隐居岛屿上。这支蜡烛存放在这位隐居法师身边的一个板条箱里，带有专门用于穿透死亡帷幕的强大召唤魔法。当放在附近小岛上一个血迹斑斑的仪式桌上并点燃时，它的火焰就成了超自然的诱饵，召唤出Lillith Nefara沉睡的阴影。",al={"什么是诱灵蜡烛","诱灵蜡烛背景传说"}},cb4d5793={q="为什么会有人想要诱灵蜡烛？",a="任何寻求与冈瑟尔·阿坎努斯会面或结盟的人，首先必须证明他们的忠诚不在于巫妖王。冈瑟尔在与被遗忘者分享他强大的天赋之前，要求忠诚的证明。通过取回诱灵蜡烛，你可以引出并消灭Lillith Nefara，证明你反对天灾军团的决心，并赢得这位隐居死灵法师来之不易的尊重。",al={"我为什么需要诱灵蜡烛","为什么想要诱灵蜡烛","诱灵蜡烛的用途"}}},fp="19,244,20.666.0,41.240.0,41.179.0,30.199.0,44.236.0"}
P.entries["item:cantation-of-manifestation"] = {n="显形卷轴",s="“显形卷轴”是一种写在羊皮纸卷轴上的专门奥术咒语，法师们用它来揭示肉眼看不见的魔法异常。在幽暗城，安娜斯塔西娅·哈特威尔会将它交给那些去调查Apothecarium里阿尔格隆的店铺中出没的隐形魔法实体的学徒们。",h="“显形卷轴”是一种写在羊皮纸卷轴上的专门奥术咒语，法师们用它来揭示肉眼看不见的魔法异常。在幽暗城，安娜斯塔西娅·哈特威尔会将它交给那些去调查Apothecarium里阿尔格隆的店铺中出没的隐形魔法实体的学徒们。",kw={"阿尔格隆","安娜斯塔西娅·哈特威尔","apothecarium","显形卷轴","收容箱","magic quarter","裂隙衍生物","幽暗城"},ang={["class:Mage"]="显形卷轴是你早期训练中的重要工具，它教会你如何探测隐藏的奥术流以及收容不稳定的裂隙实体。",["race:Undead"]="法师区的被遗忘者施法者们对奥术波动保持着严格的控制，确保魔法裂隙不会影响幽暗城的稳定性。"},sec={{t="揭示无形之物",b="“显形卷轴”中包含一道专门用于穿透魔法帷幕，强迫虚体、隐形的生物显形的专注法术。卷轴存放在幽暗城的法师区，靠近安娜斯塔西娅·哈特威尔的地方，专门交给有能力的法师去收容失控的魔法异常。当在奥术不稳定的区域（例如Apothecarium里阿尔格隆的炼金实验室）诵读该卷轴时，咒语会迫使游荡的裂隙衍生物现形，从而让施法者能够制服并将它们困在收容箱中以供进一步研究。"}},faq={{q="显形卷轴有什么用？",a="它是一张魔法卷轴，施放的法术可以揭示隐形的奥术异常。在经历魔法裂隙或扰动的区域诵读时，它会强迫隐形的生物（例如裂隙衍生物）现身，以便将它们击败并捕获。",al={"什么是显形卷轴","显形卷轴的用途","显形卷轴如何工作"}},{q="我在哪里可以在幽暗城找到这个卷轴？",a="它就放在幽暗城法师区安娜斯塔西娅·哈特威尔身后的地板上。",al={"幽暗城显形卷轴位置","显形卷轴在哪里","寻找幽暗城显形卷轴"}},{q="为什么安娜斯塔西娅·哈特威尔需要使用这个卷轴？",a="Apothecarium的阿尔格隆炼金商店里爆发了一场奇怪的魔法扰动。完全由魔法构成的隐形实体开始在店里游荡，哈特威尔需要有人在现场诵读卷轴，以在裂隙恶化之前显现并捕获这些生物。",al={"为什么要使用显形卷轴","哈特威尔任务动机","安娜斯塔西娅扰动"}},{q="用完之后我可以保留这个卷轴吗？",a="不行。一旦你显现并用收容箱捕获了裂隙衍生物，你必须将显形卷轴连同收容箱一起带回给安娜斯塔西娅·哈特威尔。",al={"保留显形卷轴","我会失去显形卷轴吗","归还显形卷轴"}}},fx={["1a839123"]={q="显形卷轴是什么？",a="显形卷轴是法师使用的一种特殊奥术卷轴。在被施放时，其咒语能穿透魔法伪装，迫使纯粹由奥术能量构成的隐形实体在肉眼下显形。",al={"什么是显形卷轴","显形卷轴道具","显形卷轴有什么用"}},f236f2b5={q="为什么安娜斯塔西娅·哈特威尔想要显形卷轴？",a="幽暗城的Apothecarium中，Algernon的商店周围出现了隐形的魔法生物，这标志着魔法流出现了裂隙。法师训练师需要阅读这份卷轴，以便让学徒显现并捕获这些实体进行研究，从而让幽暗城的法师们确定这次扰动是意外，还是主动的魔法攻击。",al={"为什么要显形卷轴","为什么需要显形卷轴","为什么安娜斯塔西娅想要显形卷轴"}}},fp="26,298,23.573.0,44.249.0,44.121.0,50.268.0,43.184.0"}
P.entries["item:canvas-scraps"] = {n="帆布脚料",s="帆布脚料是入侵杜隆塔尔的人类侵略者和半人马部落所携带的坚韧织物残片。在剃刀岭，年迈的老兵弗恩·凝眉收集这些搜刮来的布料，为新加入部落的成员缝制实用的旅行袋。",h="帆布脚料是入侵杜隆塔尔的人类侵略者和半人马部落所携带的坚韧织物残片。在剃刀岭，年迈的老兵弗恩·凝眉收集这些搜刮来的布料，为新加入部落的成员缝制实用的旅行袋。",kw={"帆布脚料","负重前行","杜隆塔尔","弗恩·凝眉","考尔卡","库尔提拉斯","剃刀岭"},ang={["faction:Horde"]="从库尔提拉斯侵略者或考尔卡掠夺者身上搜刮来的每一片残布，都能为响应萨尔号召、守卫杜隆塔尔各地的新防卫者提供补给。",["profession:Tailoring"]="虽然简单的编织帆布主要是战士们收集的原始战利品，但在严酷的沙漠中，它却是制作实用背包的坚固基础。"},sec={{t="杜隆塔尔敌人的战利品",b="帆布并非兽人粗犷的制皮传统中常用的面料，但在杜隆塔尔的敌人手中却随处可见。驻扎在东海岸的库尔提拉斯陆战队和水手们携带了大量的帆布装备和从海上航行中留下的帆布残片。在内陆地区，游荡的考尔卡半人马将从补给商队和过去的冲突中劫掠来的粗布残片重新利用。击败这些敌对势力，就可以从他们的营地和装备中搜刮到这些耐用的残片。"},{t="老兵的手艺",b="老兵弗恩·凝眉驻守在Razor Hill Watchtower之巅，在警惕入侵者的同时，也从事着有用的劳作。尽管已过了战斗的巅峰期，这位老战士还是将搜刮来的敌方布料改制成坚固的背包，分发给年轻的士兵。通过将库尔提拉斯和考尔卡半人马的物资转为己用，弗恩为守卫部落边疆的新一代防卫者们提供了装备。"}},faq={{q="帆布脚料从哪里来？",a="它们是从杜隆塔尔各地的人类和半人马敌人身上回收的。你可以从占领提拉加德城堡和东海岸的库尔提拉斯军队身上，或是从内陆营地附近徘徊的考尔卡半人马苦工和斥候身上获取它们。",al={"谁掉落帆布脚料","哪里可以获得帆布脚料","帆布脚料刷取"}},{q="为什么弗恩·凝眉需要这些脚料？",a="弗恩·凝眉是一位驻扎在Razor Hill Watchtower的年迈兽人老兵，他已无法再在前线战斗。为了继续为部落效力，他利用搜刮来的布料为年轻的冒险者缝制实用的旅行袋。",al={"谁需要帆布脚料","帆布脚料的用途","弗恩·凝眉 帆布"}},{q="为什么库尔提拉斯军队和半人马会携带帆布？",a="库尔提拉斯远征军乘坐战舰抵达杜隆塔尔，并维持着海边的营地，因此帆布和编织布料是他们的日常必需品。考尔卡半人马通过突袭商队、搜刮海岸线以及劫掠穿越干旱平原的旅行者，来获取类似的粗布面料。",al={"为什么半人马会有帆布","人类帆布脚料背景故事"}}},fx={["6d5b894e"]={q="什么是帆布脚料？",a="帆布脚料是从杜隆塔尔各地敌人的营地和装备中回收的厚实织物碎片。帆布比普通的亚麻布更结实，广泛用于重型军事装备、风帆和坚固的帐篷。虽然这些碎片在战场上看起来像是垃圾，但它们耐用的纤维可以很容易地被熟练的裁缝或工匠改造成实用的补给品，例如为行军的战士制作坚固的背包。",al={"什么是帆布脚料","帆布脚料道具","帆布脚料是做什么的"}}},fp="13,252,29.493.0,17.413.0,33.234.0,42.235.0,53.294.0"}
P.entries["item:cask-of-merlot"] = {n="一桶葡萄酒",s="一桶葡萄酒是暴风城生产并销售的一种优质红酒。它是湖畔镇旅店老板在黑石兽人入侵导致物资短缺期间所需要的几种地区特产烈酒之一。",h="一桶葡萄酒是暴风城生产并销售的一种优质红酒。它是湖畔镇旅店老板在黑石兽人入侵导致物资短缺期间所需要的几种地区特产烈酒之一。",kw={"酒吧老板丹尼尔","一桶葡萄酒","干旱时期","加琳娜酒庄","湖畔镇","梅洛红酒","罗伯托·普佩尔维波斯","暴风城"},ang={["faction:Alliance"]="获取这桶酒凸显了暴风城运河区安全的奢华环境，与赤脊山遭受围困的边境城镇在战争中的挣扎形成了鲜明对比。"},sec={{t="首都的滋味",b="这桶葡萄酒在王国腹地收割发酵，直接来自加琳娜酒庄的酒窖，酒庄坐落在暴风城贸易区的运河边上。酿酒师罗伯托·普佩尔维波斯在那里打理着各个年份的酒，迎合着首都那些品味挑剔的顾客。与暮色森林辛辣的月光酒或艾尔文森林酿造的粗糙烈酒不同，梅洛红酒代表了在城市城墙相对安全的保护下，人类酿酒师精湛的技艺。"},{t="为湖畔镇补货",b="当黑石氏族入侵赤脊山时，补给路线中断，湖畔镇与常规的商队运输断绝了联系。面对口渴且惊恐的当地人，酒吧老板丹尼尔委托愿意帮忙的信使跑遍整个王国，为他的旅店酒窖补充货源。采购这桶酒能确保坚守在止水湖边的保卫者和难民们能有温和的饮品来送服口粮。"}},faq={{q="在哪里可以找到一桶葡萄酒？",a="它由罗伯托·普佩尔维波斯在加琳娜酒庄内出售。这家店位于暴风城贸易区外围的运河沿岸。",al={"一桶葡萄酒位置","在哪里购买梅洛红酒","谁出售一桶葡萄酒","暴风城葡萄酒商"}},{q="为什么酒吧老板丹尼尔需要这种酒？",a="湖畔镇的常规贸易运输因黑石兽人入侵赤脊山而中断。酒吧老板丹尼尔的酒水几乎耗尽，于是他派遣冒险者前往艾泽拉斯南部搜集地区特产，以满足他顾客的需求。",al={"干旱时期任务梅洛红酒","为什么丹尼尔想要酒","湖畔镇梅洛红酒用途"}},{q="除了梅洛红酒之外，还要收集哪些其他饮品？",a="丹尼尔还要求从闪金镇取一袋蜂蜜酒，从夜色镇取一瓶月光酒，以及从西部荒野山区的葛瑞姆·雷酒那里取一桶雷酒淡啤酒。",al={"干旱时期饮品","丹尼尔的酒水清单","干旱时期的其他酒精饮品"}},{q="加琳娜酒庄有危险吗？",a="酒庄在暴风城石墙的保护下十分安全。虽然西部荒野和赤脊山等外围领土遭受着强盗和兽人袭击的苦难，但在首都的运河区，商业活动和酿酒工作仍在持续，未受干扰。",al={"加琳娜酒庄背景故事","暴风城的酒庄"}}},fx={e882dee4={q="一桶葡萄酒是什么？",a="这是一种在暴风城生产和销售的优质红酒，装在一个大容器里。虽然普通市民将其作为日常美酒享用，但那些陷入动荡的边远定居点却将这种散装烈酒视为珍宝，以维持当地酒馆的库存并提振当地民心。",al={"什么是一桶葡萄酒","一桶葡萄酒道具","一桶葡萄酒是什么东西"}},["33c97a45"]={q="一桶葡萄酒来自哪里，是谁制作的？",a="这桶酒来自位于暴风城Trade District边缘运河旁的加利纳酒庄。它由罗伯特·普佩里弗伯斯准备并出售，他负责向城市顾客和旅行商人供应酒庄备受欢迎的陈酿。",al={"一桶葡萄酒的起源","谁制作了葡萄酒","一桶葡萄酒来自哪里"}}},fp="14,237,22.489.0,20.421.0,34.150.0,40.245.0,53.179.0,31.241.0"}
P.entries["item:cask-of-scalder"] = {n="一桶热酒",s="一桶沉重的烈性麦酒，专为前往暴风城的勇敢冒险者准备。它既是解渴的礼物，也是老友之间非正式的流通货币。",h="一桶沉重的烈性麦酒，专为前往暴风城的勇敢冒险者准备。它既是解渴的礼物，也是老友之间非正式的流通货币。",kw={"麦酒","麦酒家族","一桶热酒","dwarven district","弗伦·长须","盾牌匠","暴风城"},ang={["class:Warrior"]="对于寻求可靠保护的战士来说，用一桶好酒换取弗伦·长须传奇般的锻造技艺，是必经的重要考验。",["race:Dwarf"]="对于矮人来说，没有什么比送上一桶新鲜的Barleybrew顶级佳酿更能促成交易或偿还旧债了。"},sec={{t="矮人的交易",b="“热酒”是闻名遐迩的麦酒，足以温暖最怕冷的矮人。这桶酒被委托给那些在赤脊山试炼中证明了自己的勇士，直接送往位于暴风城Dwarven District的弗伦·长须处。作为一名技艺高超的盾牌匠，长须无法忍受无酒可饮的“干旱期”，因此这种烈酒是让他偿还旧日人情并打造高品质矮人工艺品的绝佳筹码。"}},faq={{q="一桶热酒里装的是什么？",a="这桶里装的是“热酒”，这是一种由麦酒酿造家族（Barleybrew family）制作的烈性酒。因其浓郁的口感和暖身的效果，深受矮人们的喜爱。",al={"这里面是什么酒","热酒麦酒","麦酒热酒"}},{q="这桶酒是给谁的？",a="这桶酒是给弗伦·长须的，他是一位在暴风城Dwarven District工作的矮人盾牌大师。",al={"谁接收酒桶","我该把酒送到哪","热酒接收人"}},{q="为什么要把这桶酒送给弗伦·长须？",a="弗伦欠了Yorus Barleybrew一个人情。交出这桶珍贵的麦酒既能满足弗伦在“干旱期”的酒瘾，也能说服他为送信人打造一面坚固且卓越的盾牌。",al={"为什么弗伦想要热酒","盾牌匠的人情","酒桶的用途"}}},fx={df3534f2={q="一桶热酒是什么？",a="一桶热酒是一个木桶，里面装满了麦酒家族酿造的烈性酒——麦酒热酒。尤鲁斯·麦酒将其作为礼物委托给你，介绍给他在暴风城的矮人朋友：盾甲匠弗伦·长须。",al={"什么是一桶热酒","一桶热酒","热酒是什么"}},["1fd358f8"]={q="一桶热酒来自哪里，是谁制作的？",a="这桶酒由赤脊山的尤鲁斯·麦酒在你通过瑞斯班的挑战后提供。这种独特的酒由著名的麦酒家族酿造，作为一份能换取矮人大师打造的盾牌的厚礼，这份心意再合适不过了。",al={"谁制作了一桶热酒","一桶热酒的起源","一桶热酒来自哪里"}}},fp="15,127,17.336.0,35.132.0,30.109.0,52.170.0"}
P.entries["item:cask-of-shimmer-stout"] = {n="一桶微光酒",s="“一桶微光酒”是雷杰德·麦酒酿造的一种烈性新酒，在丹莫罗寒冷的高地上制成，并密封在一个木桶中。它以劲头十足和令人眩晕的活力而闻名，被作为一份充满情谊的礼物，向东跨越群山，送给其他的矮人巡山人。",h="“一桶微光酒”是雷杰德·麦酒酿造的一种烈性新酒，在丹莫罗寒冷的高地上制成，并密封在一个木桶中。它以劲头十足和令人眩晕的活力而闻名，被作为一份充满情谊的礼物，向东跨越群山，送给其他的矮人巡山人。",kw={"一桶微光酒","丹莫罗","卡德雷尔","洛克莫丹","雷杰德·麦酒","微光酒","塞尔萨玛"},ang={["race:Dwarf"]="对矮人来说，在巡逻间隙分享美酒是一种受人尊重的传统，它将分散在卡兹莫丹崎岖山峰上的巡山人紧密联系在一起。"},sec={{t="充满情谊的快递",b="微光酒由雷杰德·麦酒在烈酒村酿造，很快便在当地常客和那些冒着丹莫罗严寒的巡山人中赢得了极高评价。巡山人维拉特·麦酒对兄弟酿造的这种酒印象深刻，于是托人运送了一桶酒，穿过东部山口送往洛克莫丹。矮人将烈酒视为社交必需品，也是抵御刺骨山风的实用手段，与远方的战友分享新酒更是一项由来已久的军事传统。"},{t="矮人的提神酒",b="当巡山人卡德雷尔在塞尔萨玛执勤时打开并品尝了这种酒，它的名声果然名不虚传。这绝非普通的酒馆饮品，据说只需饮用一口微光酒，就会感到浑身轻盈，仿佛能飞起来一般——这正是矮人侦察兵在漫长而孤独的高地巡逻时所依赖的那种强效饮品。"}},faq={{q="什么是微光酒？",a="微光酒是雷杰德·麦酒在丹莫罗酿造的一种烈性矮人啤酒。它以劲头十足而备受推崇，并以强身健体、抵御严寒的功效而闻名。",al={"什么是微光酒","微光酒背景故事","谁酿造了微光酒"}},{q="这桶酒是送给谁的？",a="这桶酒是送给巡山人卡德雷尔的，他是一名驻守在洛克莫丹塞尔萨玛定居点沿途的卫兵。",al={"谁收到了酒桶","酒桶去向","酒桶接收者"}},{q="为什么要跨越群山送酒？",a="矮人巡山人经常与远方巡逻的同僚分享美酒。在品尝了雷杰德的杰作后，他的兄弟希望能让卡德雷尔也尝尝这丹莫罗最棒的新配方。",al={"为什么送酒","为什么要运送啤酒","为什么要送给卡德雷尔"}},{q="微光酒对饮用者有什么影响？",a="这种啤酒劲头大得惊人。巡山人卡德雷尔在品尝后惊叹，它让自己头晕目眩，浑身轻盈，感觉仿佛能飞起来一样。",al={"微光酒有多烈","微光酒的作用"}}},fx={aa5543f0={q="一桶微光酒来自哪里，是谁制作的？",a="这种烈酒由丹莫罗烈酒村的雷杰德·麦酒酿造。他的兄弟，巡山人维拉特·麦酒对这个配方印象深刻，于是打包了这桶酒想要在家乡之外分享，并让一位冒险者将它一路带到了洛克莫丹。",al={"谁制作了微光酒","微光酒来自哪里","一桶微光酒的酿造者"}},["3b29018e"]={q="为什么会有人想要一桶微光酒？",a="巡山人维拉特·麦酒很喜欢他兄弟的新配方，并希望另一位巡山人，巡山人卡德雷尔也能尝尝。卡德雷尔负责在塞尔萨玛周围寒冷的道路上巡逻，而一种能暖身、松骨、让人晕乎乎的烈性矮人麦酒，在漫长的值守期间是极好的慰藉。",al={"为什么要送微光酒","谁想要一桶微光酒","为什么卡德雷尔想要微光酒"}}},fp="21,274,19.520.0,20.395.0,22.190.0,30.138.0,34.223.0,51.169.0"}
P.entries["item:cats-eye-emerald"] = {n="猫眼翡翠",s="猫眼翡翠是一颗异常巨大的拳头大小的宝石，出土于贫瘠之地北部的石矿洞。因为它拥有巨大的市场价值，许多荆棘谷地精之外的人都对它垂涎欲滴，它很快就成了各方阴谋诡计的目标。",h="猫眼翡翠是一颗异常巨大的拳头大小的宝石，出土于贫瘠之地北部的石矿洞。因为它拥有巨大的市场价值，许多荆棘谷地精之外的人都对它垂涎欲滴，它很快就成了各方阴谋诡计的目标。",kw={"铜栓老板","石矿洞","猫眼翡翠","翡翠","棘齿城","淤泥沼泽","荆棘谷地精","码头管理员迪兹维格"},ang={["class:Rogue"]="在腐败的荆棘谷地精工头眼皮底下偷走一颗巨大的、守卫不严的宝石，简直是教科书般的投机行为。",["profession:Mining"]="在石矿洞这种肮脏的工业挖掘场发现一颗完美无瑕的拳头大小的宝石，代表了每个矿工梦寐以求的终极好运。"},sec={{t="拳头大小的财富",b="当在淤泥沼泽东北部的荆棘谷地精的石矿洞进行挖掘的劳工们发现一颗巨大的翡翠时，这个消息迅速传遍了整个大草原。在这些由地精统治的领地里，这种罕见的高级宝石很难长久地保持秘密。棘齿城的码头管理员迪兹维格通过码头和藏宝海湾之间源源不断的贸易流言听到了这个发现，立即策划要将这件宝物弄到手，以便在地底之城的公开市场上出售。"},{t="公司所属",b="这颗宝石并没有通过正当渠道进入常见的贸易通道，而是被矿井内的荆棘谷地精管理层严密看管。监工、执行者以及像铜栓老板这样的一线主管们警惕地守护着这件珍贵的战利品，防止敌对财团和那些想要获得迪兹维格承诺的五成报酬的投机寻宝者抢走它。"}},faq={{q="什么是猫眼翡翠？",a="这是一颗异常巨大的翡翠，大约有拳头大小，是在贫瘠之地北部的挖掘作业中发现的。它的净度和尺寸使其在国际市场上价值连城。",al={"什么是猫眼翡翠","猫眼宝石","这是什么宝石"}},{q="这颗宝石是在哪里发现的？",a="它是由荆棘谷地精的矿工在石矿洞中出土的，该矿洞位于贫瘠之地北部淤泥沼泽的东北方。",al={"它是在哪里发现的","宝石位置","石矿洞翡翠"}},{q="棘齿城里谁想要这颗翡翠？",a="码头管理员迪兹维格，这位负责棘齿城航运和货物的地精，想要得到这块石头，以便通过地底之城的贸易关系将其卖给富有的买家。",al={"谁购买这颗翡翠","迪兹维格 翡翠","谁发布猫眼翡翠任务"}},{q="谁在矿井里保管着这块石头？",a="这颗翡翠由石矿洞里的荆棘谷地精高级主管保管，由其中一名荆棘谷地精监工或执行者随身携带。",al={"谁掉落猫眼翡翠","谁持有猫眼翡翠","哪里可以找到猫眼翡翠"}}},fx={["24f13ef4"]={q="猫眼翡翠来自哪里？",a="猫眼翡翠是一颗天然的、拳头大小的宝石，是在贫瘠之地淤泥沼泽东北部的石矿洞（荆棘谷地精的一个挖掘场）深处出土的。它并非由工匠锻造或切割，而是最近由该地精公司里一位运气较好的矿工从地里挖掘出来的。",al={"猫眼翡翠的起源","在哪里发现了猫眼翡翠","谁制作了猫眼翡翠"}}},fp="16,248,20.470.0,18.366.0,29.187.0,29.141.0,33.161.0,41.137.0"}
P.entries["item:cenarion-lunardust"] = {n="赛纳里奥银尘",s="赛纳里奥银尘是图拉克·符文图腾在雷霆崖高地上赐予年轻牛头人德鲁伊的神圣粉末。它被用于在莫高雷和贫瘠之地交界处的一块古老枭兽之石前唤醒守护兽月爪。",h="赛纳里奥银尘是图拉克·符文图腾在雷霆崖高地上赐予年轻牛头人德鲁伊的神圣粉末。它被用于在莫高雷和贫瘠之地交界处的一块古老枭兽之石前唤醒守护兽月爪。",kw={"身与心","赛纳里奥银尘","利爪德鲁伊","月爪","银尘","枭兽之石","图拉克·符文图腾"},ang={["class:Druid"]="对于牛头人德鲁伊来说，这种粉末是解锁古老熊形态变形术这一神圣通过仪式的关键催化剂。",["race:Tauren"]="这种粉末将年轻的舒哈鲁与塞纳里奥议会的教导直接联系起来，展示了他们与自然以及卡利姆多荒野之灵日益加深的共鸣。"},sec={{t="身与心的试炼",b="赛纳里奥银尘被授予那些准备在利爪德鲁伊中占据一席之地的入门者，它承载着塞纳里奥议会的祝福。当这种发光的粉末被撒在陶拉祖营地西面的枭兽之石上时，它会召唤出月爪——一头注定要考验入门者的神圣野兽。击败这位守护者是对其身体素质和精神意志的双重考验，使年轻的德鲁伊能够吸收化身为熊所需的身体与心灵的力量。"}},faq={{q="赛纳里奥银尘有什么用？",a="它被洒在位于莫高雷和贫瘠之地之间丘陵地带的枭兽之石上，就在陶拉祖营地的正西面。使用这种粉末会召唤出月爪，这是一种强大的野兽，入门者必须击败它来证明自己的力量。",al={"银尘的作用","赛纳里奥银尘的使用方法","银尘的目的"}},{q="谁提供了赛纳里奥银尘？",a="雷霆崖长者高地的德鲁伊训练师图拉克·符文图腾，会为进行熊形态试炼的牛头人德鲁伊提供这种粉末。",al={"谁给予银尘","哪里获得赛纳里奥银尘","图拉克·符文图腾的粉末"}},{q="如果你弄丢了赛纳里奥银尘该怎么办？",a="如果你弄丢了粉末，或者在与月爪的试炼中失败了，你必须回到雷霆崖长者高地找图拉克·符文图腾再拿一袋。",al={"银尘丢失","需要更多银尘","哪里再拿一份银尘"}},{q="为什么德鲁伊必须面对月爪？",a="月爪是这块石头的守护者，体现了身体力量与内在意志的平衡。通过挑战并战胜这头野兽，一名渴望成为利爪德鲁伊的人能够吸取驾驭伟大熊灵力量所需的身体与心灵的课程。",al={"为什么挑战月爪","月爪是谁","月爪的目的"}}},fx={ca885fb9={q="什么是赛纳里奥银尘？",a="赛纳里奥银尘是由塞纳里奥德鲁伊制作的一种圣粉，只授予那些展现出奉献精神的入门者。当把它撒在贫瘠之地和莫高雷边界附近的枭兽石上时，银尘的魔法会召唤出卢娜爪，以考验年轻的德鲁伊是否具备行走利爪之路所需的体魄与心灵力量。",al={"什么是银尘","赛纳里奥银尘传说","塞纳里奥之尘"}},d52557a0={q="为什么会有人想要赛纳里奥银尘？",a="只有有志于成为德鲁伊的人才会寻求这种粉末，因为它是召唤枭兽石处的卢娜爪的关键。没有它，守护者就不会出现，导致入门者无法面对考验，也无法获得成为真正的利爪德鲁伊所需的精神力量。",al={"为什么要银尘","谁想要赛纳里奥银尘","为什么要使用银尘"}}},fp="18,242,24.474.0,36.224.0,36.145.0,49.152.0,31.267.0"}
P.entries["item:cenarion-moondust"] = {n="塞纳里奥月尘",s="塞纳里奥月尘是赋予正在进行利爪德鲁伊试炼的暗夜精灵德鲁伊的神圣粉末。当它被撒在奥伯丁以东丘陵上的古老枭兽石上时，会引出洞穴的野性守护者——月爪。",h="塞纳里奥月尘是赋予正在进行利爪德鲁伊试炼的暗夜精灵德鲁伊的神圣粉末。当它被撒在奥伯丁以东丘陵上的古老枭兽石上时，会引出洞穴的野性守护者——月爪。",kw={"奥伯丁","身心","塞纳里奥月尘","利爪德鲁伊","月爪","玛斯雷·驭熊者","月尘","枭兽石"},ang={["class:Druid"]="对于暗夜精灵德鲁伊来说，使用塞纳里奥月尘标志着成为利爪德鲁伊之路上的终极一步，直接通向对熊形态的掌握。",["race:NightElf"]="这种粉末体现了塞纳里奥议会的古老传统，将自然崇拜与月亮仪式融合在一起，以尊崇黑海岸的野兽。"},sec={{t="利爪仪式",b="塞纳里奥月尘由达纳苏斯的玛斯雷·驭熊者赐予，它是年轻德鲁伊进行最终身心试炼的催化剂。为了与守护者月爪沟通并证明自己，试炼者必须前往黑海岸奥伯丁以东的枭兽巢穴。将月尘涂抹在古老的枭兽石上，可以召唤野兽来测试试炼者的战斗能力，让德鲁伊能够领悟变身为熊所需的持久力量。"}},faq={{q="塞纳里奥月尘有什么用途？",a="它被黑海岸枭兽石处的暗夜精灵德鲁伊学徒用来唤醒月爪，以测试他们的力量和决心，从而获得熊形态的力量。",al={"月尘用途","塞纳里奥月尘有什么用","塞纳里奥月尘的目标"}},{q="我应该在哪里使用塞纳里奥月尘？",a="它必须被撒在黑海岸奥伯丁正东方丘陵内的一座枭兽洞穴里的枭兽石上。",al={"在哪里使用月尘","枭兽石位置","月爪之石在哪里"}},{q="谁提供塞纳里奥月尘？",a="玛斯雷·驭熊者，这位居住在达纳苏斯塞纳里奥区的德鲁伊训练师，会将它交给那些已经证明自己准备好进行身心试炼的学徒。",al={"谁提供月尘","在哪里获得塞纳里奥月尘","玛斯雷的月尘"}},{q="如果我弄丢了月尘该怎么办？",a="如果月尘丢失，或者在对抗月爪的尝试中失败并耗尽，学徒必须回到达纳苏斯再次向玛斯雷·驭熊者申请，以重试该项试炼。",al={"丢失的塞纳里奥月尘","丢失的月尘","找回月尘"}}},fx={d9963f3d={q="什么是塞纳里奥月尘？",a="塞纳里奥月尘是塞纳里奥议会赐予暗夜精灵德鲁伊的一种圣粉，他们寻求的是利爪德鲁伊的职责。它带有大自然的祝福，被用作一种仪式试剂来纪念并召唤古代的守护之灵。",al={"什么是塞纳里奥月尘","塞纳里奥月尘传说","月尘的用途"}},["34087882"]={q="塞纳里奥月尘来自哪里，是谁制作的？",a="这种粉末由达纳苏斯的塞纳里奥议会准备和保管。它专门由玛斯雷·驭熊者这样的德鲁伊训练师授予那些表现出敬意并赢得了进行神圣试炼权利的入门者。",al={"谁制作了塞纳里奥月尘","塞纳里奥月尘的起源","月尘来自哪里"}},["1f04d9d3"]={q="为什么需要塞纳里奥月尘？",a="月尘是唤醒卢娜爪所必需的，它是守护黑海岸枭兽石的古代野兽。卢娜爪只会回应那些将这种圣粉洒在石头上的入门者的挑战，让德鲁伊证明他们的体魄与心灵力量。",al={"为什么我需要塞纳里奥月尘","为什么要使用月尘","塞纳里奥月尘的目的是什么"}}},fp="17,255,18.479.0,35.170.0,37.127.0,31.174.0,36.178.0"}
P.entries["item:centaur-bracers"] = {n="半人马护腕",s="半人马护腕是取自贫瘠之地各处被击杀的库卡隆半人马的简单皮革与铁制臂环。雷格萨·死门在十字路口以西收集这些护腕，作为清理半人马劫掠者的证据。",h="半人马护腕是取自贫瘠之地各处被击杀的库卡隆半人马的简单皮革与铁制臂环。雷格萨·死门在十字路口以西收集这些护腕，作为清理半人马劫掠者的证据。",kw={"贫瘠之地","赏金","护腕","半人马","十字路口","死门","库卡隆","雷格萨"},ang={["faction:Horde"]="击败库卡隆劫掠者能直接助力部落的扩张，保障杜隆塔尔、莫高雷和十字路口之间脆弱的商队补给线安全。",["race:Tauren"]="世世代代以来，游牧的牛头人都忍受着半人马氏族的残暴骚扰；将库卡隆从贫瘠之地清除，不仅能带来期待已久的复仇，也能确保安全。"},sec={{t="粗糙的赏金",b="库卡隆部族对部落在贫瘠之地干旱平原上的立足点构成了持续的威胁。从倒下的半人马战士身上剥下护腕，是证明又一个敌对劫掠者已从贸易路线上被清除的不二铁证。雷格萨·死门，一名驻扎在十字路口以西悬崖边的兽人侦察兵，针对这些战利品发布了长期赏金，以削弱该部族的侵略行径。"}},faq={{q="谁需要这些护腕？",a="雷格萨·死门，一名驻扎在贫瘠之地十字路口以西高地上的部落侦察兵，会接受这些护腕作为你对抗当地库卡隆半人马的证据。",al={"谁收集半人马护腕","雷格萨·死门上交","谁购买半人马护腕"}},{q="哪些半人马携带着这些护腕？",a="这些护腕由游荡在贫瘠之地北部绿洲与营地（例如遗忘之池和甜水绿洲）中的库卡隆战士所佩戴。",al={"哪里刷护腕","库卡隆护腕掉落","半人马护腕来源"}},{q="雷格萨为什么要收集它们？",a="雷格萨试图积极地削减库卡隆的数量以保护部落的领地。收集护腕之类的战利品可以确保战士们确实是在消灭劫掠者，而不是仅仅将他们赶走。",al={"为什么要收集护腕","雷格萨·死门动机","半人马护腕用途"}}},fx={["2b8929fb"]={q="什么是半人马护腕？",a="这些护腕是贫瘠之地各处的半人马战士所穿戴的粗糙护甲。它们是从被杀死的科卡尔掠夺者手臂上剥下来的，对于部落来说，它们是猎人成功猎杀其好战部族的严酷实物证明。",al={"什么是半人马护腕","半人马护腕传说","半人马护腕是什么"}},e954048b={q="半人马护腕来自哪里？",a="它们由游荡在卡利姆多干旱平原上的半人马氏族，特别是敌对的科卡尔部族锻造或制作。战士们装备它们用于战斗，作为抵御许多敌人刀剑、箭矢和利爪的原始防护。",al={"谁制作了半人马护腕","半人马护腕的起源","半人马护腕来自哪里"}}},fp="15,199,15.413.0,24.160.0,34.151.0,37.207.0"}
P.entries["item:charred-horn"] = {n="烧焦的奇美拉角",s="烧焦的奇美拉角是那种从栖息在石爪山脉峭壁间的幼年奇美拉身上采集而来的粗糙、经受过高温烘烤的角。它们坚硬到足以抵御恶劣的元素力量，是专门的盔甲锻造中不可或缺的淬火材料。",h="烧焦的奇美拉角是那种从栖息在石爪山脉峭壁间的幼年奇美拉身上采集而来的粗糙、经受过高温烘烤的角。它们坚硬到足以抵御恶劣的元素力量，是专门的盔甲锻造中不可或缺的淬火材料。",kw={"烧焦的奇美拉角","奇美拉","防火锁甲","弗伦·长须","石爪山脉"},ang={["class:Warrior"]="弗伦·长须专门招募新晋战士前往卡利姆多各处取回这些角，并以定制的防火锁甲奖励他们危险的旅程。",["profession:Blacksmithing"]="这些野兽的角展示了一种异域的锻造技术，利用卡利姆多掠食者天然经过火焰固化的生物材料来回火锁甲链环。"},sec={{t="一种稀有的锻造材料",b="烧焦的奇美拉角是从石爪山脉崎岖高地上筑巢的幼雏和年轻奇美拉身上采集而来，因其对火焰和钝击伤害的非凡抗性而备受青睐。暴风城的矮人护甲大师弗伦·长须正在他的熔炉前忙碌，他需要收集这些角来打造防火锁甲。配合湿地的毒蜘蛛毒牙、剃刀沼泽的燃素，以及奇美拉主宰的光滑的奇美拉角，这些钙化的角提供了打造一套极其坚韧的防护盔甲所必需的核心结构加固。"}},faq={{q="哪些生物会掉落烧焦的奇美拉角？",a="它们是从卡利姆多石爪山脉崎岖地形中土生土长的奇美拉幼雏和年轻奇美拉身上收集而来的。",al={"哪里获得烧焦的奇美拉角","谁掉落烧焦的奇美拉角","烧焦的奇美拉角来源"}},{q="在暴风城里，谁需要这些角？",a="护甲大师弗伦·长须需要它们。他利用这些角经过火焰淬火的特性作为原材料，为有前途的战士打造极其坚固的锁甲胸甲。",al={"谁使用烧焦的奇美拉角","烧焦的奇美拉角上交","弗伦·长须的角"}},{q="为什么弗伦需要这么多这种角？",a="弗伦需要十二个烧焦的奇美拉角，以提供足够的原始、经受过热处理的材料，从而适当地加固他的防火锁甲的圆环和板甲。",al={"为什么需要12个烧焦的奇美拉角","烧焦的奇美拉角的用途"}},{q="它们和光滑的奇美拉角有什么不同吗？",a="是的。烧焦的奇美拉角可以从石爪山脉较弱、较年轻的奇美拉身上大量获得，而光滑的奇美拉角是一种极其稀有的战利品，直接取自奇美拉主宰。",al={"光滑的奇美拉角与烧焦的奇美拉角对比","角之间的区别"}}},fx={["785d7f85"]={q="什么是烧焦的奇美拉角？",a="烧焦的奇美拉角是从游荡在石爪山脉山峰上的幼年奇美拉身上收获的一种坚硬、发黑的角。在严酷的山地气候和野兽元素本性的作用下，这些角拥有独特的耐用性，使其成为一种用于专业锻造的珍贵原材料。",al={"什么是烧焦的奇美拉角","烧焦的奇美拉角传说","关于烧焦的奇美拉角"}}},fp="12,258,25.607.0,34.132.0,35.177.0,39.149.0,45.185.0"}
P.entries["item:chest-of-containment-coffers"] = {n="一盒封灵箱",s="一盒封灵箱中装有被施了法的容器，法师们利用这些容器来捕获不稳定的魔法现象。对于被派去调查并安全捕获隐形法力异常的施法者来说，这是必不可少的装备。",h="一盒封灵箱中装有被施了法的容器，法师们利用这些容器来捕获不稳定的魔法现象。对于被派去调查并安全捕获隐形法力异常的施法者来说，这是必不可少的装备。",kw={"安娜斯塔西娅·哈特威尔","apothecarium","奥术异常","封灵箱","magic quarter","裂隙生物"},ang={["class:Mage"]="该箱子为学习管理不稳定奥术表现并保存活体标本以供研究的法师提供了必要的实地工具。",["race:Undead"]="Forsaken法师使用这些封灵箱来固定Apothecarium附近出现的魔法异常，以免未经审查的奥术力量破坏他们的工作。"},sec={{t="针对隐形之物的容器",b="魔法实验和突发的位面裂隙经常会产生由纯粹奥术力量构成的、不稳定的隐形异常。普通的物理牢笼无法囚禁纯粹由魔法构成的实体。一盒封灵箱为法师们提供了专门设计的、附魔的封灵箱，用于活捉并束缚这些被制服的生物。这些箱子被放置在Undercity的安娜斯塔西娅·哈特威尔和暴风城的詹妮亚·坎农等高级导师附近，为那些负责在异常造成周围环境不稳定之前进行调查的学徒们提供必要的装备。"},{t="奥术收容协议",b="当Apothecarium中Algernon的商店里出现隐形干扰时，Forsaken导师派遣了配备这些封灵箱的法师去控制事态。捕获裂隙实体需要用专门的卷轴使其显形，通过施法削弱其形态，并将它关进从这个箱子里拿出的封灵箱中。装满的容器使Forsaken研究人员能够安全地解剖、研究并确定这些干扰是Ley中的随机撕裂，还是蓄意的奥术袭击。"}},faq={{q="一盒封灵箱里有什么？",a="箱子里装有专门的空封灵箱。法师们在危险的实地调查中获取这些容器，以固定并捕获被制服的魔法生物，例如裂隙生物。",al={"箱子提供什么","封灵箱内容物","箱子内容物"}},{q="这个箱子在哪里可以找到？",a="在Undercity，它就放在Magic Quarter的法师训练师安娜斯塔西娅·哈特威尔身后。在暴风城Wizard's Sanctum的詹妮亚·坎农身后也能找到一个同样的箱子。",al={"一盒封灵箱位置","封灵箱在哪里","封灵箱位置"}},{q="为什么法师需要这些封灵箱，而不是普通的笼子？",a="正在调查的生物是纯粹由无形奥术能量构成的裂隙生物。普通材料无法囚禁它们；只有施加了魔法的封灵箱才能物理性地捕获并稳定奥术异常。",al={"为什么要用封灵箱","封灵箱有什么用","封灵箱如何运作"}},{q="封灵箱装满后会怎样？",a="装满的封灵箱会被交给高级导师进行研究。被捕获的生物会经过分析，以查明奥术干扰是偶然的自然裂隙，还是外部势力的蓄意攻击。",al={"被捕获的裂隙生物会怎样","装满的封灵箱的用途","为什么要捕获生物"}}},fx={fa57c13a={q="一盒封灵箱是什么？",a="这是一个沉重的补给箱，由法师导师保管，用于装备调查魔法异常的从业者。里面放着一套特制的附魔封灵箱，专门用于束缚和容纳那些纯粹由奥术能量构成的、不稳定的非物质实体。",al={"什么是一盒封灵箱","一盒封灵箱","封灵箱盒子"}},c9b5ba3b={q="为什么安娜斯塔西娅·哈特威尔想要你带走一盒封灵箱？",a="安娜斯塔西娅·哈特威尔探测到幽暗城Apothecarium里Algernon的炼金商店周围游荡着隐形的魔法实体。普通的束缚手段无法触及这些完全由原始魔法编织而成的生物，所以她为你提供了这盒特制的封灵箱，以便将这些异常实体活捉并进行研究。",al={"为什么要拿一盒封灵箱","为什么我需要封灵箱","为什么安娜斯塔西娅要封灵箱"}}},fp="28,226,22.578.0,28.527.1,48.185.0,30.194.0,56.222.0,49.216.0"}
P.entries["item:chief-sharptusk-thornmantle-s-head"] = {n="刺鬃酋长的头颅",s="刺鬃酋长的头颅是战胜威胁红云台地的刺鬃野猪人领袖的冷酷胜利证明。它从刺刃峡谷深处寻回，并被呈交给卫兵维萨罗·风羽，标志着对年轻牛头人勇士持续威胁的终结。",h="刺鬃酋长的头颅是战胜威胁红云台地的刺鬃野猪人领袖的冷酷胜利证明。它从刺刃峡谷深处寻回，并被呈交给卫兵维萨罗·风羽，标志着对年轻牛头人勇士持续威胁的终结。",kw={"刺刃峡谷","刺鬃","头颅","莫高雷","thornmantle","维萨罗·风羽"},ang={["class:Hunter"]="对猎人来说，刺鬃代表了终极猎物：一个能够反击的聪明敌人，将一场生存遭遇战变成对追踪和射术的真正考验。",["race:Tauren"]="夺取强大对手的头颅是年轻牛头人的重要里程碑，证明他们拥有保护族人新建立家园的决心和技能。"},sec={{t="狩猎战利品",b="牛头人通过警惕和力量在莫高雷开辟了他们和平的家园。盘踞在刺刃峡谷内的刺鬃野猪人在他们凶残的酋长刺鬃的怂恿下，对纳拉其营地的部族发动了侵略性的攻势。割下他的头颅并非出于毫无意义的残忍，而是他死亡的确凿证据，也是对那些蚕食台地边界的幸存野猪人氏族严厉的警告。"},{t="狩猎的一课",b="卫兵维萨罗·风羽要求获取这位酋长的头颅，作为新晋猎人和部落保卫者的成年礼。对牛头人而言，面对一个狡猾到能够反击并组织起整个战团的对手，是考验武艺的重要测试。呈上刺鬃的头颅即完成了这项试炼，使这位年轻的战士在红云台地的勇士中赢得了稳固的声望。"}},faq={{q="为什么卫兵维萨罗·风羽想要刺鬃的头颅？",a="卫兵维萨罗·风羽需要确凿的证据证明刺鬃野猪人酋长已经倒下。带回他的头颅表明刺鬃将不再指挥对纳拉其营地的袭击，并向剩下的野猪人发出信号，表明他们的侵略将遭到果断的反击。",al={"为什么要取他的头颅","获取刺鬃头颅的原因","维萨罗·风羽对头颅的要求"}},{q="刺鬃酋长是谁？",a="刺鬃酋长是居住在红云台地东缘刺刃峡谷中的刺鬃野猪人的首领。在他的指挥下，刺鬃野猪人不断骚扰和袭击年轻的牛头人勇士。",al={"谁是刺鬃","刺鬃背景故事","莫高雷野猪人酋长"}},{q="这个战利品在哪里获得？",a="这颗头颅是通过在刺刃峡谷深处、纳拉其营地以东的临时部落村庄中击杀刺鬃酋长获得的。",al={"我在哪里能找到头颅","刺鬃头颅位置"}}},fx={["27fbe344"]={q="刺鬃酋长的头颅是从哪里来的？",a="这一可怕的战利品直接取自盘踞在刺刃峡谷的棘背野猪人酋长，该地就在纳拉其营地以东。刺鬃酋长集结了他那简陋的营地来对抗红云台地的牛头人，这使得勇士们要求得到他被砍下的头颅，以此作为棘背野猪人的战争努力已被粉碎的无可辩驳的证据。",al={"刺鬃酋长的头颅来源","刺鬃酋长的头颅从哪来","谁有刺鬃酋长的头颅"}}},fp="34,295,18.458.0,20.398.0,66.288.0,36.232.0,30.161.0"}
P.entries["item:chok-sul-s-head"] = {n="卓克苏尔的头颅",s="卓克苏尔的头颅是莫格罗什食人魔酋长已死的恐怖实证。将其带给塞尔萨玛的镇长埃罗恩·钝鼻，即可获得当地矮人当局悬赏的奖金。",h="卓克苏尔的头颅是莫格罗什食人魔酋长已死的恐怖实证。将其带给塞尔萨玛的镇长埃罗恩·钝鼻，即可获得当地矮人当局悬赏的奖金。",kw={"卓克苏尔","卓克苏尔的头颅","洛克莫丹","镇长埃罗恩·钝鼻","莫格罗什","食人魔","巨石水坝","塞尔萨玛"},ang={["race:Dwarf"]="消灭卓克苏尔能直接缓解铁炉堡各乡村定居点的压力，并保护像巨石水坝这样重要的市政纪念物免遭蛮力破坏。"},sec={{t="酋长陨落的证明",b="莫格罗什要塞的食人魔持续威胁着洛克莫丹的定居点，他们策划了针对塞尔萨玛、挖掘场以及重要的巨石水坝的袭击。镇长埃罗恩·钝鼻对那个被认为正在策划这些袭击的蛮族——卓克苏尔——发出了悬赏。鉴于东北部丘陵地带的混乱局势，镇长在发放城镇资金前要求获得确凿的证据。这颗食人魔酋长的断头提供了矮人议会确认合同已完成所需要的恐怖凭证。"}},faq={{q="卓克苏尔是谁？",a="卓克苏尔是驻扎在洛克莫丹东北部莫格罗什要塞的一名食人魔酋长。矮人官员认为他是针对塞尔萨玛、巨石水坝以及附近挖掘场发动协同突袭的幕后主使。",al={"卓克苏尔是谁","卓克苏尔背景故事","卓克苏尔身份"}},{q="为什么镇长埃罗恩·钝鼻想要这个头颅？",a="镇长埃罗恩·钝鼻通过一切必要手段对卓克苏尔的死发出了公开悬赏。由于食人魔的袭击严重困扰了该地区，镇长在发放来自塞尔萨玛国库的货币补偿前，需要酋长死亡的确凿证据。",al={"为什么钝鼻镇长想要头颅","卓克苏尔的头颅用途","谁想要卓克苏尔的头颅"}},{q="卓克苏尔在哪里活动？",a="卓克苏尔在莫格罗什要塞指挥他的战团，这是一个坐落在洛克莫丹东北部崎岖山丘中的防御严密的食人魔据点。",al={"卓克苏尔在哪里","莫格罗什要塞位置","卓克苏尔位置"}},{q="卓克苏尔对该地区构成了什么威胁？",a="据信他策划了针对塞尔萨玛和附近矮人基础设施（包括巨石水坝和当地考古挖掘场）的积极打击。",al={"为什么要通缉卓克苏尔","卓克苏尔做了什么"}}},fx={["8aed7d95"]={q="卓克苏尔的头颅是从哪里来的？",a="这一可怕的战利品直接取自洛克莫丹东北部荒野中莫格罗什要塞的食人魔卓克苏尔。这不是什么神器或工艺品，而是食人魔督军本人的断头，由为了完成塞尔萨玛镇发布的官方悬赏而来的冒险者所取。",al={"卓克苏尔的头颅来源","卓克苏尔的头颅从哪来","谁制造了卓克苏尔的头颅"}}},fp="15,204,29.539.0,17.240.0,44.284.0,27.149.0,45.174.0"}
P.entries["item:clarice-s-pendant"] = {n="克拉莉斯的坠饰",s="克拉莉斯的坠饰是一个小小的纪念品，属于住在雷霆崖预见之池的亡灵克拉莉斯·弗斯特。这件首饰曾经是她前夫尤里夫给她的信物，如今却仅仅是一个苦涩的提醒，提醒着她被遗弃的家庭以及对圣光错付的虔诚。",h="克拉莉斯的坠饰是一个小小的纪念品，属于住在雷霆崖预见之池的亡灵克拉莉斯·弗斯特。这件首饰曾经是她前夫尤里夫给她的信物，如今却仅仅是一个苦涩的提醒，提醒着她被遗弃的家庭以及对圣光错付的虔诚。",kw={"克拉莉斯·弗斯特","克拉莉斯的坠饰","被遗忘者","瑟伯切尔","银松森林","坟墓","至死不渝","尤里夫"},ang={["class:Paladin"]="克拉莉斯对尤里夫圣战的轻蔑，令人不安地提醒着人们在神圣狂热的背后所付出的个人代价和破碎的家庭。",["race:Undead"]="这枚坠饰凸显了许多被遗忘者共同的悲剧和苦涩，他们生前的挚爱往往为了最终未能保护任何人的圣战而抛弃了他们。"},sec={{t="苦涩的信物",b="克拉莉斯的坠饰代表了许多被遗忘者共同的支离破碎的人类过去。在第三次战争摧毁洛丹伦之前，克拉莉斯的丈夫尤里夫抛弃了她和孩子们，投身于对抗亡灵的战斗中，声称对圣光的虔诚高于一切。尤里夫不仅没能拯救家园，反而战死沙场，留下了家人，使她们最终屈服于他誓要对抗的天灾军团。对于克拉莉斯来说，这坠饰并非什么珍贵的纪念，而是一件充满讽刺意味的饰品，象征着她一生都在狂热和义务面前被排在次要位置。"},{t="安放在尤里夫的墓上",b="为了断绝与过去的生活和疏忽职守的丈夫之间残留的情感联系，克拉莉斯派遣一名冒险者将这件首饰直接送回位于瑟伯切尔的尤里夫之墓。那座坟墓被荒废且遭到了破坏，掩埋在杂草和垃圾之下。当坠饰最终被放在棺木雕刻出的双手上时，它上面的宝石变得明显暗淡，熄灭了克拉莉斯旧生活中最后残留的一丝温暖。"}},faq={{q="克拉莉斯的坠饰是谁的？",a="这枚坠饰属于克拉莉斯·弗斯特，她是住在雷霆崖预见之池的一名被遗忘者女性。这是她在生前由丈夫尤里夫在奔赴战场前交给她的。",al={"坠饰属于谁","这是谁的坠饰","克拉莉斯·弗斯特"}},{q="尤里夫是谁？",a="尤里夫是克拉莉斯生前的丈夫。他抛弃了克拉莉斯和他们的孩子，以圣光的名义去对抗日益严重的亡灵威胁，结果却战死沙场，最终被埋葬在瑟伯切尔的一座荒凉墓穴中。",al={"克拉莉斯的丈夫","谁是尤里夫","尤里夫的墓"}},{q="为什么克拉莉斯想要扔掉坠饰？",a="克拉莉斯怨恨尤里夫将他的圣战和对圣光的虔诚置于她和孩子们之上。他的牺牲毫无意义——他最终还是死了，而她被抛下，最终以亡灵的身份复活，这正是他试图根除的状态。",al={"为什么要扔掉坠饰","为什么克拉莉斯恨尤里夫","克拉莉斯的坠饰任务"}},{q="当坠饰被放在尤里夫的墓上时会发生什么？",a="将坠饰放回尤里夫的墓上，了却了克拉莉斯想要抛弃这件纪念品以及它所代表的痛苦牵挂的愿望。",al={"尤里夫墓发生了什么","墓上的坠饰"}}},fp="17,277,14.572.0,25.437.1,27.186.0,14.213.0,48.259.0,57.130.1"}
P.entries["item:claw-key"] = {n="利爪钥匙",s="利爪钥匙是隐藏在石爪峰猛禽洞穴中的三把德鲁伊钥匙之一。它与古墓钥匙和沉睡者的钥匙一起，是开启受附魔保护的猛禽洞穴宝藏所必需的物品。",h="利爪钥匙是隐藏在石爪峰猛禽洞穴中的三把德鲁伊钥匙之一。它与古墓钥匙和沉睡者的钥匙一起，是开启受附魔保护的猛禽洞穴宝藏所必需的物品。",kw={"古墓洞穴","利爪钥匙","德鲁伊藏宝盒","守门人的钥匙","石爪峰","猛禽洞穴","猛禽洞穴宝藏","大兽穴"},ang={["class:Druid"]="这把钥匙以标志性的利爪德鲁伊命名，反映了暗夜精灵古墓居住者所创造的神圣传统和保护性结界。",["faction:Horde"]="审问被俘的暗夜精灵让部落能够绕过德鲁伊的古老防御，并掠夺储存在石爪峰顶的神圣遗物。"},sec={{t="猛禽洞穴的守卫",b="暗夜精灵德鲁伊在石爪峰高处建立了猛禽洞穴，将其作为圣所和存放强大遗物的仓库。为了确保这些宝藏免受入侵者觊觎，他们将其隐藏在一套分层防御系统之后。宝藏本身被三把不同的附魔锁封印着：古墓钥匙、沉睡者的钥匙和利爪钥匙。每把钥匙都隐藏在一个专门的德鲁伊藏宝盒里，这些盒子伪装成火炬，散落在古墓洞穴蜿蜒的隧道中。"},{t="闯入藏宝盒",b="德鲁伊并没有让这些钥匙处于无人看管或可随意获取的状态。要打开装有利爪钥匙的藏宝盒，必须先获得守门人的钥匙，它被藏在靠近洞穴入口的地方。一旦取回，利爪钥匙便成为打破德鲁伊封印并夺取深藏于山中财富的关键部件。"}},faq={{q="利爪钥匙有什么用？",a="利爪钥匙是解锁猛禽洞穴宝藏所需的三把钥匙之一，这是一个放置在石爪峰猛禽洞穴中心的受附魔保护的石箱。",al={"利爪钥匙用途","利爪钥匙开启什么","猛禽洞穴宝藏钥匙"}},{q="利爪钥匙在哪里可以找到？",a="它被存放在石爪峰猛禽洞穴隧道内一个伪装成火炬的德鲁伊藏宝盒中。打开该藏宝盒需要使用在洞穴入口处获得的守门人的钥匙。",al={"利爪钥匙位置","利爪钥匙在哪里","寻找利爪钥匙"}},{q="除了利爪钥匙外还需要哪些钥匙？",a="要开启猛禽洞穴宝藏，你必须收集利爪钥匙、古墓钥匙和沉睡者的钥匙，它们都散布在洞穴各处的不同藏宝盒中。",al={"其他钥匙","猛禽洞穴钥匙","洞穴所需的钥匙"}},{q="德鲁伊为什么要隐藏这些钥匙？",a="暗夜精灵德鲁伊建造猛禽洞穴是为了将强大的遗物存放在远离窥探的地方，并利用一套复杂的钥匙和隐蔽的藏宝盒系统来阻止入侵者。",al={"为什么要隐藏钥匙","猛禽洞穴背景"}}},fx={["31018164"]={q="利爪钥匙是什么？",a="利爪钥匙是石爪峰的暗夜精灵德鲁伊所制作的三把附魔钥匙之一。它被锁在地下猛禽洞穴里的一个隐秘藏匿处，是专门用来保护他们最珍贵的财宝免受入侵的安全屏障的重要组成部分。",al={"利爪钥匙是什么","利爪钥匙信息","利爪钥匙是什么类型的钥匙"}},e0ebbe01={q="利爪钥匙是从哪里来的，是谁制作的？",a="这把钥匙是由在石爪峰高处建立猛禽洞穴的德鲁伊们锻造的。为了守护他们的遗物，他们制作了这把钥匙，以及兽穴钥匙和沉睡者钥匙，并将它锁在一个需要使用守门人的钥匙才能打开的密盒中。",al={"谁制作了利爪钥匙","利爪钥匙来源","利爪钥匙从哪来"}},["9663afaa"]={q="为什么有人想要利爪钥匙？",a="人们寻找利爪钥匙是因为需要它来打开猛禽洞穴宝库。德鲁伊们将许多强大的神器锁在洞穴深处，并加上了三把特殊的锁，确保只有集齐了所有三把钥匙的人才能取回宝库中隐藏的遗物。",al={"为什么要找利爪钥匙","为什么要拿利爪钥匙","利爪钥匙的作用背景"}}},fp="8,191,22.466.0,20.344.0,30.150.0,32.175.0,50.149.0,35.166.0"}
P.entries["item:cliffspring-river-sample"] = {n="壁泉河水样",s="一个玻璃瓶，装有从黑海岸壁泉河瀑布底部汲取的浑浊、恶臭的水。这是代表奥伯丁的Thundris Windweaver采集的，该水样为威胁这一沿海定居点的侵蚀性腐化提供了确凿证据。",h="一个玻璃瓶，装有从黑海岸壁泉河瀑布底部汲取的浑浊、恶臭的水。这是代表奥伯丁的Thundris Windweaver采集的，该水样为威胁这一沿海定居点的侵蚀性腐化提供了确凿证据。",kw={"奥伯丁","黑木","壁泉","费伍德森林","水样","thundris","试管","瀑布","织风者"},ang={["class:Druid"]="德鲁伊对自然水道的平衡有着敏锐的感知，因此壁泉河水样的非自然毒性是需要紧急研究和净化的首要问题。",["race:NightElf"]="对于奥伯丁的暗夜精灵来说，卡利姆多北部水域的任何腐化，都是费伍德森林蔓延出的灾难性瘟疫的严重预兆。"},sec={{t="污浊的水流",b="壁泉河从黑海岸崎岖的东部高地流下，翻腾着流过古老的石桥，最后汇入薄雾海。近来，这条河流清澈的水质变得污浊，并出现了明显的腐化。由于担心毒水会很快污染奥伯丁的海岸线和水源，暗夜精灵Thundris Windweaver委托旅行者直接从河道下方的瀑布水潭中汲取了这份水样。水样证实了最坏的情况：非自然的腐烂正不断向下游漂流，直逼海岸。"},{t="费伍德森林的回响",b="虽然当地的黑木熊怪居住在上游河岸并深受其黑暗影响，但水样表明这绝非简单的部落骚乱，而是一种更深层的疾病。Thundris认识到，这种恶臭的腐化起源于东部高耸的悬崖之上，即费伍德森林那片枯萎的荒原。这份被污染的水样是确凿的证据，证明困扰山顶的恶魔瘟疫正在渗入黑海岸的流域，迫使奥伯丁的守卫者们必须做出积极应对。"}},faq={{q="壁泉河水样是在哪里采集的？",a="它采集自壁泉河沿岸第一个瀑布下的水潭，位于奥伯丁以北。旅行者必须顺着河流向内陆行进，直到到达一座架空桥下的瀑布。",al={"怎样获取水样","壁泉河位置","瀑布水潭水样"}},{q="为什么Thundris Windweaver需要这些水？",a="Thundris担心河流的污浊会污染奥伯丁附近的沿海水域。收集并检查实物样本可以让他分析腐化的本质，并制定应对计划。",al={"为什么要收集这些水","thundris河流任务","河流水样的用途"}},{q="是什么导致壁泉河变脏的？",a="虽然受腐化的黑木熊怪栖息在河岸边，但Thundris怀疑真正的源头位于更东边的费伍德森林，那里残留的恶魔瘟疫正渗入山区的源头。",al={"什么污染了河流","为什么水被腐化了","河流腐化的源头"}},{q="是黑木熊怪造成的毒害吗？",a="它们加剧了河岸边的问题，但它们并非根本原因。熊怪本身也是从东部荒芜之地冲刷下来的大规模腐化的受害者。",al={"是熊怪做的吗","黑木熊怪腐化","熊怪在毒害水源吗"}}},fx={["2e135e3b"]={q="壁泉河水样是什么？",a="这是一瓶取自壁泉河瀑布底部、用空的水样试管收集的恶臭的受污染河水。它有力地证明了一种邪恶的腐蚀正顺流而下，穿过黑海岸。",al={"壁泉河水样","壁泉河水样是什么"}},["57059c85"]={q="壁泉河水样是从哪里来的？",a="该水样采集自奥伯丁以北，壁泉河第一道瀑布下方的水潭中。虽然是你自己用空的水样试管采集的天然河水，但其不自然的恶臭源于上游从费伍德森林流下的腐化力量。",al={"壁泉河水样从哪来","壁泉河水样来源","谁制作了壁泉河水样"}}},fp="24,275,17.572.0,17.522.1,48.206.0,45.211.0,51.197.0,54.199.0"}
P.entries["item:cloth-request"] = {n="布料订单",s="布料订单是一张由暴风城商人哈兰·巴格雷亲笔书写的订单。这份便条是写给运河裁缝店的雷玛·施涅德的，旨在寻求新鲜的布匹和针织品，以补充巴格雷货架上迅速消耗的库存。",h="布料订单是一张由暴风城商人哈兰·巴格雷亲笔书写的订单。这份便条是写给运河裁缝店的雷玛·施涅德的，旨在寻求新鲜的布匹和针织品，以补充巴格雷货架上迅速消耗的库存。",kw={"运河裁缝店","布料订单","哈兰·巴格雷","雷玛·施涅德","补货","暴风城"},ang={["faction:Alliance"]="对耐用服装的抢购反映了暴风城市民心中那种显而易见的忧虑，尽管摄政王室没有发布任何官方公告，但他们已经在为冲突做准备了。",["profession:Tailoring"]="这份请求突显了暴风城内部繁忙的纺织贸易，像施涅德家族这样的社区裁缝为杂货店和服装店供应纺织品。"},sec={{t="对耐用品的抢购",b="这份由哈兰·巴格雷书写的贸易征购单，向运河区的裁缝们请求补充新鲜的针织服装和布料。巴格雷指出，商业活动出现了一次突然且令人不安的激增：普通市民和旅行者正在大量囤积护甲和耐用的服装，仿佛在为一个残酷的季节做准备。当这份请求被送到雷玛·施涅德手中时，令这位裁缝感到困惑和警惕。雷玛想知道，既然贵族议会并没有宣布公开开战，为什么城市居民却在悄悄地武装自己，这引发了人们暗中的猜疑，认为王室的领导人正在掩盖社会动荡。"}},faq={{q="布料订单是什么？",a="这是一份来自店主哈兰·巴格雷的书面补货申请，请求裁缝雷玛·施涅德提供新鲜的布料和针织品以补充他的商店库存。",al={"布料订单是什么","布料订单物品","哈兰的订单便条"}},{q="哈兰·巴格雷为什么需要更多的布料？",a="巴格雷的生意异常繁忙。城镇居民和旅行者正在大量购买护甲和耐用的服装，导致他的库存告急。",al={"哈兰为什么需要布料","巴格雷为什么缺货","巴格雷补货原因"}},{q="这份请求需要送到哪里？",a="这张订单被带往位于暴风城水道旁的运河裁缝店，交给雷玛·施涅德。",al={"布料订单要交给谁","谁收到布料订单","布料订单交付"}},{q="暴风城的居民为什么在大量购买护甲和服装？",a="商人和平民都无法确定原因。雷玛·施涅德觉得这种突然的抢购令人不安，他怀疑贵族议会是否在向公众隐瞒正在酝酿的敌对行动或危险。",al={"人们为什么要买护甲","暴风城处于战争状态吗","雷玛·施涅德的怀疑"}}},fx={b4374b3c={q="布料订单是从哪里来的，是谁写的？",a="这份请求由暴风城的店主哈兰·巴格雷所写。随着市民们购买结实的衣服和护甲，生意突然激增，巴格雷写下这张征购单是为了确保能再获得一批针织服装，并保持货架充盈。",al={"谁写了布料订单","布料订单来源","布料订单从哪来"}}},fp="13,150,21.430.0,26.123.0,39.147.0,35.95.0,62.193.0"}
P.entries["item:cloven-hoof"] = {n="裂开的蹄子",s="裂开的蹄子是一件神秘遗物，由千针石林的加拉克半人马部落守护在深处。它被保存在裂蹄堡的一团古老圣火之中，散发出一种不同寻常的超自然能量，牛头人学者们非常渴望了解它。",h="裂开的蹄子是一件神秘遗物，由千针石林的加拉克半人马部落守护在深处。它被保存在裂蹄堡的一团古老圣火之中，散发出一种不同寻常的超自然能量，牛头人学者们非常渴望了解它。",kw={"古老火盆","裂开的蹄子","加拉克","劳恩·峭壁行者","圣火","裂蹄峭壁","裂蹄堡"},ang={["class:Shaman"]="利用仪式元素安全地熄灭魔法火焰并取回被赋予魔力的遗物，凸显了卡利姆多灵性探索的微妙本质。",["race:Tauren"]="几代以来，游牧的牛头人一直遭受半人马的无情侵略。揭开像裂开的蹄子这类遗物背后的起源和魔法秘密，为对抗他们的历史宿敌提供了宝贵的知识。"},sec={{t="一件神圣的半人马遗物",b="裂开的蹄子被安放在裂蹄堡最深处的一个古老火盆中，是加拉克半人马最珍贵的遗物之一。这件神器持续被魔法火焰包裹，需要用圣水短暂熄灭火焰才能接触它。半人马社会以残酷和分裂成好战的氏族而闻名，但他们对火盆的崇敬表明这与他们的起源有着直接的仪式联系。像乱风岗的劳恩·峭壁行者这样的牛头人观察者认为，从蹄子上散发出的奇异光环可能会揭示关于这个世代困扰卡利姆多平原的种族的深刻见解。"}},faq={{q="裂开的蹄子保存在哪里？",a="裂开的蹄子安放在裂蹄堡最里侧的古老火盆内，裂蹄堡是乱风岗以北裂蹄峭壁内的一处洞穴。它由加拉克半人马的精英战士严密守卫。",al={"裂开的蹄子位置","哪里可以找到裂开的蹄子","裂蹄堡遗物"}},{q="为什么劳恩·峭壁行者想要裂开的蹄子？",a="劳恩·峭壁行者试图研究这件神器，以了解更多关于半人马起源和魔法的信息。他感应到遗物中散发出的奇异能量，希望借此解开关于这些敌对氏族长期隐藏的秘密。",al={"为什么要获取裂开的蹄子","劳恩·峭壁行者任务","谁想要裂开的蹄子"}},{q="如何从火盆中取回裂开的蹄子？",a="这件遗物被魔法火焰包裹，无法直接取走。必须将一瓶特殊的水倒入古老的火盆中，暂时浇灭圣火，以便在火焰重新燃起之前安全地拿走蹄子。",al={"如何获取裂开的蹄子","浇灭圣火","装满水的蚀刻瓶用途"}},{q="守护它的加拉克半人马是什么人？",a="加拉克部落是占据千针石林北部地区的主要半人马势力。他们在裂蹄峭壁建立了据点，并积极抵御外来者以捍卫他们的圣火。",al={"加拉克半人马","裂蹄峭壁半人马","谁在守护圣火"}}},fx={b52742f5={q="裂开的蹄子是什么？",a="裂开的蹄子是一件古老而神秘的遗物，受到千针石林加拉克半人马的崇拜。它被封存在裂蹄堡深处的永恒圣火中，散发出一种奇怪的、未被研究过的能量，引起了牛头人研究人员的极大好奇。",al={"裂开的蹄子是什么","裂开的蹄子遗物","蹄子是什么"}}},fp="11,259,22.647.0,30.200.0,46.215.0,50.240.0,38.203.0"}
P.entries["item:comar-s-heart"] = {n="Comar's Heart",s="Comar's Heart是一个令人毛骨悚然的仪式材料，它取自科玛·维拉德。科玛·维拉德是一个忠诚的人类流浪者，正在湿地的沼泽中寻找失踪的妻子。幽暗城的被遗忘者术士们寻找这种纯粹奉献的圣物，以供奉魅魔的召唤仪式。",h="Comar's Heart是一个令人毛骨悚然的仪式材料，它取自科玛·维拉德。科玛·维拉德是一个忠诚的人类流浪者，正在湿地的沼泽中寻找失踪的妻子。幽暗城的被遗忘者术士们寻找这种纯粹奉献的圣物，以供奉魅魔的召唤仪式。",kw={"凯伦丁·哈加尔","科玛·维拉德","comar's heart","纯洁之心","魅魔","诅咒神庙","幽暗城","湿地"},ang={["class:Warlock"]="获取Comar's Heart展现了恶魔学识那冰冷而务实的残忍：无瑕的凡人美德仅仅是被用来引诱魅魔成为你奴仆的诱饵。",["race:Undead"]="对于被遗忘者来说，收割一颗忠诚的人类爱人的心脏，凸显了洛丹伦生者与亡者之间彻底的情感隔绝。"},sec={{t="纯洁的灯塔",b="为了束缚像魅魔这样反复无常且极具掠夺性的生物，术士必须用真正的纯洁和奉献来引诱恶魔。凯伦丁·哈加尔在幽暗城的弟子们认定科玛·维拉德是少数拥有这种无瑕忠诚的人之一。当他的妻子在席卷东部王国的动荡中失踪后，科玛固执地徘徊在湿地潮湿的道路上，拒绝放弃寻找。正是这份坚定不移的爱让他成为了屠戮的目标，让他那颗依然跳动的心脏成为了诱捕恶魔仆从的绝佳诱饵。"},{t="诱惑的代价",b="获取这颗心脏需要被遗忘者学徒们深入南方，穿过纷争领土，越过萨多尔大桥，深入联盟控制的沼泽。这颗器官被带回诅咒神庙，与达林的心脏放在一起。尽管它曾经蕴含着深厚的善良，但现在看起来却极为平凡。然而，在扭曲虚空的感官看来，从科玛的血肉中散发出的残留美德是令人陶醉的诱饵，足以将一只魅魔从维度面纱的另一侧吸引过来，并使其成为术士的奴仆。"}},faq={{q="科玛·维拉德是谁？",a="科玛·维拉德是一位忠诚的人类，他在危险的湿地中寻找失踪妻子的任何踪迹。他那永无止境的爱和拒绝放弃希望的坚定使他以一个真正纯洁的人而闻名。",al={"comar是谁","科玛·维拉德背景故事","为什么要杀死科玛"}},{q="术士为什么需要Comar's Heart？",a="幽暗城的术士需要一颗完全纯洁且高尚的凡人之心来引诱并束缚魅魔。恶魔天生就会被真正的美德所吸引，想要腐化并以此为食，这使得科玛坚定不移的奉献成为了无法抗拒的诱饵。",al={"为什么需要科玛的心脏","comar's heart有什么用","魅魔心脏背景故事"}},{q="在哪里可以找到科玛·维拉德？",a="他徘徊在湿地北部的主路上，就在连接阿拉希高地和卡兹莫丹的萨多尔大桥南侧。",al={"科玛·维拉德位置","科玛在哪里","如何找到科玛"}},{q="是谁派遣术士去收集这颗心脏？",a="该任务由幽暗城的术士训练师指派，并由诅咒神庙内的凯伦丁·哈加尔指导，这是学徒召唤魅魔的仪式训练的一部分。",al={"谁想要comar's heart","谁提供纯洁之心","凯伦丁·哈加尔的心脏"}}},fx={["7acb4df8"]={q="Comar's Heart是什么？",a="Comar's Heart是直接从湿地中一位忠诚的人类流浪者Comar Villard的遗体中取出的心脏。术士们将其视为一种罕见的纯洁美德标本，浸透着忠诚和永恒的爱。",al={"comar's heart是什么","comar's heart物品","comar's heart背景"}},a49b76cf={q="Comar's Heart是从哪里来的？",a="它直接取自Comar Villard的胸膛，此人正在湿地险恶的沼泽中寻找他失踪妻子的踪迹。它并非由魔法锻造的神器，而是一个凡人的器官，其纯粹的奉献使它成为一种强效的仪式试剂。",al={"comar's heart从哪来","谁制作了comar's heart","comar's heart来源"}}},fp="13,268,18.556.0,22.505.1,22.204.0,35.239.0,29.133.0,40.188.0"}
P.entries["item:consecrated-rune"] = {n="神圣符文",s="神圣符文是一件铭刻了神圣文字的物品，专门交给在寒脊山谷受训的矮人圣骑士新兵。它也是布罗莫斯·格鲁诺尔发出的一份入门召集令，指引新兵前往安威玛尔报到，并开始履行他们作为白银之手骑士团成员的正式职责。",h="神圣符文是一件铭刻了神圣文字的物品，专门交给在寒脊山谷受训的矮人圣骑士新兵。它也是布罗莫斯·格鲁诺尔发出的一份入门召集令，指引新兵前往安威玛尔报到，并开始履行他们作为白银之手骑士团成员的正式职责。",kw={"安威玛尔","布罗莫斯·格鲁诺尔","寒脊山谷","神圣符文","圣光","圣骑士","白银之手"},ang={["class:Paladin"]="对于矮人圣骑士来说，收到这枚符文代表着在布罗莫斯·格鲁诺尔的指导下，正式迈入白银之手骑士团的行列。",["race:Dwarf"]="这枚符文反映了人类神圣传统融入矮人军事文化的历程，其根源在于铁炉堡与人类之间牢固的联盟和相互尊重。"},sec={{t="白银之手的召唤",b="在寒脊山谷证明了自己实力的矮人圣骑士新兵，一旦展现出基本的战斗能力，就会被授予一枚神圣符文。这枚符文铭刻着神圣的文字，并经过圣光的祝福，它出自安威玛尔内的圣骑士训练师布罗莫斯·格鲁诺尔之手。矮人对人类盟友引入的圣光传统抱有极大的敬意。阅读这枚符文既是一种正式的召集，也是一种象征性的成年礼，确认了新兵在白银之手骑士团中的地位。"}},faq={{q="神圣符文有什么用途？",a="这枚符文是一份书面召集令，供矮人圣骑士新兵阅读。它指示新兵在安威玛尔内寻找布罗莫斯·格鲁诺尔，以继续进行他们的圣骑士训练。",al={"神圣符文用途","符文的作用","神圣符文任务物品"}},{q="神圣符文是谁发出的？",a="它是由布罗莫斯·格鲁诺尔发出的，他是驻扎在寒脊山谷安威玛尔内的矮人圣骑士训练师。",al={"谁给了我神圣符文","符文来源","布罗莫斯·格鲁诺尔符文"}},{q="为什么矮人圣骑士会遵循白银之手的传统？",a="矮人从人类导师那里学到了许多关于圣光和白银之手教义的知识。他们对该组织的悠久历史、传统以及“单次牺牲就能改变艾泽拉斯命运”的信仰怀有崇高的敬意。",al={"矮人圣骑士白银之手","矮人为何能成为圣骑士","矮人与圣光"}}},fx={dda1df9e={q="神圣符文是什么？",a="这是一块在圣光中加持过的矮人铭文石，作为一份正式的征召令，发送给正在寒脊山谷训练的圣骑士新兵。矮人将符文工艺与圣教结合，使用像这样的石头来传达庄严的信息，并召唤圣光的初学者们前往导师处。",al={"神圣符文是什么","神圣符文物品","神圣符文含义"}},["924bde77"]={q="为什么布罗莫斯·格鲁诺尔想要你拥有神圣符文？",a="布罗莫斯·格鲁诺尔寄出这枚符文是为了测试你的准备情况，并指引你前往安威玛尔进行正式训练。整个丹莫罗正面临麻烦，白银之手骑士团需要有能力、受过纪律训练的勇士，随时准备履行神圣职责，保护艾泽拉斯免受伤害。",al={"为什么要有神圣符文","为什么布罗莫斯想要神圣符文","我为什么要拿神圣符文"}}},fp="16,275,28.546.0,38.169.0,31.105.0,65.222.0"}
P.entries["item:console-key"] = {n="控制台钥匙",s="控制台钥匙是一把机械旁路钥匙，由位于贫瘠之地的风险投资公司挖掘场的风险投资公司修理工斯尼格尔斯持有。它能解锁装有测距仪的主控制终端，从而在装置关闭后将其取出。",h="控制台钥匙是一把机械旁路钥匙，由位于贫瘠之地的风险投资公司挖掘场的风险投资公司修理工斯尼格尔斯持有。它能解锁装有测距仪的主控制终端，从而在装置关闭后将其取出。",kw={"贫瘠之地","控制台钥匙","控制台","测距仪","风险投资公司修理工斯尼格尔斯","荆棘谷地精"},ang={["faction:Horde"]="从风险投资公司修理工斯尼格尔斯手中夺取控制台钥匙，有助于破坏风险投资公司在贫瘠之地腹地的剥削性工业行动。",["profession:Engineering"]="风险投资公司使用定制的带锁装置来保护像测距仪这样精密的工程原型免受竞争对手的侵害。"},sec={{t="保护设备",b="风险投资公司在北部贫瘠之地维护着一个庞大的工业前哨站，依赖于一种被称为测距仪的神秘装置来调节专门的蒸汽驱动机械。为了防止未经授权的篡改，设备控制台被紧紧锁住。只有现场的首席技术员，风险投资公司修理工斯尼格尔斯，随身携带打开终端外壳并完全切断钻机电源所需的控制台钥匙。"},{t="关闭钻机",b="禁用控制台不仅仅需要蛮力。一旦辅助阀门被操作，内部设备冷却到空转状态，插入控制台钥匙就能切断最后的电路。转动钥匙会耗尽终端中剩余的能量，解锁外壳，这样就可以从机械中安全地撬出测距仪。"}},faq={{q="控制台钥匙能解锁什么？",a="它能解锁北部贫瘠之地风险投资公司钻机上的主控制台，在机械空转后，使测距仪暴露出来并耗尽终端的能量。",al={"控制台钥匙的作用","控制台钥匙打开什么","控制台钥匙的使用"}},{q="谁携带控制台钥匙？",a="这把钥匙由风险投资公司修理工斯尼格尔斯保管，他是一名驻扎在主控制设备东北方小屋里的风险投资公司工程师。",al={"谁掉落控制台钥匙","哪里获得控制台钥匙","风险投资公司修理工斯尼格尔斯的钥匙"}},{q="控制台为什么要锁住？",a="风险投资公司运营着专利且危险的工业技术。锁定终端可以防止爱管闲事的竞争对手或不守规矩的劳工破坏机械或窃取像测距仪这样贵重的组件。",al={"为什么需要钥匙","为什么测距仪被锁住"}},{q="可以在关闭阀门之前使用钥匙吗？",a="这把钥匙旨在设备断电且仪表读数为零后解锁控制台。试图在活动状态下篡改控制台有导致机械彻底反噬的风险。",al={"先使用钥匙","能直接解锁控制台吗"}}},fx={["4424a0fd"]={q="控制台钥匙是什么？",a="控制台钥匙是负责管理贫瘠之地控制台的荆棘谷地精技师所持有的一把机械安全钥匙。它能插入包裹着调节器的锁定外壳中，确保只有获得授权的人员才能接触到精密的机械和终端内部结构。",al={"控制台钥匙","控制台钥匙是什么"}},["81c16021"]={q="为什么有人想要控制台钥匙？",al={"为什么要拿控制台钥匙","我为什么需要控制台钥匙","控制台钥匙的作用"}}},fp="11,253,22.419.0,21.360.1,33.179.0,28.132.0,45.222.0,52.186.0"}
P.entries["item:control-console-operating-manual"] = {n="控制台操作手册",s="《控制台操作手册》是一份技术文档，详细说明了如何操作位于淤泥沼泽西南方的荆棘谷地精研究站的机械。手册中包含了安全关闭阀门并拆卸被称为“萨摩法兰”的神秘装置所需的说明。",h="《控制台操作手册》是一份技术文档，详细说明了如何操作位于淤泥沼泽西南方的荆棘谷地精研究站的机械。手册中包含了安全关闭阀门并拆卸被称为“萨摩法兰”的神秘装置所需的说明。",kw={"贫瘠之地","控制台","地精工程","操作手册","萨摩法兰","淤泥沼泽","荆棘谷地精"},ang={["faction:Horde"]="这本手册为部落的调查员提供了深入了解荆棘谷地精在贫瘠之地北部建立的侵入性工业行动的机会。",["profession:Engineering"]="这本手册阐述了典型的地精工程理念：依靠混乱的杠杆和阀门阵列来管理高压且安全性边缘化的系统，而不是通过平衡的故障安全机制。"},sec={{t="解读地精机械",b="荆棘谷地精在贫瘠之地北部，也就是淤泥沼泽的西南方，运营着一个隐蔽的钻探与研究点。按照地精的一贯作风，他们复杂的机械运行在一系列不稳定的仪表、压力阀和相互连接的机制上，旨在利用一种名为“萨摩法兰”的装置。如果没有正确的操作程序，操纵这些不稳定的装置会有引发灾难性反噬或系统完全锁死的风险。这份操作手册概述了安全拆卸核心装置所需的精确阀门操纵顺序，以避免引发爆炸性故障。"}},faq={{q="《控制台操作手册》有什么用途？",a="它提供了操作位于淤泥沼泽西南方的荆棘谷地精控制台的操作说明，指引你关闭相应的阀门，以便拆卸萨摩法兰。",al={"手册有什么用","手册用途","为什么我有操作手册"}},{q="什么是萨摩法兰？",a="即使是荆棘谷地精之外的研究人员，也并不完全了解萨摩法兰的作用。它看起来是一种精巧的地精工程核心机制，与他们在贫瘠之地的钻探和工业作业有关。",al={"萨摩法兰有什么用","萨摩法兰背景","这是什么机器"}},{q="谁编写了这本手册？",a="这本手册由负责监管该研究前哨站的荆棘谷地精技术人员起草，旨在确保他们的工人能够操作控制台并保持其控制阀的压力水平处于最佳状态。",al={"谁制作了手册","手册作者"}},{q="如果我不小心弄丢了手册会怎样？",a="控制台本身配有清晰的仪表和读数，显示阀门压力，这意味着熟练的冒险者可以直接读取控制台面板，无需手头持有实体文本即可操作开关。",al={"丢失手册","删除了操作手册"}}},fx={["4b9f7b43"]={q="控制台操作手册是什么？",a="这是从荆棘谷地精那里回收的一本操作指南，详细介绍了淤泥沼泽西南方研究设施中控制台的操作方法。它概述了他们的机械运作方式，以便技术人员可以安全地操纵其阀门并拆卸设备。",al={"控制台操作手册是什么","控制台操作手册","荆棘谷地精手册"}},["5e9de40e"]={q="为什么要寻找控制台操作手册？",a="手册提供了关闭并拆卸荆棘谷地精神秘调节器所需的具体操作步骤。如果不解读其说明，盲目摆弄控制台上那些不稳定的操纵杆、按钮和加压控制阀几乎是不可能的。",al={"为什么要找控制台操作手册","为什么需要手册","手册有什么用"}}},fp="32,289,28.603.0,54.215.0,22.230.0,22.209.0,34.214.0"}
P.entries["item:corroded-shrapnel"] = {n="被腐蚀的弹片",s="被腐蚀的弹片是深深嵌入石爪山脉被腐化的树人体内的锯齿状金属碎片。这些碎片从焦黑的古树和发黑的古树等倒下的保护者身上回收而来，是荆棘谷地精在撤退时使用邪恶武器的实物证据。",h="被腐蚀的弹片是深深嵌入石爪山脉被腐化的树人体内的锯齿状金属碎片。这些碎片从焦黑的古树和发黑的古树等倒下的保护者身上回收而来，是荆棘谷地精在撤退时使用邪恶武器的实物证据。",kw={"焦黑的古树","被腐蚀的弹片","加克希姆","凯拉·影矛","石爪山脉","树人","荆棘谷地精"},ang={["class:Druid"]="看到卡利姆多雄伟的古树被地精的工业弹药和溃烂的金属碎片扭曲，这是对不受约束的开发给荒野造成破坏的沉重提醒。",["race:Gnome"]="加克希姆对这些受污染弹片的追求，展现了侏儒在解决令传统的林地哨兵感到困惑的生态异常现象时所采取的务实、科学的态度。"},sec={{t="工业废墟的残余",b="当荆棘谷地精被赶出石爪山脉的树林时，这些地精为了掩护撤退，疯狂地动用了残暴的弹药。来自这些爆炸性武器的弹片撕裂了山谷中守卫的树人，锯齿状的金属深深嵌入了它们的树皮和核心。这些古老的守护者没能自愈，反而慢慢陷入了腐化，木质变黑，并将愤怒转向了任何踏入山谷的人。从这些受伤的保护者身上回收的锈迹斑斑、受到污染的碎片是凯拉·影矛所寻求的物品，以便让侏儒加克希姆·尘链能够分析这种腐化的确切机制。"}},faq={{q="这些弹片来自哪里？",a="被腐蚀的弹片是从石爪山脉被腐化的树人身上打捞出来的，包括焦黑的古树、发黑的古树和复仇的古树。",al={"我在哪里能找到弹片","被腐蚀的弹片掉落","谁掉落弹片"}},{q="为什么弹片会嵌入树人的体内？",a="当森林守护者起义将地精伐木工赶出山谷时，荆棘谷地精向树人发射了爆炸性的锯齿状弹药。金属碎片在战斗中嵌入了它们的树皮，并从此留在了里面。",al={"弹片是如何进入树人体内的","为什么树人体内全是金属"}},{q="弹片是导致森林古树腐化的原因吗？",a="根据凯拉·影矛的说法，侏儒加克希姆认为导致树人患病的腐化与地精撤退时使用的武器中肮脏的化学成分或金属构成直接相关。",al={"弹片是否腐化了树人","为什么树人会发狂"}},{q="谁想要检查这些弹片？",a="暗夜精灵凯拉·影矛请求获取样本，以便将其转交给侏儒发明家加克希姆，后者打算研究其特性，从而揭开树人痛苦的本质。",al={"谁需要这些弹片","弹片上交"}}},fx={["1f081bfa"]={q="被腐蚀的弹片是什么？",a="被腐蚀的弹片是由地精武器留下的锯齿状金属碎片。这些退化、生锈的爆炸性弹药碎片深深嵌入石爪山脉树人的树皮中，被认为带有挥之不去的毒素或邪恶的腐蚀，折磨着森林的守护者。",al={"被腐蚀的弹片是什么","被腐蚀的弹片背景","被腐蚀的弹片物品"}}},fp="17,302,27.617.0,35.162.0,44.225.0,63.202.0,34.189.0"}
P.entries["item:corrupt-manifestation-s-bracers"] = {n="堕落水之魂的护腕",s="堕落水之魂的护腕是人们在银松森林海岸的一只被污染的水元素身上发现的残留物。在执行Call of Water的萨满祭司学徒们取走这些护腕后，它们成为了在永恒之泉火盆上进行元素净化仪式的关键材料。",h="堕落水之魂的护腕是人们在银松森林海岸的一只被污染的水元素身上发现的残留物。在执行Call of Water的萨满祭司学徒们取走这些护腕后，它们成为了在永恒之泉火盆上进行元素净化仪式的关键材料。",kw={"永恒之泉火盆","call of water","堕落水之魂的护腕","萨满祭司任务","银松森林","水元素"},ang={["class:Shaman"]="找回并净化这些护腕是Call of Water的最终考验，它证明了萨满祭司安抚并恢复扭曲元素力量的能力。"},sec={{t="净化祭品",b="当亡灵天灾的瘟疫席卷洛丹伦时，这片土地上的自然之灵也未能幸免。在瑟伯切尔以西、银松森林那雾气缭绕的海岸边，一座曾经神圣的水之祭坛遭受了污染，导致栖息于此的水之魂被扭曲，变成了一个充满敌意的、堕落的阴影。萨满祭司学徒们被派去镇压这只生物并取回它的护腕。这些护腕与永恒之泉火盆上的纯净之水结合，投入火焰之中，以消除污染并召唤出一个纯净的元素之灵。"}},faq={{q="这些护腕有什么用途？",a="在净化仪式中，它们会被与几滴纯净之水一同放置在永恒之泉火盆上。这个仪式可以驱散银松森林祭坛上残留的腐化，并引出纯净的水之魂。",al={"护腕的作用","call of water护腕","堕落护腕的用途"}},{q="这些护腕是从哪里来的？",a="它们取自堕落的水之魂的残骸，该生物位于瑟伯切尔以西、银松森林海岸边的一个被污染的元素祭坛附近。",al={"在哪里获得护腕","堕落水之魂的位置"}},{q="为什么水元素会腐化？",a="该元素受到了蹂躏洛丹伦大地的瘟疫和黑暗力量的扭曲，使得当地的自然之灵与萨满祭司的沟通中断。",al={"为什么水被污染","银松森林水体腐化"}}},fx={["0d8aeb2f"]={q="堕落水之魂的护腕是什么？",a="这些护腕是与在银松森林受污染海岸线上发现的一种被腐化的水之魂绑定的物理残留物。像许多与凡世位面相连的元素生物一样，水之魂佩戴着护腕来锚定和塑造其液态形态。即使在生物被消灭后，护腕仍保留着元素生物受腐化存在的精神残留，使其成为仪式净化的重要催化剂。",al={"堕落水之魂的护腕是什么","堕落水之魂的护腕","这些护腕是什么"}}},fp="31,283,20.539.0,32.208.0,31.175.0,43.152.0"}
P.entries["item:corrupted-brain-stem"] = {n="堕落者的脑干",s="堕落者的脑干是从栖息在黑暗深渊和灰谷海岸线的扭曲娜迦与萨特身上采集的生物样本。奥伯丁的戈沙拉·夜语希望能通过研究这些样本，来探索鲁莽的魔法腐蚀所造成的生理畸变。通过检查这些大脑，暗夜精灵学者希望能够理解并尽可能防止同样的命运降临在血精灵身上。",h="堕落者的脑干是从栖息在黑暗深渊和灰谷海岸线的扭曲娜迦与萨特身上采集的生物样本。奥伯丁的戈沙拉·夜语希望能通过研究这些样本，来探索鲁莽的魔法腐蚀所造成的生理畸变。通过检查这些大脑，暗夜精灵学者希望能够理解并尽可能防止同样的...",kw={"灰谷","奥伯丁","黑暗深渊","堕落者的脑干","戈沙拉·夜语","娜迦","研究腐蚀","萨特"},ang={["faction:Alliance"]="被派往灰谷的联盟斥候深入黑暗深渊的底部，以协助奥伯丁的学者了解艾泽拉斯各地日益增长的威胁。",["race:NightElf"]="对于暗夜精灵来说，收集这些遗骸是对他们种族悲剧历史，以及不受限制的奥术和邪能干预所导致的怪物化结果的严酷提醒。"},sec={{t="变形的解剖学",b="卡利姆多的萨特与娜迦是禁忌魔法与恶魔契约扭曲力量的活见证。很久以前，鲁莽的卡多雷上层精灵不可逆转地变成了蛇形水生野兽和长角的恶魔怪物。从这些生物身上采集的脑干表现出严重的生理突变，为腐蚀性能量如何深入曾经是精灵的生物的神经系统提供了直接的解剖学证据。"},{t="戈沙拉的警告",b="在奥伯丁的沿海定居点，暗夜精灵戈沙拉·夜语观察到了有关东部王国血精灵的令人不安的传闻。戈沙拉担心他们对恶魔巫术的接触会催生出艾泽拉斯的又一代怪物，因此委托冒险者前往黑暗深渊。通过解剖娜迦和萨特的组织，这位研究者希望在又一种精灵文化毁灭之前，探明魔法退化的路径。"}},faq={{q="哪些生物会掉落堕落者的脑干？",a="它们是从居住在黑暗深渊内以及灰谷周围海岸的娜迦和萨特身上收集的，包括黑暗深渊神谕者、海巫和落根萨特。",al={"谁掉落脑干","堕落者的脑干掉落","在哪里获得脑干"}},{q="谁需要这些脑干，为什么？",a="驻扎在黑海岸奥伯丁的戈沙拉·夜语要求收集这些样本，以对魔法腐蚀进行解剖学研究。",al={"谁需要堕落者的脑干","戈沙拉任务","上交脑干"}},{q="暗夜精灵希望从这些标本中学到什么？",a="戈沙拉担心血精灵对恶魔魔法的使用会使他们变成怪物，就像古代的上层精灵变成娜迦和萨特一样。研究这些脑干有助于确定恶魔能量如何改变精灵的生物学特征。",al={"为什么要研究娜迦和萨特","研究腐蚀背景故事","与血精灵的联系"}},{q="在黑暗深渊洞穴之外能找到这些吗？",a="可以。在灰谷海岸的洞穴入口外徘徊的某些落根萨特和黑暗深渊潮汐女祭司也会携带它们。",al={"黑暗深渊之外","灰谷脑干","地表怪物掉落吗"}}},fx={["3ff1da04"]={q="堕落者的脑干是什么？",a="堕落者的脑干是一种解剖学标本，从居住在黑暗深渊内及周边的萨特和娜迦身上采集而来。这两个种族曾经都是暗夜精灵，但其身体和思想被恶魔契约或古老而阴暗的深渊暴力地扭曲了。这些脑干带有这种魔法变形的生理特征，使它们成为研究黑暗魔法如何扭曲凡人血肉的学者的宝贵解剖研究对象。",al={"堕落者的脑干是什么","堕落者的脑干物品","堕落者的脑干背景"}},["53f0c38a"]={q="堕落者的脑干是从哪里来的？",al={"堕落者的脑干来源","谁掉落堕落者的脑干","堕落者的脑干出处"}}},fp="20,403,25.444.0,18.475.0,44.186.0,36.136.0,58.226.0,60.144.0"}
P.entries["item:corrupted-kor-gem"] = {n="被污染的科尔宝石",s="被污染的科尔宝石是一种强效的魔法导管，被居住在黑暗深渊周围的纳迦通过黑暗仪式所扭曲。施法者觊觎此类宝石，因为它们能够储存纯粹的奥术力量，但宝石被玷污的状态需要先经过净化，才能用于正义的工艺。",h="被污染的科尔宝石是一种强效的魔法导管，被居住在黑暗深渊周围的纳迦通过黑暗仪式所扭曲。施法者觊觎此类宝石，因为它们能够储存纯粹的奥术力量，但宝石被玷污的状态需要先经过净化，才能用于正义的工艺。",kw={"黑暗深渊","被污染的科尔宝石","科尔宝石","纳迦","净化","桑德斯·织风","潮汐女巫"},ang={["class:Paladin"]="寻求锻造神圣武装的圣骑士必须找回并净化一颗科尔宝石，以证明他们有能力面对邪恶，并将黑暗转化为正义的力量。",["race:NightElf"]="像桑德斯·织风这样的暗夜精灵学者认识到了纳迦遗物入侵黑海岸的危险，并守护着净化这些古老宝石所需的知识。"},sec={{t="污秽之力的容器",b="科尔宝石天生就拥有捕获并容纳大量魔法能量的稀有能力，这使它们成为术士和附魔锻造中不可或缺的焦点。然而，在靠近黑暗深渊遗迹的海岸线上，当地的纳迦神谕者和潮汐女巫将这些宝石据为己有，用于她们那阴暗的仪式。通过邪恶的附魔，这些蛇人扭曲了宝石，使其充斥着邪恶的、来自海洋的腐化。虽然这种灌注玷污了宝石的本质，但其核心的潜能依然强大，吸引着那些需要特殊魔法焦点的人从纳迦手中夺取它们。"},{t="净化与锻造",b="被污染的科尔宝石必须先经过净化，桑德斯·织风才会允许将其带给乔丹·斯迪威尔。这位奥伯丁的暗夜精灵会清除纳迦的邪恶魔法，并向圣骑士保证宝石的力量完好无损，随时可以进行铁匠的仪式。"}},faq={{q="科尔宝石有什么用途？",a="科尔宝石充当着奥术能量的强效导管和容器。施法者利用它们为咒语储存巨大的能量储备，而熟练的铁匠则将其嵌入附魔武器中以引导魔法力量。",al={"什么是科尔宝石","科尔宝石的用途","科尔宝石背景故事"}},{q="哪里可以找到被污染的科尔宝石？",a="被污染的科尔宝石由纳迦施法者携带——特别是黑暗深渊潮汐女巫和黑暗深渊神谕者——她们居住在位于灰谷和黑海岸边界的、通往黑暗深渊的古老遗迹内外。",al={"哪里可以找到被污染的科尔宝石","科尔宝石位置","谁掉落科尔宝石"}},{q="为什么要净化这颗宝石？",a="纳迦在仪式中用邪恶的魔法浸透了这些宝石。试图在神圣的工艺中使用被污染的宝石可能会污染锻炉或使用者，因此需要像桑德斯·织风这样的自然或圣光大师在将其锻造成武器之前清除邪恶。",al={"净化科尔宝石","为什么要净化科尔宝石","这颗宝石是邪恶的吗"}},{q="净化宝石会保留其力量吗？",a="是的。在净化宝石后，桑德斯·织风向圣骑士保证其力量完好无损，并且应该非常适合乔丹·斯迪威尔的仪式。",al={"净化会毁掉宝石吗","净化后会变弱吗"}}},fx={["114a4618"]={q="什么是被污染的科尔宝石？",a="被污染的科尔宝石是一种原本用于储存原始奥术或施法能量的魔法容器，但被黑暗魔法扭曲了。娜迦施法者将她们自己邪恶的力量注入了这块石头，将原本中立的导管变成了充满恶意的被玷污的圣物。",al={"什么是被污染的科尔宝石","被污染的科尔宝石信息","介绍被污染的科尔宝石"}},["1218ae71"]={q="被污染的科尔宝石是从哪里来的，它是谁制造的？",a="虽然科尔宝石最初是为施法者储存魔法能量而制作的导管，但这些被污染的版本是由居住在灰谷西北部黑暗深渊周围的娜迦持有并改造的。娜迦女祭司和神谕者用她们自己污秽的魔法使这些宝石饱和，将其变成了黑暗仪式的工具。",al={"谁制造了被污染的科尔宝石","被污染的科尔宝石出处","科尔宝石来源"}},["1d7ce70e"]={q="为什么会有人想要被污染的科尔宝石？",a="圣骑士们在铁匠乔丹·斯迪威尔的要求下寻找这种宝石，以帮助锻造一把正义的武器，尽管它必须首先由桑德里斯·风织者净化掉其中的邪恶魔法。它储存魔法能量的能力使其在适当净化后对于仪式制作非常有价值。",al={"为什么要获取被污染的科尔宝石","谁需要被污染的科尔宝石","为什么需要科尔宝石"}}},fp="17,288,24.601.0,25.263.1,27.238.0,35.236.0,29.280.0,42.153.0"}
P.entries["item:cougar-claws"] = {n="平原狮的爪子",s="平原狮的爪子是从游荡在莫高雷中部平原的平原狮身上采集的。它们是牛头人仪式工艺中的重要材料，体现了野生掠食者未经驯服的平衡与自然凶猛。",h="平原狮的爪子是从游荡在莫高雷中部平原的平原狮身上采集的。它们是牛头人仪式工艺中的重要材料，体现了野生掠食者未经驯服的平衡与自然凶猛。",kw={"净化图腾","平原狮的爪子","平原狮","莫高雷","穆尔·雷角","雷角图腾"},ang={["class:Shaman"]="萨满们认识到，当地掠食者的精髓与平原之灵有着紧密的联系，这使它们成为净化结界和清洁图腾的重要媒介。",["race:Tauren"]="收集这些爪子教会了年轻的牛头人，狩猎植根于平衡和精神需求，这与地精企业带来的鲁莽污染形成了鲜明的对比。"},sec={{t="自然平衡的容器",b="平原狮是莫高雷广袤草原上的顶级猎手之一，以本能的优雅跟踪猎物。在牛头人的传统中，获取这种掠食者的爪子并非随意的杀戮或狩猎战利品，而是一种驾驭野兽自然精神的方式。当地精的行动开始玷污平原上的祖传水源时，穆尔·雷角便号召年轻的猎手们去收集这些爪子，以及草原捕食者的爪子。牛头人相信，原生野兽纯净、未受污染的掠食本能可以被编织进仪式图腾中，用以清除雷角水井中被毒化的非自然毒素和邪恶法术。"}},faq={{q="平原狮的爪子有什么用？",a="穆尔·雷角将它们与草原捕食者的爪子一起使用，来制作雷角之井净化图腾。牛头人将原生掠食者的纯净精神编织进仪式物品中，以净化被地精工业活动所毒化的水井。",al={"平原狮的爪子用途","为什么要获取平原狮的爪子","平原狮的爪子目的"}},{q="平原狮的爪子从哪里来？",a="它们取自潜伏在莫高雷草海平原上的平原狮，主要分布在血蹄村的东部和西部。",al={"哪里可以获得平原狮的爪子","平原狮的爪子来源","什么生物掉落平原狮的爪子"}},{q="为什么穆尔·雷角需要掠食者的爪子来净化水井？",a="牛头人的萨满和德鲁伊传统尊崇野兽狩猎时的纯粹。与那些剥削和玷污大地地精不同，原生掠食者与土地完全保持平衡，这使得它们的精髓成为抵御人为腐化的理想选择。",al={"为什么需要掠食者的爪子","穆尔需要爪子的原因","图腾与掠食者的爪子"}},{q="平原狮的爪子还有其他用途吗？",a="除了制作雷角之井的仪式图腾外，它们没有其他特殊用途，通常被卖给当地商人。",al={"平原狮的爪子的其他用途","出售平原狮的爪子"}}},fx={ad1b83a1={q="什么是平原狮的爪子？",a="这些是从潜伏在莫高雷平原的平原狮爪子上取下的天然利爪。牛头人萨满并不将其视为仅仅是战利品，而是将其看作自然狩猎的象征，体现了潜行于荒野中的野兽那纯净且未受玷污的平衡。",al={"什么是平原狮的爪子","平原狮的爪子物品背景","这些爪子是什么"}}},fp="12,218,27.670.0,31.228.0,32.128.0,64.259.0,42.138.0"}
P.entries["item:courser-eye"] = {n="巨角鹿的眼球",s="巨角鹿的眼球是从漫步在石爪山脉高地的长角巨角鹿身上采集的生物试剂。玛拉卡金的巫医金吉尔需要大量的眼球，来准备一种他戏称为丛林魔法的药剂。",h="巨角鹿的眼球是从漫步在石爪山脉高地的长角巨角鹿身上采集的生物试剂。玛拉卡金的巫医金吉尔需要大量的眼球，来准备一种他戏称为丛林魔法的药剂。",kw={"长角巨角鹿","巨角鹿的眼球","丛林魔法","巨型巨角鹿","巫医金吉尔","玛拉卡金","石爪山脉"},ang={["race:NightElf"]="屠杀石爪山脉的巨角鹿来供应一名巫医对被俘暗夜精灵进行的残忍实验，这触犯了他们对自然的崇敬。",["race:Troll"]="巫医金吉尔对动物成分的粗糙应用，反映了巨魔炼金术和巫术中用于对付部落敌人的黑暗、务实的一面。"},sec={{t="巨魔的药剂",b="在玛拉卡金这个偏远的哨所，巫医金吉尔配置了各种部落混合剂，用来对付该地区争夺领土的暗夜精灵。虽然鹿眼在巫毒和民间炼金术中并非罕见成分，但金吉尔一次性要求提供三十个巨角鹿的眼球——这远远超出了普通施法所需。这种药剂混合了精灵龙鳞、树液和猫科动物的胡须，作为一种致命药水的基底，专门用于那些被关在他巢穴后方笼子里的暗夜精灵囚犯。"}},faq={{q="哪里可以找到巨角鹿的眼球？",a="它们是从石爪山脉高海拔地区，特别是暗色湖和石爪峰附近，原生于此的各种巨角鹿（包括长角巨角鹿和巨型巨角鹿）身上采集到的。",al={"巨角鹿的眼球位置","哪里可以获得巨角鹿的眼球","如何获取巨角鹿的眼球"}},{q="为什么巫医金吉尔需要这么多眼球？",a="金吉尔声称在配置合适的药水时，眼球永远都不嫌多。他将这些眼球与当地动物的身体部位混合在一起，制作成他戏称为丛林魔法的药剂。",al={"为什么需要30个眼球","为什么金吉尔需要眼球","金吉尔用巨角鹿的眼球做什么"}},{q="当金吉尔完成他的丛林魔法药水后会发生什么？",a="金吉尔计划将他的丛林魔法药剂用在他洞穴中被关押的暗夜精灵囚犯身上。当他的实验进行时，他们的命运就会揭晓。",al={"金吉尔的丛林魔法结果","玛拉卡金的囚犯发生了什么"}}},fx={["5cdf5ac9"]={q="什么是巨角鹿的眼球？",a="巨角鹿的眼球是一种从漫步在石爪山脉的本地鹿类生物——巨角鹿身上采集的炼金试剂。对于大多数林地居民来说，它们仅仅是当地野生动物的一部分，但在狡猾的从业者手中，这些众多的眼球可以作为强力药剂的原材料。",al={"什么是巨角鹿的眼球","巨角鹿的眼球物品","什么是巨角鹿的眼球（复数）"}},a4aa468a={q="巨角鹿的眼球是从哪里来的？",a="这些眼球直接从漫步在石爪山脉（特别是在暗色湖周围和石爪峰附近）的长角巨角鹿和大型巨角鹿身上采集。它们是取自山中野生动物的天然部分，而不是制作或附魔的工艺品。",al={"巨角鹿的眼球来源","谁制作了巨角鹿的眼球","巨角鹿的眼球出处"}}},fp="11,250,20.483.1,29.207.0,48.173.1,60.153.1"}
P.entries["item:covert-ops-pack"] = {n="隐秘行动工具包",s="隐秘行动工具包是一套专为联盟在石爪山脉的间谍活动而组装的专业爆破装备和行动蓝图。该背包旨在瓦解荆棘谷地精在狂风峭壁的贪婪行径，它使特工能够实施协同破坏，同时获取高价值的技术情报。",h="隐秘行动工具包是一套专为联盟在石爪山脉的间谍活动而组装的专业爆破装备和行动蓝图。该背包旨在瓦解荆棘谷地精在狂风峭壁的贪婪行径，它使特工能够实施协同破坏，同时获取高价值的技术情报。",kw={"隐秘行动工具包","峭壁湖","ng-5炸药","阿尔法计划","贝塔计划","荆棘谷地精","狂风峭壁"},ang={["faction:Alliance"]="用该背包策划的秘密行动直接支持了哨兵在石爪山脉反抗商业掠夺的斗争。",["profession:Engineering"]="该背包代表了针对地精工业的精湛侏儒智慧，利用定制的NG-5炸药揭开了荆棘谷地精机械背后的秘密。"},sec={{t="精心设计的破坏行动",b="隐秘行动工具包是为深入荆棘谷地精领地的秘密打击而发放的，它将强大的破坏力与战术精确性结合在了一起。包内装有与遥控引爆器配套的彩色NG-5炸药，以及标有“阿尔法计划”和“贝塔计划”的详细说明。该策略旨在关键基础设施节点——即峭壁湖伐木场和东部矿洞——制造高强度的干扰。当地精们忙于扑灭大火和评估机械故障时，渗透者便可趁乱溜过，窃取关键文件和蓝图。"},{t="利益的交汇",b="该背包中的物品对联盟在石爪山脉的行动具有双重目的。对于暗夜精灵哨兵来说，爆炸和盗窃破坏了对神圣山坡无情的砍伐和挖掘。对于联盟修补匠来说，主要的收获在于文件本身。回收荆棘谷地精的工程蓝图可以为地精重型机械提供难得的见解，揭示可利用的机械弱点，并使联盟工程师能够将这些工业创新融入他们自己的设计中。"}},faq={{q="隐秘行动工具包里有什么？",a="该背包包含两对彩色爆破装药：红色和蓝色的NG-5炸药，以及与之配套的遥控引爆器。它还装有详细说明“阿尔法计划”和“贝塔计划”的书面任务简报。",al={"隐秘行动工具包内容","背包里装了什么","隐秘行动工具包中的物品"}},{q="这些炸药的战术目的是什么？",a="NG-5炸药被放置在荆棘谷地精的工作点，旨在制造巨大的、剧烈的干扰。它们的目的并不是为了造成破坏本身，而是为了引开守卫，以便特工能够潜入伐木场和矿洞而不被察觉。",al={"为什么要使用炸弹","ng-5炸药的用途","阿尔法和贝塔爆破"}},{q="这次行动的目标是什么情报？",a="该任务的目标是峭壁湖以南伐木场的荆棘谷地精工程蓝图，随后是存放在狂风峭壁东端狂风矿洞内的行政信函。",al={"我们窃取什么","背包任务目标","隐秘行动目标"}},{q="谁能从使用此背包回收的材料中受益？",a="守卫石爪山脉的暗夜精灵哨兵和联盟工程师都将受益。哨兵看到了砍伐工作的瘫痪，而联盟工匠则通过研究缴获的蓝图来找出荆棘谷地精伐木机的缺陷，并为他们自己的技术汲取灵感。",al={"谁想要荆棘谷地精的蓝图","背包是为谁准备的","哨兵隐秘行动"}}},fx={["8d787d42"]={q="什么是隐秘行动工具包？",a="隐秘行动工具包是为在狂风峭壁的渗透行动而准备的专业破坏工具包。它包含彩色编码的NG-5爆炸物、配套的远程引爆器和详细的任务计划，旨在制造定时的干扰，以便在荆棘谷地精眼皮底下窃取重要的文件。",al={"什么是隐秘行动工具包","隐秘行动工具包信息","隐秘行动套件"}},["23fc442d"]={q="隐秘行动工具包是从哪里来的，它是谁制造的？",a="该工具包由一名协助石爪山脉暗夜精灵哨兵的联盟技师组装。结合了精密工程与战术爆破，他们特意制作了不稳定的NG-5炸药和远程触发器，以协助针对荆棘谷地精设施的行动打击。",al={"谁制作了隐秘行动工具包","隐秘行动工具包来源","隐秘行动工具包创造者"}},ca775219={q="为什么需要隐秘行动工具包？",a="直接突袭荆棘谷地精的防御工事（如他们的伐木场和矿井）无异于自杀，或者会在获取重要情报之前惊动守卫。该工具包提供了在别处安放远程爆炸物并引发可控混乱的工具，从而将防守者引开，让你能溜进去找回他们的工程计划和通信文件。",al={"为什么要隐秘行动工具包","为什么需要隐秘行动工具包","隐秘行动工具包用途"}}},fp="15,339,18.584.0,25.515.0,35.202.0,47.250.0,45.191.0,58.280.0"}
P.entries["item:crate-of-crash-helmets"] = {n="一箱防撞头盔",s="一箱运往千针石林闪光平原的重型物资，里面装满了矮人的攻城坦克头盔。铜栓兄弟急需这些坚固的头盔，以保护测试车手免受实验性火箭车造成的脑震荡。",h="一箱运往千针石林闪光平原的重型物资，里面装满了矮人的攻城坦克头盔。铜栓兄弟急需这些坚固的头盔，以保护测试车手免受实验性火箭车造成的脑震荡。",kw={"一箱防撞头盔","沙漠赛道","火箭车","闪光平原","攻城坦克","千针石林","维兹尔·铜栓"},ang={["profession:Engineering"]="任何工程师都明白最大推进力和灾难性故障之间的微妙平衡——以及当安全功能成为事后补救措施时，重型护甲的绝对必要性。",["race:Gnome"]="对于沙漠赛道的侏儒们来说，当在盐碱滩上与地精竞争对手进行技术创新竞赛时，车手的脑震荡不过是经营成本的一部分。"},sec={{t="高速安全",b="在闪光平原那耀眼的白色荒原上，侏儒工程师们正在测试机械推进的极限。但对于试驾员来说不幸的是，铜栓兄弟设计的实验性火箭车速度太快，超出了转向系统的可控范围。由于车手们经常遭遇剧烈撞击和头部创伤，普通的皮帽已经无法满足防护需求。为了防止他们麾下这些甘冒风险的勇士们彻底消失，重型矮人攻城坦克头盔被打包并跨海运来，以确保车手们保持清醒——并活下去。"}},faq={{q="一箱防撞头盔里装的是什么？",a="这个箱子里装着从矮人军事储备中获取的重型攻城坦克头盔。它们旨在抵御震荡性爆炸和剧烈的车辆撞击，为高速试验提供了最厚实的头部防护。",al={"箱内物品","这是什么头盔","防撞头盔类型"}},{q="谁需要这些头盔？",a="它们被送往位于闪光平原沙漠赛道的维兹尔·铜栓和他兄弟那里。他们鲁莽的车辆设计一次又一次地将试驾员撞晕，因此亟需专业的头部防护装备。",al={"谁获得头盔","箱子是给谁的","头盔目的地"}},{q="为什么铜栓兄弟总是频繁发生撞车事故？",a="侏儒的车辆设计将原始速度和对技术极限的追求置于稳定的操控性之上。这对兄弟制造了一辆速度极快的火箭车，但在盐碱滩上，其极高的速度让碰撞几乎无法避免。",al={"为什么撞车","火箭车问题","侏儒竞速撞车"}},{q="头盔被运往哪里？",a="这批货物必须运送到闪光平原，那是位于卡利姆多千针石林东南方的一片广袤盐碱滩。",al={"运送地点","维兹尔在哪里","这些东西运往何处"}}},fx={["94078cd5"]={q="一箱防撞头盔是从哪里来的，它是谁制造的？",a="该箱子由丹莫罗的矮人工程师飞行员比罗·长须装箱并提供。长须收集了一批坚固的矮人攻城坦克头盔，以帮助他的老朋友——黄铜螺栓兄弟，他们急需为在闪光平原测试的飞行员提供头部保护。",al={"谁制作了一箱防撞头盔","一箱防撞头盔来源","防撞头盔出处"}}},fp="22,262,21.584.0,42.227.0,24.218.0,49.232.0,38.147.0"}
P.entries["item:crate-of-horseshoes"] = {n="一箱马掌",s="“一箱马掌”是一个沉重的包裹，里面装有五十个在艾尔文森林打造的铁制马掌。这批货物目的地是湖畔镇，代表了闪金镇铁匠铺与赤脊山苦战中的定居者之间至关重要的贸易纽带。",h="“一箱马掌”是一个沉重的包裹，里面装有五十个在艾尔文森林打造的铁制马掌。这批货物目的地是湖畔镇，代表了闪金镇铁匠铺与赤脊山苦战中的定居者之间至关重要的贸易纽带。",kw={"一箱马掌","艾尔文森林","闪金镇","湖畔镇","赤脊山","铁匠阿古斯","弗纳·奥斯古"},ang={["faction:Alliance"]="在艾尔文和赤脊山之间运送货物的信使维持着王国脆弱的贸易命脉，即使暴风城迟迟不愿增援，也能确保边远驻军获得装备。",["profession:Blacksmithing"]="这次运送展示了王国边境道路沿线对大宗铁匠制品的需求，在那里，像湖畔镇这样的城镇完全依赖闪金镇的铁砧来维持他们的役用动物。"},sec={{t="送往湖畔镇的货物",b="这个沉重的板条箱由闪金镇的铁匠阿古斯打包并钉死，里面装着五十个由弗纳·奥斯古订购的新鲜打造的马掌。湖畔镇的当地工业在周围豺狼人和兽人的持续压力下艰难维持，这使得像弗纳这样的工匠只能依赖艾尔文森林来获取必需的金属制品。虽然这箱货物满足了弗纳对装备的迫切需求，但阿古斯还是附上了一份严厉的账单，确保这位赤脊山的工匠记得，即使在边境生存也是要付出高昂代价的。"}},faq={{q="“一箱马掌”里面有什么？",a="这个板条箱里装有五十个由闪金镇的铁匠阿古斯打造的铁制马掌，并附有一份要求买家付款的账单。",al={"箱中物品","箱子里有什么","马掌箱内容物"}},{q="是谁订购了这箱货物？",a="弗纳·奥斯古，一名驻扎在赤脊山湖畔镇的商人和工匠，他订购了这些马掌以维持他的工作和当地役用动物的运转。",al={"谁想要这些马掌","弗纳的马掌","货物接收者"}},{q="是谁打造了这些马掌？",a="铁匠阿古斯，艾尔文森林闪金镇的驻地铁匠，他打造了这些马掌并将其装箱等待运输。",al={"谁制作了这些马掌","闪金镇的铁匠","铁匠阿古斯"}},{q="为什么弗纳需要来自艾尔文的马掌？",a="湖畔镇正遭受敌对的黑石兽人和豺狼人的围困，使得这个边境定居点陷入孤立，且缺乏原材料和贸易物资。当地工人们必须从像闪金镇这样更安全的定居点进口基本物资。",al={"为什么赤脊山需要马掌","为什么进口马掌","湖畔镇的补给问题"}}},fx={["50a21bee"]={q="什么是一箱马掌？",a="一箱马掌是一个沉重的木制运输箱，里面装着五十个新锻造的马掌，并附有一张发货单。铁匠阿古斯在闪金镇准备了这批货物，以完成弗纳·奥斯古下的订单，他急需新鲜的铁器来给附近的湖畔镇的驮兽和坐骑钉马掌。",al={"什么是一箱马掌","一箱马掌背景","马掌的用途"}}},fp="19,57,23.433.0,39.122.0,23.179.0,29.124.0,44.219.0"}
P.entries["item:crate-of-inn-supplies"] = {n="一箱旅店补给品",s="一箱旅店补给品是一件从寒脊山谷打包好，运往卡拉诺斯雷酒酿制厂的包裹。由于山间小径被穴居怪占领，常规补给路线已被切断，导致旅店只能依靠过往的旅行者来运送货物。",h="一箱旅店补给品是一件从寒脊山谷打包好，运往卡拉诺斯雷酒酿制厂的包裹。由于山间小径被穴居怪占领，常规补给路线已被切断，导致旅店只能依靠过往的旅行者来运送货物。",kw={"安威玛尔","寒脊","箱子","霜锤","汉兹","卡拉诺斯","跳链","补给品","塔诺克","穴居怪"},ang={["race:Dwarf"]="运送这些补给品标志着年轻的矮人第一次在寒脊山谷之外执行任务，他们勇敢地穿过被穴居怪堵塞的小径，以帮助他们在卡拉诺斯的同胞。",["race:Gnome"]="对于新来的侏儒来说，运送汉兹·跳链的包裹是赢取丹莫罗旅店管理方当地矮人好感的一种实际方式。"},sec={{t="穿过穴居怪小径",b="通常情况下，货物会在安威玛尔安静的训练场和丹莫罗繁华的城镇之间顺畅流通。然而，最近穴居怪的入侵切断了寒脊山小径，在全副武装的探险者护卫清理道路之前，平民信使无法通行。这箱沉重的货物由汉兹·跳链打包，里面装满了塔诺克·霜锤在卡拉诺斯急切等待的旅店必需品，以应对当前的补给中断。"}},faq={{q="箱子里装的是什么？",a="箱子里装的是从寒脊山谷运出的普通旅店补给品，旨在让卡拉诺斯的旅店储备充足，为寻求温暖的旅客和当地人提供服务。",al={"箱子内容物","旅店补给品内容","盒子里有什么"}},{q="谁把箱子送往卡拉诺斯？",a="驻扎在安威玛尔附近的汉兹·跳链负责打包，并请求离开寒脊山谷的冒险者将其带过山间小径。",al={"谁提供箱子","汉兹·跳链","寄件人"}},{q="为什么普通的信使无法递送？",a="穴居怪已经占领了寒脊山小径，如果没有全副武装的探险者护卫，对于普通信使来说太危险了。有能力杀出一条血路的冒险者是旅店目前接收货物的唯一希望。",al={"为什么汉兹无法递送","小径被封锁","为什么要使用冒险者"}},{q="谁接收这些补给品？",a="卡拉诺斯雷酒酿制厂的旅店老板助手，塔诺克·霜锤，负责接收包裹。",al={"谁拿到箱子","塔诺克·霜锤","卡拉诺斯旅店老板"}}},fx={bc2f2ebd={q="什么是一箱旅店补给品？",a="这是一个由汉兹·跳链在寒脊山小径打包的货物包裹，旨在送往卡拉诺斯的雷酒酿制厂和旅店。由于离开寒脊山谷的通道被穴居人堵塞，这批货物一直被耽搁，直到有能力强壮的旅行者能将其运送过去。",al={"什么是一箱旅店补给品","一箱旅店补给品任务物品","这个箱子是什么"}},e676223e={q="为什么卡拉诺斯需要一箱旅店补给品？",a="卡拉诺斯旅店的助理塔诺克·霜锤一直在等待来自寒脊山谷的新鲜库存，但由于穴居人起义，消息一直很少。由于常规的信使线路被切断，旅店需要将这些补给品通过通道运进来，以保持旅行者和当地人在火炉旁的供应。",al={"塔诺克为什么要这个箱子","为什么需要旅店补给品","一箱旅店补给品用途"}}},fp="21,261,22.431.0,25.157.0,32.156.0,43.232.0,26.118.0"}
P.entries["item:crate-of-lightforge-ingots"] = {n="一箱光铸铁锭",s="一箱光铸铁锭中装着珍稀的圣化金属，这些金属是为打造能击败死灵法师摩尔班·菲尔的武器而收集的。它被安全地封装以便运输，目的地是暴风城Dwarven District的铁砧。",h="一箱光铸铁锭中装着珍稀的圣化金属，这些金属是为打造能击败死灵法师摩尔班·菲尔的武器而收集的。它被安全地封装以便运输，目的地是暴风城Dwarven District的铁砧。",kw={"箱子","dwarven district","grimand elmore","铁锭","铁","光铸","摩尔班·菲尔","暴风城"},ang={["class:Paladin"]="这些铁锭对圣光有着独特的感应力，用它们锻造的武器是死灵法师及其亡灵爪牙的天然克星。",["profession:Blacksmithing"]="处理光铸铁是一门稀有的艺术；即使是像Grimand Elmore这样的资深武器匠，也可能多年都无法接触到这种具有灵性的神圣金属。"},sec={{t="神圣的补给",b="光铸铁是一种极其稀有的材料，天生适合引导圣光之力来对抗黑暗生物。这些铁锭被安全地装在这只箱子里，代表着暮色森林在对抗死灵法师摩尔班·菲尔的艰苦斗争中的希望。摩尔班·菲尔的暗影护盾让普通的钢铁毫无作用。普通的铁匠无法轻易处理这种金属；它需要一位了解其特性并尊重其神圣本质的工匠。"},{t="暴风城的武器匠",b="这个箱子是交给Grimand Elmore的，他是一位在暴风城Dwarven District从事贸易的资深矮人武器匠。由于多年未曾处理过光铸铁，Grimand同意将这种金属锻造成一把圣洁的武器——一把拥有足以粉碎摩尔班·菲尔防御并将其击倒之力量的武器。"}},faq={{q="这个箱子里装着什么？",a="箱子里装的是光铸铁锭，这是一种特殊的圣化金属，收集它是为了打造一把专门用来穿透死灵法师摩尔班·菲尔魔法防御的武器。",al={"箱内物品","什么是光铸铁","盒子里有什么"}},{q="谁应该收到这个箱子？",a="这个箱子必须送到Grimand Elmore手中，他是一位经验丰富的矮人铁匠，位于暴风城Dwarven District的铁砧旁。",al={"我该把箱子交给谁","箱子收件人","箱子要去哪里"}},{q="为什么需要光铸铁？",a="死灵法师摩尔班·菲尔用邪恶的暗影魔法保护自己，这种魔法能排斥常规刀剑。光铸铁拥有神圣属性，可以穿透黑暗巫术。",al={"为什么需要光铸铁","为什么不用普通钢铁","摩尔班·菲尔的弱点"}},{q="谁制作了这个箱子？",a="戈罗林·钢眉将你找回的光铸铁打包进了箱子，以便你将其送到暴风城的武器大师Grimand Elmore那里。",al={"谁打包了铁锭","谁给了这个箱子"}}},fp="26,152,17.254.0,28.270.1,26.130.0,38.101.0,30.114.0,22.117.0"}
P.entries["item:crate-with-holes"] = {n="开孔的箱子",s="这是一个便携式运输容器，由棘齿城的加基森企业家麦伯克·米希瑞克斯提供。箱子上钻有通风孔，可以安全地容纳一只经过训练的地鼠，用于在剃刀沼泽的野猪人巢穴中寻找地下的烹饪美食。",h="这是一个便携式运输容器，由棘齿城的加基森企业家麦伯克·米希瑞克斯提供。箱子上钻有通风孔，可以安全地容纳一只经过训练的地鼠，用于在剃刀沼泽的野猪人巢穴中寻找地下的烹饪美食。",kw={"蓝叶薯","开孔的箱子","麦伯克·米希瑞克斯","棘齿城","剃刀沼泽","地鼠"},sec={{t="箱子里的嗅探者",b="为了从剃刀沼泽多刺的深处获得稀有的蓝叶薯，地精商人麦伯克·米希瑞克斯依靠经过训练的地鼠，而不是盲目挖掘。由于地鼠无法简单地跟随冒险者穿过贫瘠之地的尘土小径，麦伯克将每只小动物装进一个通风良好的木箱里。一旦被带入野猪人巢穴潮湿且根系缠绕的走廊，箱子就会被打开，让里面的野兽跟随其敏锐的嗅觉寻找埋藏的块茎。"}},faq={{q="开孔的箱子里有什么？",a="箱子里装着一只由麦伯克·米希瑞克斯训练过的地鼠。木板上钻的孔可以让这种生物在穿越贫瘠之地时呼吸。",al={"盒子里有什么","箱子内容物","里面是什么"}},{q="我在哪里可以得到开孔的箱子？",a="你可以直接从位于贫瘠之地东海岸的港口城市棘齿城，麦伯克·米希瑞克斯旁边的堆叠物中拿走一个箱子。",al={"箱子位置","在哪里找到开孔的箱子","麦伯克的箱子"}},{q="在剃刀沼泽里箱子怎么用？",a="在剃刀沼泽内打开箱子会放出地鼠。当地鼠使用地鼠指挥棒引导时，它会利用敏锐的鼻子定位埋在土下的蓝叶薯。",al={"如何使用开孔的箱子","使用箱子","召唤地鼠"}},{q="为什么没有地鼠就很难找到蓝叶薯？",a="蓝叶薯生长在剃刀沼泽地下的根系网络中。普通视力无法发现它们，但地鼠可以在五十步外闻到它们的气味。",al={"为什么需要地鼠","寻找块茎","块茎位置"}}},fx={["39b6cc8f"]={q="开孔的箱子是从哪里来的，它是谁制造的？",a="该箱子由在贫瘠之地棘齿城港口城镇经营的进取心强的地精商人麦伯克·米希瑞克斯提供。为了收获隐藏在剃刀沼泽野猪人据点内的珍贵根茎，麦伯克想出了一种将受过训练的嗅鼻地鼠安全运送到现场的方法，在标准的运输箱上打孔，以便他珍贵的小动物在运输过程中呼吸。",al={"开孔的箱子出处","谁制作了开孔的箱子","开孔的箱子来源"}},["08415caf"]={q="为什么麦伯克·米希瑞克斯想要取回开孔的箱子？",a="麦伯克希望取回箱子，同时还有他的指挥棒和收获的蓝叶块茎，因为受过训练的嗅鼻地鼠是他负担不起损失的投资。块茎是世界上极为罕见的美味，没有他受过训练的地鼠和专门的运输箱，在剃刀沼泽深处找到它们几乎是不可能的。",al={"麦伯克为什么要这个箱子","为什么要这个开孔的箱子","开孔的箱子用途"}}},fp="16,265,18.509.0,36.170.0,36.153.0,46.216.0,59.181.0"}
P.entries["item:crawler-leg"] = {n="蟹腿",s="蟹腿是从徘徊在黑海岸迷雾笼罩的海岸线上的各种螃蟹身上获取的肢体。虽然对于大多数旅行者来说它们毫无价值，但这些坚硬的甲壳状附肢却出人意料地适合用于机械拼凑。",h="蟹腿是从徘徊在黑海岸迷雾笼罩的海岸线上的各种螃蟹身上获取的肢体。虽然对于大多数旅行者来说它们毫无价值，但这些坚硬的甲壳状附肢却出人意料地适合用于机械拼凑。",kw={"奥伯丁","蜂鸣盒827","蟹腿","黑海岸","礁行蟹","潮行蟹","维兹班恩·曲针"},ang={["profession:Engineering"]="维兹班恩·曲针决定使用螃蟹附肢作为临时机械杠杆，这反映了典型的侏儒现场即兴创作风格，避开了标准金属连杆，转而使用唾手可得的当地资源。",["race:Gnome"]="恐怕只有侏儒才会看到满是好斗甲壳类动物的海滩，然后断定它们被砍下的腿是修复精密的远程电信网络的理想替换零件。"},sec={{t="海岸上的侏儒巧思",b="黑海岸的螃蟹——从侏儒潮行蟹到更大的礁行蟹——以其结实且富有韧性的甲壳而闻名。虽然暗夜精灵哨兵对这些沿海害虫丢弃的肢体不屑一顾，但古怪的侏儒工程师维兹班恩·曲针却发现了它们的意外用途。维兹班恩在奥伯丁进行作业，他设计的原型远程通信设备（被称为蜂鸣盒）正是依靠临时搜集的当地组件来运行的。蟹腿的分节关节和耐用的甲壳提供了修复“蜂鸣盒827”所需的精确机械摩擦力和杠杆作用，该设备位于镇子南部的海岸线上。"}},faq={{q="蟹腿有什么用？",a="收集蟹腿是为了修复“蜂鸣盒827”，这是一个实验性通信站，由侏儒发明家维兹班恩·曲针放置在奥伯丁以南的黑海岸沿岸。",al={"蟹腿用途","为什么保留蟹腿","蜂鸣盒蟹腿"}},{q="蟹腿来自哪里？",a="它们可以从黑海岸海滩上的各种螃蟹身上搜集到，包括侏儒潮行蟹、幼年礁行蟹、甲壳潮行蟹和礁行蟹。",al={"蟹腿来源","哪些螃蟹掉落蟹腿","哪里寻找蟹腿"}},{q="为什么机械蜂鸣盒需要蟹腿？",a="维兹班恩·曲针特意将他的机器设计为利用附近的野生生物部件进行持续的现场维护。蟹腿的僵硬关节和甲壳分段可以直接插入蜂鸣盒的研磨齿轮中，以修复其内部机械结构。",al={"为什么机器要用螃蟹","蜂鸣盒蟹腿背景故事","蟹腿如何修理蜂鸣盒"}}},fx={bab31e79={q="什么是蟹腿？",a="蟹腿是从沿着黑海岸雾气笼罩的海岸爬行的各种爬行类生物身上采集的断肢。凭借其坚硬的甲壳和耐用的关节，这些腿非常坚韧，适合进行粗糙的临时机械修理。",al={"什么是蟹腿","蟹腿物品","关于蟹腿"}}},fp="11,231,30.641.0,31.191.0,32.179.0,45.270.0"}
P.entries["item:creeper-ichor"] = {n="食苔蛛的毒液",s="食苔蛛的毒液是一种稀有且剧毒的液体，采集自潜伏在希尔斯布莱德丘陵森林各处的食苔蛛。塔伦米尔的皇家药剂师协会将其视为一种强效的生物制剂，用于配制针对生者的各种新型瘟疫。",h="食苔蛛的毒液是一种稀有且剧毒的液体，采集自潜伏在希尔斯布莱德丘陵森林各处的食苔蛛。塔伦米尔的皇家药剂师协会将其视为一种强效的生物制剂，用于配制针对生者的各种新型瘟疫。",kw={"药剂师林度恩","食苔蛛的毒液","克里普瑟斯","受难药剂","希尔斯布莱德丘陵","食苔蛛","塔伦米尔"},ang={["race:Undead"]="对于被遗忘者的忠诚者来说，获取食苔蛛的毒液这类致命成分，将直接推进皇家药剂师协会将生者从洛丹伦清除出去的行动。"},sec={{t="希尔斯布莱德的药剂师研究",b="在塔伦米尔，药剂师林度恩正在进行实验，试图制造致命的新型毒素，以根除周围的人类居民。由于厌恶丘陵地区清新的空气和充满活力的生命，林度恩一直在寻找当地野生动物体内天然的毒素和生物催化剂。森林中巨大蛛形纲生物的毒液——尤其是成年食苔蛛体内那种难以捕捉的体液——是他配制受难药剂的理想基底。将这种体液与灰熊舌等其他试剂混合，能帮助被遗忘者完善他们致命的炼金术工艺。"}},faq={{q="什么生物会掉落食苔蛛的毒液？",a="这种体液是从栖息在希尔斯布莱德丘陵的食苔蛛身上采集的，包括巨型食苔蛛、森林食苔蛛、年长的食苔蛛，以及著名的蛛形纲生物克里普瑟斯。",al={"哪里可以获得食苔蛛的毒液","什么生物掉落食苔蛛的毒液","食苔蛛的毒液相关怪物"}},{q="为什么药剂师林度恩需要这种体液？",a="药剂师林度恩在持续的炼金研究中将食苔蛛的毒液用作关键的杀伤剂，用来酿制受难药剂，旨在用瘟疫消灭希尔斯布莱德的人类生者。",al={"为什么林度恩想要毒液","受难药剂的用途","食苔蛛的毒液有什么用"}},{q="为什么食苔蛛的毒液如此难寻？",a="虽然食苔蛛在塔伦米尔周围的森林中很常见，但含有这种特定剧毒体液的样本并不多见，猎人们通常需要杀死许多只蛛形纲生物才能获得一份可用的样本。",al={"为什么稀有","食苔蛛的毒液掉落率"}}},fx={f45507cb={q="什么是食苔蛛的毒液？",a="食苔蛛的毒液是一种极其罕见的体液，是从出没于希尔斯布莱德丘陵的苔藓爬行者身上采集的。这些巨大的蜘蛛在塔伦米尔周围的森林和田野中潜行，但只有极少数能产生足够强效和纯净的毒液，可作为可用的炼金试剂。对于皇家药剂师协会来说，这种有害的精华是一种极佳的致命药剂，因其天然的毒性和不稳定的酿造潜力而备受珍视。",al={"什么是食苔蛛的毒液","食苔蛛的毒液背景","苔藓爬行者毒液"}},["3620ba85"]={q="食苔蛛的毒液是从哪里来的？",a="食苔蛛的毒液不是人工制造的，而是直接从希尔斯布莱德丘陵的原生各种苔藓爬行者身上采集的，包括巨型、森林和长者爬行者，以及像克里普瑟斯这样的臭名昭著的野兽。这是一种在这些巨大的掠食性蜘蛛体内形成的天然生物液体，虽然找到一个含有可用、浓缩量的样本需要追踪并在荒野中杀死数十只这种生物。",al={"食苔蛛的毒液来源","食苔蛛的毒液出处","谁制作了食苔蛛的毒液"}}},fp="13,270,32.579.0,35.188.0,42.195.0,42.220.0"}
P.entries["item:crocolisk-skin-classic"] = {n="Crocolisk Skin (Classic)",s="鳄鱼皮取自栖息在洛克莫丹洛克湖岛屿和水域中的鳄鱼坚韧的皮。这种皮因其耐用性而受到商人和制皮师的珍视，尽管获取它们需要冒很大的风险，但仍能卖出不错的价格。",h="鳄鱼皮取自栖息在洛克莫丹洛克湖岛屿和水域中的鳄鱼坚韧的皮。这种皮因其耐用性而受到商人和制皮师的珍视，尽管获取它们需要冒很大的风险，但仍能卖出不错的价格。",kw={"鳄鱼狩猎","鳄鱼皮","旅行者营地","洛克湖鳄鱼","洛克莫丹","马雷克·铁心","洛克湖"},ang={["class:Hunter"]="旅行者营地尊重任何愿意涉水前往岛屿，并与拼命挣扎的鳄鱼搏斗以获取其皮毛的追踪者。",["race:Dwarf"]="洛克莫丹著名的鳄鱼是登山者和营地护林人公认的勇气试炼。"},sec={{t="危险的贸易",b="洛克湖冰冷的水域中挤满了极具攻击性的鳄鱼，它们在湖中的岛屿和岸边筑巢。猎杀它们并非易事，因为这些凶猛的野兽拥有锋利的牙齿和厚实、坚韧的鳞片，足以让粗心大意的刀刃偏转。尽管危险重重，但在旅行者营地活动的猎人还是经常猎杀这些生物。裁缝、制皮师和远方的商人们不断寻找这种皮，用以制作耐用的服装和防护盔甲，这使得一捆未受损的兽皮成为该地区有价值的贸易商品。"}},faq={{q="鳄鱼皮是从哪里来的？",a="它们是从栖息在洛克莫丹洛克湖的水域和岛屿中的洛克湖鳄鱼和大型洛克湖鳄鱼身上采集的。",al={"鳄鱼皮获取途径","洛克湖鳄鱼皮来源","谁掉落鳄鱼皮"}},{q="谁在洛克莫丹购买或交易这些兽皮？",a="马雷克·铁心，一位驻扎在旅行者营地的经验丰富的矮人猎人，他负责收集这些兽皮以及鳄鱼肉，并将它们出售给来访的商人和工匠。",al={"谁需要鳄鱼皮","旅行者营地鳄鱼皮","马雷克·铁心兽皮"}},{q="为什么这些兽皮有需求？",a="商人们看重这种坚韧、多鳞的兽皮，用其制作结实的衣服和盔甲。因为这些野兽凶猛且难以猎杀，优质的兽皮能带来可靠的收入。",al={"鳄鱼皮的用途","鳄鱼皮革用途","为什么要猎杀鳄鱼"}},{q="在洛克湖猎杀鳄鱼被认为是危险的吗？",a="是的。这些鳄鱼以极具攻击性著称，拥有强大的颌骨和锯齿状的牙齿，足以撕断肢体。像马雷克·铁心这样的当地猎人经常在试图制服猎物时，谈论他们九死一生的经历。",al={"洛克湖鳄鱼危险吗","鳄鱼狩猎危险性"}}},fx={c6e655b9={q="什么是鳄鱼皮？",a="鳄鱼皮是从栖息在洛克莫丹水域和岛屿上的鳄鱼身上采集的坚韧带鳞的兽皮。因其耐用性和独特的纹理而备受珍视，它是制皮师和裁缝想要制作坚固的服装、防护装备或特种护甲时的宝贵原材料。",al={"什么是鳄鱼皮","鳄鱼皮（材质）","什么是鳄鱼皮（复数）"}}},fp="24,267,17.570.0,35.131.0,45.165.0,30.172.0,55.235.0"}
P.entries["item:crocolisk-tear-classic"] = {n="Crocolisk Tear (Classic)",s="鳄鱼的眼泪是一种奇特的炼金试剂，采集自栖息在洛克莫丹水域中的鳄鱼。总工程师亨德维尔需要它来合成一种能够拆除黑铁矮人炸药的中和混合物。",h="鳄鱼的眼泪是一种奇特的炼金试剂，采集自栖息在洛克莫丹水域中的鳄鱼。总工程师亨德维尔需要它来合成一种能够拆除黑铁矮人炸药的中和混合物。",kw={"鳄鱼的眼泪","黑铁矮人","亨德维尔","洛克莫丹","试剂","巨石水坝","洛克湖"},ang={["profession:Engineering"]="像总工程师亨德维尔这样的矮人工程师经常使用非常规的炼金化合物来中和常规工具无法解决的高级炸药。"},sec={{t="奇特的成分",b="洛克鳄鱼是洛克莫丹温带水域中一种生命力顽强的爬行动物。虽然猎人通常看重它们的皮和肉，但总工程师亨德维尔却发现了它们分泌物的一种意想不到的用途。鳄鱼的眼泪与强效蜘蛛毒液和共鸣食人魔矿石相结合，能提供抵消威胁着巨石水坝的那些不稳定的黑铁矮人爆破炸药所需的特定化学性质。"}},faq={{q="鳄鱼的眼泪有什么用？",a="位于巨石水坝的总工程师亨德维尔需要鳄鱼的眼泪来配制一种化学混合物，用于拆除黑铁矮人破坏者安放的炸药。",al={"鳄鱼的眼泪用途","为什么我需要鳄鱼的眼泪","谁需要鳄鱼的眼泪"}},{q="在哪里可以收集到鳄鱼的眼泪？",a="它们可以从栖息在洛克莫丹洛克湖水域和浅滩的洛克鳄鱼和大型洛克鳄鱼身上采集到。",al={"鳄鱼的眼泪在哪里掉落","鳄鱼的眼泪位置","如何获得鳄鱼的眼泪"}},{q="还有哪些材料需要与眼泪结合？",a="亨德维尔将这种眼泪与从当地森林蜘蛛身上提取的潜伏者的毒液，以及从东北部山丘的食人魔那里获得的莫格罗什水晶配对，以完成拆弹剂的制作。",al={"亨德维尔的配料","拆弹材料","还需要什么材料和鳄鱼的眼泪配合"}}},fx={["27a8e6d1"]={q="什么是鳄鱼的眼泪？",a="鳄鱼的眼泪是一种稀有的炼金试剂，直接从栖息在洛克莫丹水域的鳄鱼身上采集而来。尽管有一句关于虚情假意的古老谚语，但这种生理分泌物却具有非同寻常的特性，使其在特殊药剂中非常有用，特别是当它与当地其他强效试剂混合使用以中和挥发性爆炸物时。",al={"鳄鱼的眼泪","什么是鳄鱼的眼泪","鳄鱼的眼泪物品"}}},fp="24,236,19.429.0,34.166.0,38.129.0,48.181.0"}
P.entries["item:crossroads-supply-crate"] = {n="Crossroads Supply Crate",s="Crossroads Supply Crate 包含着旨在供应贫瘠之地十字路口定居点的关键物资。在商队于干旱的道路上遭到劫掠后，这些被窃的货物散落在了当地剃刀鬃野猪人的营地中。",h="Crossroads Supply Crate 包含着旨在供应贫瘠之地十字路口定居点的关键物资。在商队于干旱的道路上遭到劫掠后，这些被窃的货物散落在了当地剃刀鬃野猪人的营地中。",kw={"十字路口","crossroads supply crate","野猪人","剃刀鬃","给十字路口的补给","贫瘠之地","索克"},ang={["faction:Horde"]="十字路口是连接杜隆塔尔、莫高雷和北方荒野的中心枢纽；确保其补给能够直接保障部落在卡利姆多各地的交通与后勤。"},sec={{t="劫掠的补给",b="十字路口定居点是部落在卡利姆多中部旅行的核心枢纽，但要在荒凉的贫瘠之地维持其补给是一项持续的挑战。穿过贫瘠之地的商队路线不断受到当地剃刀鬃野猪人的骚扰。在一次伏击中，一批运往该定居点的重要补给物资被洗劫一空。这些板条箱被拖进了附近野猪人营地多刺的灌木丛和泥土洞穴中。定居点的指挥官索克不得不招募过往的旅人，在哨所陷入食物、工具和必需品极度匮乏的困境之前，将它们找回来。"}},faq={{q="这些补给箱是什么？",a="它们是用于维持部落十字路口定居点的食物、工具和必需品补给。它们是在贫瘠之地的道路上被伏击的补给商队中被掠夺走的。",al={"十字路口补给","箱子里有什么","补给箱信息"}},{q="是谁偷走了补给箱？",a="剃刀鬃野猪人袭击了商队，并将板条箱拖回了附近带刺的营地中，以此来享用和囤积战利品。",al={"谁拿走了箱子","谁袭击了商队","野猪人窃贼"}},{q="谁在寻找这些箱子？",a="驻守在十字路口的兽人军官索克，请求收回被窃的箱子，以确保卫戍部队和当地居民能获得充足的补给。",al={"谁需要这些箱子","上交补给箱","索克的补给品"}},{q="这些箱子位于何处？",a="它们散落在贫瘠之地周边地区各处剃刀鬃野猪人的营地地面上。",al={"箱子位置","在哪里可以找到补给箱","十字路口补给箱地点"}}},fp="23,236,20.603.0,29.196.0,28.137.0,32.159.0,29.141.0"}
P.entries["item:crude-flint"] = {n="粗制打火石",s="粗制打火石碎片是粗糙的引火石，湿地的苔皮豺狼人随身携带着它们。豺狼人用这些石头点燃刚砍下的沼泽木材，这一行为令当地的守护者绿色守卫者雷希耶尔勃然大怒。",h="粗制打火石碎片是粗糙的引火石，湿地的苔皮豺狼人随身携带着它们。豺狼人用这些石头点燃刚砍下的沼泽木材，这一行为令当地的守护者绿色守卫者雷希耶尔勃然大怒。",kw={"粗制打火石","火的禁忌","狼人","绿色守卫者","苔藓蹄","雷希耶尔","敲击石","湿地"},ang={["class:Druid"]="仅仅为了狼人的舒适而破坏活体植物直接触犯了自然法则，因此，对于任何荒野守护者来说，没收并粉碎这些火石都是一种本能的职责。"},sec={{t="泥沼中的火种",b="虽然粗糙且未经加工，但这些简单的敲击打火石为湿地潮湿沼泽中的苔藓蹄狼人提供了取暖和烹饪肉食的主要手段。不幸的是，对于沼泽的生态系统来说，苔藓蹄狼人会砍伐活着的树木来供养他们的炉火和篝火。这种鲁莽的砍伐和燃烧活树枝的行为引起了绿色守卫者雷希耶尔的愤怒，他将每一次火星的迸发都视为对自然平衡的攻击。"},{t="绿色守卫者的报复",b="为了阻止对沼泽树木的屠戮，绿色守卫者雷希耶尔委托路过的冒险者系统性地剥夺苔藓蹄狼人的火石。守护者并不打算重新利用这些搜集来的打火石，而是计划将每一块收回的碎片砸成粉末并扔进大海，确保狼人无法再焚烧湿地的活木。"}},faq={{q="粗制打火石有什么用？",a="苔藓蹄狼人将粗制打火石作为原始的打火工具，用来点火取暖和烹饪。对于旅行者来说，受绿色守卫者雷希耶尔之托，收集这些打火石是为了阻止狼人点燃活树。",al={"粗制打火石用途","粗制打火石有什么用","粗制打火石的目的"}},{q="哪些生物携带粗制打火石？",a="苔藓蹄狼人部落中的大多数成年和特殊成员都携带这种物品，包括苔藓蹄蛮兵、猎手、沼泽奔跑者、迷雾织者、秘法师、阿尔法和格纳博恩。较小的苔藓蹄狼人和混血种并不携带它们。",al={"谁掉落粗制打火石","哪里获得粗制打火石","哪些狼人有打火石"}},{q="为什么绿色守卫者雷希耶尔要销毁这些打火石？",a="绿色守卫者雷希耶尔对狼人砍伐湿地活树并焚烧木材取暖的行为感到恐惧。通过摧毁他们的打火石并将碎片倒入海洋，他希望能永久剥夺他们点燃破坏性火焰的能力。",al={"为什么要销毁粗制打火石","绿色守卫者雷希耶尔销毁打火石的原因","火的禁忌原因"}},{q="这些打火石有锻造价值吗？",a="没有。尽管它们具有矿物属性，但这些只是适合产生粗糙火花的粗糙石头，缺乏铁匠或工程师所要求的纯度或形状。",al={"我可以用粗制打火石锻造吗","粗制打火石是锻造材料吗"}}},fx={b9abde94={q="什么是粗制打火石？",a="粗制打火石是一种粗糙、原始的生火石，由湿地的苔藓爪豺狼人携带。豺狼人利用这些简单的工具敲击出火花来点燃营火，焚烧沼泽地的活树枝来取暖。",al={"什么是粗制打火石","粗制打火石背景故事","这些打火石是什么"}},e1f52dc4={q="粗制打火石来自哪里，是谁制造的？",a="这些石块是由栖息在湿地沼泽中的苔藓爪豺狼人打制并携带的。几乎每一位成年的苔藓爪掠夺者、捕兽者和秘法师都会随身携带一块，作为在潮湿沼泽中引火的必备生存工具。",al={"谁制造了粗制打火石","豺狼人从哪获取粗制打火石","粗制打火石起源"}}},fp="11,247,20.466.1,29.363.1,29.223.1,34.227.0,43.258.1,39.155.0"}
P.entries["item:crystal-kelp-frond"] = {n="水晶藻叶",s="水晶海带叶是艾尔文森林的水晶湖中鱼人所携带的水生植物切片。虽然这种海带原产于海洋，但鱼人会将叶片带到内陆，使它成为了威廉·匹斯特在闪金镇所寻觅的一种不同寻常的炼金试剂。",h="水晶海带叶是艾尔文森林的水晶湖中鱼人所携带的水生植物切片。虽然这种海带原产于海洋，但鱼人会将叶片带到内陆，使它成为了威廉·匹斯特在闪金镇所寻觅的一种不同寻常的炼金试剂。",kw={"水晶海带","水晶藻叶","水晶湖","闪金镇","隐形水","鱼人","威廉·匹斯特"},ang={["profession:Herbalism"]="不同于扎根在土壤中的常见草药，水晶海带是一种无法在艾尔文各地的标准草药点中找到的水生植物；草药师和采集者必须直接从囤积它的当地鱼人手中获取。"},sec={{t="一种稀有的水生试剂",b="水晶海带通常生长在深海海域，因此出现在艾尔文森林的淡水池塘中十分罕见。定居在水晶湖岸边的鱼人部落收集并保存着这些叶片，原因不明。炼金术士看重这些叶片独特的视觉扭曲特性，而闪金镇的威廉·匹斯特专门用它们作为一种隐形水的核心成分，这种药水旨在帮助偷偷摸摸的情侣避开家人的视线。"}},faq={{q="水晶海带在什么地方自然生长？",a="水晶海带是一种海洋植物，通常生长在咸水海域。它并非内陆淡水湖的原生植物，但鱼人部落会收集这些切片并将它们带入像水晶湖这样的淡水区域。",al={"水晶海带生长在哪里","水晶海带来源","海带栖息地"}},{q="为什么水晶湖的鱼人会有海洋海带？",a="鱼人与海岸有着深厚的联系，并会在各条水道之间迁徙。它们从沿海水域采集海带，并随身携带进入湖泊和溪流周边的内陆营地。",al={"为什么鱼人有海带","鱼人持有海带的原因"}},{q="谁在闪金镇需要水晶海带叶？",a="在闪金镇的Lion's Pride Inn工作的药剂师威廉·匹斯特需要这种海带。他用它为梅贝尔·马科伦酿制一种特殊的隐形水，这样她就可以从她家的葡萄园溜出来去见托米·乔·斯通菲尔德。",al={"谁需要水晶海带","威廉·匹斯特海带"}},{q="水晶海带有什么特性？",a="经过炼金术士的适当提炼，水晶海带叶的不寻常品质可以产生强效的隐蔽混合物，特别是能让饮用者暂时隐形的隐形水。",al={"海带效果","水晶海带有什么用"}}},fx={e295764f={q="什么是水晶藻叶？",a="水晶藻叶是水晶海带的切片，这是一种海洋原生的稀有水生植物。虽然主要是海洋植被，但这些藻叶有时会被水晶湖等淡水水域周围的鱼人采集并保存。炼金术士看重这些藻叶是因为它们具有强效、半透明的特性，可以用来酿造诸如隐形水之类的特殊药剂。",al={"什么是水晶藻叶","水晶藻叶信息","什么是水晶海带"}},["8bde59b0"]={q="为什么会有人需要水晶藻叶？",a="闪金镇的炼金术士威廉·匹斯特需要水晶藻叶来酿造一种强效隐形水。他打算用这种药剂来帮助年轻的梅贝尔·马科伦，让她能神不知鬼不觉地从她家人严加看管的葡萄园里溜走，去私会她的禁忌恋人托米·乔·斯通菲尔德。",al={"谁需要水晶藻叶","为什么要采集水晶藻叶","水晶藻叶的用途"}}},fp="18,149,22.409.0,39.159.0,51.136.0,43.232.1,42.162.0"}
P.entries["item:crystal-phial"] = {n="水晶瓶",s="这是一个精致的水晶瓶，由德鲁伊特纳隆·雷拳交给幽影谷的年轻暗夜精灵冒险者。它被用来从附近的月井中汲取圣水，开启一系列旨在荣耀并滋养正在生长的世界之树泰达希尔的仪式。",h="这是一个精致的水晶瓶，由德鲁伊特纳隆·雷拳交给幽影谷的年轻暗夜精灵冒险者。它被用来从附近的月井中汲取圣水，开启一系列旨在荣耀并滋养正在生长的世界之树泰达希尔的仪式。",kw={"奥达希尔","crown of the earth","水晶瓶","月井","幽影谷","泰达希尔","特纳隆·雷拳"},ang={["class:Druid"]="德鲁伊对月井怀有深深的敬意，利用其宁静的特性来引导自然能量并培育新的生长，而不屈服于奥术魔法的诱惑。",["race:NightElf"]="对于刚走出奥达希尔的年轻卡多雷来说，装满这个瓶子是一个基础的成年礼，将他们直接与艾露恩的圣水以及他们的人民在第三次战争后的复兴联系起来。"},sec={{t="圣水容器",b="这个精致的玻璃瓶被交给奥达希尔顶部的暗夜精灵新兵，用于重要的仪式。特纳隆·雷拳指派年轻的守护者携带它前往大树枝北侧的月井，收集那里散发着微光的湖水。虽然构造简单，但瓶中盛放的水蕴含着永恒之井的神圣遗产。带回装满水的水晶瓶是“Crown of the Earth”朝圣之旅的第一步，教导年轻的卡多雷关于他们在岛屿新家园中魔法、历史与自然之间微妙的平衡。"}},faq={{q="水晶瓶的用途是什么？",a="这个瓶子用于从幽影谷奥达希尔北侧的月井收集圣水。一旦装满，它将被送回给特纳隆·雷拳，作为任务“Crown of the Earth”的一部分。",al={"水晶瓶用途","水晶瓶的使用","我该如何处理这个瓶子"}},{q="谁会给你水晶瓶？",a="德鲁伊特纳隆·雷拳在奥达希尔大树枝顶部给年轻冒险者布置最初任务时会提供空的水晶瓶。",al={"谁提供水晶瓶","在哪里获取水晶瓶"}},{q="收集月井之水为何意义重大？",a="月井中包含与永恒之井的精华及艾露恩的恩赐相连的圣水。瓶中汲取的水被用于理解第三次战争的余波，并参与致力于滋养泰达希尔的仪式。",al={"为什么要收集月井之水","月井之水的意义","月井的用途"}},{q="瓶子装满后会发生什么？",a="它会变成装满水的水晶瓶。将其交还给特纳隆·雷拳即可完成你的初步试炼，并开启关于在泰达希尔全境创造和照料世界之树的后续课程。",al={"装满瓶子之后","装满水的水晶瓶用途"}}},fx={d56aa813={q="什么是水晶瓶？",a="水晶瓶是由幽影谷中奥达希尔顶端的特纳隆·雷拳所提供的一种精致、特制的容器。它的设计旨在安全地运输圣水，其纯净的水晶构造确保了你在从森林圣地取回月亮井水时，水中的神圣能量不会受到污染。",al={"什么是水晶瓶","水晶瓶物品"}},["819f868c"]={q="特纳隆·雷拳为什么要装满水晶瓶？",a="特纳隆·雷拳让你装满水晶瓶，作为你加入暗夜精灵社会和迈向更广阔世界的第一步。月亮井中包含着被永恒之井遗产所祝福的水，哨兵将其视为艾露恩的神龛，由德鲁伊照看。采集井水能让你了解在海加尔山所做出的牺牲，并测试你对泰达希尔脆弱现状的理解程度。",al={"为什么要装满水晶瓶","特纳隆为什么要月亮井水","特纳隆的水晶瓶意图"}}},fp="13,258,26.540.0,35.200.0,32.147.0,44.252.0,39.194.0"}
P.entries["item:crystalized-scales"] = {n="水晶鳞片",s="水晶鳞片是从栖息在卡利姆多严酷环境（如焦炭谷和千针石林）中的蛇颈龙身上采集到的坚硬、矿质兽皮。当研磨成细粉时，这些特殊的鳞片便成为了暴风城的施法者们梦寐以求的一种珍奇魔法试剂。",h="水晶鳞片是从栖息在卡利姆多严酷环境（如焦炭谷和千针石林）中的蛇颈龙身上采集到的坚硬、矿质兽皮。当研磨成细粉时，这些特殊的鳞片便成为了暴风城的施法者们梦寐以求的一种珍奇魔法试剂。",kw={"蛇颈龙","焦炭谷","科林·马伦","水晶鳞片","试剂","石爪山脉","暴风城","千针石林"},ang={["class:Mage"]="对于奥术修行者来说，这些鳞片展示了环境暴露如何改变野兽的魔法构成，从而产生用于独特法术配方的专用试剂。",["faction:Alliance"]="获取这些鳞片架起了一座桥梁，连接了联盟首都暴风城与卡利姆多那未被驯服的荒野。"},sec={{t="一种稀有的卡利姆多试剂",b="那些忍受着极端环境高温和灰烬的蛇颈龙——特别是栖息在石爪山的焦炭谷或千针石林那闪烁的盐碱平原中的蛇颈龙——会长出坚硬、布满结晶的兽皮。这些水晶鳞片具有潜在的奥术共鸣，使得无尽之海彼岸那些进行稀有法术实验的学者法师们对其趋之若鹜。"},{t="马伦的奥术研究",b="在人类王国暴风城，法师科林·马伦积极寻找前往卡利姆多边境冒险的探险者，以获取这些鳞片。通过将结晶矿层研磨成粉末，马伦将这种颗粒材料用作他新创法术和个人奥术研究的重要试剂。"}},faq={{q="什么生物会掉落水晶鳞片？",a="它们主要从适应严酷环境的蛇颈龙身上采集，例如石爪山焦炭谷中那些被烧焦、灼伤和熏黑的蛇颈龙，以及在千针石林中发现的盐石蛇颈龙。",al={"鳞片从哪里掉落","谁掉落水晶鳞片","蛇颈龙鳞片的来源"}},{q="谁在暴风城寻求这些鳞片？",a="居住在暴风城的法师科林·马伦委托前往石爪山的旅行者收集这些鳞片，用于他的魔法实验。",al={"谁需要水晶鳞片","科林·马伦 鳞片","谁使用这些鳞片"}},{q="这些鳞片是如何在施法中使用的？",a="据科林·马伦所言，将这些水晶鳞片研磨成细粉可以提供一种强效试剂，这是他自创特殊法术所需的动力来源。",al={"为什么水晶鳞片具有魔法","鳞片法术试剂"}},{q="水晶鳞片只能在石爪山找到吗？",a="虽然马伦特别要求前往石爪山焦炭谷的冒险者收集鳞片，但类似的结晶兽皮也可以从千针石林的盐石蛇颈龙身上采集到。",al={"千针石林 鳞片","获取鳞片的其他地点"}}},fx={cec6ea6a={q="什么是水晶鳞片？",a="水晶鳞片是从某些种类的蛇怪身上采集到的坚硬的结晶外板。值得注意的是，这些坚韧的鳞片常见于栖息在石爪山脉焦炭谷等恶劣地区的蛇怪身上，它们具有独特的矿物类特性，因此受到学者和施法者的青睐。",al={"什么是水晶鳞片","水晶鳞片背景故事","关于水晶鳞片"}},["5be8a367"]={q="水晶鳞片来自哪里？",a="这些鳞片自然生长在特定品种的蛇怪身上。它们通常从徘徊在石爪山脉焦炭谷的焦黑、黝黑且被烧焦的蛇怪身上采集，也常见于千针石林盐碱平原上的盐石蛇怪身上。",al={"水晶鳞片起源","在哪里获得水晶鳞片","水晶鳞片的来源"}}},fp="18,292,23.382.0,20.324.0,40.215.0,41.142.0,40.161.0,51.185.0"}
P.entries["item:curative-animal-salve"] = {n="动物医疗药膏",s="动物医疗药膏是由德鲁伊草药师调配的一种草药疗法，旨在安抚和治愈受蔓延的生态疾病折磨的野生动物。它在黑海岸和贫瘠之地都有配制，作为治疗深受大地无形污秽折磨的病弱生物的一线手段。",h="动物医疗药膏是由德鲁伊草药师调配的一种草药疗法，旨在安抚和治愈受蔓延的生态疾病折磨的野生动物。它在黑海岸和贫瘠之地都有配制，作为治疗深受大地无形污秽折磨的病弱生物的一线手段。",kw={"奥兰达利亚·夜歌","动物医疗药膏","治愈病患","毒素净化能力","病弱小鹿","病弱瞪羚","图加·符文图腾"},ang={["class:Druid"]="施用这种疗法是学习安抚毒素和疾病的基础试炼，证明了你对塞纳里奥议会在卡利姆多使命的忠诚。",["race:Tauren"]="在贫瘠之地使用这种药膏证明了牛头人德鲁伊是如何践行塞纳留斯的教诲，与先祖议会仪式和谐共处以治愈大地。"},sec={{t="修复荒野",b="动物医疗药膏由当地采集的草药原料制成，通常以十份为一批进行配制，用于治疗陷入蔓延腐蚀之苦的野生动物。在黑海岸雾气缭绕的森林中，奥兰达利亚·夜歌指导年轻的德鲁伊将药膏涂抹在徘徊于壁泉河与灰谷边界之间的病弱小鹿身上。在遥远的南方，贫瘠之地的干旱旷野中，图加·符文图腾调配了同样的药剂，用于治疗在十字路口以北吃草的病弱瞪羚。尽管两位草药师都在与当地官员合作以生产更多补给，但实地从业者们还是会将药膏直接施用于那些深受环境恶疾折磨的野兽。"},{t="更深层恶疾的症状",b="直接涂抹药膏可以缓解动物的痛苦，然而塞纳里奥议会认为这些病症仅仅是更大动荡的症状。在月光林地，德迪利特·星焰指出，无论是沿海受折磨的小鹿，还是草原上受苦的瞪羚，都不是随机的受害者。相反，它们是蔓延的枯萎病无意中的牺牲品，这种枯萎病正从多个方向侵袭着卡利姆多。施用药膏是新晋成员的基本仪式，用以考验他们守护自然世界的决心，并磨练他们净化毒素的技艺。"}},faq={{q="动物医疗药膏有什么用途？",a="药膏直接涂抹在受折磨的野生动物身上以治愈它们的疾病。德鲁伊用它来治疗徘徊在黑海岸的病弱小鹿，或是治疗在贫瘠之地十字路口以北吃草的病弱瞪羚。",al={"动物医疗药膏用途","动物医疗药膏使用方法","药膏的作用"}},{q="谁来配制这种药膏？",a="在黑海岸，奥兰达利亚·夜歌在奥伯丁利用采集到的原料配制药膏。在贫瘠之地，十字路口的图加·符文图腾为部落德鲁伊调制这种合剂。",al={"谁制造药膏","药膏来源"}},{q="为什么小鹿和瞪羚会生病？",a="根据塞纳里奥议会的德迪利特·星焰所言，这些野生动物是卡利姆多各地不断蔓延的污秽与腐蚀的受害者，它们是生态失衡枯萎病的早期牺牲品。",al={"动物为什么生病","是什么毒害了黑海岸的小鹿","贫瘠之地瞪羚疾病"}},{q="一批药膏包含多少剂量？",a="一份标准的实地用药剂批次可提供十次单独涂抹的药量，随后草药混合物即会消耗殆尽。",al={"多少使用次数","药膏使用次数"}}},fx={a20a877c={q="什么是动物医疗药膏？",a="动物医疗药膏是一种草药疗法，专门用于治疗受蔓延的不自然疾病困扰的野生动物。它由德鲁伊盟友使用当地试剂配制而成，能够净化毒害黑海岸的鹿和贫瘠之地的瞪羚等无辜生物的顽疾。",al={"治疗药膏","什么是动物医疗药膏","动物医疗药膏背景故事"}}},fp="21,285,17.678.0,28.582.0,39.205.0,23.181.0,54.210.0,36.128.0"}
P.entries["item:daffodil-bouquet"] = {n="水仙花",s="水仙花是一束由湖畔镇的草药师玛蒂·詹罗斯采集的新鲜花束。卫兵帕克本想借此作为浪漫的感谢礼物送给达希，却无意中引发了当地的流言蜚语和一些小小的竞争。",h="水仙花是一束由湖畔镇的草药师玛蒂·詹罗斯采集的新鲜花束。卫兵帕克本想借此作为浪漫的感谢礼物送给达希，却无意中引发了当地的流言蜚语和一些小小的竞争。",kw={"水仙花","达希","卫兵帕克","湖畔镇","玛蒂·詹罗斯","赤脊山"},ang={["profession:Herbalism"]="拜访湖畔镇的草药师们会认出这束花是同行玛蒂·詹罗斯的手艺，这也凸显了当地野生花卉采集的贸易活动。"},sec={{t="纠缠的信物",b="当卫兵帕克想要在Lakeshire Inn感谢达希每天为他准备午餐时，他通过镇上的草药师玛蒂·詹罗斯安排了一次送花。玛蒂准备了一束水仙花，并提到这是她个人最喜欢的花。然而，当这些鲜艳的花朵送到达希手中时，立刻引起了她的怀疑：达希认出这是玛蒂的标志性花卉，并怀疑这位女性怀有嫉妒之心，甚至开玩笑说玛蒂可能会因为怨恨而在花茎上涂毒。"}},faq={{q="水仙花的用途是什么？",a="这束花是送给Lakeshire Inn的达希的。卫兵帕克安排人送去这束花，以此衷心地感谢她每天为他准备并送去午餐。",al={"水仙花用途","水仙花有什么用","谁收到了水仙花"}},{q="谁准备了这束花？",a="湖畔镇的当地草药师和花商玛蒂·詹罗斯应要求采集并捆扎了这束花。她特意选择了水仙花，因为这是她最喜欢的花朵。",al={"谁制作了花束","水仙花来源","花是从哪里来的"}},{q="为什么达希对这些花反应如此多疑？",a="达希立刻认出水仙花是玛蒂最喜欢的花，而不是专门为她挑选的。达希将玛蒂称为嫉妒的竞争对手，并幽默地怀疑这束花是否因怨恨而被下了毒，尽管她最终还是接受了这份心意。",al={"为什么达希生气","达希中毒花朵","达希和玛蒂的竞争"}},{q="水仙花真的有毒吗？",a="没有。达希的怀疑仅仅是这两位湖畔镇女性之间当地戏剧性的嫉妒心作祟。这些花完全无害。",al={"花束有毒吗","玛蒂给水仙花下毒了吗"}}},fx={d233835e={q="什么是水仙花？",a="水仙花是在赤脊山采集的一束新鲜黄色花朵。这被特别选定为玛蒂·詹罗斯最喜欢的花，作为给Lakeshire Inn的达希的谢礼，以回报她提供的一顿餐食。",al={"什么是水仙花","水仙花背景故事","水仙花物品"}},c8a417a4={q="为什么达希需要水仙花？",a="达希并没有特别要求花，但卫兵帕克在收到她送到三角路口哨所的热午餐后，想回馈她的好意。他让你去取一束花来让她开心一下，尽管她在意识到是谁准备的这些草药之前，还是迫不及待地收下并将它们插进水里。",al={"为什么要送水仙花","为什么达希想要花","谁想要水仙花"}}},fp="16,247,15.516.0,38.182.0,26.184.0,49.268.1,36.135.1"}
P.entries["item:daggerspine-scale"] = {n="刺脊纳迦的鳞片",s="刺脊纳迦的鳞片是从游荡在希尔斯布莱德丘陵南岸的刺脊纳迦身上采集的一种坚硬爬行动物鳞片。这种鳞片备受皇家药剂师学会青睐，它们是激活被遗忘者正在进行的瘟疫实验中致命药剂的关键催化剂。",h="刺脊纳迦的鳞片是从游荡在希尔斯布莱德丘陵南岸的刺脊纳迦身上采集的一种坚硬爬行动物鳞片。这种鳞片备受皇家药剂师学会青睐，它们是激活被遗忘者正在进行的瘟疫实验中致命药剂的关键催化剂。",kw={"刺脊","刺脊纳迦的鳞片","苦痛药剂","希尔斯布莱德","林度恩","纳迦","皇家药剂师学会","幽暗城"},ang={["faction:Horde"]="在南岸收集鳞片需要仔细规划，因为刺脊纳迦的营地坐落在离联盟港口南海镇极其危险的近距离处。",["race:Undead"]="获取这些鳞片直接推进了皇家药剂师学会的研究，旨在开发出针对被遗忘者敌人的毁灭性新瘟疫。"},sec={{t="药剂师的研究",b="皇家药剂师学会一直在寻找生物试剂来增强他们的毒素、瘟疫和药剂。在提炼被称为“苦痛药剂”的实验性药剂时，药剂师们发现从当地刺脊纳迦身上取下的鳞片具有独特的反应特性。当这些鳞片与巨魔再生药剂和鱼人器官结合时，可以从化学层面上激活悬浮在原始混合物中的休眠污染剂。要获得这些鳞片，必须在南海镇以东的岩石海岸线上狩猎，同时面对凶残的纳迦部落和附近的联盟军队。"}},faq={{q="刺脊纳迦的鳞片有什么用途？",a="它们是作为研究苦痛药剂的一部分，为塔伦米尔的药剂师林度恩收集的。当与其他试剂混合时，这些鳞片能激活炼金泥头花水的污染特性。",al={"刺脊纳迦的鳞片用途","为什么收集刺脊纳迦的鳞片","刺脊纳迦的鳞片有什么作用"}},{q="这些鳞片从哪里来？",a="它们是从居住在希尔斯布莱德丘陵南海镇人类定居点正东海岸线上的刺脊纳迦（包括岸行者、岸猎者、尖叫者、海妖以及她们的首领泽弗里斯女士）身上剥取下来的。",al={"哪里寻找刺脊纳迦的鳞片","谁掉落刺脊纳迦的鳞片","刺脊纳迦的鳞片位置"}},{q="为什么皇家药剂师学会需要纳迦鳞片？",a="学会的药剂师确定，刺脊部落坚韧的鳞片带有触发他们实验性枯萎病和疾病药剂中特定传染源所需的精确化学性质。",al={"为什么需要纳迦鳞片","药剂师纳迦鳞片"}}},fx={["8e2c4377"]={q="什么是刺脊纳迦的鳞片？",a="刺脊纳迦的鳞片是一种坚韧的水生鳞片，是从徘徊在希尔斯布莱德丘陵海岸的刺脊纳迦身上采集的。这些蛇形生物拥有独特的生物特性，使得它们脱落和采集到的鳞片成为皇家药剂师学会制造邪恶药剂的珍贵试剂。",al={"什么是刺脊纳迦的鳞片","刺脊纳迦的鳞片物品","关于刺脊纳迦的鳞片"}}},fp="17,299,19.597.0,37.222.0,32.233.0,55.227.0"}
P.entries["item:dal-bloodclaw-s-skull"] = {n="达尔·血爪的颅骨",s="达尔·血爪的颅骨取自灰谷北部蓟毛熊怪的首领。将其带给阿斯特兰纳的莱恩·狼行者，即可作为暗夜精灵定居点免于迫在眉睫的攻击的有力证据。",h="达尔·血爪的颅骨取自灰谷北部蓟毛熊怪的首领。将其带给阿斯特兰纳的莱恩·狼行者，即可作为暗夜精灵定居点免于迫在眉睫的攻击的有力证据。",kw={"灰谷","阿斯特兰纳","达尔·血爪","熊怪","莱恩·狼行者","颅骨","蓟毛"},ang={["faction:Alliance"]="击杀达尔·血爪稳固了阿斯特兰纳的北翼，确保了联盟在灰谷中部的这处主要据点依然安全。",["race:NightElf"]="对暗夜精灵来说，铲除堕落的熊怪首领是一种悲哀的必要之举；曾经的古老盟友已被腐蚀扭曲，现在直接威胁到了像阿斯特兰纳这样的定居点。"},sec={{t="首领的覆灭",b="居住在阿斯特兰纳北部的蓟毛熊怪数量激增且极具攻击性，它们和灰谷的大部分古老森林一样受到了腐蚀。暗夜精灵哨兵莱恩·狼行者担心这个不断壮大的部落很快就有胆量直接进犯阿斯特兰纳，于是下令削减其族群人数并杀死其领袖达尔·血爪。获取达尔·血爪的颅骨并非为了炫耀琐碎的复仇，而是作为部落首领已被击溃的冷酷且无可辩驳的证据，为阿斯特兰纳的守军争取了宝贵的时间。"}},faq={{q="达尔·血爪是谁？",a="达尔·血爪是居住在阿斯特兰纳以北蓟毛要塞的蓟毛熊怪的首领。在他的领导下，这个充满敌意的部落迅速繁衍，对附近的暗夜精灵前哨站构成了迫在眉睫的威胁。",al={"达尔·血爪","血爪是谁","蓟毛首领"}},{q="为什么莱恩·狼行者需要这个颅骨？",a="莱恩·狼行者需要证明蓟毛熊怪首领已被击杀。随着达尔·血爪的死亡，暗夜精灵们希望幸存熊怪之间的混乱能够压制任何袭击阿斯特兰纳的有组织计划。",al={"为什么是颅骨","莱恩·狼行者的颅骨","死亡证明"}},{q="为什么蓟毛熊怪如此充满敌意？",a="和灰谷各地的许多熊怪部落一样，蓟毛熊怪屈服于森林中蔓延的腐蚀，从和平的林地邻居变成了暴力且领地意识极强的威胁。",al={"为什么熊怪有攻击性","熊怪的腐蚀","蓟毛发狂"}}},fx={b1ad26a7={q="什么是达尔·血爪的颅骨？",a="这是达尔·血爪被砍下的颅骨，他是阿斯特兰纳以北Thistlefur Hold中受腐化的Thistlefur熊怪的首领。它是他死亡的血腥物证。",al={"什么是达尔·血爪的颅骨","达尔的颅骨","这个颅骨是什么"}},fa2f0114={q="达尔·血爪的颅骨来自哪里？",a="这个颅骨是在达尔·血爪本人被杀，以打破他日益壮大的部落的领导层之后，直接从位于北部灰谷深处的Thistlefur Hold中的遗骸上取下的。",al={"达尔·血爪的颅骨来自哪里","谁制造了达尔·血爪的颅骨","达尔·血爪的颅骨起源"}}},fp="21,238,22.573.0,22.231.0,41.221.0,43.221.0"}
P.entries["item:dalaran-mana-gem"] = {n="达拉然法力宝石",s="达拉然法力宝石是肯瑞托人员在银松森林行动时随身携带的奥术结晶储备。被遗忘者施法者将这些宝石视为制作魔法服饰（如法术火焰长袍）的强力原材料，对此趋之若鹜。",h="达拉然法力宝石是肯瑞托人员在银松森林行动时随身携带的奥术结晶储备。被遗忘者施法者将这些宝石视为制作魔法服饰（如法术火焰长袍）的强力原材料，对此趋之若鹜。",kw={"安伯米尔","达拉然法力宝石","乔瑟夫·格里高利","肯瑞托","亚麻布","法力宝石","银松森林","法术火焰长袍"},ang={["class:Mage"]="被遗忘者学徒法师会被派去获取这些宝石作为一种成人礼，以此证明他们既有战斗能力，又能掌控获取来的奥术源。",["race:Undead"]="这种获取行为凸显了被遗忘者冷酷的务实主义，他们抛弃了对达拉然前人类同事的感伤，只为维持本阵营的生存。"},sec={{t="被窃取的奥术",b="驻扎在银松森林安伯米尔周围的肯瑞托法师、咒术师和卫兵们随身携带特制的法力宝石，以汇聚和补充他们的奥术能量。对于幽暗城Magic Quarter的被遗忘者修行者来说，这些晶体导管是一种触手可及的浓缩魔法精粹来源。尽管一些亡灵法师承认他们与达拉然有着共同的学术渊源，但务实的必要性和生存哲学决定了：对于毫不妥协的竞争对手，剥夺其魔法资源是理所当然的。"},{t="编织法术火焰",b="当从战败的肯瑞托特工身上获取这些宝石后，它们会被连同成捆的亚麻布一起送到幽暗城的乔瑟夫·格里高利这样的裁缝那里。虽然普通的工匠无法直接引导奥术力量，但熟练的裁缝可以将法力宝石编织进布料之中。这种灌注将普通的线变成了附魔的衣物，能够增强初出茅庐的施法者与奥术的联系。"}},faq={{q="达拉然法力宝石来自哪里？",a="它们由驻扎在银松森林的肯瑞托部队携带，特别是在瑟伯切尔东南方、安伯米尔附近的达拉然营地和哨所周围。",al={"哪里可以刷法力宝石","达拉然宝石掉落","谁掉落法力宝石"}},{q="这些宝石有什么用途？",a="被遗忘者法师将其用作必要的附魔材料。将其与亚麻布一起带给幽暗城的乔瑟夫·格里高利，它们能提供编织法术火焰长袍所需的魔法能量。",al={"法力宝石用途","为什么需要达拉然法力宝石"}},{q="为什么银松森林的肯瑞托人员要携带这些宝石？",a="肯瑞托成员将法力宝石用作奥术力量的个人储备，以维持他们在银松森林等敌对地区施法、防御结界和召唤术所需的能量。",al={"为什么达拉然法师会有宝石","肯瑞托法力宝石背景知识"}},{q="为什么被遗忘者会针对达拉然法师获取这些宝石？",a="虽然被遗忘者与达拉然的魔法传统有着共同的学术根源，但他们将这些活着的同类视为竞争对手。幽暗城的导师认为，任何无法捍卫自己奥术财富的法师都不足以生存，这使得掠夺他们的材料变得合乎情理。",al={"被遗忘者与达拉然法师","为什么要为了长袍杀达拉然法师"}}},fx={["02094a76"]={q="什么是达拉然法力宝石？",a="达拉然法力宝石是由驻扎在银松森林的肯瑞托特工所携带的带有魔法充能的石头。这些晶体注入了奥术能量，是制作附魔服装的重要组件，例如幽暗城的被遗忘者裁缝所缝制的法术火长袍。",al={"什么是达拉然法力宝石","达拉然法力宝石","银松森林的法力宝石"}}},fp="16,232,13.549.0,21.423.0,37.169.0,29.187.0,56.187.0,56.259.0"}
P.entries["item:dalaran-pendant"] = {n="达拉然坠饰",s="达拉然坠饰是驻扎在银松森林安伯米尔村的肯瑞托法师们所携带的魔法护身符。被遗忘者试图收集这些坠饰，以干扰这些法师的奥术运作，并追踪他们力量的来源。",h="达拉然坠饰是驻扎在银松森林安伯米尔村的肯瑞托法师们所携带的魔法护身符。被遗忘者试图收集这些坠饰，以干扰这些法师的奥术运作，并追踪他们力量的来源。",kw={"奥利斯特","安伯米尔","达拉然坠饰","肯瑞托","瑟伯切尔","银松森林"},ang={["class:Mage"]="这些坠饰是肯瑞托法术编织的焦点，展示了达拉然术士们是如何协调复杂的集体魔法的。",["race:Undead"]="从肯瑞托手中夺取这些坠饰，是确保银松森林免受试图重新建立据点的人类术士威胁的关键一步。"},sec={{t="安伯米尔的护身符",b="在安伯米尔村，肯瑞托的术士、法师和保护者们正在积极编织强大的奥术法术，威胁着被遗忘者对银松森林南部的控制。每一名行动人员都携带有一枚协调过的达拉然坠饰。在瑟伯切尔，暗影牧师奥利斯特指派被遗忘者的特工回收这些坠饰，以减缓法师们的行动，并找出是谁在引导他们的奥术编织。"}},faq={{q="什么是达拉然坠饰？",a="它是由驻扎在安伯米尔的肯瑞托术士、法师和保护者所佩戴的奥术护身符。被遗忘者回收它们是为了打断法师们的仪式运作，并研究他们的魔法技艺。",al={"什么是达拉然坠饰","银松森林肯瑞托项链"}},{q="谁携带这些坠饰？",a="它们是由占据银松森林安伯米尔的达拉然人类法师、术士和保护者所携带的。",al={"谁掉落达拉然坠饰","哪里获得达拉然坠饰"}},{q="为什么暗影牧师奥利斯特想要这些坠饰？",a="暗影牧师奥利斯特和他的盟友达拉需要这些坠饰来减缓法师们的施法速度，并查明在安伯米尔引导魔法能量编织的强大法师。",al={"为什么奥利斯特需要坠饰","安伯米尔调查坠饰"}},{q="安伯米尔位于何处？",a="安伯米尔位于银松森林南部。从瑟伯切尔向南旅行的游客在主干道上走东边的岔路即可找到该村庄。",al={"安伯米尔位置","如何前往安伯米尔"}}},fp="15,250,20.406.0,28.198.0,27.115.0,42.176.0,27.149.0"}
P.entries["item:dalaran-status-report"] = {n="达拉然形势报告",s="“达拉然形势报告”是一份由驻扎在银松森林安伯米尔的肯瑞托法师所汇编的敏感情报集。它详细记录了达拉然城重建的现状，使之成为被被遗忘者和幽暗城死亡追猎者垂涎的文件。",h="“达拉然形势报告”是一份由驻扎在银松森林安伯米尔的肯瑞托法师所汇编的敏感情报集。它详细记录了达拉然城重建的现状，使之成为被被遗忘者和幽暗城死亡追猎者垂涎的文件。",kw={"安伯米尔","安伯米尔保险箱","达拉然形势报告","死亡追猎者","肯瑞托","mennet carkad","行业工具","瓦里玛萨斯"},ang={["class:Rogue"]="Mennet Carkad将取回这份报告作为一项实地测试，用于训练死亡追猎者在警惕的法师面前磨练精细的开锁和潜入技艺。",["race:Undead"]="安伯米尔的肯瑞托残党是银松森林中被遗忘者的眼中钉，因此任何有关他们行动的情报对于幽暗城的安全都至关重要。"},sec={{t="关注重建中的城市",b="第三次战争期间，天灾军团洗劫了达拉然，阿克蒙德摧毁了它高耸的尖塔。幸存的法师在重建初期移除了它的防护罩，并在空旷地带重建这座城市。肯瑞托还在银松森林东南部维持着诸如安伯米尔等飞地。“达拉然形势报告”中包含着死亡追猎者所觊觎的有关达拉然现状的情报。"},{t="死亡追猎者的试炼",b="掌控洛丹伦需要绝对的警惕，瓦里玛萨斯领主密切监视着联盟和肯瑞托的任何残余势力。在被遗忘者的审讯官从一名肯瑞托俘虏口中逼供出情报后，这位恐惧魔王命令死亡追猎者去获取这份形势报告。这份文件被藏在安伯米尔深处的一个上锁保险箱里，它不仅是一项行动必需品，也成为了在Rogues' Quarter跟随Mennet Carkad磨练开锁技艺的新手潜行者们的试炼仪式。"}},faq={{q="什么是达拉然形势报告？",a="这是一套机密的肯瑞托文件，概述了达拉然的现状、恢复行动和状况，由维护安伯米尔哨所的法师汇编而成。",al={"什么是这份报告","达拉然报告","安伯米尔文件"}},{q="这份报告保存在哪里？",a="安伯米尔的法师将报告锁在他们位于银松森林东南部的定居点内的一个保险箱里，以防闯入者和好奇之眼窥探。",al={"报告在哪里","安伯米尔保险箱位置","如何找到形势报告"}},{q="为什么幽暗城想要这份报告？",a="瓦里玛萨斯领主和被遗忘者认为幸存的肯瑞托是他们家门口的一大威胁。获取这份报告可以让死亡追猎者评估达拉然的军事实力和秘密重建项目。",al={"为什么被遗忘者想要这个","瓦里玛萨斯 达拉然报告","死亡追猎者目标"}},{q="死亡追猎者是如何得知这份文件的？",a="死亡追猎者直接从一名在幽暗城被关押和审问的肯瑞托俘虏口中获取了这份文件的存在信息及其位置。",al={"幽暗城是如何发现的","俘虏招供"}}},fx={f1fae308={q="达拉然形势报告来自哪里，是谁制作的？",a="这份报告由驻扎在银松森林南部安伯米尔的肯瑞托巫师起草。在第三次战争期间达拉然遭到破坏后，幸存的法师们在周边地区维持哨站，以监视他们沦陷的城市、记录正在发生的事务并协调他们剩余的部队。",al={"谁撰写了达拉然形势报告","达拉然形势报告起源","谁制作了达拉然形势报告"}}},fp="21,286,27.409.0,21.518.1,34.185.0,25.172.0,40.223.0,51.147.0"}
P.entries["item:dalin-s-heart"] = {n="达林的心脏",s="达林的心脏是一件可怕的仪式材料，它取自达林·锻造者，这名高尚的人曾在银松森林的格雷迈恩之墙附近巡逻。幽暗城的术士寻找它作为纯洁无瑕的祭品，意图引诱并奴役一名魅魔为他们效力。",h="达林的心脏是一件可怕的仪式材料，它取自达林·锻造者，这名高尚的人曾在银松森林的格雷迈恩之墙附近巡逻。幽暗城的术士寻找它作为纯洁无瑕的祭品，意图引诱并奴役一名魅魔为他们效力。",kw={"凯伦丁·哈加尔","达林·锻造者","达林的心脏","格雷迈恩之墙","纯洁之心","银松森林","魅魔","幽暗城"},ang={["class:Warlock"]="获取这颗心脏是被遗忘者术士学习奴役魅魔的重要仪式，证明了他们愿意为了获得恶魔的控制力而收割未受污染的纯洁。",["race:Undead"]="对达林心脏的搜寻凸显了天灾军团战后洛丹伦的残酷现实，格雷迈恩之墙外幸存的人类利他主义者成为了被遗忘者的猎物。"},sec={{t="黑暗艺术所需的纯洁之心",b="为了召唤并奴役魅魔，幽暗城的术士们需要一种稀有的诱饵：真正善良的凡人的心脏。达林·锻造者因为无私的奉献而遭遇了黑暗的命运，他终日守护着那些被格雷迈恩之墙拒之门外、走投无路的洛丹伦难民。他毫无保留的利他主义使他成为了这片沦陷之地上善良的象征，这让他的心脏成为了在被诅咒的神庙中进行的恶魔诱惑仪式中，极具吸引力的奖品。"}},faq={{q="达林·锻造者是谁？",a="达林·锻造者是一名高尚的人类，他毕生致力于保护那些被困在银松森林南部，紧闭的格雷迈恩之墙大门外的洛丹伦难民。",al={"达林·锻造者","达林是谁","达林背景故事"}},{q="为什么术士需要达林的心脏？",a="幽暗城的术士召唤师需要一颗真正纯洁高尚之人的心脏，作为引诱并控制魅魔的仪式诱饵。",al={"为什么要达林的心脏","达林的心脏用途","术士为什么想要达林的心脏"}},{q="谁会接收达林的心脏？",a="这颗心脏会被带给凯伦丁·哈加尔，他是位于幽暗城被诅咒的神庙里的一位术士训练师。",al={"谁接收心脏","达林的心脏上交","去哪上交达林的心脏"}},{q="除了这颗心脏，还需要什么其他材料？",a="凯伦丁·哈加尔需要达林的心脏和Comar's Heart，后者属于科马尔·维拉德，这是一位在湿地游荡，寻找失踪妻子的忠诚丈夫。",al={"纯洁之心所需另一颗心脏","需要另一颗心脏","第二颗心脏"}}},fx={["5b5f5201"]={q="什么是达林的心脏？",a="这是从达林·锻铸者身上切下来的实体心脏，他是一位在银松森林格雷迈恩之墙附近照顾洛丹伦难民的正直之人。虽然在物理上与其他人类心脏没有区别，但它拥有无私且高尚灵魂所独有的纯洁精神。",al={"什么是达林的心脏","达林的心脏描述","达林的心脏物品"}},d7d2edf8={q="达林的心脏来自哪里？",a="这颗心脏来自达林·锻铸者，一位在银松森林南部封闭的格雷迈恩之墙照顾洛丹伦难民的正直之人。术士必须追踪并杀死他，才能直接从他的尸体中获取这个器官。",al={"在哪里获取达林的心脏","达林的心脏起源","谁掉落达林的心脏"}}},fp="13,271,26.478.0,26.182.0,35.143.0,26.116.0,52.160.0"}
P.entries["item:darkhound-blood"] = {n="黑暗犬的血液",s="黑暗犬的血液是一种从提瑞斯法林地原野和森林中徘徊的受污染犬类野兽身上采集到的恶臭体液。在皇家药剂师学会的授意下，这种血液被收集起来，作为他们研制致命新瘟疫的早期试剂。",h="黑暗犬的血液是一种从提瑞斯法林地原野和森林中徘徊的受污染犬类野兽身上采集到的恶臭体液。在皇家药剂师学会的授意下，这种血液被收集起来，作为他们研制致命新瘟疫的早期试剂。",kw={"新瘟疫","药剂师乔汉","布瑞尔","黑暗犬","黑暗犬的血液","皇家药剂师学会","提瑞斯法林地"},ang={["faction:Horde"]="当黑暗实验在布瑞尔悄然进行时，除了被遗忘者核心圈外，鲜有人完全了解皇家药剂师学会正在释放的毒性潜力。",["race:Undead"]="采集黑暗犬的血液等试剂对于被遗忘者来说是至关重要的工作，这能帮助Sylvanas女士和皇家药剂师学会打造出对抗天灾军团的终极武器。"},sec={{t="新瘟疫的燃料",b="在Sylvanas Windrunner的统领下，皇家药剂师学会致力于开发一种能够消灭Arthas及其天灾军团的剧毒瘟疫。驻扎在布瑞尔的药剂师乔汉推测，当地那些受到黑暗能量侵蚀且对周围腐败环境具有抗性的野兽，拥有不同寻常的生物特性。通过蒸馏野生黑暗犬的血液，乔汉旨在找出能够抵抗或传播剧毒坏死菌株的生物化合物。"}},faq={{q="黑暗犬的血液有什么用途？",a="它被布瑞尔的药剂师乔汉用作皇家药剂师学会研究的基础试剂，旨在调制出一种比艾泽拉斯所见过的任何瘟疫都更为致命的新型瘟疫。",al={"黑暗犬的血液用途","为什么要获得黑暗犬的血液","黑暗犬的血液目的"}},{q="哪些生物会掉落这种血液？",a="它提取自徘徊在提瑞斯法林地的各种黑暗犬，包括被诅咒的、饥饿的以及衰弱的黑暗犬。",al={"在哪里获得黑暗犬的血液","谁掉落黑暗犬的血液","黑暗犬的血液来源"}},{q="为什么将黑暗犬作为瘟疫研究的目标？",a="药剂师乔汉推测，那些适应了提瑞斯法腐化之地的野兽，其血液可能蕴含着合成这种不可阻挡的瘟疫所需的生物学秘密。",al={"为什么选择黑暗犬","药剂师乔汉的理论","黑暗犬的特性"}}},fx={db825c3d={q="什么是黑暗犬的血液？",a="黑暗犬的血液是从徘徊在提瑞斯法林地的野性黑暗犬身上采集的受污染的生命液体。这些被黑暗魔法和遍布林地的残留亡灵扭曲的可怜犬类，其血液携带独特的、坚韧的特性。尽管对于普通的活体生物来说，它既令人作呕又具有危险性，但炼金术士和研究人员发现它是进行生物实验的理想媒介，特别是在研究剧毒化合物或抵抗亡灵腐烂时。",al={"什么是黑暗犬的血液","黑暗犬的血液背景故事","解释黑暗犬的血液"}},["93cde5f9"]={q="黑暗犬的血液来自哪里？是谁制造的？",a="这种血液是从提瑞斯法林地被诅咒、饥饿而衰弱的黑暗犬身上自然采集的。这些野兽在闹鬼的林地和废弃农庄间徘徊。它并非人工调制品，而是野兽的体液；自第三次战争以来，它们逐渐适应并吸收了毒害这片区域的腐化之力。",al={"黑暗犬血液的来源","黑暗犬的血液来自哪里","谁制造了黑暗犬的血液"}}},fp="15,275,23.478.0,33.185.0,33.119.0,48.179.0"}
P.entries["item:darkshore-grouper"] = {n="黑海岸石斑鱼",s="黑海岸石斑鱼是一种原产于黑海岸迷雾缭绕的沿海水域的坚韧咸水鱼。这种鱼既是美味的日常食材，也是垂钓者的运动猎物，但由于鱼人活动导致当地渔民无法出海，现在从码头捕获它们变得越来越困难了。",h="黑海岸石斑鱼是一种原产于黑海岸迷雾缭绕的沿海水域的坚韧咸水鱼。这种鱼既是美味的日常食材，也是垂钓者的运动猎物，但由于鱼人活动导致当地渔民无法出海，现在从码头捕获它们变得越来越困难了。",kw={"奥伯丁","布拉普家族鱼竿","黑海岸","黑海岸石斑鱼","钓鱼","石斑鱼","古博·布拉普","鱼人"},ang={["profession:Cooking"]="黑海岸石斑鱼是制作简单沿海食谱的多功能配料，对于那些希望在岸边磨练手艺的旅行厨师来说，这是一种方便获得的渔获。",["race:Dwarf"]="矮人垂钓者古博·布拉普在卡利姆多的海岸上代表着他家族引以为傲的钓鱼传统，他会奖励任何能达到他族人捕鱼水平的人。"},sec={{t="被笼罩海岸的日常主食",b="黑海岸石斑鱼栖息在黑海岸冰冷的海水中，是海岸垂钓者梦寐以求的渔获。这种鱼以其烹饪的多样性而闻名，成为了奥伯丁周边旅行者和居民喜爱的各种简单沿海菜肴的原材料。虽然用基本的钓鱼装备就能从浪花中钓到它们，但渔民们认为垂钓的过程和品尝美味一样令人享受。"},{t="鱼人的威胁",b="从历史上看，像古博·布拉普这样的渔民会乘小船进入更深的水域，一网打尽地捕捞石斑鱼。然而，海岸鱼人日益增长的攻击性使奥伯丁周围的大多数船只无法出海。由于垂钓者被迫只能待在海岸线和码头上，当地人怀疑入侵的鱼人正在吞噬当地的石斑鱼种群，这使得在没有耐心的情况下很难获得好的渔获。"}},faq={{q="哪里可以找到黑海岸石斑鱼？",a="黑海岸石斑鱼可以通过在黑海岸沿岸的咸水中投掷鱼线捕获，包括奥伯丁周围的水域。",al={"哪里钓石斑鱼","黑海岸石斑鱼位置","如何捕捉黑海岸石斑鱼"}},{q="在奥伯丁，谁需要黑海岸石斑鱼？",a="停留在奥伯丁的矮人渔夫古博·布拉普会请求旅行者为他捕捉黑海岸石斑鱼，以换取珍贵的布拉普家族鱼竿。",al={"谁需要石斑鱼","古博·布拉普 鱼","石斑鱼任务发布者"}},{q="为什么渔民不使用船只来捕捞石斑鱼？",a="极具攻击性的鱼人已经沿着黑海岸的海岸线移动，使得当地渔民的乘船出海变得非常危险。",al={"为什么船只停运","奥伯丁钓鱼船","鱼人 石斑鱼"}},{q="捕捉黑海岸石斑鱼需要接取任务吗？",a="不需要。虽然它是古博·布拉普等当地人所要求任务的目标，但黑海岸石斑鱼是一种普通的咸水鱼，任何将鱼线投入黑海岸水域的垂钓者都可以钓到它。",al={"石斑鱼是任务物品吗","我可以随时钓石斑鱼吗"}}},fx={bdb033c0={q="什么是黑海岸石斑鱼？",a="黑海岸石斑鱼是一种生活在黑海岸雾气弥漫的海岸附近的本地咸水鱼。古博·布拉普等当地钓鱼爱好者十分珍视它；它既是从海浪中垂钓的绝佳猎物，也是适合家常烹饪的多用途食材。",al={"什么是黑海岸石斑鱼","黑海岸石斑鱼","黑海岸石斑鱼简介"}},["97e4a4d8"]={q="黑海岸石斑鱼来自哪里？",a="黑海岸石斑鱼是一种野生咸水鱼，原产于黑海岸沿岸的海域。它并非由任何人制作或创造，不过要捕获它，必须在岸边和码头向海浪中抛竿垂钓。",al={"黑海岸石斑鱼的来历","黑海岸石斑鱼来自哪里","黑海岸石斑鱼产自哪里"}},f987244e={q="古博·布拉普为什么想要黑海岸石斑鱼？",a="古博·布拉普只是喜欢钓这种鱼，也喜欢吃它。他夸口说，新鲜捕获的鱼可以做出许多美味佳肴。由于凶恶的鱼人把当地渔船赶离了水面，他只能依靠热心的旅人从海岸捕捉这些鱼。",al={"为什么想要黑海岸石斑鱼","古博为什么想要石斑鱼","黑海岸石斑鱼有什么用途"}}},fp="17,267,30.384.0,17.397.0,37.148.0,41.157.0,50.139.0,58.198.0"}
P.entries["item:darksoul-shackle"] = {n="魔魂镣铐",s="魔魂镣铐是一种附魔束缚物，由在银松森林中潜行的月怒魔魂狼人佩戴。这些器具是在大法师阿鲁高的指导下制造的，瑟伯切尔的被遗忘者法师们为了解开控制该地区的野性魔法，一直在搜寻它们。",h="魔魂镣铐是一种附魔束缚物，由在银松森林中潜行的月怒魔魂狼人佩戴。这些器具是在大法师阿鲁高的指导下制造的，瑟伯切尔的被遗忘者法师们为了解开控制该地区的野性魔法，一直在搜寻它们。",kw={"阿鲁高","达拉尔·道恩维沃尔","魔魂镣铐","月怒魔魂","瑟伯切尔","银松森林","狼人"},ang={["class:Mage"]="检查这些镣铐揭示了一个绝望的巫师是如何使用粗糙的附魔工艺品来支撑他无法妥善控制的不稳定召唤法术的。",["race:Undead"]="对于被遗忘者来说，打破阿鲁高对银松森林的控制对于保护他们的南部边界以及证明幽暗城的奥术学术地位高于达拉然的失败至关重要。"},sec={{t="对不稳魔法的补救",b="当大法师阿鲁高将狼人释放到银松森林时，他自身的奥术造诣不足以完全引导和维持这些异界的野兽。为了弥补自己的短板，他将魔魂镣铐之类的附魔器具束缚在这些造物身上。这些镣铐将外部法术引导至月怒魔魂狼人体内，增强了它们的超自然力量，并以此锚定诅咒，使它们受困于影牙城堡。"},{t="肯瑞托的审视",b="在瑟伯切尔，被遗忘者法师达拉尔·道恩维沃尔认为阿鲁高是个危险且无能之辈，他的干预毁掉了肯瑞托对抗天灾军团的防御。通过收集魔魂镣铐以及从月怒饕餮者身上撕下的镣铐，被遗忘者研究人员提取了编织在金属中的残留附魔。研究这些拐杖般的器具揭示了阿鲁高法术结构中的缺陷，为被遗忘者提供了必要的奥术洞察力，以制定针对他狼人灾祸的对策。"}},faq={{q="什么是魔魂镣铐？",a="这是一种附魔金属镣铐，由银松森林里的月怒魔魂狼人佩戴。它是由大法师阿鲁高制造的，旨在加强他那充满缺陷的法术，并以此将这些野兽束缚在他的控制之下。",al={"魔魂镣铐是什么","魔魂镣铐物品背景","这个镣铐是什么"}},{q="谁需要魔魂镣铐？",a="驻扎在银松森林瑟伯切尔的被遗忘者法师达拉尔·道恩维沃尔需要它们。他通过研究镣铐内部的附魔，试图找到解决阿鲁高狼人爆发事件的方法。",al={"谁需要魔魂镣铐","谁在收集镣铐","达拉尔·道恩维沃尔任务"}},{q="这些镣铐从哪里来？",a="它们是从月怒魔魂的尸体上回收的，这些极具攻击性的狼人徘徊在银松森林的北部和东部地区。",al={"谁掉落魔魂镣铐","魔魂镣铐怪物","哪里获取魔魂镣铐"}},{q="阿鲁高为什么要给狼人戴上镣铐？",a="根据达拉尔·道恩维沃尔的说法，阿鲁高没有足够的法师天赋仅凭纯粹的力量来驾驭这些野兽。他依赖像这些镣铐一样的附魔物品来引导和维持使狼群凝聚在一起的不稳定魔法。",al={"为什么狼人佩戴镣铐","阿鲁高镣铐的目的"}}},fp="16,273,28.448.0,18.505.1,27.191.0,28.193.0,34.140.0,42.237.0"}
P.entries["item:darnassus-marzipan"] = {n="达纳苏斯水果糖",s="达纳苏斯水果糖是为庆祝万圣节而在暗夜精灵主城制作的节日糖果。达纳苏斯的旅店老板会将其分发给愿意通过跳舞来换取甜蜜奖励的捣蛋鬼们。",h="达纳苏斯水果糖是为庆祝万圣节而在暗夜精灵主城制作的节日糖果。达纳苏斯的旅店老板会将其分发给愿意通过跳舞来换取甜蜜奖励的捣蛋鬼们。",kw={"糖果","达纳苏斯","达纳苏斯水果糖","万圣节","耶斯帕尔","水果糖","甜点"},ang={["faction:Alliance"]="收集来自达纳苏斯、铁炉堡和暴风城的糖果，通过共同的万圣节庆典将联盟中远隔重洋的子民们联系在一起。",["race:NightElf"]="就连严肃的卡多雷也欣然接受了秋季的轻松习俗，向那些以热情的舞蹈来回馈其好客之道的旅行者们提供甜蜜的水果糖。"},sec={{t="世界之树的味道",b="在万圣节期间，联盟的各个主城都会参与轻松愉快的“不给糖就捣蛋”传统活动。当矮人们提供清凉薄荷糖，暴风城制作耐嚼牛轧糖时，达纳苏斯的旅店老板们则为游客准备了精致的达纳苏斯水果糖。获得这种糖果需要游客展示出一点节日精神——具体来说，就是按照旅店老板的要求跳舞。这种糖果是耶斯帕尔寻找的四种地区特产之一。耶斯帕尔是暴风城Cathedral Square的一名患病孤儿，无法亲自外出收集糖果。"}},faq={{q="达纳苏斯水果糖有什么用？",a="达纳苏斯水果糖是万圣节期间暴风城Cathedral Square孤儿院里的患病孤儿耶斯帕尔所需的四种特殊糖果之一。将它与来自铁炉堡、诺莫瑞根和暴风城的糖果一起交给耶斯帕尔，可以换取一捆节日南瓜糖。",al={"达纳苏斯水果糖用途","水果糖怎么用"}},{q="如何获得达纳苏斯水果糖？",a="在万圣节期间由达纳苏斯的旅店老板发放。旅店老板会要求你在得到这份甜点前先跳一段舞。",al={"如何获得达纳苏斯水果糖","哪里能得到水果糖"}},{q="为什么耶斯帕尔不能自己去拿水果糖？",a="耶斯帕尔生病了，无法外出参加“不给糖就捣蛋”活动。他待在暴风城Cathedral Square的孤儿院里，只能依靠冒险者们为他收集远方的糖果。",al={"为什么耶斯帕尔需要糖果","为什么耶斯帕尔不能去"}}},fp="18,203,25.452.0,36.271.0,37.102.0,42.169.0"}
P.entries["item:darthalia-s-sealed-commendation"] = {n="达萨利亚的奖状",s="达萨利亚的奖状是塔伦米尔的被遗忘者战斗指挥官起草的一份正式公文。它赞扬了一名士兵在针对希尔斯布莱德人类的战役中坚持不懈的表现，并将这些胜利的消息直接传达给幽暗城的高层指挥部。",h="达萨利亚的奖状是塔伦米尔的被遗忘者战斗指挥官起草的一份正式公文。它赞扬了一名士兵在针对希尔斯布莱德人类的战役中坚持不懈的表现，并将这些胜利的消息直接传达给幽暗城的高层指挥部。",kw={"奖状","达萨利亚","希尔斯布莱德","南海镇","塔伦米尔","幽暗城","瓦里玛萨斯"},ang={["faction:Horde"]="这份奖状标志着洛丹伦一场关键的战略胜利，向幽暗城的领导层证明了联盟在南部丘陵地带的筑垒据点是可以被系统性瓦解的。",["race:Undead"]="赢得达萨利亚的高度赞扬并将其直接呈交给王座大厅，可以提升一名士兵在黑暗女王那日益壮大的军事等级中的地位。"},sec={{t="向高层指挥部汇报",b="在希尔斯布莱德丘陵发生残酷冲突后，高级执行官达萨利亚起草了这份密封的公文，以正式记录针对希尔斯布莱德人类防御者的胜利，以及对人类据点造成的破坏。该文件经过密封，以防止指挥官的评估被窥探，收件人为Sylvanas Windrunner的恐惧魔王顾问瓦里玛萨斯。对于Royal Quarter的被遗忘者领导层来说，此类公文提供了切实可行的证据，证明洛丹伦南部的人类据点是可以被瓦解的，从而使北部驻军能够集中精力应对天灾军团带来的无情威胁。"}},faq={{q="什么是达萨利亚的奖状？",a="这是由塔伦米尔的高级执行官达萨利亚签署的一份正式战争奖状。该文件正式表彰了一名战士在希尔斯布莱德之战中对抗联盟的战斗表现，并旨在呈交给幽暗城的高层指挥部。",al={"密封的奖状","达萨利亚的信件","希尔斯布莱德报告"}},{q="谁来接收这份奖状？",a="这份奖状必须直接交给恐惧魔王瓦里玛萨斯，他在幽暗城的Royal Quarter辅佐Sylvanas Windrunner监督军事行动。",al={"我应该把这个交给谁","奖状上交","谁会收到达萨利亚的奖状"}},{q="为什么瓦里玛萨斯关心希尔斯布莱德的战斗？",a="尽管被遗忘者认为巫妖王及其天灾军团是来自北方的首要生存威胁，但希尔斯布莱德的人类存在不断干扰着他们的补给线和南部边境安全。瓦里玛萨斯看重那些能够消除人类障碍的战场胜利，使幽暗城的军队能够专注于更宏大的战争。",al={"为什么瓦里玛萨斯会在意","希尔斯布莱德的恐惧魔王","被遗忘者在希尔斯布莱德的战略"}}},fx={fd99e080={q="达萨利亚的奖状来自哪里？是谁制作的？",a="这封信由被遗忘者指挥官达萨利亚亲笔撰写并封缄，她负责协调希尔斯布莱德丘陵的部落军队。她认可你在对抗希尔斯布莱德人类定居点的艰苦战役中展现的英勇与不懈毅力，于是写下这份正式公文，亲自向高层赞扬你在战场上的功绩。",al={"谁写了达萨利亚的奖状","达萨利亚的奖状来自哪里","谁送出了密封奖状"}},["9dfe1fb6"]={q="瓦里玛萨斯为什么想要达萨利亚的奖状？",a="达萨利亚将这份文件直接送往幽暗城交给瓦里玛萨斯，好让被遗忘者的领导层注意到你致命的作战效率。虽然恐惧魔王视北方的天灾军团为首要威胁，但希尔斯布莱德的人类联盟军扰乱了他们更宏大的战略计划。这份奖状正式证明，在你这样的能干战地勇士带领下，对人类定居点发动决定性打击确实能够奏效。",al={"为什么要递送密封奖状","瓦里玛萨斯为什么想要奖状","达萨利亚的奖状有何用途"}}},fp="31,261,22.601.0,40.251.0,31.175.0,58.345.0"}
P.entries["item:deadmire-s-tooth"] = {n="死沼巨鳄的牙齿",s="死沼巨鳄的牙齿是从那只被称为死沼巨鳄的远古鳄鱼身上获取的战利品，它潜伏在尘泥沼泽的浑浊水域中。将它带给雷霆崖猎人高地的梅洛·石蹄，便证明了这头年迈的掠食者已经得到了仁慈而光荣的终结。",h="死沼巨鳄的牙齿是从那只被称为死沼巨鳄的远古鳄鱼身上获取的战利品，它潜伏在尘泥沼泽的浑浊水域中。将它带给雷霆崖猎人高地的梅洛·石蹄，便证明了这头年迈的掠食者已经得到了仁慈而光荣的终结。",kw={"鳄鱼","死沼巨鳄","尘泥沼泽","猎人高地","梅洛·石蹄","雷霆崖","牙齿"},ang={["class:Hunter"]="对于在猎人高地的导师门下学习的猎人们来说，获取这颗牙齿是一堂课，教导他们狩猎必须包含尊重与仁慈，而不仅仅是为了追求战利品。",["race:Tauren"]="对死沼巨鳄的狩猎体现了大地母亲的平衡循环，让年迈的掠食者走向安宁，而不是任其受苦。"},sec={{t="仁慈的战利品",b="在猎人高地的牛头人猎人传统中，追踪野生兽类不仅仅是对武艺的考验或盲目的血腥运动。它是一份关于平衡、敬畏以及偶尔施以仁慈的精神契约。死沼巨鳄曾是尘泥沼泽中最壮丽的鳄鱼之一，但岁月的侵蚀让它的晚年充满了极度的痛苦。尽管它依然拥有全盛时期那般不屈的精神和恐怖的凶猛，但它巨大的骨骼和衰弱的躯体已成为痛苦的囚笼。获取死沼巨鳄的牙齿是向梅洛·石蹄证明这头野兽长期的苦难终于通过一场光荣的狩猎得以终结的实物凭证。"}},faq={{q="死沼巨鳄的牙齿有什么用？",a="这颗牙齿需要交给雷霆崖猎人高地的梅洛·石蹄。它完成了他指派的追踪死沼巨鳄的狩猎任务，并提供了这头远古掠食者已获得仁慈解脱的证明。",al={"死沼巨鳄的牙齿上交","谁需要死沼巨鳄的牙齿","死沼巨鳄的牙齿有什么用"}},{q="死沼巨鳄的牙齿从何而来？",a="这颗牙齿直接取自死沼巨鳄，这是一头徘徊在尘泥沼泽南部沼泽地带的巨大远古鳄鱼，经常在Tabetha's Farm以东的水域出没。",al={"哪里获得死沼巨鳄的牙齿","谁掉落死沼巨鳄的牙齿","死沼巨鳄位置"}},{q="为什么梅洛·石蹄要猎杀死沼巨鳄？",a="梅洛并不认为死沼巨鳄是个怪物，而是一头在垂暮之年忍受着疯狂肉体折磨的高贵生物。这场狩猎是一种仁慈的行为，让这头鳄鱼的生命之火能够平静地熄灭，而不是在缓慢的折磨中消逝。",al={"为什么要杀死沼巨鳄","梅洛·石蹄的理由","死沼巨鳄是邪恶的吗"}}},fx={["4f19a846"]={q="什么是死沼巨鳄的牙齿？",a="死沼巨鳄的牙齿是从死沼巨鳄的颚中取下的战利品。这只体型庞大、年岁古老的鳄鱼潜伏在尘泥沼泽里。对于遵循雷霆崖牛头人传统的猎人来说，这颗牙齿是有力的凭证，证明他们追踪到了这头强大的野兽，并让它得以安然解脱。",al={"死沼巨鳄的牙齿","死沼巨鳄的牙齿是什么","死沼巨鳄牙齿信息"}},["200b2360"]={q="为什么有人想要死沼巨鳄的牙齿？",a="雷霆崖猎人高地上的猎人训练师梅洛·石蹄要这颗牙齿作为你完成狩猎的凭证。死沼巨鳄年事已高，骨骼常年摩擦，始终承受着难以忍受的痛苦。牛头人敬重自然，也认为仁慈是猎人神圣职责的一部分；带回牙齿，便能让梅洛确信你已经结束了这头高贵野兽的苦难。",al={"为什么要带回死沼巨鳄的牙齿","谁想要死沼巨鳄的牙齿","梅洛为什么想要这颗牙齿"}}},fp="16,270,17.677.0,34.204.0,38.166.0,46.238.0"}
P.entries["item:death-cap"] = {n="毒帽蘑菇",s="毒帽蘑菇是一种罕见且强效的真菌，隐藏在黑海岸峭壁之泉后的阴影洞穴中。暗夜精灵炼金术师因其独特的药性而对其趋之若鹜，但想要采集它，必须冒险进入古树之林所警告的地底巢穴。",h="毒帽蘑菇是一种罕见且强效的真菌，隐藏在黑海岸峭壁之泉后的阴影洞穴中。暗夜精灵炼金术师因其独特的药性而对其趋之若鹜，但想要采集它，必须冒险进入古树之林所警告的地底巢穴。",kw={"奥伯丁","巴瑞萨斯·月影","洞穴蘑菇","峭壁之泉","黑海岸","毒帽蘑菇","古树之林","粗柄蘑菇"},ang={["profession:Herbalism"]="虽然为巴瑞萨斯采集毒帽蘑菇并不需要专业的镰刀，但任何草药师都会明白在潮湿且受到腐蚀的地底区域采集稀有真菌所蕴含的危险。",["race:NightElf"]="获取毒帽蘑菇可以达成两个目的：既能帮助奥伯丁的巴瑞萨斯制作药水，又能证实古树之林发出的可怕预言。"},sec={{t="黑暗中的毒花",b="毒帽蘑菇仅生长在黑海岸东北部山脊峭壁之泉后方的潮湿洞穴中。与洞穴地面上随处可见的粗柄蘑菇不同，毒帽蘑菇非常稀有且特征鲜明。像巴瑞萨斯·月影这样的暗夜精灵草药师将这种真菌视为炼金实验的珍宝，尽管获取哪怕一株样本都需要冒着生命危险，进入那据说潜伏着某种新现腐蚀力量的洞穴。"},{t="峭壁之泉的预兆",b="采集毒帽蘑菇既是一项炼金任务，也是一次侦察行动。古树之林的守护者们曾警告当地的卡多雷不要靠近瀑布，因为他们感觉到黑暗中有一种邪恶的存在正在扎根。那些进入洞穴采摘蘑菇的人，必须直面那些将这处潮湿空洞据为巢穴的潜伏力量。"}},faq={{q="我在哪里可以找到毒帽蘑菇？",a="毒帽蘑菇生长在黑海岸东北部、背靠山壁的峭壁之泉后方的隐蔽洞穴内。",al={"毒帽蘑菇位置","毒帽蘑菇在哪里","峭壁之泉洞穴蘑菇"}},{q="谁需要这种蘑菇？",a="居住在沿海定居点奥伯丁的炼金术师巴瑞萨斯·月影正在寻找毒帽蘑菇，用以酿制一种特制的药水。",al={"谁需要毒帽蘑菇","巴瑞萨斯蘑菇任务"}},{q="为什么巴瑞萨斯·月影不自己去采集？",a="来自古树之林的树木守护者警告巴瑞萨斯远离峭壁之泉后的洞穴，因为他们感觉到一股正在蔓延的邪恶力量已将该洞穴作为藏身之处。",al={"为什么他不亲自去","巴瑞萨斯的警告"}},{q="毒帽蘑菇与粗柄蘑菇有何区别？",a="虽然粗柄蘑菇在峭壁之泉的洞穴地面上相对丰富，但毒帽蘑菇是一种更稀有、药性更强的真菌，需要仔细寻找才能发现。",al={"毒帽蘑菇与粗柄蘑菇","蘑菇之间的区别"}}},fx={["508b05a0"]={q="什么是毒帽蘑菇？",a="毒帽蘑菇是一种极其罕见、效力强大的蘑菇，生长在黑海岸幽暗隐秘之处。它不同于普通的林地真菌，只在某些特定的隐秘洞穴中生长，例如峭壁之泉后方的洞穴。它那不祥的名字既反映了它的稀有，也暗示了它潜在的危险，因此成为研究当地独特植物的炼金术士和草药师珍视的样本。",al={"什么是毒帽蘑菇","毒帽蘑菇","毒帽蘑菇是什么种类"}}},fp="9,273,25.485.0,19.361.1,29.125.0,24.132.0,50.177.0,50.166.0"}
P.entries["item:deathstalker-report"] = {n="亡灵哨兵的报告",s="亡灵哨兵的报告是由亡灵哨兵兰妮·尤瑞克所写的一份书面通讯，详细记录了银松森林的军事侦察情况。它包含旨在传达给瑟伯切尔的高级执行官哈德瑞克的关键战术情报，涉及当地天灾军团的动向以及被遗忘者前线斥候的状态。",h="亡灵哨兵的报告是由亡灵哨兵兰妮·尤瑞克所写的一份书面通讯，详细记录了银松森林的军事侦察情况。它包含旨在传达给瑟伯切尔的高级执行官哈德瑞克的关键战术情报，涉及当地天灾军团的动向以及被遗忘者前线斥候的状态。",kw={"亡灵哨兵的报告","哈德瑞克","奎恩","兰妮·尤瑞克","天灾军团","瑟伯切尔","银松森林"},ang={["class:Rogue"]="携带由经验丰富的亡灵哨兵收集的情报，可以让人直接了解使被遗忘者军队保持运转的隐秘侦察工作。",["race:Undead"]="这份报告强调了亡灵哨兵所面临的无情效率和持续不断的危险，他们是为希尔瓦娜斯守卫洛丹伦边境的情报收集部门。"},sec={{t="前线情报",b="在银松森林北部进行侦察是一项致命的任务，即便是对于亡灵来说也是如此。在发现自己被潜伏在松林中的天灾军团伏击并困住后，亡灵哨兵兰妮·尤瑞克和奎恩·尤瑞克不得不将他们的发现整理成这份匆忙写就的公文。报告总结了意料之外的天灾军团抵抗程度，这些抵抗正威胁着被遗忘者在该地区的领土企图。由于奎恩在任务中身受重伤，这份文件被托付给路过的盟友，以确保瑟伯切尔的高级执行官哈德瑞克能毫不拖延地收到消息。"}},faq={{q="什么是亡灵哨兵的报告？",a="这是一份由亡灵哨兵兰妮·尤瑞克汇编的战地报告，记录了在银松森林中活动的被遗忘者斥候所面临的危险、天灾军团的活动以及障碍。",al={"这份报告是什么","亡灵哨兵的报告背景故事","什么是亡灵哨兵的报告"}},{q="是谁写的这份报告？",a="这份报告是由亡灵哨兵兰妮·尤瑞克在照顾她受伤的兄弟——亡灵哨兵奎恩，并遭遇了当地的天灾军团之后所写的。",al={"谁写了亡灵哨兵的报告","报告作者","谁写的"}},{q="这份报告是送给谁的？",a="它是致送并交付给驻扎在瑟伯切尔的被遗忘者指挥官高级执行官哈德瑞克的，他负责监督整个银松森林的军事行动。",al={"报告送到哪里","谁收到报告","哈德瑞克的报告"}},{q="为什么这份报告如此迫切地需要？",a="高级执行官哈德瑞克低估了银松森林中天灾军团的庞大数量。这份报告概述了这些敌对势力，提供了保护被遗忘者占领工作所需的重要数据。",al={"为什么它很重要","为什么哈德瑞克需要它","里面有什么信息"}}},fp="19,312,22.578.0,32.178.0,21.157.0,31.167.0,37.209.0"}
P.entries["item:deepfury-s-orders"] = {n="深怒的命令",s="《深怒的命令》是一份从萨多尔大桥下老锈锁的尸体上回收的皱巴巴的羊皮纸。上面记载了黑铁矮人的残酷指令，正是这些人伏击了这位负责侦查的矮人守卫。",h="《深怒的命令》是一份从萨多尔大桥下老锈锁的尸体上回收的皱巴巴的羊皮纸。上面记载了黑铁矮人的残酷指令，正是这些人伏击了这位负责侦查的矮人守卫。",kw={"黑铁","深怒","命令","拉格·加玛森","老锈锁","萨多尔大桥","湿地"},ang={["faction:Alliance"]="这份被截获的命令揭露了一起针对丹莫罗、湿地以及北部联盟前哨站之间主要陆路动脉的破坏企图。",["race:Dwarf"]="在萨多尔大桥下发现黑铁矮人的阴谋对铁炉堡的矮人来说打击沉重，因为这座大桥代表了他们王国最伟大的工程成就之一，也是至关重要的北部贸易通道。"},sec={{t="大桥下的紧握",b="在侦查萨多尔大桥的地基时，矮人桥梁守卫老锈锁被突然出现的黑铁矮人伏击并杀害。在这位侦察兵紧握的拳头旁，放着这份由敌方首领深怒草拟的命令。这份文件直接证明了一个针对连接湿地与阿拉希高地的桥梁的协同阴谋。"},{t="揭露威胁",b="将《深怒的命令》带回给拉格·加玛森，证实了驻守大桥的守军最担心的猜想。这绝非一场随机的冲突，黑铁矮人在萨多尔大桥宏伟的石构建筑下方进行了蓄意的行动，这促使他们紧急向铁炉堡和暴风城请求增援。"}},faq={{q="什么是《深怒的命令》？",a="这是一份属于黑铁指挥官深怒的军事命令书，在萨多尔大桥下老锈锁的尸体旁被发现。",al={"深怒的命令","这些命令是什么","深怒的羊皮纸"}},{q="这份命令在哪里可以找到？",a="这张羊皮纸是在湿地北部萨多尔大桥下方宽阔的支撑结构中，老锈锁紧握的拳头旁被发现的。",al={"命令在哪里","老锈锁的位置","找到深怒的命令"}},{q="谁是老锈锁？",a="老锈锁是一名驻扎在萨多尔大桥的矮人侦察兵，他在下桥调查桥梁支撑处的异常活动时，遭到了黑铁矮人的伏击。",al={"谁是老锈锁","老锈锁的背景故事"}},{q="谁会接收《深怒的命令》？",a="这份命令被带给了拉格·加玛森，他是驻守在萨多尔大桥附近丹莫德的矮人指挥官，他阅读了命令以评估黑铁矮人的威胁。",al={"我应该把命令交给谁","拉格·加玛森"}}},fx={["21094d89"]={q="深怒的命令来自哪里？",a="这些书面命令源自黑铁氏族，以负责在萨多尔大桥周边策划敌对行动的行动人员或首领深怒命名。伏击并杀害山地猎人老锈锁的黑铁矮人曾携带这些命令；它们被遗落在他倒下的尸体旁的泥土中。",al={"谁写了深怒的命令","深怒的命令来源","谁制作了深怒的命令"}},ac08f373={q="拉格·加玛森为什么想要深怒的命令？",a="拉格·加玛森需要确凿证据，弄清失踪斥候老锈锁的遭遇。这份羊皮纸残酷地证实了这位山地猎人的死讯，也揭露了黑铁矮人在桥附近正在策划的敌对阴谋。",al={"为什么要把深怒的命令交给拉格","为什么有人想要深怒的命令","拉格·加玛森的命令"}}},fp="17,217,24.375.0,21.315.1,27.153.0,27.151.0,22.175.0,31.156.0"}
P.entries["item:deepmoss-egg"] = {n="深苔蜘蛛的卵",s="深苔蜘蛛的卵是深苔蜘蛛在石爪山脉的峭壁和峡谷中产下的成堆卵群。棘齿城的贪婪地精商人们对其垂涎三尺，这些卵最终将被运往藏宝海湾的港口，成为那里的奇异珍馐。",h="深苔蜘蛛的卵是深苔蜘蛛在石爪山脉的峭壁和峡谷中产下的成堆卵群。棘齿城的贪婪地精商人们对其垂涎三尺，这些卵最终将被运往藏宝海湾的港口，成为那里的奇异珍馐。",kw={"藏宝海湾","深苔蜘蛛的卵","深苔蜘蛛","麦伯克·米希瑞克斯","棘齿城","希塞尔山谷","石爪山脉","狂风峭壁"},ang={["profession:Cooking"]="虽然人类、兽人和矮人厨师可能会犹豫，但藏宝海湾的居民们却将搅拌好的蜘蛛卵视为一种值得地精高价售卖的冒险珍馐。"},sec={{t="峭壁上的美味",b="深苔蜘蛛在石爪山脉的崎岖高地上筑巢，特别是在希塞尔山谷和狂风峭壁残存的树木之下。它们留下的卵群包含着活跃的蛛卵，被厚厚的蛛网囊和潮湿的山地苔藓包裹着。虽然对于大多数旅行者来说这些卵囊看起来很不讨喜，但它们却引起了地精商人的注意。"},{t="藏宝海湾的烹饪风尚",b="在南方的藏宝海湾港口，蜘蛛卵煎蛋卷已经成为了一种古怪的美食潮流。由于本地供应无法满足富有海盗和冒险美食家们的胃口，棘齿城的商人麦伯克·米希瑞克斯通过码头管理员迪兹威格协调货运。冒险者们勇闯石爪山脉的毒蛛群来采集新鲜的卵群，将危险的蜘蛛巢穴变成了有利可图的航运合同。"}},faq={{q="深苔蜘蛛的卵在哪里可以找到？",a="它们位于贫瘠之地西北方的石爪山脉中。在狂风峭壁残存的树木下，以及深入希塞尔山谷的毒蛛巢穴中，都可以找到这些卵群。",al={"卵的位置","哪里可以获得深苔蜘蛛的卵","深苔蜘蛛的卵位置"}},{q="谁想要收集这些卵？",a="棘齿城的地精企业家麦伯克·米希瑞克斯会雇佣冒险者来采集它们，并安排与码头管理员迪兹威格的贸易路线，将这些卵群运往海外。",al={"谁需要深苔蜘蛛的卵","谁购买深苔蜘蛛的卵","麦伯克·米希瑞克斯任务"}},{q="这些卵到底有什么用？",a="它们被运往藏宝海湾，在那里，蜘蛛卵煎蛋卷已成为当地海盗和顾客中一种流行但又离奇的烹饪风尚。",al={"蜘蛛卵用途","为什么要收集蜘蛛卵","蜘蛛卵煎蛋卷"}},{q="为什么采集它们时会警告希塞尔山谷的情况？",a="希塞尔山谷是一个充满成年蜘蛛、蛛网和被蚕食猎物的恐怖滋生地。麦伯克提醒那些肠胃不好的人，最好还是在狂风峭壁稀疏的树木下采集卵。",al={"希塞尔山谷警告","肠胃弱者希塞尔"}}},fx={["19ff336a"]={q="什么是深苔蜘蛛的卵？",a="深苔蜘蛛的卵是石爪山脉本地深苔蜘蛛产下的卵。这些裹着蛛丝的卵成堆聚集在树下，深藏于山间峡谷之中。大胆的冒险者主要会采集它们，以便在海那边稀奇古怪的美食市场上换取钱财。",al={"什么是深苔蜘蛛的卵","深苔蜘蛛的卵"}},["80df5d4f"]={q="深苔蜘蛛的卵来自哪里？",a="这些卵由侵扰石爪山脉峭壁和山谷的深苔蜘蛛产下，尤其常见于狂风峭壁和险峻的希塞尔山谷。它们自然成窝产在尚存的树根附近和蛛巢旁，并非由有思想的凡人制造。",al={"深苔蜘蛛卵的来源","深苔蜘蛛的卵来自哪里","谁产下深苔蜘蛛的卵"}}},fp="12,262,23.380.0,24.427.0,30.207.0,32.171.0,36.148.0,54.217.0"}
P.entries["item:defias-docket"] = {n="迪菲亚记事本",s="迪菲亚记事本是一份属于迪菲亚潜行者的机密行动命令集，被发现隐藏在暮色森林西部的腐草农场中。它包含有关迪菲亚雄心勃勃的阴谋的详细情报，为寻找暴风城失踪的特使提供了关键线索。",h="迪菲亚记事本是一份属于迪菲亚潜行者的机密行动命令集，被发现隐藏在暮色森林西部的腐草农场中。它包含有关迪菲亚雄心勃勃的阴谋的详细情报，为寻找暴风城失踪的特使提供了关键线索。",kw={"腐草农场","迪菲亚记事本","迪菲亚保险箱","暮色森林","埃林·提亚斯","失踪的外交官","守夜人巴库斯"},ang={["class:Rogue"]="这本记事本严厉地提醒人们，迪菲亚潜行者在普通强盗的伪装下，运用了多么复杂的密码工作和秘密后勤。",["faction:Alliance"]="记事本内的文件揭露了一个协同一致的迪菲亚阴谋，其影响远超普通的土匪行径。"},sec={{t="通往黑暗的足迹",b="在追查王国失踪外交官的线索时，埃林·提亚斯大师指引调查人员前往暮色森林。守夜人巴库斯注意到迪菲亚潜行者近期有异常活动，正向腐草农场汇集，那是一座位于从西部荒野进入的道路以南的废弃农场。迪菲亚记事本被藏在该处的一个保险箱内，其中包含详细记录迪菲亚潜行者行动的复杂档案，其复杂程度远超简单的公路抢劫或当地土匪行为。"},{t="阴谋之网",b="检查后，这些文书被证明过于错综复杂且具有政治危险性，守夜人巴库斯拒绝保管，担心如果被发现处理这些文件会受到上级的严厉惩罚。在被送回暴风城的提亚斯奶酪店后，记事本揭露迪菲亚潜行者投入了大量资源进行精心策划的绑架计划，并与已知的地下组织成员（例如代号为“拳头”的特工）进行了关联。"}},faq={{q="什么是迪菲亚记事本？",a="这是一份属于迪菲亚潜行者的正式书面文件和命令集合，详细记录了他们的计划以及他们在暮色森林和西部荒野周围进行的秘密行动。",al={"什么是记事本","迪菲亚文件","失踪外交官记事本"}},{q="在哪里可以找到迪菲亚记事本？",a="它被锁在腐草农场那座破旧农舍里的一个迪菲亚保险箱中，就在从西部荒野进入暮色森林西部的道路南侧。",al={"记事本位置","迪菲亚记事本在哪里找到","腐草农场记事本"}},{q="为什么记事本会保存在暮色森林？",a="迪菲亚潜行者将腐草农场用作西部荒野和暮色森林之间的一个偏远集结地，以协调一项高度优先的行动，从而避开暴风城主要巡逻队的监视。",al={"为什么在暮色森林","腐草农场的迪菲亚潜行者"}},{q="谁在分析这份记事本？",a="守夜人巴库斯在简单查看后将其直接送往暴风城的埃林·提亚斯处，他的私人情报网络专门负责破译地下组织的秘密通讯。",al={"谁得到了记事本","谁在阅读记事本"}}},fp="13,178,21.413.0,21.383.1,26.174.0,33.154.0,36.181.0,24.189.0"}
P.entries["item:defias-tower-key"] = {n="迪菲亚塔楼钥匙",s="迪菲亚塔楼钥匙是从守卫西部荒野Klaven's Tower的怪异哨兵身上偷来的物品。它由防守该地点的畸变无人机携带，是迪菲亚潜行者危险行动的重要证据，也是暴风城情报人员搜寻的目标。",h="迪菲亚塔楼钥匙是从守卫西部荒野Klaven's Tower的怪异哨兵身上偷来的物品。它由防守该地点的畸变无人机携带，是迪菲亚潜行者危险行动的重要证据，也是暴风城情报人员搜寻的目标。",kw={"密探吉尔妮","迪菲亚塔楼钥匙","暮色森林宝箱","克拉文·摩特维克","klaven's tower","畸形迪菲亚无人机","mathias shaw","军情七处"},ang={["class:Rogue"]="获取迪菲亚塔楼钥匙是与军情七处合作的潜行者的一项典型考验，要求潜行者精通潜行、扒窃以及对致命毒药的了解。",["faction:Alliance"]="从Klaven's Tower获得情报有助于暴风城调查迪菲亚潜行者来自暮色森林的奇怪货物。"},sec={{t="来自扭曲守卫的战利品",b="位于西部荒野海岸线的Klaven's Tower长期以来一直是迪菲亚潜行者的据点，但最近从暮色森林运来的货物为其周边带来了更加可怕的哨兵。守卫中包括畸形的迪菲亚无人机——一种浑身长满尖刺的不死憎恶。为了突破防御并证明外围防线已被渗透，军情七处的情报员会在现场监视，并要求外勤特工从这些怪异的哨兵身上扒窃，而不是直接与他们交战。这把钥匙是渗透者在未触发警报的情况下潜入防线的有力证据。"},{t="揭开暮色森林的联系",b="找回这把钥匙是揭开一起远超一般拦路抢劫的非自然阴谋的第一步。塔内有一个装有来自暮色森林货物的箱子，里面装着克拉文·摩特维克的日记。当交给暴风城的马迪亚斯·肖尔大师时，任务揭示了迪菲亚潜行者是如何与荆棘谷地精勾结，贩运被流放者赞吉尔所发现的特殊巨魔毒药的。这些混合物可以使死者复生，这也解释了为什么塔楼周围驻扎着这些怪异、不断咳嗽的憎恶。"}},faq={{q="如何获得迪菲亚塔楼钥匙？",a="这把钥匙不能从被击败的敌人身上拾取。特工必须潜行靠近并扒窃守卫西部荒野Klaven's Tower外部的其中一个畸形迪菲亚无人机。",al={"我在哪里可以得到钥匙","如何获得迪菲亚塔楼钥匙","谁掉落迪菲亚塔楼钥匙"}},{q="迪菲亚塔楼钥匙能打开什么？",a="这把钥匙并不能物理打开塔门或里面的暮色森林宝箱。相反，它是马迪亚斯·肖尔大师所需的情报信物，用于核实特工是否成功在未被发现的情况下潜入了防线。",al={"它能打开暮色森林宝箱吗","这能打开什么门","迪菲亚钥匙能解锁什么"}},{q="守卫塔楼的畸形迪菲亚无人机是什么？",a="它们是驻扎在Klaven's Tower周围的怪异带刺不死守卫。密探吉尔妮不知道是什么制造了它们，并要求特工调查它们所看守的货物。",al={"谁持有钥匙","塔楼守卫是什么","带刺的僵尸是什么"}},{q="是谁派遣特工去获取这把钥匙？",a="正在监视Klaven's Tower外围的军情七处侦察员密探吉尔妮，指挥外勤潜行者获取钥匙，并为暴风城的马迪亚斯·肖尔大师取回暮色森林宝箱中的物品。",al={"谁发布任务","谁需要这把钥匙"}}},fp="16,168,30.445.0,34.457.1,39.138.0,36.165.0,56.166.1,42.182.0"}
P.entries["item:deliah-s-ring"] = {n="黛丽娅的戒指",s="黛丽娅的戒指是一件雕刻过的珠宝，从银松森林里烂皮豺狼人堆积的尸堆中寻获。戒指上刻着“致黛丽娅”，这条纪念品提供了一条线索，追溯回了一具从提瑞斯法林地的集体坟墓中被盗的瘟疫受害者遗体。",h="黛丽娅的戒指是一件雕刻过的珠宝，从银松森林里烂皮豺狼人堆积的尸堆中寻获。戒指上刻着“致黛丽娅”，这条纪念品提供了一条线索，追溯回了一具从提瑞斯法林地的集体坟墓中被盗的瘟疫受害者遗体。",kw={"布瑞尔","黛丽娅","黛丽娅的戒指","刻字戒指","芬里斯岛","哈德瑞克","执政官塞弗伦","烂皮豺狼人"},ang={["race:Undead"]="这枚戒指展示了被遗忘者存在的冰冷现实：凡人的羁绊往往随着血肉一同腐烂，尽管仍有极少数人固守着对生前所爱之人的记忆。"},sec={{t="泥沼中的纪念品",b="这枚戒指是在银松森林的豺狼人土堆中，从一具尸体布满麻点、相对新鲜的手上发现的，上面仅刻着：“致黛丽娅”。这一发现揭示了当地的烂皮豺狼人不仅仅是在战场上搜刮——他们还在主动劫掠提瑞斯法林地的集体坟墓，并将人类和被遗忘者的尸体运往南部的芬里斯岛，以达到他们邪恶的目的。"},{t="与布瑞尔的关联",b="当被带到被遗忘者当局面前时，高级执行官哈德瑞克指引将这件文物送往布瑞尔，执政官塞弗伦在那里保存着近期死者的记录。塞弗伦证实黛丽娅生前居住在布瑞尔，后死于瘟疫，并在尸体盗贼挖掘出她的遗体前被安葬在那里。追踪这枚戒指揭示了她所留之人的挥之不去的悲伤，并考验着凡人的忠诚是否能在转变为亡灵的过程中幸存下来。"}},faq={{q="黛丽娅的戒指在哪里发现？",a="这枚戒指是在调查银松森林北部的烂皮豺狼人土堆时发现的，它就戴在被搜刮的死者中一具未被包裹的瘟疫受害者手上。",al={"在哪里可以找到黛丽娅的戒指","黛丽娅的戒指位置","如何获得黛丽娅的戒指"}},{q="黛丽娅是谁？",a="黛丽娅曾是布瑞尔的居民，死于瘟疫。她的遗体被安葬在当地的集体坟墓中，随后被烂皮豺狼人偷走并拖到了银松森林。",al={"黛丽娅是谁","黛丽娅的背景故事","布瑞尔的黛丽娅"}},{q="为什么烂皮豺狼人会有她的遗体？",a="追随天灾军团的烂皮豺狼人一直在劫掠提瑞斯法林地的公共墓地，囤积尸体并将它们运往他们在芬里斯岛的据点。",al={"为什么豺狼人偷盗尸体","烂皮尸体窃贼","豺狼人拿尸体做什么"}},{q="戒指上的铭文是什么？",a="戒圈内侧刻着“致黛丽娅”字样，表明这是她在去世前爱人或丈夫赠送的个人礼物。",al={"戒指铭文","戒指上写了什么","致黛丽娅戒指"}}},fx={c1c1eafc={q="什么是黛丽娅的戒指？",a="黛丽娅的戒指是一件刻有铭文的私人饰品，发现时戴在银松森林一名死去女性的手上，周围是腐皮豺狼人。戒指上只刻着“献给黛丽娅”，是洛丹伦瘟疫蔓延之前，爱情与生命留下的罕见遗物。",al={"什么是黛丽娅的戒指","黛丽娅的戒指背景","关于黛丽娅的戒指"}},a38bd9ea={q="为什么需要黛丽娅的戒指？",a="高级执行官哈德瑞克认为，这枚戒指是重要证据，表明腐皮豺狼人正在提瑞斯法林地的瘟疫墓地中搜掘新鲜尸体。除了提供军事线索外，这枚戒指还可以通过布瑞尔的记录确认死去女性的身份，让人有机会查明曾经爱着她的人是谁，以及那位哀悼者是否仍然活着。",al={"为什么留下黛丽娅的戒指","谁想要黛丽娅的戒指","为什么要交出黛丽娅的戒指"}}},fp="13,266,22.395.0,13.454.1,29.182.0,15.183.0,42.173.0,36.143.0"}
P.entries["item:delivery-to-mathias"] = {n="给马迪亚斯的密信",s="给马迪亚斯的密信是一个密封的包裹，由闪金镇的科瑞恩·塞尔留斯托付给有前途的潜行者。将其交给马迪亚斯·肖尔大师，可以使一名有志成为特工的新人进入暴风城军情七处的内部工作。",h="给马迪亚斯的密信是一个密封的包裹，由闪金镇的科瑞恩·塞尔留斯托付给有前途的潜行者。将其交给马迪亚斯·肖尔大师，可以使一名有志成为特工的新人进入暴风城军情七处的内部工作。",kw={"给马迪亚斯的密信","闪金镇","科瑞恩·塞尔留斯","mathias shaw","old town","包裹","军情七处","暴风城"},ang={["class:Rogue"]="这个包裹象征着潜行者从街头巷尾的小打小闹，过渡到马迪亚斯·肖尔领导下的皇家情报间谍世界的成人礼。",["faction:Alliance"]="在区域侦察员与首都之间传递秘密快件，能确保暴风城秘密间谍机构在应对内部颠覆活动时有效运作。"},sec={{t="信使的测试",b="在外行看来，把一个简单的包裹从Lion's Pride Inn送到暴风城兵营，似乎只是普通的信使工作。但对于初出茅庐的潜行者来说，这个包裹是他们加入暴风城情报部门的试金石。它由当地训练师科瑞恩·塞尔留斯转交，为新手窃贼提供了直接接触马迪亚斯·肖尔大师的机会，考验他们穿梭于首都、保持低调以及在不问缘由的情况下执行秘密指令的能力。"},{t="通往军情七处的大门",b="运送这个包裹意味着特工将直接进入位于Old Town的军情七处总部中心。马迪亚斯·肖尔利用这种交付方式将伪装者与真正的人才区分开来。那些毫无差错地送达包裹的人会获得高风险的实地任务奖励，首先是针对艾尔文森林中迪菲亚潜行者走私网络的秘密侦察与渗透。"}},faq={{q="给马迪亚斯的密信里装的是什么？",a="对信使而言，包裹始终处于密封状态。鉴于它是由外勤训练师科瑞恩·塞尔留斯传递给间谍大师马迪亚斯·肖尔的，其中很可能包含情报报告、学员评估，或是关于艾尔文森林中迪菲亚潜行者等当地威胁的机密材料。",al={"包裹里有什么","递送内容","包裹内容"}},{q="是谁寄送了这份包裹？",a="这份包裹由科瑞恩·塞尔留斯转交，她是一位驻扎在闪金镇Lion's Pride Inn楼上的潜行者特工兼训练师。",al={"谁给了我这个包裹","包裹发送者","科瑞恩·塞尔留斯包裹"}},{q="马迪亚斯·肖尔的总部在哪里？",a="马迪亚斯·肖尔位于军情七处建筑的二楼，该建筑坐落在Old Town东南角的暴风城兵营内。",al={"马迪亚斯·肖尔在哪里","去哪里递送包裹","肖尔的位置"}},{q="把包裹交给肖尔后会发生什么？",a="一旦肖尔确认了你的能力，他就会带你正式进入实地间谍活动。他会派你去渗透杰罗德码头，从一名迪菲亚码头管理员手中窃取一份Shipping Schedule。",al={"递送后的下一个任务","肖尔做什么","给马迪亚斯递送之后"}}},fp="19,158,16.428.0,15.335.0,39.181.0,24.132.0,46.156.0,49.182.1"}
P.entries["item:deviate-hide"] = {n="变异皮革",s="变异皮革是剥自居住在哀嚎洞穴内的野兽的变异毛皮。在德鲁伊纳拉雷克斯那堕落梦境的扭曲下，这些非同寻常的毛皮被德鲁伊们所搜寻，他们试图将梦魇的污染转化成耐用的皮革制品。",h="变异皮革是剥自居住在哀嚎洞穴内的野兽的变异毛皮。在德鲁伊纳拉雷克斯那堕落梦境的扭曲下，这些非同寻常的毛皮被德鲁伊们所搜寻，他们试图将梦魇的污染转化成耐用的皮革制品。",kw={"贫瘠之地","变异皮革","皮革","纳尔帕克","纳拉雷克斯","梦魇","毛皮","哀嚎洞穴"},ang={["class:Druid"]="对德鲁伊来说，收集变异皮革是一场与翡翠梦魇对自然腐蚀力量的直接对抗，尽管像纳尔帕克这样的学徒试图将这些受污染的材料净化，以供生存所需。"},sec={{t="梦魇的污染毛皮",b="当暗夜精灵德鲁伊纳拉雷克斯在贫瘠之地下方陷入沉睡时，他的梦境化作了一场翡翠梦魇，扭曲了当地洞穴的生态。潜伏在深处的野兽变成了不自然的变异掠食者，长着坚韧且变异的毛皮。虽然本质上沾染了邪恶，但这些毛皮却拥有一种不同寻常的柔韧性，使其特别适合皮革制作。纳尔帕克栖身于洞穴入口上方那酷似头骨的岩石结构中，他收集这些皮革以研究其特性，并将它们制成坚固的实用背包。"}},faq={{q="变异皮革与普通皮革有何不同？",a="变异皮革源自被纳拉雷克斯沉睡中渗出的翡翠梦魇所扭曲的生物。这种腐蚀改变了它们的肉体，赋予了它们普通野兽毛皮所不具备的奇异且超凡的耐用性和弹性。",al={"变异皮革背景知识","为什么变异皮革很奇怪","变异毛皮的本质"}},{q="谁在收集这些皮革？",a="纳拉雷克斯的学徒纳尔帕克正驻扎在哀嚎洞穴入口上方的眼窝状洞穴中，他在搜寻这些毛皮。他认为尽管变异野兽生性邪恶，但它们的材料仍可被净化，并制成有用的皮革制品。",al={"谁在寻找变异皮革","纳尔帕克的皮革","谁需要变异皮革"}},{q="哪里可以找到变异皮革？",a="它们取自潜行在贫瘠之地下方哀嚎洞穴内的各种变异野兽，包括迅猛龙、毒蛇、鳄鱼和恐惧之牙。",al={"变异皮革在哪里掉落","如何获取变异皮革"}}},fx={["8b5833f5"]={q="变异皮革来自哪里？是谁制造的？",a="变异皮革取自哀嚎洞穴深处游荡的奇异畸变野兽。这些生物并非出自凡人之手，而是在贫瘠之地地下诞生；德鲁伊纳拉雷克斯陷入沉睡时，被吞噬他的邪恶梦魇所改变。异常的腐化扭曲了当地野生生物，使它们的皮毛也带上奇异而超凡的特质。",al={"变异皮革来自哪里","变异皮革的来源","谁制造了变异皮革"}}},fp="12,267,30.569.0,56.225.0,30.260.0,30.158.0"}
P.entries["item:devlin-s-remains"] = {n="代弗林的遗骸",s="代弗林的遗骸是代弗林·阿加曼德的遗骨。他是阿加曼德磨坊业主的幼子，这家人曾经非常富有。他在被摧毁的祖宅附近的道路上游荡，成为了一名毫无思想的天灾军团奴仆。他最终被击败，遗骨被带给布瑞尔的一名复仇心切的幸存者。",h="代弗林的遗骸是代弗林·阿加曼德的遗骨。他是阿加曼德磨坊业主的幼子，这家人曾经非常富有。他在被摧毁的祖宅附近的道路上游荡，成为了一名毫无思想的天灾军团奴仆。他最终被击败，遗骨被带给布瑞尔的一名复仇心切的幸存者。",kw={"阿加曼德磨坊","布瑞尔","库勒曼·法席恩","代弗林·阿加曼德","代弗林的遗骸","闹鬼的磨坊","提瑞斯法林地"},ang={["race:Undead"]="对于被遗忘者来说，阿加曼德家族代表了洛丹伦陈旧且享有特权的贵族阶级，他们的无能导致平民死亡并复活成为怪物，因此亵渎代弗林的遗骸也是一种阶级报复行为。"},sec={{t="苦涩的遗产",b="在生前，代弗林·阿加曼德一直活在他哥哥瑟曼的阴影之下。瑟曼温和而高大，而人们印象中的代弗林身体虚弱，且言辞刻薄。当亡灵瘟疫席卷提瑞斯法林地北部时，阿加曼德家族没能保护他们的土地和劳工。代弗林是第一批倒下的人，他被复活成为了一只贪婪的天灾食尸鬼，他那疯狂而狂躁的呓语一直萦绕在通往阿加曼德磨坊的道路上。"},{t="壁炉架上的复仇",b="库勒曼·法席恩是住在布瑞尔的一名被遗忘者，他对整个阿加曼德家族怀有深沉而持久的怨恨。他认为正是他们未能在瘟疫来临时保护他的家人，因此要负直接责任。法席恩委托旅行者让代弗林安息并收集他的遗骸。法席恩想把代弗林的骨头展示在壁炉架上，享受着昔日的主人如今被践踏在脚下，化为尘埃和碎片的快感。"}},faq={{q="代弗林·阿加曼德生前是什么样的人？",a="代弗林是阿加曼德家族的幼子，该家族是富有的土地所有者，在提瑞斯法林地北部建立了阿加曼德磨坊。与他那脾气温和、宽肩阔背的哥哥瑟曼不同，代弗林身体虚弱、多病，且以脾气暴躁和言辞刻薄而臭名昭著。",al={"谁是代弗林","代弗林·阿加曼德背景故事","关于代弗林"}},{q="代弗林的遗骸是从哪里收集的？",a="它们取自代弗林·阿加曼德被天灾军团控制的尸体，该尸体位于阿加曼德磨坊以南，沿着蜿蜒穿过提瑞斯法林地的道路旁。",al={"代弗林在哪里","去哪找到代弗林","代弗林·阿加曼德位置"}},{q="为什么库勒曼·法席恩想要这些骨头？",a="库勒曼·法席恩痛恨阿加曼德家族，认为他们在瘟疫爆发期间抛弃了并辜负了他和他的亲人。他打算将代弗林的骨头陈列在布瑞尔的壁炉架上，作为复仇和满足的战利品。",al={"为什么法席恩想要遗骸","库勒曼·法席恩动机","为什么要收集阿加曼德的骨头"}},{q="代弗林是被遗忘者吗？",a="不。当代弗林屈服于瘟疫时，他的思想完全被天灾军团吞噬了。他像一只毫无思想的亡灵食尸鬼一样在磨坊附近的土地上徘徊，直到被消灭前一直在胡言乱语。",al={"代弗林是被遗忘者吗","代弗林是天灾军团吗"}}},fx={["0d9d3e5c"]={q="什么是代弗林的遗骸？",a="代弗林的遗骸是代弗林·阿加曼的骸骨，他是显赫的阿加曼家族的小儿子。代弗林死于亡灵瘟疫后，沦为毫无理智的天灾爪牙，在通往家族废弃磨坊的路边徘徊，直到被击杀并收殓。",al={"什么是代弗林的遗骸","代弗林的遗骸物品","代弗林的遗骸是谁的"}}},fp="16,290,15.464.0,23.452.0,31.284.0,42.152.0,43.245.0,31.184.0"}
P.entries["item:dirt-caked-pendant"] = {n="Dirt-Caked Pendant",s="Dirt-Caked Pendant 是被俘的兽人多格兰的一件私人物品。它交给了贫瘠之地的一名术士学徒，作为诱饵在奥格瑞玛召唤并束缚一名魅魔的关键情感信物。",h="Dirt-Caked Pendant 是被俘的兽人多格兰的一件私人物品。它交给了贫瘠之地的一名术士学徒，作为诱饵在奥格瑞玛召唤并束缚一名魅魔的关键情感信物。",kw={"噬魂者","dirt-caked pendant","多格兰","甘鲁尔·血眼","爱的礼物","魅魔","赞卡沙"},ang={["class:Warlock"]="对于受训中的术士来说，这个坠饰阐释了利用凡人的悲伤与奉献来驾驭扭曲虚空恶魔的黑暗艺术。",["race:Orc"]="这枚坠饰体现了多格兰苦涩的选择：他拒绝成为氏族和伴侣的残废负担，牺牲了自己的纪念品来换取一名战士最后的尊严。"},sec={{t="悲剧的信物",b="Dirt-Caked Pendant 在贫瘠之地的折磨期间一直被破碎的战士多格兰紧握在手中，代表了他对伴侣赞卡沙那难以言表的爱。由于身中剧毒且残废到无法治愈，多格兰放弃了这个坠饰，而不愿以负担的身份回到她身边，转而选择与俘虏战斗至死。这个沉重的纪念品被托付给一名术士，带回了奥格瑞玛，以便暗影裂口中的术士们可以利用其中蕴含的深沉心碎与奉献。"},{t="恶魔的诱饵",b="在暗影裂口的地下深处，甘鲁尔·血眼认出了这类圣物中蕴含的黑暗潜力。魅魔以凡人的渴望、浪漫和悲剧为食。通过将多格兰的坠饰清洗打磨至闪闪发光，术士大师将一个忠贞爱情的象征转化成了一个无法抗拒的灵魂诱饵，召唤出一只魅魔，并通过仪式战斗将其征服。"}},faq={{q="Dirt-Caked Pendant 是从哪里来的？",a="在贫瘠之地被囚禁的兽人战士多格兰，在你使用肯兹格拉的伤药让他恢复神智后，将这枚坠饰交给了你。",al={"坠饰来源","在哪里获得坠饰","谁给的坠饰"}},{q="这个坠饰与赞卡沙有什么联系？",a="赞卡沙是多格兰在奥格瑞玛的伴侣。多格兰选择交出坠饰并隐瞒自己还活着的事实，这样她就不会背负照顾一名残疾战士的重担。",al={"谁是赞卡沙","多格兰和赞卡沙","坠饰含义"}},{q="为什么甘鲁尔·血眼需要这个特定的坠饰？",a="魅魔会被强烈的凡人情感所吸引，特别是浪漫、心碎和奉献。一旦清洗干净，多格兰的坠饰就成为了将魅魔召唤到召唤法阵中的有力媒介。",al={"为什么需要坠饰","魅魔诱饵坠饰","甘鲁尔·血眼坠饰"}},{q="坠饰送到奥格瑞玛后会发生什么？",a="甘鲁尔·血眼会将坠饰清洗干净，并利用其诱惑力启动“束缚仪式”，将一只魅魔引诱到暗影裂口下方的法阵中，供术士击败并奴役。",al={"坠饰后续","坠饰用途"}}},fx={cbd86f91={q="什么是Dirt-Caked Pendant？",a="Dirt-Caked Pendant是一件蒙尘的私人信物，由被俘的兽人Dogran随身携带。它是与他的伴侣Zankaja有关的信物，承载着强烈的爱意与思念——这些正是术士准备引诱并奴役魅魔所需要的情感。",al={"什么是dirt-caked pendant","dirt-caked pendant背景","dirt-caked pendant是什么类型的物品"}}},fp="18,208,14.494.1,16.400.1,44.143.0,44.169.1,53.196.0,57.184.1"}
P.entries["item:disarming-colloid"] = {n="拆弹胶质",s="拆弹胶质是一种专门配制的化学药剂，旨在对抗瑟银炸药粉末的不稳定性。该药剂由湿地中的矮人阿什兰·暗石提供，是旨在防止巨石水坝遭受灾难性爆破的中和混合物中的关键稳定成分。",h="拆弹胶质是一种专门配制的化学药剂，旨在对抗瑟银炸药粉末的不稳定性。该药剂由湿地中的矮人阿什兰·暗石提供，是旨在防止巨石水坝遭受灾难性爆破的中和混合物中的关键稳定成分。",kw={"阿什兰·暗石","黑铁","拆弹胶质","爆炸物","辛德维尔","瑟银","巨石水坝","湿地"},ang={["profession:Engineering"]="工程师们会认出瑟银是一种能够造成巨大破坏的高级爆炸化合物，需要像这种胶质这样精确的化学对抗剂，而不是粗糙的机械拆除。",["race:Dwarf"]="发现针对巨石水坝的瑟银威胁到了矮人的工程杰作，也威胁到了上方洛克莫丹的安全。"},sec={{t="一种化学中和剂",b="当阿什兰·暗石分析了黑铁工兵留在洛克莫丹巨石水坝上的那种不同寻常的炸药粉末时，他立刻凭借其独特的气味和精细的银色晶体认出了它：瑟银。瑟银在完全干燥时并无害处，但一旦接触水分就会变得极具破坏性，这使其成为对潮湿的巨石水坝的生存威胁。为了在引爆发生前阻止这种反应，暗石提供了一种拆弹胶质。当这种胶质与三种特定的当地试剂——潜伏者的毒液、磨碎的莫格罗什水晶以及鳄鱼的眼泪——混合使用时，能有效中和瑟银复合物的爆炸特性。"}},faq={{q="拆弹胶质有什么用途？",a="它是解除瑟银炸药粉末引信所需的基础化学药剂。当与潜伏者的毒液、磨碎的莫格罗什水晶和鳄鱼的眼泪混合时，它能中和瑟银在遇水后会引起灾难性爆炸的剧烈反应。",al={"胶质用途","拆弹胶质的作用","瑟银拆解剂"}},{q="是谁制造或提供了这种胶质？",a="拆弹胶质由阿什兰·暗石提供，他是被派往驻守湿地丹莫德的一名爆炸专家，他识破了黑铁矮人炸毁巨石水坝的阴谋。",al={"谁提供了胶质","阿什兰的胶质"}},{q="为什么瑟银在湿地如此危险？",a="瑟银粉末在干燥时是化学惰性的，但接触水分会使其变得极其易爆。由于湿地到处都是水，而目标又是巨石水坝本身，任何受潮的瑟银都构成了即刻造成大规模破坏的威胁。",al={"为什么瑟银很危险","潮湿的瑟银"}},{q="这种胶质必须交给谁？",a="阿什兰·暗石指示，必须将胶质和关于瑟银阴谋的消息直接火速送往巨石水坝的总工程师辛德维尔那里。",al={"我应该把胶质带给谁","胶质上交"}}},fx={["6b4ad5ab"]={q="什么是拆弹胶质？",a="拆弹胶质是阿什兰·暗石调制的一种特殊中和剂。将它与另外三种强效试剂——潜伏者的毒液、碾碎的莫格罗什水晶和鳄鱼的眼泪混合后，就能安全地解除海蓝色炸药粉的剧烈化学反应，避免爆炸物受潮引爆。",al={"什么是拆弹胶质","拆弹胶质是什么","拆弹胶质背景"}},["1c3f9fc5"]={q="为什么需要拆弹胶质？",a="首席工程师亨德尔维尔急需这种胶质，以免洛克莫丹的巨石水坝发生灾难。黑铁破坏者已在水坝安放了不稳定的海蓝色炸药；若没有这种化学药剂来消解反应，炸药接触水后就可能炸毁水坝。",al={"为什么需要拆弹胶质","为什么需要这种胶质","谁需要拆弹胶质"}}},fp="17,315,22.679.0,35.277.0,37.212.0,46.279.0,38.152.0"}
P.entries["item:disarming-mixture"] = {n="拆弹剂",s="拆弹剂是一种由巨石水坝的总工程师亨德维尔调制的特制化学混合物。它被用于中和不稳定的瑟银炸药，以阻止黑铁矮人破坏这座阻挡洛克莫丹湖水的宏伟矮人建筑。",h="拆弹剂是一种由巨石水坝的总工程师亨德维尔调制的特制化学混合物。它被用于中和不稳定的瑟银炸药，以阻止黑铁矮人破坏这座阻挡洛克莫丹湖水的宏伟矮人建筑。",kw={"黑铁","拆弹剂","爆炸物","亨德维尔","洛克莫丹","炸药桶","瑟银","巨石水坝"},ang={["profession:Engineering"]="拆弹剂展示了实用的反工程技术，依靠快速化学中和使不稳定的瑟银炸药在不触发引爆的情况下失效。",["race:Dwarf"]="保护巨石水坝对于守护周边的山谷和低地至关重要，因此迅速使用这种中和剂对矮人的安全至关重要。"},sec={{t="一种化学中和剂",b="当黑铁矮人破坏者在巨石水坝的基座下安放了一枚重型瑟银炸药时，常规的拆除方法风险过大。在缺乏山地探险队员支援的情况下，总工程师亨德维尔结合了爆炸物专家阿什兰·暗石所提供的成分，调制出了拆弹剂，从而迅速中和了水下的爆炸物。当这种溶液直接搅拌进已安放的炸药桶中时，它会中和其中的反应性化合物，将一场灾难性的爆炸化为无害且嘶嘶作响的残渣。"}},faq={{q="拆弹剂是用来做什么的？",a="这种混合物旨在中和黑铁叛军安放在巨石水坝水下基座的大型瑟银炸药桶。",al={"拆弹剂的作用是什么","拆弹剂的用途","拆弹剂的目的"}},{q="谁制作了拆弹剂？",a="负责巨石水坝维护与防御的矮人工程师总工程师亨德维尔负责混合必要的成分来制作这种药剂。",al={"谁制作了拆弹剂","谁提供了拆弹剂","亨德维尔的混合物"}},{q="为什么一定要用这种混合物，而不是直接拆除炸弹？",a="瑟银粉末在干燥时是无害的，但一旦受潮，它就会爆发出巨大的威力。这种化学混合物能直接中和炸药桶内部的反应性粉末，在水坝水下将其消除，从而避免爆炸危险。",al={"为什么不正常拆除","为什么要用化学药剂处理炸弹","为什么要用拆弹剂"}}},fx={["8d78f743"]={q="什么是拆弹剂？",a="拆弹剂是一种专门用于中和不稳定爆炸物的化学混合物。将它混入海蓝色炸药或高级爆破粉后，它会与爆炸材料发生反应，从化学层面使其失效，让炸药只发出无害的嘶嘶声，而不会引发灾难性的爆炸。",al={"什么是拆弹剂","拆弹剂物品","关于拆弹剂"}}},fp="17,297,22.527.0,39.157.0,34.163.0,67.230.0"}
P.entries["item:divined-scroll"] = {n="使用过的占卜卷轴",s="使用过的占卜卷轴是一种附魔羊皮纸，银风避难所的暗夜精灵利用它来揭开灰谷水域动荡的源头。通过引导完整的元素护腕中残留的魔法，该卷轴可以揭示召唤它们的邪恶施法者的身份。",h="使用过的占卜卷轴是一种附魔羊皮纸，银风避难所的暗夜精灵利用它来揭开灰谷水域动荡的源头。通过引导完整的元素护腕中残留的魔法，该卷轴可以揭示召唤它们的邪恶施法者的身份。",kw={"灰谷","使用过的占卜卷轴","占卜卷轴","元素护腕","密斯特拉湖","银风避难所","维尔莉妮·星坠"},ang={["class:Mage"]="该卷轴基于召唤追踪的基本原理运作，证明了元素束缚总是带有其召唤者不可磨灭的奥术特征。",["race:NightElf"]="对于守卫灰谷的哨兵来说，像这样的占卜工具对于揪出那些奥术干预威胁到森林神圣水域的凡人污染者至关重要。"},sec={{t="追踪召唤者",b="密斯特拉湖被污染的水域长期困扰着守卫灰谷的哨兵。为了查明是谁在操纵盘踞在湖中的水元素，哨兵维尔莉妮·星坠为旅行者提供了一份未充能的占卜卷轴。通过直接从被击杀的元素身上收集完整的护腕并将其用作奥术试剂，金属中潜藏的束缚会渗透到羊皮纸中。生成的使用过的占卜卷轴会揭露幕后黑手——那个邪恶法师的魔法特征。"},{t="暴露的法师",b="一旦充能，使用过的占卜卷轴上的文字就会直接指向哨兵维尔莉妮想要寻找的凡人罪魁祸首：一个故意腐蚀原始林地水池的鲁莽法师。凭借羊皮纸上写下的启示，哨兵们能够计划报复，并派出侦察兵去追捕那些亵渎了她们神圣荒野的召唤者。"}},faq={{q="使用过的占卜卷轴有什么用？",a="使用过的占卜卷轴可以揭示正在灰谷的湖泊中召唤并束缚敌对水元素的施法者的身份，使哨兵维尔莉妮·星坠能够直接锁定罪魁祸首。",al={"使用过的占卜卷轴的作用","使用过的占卜卷轴的目的","为什么要制作使用过的占卜卷轴"}},{q="如何制作使用过的占卜卷轴？",a="通过将哨兵维尔莉妮·星坠提供的空白占卜卷轴施放在从密斯特拉湖周围被击败的水元素身上收集到的五个完整的元素护腕上，即可制作完成。",al={"如何制作使用过的占卜卷轴","制作使用过的占卜卷轴","如何获得使用过的占卜卷轴"}},{q="为什么占卜卷轴需要元素护腕？",a="这些护腕是束缚元素停留在凡世的物理纽带。它们残留的附魔提供了必要的魔法特征，使卷轴能够识别出召唤它们的特定法师。",al={"为什么需要完整的护腕","元素护腕的作用"}},{q="我应该把使用过的占卜卷轴交给谁？",a="将制作完成的使用过的占卜卷轴交给位于灰谷南部路边的银风避难所的哨兵维尔莉妮·星坠。",al={"在哪里交使用过的占卜卷轴","谁需要使用过的占卜卷轴"}}},fx={["155064fc"]={q="什么是使用过的占卜卷轴？",a="使用过的占卜卷轴是将占卜卷轴与从污染灰谷水域的水元素身上取得的完整护腕一同使用后得到的物品。卷轴吸收了这些护腕上残留的奥术痕迹，从而揭示与召唤并腐化水元素的特定召唤者有关的神秘信息。",al={"什么是使用过的占卜卷轴","使用过的占卜卷轴的用途","使用过的占卜卷轴有什么作用"}},ebb5ddd6={q="使用过的占卜卷轴来自哪里？是谁制作的？",a="你将哨兵维尔莉妮·星坠的占卜卷轴施法于数个完整的元素护腕上，亲手制作出使用过的占卜卷轴。护腕充当奥术试剂，使卷轴的占卜魔法能够聚焦并记录创造这些元素生物之人的魔法印记。",al={"谁制作了使用过的占卜卷轴","使用过的占卜卷轴的来源","使用过的占卜卷轴是如何制作的"}}},fp="14,288,20.507.0,16.364.1,36.202.0,34.186.0,58.222.0,37.124.0"}
P.entries["item:divining-scroll"] = {n="占卜卷轴",s="占卜卷轴是一张由银风避难所的哨兵维尔莉妮·星坠提供的附魔羊皮纸。它的魔法允许调查者追踪在灰谷泛滥的不自然水元素留下的魔法特征，从而找到它们的创造者。",h="占卜卷轴是一张由银风避难所的哨兵维尔莉妮·星坠提供的附魔羊皮纸。它的魔法允许调查者追踪在灰谷泛滥的不自然水元素留下的魔法特征，从而找到它们的创造者。",kw={"灰谷","使用过的占卜卷轴","占卜卷轴","元素护腕","银风避难所","维尔莉妮·星坠","水元素"},ang={["class:Mage"]="这卷轴展示了用于追踪奥术共鸣的经典占卜魔法，揭示出另一位奥术修行者正在神圣的卡多雷树林中滥用元素召唤。",["race:NightElf"]="对于保护灰谷的哨兵来说，这卷轴是揭露那些用不自然的腐化亵渎森林纯净水域的局外人的关键工具。"},sec={{t="追踪不自然的水元素",b="当腐化的水元素开始从灰谷纯净的池塘中涌现时，哨兵们意识到这种骚乱并非自然发生的。哨兵维尔莉妮·星坠获得了这张占卜卷轴，以查明责任人。通过将卷轴的魔法引导通过完好的元素护腕作为聚焦试剂，使用者可以提取召唤者的特征，将空白的羊皮纸转化为写明了罪魁祸首名字的“使用过的占卜卷轴”。"}},faq={{q="占卜卷轴有什么用途？",a="这卷轴旨在查明是谁制造了入侵灰谷的腐化水元素。使用完好的元素护腕作为焦点，羊皮纸会引导占卜魔法来读取施法者的光环并记录他们的身份。",al={"卷轴的作用","占卜卷轴的目的","为什么要使用占卜卷轴"}},{q="谁提供了占卜卷轴？",a="在调查被污染的水域期间，哨兵维尔莉妮·星坠在灰谷南部的银风避难所将卷轴提供给联盟调查员。",al={"谁给予占卜卷轴","在哪里获得卷轴","维尔莉妮·星坠的卷轴"}},{q="为什么需要完好的元素护腕？",a="大多数护腕在战斗中都破碎得无法辨认。少数完好的护腕仍保留着足够的来自召唤者的残余束缚魔法，足以作为占卜法术的合适奥术焦点。",al={"为什么需要护腕","完好的元素护腕","卷轴的试剂"}},{q="使用卷轴后会发生什么？",a="一旦在五个完好的护腕面前激活，该物品就会被消耗并变成“使用过的占卜卷轴”，揭示出一名叛逆法师正在故意将腐化元素召唤到森林的湖泊中。",al={"使用过的占卜卷轴","使用卷轴之后","它会变成什么"}}},fx={["51ca655d"]={q="什么是占卜卷轴？",a="占卜卷轴是一张用于揭示魔法来源的附魔羊皮纸。以完整的元素护腕作为试剂聚焦后，它的魔法可以追踪侵扰灰谷的水元素身上的束缚印记，并找出将它们召入森林纯净水域的叛逃施法者。",al={"什么是占卜卷轴","占卜卷轴背景","占卜卷轴物品"}},af5653e2={q="为什么需要占卜卷轴？",a="哨兵维尔莉妮·星坠需要这张卷轴，查明是谁在灰谷的湖泊与水池中不断召唤受腐化的水元素。没有卷轴的占卜魔法，暗夜精灵就无法锁定罪魁祸首，也无法阻止这片圣洁荒野继续遭到玷污。",al={"为什么需要占卜卷轴","为什么需要这张卷轴","占卜卷轴的用途"}}},fp="15,245,28.456.0,37.231.0,33.165.0,40.205.0,38.207.1"}
P.entries["item:dogran-s-pendant"] = {n="多格兰的坠饰",s="多格兰的坠饰是一件极具个人色彩的护身符，由受伤的兽人多格兰随身携带，并与他被迫离开伴侣赞卡沙的悲剧紧密相连。在奥格瑞玛术士的阴影圈子中，坠饰所蕴含的原始情感共鸣被用作诱饵和束缚魅魔的媒介。",h="多格兰的坠饰是一件极具个人色彩的护身符，由受伤的兽人多格兰随身携带，并与他被迫离开伴侣赞卡沙的悲剧紧密相连。在奥格瑞玛术士的阴影圈子中，坠饰所蕴含的原始情感共鸣被用作诱饵和束缚魅魔的媒介。",kw={"cleft of shadow","多格兰","多格兰的坠饰","甘鲁尔·血眼","奥格瑞玛","魅魔","束缚","赞卡沙"},ang={["class:Warlock"]="对于部落术士而言，多格兰的坠饰是证明对虚空掌控力并学习召唤魅魔仪式的核心护身符。",["faction:Horde"]="这枚坠饰象征着发生在贫瘠之地和杜隆塔尔那些不为人知的个人悲剧，它们与奥格瑞玛内秘密活动的术士结社有着密切的联系。"},sec={{t="心碎的媒介",b="多格兰的坠饰沉浸在个人的悲伤之中，它标志着一名兽人的悲惨命运，他与赞卡沙的爱恋被囚禁和严重的创伤所笼罩。对于大断崖的术士们来说，这种强烈的情感不仅仅是悲伤的残余，更是魔法的导管。魅魔这类恶魔贪婪地以爱、渴望和脆弱为食，这使得坠饰成为了将它们从扭曲虚空引诱到尼鲁·火刃的召唤法阵中的理想诱饵。"},{t="奴役与铭记",b="在甘鲁尔·血眼的指导下，一名有抱负的术士会使用该坠饰召唤恶魔，在战斗中将其制服，并证明自己完全掌控了其诱惑性的操纵手段。仪式结束后，护身符会被交还给甘鲁尔，再转交给赞卡沙，这作为一种庄严的提醒，告诫人们过度的自信和杂乱的情感会迅速让术士付出灵魂的代价。"}},faq={{q="多格兰的坠饰有什么用？",a="它是在大断崖的尼鲁·火刃帐篷内召唤魅魔的核心试剂。一旦恶魔被召唤并击败，坠饰必须归还给甘鲁尔·血眼。",al={"坠饰的用途","多格兰的坠饰怎么用","多格兰的坠饰任务"}},{q="为什么魅魔会回应这个坠饰？",a="魅魔以渴望、爱和激情为食并操纵它们。由于坠饰与多格兰和赞卡沙之间那段悲剧性的爱情紧密相连，其情感重量成为了跨越虚空、无法抗拒的诱饵。",al={"为什么魅魔需要坠饰","为什么坠饰能召唤恶魔","坠饰背景故事"}},{q="多格兰是谁？",a="多格兰是一位兽人，部落术士通过盲眼卡祖尔和肯兹格拉等接触渠道调查了他的被俘和受伤情况。他与赞卡沙有着深厚的爱恋，但拒绝让她照顾一个伤残之人，从而成为负担。",al={"谁是多格兰","多格兰的故事"}},{q="召唤仪式后坠饰会怎么样？",a="在击败被召唤的魅魔后，术士会将坠饰归还给甘鲁尔·血眼，这样他就能最终将遗物和答案带给赞卡沙。",al={"谁来接收坠饰","归还多格兰的坠饰"}}},fx={f4378ded={q="什么是多格兰的坠饰？",a="多格兰的坠饰是一件私人信物，与兽人多格兰及其爱人赞卡沙的悲惨命运息息相关。这枚小小的坠饰充满强烈的思念与悲伤，是黑暗魔法的强力媒介，能在术士的束缚仪式中将魅魔从虚空中引来。",al={"什么是多格兰的坠饰","多格兰的坠饰信息","多格兰的坠饰背景"}},bd6e6859={q="为什么需要多格兰的坠饰？",a="术士需要这枚坠饰，因为其中的情感共鸣能成为引诱魅魔的绝佳媒介，将恶魔直接引入召唤法阵并加以制服束缚。仪式结束后，甘鲁尔·血眼需要取回坠饰，以便将消息带给多格兰的伴侣赞卡沙。",al={"他们为什么想要多格兰的坠饰","谁想要多格兰的坠饰","多格兰的坠饰的用途"}}},fp="16,298,23.477.0,27.383.1,34.196.0,43.209.0,15.226.0,55.150.0"}
P.entries["item:dolanaar-delivery"] = {n="多兰纳尔的货物",s="“多兰纳尔的货物”是一份从幽影谷的德鲁伊营地寄往多兰纳尔村的草药包。它被托付给离开避风谷地的年轻旅行者，作为一个简单的差事，让他们与路途下方的旅店老板凯达米尔建立联系。",h="“多兰纳尔的货物”是一份从幽影谷的德鲁伊营地寄往多兰纳尔村的草药包。它被托付给离开避风谷地的年轻旅行者，作为一个简单的差事，让他们与路途下方的旅店老板凯达米尔建立联系。",kw={"奥达希尔","货物","多兰纳尔","草药","凯达米尔","伯萨努斯","幽影谷"},ang={["profession:Herbalism"]="这份货物凸显了奥达希尔周边采集的植物对于泰达希尔外围定居点供应的持续需求。",["race:NightElf"]="运送这个包裹标志着年轻的卡多雷走出幽影谷的保护枝叶，迈向更广阔世界的成长仪式。"},sec={{t="幽影谷的包裹",b="这个包裹在奥达希尔的阴影树丛中采集而成，里面装满了为多兰纳尔定居点收集的新鲜草药。伯萨努斯因为幽影谷德鲁伊之间的事务缠身，只能寄希望于前往南方的冒险新手将包裹安全送达旅店老板凯达米尔手中。"},{t="欢迎来到炉火旁",b="交付这份包裹会将旅行者直接带到多兰纳尔旅店的门槛前。凯达米尔怀着感激之情收下了货物，并借此机会提醒疲惫的过客，在他们深入泰达希尔之前，休息、安宁的心境以及旅店炉火所提供的庇护是多么必要。"}},faq={{q="“多兰纳尔的货物”里装的是什么？",a="包裹里装有在幽影谷收集的精选新鲜草药，旨在供应旅店老板凯达米尔和多兰纳尔旅店的顾客。",al={"里面有什么草药","多兰纳尔的货物的成分","包裹里有什么"}},{q="是谁寄送了这份货物？",a="伯萨努斯是一位在幽影谷处理德鲁伊事务的精灵，他准备了这个包裹，但无法抽出时间亲自前往南方。",al={"谁给予了货物","谁寄送了草药","伯萨努斯的货物"}},{q="谁在多兰纳尔接收这个包裹？",a="这份货物是直接送到旅店老板凯达米尔手中的，他负责管理多兰纳尔中心地区的公共旅店。",al={"我应该把草药带给谁","多兰纳尔的货物的接收者","凯达米尔的草药"}},{q="为什么伯萨努斯不能亲自递送包裹？",a="伯萨努斯有紧迫且未完成的事务需要与驻扎在奥达希尔附近的德鲁伊商议，迫使他寻找一位正沿着森林之路南下的过路冒险者。",al={"为什么伯萨努斯要留下","为什么伯萨努斯派我去"}}},fx={["432231a6"]={q="什么是多兰纳尔的货物？",a="多兰纳尔的货物是一包从幽影谷采集的新鲜草药，准备送往南边的多兰纳尔。这批货物由伯萨努斯托付给你，代表着日常贸易与补给从幽影谷隐蔽的树林运往规模更大的暗夜精灵社区。",al={"什么是多兰纳尔的货物","多兰纳尔包裹","幽影谷包裹"}},["7521a0db"]={q="旅店老板凯达米尔为什么需要多兰纳尔的货物？",a="旅店老板凯达米尔依靠幽影谷送来的新鲜草药为多兰纳尔的旅店补充物资。草药对于酿制药水、烹制滋补餐食，以及照料在泰达希尔寻求休息和疗伤的疲惫旅客与守卫都不可或缺。",al={"凯达米尔为什么需要草药","多兰纳尔草药的用途","为什么需要多兰纳尔的货物"}}},fp="17,266,24.310.0,21.305.0,37.144.0,24.144.0,37.110.0,52.171.0"}
P.entries["item:dragonmaw-war-banner"] = {n="龙喉战旗",s="龙喉战旗是驻扎在湿地的龙喉兽人所携带的集结旗帜。旗帜上印着他们氏族的图章，对于那些试图平息日益增长的兽人威胁的米奈希尔港矮人守卫来说，它们是战斗胜利的证明。",h="龙喉战旗是驻扎在湿地的龙喉兽人所携带的集结旗帜。旗帜上印着他们氏族的图章，对于那些试图平息日益增长的兽人威胁的米奈希尔港矮人守卫来说，它们是战斗胜利的证明。",kw={"龙喉","格瑞姆巴托","米奈希尔","尼克罗什","斯托菲","战旗","湿地"},ang={["faction:Alliance"]="从龙喉兽人手中夺走旗帜，可以在他们重建第二次战争期间所拥有的恐怖力量之前，削弱这个联盟的宿敌。",["race:Dwarf"]="对于卡兹莫丹的矮人来说，清除沼泽中的龙喉旗帜对于确保通往米奈希尔港的贸易走廊免受兽人突袭队的骚扰至关重要。"},sec={{t="持续威胁的象征",b="第二次战争结束后，随着对被奴役红龙控制权的丧失，龙喉氏族分崩离析。愤怒的巨龙反戈一击，将幸存者赶出了格瑞姆巴托，逼入东部的山丘。近来，残存的兽人在尼克罗什酋长的带领下重整旗鼓，在米奈希尔港东北部的营地中竖起了战旗。这些粗糙而令人望而生畏的旗帜不仅代表了他们挥之不去的反抗意志，也对沼泽地区的定居点构成了直接威胁。"},{t="征服的证明",b="驻扎在米奈希尔港的斯托菲队长指派联盟的冒险者深入沼泽营地，带回这些旗帜。这些从劫掠者、百夫长和白骨守卫身上缴获的战利品，向矮人守卫证实了龙喉氏族的营地正在被系统性地瓦解，从而阻止他们发动协同突袭。"}},faq={{q="为什么斯托菲队长需要这些旗帜？",a="斯托菲队长需要这些旗帜作为切实的证据，证明冒险者已经攻击了米奈希尔港东北部的龙喉营地，并确认了其兵力已被削减。",al={"为什么要收集旗帜","战旗的作用","斯托菲队长想要旗帜的原因"}},{q="谁携带龙喉战旗？",a="这些旗帜由散布在湿地各处营地中的各类龙喉作战单位携带，包括劫掠者、沼泽奔行者、百夫长、战术大师、暗影守卫、白骨守卫以及尼克罗什酋长本人。",al={"谁掉落龙喉战旗","到哪里获取战旗","哪些兽人拥有旗帜"}},{q="为什么龙喉兽人会出现在湿地？",a="第二次战争末期，龙喉氏族失去了对俘获的红龙的控制。获得自由的巨龙凶猛地捕杀它们曾经的主人，迫使幸存的兽人逃离了他们位于格瑞姆巴托的要塞，并溃散到湿地和周围的山区中。",al={"龙喉兽人为什么在这里","湿地龙喉历史","龙喉背景故事"}},{q="谁现在领导着龙喉氏族？",a="该氏族目前由尼克罗什酋长领导，他是前任酋长奈克罗斯的儿子。尼克罗什发誓要向那些反戈并杀害他父亲的红龙复仇。",al={"龙喉领袖","谁是尼克罗什","尼克罗什酋长"}}},fx={abf078db={q="什么是龙喉战旗？",a="这些战旗是湿地龙喉氏族的集结象征。旗帜上绘有兽人氏族的徽记；这个氏族曾因奴役红龙军团而恶名远扬。战旗彰显着他们的军威与不屈。对于米奈希尔港的联盟守军而言，夺取战旗证明一处营地已被攻破，其中的战士也已溃败。",al={"什么是龙喉战旗","龙喉战旗"}},["2c481a00"]={q="龙喉战旗来自哪里？是谁制作的？",a="它们由龙喉氏族的幸存兽人制作并携带。龙喉氏族失去格瑞姆巴托要塞，并逃离获得解放的红龙的怒火后，在米奈希尔港东北方的山地与沼泽中重新集结。在那里，他们的掠袭者、百夫长与萨满制作这些战旗，标示新占领的领地，并在酋长奈克罗什的率领下集结日渐壮大的战团。",al={"谁制作了龙喉战旗","龙喉战旗的来源","战旗来自哪里"}}},fp="20,264,29.519.0,17.360.0,46.180.0,38.217.0,43.268.0,33.172.0"}
P.entries["item:dried-seeds"] = {n="干枯的种子",s="干枯的种子是贫瘠之地十字路口的牛头人德鲁伊图加·符文图腾发给旅行者的毫无生气的果壳。它们被用作一种实验媒介，用于测试从贫瘠之地水域下方的裂隙中涌出的反常的生命力。",h="干枯的种子是贫瘠之地十字路口的牛头人德鲁伊图加·符文图腾发给旅行者的毫无生气的果壳。它们被用作一种实验媒介，用于测试从贫瘠之地水域下方的裂隙中涌出的反常的生命力。",kw={"贫瘠之地","冒泡的裂隙","十字路口","干枯的种子","死水绿洲","图加·符文图腾"},ang={["class:Druid"]="研究贫瘠之地各地奇怪植被生长的德鲁伊们会将这些死种子视为探测从大地中涌出的狂野、不受约束的能量的关键工具。",["faction:Horde"]="部落的冒险者们协助图加·符文图腾揭开改变贫瘠之地干燥土壤的生态谜团。"},sec={{t="种子与绿洲",b="在漫不经心的人眼中，这些枯萎的种子看起来完全干瘪，毫无生命迹象。但在图加·符文图腾手中，它们却是德鲁伊研究不可或缺的工具。由于对在遗忘之池发现的奇怪水下喷口很感兴趣，图加试图确认在东南方的死水绿洲下方是否存在类似的裂隙。通过将这些死种子浸入冒泡的裂隙中，调查者可以亲眼见证流经贫瘠之地各绿洲的神秘能量，这些能量拥有在不该有生命的地方催生生命的奇迹般能力。"}},faq={{q="干枯的种子有什么用途？",a="干枯的种子被用来测试死水绿洲深处冒泡裂隙所蕴含的神奇生命力。通过将这些死种子暴露在裂隙的水域中，你可以测试绿洲下方的反常能量是否能使植物恢复生机。",al={"干枯的种子用途","干枯的种子怎么用","干枯的种子目的"}},{q="谁提供了干枯的种子？",a="它们由图加·符文图腾交给冒险者。他是驻扎在贫瘠之地十字路口的牛头人德鲁伊，正在研究该地区突然出现的、非自然的大规模植被生长。",al={"谁给的干枯的种子","干枯的种子哪里来的"}},{q="用来测试的裂隙在哪里？",a="裂隙位于死水绿洲的水下，该绿洲位于贫瘠之地十字路口的东南方。",al={"干枯的种子种在哪里","死水绿洲裂隙位置","冒泡的裂隙干枯的种子"}},{q="种子接触裂隙后会发生什么？",a="图加要求将死种子放入冒泡的裂隙中并进行观察。它们对裂隙的反应就是他实验的结果，随着调查的深入，答案终将揭晓。",al={"种子会长出来吗","干枯的种子结果"}}},fx={aa7d6cee={q="什么是干枯的种子？",a="这些是完全枯死、无法发芽的植物种子，供你用于一项生态实验。它们自身早已枯萎，绝无自然发芽的可能，因此是理想的对照样本，可用来测试贫瘠之地绿洲中神秘冒泡的裂隙是否具有超自然的孕育生命之力。",al={"什么是干枯的种子","干枯的种子物品","干枯的种子背景"}},f2970934={q="图加·符文图腾为什么要你测试干枯的种子？",a="图加·符文图腾想要揭开贫瘠之地绿洲水下奇异裂隙的真正面目。他希望将毫无生机、无法发芽的种子直接放到死水绿洲的裂隙上，观察那里的水能否让种子生长，创造自然条件下完全不可能出现的生命奇迹。",al={"为什么要干枯的种子","为什么使用干枯的种子","图加的种子用途"}}},fp="11,247,23.583.1,34.261.0,29.181.0,36.129.0,55.167.1"}
P.entries["item:durnan-s-scalding-mornbrew"] = {n="德南的热酒",s="德南的热酒是一种刚倒出、滚烫的矮人饮品，是为寒脊山谷的德南·弗卡特准备的。由于这种饮料在寒冷的山间空气中热量流失极快，必须在变冷之前直接送到安威玛尔。",h="德南的热酒是一种刚倒出、滚烫的矮人饮品，是为寒脊山谷的德南·弗卡特准备的。由于这种饮料在寒冷的山间空气中热量流失极快，必须在变冷之前直接送到安威玛尔。",kw={"安威玛尔","寒脊山谷","丹莫罗","德南·弗卡特","晨酒","滚烫"},ang={["race:Dwarf"]="对于一位丹莫罗的矮人来说，让好啤酒或晨酒在山间霜雪中变凉，是莫大的罪过。"},sec={{t="与寒冷的赛跑",b="在寒脊山谷的刺骨严寒中，没有什么比得上一杯热气腾腾的新鲜晨酒了。当一位信使在为格瑞林·白须送酒时耽搁了时间，本该送给安威玛尔内德南·弗卡特的那杯新鲜饮料就有结冰的风险。德南特别要求他的酒要滚烫，因此只有短短几分钟的时间将这杯冒着热气的杯子沿着雪路送入山中大厅，以免它完全冷却。"}},faq={{q="这杯酒是给谁准备的？",a="这杯酒是给德南·弗卡特准备的，他是一位驻扎在寒脊山谷安威玛尔定居点内的矮人。",al={"谁喝晨酒","德南晨酒接收者","酒送到哪里"}},{q="为什么配送需要如此迅速？",a="丹莫罗的冰冷空气会迅速带走敞口杯中的热量。德南特别要求要滚烫的晨酒，不热或温热的酒根本无法满足他。",al={"为什么有时限","酒变冷了","为什么要快送晨酒"}},{q="配送的起点在哪里？",a="在信使意识到自己无法及时赶到熔炉大厅后，这杯饮料是在安威玛尔外格瑞林·白须的营地附近转交的。",al={"晨酒从哪里来","谁倒的酒"}},{q="德南收到杯子后会发生什么？",a="德南会立即放下安威玛尔内的工作，趁热细细品味这杯冒着热气的饮料。",al={"德南的反应","上交晨酒"}}},fx={["93832100"]={q="什么是德南的热酒？",a="这是一杯刚倒好的矮人热酒，专为安威玛尔的德南·弗卡特准备。它是用来抵御寒脊山谷刺骨山风的暖身饮品，必须趁热喝下才够味。",al={"什么是德南的热酒","德南的热酒物品","热酒饮品"}},c7c22f23={q="德南为什么想要热酒？",a="德南·弗卡特点了这杯热气腾腾的酒，打算在安威玛尔辛苦劳作后好好歇上一会儿。矮人对晨饮十分讲究，这样一杯醇厚的热酒要是凉了，整份享受就全毁了。",al={"德南为什么要热酒","为什么需要热酒","德南的酒有什么用"}}},fp="26,255,23.436.0,29.112.0,48.170.0,34.152.0,42.124.0"}
P.entries["item:durotar-tiger-fur"] = {n="杜隆塔尔虎皮",s="杜隆塔尔虎皮取自漫步在杜隆塔尔东南海岸外，热带回音群岛上的凶猛老虎。随着难民人口的不断增加，暗矛巨魔非常依赖这些皮毛来制作御寒毛毯、坚固的帐篷和耐用的护甲。",h="杜隆塔尔虎皮取自漫步在杜隆塔尔东南海岸外，热带回音群岛上的凶猛老虎。随着难民人口的不断增加，暗矛巨魔非常依赖这些皮毛来制作御寒毛毯、坚固的帐篷和耐用的护甲。",kw={"杜隆塔尔虎","杜隆塔尔虎皮","回音群岛","实用猎物","森金村","巨魔兽皮","维尔林·长牙"},ang={["class:Hunter"]="追踪回音群岛的老虎体现了经典的巨魔狩猎仪式，要求猎手拥有极大的耐心和伪装技巧，才能伏击这些潜伏在岛屿上的掠食者。",["race:Troll"]="对于暗矛巨魔来说，获取虎皮既是提醒他们在森金村为生存而进行的实际斗争，也是对他们痛失回音群岛这一正当家园的铭记。"},sec={{t="暗矛部族的重要资源",b="在拥挤的森金村定居点，资源永远捉襟见肘。暗矛巨魔在族人的生存需求与新家园脆弱的生态环境之间寻求平衡，特意让当地的老虎种群繁衍生息，直到日益增长的需求迫使他们进行捕猎。杜隆塔尔虎皮厚实而坚韧，经过精心鞣制后，可用于生产日常生存必需品，从基础的防护护甲到在季节更替时为族人保暖的毯子，应有尽有。"},{t="回音群岛狩猎",b="收集这些皮毛需要渡过开阔的水域前往回音群岛。这是一座位于杜隆塔尔南部的葱郁群岛，在巫医扎拉赞将暗矛巨魔驱逐之前，这里曾是他们的家园。除了要面对扎拉赞爪牙带来的危险，穿行于茂密植被中的猎手还必须应对老虎本身那种耐心而致命的捕食本性。像维尔林·长牙这样经验丰富的巨魔猎手经常说，他们需要在丛林灌木丛中一动不动地待上一整天，才能确保获得一张完整的兽皮。"}},faq={{q="杜隆塔尔虎皮是从哪里获得的？",a="它们是通过狩猎回音群岛上的杜隆塔尔虎获得的，该群岛位于杜隆塔尔东南海岸外。",al={"虎皮从哪里掉落","杜隆塔尔虎皮位置","如何获得虎皮"}},{q="为什么森金村的巨魔需要这些皮毛？",a="森金村的维尔林·长牙负责收集这些皮毛，为日益壮大的暗矛定居点提供毛毯、帐篷和防护皮甲，以确保族人在季节更替时不会受苦。",al={"为什么要收集虎皮","谁需要虎皮","实用猎物的用途"}},{q="为什么巨魔不过度捕杀老虎？",a="暗矛部族特意让老虎种群自然繁衍，只有当社区补给不足，且人口增加导致庇护所或衣物储备告急时，才会进行有限的捕杀。",al={"老虎保护","捕杀兽群"}}},fx={e997b985={q="什么是杜隆塔尔虎皮？",a="杜隆塔尔虎皮是从杜隆塔尔东南海岸外回音群岛上出没的野生老虎身上剥下的毛皮。这些皮结实、保暖且耐用，是森金村暗矛巨魔的重要原料，他们会将其制成日常必需品，为族人抵御严酷的环境。",al={"什么是杜隆塔尔虎皮","杜隆塔尔虎皮","这是什么毛皮"}},c85f7978={q="杜隆塔尔虎皮来自哪里？",a="这些毛皮是直接从回音群岛茂密灌木丛中潜行的杜隆塔尔虎身上剥下的。它们并非由工匠制作，而是由潜行者和斥候冒着风险，在森金村以南的海域猎取而来。",al={"杜隆塔尔虎皮的来源","虎皮来自哪里","谁制作杜隆塔尔虎皮"}}},fp="17,283,34.484.0,22.492.0,38.139.0,53.203.0,41.206.0"}
P.entries["item:duskbat-wing"] = {n="夜行蝙蝠翼",s="夜行蝙蝠翼是一种原材料，采集自丧钟镇周围阴影中飞行的皮革双翼蝙蝠。在这个资源匮乏的被遗忘者定居点，当地裁缝会将这些皮革状的附肢回收利用，制成坚固的临时护甲，供新复生的士兵使用。",h="夜行蝙蝠翼是一种原材料，采集自丧钟镇周围阴影中飞行的皮革双翼蝙蝠。在这个资源匮乏的被遗忘者定居点，当地裁缝会将这些皮革状的附肢回收利用，制成坚固的临时护甲，供新复生的士兵使用。",kw={"丧钟镇","夜行蝙蝠","夜行蝙蝠翼","新兵艾尔雷斯","食腐狼的爪子","被诅咒者","提瑞斯法林地"},ang={["profession:Tailoring"]="新兵艾尔雷斯展示了提瑞斯法所必需的简单粗犷的生存裁缝技术，利用坚韧的蝙蝠翅膀作为实用的皮革和布料替代品。",["race:Undead"]="对于刚觉醒的被遗忘者来说，收集这些翅膀是分配给他们的首批生存任务之一，以确保你在最初的战斗中不会散架。"},sec={{t="丧钟镇的简易防护",b="当新的亡灵从丧钟镇的土地中爬出来时，他们身上几乎只有破布和脆弱的骨头。被残留的亡灵天灾和充满敌意的野生生物包围，这些初生的被遗忘者必须竭尽所能搜集一切能找到的防护装备。暗影牧师萨维斯的助手新兵艾尔雷斯会将夜行蝙蝠翼与狼爪收集起来，为新复生的战士修补和加固衣物与护甲，以便他们在被送往野外作战之前得到保护。"}},faq={{q="夜行蝙蝠翼有什么用？",a="在丧钟镇，新兵艾尔雷斯将夜行蝙蝠翼和拾荒者的爪子作为原材料，为刚觉醒的被遗忘者新兵制作、修补和加固护甲与衣物。",al={"夜行蝙蝠翼用途","为什么收集夜行蝙蝠翼","夜行蝙蝠翼的目的"}},{q="夜行蝙蝠翼从哪里来？",a="它们是从提瑞斯法林地的丧钟镇村庄周围的小树林和山坡上出没的夜行蝙蝠和灰鬃夜行蝙蝠身上采集而来。",al={"哪里可以找到夜行蝙蝠翼","夜行蝙蝠翼来源","谁掉落夜行蝙蝠翼"}},{q="谁在丧钟镇请求这些翅膀？",a="在丧钟镇教堂内，负责照料伤员并在暗影牧师萨维斯的指导下制作装备的新兵艾尔雷斯，会要求新兵收集它们。",al={"谁需要夜行蝙蝠翼","上交夜行蝙蝠翼","夜行蝙蝠翼任务发放者"}},{q="为什么被遗忘者依靠蝙蝠部位来制作护甲？",a="丧钟镇几乎没有补给线或传统的制造业。当地的看守者必须从提瑞斯法当地的掠食者身上搜集坚韧的兽皮、毛皮和皮革状的蝙蝠翅膀，为即将投入战斗的新兵制作原始的防护服。",al={"为什么用蝙蝠翅膀做护甲","被遗忘者蝙蝠皮甲"}}},fx={d5eef861={q="什么是夜行蝙蝠翼？",a="夜行蝙蝠翼是从提瑞斯法林地闹鬼树林中飞舞的夜行蝙蝠身上剥下的皮革翅膀。在制成品稀缺的丧钟镇，这些翅膀是重要的原料。被遗忘者中的裁缝和看护者会将蝙蝠皮缝制、鞣制成耐用的衣物和轻甲，供新近苏醒的亡灵穿戴，然后再派他们去面对林地中的危险。",al={"什么是夜行蝙蝠翼","夜行蝙蝠翼物品","关于夜行蝙蝠翼"}}},fp="12,287,35.494.0,32.176.0,33.149.0,39.159.0,48.251.0"}
P.entries["item:dusky-crab-cakes"] = {n="黑蟹蛋糕",s="黑蟹蛋糕是厨师格鲁奥在夜色镇精心烹制的一道美味佳肴，专门用来满足基特斯那迫切的饥饿感。这种当地特产风味浓郁，对于饥肠辘辘的基特斯来说，简直是一顿绝佳的餐点。",h="黑蟹蛋糕是厨师格鲁奥在夜色镇精心烹制的一道美味佳肴，专门用来满足基特斯那迫切的饥饿感。这种当地特产风味浓郁，对于饥肠辘辘的基特斯来说，简直是一顿绝佳的餐点。",kw={"夜色镇","暮色森林","黑蟹蛋糕","格鲁奥","基特斯","蜘蛛腿"},ang={["profession:Cooking"]="格鲁奥的肉饼展示了一位富有创意的厨师是如何利用暮色森林中可获取的原料制作出风味独特的当地特产。"},sec={{t="值得怀疑的美味",b="在昏暗的暮色森林里，新鲜的补给十分稀缺，厨师们必须利用这片黑暗森林所产出的任何肉类来凑合。当惊恐不安的流浪汉基特斯忍受着饥饿的折磨时，厨师格鲁奥便会烹制一批他的招牌“蟹”肉饼。对于外人来说，这道菜看起来像是普通的炸鱼饼，但格鲁奥的秘制配料却一点也不诱人：那是暮色森林里巨型蜘蛛那充满筋络和粘液的腿。基特斯狼吞虎咽地吃下了这些肉饼，完全没有意识到他吃下去的到底是什么。"}},faq={{q="黑蟹蛋糕到底是用什么做的？",a="厨师格鲁奥对他的招牌菜配方守口如瓶。只有在为他在暮色森林收集补给时，人们才会发现其秘密配料。",al={"蟹肉饼配料","黑蟹蛋糕里有什么","蜘蛛肉"}},{q="谁会吃黑蟹蛋糕？",a="这些肉饼是为基特斯准备的，他是一个躲在乌鸦岭的焦虑男人，经常抱怨肚子饿得咕咕叫。",al={"谁吃了蟹肉饼","这是给谁准备的","基特斯的食物"}},{q="基特斯对这些肉饼反应如何？",a="基特斯饿极了，他开心地吃掉了肉饼，根本没有质疑配方，只是庆幸它们填饱了肚子。",al={"基特斯的反应","基特斯喜欢这些肉饼吗"}},{q="谁烹制了黑蟹蛋糕？",a="夜色镇Scarlet Raven Tavern的驻店厨师格鲁奥负责用收集来的补给烹制这道菜。",al={"谁制作了蟹肉饼","厨师格鲁奥","夜色镇厨师"}}},fp="16,208,23.544.1,43.137.0,30.128.0,36.119.0,31.121.0"}
P.entries["item:dust-devil-debris"] = {n="尘魔的残骸",s="尘魔的残骸是由那些游荡在西部荒野的狂暴空气灵体留下的旋转沙砾和元素残余组成的。法师们将这些带有能量的颗粒视为魔法试剂，利用其空气精华来为羊皮纸附魔，并将传信法术绑定到卷轴上。",h="尘魔的残骸是由那些游荡在西部荒野的狂暴空气灵体留下的旋转沙砾和元素残余组成的。法师们将这些带有能量的颗粒视为魔法试剂，利用其空气精华来为羊皮纸附魔，并将传信法术绑定到卷轴上。",kw={"科林·马伦","尘魔的残骸","尘魔","传信法术","卷轴","暴风城","西部荒野"},ang={["class:Mage"]="尘魔的残骸展示了元素残余如何被引导至实用的抄写和通讯法术中，将原始的元素混乱与精炼的奥术纪律连接起来。"},sec={{t="纺气成纸",b="西部荒野那干旱的平原变得越来越躁动不安，遭受着被称为尘魔的狂暴旋风的侵扰。当这些活生生的风暴被击败后，它们会坍塌成一堆带有电荷的尘土和沙砾，也就是尘魔的残骸。这种残留物并非普通的泥土，而是保留了赋予其生命的元素漩涡的一丝痕迹。像暴风城科林·马伦这样的奥术修行者十分看重这种用于特殊巫术的材料。通过将这些沙砾注入附魔墨水和羊皮纸中，巫师可以将空气传信法术绑定在卷轴上，从而实现王国境内的远程通讯。"}},faq={{q="尘魔的残骸有什么用途？",a="居住在暴风城Mage Quarter的法师科林·马伦需要这种元素残骸来制作一种特殊的传信卷轴。尘土中残留的元素能量使他能够将微妙的通讯魔法印刻在纸上。",al={"尘魔的残骸用途","为什么要收集尘魔的残骸","残骸的目的"}},{q="这种残骸来自哪里？",a="它从尘魔的遗骸中回收，这些尘魔是游荡在西部荒野贫瘠农田和道路上的敌对空气元素生物。",al={"在哪里寻找残骸","尘魔掉落物","西部荒野残骸"}},{q="为什么尘魔很危险？",a="它们是游荡在西部荒野的敌对空气元素生物。科林·马伦警告说，收集它们的残骸意味着要面对这些危险的生物。",al={"为什么西部荒野有元素生物","西部荒野尘魔的起源"}},{q="科林·马伦是谁？",a="科林·马伦是一位在暴风城Mage Quarter工作的男性人类法师。他运用自己的奥术专业知识为同行和好奇的研究者制作附魔卷轴和魔法组件。",al={"科林·马伦","谁需要残骸"}}},fp="17,167,23.468.0,35.163.0,33.128.0,30.141.0,21.189.0"}
P.entries["item:dwarven-tinder"] = {n="矮人火绒",s="矮人火绒是一种特制的易燃物质，由湿地的联盟军队所使用。它被分发给破坏者，任务是焚毁龙喉氏族的攻城器械，以免它们被用来攻击米奈希尔港。",h="矮人火绒是一种特制的易燃物质，由湿地的联盟军队所使用。它被分发给破坏者，任务是焚毁龙喉氏族的攻城器械，以免它们被用来攻击米奈希尔港。",kw={"投石车","龙喉","矮人火绒","米奈希尔港","奈克罗什","破坏","湿地"},ang={["faction:Alliance"]="由于丹奥加兹山口战事吃紧，在敌人的战争机器到达米奈希尔港之前将其烧毁，对于维持联盟这一主要沼泽港口的存续至关重要。",["race:Dwarf"]="矮人工程师和侦察兵深知可靠的引火物的重要性，特别是在湿地这种终年潮湿、雨水连绵的沼泽地区。"},sec={{t="破坏龙喉氏族",b="当联盟侦察兵发现酋长奈克罗什在龙喉营地内建造了重型投石车时，米奈希尔港面临着迫在眉睫的危机。由于丹奥加兹激烈的战斗导致通往南方的援军被切断，守军无法在长期的围攻中幸存。解决办法就是先发制人的破坏行动。矮人火绒被提供给深入兽人领地的志愿者，它能迅速被火星点燃，产生的火焰足以在几分钟内烧毁加固过的木制攻城器械。"}},faq={{q="矮人火绒的用途是什么？",a="矮人火绒用于点燃并摧毁龙喉氏族在湿地建造的攻城投石车，以防止他们对米奈希尔港发动炮火袭击。",al={"矮人火绒用途","为什么要使用矮人火绒","矮人火绒的作用"}},{q="为什么要烧毁投石车而不是俘获它们？",a="米奈希尔港的驻军人数处于绝对劣势，且由于丹奥加兹的封锁，无法得到来自铁炉堡的增援。守军没有足够的人力去夺取或回收深入龙喉氏族敌对领地内的重型攻城器械，因此摧毁它们是唯一可行的防御手段。",al={"为什么要摧毁投石车","为什么不夺取攻城器械"}},{q="谁准备了这种火绒？",a="这种火绒由驻扎在米奈希尔港的矮人守军提供，专为军事破坏行动中的快速、可靠引燃而准备。",al={"谁制作了火绒","矮人火绒的来源"}}},fx={["5fa2c489"]={q="什么是矮人火绒？",a="矮人火绒是由米奈希尔港的守军提供的一种易燃引火物，经过特殊处理。矮人民兵将它制成只需一星火花就能迅速点燃的引火物，确保笨重的木制战争机器能在潮湿的湿地中迅速、彻底地燃烧起来，不给敌军反应的机会。",al={"什么是矮人火绒","矮人火绒物品","关于矮人火绒"}},f9865b90={q="为什么现在需要矮人火绒？",a="奈克罗什麾下的龙喉兽人建造了巨型攻城投石车，企图摧毁米奈希尔港。丹奥加兹战况激烈，铁炉堡的援军无法抵达，米奈希尔港经受不住长时间的围攻。你必须用这些火绒潜入龙喉兽人的营地，把他们的战争机器烧成灰烬，赶在他们发起进攻之前完成任务。",al={"为什么要矮人火绒","为什么需要矮人火绒","为什么需要火绒"}}},fp="14,245,24.517.0,32.161.0,49.289.0,25.158.0"}
P.entries["item:ear-of-balgaras"] = {n="巴尔加拉斯的耳朵",s="巴尔加拉斯的耳朵是邪恶的黑铁术士巴尔加拉斯之死的残酷证明，他曾率军突袭了丹莫德。这件从胆小指挥官的尸体上取下的战利品，为守卫湿地北部的铁炉堡登山者们带来了慰藉。",h="巴尔加拉斯的耳朵是邪恶的黑铁术士巴尔加拉斯之死的残酷证明，他曾率军突袭了丹莫德。这件从胆小指挥官的尸体上取下的战利品，为守卫湿地北部的铁炉堡登山者们带来了慰藉。",kw={"邪恶的巴尔加拉斯","黑铁矮人","丹莫德","巴尔加拉斯的耳朵","布莱德·长须","萨多尔大桥","湿地"},ang={["class:Warlock"]="巴尔加拉斯躲在暗处施展暗影和邪能魔法，因此击败他就像是除掉一个给北部道路带来灾难的流窜作恶者。",["race:Dwarf"]="对于铁炉堡的矮人来说，取得这只耳朵是为了替在萨多尔大桥破坏事件中惨死的同胞们讨回血债。"},sec={{t="冷酷的战利品",b="当黑铁入侵者破坏了萨多尔大桥并消灭了当地的矮人驻军后，丹莫德化为一片废墟。他们在战场上的指挥官是邪恶的巴尔加拉斯，一个躲在暗处指挥军队、回避正面战斗的阴险术士。对于驻扎在废墟之外、身为山丘之王军官的布莱德·长须来说，正义需要这个头目倒下的确凿证据。割下巴尔加拉斯的耳朵提供了绝对的证明，表明这名术士在北部边境的恐怖统治已经终结。"},{t="为阵亡者讨回公道",b="丹莫德的沦陷让布莱德失去了他的兄弟以及数十名在西桥坍塌时丧生的英勇士兵。上交这名术士的耳朵并不能修复破碎的桥梁或复活阵亡者，但却能瓦解分散在湿地北部的黑铁残部。没有了巴尔加拉斯的指挥，剩下的袭击者在铁炉堡的斥候们看来，要在南部派来新的指挥官之前将其控制住就容易多了。"}},faq={{q="谁是邪恶的巴尔加拉斯？",a="邪恶的巴尔加拉斯是一名黑铁矮人术士，他指挥的战团袭击了丹莫德并摧毁了萨多尔大桥的西桥。他以怯懦而臭名昭著，总是派遣一波波士兵去送死，而自己则躲藏起来，避开联盟的巡逻队。",al={"谁是巴尔加拉斯","巴尔加拉斯的背景故事","邪恶的巴尔加拉斯"}},{q="为什么布莱德·长须特别想要他的耳朵？",a="布莱德·长须需要无可辩驳的证据来证明这个行踪诡秘的术士确实已被击杀。一只割下的耳朵是边境上经典的战利品，它既能验证任务完成，又不需要把整具尸体拖回矮人营地。",al={"为什么要耳朵","为什么要割下耳朵","布莱德的证明"}},{q="巴尔加拉斯死后，黑铁矮人会怎样？",a="失去了狡诈的领袖，丹莫德的黑铁残部失去了凝聚力。虽然他们依然徘徊在废墟之中，但布莱德相信他们已经分崩离析，联盟完全可以在铁炉堡的敌人派来继任指挥官之前处理掉他们。",al={"巴尔加拉斯死后发生了什么","丹莫德的黑铁矮人"}}},fx={a51409b4={q="巴尔加拉斯的耳朵来自哪里？",a="这只被割下的耳朵来自污秽者巴尔加拉斯，一个在湿地北部活动的懦弱黑铁术士。巴尔加拉斯统领着袭击丹莫德、摧毁萨多尔大桥西侧桥段的敌对矮人，但他更愿意躲藏起来，派手下去战斗。",al={"巴尔加拉斯的耳朵来源","哪里能获得巴尔加拉斯的耳朵","谁有巴尔加拉斯的耳朵"}}},fp="15,257,13.544.0,22.468.0,26.262.0,54.246.0,53.265.0"}
P.entries["item:ebonlocke-s-response-to-solomon"] = {n="埃伯洛克的回信",s="《埃伯洛克的回信》是一封由夜色镇镇长艾尔罗·埃伯洛克公爵亲笔写下的正式信函。这封信被送回湖畔镇，断然拒绝了赤脊山对于守夜人军事援助的绝望请求。",h="《埃伯洛克的回信》是一封由夜色镇镇长艾尔罗·埃伯洛克公爵亲笔写下的正式信函。这封信被送回湖畔镇，断然拒绝了赤脊山对于守夜人军事援助的绝望请求。",kw={"夜色镇","暮色森林","埃伯洛克","湖畔镇","信函","信使","守夜人","赤脊山","所罗门"},ang={["faction:Alliance"]="这封信揭示了联盟腹地的彻底崩溃：赤脊山、暮色森林和西部荒野都已被暴风城的王室所抛弃。"},sec={{t="痛苦的拒绝",b="面对黑石兽人的入侵，湖畔镇的所罗门镇长在暴风城无视了他的请愿后，转而向暮色森林寻求增援。艾尔罗·埃伯洛克公爵的回复言辞激烈且毫不妥协。埃伯洛克指出，守夜人的存在仅仅是因为当腐蚀性的魔法最初笼罩这片森林时，暴风城抛弃了夜色镇。如果抽调镇上的防卫力量去援助赤脊山，将使暮色森林陷入毫无防备的状态，这会导致该地区在民兵到达林边空地之前就已经沦陷于邪恶之中。"},{t="摇摇欲坠的边境",b="当所罗门收到这封信时，他深感震撼。随着暴风城军队撤出西部荒野，皇家卫队也缺席夜色镇，整个王国的南部边境已被任其自生自灭。所罗门并没有忽视埃伯洛克的愤怒，而是从中察觉到了一种可怕的模式：王室突然对偏远领地的忽视，暗示着暴风城的权力最高层存在背叛行为。"}},faq={{q="什么是《埃伯洛克的回信》？",a="这是一封由夜色镇的艾尔罗·埃伯洛克公爵写给湖畔镇所罗门镇长的密封信函。在信中，埃伯洛克拒绝派遣守夜人去保卫赤脊山，并解释说暮色森林本身也仅仅是在勉强抵御着梦魇。",al={"埃伯洛克的回信","埃伯洛克的回应","给所罗门的信"}},{q="为什么夜色镇不向湖畔镇提供援助？",a="夜色镇没有自己的皇家军队。守夜人完全是由当地志愿者组成的，因为暴风城已经抛弃了该地区。埃伯洛克公爵警告说，如果他的卫兵离开，夜色镇在他们走出森林之前就会被亡灵和邪恶生物淹没。",al={"为什么守夜人不提供援助","为什么夜色镇拒绝","埃伯洛克拒绝所罗门"}},{q="所罗门镇长对这封信有何反应？",a="所罗门镇长感到震惊和不安。得知皇家卫队抛弃了夜色镇——正如军队撤出西部荒野一样——这让他相信暴风城的领导层正遭受着某种阴谋或背叛的瘫痪。",al={"所罗门的反应","所罗门说了什么"}},{q="这封信是谁写的？",a="这封信是由夜色镇四面楚歌的镇长，同时也是夜色镇议会的领导人——艾尔罗·埃伯洛克公爵亲笔写下的，他负责监管该镇的防御工作。",al={"埃伯洛克是谁","埃伯洛克公爵"}}},fx={de19eb29={q="所罗门镇长为什么想要埃伯洛克的回信？",a="所罗门镇长急需援军来抵御黑石兽人，保卫湖畔镇。暴风城多次无视他的军事援助请求后，他向夜色镇求助，希望艾尔罗·埃伯洛克公爵能派出夜色镇卫队。所罗门急切地等待这封信，想知道暮色森林是否会派来援助，却发现夜色镇和赤脊山一样，孤立无援、处境艰难。",al={"所罗门为什么需要信件","为什么要送交埃伯洛克的回信","为什么把回信送给所罗门"}}},fp="31,225,16.500.0,22.425.1,40.249.0,43.286.0,48.223.1,22.153.0"}
P.entries["item:echeyakee-s-hide"] = {n="埃其亚基的皮",s="埃其亚基的皮是取自贫瘠之地的一头名为“白雾”的传奇白狮的苍白皮毛。这块皮毛被牛头人尊为仁慈与死亡的化身，也是猎人向十字路口的瑟格拉·黑棘证明自身实力的凭证。",h="埃其亚基的皮是取自贫瘠之地的一头名为“白雾”的传奇白狮的苍白皮毛。这块皮毛被牛头人尊为仁慈与死亡的化身，也是猎人向十字路口的瑟格拉·黑棘证明自身实力的凭证。",kw={"贫瘠之地","十字路口","埃其亚基","埃其亚基的皮","瑟格拉·黑棘","白狮","白雾"},ang={["class:Hunter"]="猎取这只草原顶级潜行者的皮毛，是渴望掌握荒野奥秘的部落追踪者们早期的成年礼之一。",["race:Tauren"]="对于牛头人来说，猎杀埃其亚基是一场神圣的仁慈与潜行考验，其目的是为了向白雾迅捷的精神致敬，而非单纯为了征服。"},sec={{t="白雾的战利品",b="在牛头人语中，埃其亚基意为“白雾”。这头猛兽因其隐秘的白色皮毛以及极快的捕猎速度在草原狮群中赢得了这个称号，它总能在猎物感受到恐惧或痛苦之前就终结其生命。想要获得这头野兽的皮毛，需要在十字路口东北方的巨型科多兽骨堆附近，使用一把祭祀号角召唤这只行踪诡秘的猫科动物。将这张皮献给瑟格拉·黑棘，不仅是为了证明武艺，更是为了向这头猛兽所代表的宁静、仁慈的终结致敬。"}},faq={{q="埃其亚基的皮来自哪里？",a="这张皮是通过击杀埃其亚基获得的，这头白狮栖息在贫瘠之地十字路口东北方的巨型科多兽骨架之间。玩家必须使用瑟格拉·黑棘提供的埃其亚基的号角来将其召唤出来。",al={"如何获得埃其亚基的皮","埃其亚基的皮获取方式","埃其亚基的皮位置"}},{q="谁需要埃其亚基的皮？",a="常驻十字路口的兽人女猎手瑟格拉·黑棘，会派遣部落的新晋猎人去追踪这只大猫，并带回它的皮毛，以证明他们与荒野之间的联系。",al={"谁收埃其亚基的皮","埃其亚基的皮交任务","谁需要埃其亚基的皮"}},{q="埃其亚基这个名字是什么意思？",a="在牛头人语言中，埃其亚基意译为“白雾”。这个名字是为了赞颂这只猫科动物苍白的皮毛，并表达人们对它如薄雾般掠过草原，杀戮时却不造成持久恐惧或痛苦的信仰。",al={"埃其亚基名字翻译","埃其亚基的含义","牛头人名字埃其亚基"}}},fx={["718fd4d1"]={q="什么是埃其亚基的皮？",a="这是埃其亚基的毛皮。埃其亚基是一头备受尊崇的白色雄狮，牛头人称它为白雾。埃其亚基被视为贫瘠之地草原猫科动物之王，狩猎时隐匿无踪、迅捷无比，被认为既是仁慈，也是死亡。取得它的皮，便是猎人拥有召唤并战胜这头传奇猛兽的技艺与勇气的实物证明。",al={"什么是埃其亚基的皮","埃其亚基的皮","白狮皮"}}},fp="16,250,19.499.0,38.216.0,27.183.0,34.217.0"}
P.entries["item:egalin-s-grimoire"] = {n="埃加林的魔典",s="埃加林的魔典是一本珍贵的奥术典籍，详细记载了召唤和奴役虚空行者所需的基础仪式。它由一位术士大师亲笔撰写，是幽暗城被诅咒者神殿中一本必不可少的教学教材。",h="埃加林的魔典是一本珍贵的奥术典籍，详细记载了召唤和奴役虚空行者所需的基础仪式。它由一位术士大师亲笔撰写，是幽暗城被诅咒者神殿中一本必不可少的教学教材。",kw={"凯伦丁·哈加尔","虚空生物","埃加林","埃加林的魔典","佩琳","被诅咒者神殿","虚空行者"},ang={["class:Warlock"]="埃加林的魔典包含了将虚空行者从虚空中拉出并使其听命于你的精确技巧，这是任何术士修行者必经的关键仪式。",["race:Undead"]="找回这本书可以阻止狂热的血色十字军占有这件从幽暗城修行者手中直接窃取的强大魔法神器。"},sec={{t="大师之作",b="这本魔典由召唤师大师埃加林所写，详细阐述了将虚空生物从虚空中拉出的精细且危险的过程。埃加林以能毫不费力地驾驭虚空行者而闻名于术士圈，这种能力也传给了他的学生，包括凯伦丁·哈加尔。若是没有书中记载的特定咒语和引导方法，毫无准备的召唤师就有可能被他们召唤出的实体撕成碎片。"},{t="血色十字军的盗窃",b="这本魔典被一名名为佩琳的血色十字军特工从被遗忘者术士手中偷走，并藏在提瑞斯法林地西部的一座塔楼的箱子里。尽管狂热分子对黑暗魔法深恶痛绝，但盗贼似乎并不清楚这本书的真正价值，只把它当作缴获的异端战利品，直到被寻求掌握虚空力量的被遗忘者学徒找回。"}},faq={{q="埃加林是谁？",a="埃加林是一位才华横溢的术士，也是凯伦丁·哈加尔的导师。他被人们铭记是因为他是他们之中第一个召唤出虚空行者的人，并且能极其轻松地驾驭混乱实体。",al={"埃加林是谁","埃加林背景故事","谁写的魔典"}},{q="为什么埃加林的魔典如此危险？",a="这本书包含了召唤虚空行者所需的咒语和引导方法。如果术士在没有完全掌握这些说明的情况下尝试仪式，召唤出的虚空实体会将他们撕成碎片。",al={"魔典有什么用","虚空行者典籍的危险性","为什么危险"}},{q="血色十字军是如何得到这本书的？",a="一名叫佩琳的血色十字军特工设法从被遗忘者术士手中偷走了这本典籍。他将其锁在提瑞斯法林地西部一座十字军瞭望塔里的箱子中，似乎并不了解它真正的魔法价值。",al={"谁偷了书","佩琳魔典","为什么十字军会有这本书"}},{q="谁需要找回这本魔典？",a="居住在幽暗城下层被诅咒者神殿里的术士训练师凯伦丁·哈加尔需要这本魔典来教导新学徒如何召唤和奴役虚空行者。",al={"谁想要这本魔典","谁回收埃加林的魔典","凯伦丁·哈加尔的书"}}},fx={cc7caae6={q="什么是埃加林的魔典？",a="埃加林的魔典是一本陈旧而专业的法术书，记载着召唤混沌彼岸生物的秘诀。书中详细记述了召唤并束缚虚空行者所需的复杂过程和法术构造——这种生物足以将毫无防备的召唤者撕成碎片。",al={"什么是埃加林的魔典","埃加林的书","什么是魔典"}},["29951967"]={q="埃加林的魔典来自哪里？是谁写的？",a="这本典籍由埃加林执笔。他是幽暗城术士中的大师，以首位召唤出虚空行者而闻名。埃加林曾教导过其他杰出的术士，包括凯伦丁·哈加尔；凯伦丁十分敬仰这位导师驾驭召唤出的恐怖生物时那举重若轻的本领。",al={"谁写了埃加林的魔典","埃加林的书的来源","谁制作了埃加林的魔典"}},c5f2fef1={q="为什么需要埃加林的魔典？",a="诅咒神殿的术士需要这本魔典来指导学徒召唤虚空行者。血色十字军的一名特工佩琳偷走魔典后将它藏在附近的一座高塔中，因此找回典籍至关重要，既能防止危险的仪式落入敌手，也能将重要知识归还被遗忘者。",al={"他们为什么想要埃加林的魔典","谁想要魔典","为什么要找回埃加林的书"}}},fp="17,232,15.458.0,17.409.1,15.206.0,38.215.0,41.221.0,33.177.0"}
P.entries["item:electropeller"] = {n="导电器",s="“电驱推进器”是一种由侏儒发明家维兹班恩·曲针设计的专业机械组件。其目的是为了驱动一个爆炸性的水禽诱饵，但在一场倒霉的夜间外出行动中，一整袋这类装置遗失在了黑海岸的淡水河流中。",h="“电驱推进器”是一种由侏儒发明家维兹班恩·曲针设计的专业机械组件。其目的是为了驱动一个爆炸性的水禽诱饵，但在一场倒霉的夜间外出行动中，一整袋这类装置遗失在了黑海岸的淡水河流中。",kw={"奥伯丁","壁泉河","黑海岸","鸭子诱饵","电驱推进器","急弯河","维兹班恩·曲针"},ang={["profession:Engineering"]="电驱推进器是典型的侏儒装置：雄心勃勃、动力驱动且充满危险，它是为一个爆炸鸭子诱饵设计的，但在还没经过正规测试之前就掉进了河里。",["race:Gnome"]="维兹班恩·曲针延续了侏儒那将狂野的技术雄心与令人困惑的冒险经历相结合的光荣传统，乐呵呵地请求路过的垂钓者打捞他深夜实验的残骸。"},sec={{t="河岸边的意外",b="侏儒工程学要求精准，但其发明者却并非总是那么循规蹈矩。住在奥伯丁的古怪侏儒维兹班恩·曲针，设计了这种电驱推进器，作为一种实验性、自动推进的爆炸鸭子诱饵的动力组件。在一次多喝了几杯后的黑海岸水道考察中，曲针失去了知觉，几小时后醒来时头发被烧焦，背包也空空如也。他的一整袋电驱推进器都掉进了淡水流中，使得这些零件散落在黑海岸的河流和湖泊里，直到被耐心的垂钓者捞起。"}},faq={{q="电驱推进器有什么用？",a="电驱推进器是由维兹班恩·曲针设计的电动推进装置。他发明这些东西是专门为了驱动他正在黑海岸开发的一种实验性、自动推进的爆炸鸭子诱饵。",al={"电驱推进器用途","电驱推进器的功能","为什么是鸭子诱饵"}},{q="这些零件是怎么掉进黑海岸的河流里的？",a="维兹班恩·曲针在晚上醉醺醺地在黑海岸游荡，寻找测试水道。他昏了过去，醒来时已经回到了奥伯丁，头发被烧焦了，而不小心将整袋零件掉进了淡水溪流里。",al={"为什么在水里","电驱推进器是如何丢失的","曲针的失误"}},{q="在哪里可以回收电驱推进器？",a="它们漂流在黑海岸的内陆淡水水域，包括壁泉河和急弯河，幸运的垂钓者可以从水中将它们捞上来。",al={"在哪里钓电驱推进器","电驱推进器位置","壁泉河垂钓"}},{q="谁想要回这些零件？",a="住在奥伯丁的侏儒维兹班恩·曲针需要十二个零件，这样他才能继续他的诱饵研究。",al={"谁需要电驱推进器","曲针是谁","奥伯丁侏儒任务"}}},fx={["3f720660"]={q="什么是电动螺旋桨？",a="电动螺旋桨是由侏儒工程学制造的专用机械推进部件。这些电动零件用于驱动水上装置，尤其是维兹班恩·曲针构思的古怪发明，例如他的电动鸭子诱饵。",al={"什么是电动螺旋桨","电动螺旋桨物品"}}},fp="13,268,27.638.0,34.208.0,54.254.0,38.162.0,36.121.0"}
P.entries["item:elixir-of-pain"] = {n="痛苦药剂",s="痛苦药剂是塔伦米尔的被遗忘者药剂师们酿造的一种实验性炼金混合物。该混合物使用从希尔斯布莱德丘陵各地采集的血液蒸馏而成，旨在测试用于达成希尔瓦娜斯女王阴暗野心的生物制剂。",h="痛苦药剂是塔伦米尔的被遗忘者药剂师们酿造的一种实验性炼金混合物。该混合物使用从希尔斯布莱德丘陵各地采集的血液蒸馏而成，旨在测试用于达成希尔瓦娜斯女王阴暗野心的生物制剂。",kw={"药剂师","痛苦药剂","雷恩农夫","希尔斯布莱德农场","皇家药剂师协会","斯坦利","希尔瓦娜斯","塔伦米尔"},ang={["faction:Horde"]="被遗忘者的盟友经常被召唤来协助这些残酷的测试，亲眼见证塔伦米尔的研究者们所采用的令人不安的手段。",["race:Undead"]="皇家药剂师协会无情的实地试验表明，为了开发对付生者的化学武器，被遗忘者愿意不择手段。"},sec={{t="药剂师实验",b="皇家药剂师协会不断研制新配方，以巩固被遗忘者对抗邻近凡人种族和天灾军团的地位。痛苦药剂就是这样的一项试验，由在希尔斯布莱德丘陵周边采集的新鲜原料混合而成。这种药剂在酿造时完全不顾及生者的感受，是旨在辅助黑暗女王的挥发性物质的概念验证。"},{t="对斯坦利的实地测试",b="为了避免冒风险动用宝贵的军事资源，或是让希尔斯布莱德的守卫过早察觉他们的行动，药剂师们寻找了一个隐秘的实验对象。这种药剂被喂给了斯坦利，一只看起来人畜无害的家犬，它属于希尔斯布莱德农场北部农舍的雷恩农夫。但这瓶毒药并没有让它安静地死去，反而剧烈地变异，让这只可怜的动物变成了一头狂暴的怪兽。"}},faq={{q="痛苦药剂的目的是什么？",a="痛苦药剂是一种实验性药剂，旨在为皇家药剂师协会测试生物化合物。其制造者希望这些混合物最终能产生毁灭性的药剂，以服务于希尔瓦娜斯女王并确保被遗忘者的统治地位。",al={"为什么要制作痛苦药剂","药剂的用途","药剂有什么作用"}},{q="斯坦利是谁？",a="斯坦利是希尔斯布莱德农场北部农舍雷恩农夫所养的一只宠物狗。它被被遗忘者药剂师选中，成为了一个毫无防备的实验对象，用以观察他们新酿药剂的生理影响。",al={"谁是斯坦利","雷恩农夫的狗","狗斯坦利"}},{q="为什么要用斯坦利来测试这种药剂？",a="药剂师林度恩想要对他新调制的药剂进行一次实地测试，于是将其送给了雷恩农夫的小狗斯坦利，看看这只动物会有什么反应。",al={"斯坦利发生了什么事","斯坦利会死吗","斯坦利变身狼"}},{q="这种药剂是在哪里测试的？",a="测试发生在希尔斯布莱德农场北部农舍外，位于塔伦米尔西南方。斯坦利通常会待在雷恩农夫房子的前廊附近。",al={"我该把药剂带到哪里","斯坦利的位置","雷恩农夫的农场"}}},fx={["5a45fd3d"]={q="什么是痛苦药剂？",a="痛苦药剂是为被遗忘者在希尔斯布莱德丘陵的战争行动酿制的实验性炼金混合剂。它以新鲜采集的血液和不稳定试剂调制而成，是皇家药剂师协会为希尔瓦娜斯女士研制黑暗瘟疫和毒素的早期原型。",al={"什么是痛苦药剂","痛苦药剂物品","痛苦药水"}},["52862df0"]={q="痛苦药剂来自哪里？是谁制作的？",a="这剂药水是在被遗忘者的塔伦米尔据点酿制的。药剂师会将从周边丘陵收集的新鲜生物血液与其他腐蚀性成分混合，意图制成一种剧毒武器，助黑暗女王征服这一地区。",al={"谁制作了痛苦药剂","痛苦药剂的制作者","痛苦药剂来自哪里"}}},fp="14,273,26.416.0,24.396.1,42.247.0,15.223.0,36.141.1,27.178.0"}
P.entries["item:elixir-of-suffering"] = {n="受难药剂",s="受难药剂是塔伦米尔的药剂师林度恩酿造的一种炼金药剂。这种药水是在皇家药剂师学会的命令下开发的，是向旨在根除活人与天灾军团的致命瘟疫迈出的实验性一步。",h="受难药剂是塔伦米尔的药剂师林度恩酿造的一种炼金药剂。这种药水是在皇家药剂师学会的命令下开发的，是向旨在根除活人与天灾军团的致命瘟疫迈出的实验性一步。",kw={"药剂师林度恩","受难药剂","被遗忘者的瘟疫","希尔斯布莱德丘陵","皇家药剂师学会","塔伦米尔","乌比"},ang={["race:Undead"]="皇家药剂师学会在洛丹伦各地工作，旨在创造一种武器，以确保被遗忘者脱离天灾军团和活人的控制，而林度恩在塔伦米尔进行的有害实验是必不可少的一步。"},sec={{t="药剂师实验",b="在塔伦米尔的废墟村庄内，药剂师林度恩不懈地将从周围荒野采集的原始试剂混合成剧毒药水。受难药剂代表了皇家药剂师学会总体使命的一个早期里程碑：配制一种旨在消灭生者与死者的新瘟疫。林度恩在他那倒霉的助手，一只名叫乌比的青蛙身上测试这种致命的药水，以确保其效力。"}},faq={{q="受难药剂的用途是什么？",a="这种药剂是药剂师林度恩作为皇家药剂师学会研究的一部分而酿造的实验性药水。它旨在测试被遗忘者针对人类和天灾军团的新型瘟疫中使用的致命化合物。",al={"为什么要制作受难药剂","这种药剂有什么作用","受难药剂的目的"}},{q="乌比是谁？",a="乌比是药剂师林度恩在塔伦米尔饲养的一只普通青蛙。尽管被戏称为助手，但乌比主要是作为新酿炼金毒素的不知情测试对象。",al={"那只青蛙是谁","那只蟾蜍是谁","林度恩的助手"}},{q="当乌比喝下药剂后会发生什么？",a="在被喂食受难药剂后，这只不幸的两栖动物会发出叫声并几乎立刻死于毒素，这证明了药剂师林度恩配方的致命功效。",al={"乌比会死吗","那只蟾蜍会怎样"}}},fx={["14f85f3d"]={q="什么是受难药剂？",a="受难药剂是皇家药剂师协会在塔伦米尔酿制的实验性混合剂。它是被遗忘者持续研制新型瘟疫的一部分，这种致命的混合物旨在给生者和亡灵都带来剧痛与死亡。",al={"什么是受难药剂","受难药剂背景","受难药剂有什么作用"}},fa4e475a={q="受难药剂来自哪里？是谁制造的？",a="这种药剂由药剂师林度恩调制，他驻扎在希尔斯布莱德丘陵的塔伦米尔。林度恩代表皇家药剂师协会和Sylvanas Windrunner，在丘陵各地收集当地材料，用以配制并改良这种致命药剂。",al={"谁制造了受难药剂","受难药剂的制造者","受难药剂来自哪里"}},["1d085d8d"]={q="药剂师林度恩为什么想制造受难药剂？",a="药剂师林度恩调制这种药剂，是为了实现黑暗女王的宏图：制造一种威力强大的武器，足以消灭天灾军团和人类。他在当地受试者身上测试药剂的致命性，确保药剂能带来极度折磨和迅速死亡。",al={"为什么制造受难药剂","受难药剂的用途","林度恩为什么要这种药剂"}}},fp="19,273,26.437.0,47.232.0,12.202.0,41.186.1"}
P.entries["item:elune-s-tear"] = {n="月神之泪",s="月神之泪是一种稀有的发光矿石，发现于灰谷伊瑞斯湖的中央岛屿上。暗夜精灵草药师和治疗者将其视为月之女神的神圣赐福，并因其能够净化魔法腐蚀和致命疾病的强大能力而寻找这种矿石。",h="月神之泪是一种稀有的发光矿石，发现于灰谷伊瑞斯湖的中央岛屿上。暗夜精灵草药师和治疗者将其视为月之女神的神圣赐福，并因其能够净化魔法腐蚀和致命疾病的强大能力而寻找这种矿石。",kw={"灰谷","阿斯特兰纳","治疗","月神之泪","伊瑞斯湖","奥雷迪尔","皮尔图拉斯","瑞拉拉"},ang={["class:Priest"]="圣光与月亮的虔诚信徒们承认这种矿石天生具有清除阴影和腐烂的力量，这体现了艾露恩祭司所归功的恢复性奇迹。",["race:NightElf"]="对于暗夜精灵来说，带有艾露恩之名的遗物是神圣的礼物。使用这种矿石来拯救一个无辜的孩子，反映了卡多雷与月之母治愈恩典之间永恒的纽带。"},sec={{t="神圣的净化之石",b="月神之泪被发现隐匿在阿斯特兰纳东部伊瑞斯湖的一座小岛上，这是一种神秘的矿石，据信承载着月之女神本身的纯洁。湖泊本身也没能逃脱森林腐蚀的侵袭：湖水已变得病态般的绿色，扭曲的沼泽兽在湖岸徘徊。这种矿石在当地的暗夜精灵草药师和治疗者——例如奥雷迪尔·阔叶——中颇为出名，当普通的林地药膏失效时，它被视为一种能够洗去顽固腐蚀的应急良药。"},{t="绝望中的疗法",b="当一种神秘的消瘦症袭击了阿斯特兰纳的年轻暗夜精灵瑞拉拉·怀特姆恩时，她的父亲皮尔图拉斯用尽了普通的药物。在药剂师奥雷迪尔的建议下，皮尔图拉斯寻找月神之泪，试图将其直接熬制成恢复性的炖汤。虽然它为对抗这种奇怪的疾病带来了暂时的希望，但困扰灰谷的顽固腐蚀往往需要更强大的净化仪式。"}},faq={{q="什么是月神之泪？",a="月神之泪是一种稀有的魔法矿石，静卧在灰谷伊瑞斯湖的岛屿上。暗夜精灵将其视为注入了艾露恩净化之触的神圣遗物，主要用于治愈非自然的腐蚀和恶性疾病。",al={"月神之泪","这是什么石头","月神之泪有什么用"}},{q="在哪里可以找到月神之泪？",a="月神之泪位于灰谷中部、阿斯特兰纳东部伊瑞斯湖中央的岛屿上。旅行者可以沿着大路北侧的溪流小径到达那里。",al={"月神之泪在哪里","伊瑞斯湖矿石位置","寻找月神之泪"}},{q="皮尔图拉斯·怀特姆恩为什么需要月神之泪？",a="皮尔图拉斯寻找月神之泪是为了挽救他生病的女儿瑞拉拉。当常规的草药治疗无法阻止她体内蔓延的非自然疾病时，药剂师奥雷迪尔建议，只有这种矿石的恢复性纯净才能净化这种苦难。",al={"皮尔图拉斯为什么想要它","瑞拉拉的治疗","谁需要月神之泪"}},{q="是什么在伊瑞斯湖守护着这种矿石？",a="扭曲的沼泽兽在伊瑞斯湖周围徘徊，湖水在灰谷蔓延的腐蚀影响下已经变成了病态的绿色。",al={"伊瑞斯湖的敌人","什么守护着月神之泪"}}},fp="12,271,24.498.0,18.415.1,21.239.0,32.187.0,42.255.0,35.140.0"}
P.entries["item:embalming-ichor"] = {n="防腐剂",s="防腐剂是一种不自然的防腐液体，是从提瑞斯法林地北部的腐皮豺狼人体内采集而来的。它维持着豺狼人行尸走肉般的存在，并引起了被遗忘者药剂师的密切关注，他们试图分析其特性以对抗天灾军团。",h="防腐剂是一种不自然的防腐液体，是从提瑞斯法林地北部的腐皮豺狼人体内采集而来的。它维持着豺狼人行尸走肉般的存在，并引起了被遗忘者药剂师的密切关注，他们试图分析其特性以对抗天灾军团。",kw={"药剂师","布瑞尔","防腐剂","加伦鬼屋","掘墓者","执政官塞弗伦","乱葬岗","腐皮豺狼人"},ang={["profession:Herbalism"]="腐皮豺狼人内部的防腐液体展示了黑暗炼金术的方法，这些方法引起了研究瘟疫试剂的草药师和化学家的兴趣。",["race:Undead"]="对于被遗忘者来说，阻止天灾军团从乱葬岗中获得新鲜尸体，对于保护提瑞斯法林地并确保他们自身生存所需的原材料至关重要。"},sec={{t="不自然的防腐",b="侵扰加伦鬼屋及其附近乱葬岗的腐皮豺狼人并非普通的野生野兽；它们是被天灾军团部署用来挖掘瘟疫受害者尸体的腐烂且经过防腐处理的奴仆。在它们腐烂的血管中流淌着防腐剂，这是一种污秽的液体，可以人工防腐它们的血肉并赋予它们持久的亡灵状态。对于布瑞尔的执政官塞弗伦来说，回收这种防腐剂的瓶子有两个目的：这既证实了这些掘墓者已被消灭，又为皇家药剂师学会的研究人员提供了新鲜的样本，以便他们对其进行解剖、研究，并将其武器化以对抗巫妖王的爪牙。"}},faq={{q="防腐剂是什么？",a="它是一种存在于提瑞斯法林地腐皮豺狼人活动躯体内的防腐炼金物质。这种液体维持着它们腐烂的血肉，并使它们能继续为天灾军团效力。",al={"防腐剂","什么是防腐剂","豺狼人液体"}},{q="谁想要收集这种防腐剂？",a="驻守布瑞尔镇的执政官塞弗伦下令让被遗忘者的勇士们从被杀死的腐皮豺狼人身上采集这种防腐剂，以便皇家药剂师学会研究其化学成分。",al={"谁需要防腐剂","执政官塞弗伦 防腐剂","谁想要防腐剂"}},{q="腐皮豺狼人为什么要挖掘坟墓？",a="天灾军团利用腐皮豺狼人挖掘埋葬在加伦鬼屋附近北部乱葬岗中的瘟疫受害者尸体，以寻求补充他们部队的原材料。",al={"为什么豺狼人掘墓","提瑞斯法林地 乱葬岗","豺狼人 天灾军团 联系"}},{q="被遗忘者计划用这种液体做什么？",a="幽暗城的药剂师们研究这种防腐剂以揭开它的秘密，希望能开发出对抗天灾军团的应对措施或新的炼金配方。",al={"塞弗伦如何处理防腐剂","药剂师研究防腐剂","防腐剂的用途"}}},fx={e6b7bf5e={q="防腐剂来自哪里？是谁制造的？",a="防腐剂采集自出没于提瑞斯法林地大墓地和加伦鬼屋一带的腐皮豺狼人。这种污秽而反常的液体被天灾军团用来驱动并保存这些亡灵豺狼人仆从，维持着驱使它们为主人军队掘出尸体的伪生命。",al={"防腐剂的来源","谁制造了防腐剂","防腐剂来自哪里"}}},fp="15,287,22.601.0,24.199.0,31.181.0,46.176.0,47.155.0"}
P.entries["item:emerald-dreamcatcher"] = {n="翡翠摄梦符",s="翡翠摄梦符是一件神圣的暗夜精灵护身符，旨在从翡翠梦境中汲取微妙的生命力。它由班奈希尔兽穴的德鲁伊赠予塔隆凯·捷根，但在棘木熊怪陷入腐化并占领星风村时，被遗落在了那里。",h="翡翠摄梦符是一件神圣的暗夜精灵护身符，旨在从翡翠梦境中汲取微妙的生命力。它由班奈希尔兽穴的德鲁伊赠予塔隆凯·捷根，但在棘木熊怪陷入腐化并占领星风村时，被遗落在了那里。",kw={"班奈希尔兽穴","多兰纳尔","翡翠摄梦符","熊怪","盖洛拉斯·塔文斯伦","星风村","塔隆凯·捷根","泰达希尔"},ang={["class:Druid"]="这枚护身符是通往班奈希尔兽穴中沉睡德鲁伊的直接纽带，展示了他们与翡翠梦境的交流如何为下方的卡多雷定居点提供援助。",["race:NightElf"]="找回这件遗物是抗击正在侵蚀星风村及泰达希尔周边枝干的蔓延疾病的一场微小胜利。"},sec={{t="来自班奈希尔的礼物",b="翡翠摄梦符是在班奈希尔兽穴的德鲁伊典狱官盖洛拉斯·塔文斯伦的监护下制作的，这是一件仅赠予极少数被选中者的附魔遗物。它被设计用来直接从翡翠梦境中抽取环境能量，并为携带它的人带来好运与庇护。当星风村落入疯狂的棘木熊怪之手时，这枚护身符被遗忘在梳妆台中，困在了充满敌意的腐化领地中心。"}},faq={{q="翡翠摄梦符有什么用？",a="根据塔隆凯·捷根的说法，该护身符会从翡翠梦境中汲取原始能量，为持有者赋予好运与活力。它被认为是塞纳里奥德鲁伊所赐予的一种珍贵的恩惠信物。",al={"翡翠摄梦符的力量","摄梦符的用途","摄梦符背景故事"}},{q="翡翠摄梦符是谁制作的？",a="它是盖洛拉斯·塔文斯伦赠予塔隆凯的，这位德鲁伊典狱官负责监视班奈希尔兽穴内沉睡的塞纳里奥议会。",al={"摄梦符的制作者","谁给了塔隆凯摄梦符"}},{q="为什么摄梦符会被遗弃在星风村？",a="塔隆凯曾将这枚护身符存放在星风村的梳妆台里。当当地的棘木熊怪被腐化吞噬并变得狂暴时，他在取回护身符之前被迫撤离了该定居点。",al={"塔隆凯为什么丢弃它","摄梦符遗失地点"}},{q="为什么星风村的熊怪充满敌意？",a="泰达希尔各地的棘木部族成了黑暗且不断蔓延的腐化的受害者，这股力量驱使他们陷入攻击性的狂乱，迫使暗夜精灵逃离了像星风村这样的外围定居点。",al={"星风村陷落原因","星风村熊怪"}}},fx={a335891d={q="什么是翡翠摄梦符？",a="翡翠摄梦符是泰达希尔德鲁伊制作的一种稀有而强大的附魔护符。它能够直接汲取翡翠梦境的力量，并引导宁静的自然魔法，为佩戴者带来好运与清晰的思绪。多兰纳尔的塔隆凯·捷根视它为珍贵的私人礼物，只会赠予少数受宠之人。",al={"什么是翡翠摄梦符","翡翠摄梦符物品","摄梦符是什么类型的物品"}},["54ca5db1"]={q="塔隆凯·捷根为什么想要取回翡翠摄梦符？",a="当Gnarlpine熊怪堕落并攻占星风村时，塔隆凯·捷根被迫将护符留在了梳妆台里。除了能从翡翠梦境汲取好运的灵性力量，这件护符对他还有重大的个人意义：它是班奈希尔兽穴守护者盖洛拉斯·塔文斯伦送给他的稀有礼物。",al={"塔隆凯为什么想要摄梦符","为什么取回摄梦符","摄梦符为何重要"}}},fp="20,300,21.470.0,38.204.0,34.143.0,59.219.0,51.201.0"}
P.entries["item:empty-blue-waterskin"] = {n="空的蓝色水囊",s="空的蓝色水囊是萨满的水之试炼中授予初学者的仪式器皿。它由贫瘠之地的隐士Brine提供，需要被带往北方的古老暗夜精灵领地，以获取必要的圣洁、纯净之水，从而制作水之图腾。",h="空的蓝色水囊是萨满的水之试炼中授予初学者的仪式器皿。它由贫瘠之地的隐士Brine提供，需要被带往北方的古老暗夜精灵领地，以获取必要的圣洁、纯净之水，从而制作水之图腾。",kw={"灰谷","贫瘠之地","brine","call of water","空的蓝色水囊","星尘废墟","水之图腾"},ang={["class:Shaman"]="携带并装满这个水囊是掌握水之灵的重要里程碑，可获得制作你的永久性水之图腾所需的纯净液体。",["faction:Horde"]="取水需要从贫瘠之地长途跋涉，穿越到灰谷西部的敌对暗夜精灵领地，过程十分危险。"},sec={{t="神圣器皿",b="与水之灵沟通需要与卡利姆多各地纯净、不受干扰的水源进行切实接触。空的蓝色水囊由居住在南贫瘠之地山顶小屋中的隐士Brine传授，代表了萨满早期训练中最后且最危险的收集任务。它注定要盛放直接取自灰谷争议边界内、深藏于星尘废墟中一处隐秘喷泉的原始水。"},{t="森林喷泉",b="填满这个简单的容器需要初学者走出部落领地的安全范围，进入由自然野兽和暗夜精灵守护的古老树林。一旦浸入废墟圣地的水中，容器就会变成装满水的蓝色水囊。结合来自贫瘠之地和塔伦米尔的样本，其内容物将帮助Brine酿造召唤并安抚水元素之灵所需的药剂。"}},faq={{q="空的蓝色水囊有什么用途？",a="这是一个在Call of Water任务线中使用的空容器。初学者必须将其带到灰谷星尘废墟的圣洁喷泉处，在那里将其装满，然后交还给Brine以帮助酿造纯净之水的药剂。",al={"空的蓝色水囊的作用","空的蓝色水囊的使用方法","为什么我有空的蓝色水囊"}},{q="谁会给你这个水囊？",a="它由Brine提供，这是一位苦行僧般的萨满导师，独自居住在南贫瘠之地、陶拉祖营地以南、Razorfen边界附近的一间小屋里。",al={"空的蓝色水囊的来源","获取蓝色水囊的位置"}},{q="水囊必须在哪里装满？",a="它必须在星尘废墟内发现的中央喷泉处装满，该喷泉位于灰谷西南部深处，刚好越过Lake Mystral、靠近Stonetalon山脊。",al={"空的蓝色水囊装填位置","蓝色水囊位置","装填地点"}},{q="为什么Brine需要来自灰谷的水？",a="Brine试图创造出卡利姆多已知的最纯净的水瓶。暗夜精灵废墟中未受触碰的圣洁泉水提供了与水元素之灵沟通所需的纯净最终成分。",al={"为什么需要灰谷之水","为什么需要星尘废墟之水"}}},fx={["6fa6361d"]={q="什么是空的蓝色水囊？",a="空的蓝色水囊是一种仪式容器，受托给参加试炼的萨满祭司学徒。它由南贫瘠之地的隐士Brine赠予，专为安全收集并携带圣地的纯净之水而制，不会损害水的灵性力量。",al={"空的蓝色水囊","什么是蓝色水囊","蓝色水囊的用途"}}},fp="20,268,15.473.0,19.424.0,42.228.0,29.143.0,35.178.0,41.218.0"}
P.entries["item:empty-brown-waterskin"] = {n="空的棕色水囊",s="空的棕色水囊是萨满在贫瘠之地进行试炼时，由布莱恩提供的一种元素容器。它被用于从附近的绿洲收集水，是在这片干旱的土地上学习水元素脆弱且充满争端这一本质的第一件物理工具。",h="空的棕色水囊是萨满在贫瘠之地进行试炼时，由布莱恩提供的一种元素容器。它被用于从附近的绿洲收集水，是在这片干旱的土地上学习水元素脆弱且充满争端这一本质的第一件物理工具。",kw={"贫瘠之地","布莱恩","call of water","野猪人","元素药剂","萨满","水囊"},ang={["class:Shaman"]="携带这个水囊是部落萨满寻求水之图腾的成人礼，它展示了对元素的敬畏与凡人残酷生存斗争之间的平衡。"},sec={{t="匮乏的教训",b="在贫瘠之地那被烈日炙烤的平原上，水远不止是一种资源，它本身就是生命，也是战争永恒的导火索。隐士布莱恩委托一位学徒拿着这个简单的皮囊，作为“水之召唤”试炼的开端。任务看似简单——把这个空容器带到她住所下方的水潭并装满带回来。然而，在从那处孤零零的水潭取水时，持有人立刻面对了这片土地残酷的真相：每一滴水都受到当地野猪人的严密守护，他们将绿洲视为无价的宝藏，这迫使学徒去理解水是如何既维持着生命，又驱使凡人走向暴力的。"}},faq={{q="空的棕色水囊有什么用？",a="这是布莱恩交给萨满学徒的一个空容器。它的用途是从位于她在贫瘠之地的住所正下方的天然水潭中取水，将其装满，这是制备元素药剂所必需的。",al={"水囊用途","棕色水囊的作用","空的棕色水囊用法"}},{q="谁提供了这个水囊？",a="布莱恩，一位居住在贫瘠之地南部的知识渊博的隐士，她为进行元素朝圣以与水之灵沟通的萨满提供了这个容器。",al={"谁给的水囊","棕色水囊任务发放者","去哪里获取空的棕色水囊"}},{q="为什么野猪人要守卫水源？",a="在整个贫瘠之地，水极其稀缺。对野猪人来说，即使是一个很小的水潭也代表着巨大的财富和生存保障。由于降雨稀少，他们以极度的贪婪守卫着每一处泉水，攻击任何胆敢取水的人。",al={"为什么野猪人会攻击","野猪人 水","为什么水潭有守卫"}},{q="水囊装满后会发生什么？",a="一旦浸入布莱恩小山下方的绿洲，它就会变成装满水的棕色水囊。把它交还给布莱恩，她就能在你前往世界各地寻找更稀有的水源之前，测试你对自然平衡的理解。",al={"装满水后做什么","交还水囊","装满水的棕色水囊交还"}}},fx={["805e4eda"]={q="什么是空的棕色水囊？",a="空的棕色水囊是南贫瘠之地的隐士Brine赠予萨满祭司学徒的普通容器。它是学习与水之灵沟通道路上的教具。若想获得Water Sapta，你必须带着这个容器前往附近一处由凶猛的野猪人看守的水源地，将它装满纯净的水，同时观察在干旱平原上，生命与冲突如何围绕稀缺的水源展开。",al={"什么是空的棕色水囊","空的棕色水囊背景","棕色水囊"}}},fp="21,255,20.652.0,43.227.0,28.186.0,48.245.0,37.219.0"}
P.entries["item:empty-cleansing-bowl"] = {n="空的净化碗",s="空的净化碗是桑德里斯·风织交给你的仪式器皿，旨在帮助调查黑木熊怪的腐化。当它在奥伯丁的月亮井中装满水并与食物样本混合后，产生的混合物能够暂时打破萨特施加的恶魔控制。",h="空的净化碗是桑德里斯·风织交给你的仪式器皿，旨在帮助调查黑木熊怪的腐化。当它在奥伯丁的月亮井中装满水并与食物样本混合后，产生的混合物能够暂时打破萨特施加的恶魔控制。",kw={"奥伯丁","黑木","净化碗","黑海岸","空的净化碗","月亮井","桑德里斯·风织","萨布拉希斯"},ang={["class:Druid"]="利用月亮井的水来消除非自然的苦难，体现了德鲁伊修复黑海岸自然平衡的核心使命。",["race:NightElf"]="净化仪式展示了艾露恩月亮井消除邪恶恶魔腐化的力量，让人们看到暗夜精灵在熊怪中的老盟友终有一天可能得到拯救的希望。"},sec={{t="一个净化器皿",b="空的净化碗由奥伯丁的桑德里斯·风织委托冒险者携带，用于盛装当地月亮井的神圣之水。暗夜精灵发现北部的黑木熊怪陷入了萨特精心策划的恶魔疯狂之中，萨特正是通过附魔的护符来施加意志的。通过将纯净的月亮之水汲入碗中，并与从熊怪那里收集的坚果、谷物和水果混合，该器皿可以产生一种受祝福的食物，暂时恢复受影响生物的理智，从而揭露幕后的萨特监工。"}},faq={{q="我该如何使用空的净化碗？",a="带着碗前往奥伯丁的月亮井，将其浸入神圣的井水中，即可获得装满水的净化碗。此后，你需要从北部的黑木熊怪营地收集谷物、坚果和水果样本，将其与碗中的水混合。",al={"空的净化碗用法","如何使用空的净化碗","在哪里装满净化碗"}},{q="为什么暗夜精灵需要这个碗来对抗熊怪的腐化？",a="黑木熊怪被萨特护符的黑暗魔法所束缚。桑德里斯·风织使用这个碗来盛放一种神圣的混合物，可以暂时治愈熊怪的狂乱，从而引出它们背后隐藏的萨特控制者——萨布拉希斯。",al={"为什么要用净化碗","净化碗的用途"}},{q="谁提供了空的净化碗？",a="奥伯丁的暗夜精灵学者桑德里斯·风织在委派你调查壁泉河沿岸黑木腐化的源头时，会将这个碗交给你。",al={"谁给予净化碗","净化碗任务发布者"}},{q="混合物准备好后会发生什么？",a="将制成的混合物放置在北部营地的篝火旁，可以净化周围的熊怪，时间足以引出萨特萨布拉希斯的愤怒，从而让你击败他并夺取他的堕落护符。",al={"净化碗篝火","放置净化碗"}}},fx={["2a179129"]={q="什么是空的净化碗？",a="空的净化碗是桑迪斯·织风在奥伯丁交给你的仪式容器。它专门用来盛放月亮井的圣水和野生食材，是准备净化祭品的关键物品。这种祭品能够驱除当地野生动物和熊怪身上的恶魔污染。",al={"什么是空的净化碗","净化碗背景","空的净化碗用途"}}},fp="20,285,24.560.0,43.236.0,70.240.1,38.176.0,42.211.1"}
P.entries["item:empty-cliffspring-falls-sampler"] = {n="空的峭壁之泉取样器",s="空的峭壁之泉取样器是塞纳里奥议会委托暗夜精灵新手德鲁伊使用的一种特制药瓶。它被用于采集黑海岸峭壁之泉河口处的样本，以帮助诊断导致当地野生动物腐化的邪恶毒素。",h="空的峭壁之泉取样器是塞纳里奥议会委托暗夜精灵新手德鲁伊使用的一种特制药瓶。它被用于采集黑海岸峭壁之泉河口处的样本，以帮助诊断导致当地野生动物腐化的邪恶毒素。",kw={"奥兰达利亚·夜歌","塞纳里奥议会","峭壁之泉","驱毒术","黑海岸","德迪利特·星焰","取样器"},ang={["class:Druid"]="在娜迦出没的洞穴中填满这个取样器是年轻德鲁伊的成人礼，这直接引导他们学习“驱毒术”。",["race:NightElf"]="黑海岸原始森林水源遭到潜伏的娜迦亵渎，这威胁到了野兽和奥伯丁定居点的安全。"},sec={{t="调查受污染的水源",b="峭壁之泉是黑海岸北部的主要淡水源，因此其源头的任何干扰对当地生态系统来说都是致命的威胁。当当地的鹿群开始死于一种剧烈的消耗性毒素时，塞纳里奥议会的德迪利特·星焰将这些空的取样器提供给了从月光林地派出的年轻德鲁伊。德鲁伊必须深入瀑布附近的悬崖，前往如今被敌对的娜迦占据的洞穴入口，采集一份可用的水样本。"},{t="解药配方",b="取样器装满后，其中的浑浊液体揭示了一种更深层的生态枯萎。将样本送到奥伯丁的奥兰达利亚·夜歌手中后，污染的样本证实了邪恶势力正在腐化地下水位。通过研究玻璃瓶中残留的污染物，奥兰达利亚和塞纳里奥的德鲁伊们获得了配制解药所需的洞察力，并授予初学者基础的德鲁伊治疗仪式。"}},faq={{q="这个取样器的用途是什么？",a="这是一个空的容器，交给德鲁伊用于从黑海岸峭壁之泉的洞穴入口处采集受污染的水。该样本可以让塞纳里奥的草药师诊断并治愈影响当地野生动物的毒素。",al={"取样器用途","峭壁之泉取样器的作用","空取样器的目的"}},{q="水样本是在哪里采集的？",a="样本必须直接从位于黑海岸东北部高山、峭壁之泉附近的洞穴入口处采集。敌对的娜迦占据了洞穴入口，使得采集工作充满了危险。",al={"在哪里填充取样器","峭壁之泉取样器位置","填充取样器的地点"}},{q="谁会接收装满的容器？",a="装满的取样器会被交给奥兰达利亚·夜歌，她是一位驻扎在奥伯丁沿海定居点的暗夜精灵治疗者，也是塞纳里奥议会的代表。",al={"谁来接收装满的取样器","在哪里上交取样器","奥兰达利亚取样器"}},{q="为什么采集峭壁之泉的水而不是其他河流？",a="峭壁之泉是黑海岸北部的核心淡水源。德迪利特·星焰将导致该地区鹿群患病的源头追溯到了这些水源处，因此直接采集水样本对于开发解药至关重要。",al={"为什么是峭壁之泉","什么在毒害黑海岸","峭壁之泉毒素"}}},fx={["0413bdcd"]={q="什么是空的峭壁之泉取样器？",a="这是一种专用容器，供塞纳里奥议会的德鲁伊采集黑海岸峭壁之泉未受污染的水样。由于人们认为瀑布的水已遭污染，使用无菌的专用容器对于研究这种有毒液体至关重要，既能避免污染样本，也能保护携带者。",al={"什么是峭壁之泉取样器","峭壁之泉取样器物品"}},dccecdc8={q="空的峭壁之泉取样器来自哪里？是谁制造的？",a="这种取样器由月光林地的塞纳里奥议会德鲁伊提供，具体来说是由德迪利特·星焰提供的。议会察觉到某种反常的东西开始毒害黑海岸的野生动物，于是准备了这些容器，让值得信任的学徒能够直接从疑似污染源采集纯净样本。",al={"谁给了我峭壁之泉取样器","谁制造了取样器","取样器来源"}}},fp="31,274,32.508.0,19.415.1,36.228.0,32.204.0,34.154.0,63.236.0"}
P.entries["item:empty-dreadmist-peak-sampler"] = {n="空的鬼雾峰取样器",s="空的鬼雾峰取样器是塞纳里奥议会委托部落德鲁伊所使用的特殊容器，用于收集鬼雾峰顶端被污染的水。研究这种瓶中收集的污秽液体，对于诊断和治愈正在影响贫瘠之地北部野生动物的蔓延枯萎病至关重要。",h="空的鬼雾峰取样器是塞纳里奥议会委托部落德鲁伊所使用的特殊容器，用于收集鬼雾峰顶端被污染的水。研究这种瓶中收集的污秽液体，对于诊断和治愈正在影响贫瘠之地北部野生动物的蔓延枯萎病至关重要。",kw={"贫瘠之地","火刃氏族","德迪利特·星焰","鬼雾峰","空的鬼雾峰取样器","主要源头","图加·符文图腾"},ang={["class:Druid"]="获取这个取样器是学习治愈毒素艺术的关键一步，也是对德鲁伊诊断和缓解野外苦难的奉献精神的一次考验。",["faction:Horde"]="部落德鲁伊携带这个取样器来协助十字路口的图加·符文图腾，以阻止威胁贫瘠之地北部平原的生态衰退。"},sec={{t="追踪枯萎病",b="当一种邪恶的折磨开始让瞪羚生病，并破坏贫瘠之地北部脆弱的生态系统时，德鲁伊德迪利特·星焰怀疑鬼雾峰顶端的影响天气的池塘是其中心。他派遣了携带着空取样器的德鲁伊新兵，去面对高山险峰——那里现在充斥着崇拜恶魔的火刃氏族——并直接从峰顶的池塘中提取原始水样。"},{t="关键样本",b="带着空取样器登上峭壁，可以让德鲁伊获得邪教徒邪恶行径的确凿证据。装满后，腐臭的水会被送到十字路口的图加·符文图腾那里，其污秽成分将成为调配解药和保护当地动物群的关键基础。"}},faq={{q="空的鬼雾峰取样器的用途是什么？",a="它是一个空的容器，供德鲁伊从鬼雾峰顶端被污染的池塘中抽取水样，以协助图加·符文图腾配制治愈生病野生动物的解药。",al={"这个物品有什么用","鬼雾峰取样器的用法","为什么我会有这个取样器"}},{q="这个取样器需要带到哪里去？",a="它必须被带到贫瘠之地十字路口西北方向的鬼雾峰顶端，并浸入水体汇聚的高处池塘中。",al={"我在哪里填充取样器","取样器位置","如何填充空的鬼雾峰取样器"}},{q="谁提供了取样器？",a="代表塞纳里奥议会的德迪利特·星焰在派遣德鲁伊与图加·符文图腾合作之前，提供了这个取样器。",al={"谁提供了取样器","谁开启了这个任务"}},{q="为什么鬼雾峰的水样如此重要？",a="鬼雾峰的空中池塘影响着区域的天气模式和雾气。由于山顶已被火刃氏族腐蚀，受污染的径流扩散到平原上，毒害了当地的生物。",al={"为什么是鬼雾峰的池塘","为什么水质变坏了"}}},fx={cf2d7f72={q="什么是空的鬼雾峰取样器？",a="这是一种由塞纳里奥议会的德迪利特·星焰托付给部落德鲁伊的专用容器。它专用于安全盛装并运送从鬼雾峰高处水池采集的水，以便安全分析，同时避免样本洒漏或受到进一步污染。",al={"什么是鬼雾峰取样器","空的鬼雾峰取样器物品","鬼雾峰取样器"}}},fp="28,298,18.434.0,18.308.1,56.174.0,41.152.0,25.143.0,58.208.0"}
P.entries["item:empty-leaden-collection-phial"] = {n="空铅瓶",s="空铅瓶是一种由侏儒技师设计的屏蔽容器，旨在从诺莫瑞根的废墟中采集放射性尘埃。它由铅制成，以保护携带者免受致命的污染，是协助卡拉诺斯的奥齐·电环的冒险者们所使用的工具。奥齐希望这些捕获的辉光能够为受灾的族人找到治愈的方法——或者至少能酿成一种效力非凡的饮料。",h="空铅瓶是一种由侏儒技师设计的屏蔽容器，旨在从诺莫瑞根的废墟中采集放射性尘埃。它由铅制成，以保护携带者免受致命的污染，是协助卡拉诺斯的奥齐·电环的冒险者们所使用的工具。奥齐希望这些捕获的辉光能够为受灾的族人找到治愈的方法—...",kw={"空铅瓶","放射性尘埃","gnogaine","诺莫瑞根","卡拉诺斯","铅瓶","奥齐·电环","辐射"},ang={["profession:Engineering"]="铅瓶展示了直接的侏儒式实用主义：重金属辐射屏蔽与旨在安全收集挥发性环境微粒的吸取装置相结合。",["race:Gnome"]="诺莫瑞根的毁灭对于流亡的侏儒来说仍然是一道无法愈合的伤口，这使得任何试图逆转有毒尘埃的实验尝试都伴随着巨大的个人风险，无论这位研究者看起来有多么古怪。"},sec={{t="屏蔽容器",b="当诺莫瑞根的通风口向这座地下城市排放有毒辐射以清除穴居人威胁时，它反而将幸存的守卫变成了麻风侏儒，并使入侵的野兽受到了辐射。为了研究并逆转这种放射性尘埃，奥齐·电环制作了空铅瓶。这种特制的瓶子由厚重的铅制成，用以屏蔽使用者免受周围环境的危险，它可以吸入徘徊在诺莫瑞根废墟中游荡的受辐射的入侵者和掠夺者身上的有害绿色辉光。一旦密封，由此产生的装满的铅瓶将提供实验性治疗所需的原始且危险的物质。"}},faq={{q="这个瓶子是用来做什么的？",a="这个瓶子用于在诺莫瑞根地面隧道附近吸取并储存来自受辐射的入侵者和受辐射的掠夺者身上的危险放射性尘埃。将尘埃密封在瓶中，它就会变成装满的铅瓶以供研究。",al={"瓶子的用途","如何使用空铅瓶","瓶子的目的"}},{q="为什么瓶子要用铅制成？",a="诺莫瑞根内部的放射性尘埃对于没有防护的生物来说是致命的，会导致严重的辐射病，甚至将侏儒变成麻风侏儒。厚重的铅结构起到了保护屏障的作用，使收集者免受内部挥发性发光污染物的伤害。",al={"为什么使用铅瓶","为什么是铅制的"}},{q="是谁创造了这个收集装置？",a="这个瓶子由侏儒技师奥齐·电环提供，他在丹莫罗的卡拉诺斯进行他那疯狂的实验。他将这种容器交给愿意冒险进入被毁城市有毒外围区域的冒险者们。",al={"谁制造了瓶子","奥齐·电环的瓶子","谁给了我这个瓶子"}},{q="奥齐希望通过收集到的尘埃实现什么目标？",a="奥齐和他的助手拉兹尔正试图为遭受灾难影响的麻风侏儒发明一种治疗方法。正如许多侏儒的事业一样，奥齐也承认这个实验配方最终可能变成一种强效朗姆酒的配方，或者仅仅是一种治疗秃顶的药剂。",al={"为什么要收集放射性尘埃","gnogaine的用途","奥齐在制作什么"}}},fx={["8d10cd55"]={q="什么是空铅瓶？",a="这是一种厚重的屏蔽容器，专门用于采集并安全保存诺莫瑞根废墟中受污染生物释放的放射性沉降物。瓶身由厚铅制成，可以保护携带者免受危险的翡翠色光芒侵害。侏儒研究人员借助它采集有毒残留物时，就不会染上扭曲这座沦陷之城的疾病。",al={"什么是空铅瓶","铅制采集瓶","诺莫瑞根的空瓶"}}},fp="29,402,17.628.0,27.257.0,30.287.0,35.227.0,59.272.0"}
P.entries["item:empty-red-waterskin"] = {n="空的红色水囊",s="空的红色水囊是萨满祭司在进行元素试炼时被托付的一种皮制容器。它被用于从塔伦米尔这个饱受瘟疫蹂躏的城镇中一个令人惊讶的水源处收集新鲜、未受污染的水。",h="空的红色水囊是萨满祭司在进行元素试炼时被托付的一种皮制容器。它被用于从塔伦米尔这个饱受瘟疫蹂躏的城镇中一个令人惊讶的水源处收集新鲜、未受污染的水。",kw={"布莱恩","call of water","空的红色水囊","希尔斯布莱德丘陵","塔伦米尔","water sapta"},ang={["class:Shaman"]="携带并装满这个水囊是掌握水之图腾以及将你的感官与水的坚韧灵魂协调一致的基础步骤。",["race:Orc"]="布莱恩将塔伦米尔那口纯净的水井比作大酋长萨尔——一个在巨大的苦难中依然屹立不倒、充满力量与希望的灯塔。"},sec={{t="纯净之水的容器",b="这个朴素的红色水囊是由贫瘠之地的隐士布莱恩交给试炼者的，它在Call of Water试炼中具有至关重要的精神用途。受训者需要带着它远渡重洋前往希尔斯布莱德丘陵，寻找塔伦米尔镇。尽管该镇已被被遗忘者占领并笼罩在亡灵气息之中，但其中心的一口孤井依然涌出甘甜、纯净的泉水。装满这个红色水囊可以获取一份在枯萎中顽强生存的生命样本，布莱恩将其混合成一瓶最纯净的水，用于受训者的试炼。"}},faq={{q="空的红色水囊有什么用途？",a="它被执行Call of Water任务线的萨满祭司用来从塔伦米尔的水井中收集泉水，并将其转化为装满水的红色水囊。",al={"空的红色水囊用途","红色水囊做什么"}},{q="谁提供了这个水囊？",a="生活在南贫瘠之地山丘上的兽人萨满隐士布莱恩，将其交给正在进行元素试炼的萨满受训者。",al={"谁给红色水囊","红色水囊任务发布者"}},{q="为什么专门要从塔伦米尔采集泉水？",a="尽管塔伦米尔已经落入被遗忘者的控制之下，但中心的水井依然完全未受腐蚀。布莱恩将这股纯净的泉水视为一种强大的元素象征，代表着希望以及在这片不洁之地中顽强存续的生命力。",al={"为什么是塔伦米尔的水","塔伦米尔水井背景"}},{q="水囊装满后会发生什么？",a="一旦在水井处装满，水囊必须被带回贫瘠之地交给布莱恩，他会将这些水与其他珍稀样本混合制成一瓶最纯净的水，水之先知伊斯伦随后会利用它来制造Water Sapta。",al={"红色水囊下一步","装满水的红色水囊交还"}}},fx={["29d0aa45"]={q="什么是空的红色水囊？",a="这是一只交给参加Call of Water试炼的萨满祭司学徒的空容器。它专为长途运送液体而制，具体用途是在希尔斯布莱德丘陵收集并保存纯净的井水，以便之后将其制成元素Sapta。",al={"什么是空的红色水囊","红色水囊物品","空的红色水囊背景"}}},fp="19,210,23.545.0,41.150.0,28.131.0,47.229.0,43.207.0"}
P.entries["item:empty-sampling-tube"] = {n="空的水样试管",s="“空的水样试管”是由奥伯丁的桑德里斯·织风提供的一只玻璃小瓶。它的用途是采集壁泉河中被腐蚀的水样，以便暗夜精灵学者研究正在威胁黑海岸的蔓延污染。",h="“空的水样试管”是由奥伯丁的桑德里斯·织风提供的一只玻璃小瓶。它的用途是采集壁泉河中被腐蚀的水样，以便暗夜精灵学者研究正在威胁黑海岸的蔓延污染。",kw={"奥伯丁","壁泉河","黑海岸","空的水样试管","薄雾海","桑德里斯·织风","水样"},ang={["class:Druid"]="水样试管代表了早期诊断费伍德森林恶魔污染的努力，这种污染正在渗入黑海岸原始的河流，并使当地野生动物染病。",["race:NightElf"]="对于奥伯丁的暗夜精灵来说，检测壁泉河对于防止腐蚀性径流毒害他们位于薄雾海的海岸避风港至关重要。"},sec={{t="试水",b="随着黑海岸的荒野屈服于蔓延的枯萎病，天然水道已经开始变质。驻扎在奥伯丁的调查员桑德里斯·织风提供了这只空的玻璃试管，用于从壁泉河采集确凿的证据。从镇北第一道瀑布下方的水潭中提取出的样本，可以让暗夜精灵自然学家检查正冲向薄雾海的腐蚀本质。"},{t="追查源头",b="尽管敌对的黑木熊怪居住在河岸边的营地中，但织风怀疑他们只是受害者和传播媒介，而非这种腐败的最终源头。装满试管证实了污染物是从东面受污染的费伍德森林高地流下的。采集到的样本为研制潜在的治疗方法和准备针对枯萎病的直接反制措施奠定了基础。"}},faq={{q="空的水样试管有什么用途？",a="这是一种密封的玻璃容器，用于从奥伯丁北部的壁泉河采集水样。采集到的样本会被带给桑德里斯·织风，以便他分析在黑海岸蔓延的污浊物质。",al={"为什么要给我这只试管","水样试管有什么用","试管的用途"}},{q="水样应该在哪里采集？",a="试管必须在壁泉河的第一道瀑布处装满，该处位于奥伯丁以北的一座桥下，正好是水流在汇入薄雾海之前形成水潭的地方。",al={"在哪里装满试管","壁泉河位置","水样采集点"}},{q="谁提供了这只试管？",a="桑德里斯·织风，一位正在研究奥伯丁周围环境威胁的暗夜精灵自然学家，将试管交给了愿意勇闯这片受污染荒野的冒险者。",al={"谁给的试管","试管任务发布者","桑德里斯·织风"}},{q="是什么污染了壁泉河？",a="虽然当地的黑木熊怪居住在河岸边并加剧了污染，但这种污秽腐败的真正源头是位于东面高山之上的受污染的费伍德森林。",al={"为什么河水是绿色的","是什么腐蚀了水","壁泉河污染"}}},fx={["54012ea9"]={q="什么是空的水样试管？",a="这是一只干净且经过特殊处理的玻璃瓶，由你用来采集壁泉河的水。桑迪斯·织风需要一只未受污染的容器，以便采集一份纯净样本，检测目前正向奥伯丁以北海域流去的污秽水流。",al={"什么是空的水样试管","空试管背景","关于空的水样试管"}},b354763d={q="桑迪斯为什么要用这只试管采集样本？",a="黑海岸的水域正在迅速变得有害，桑迪斯怀疑顺着壁泉河流下的污秽污染已抵达奥伯丁海岸。他希望检查用这只容器采集的新鲜样本，判断污染究竟来自当地的黑木熊怪，还是来自东部费伍德森林高地更深的腐化。这样，暗夜精灵就能据此采取应对措施。",al={"为什么需要空的水样试管","为什么采集峭壁之泉的水","桑迪斯为什么要样本"}}},fp="19,232,18.435.0,18.407.1,47.229.0,47.192.0,23.170.0,40.201.1"}
P.entries["item:empty-water-tube"] = {n="空水瓶",s="空水瓶是一个简单的玻璃容器，是在奥伯丁提供的，用于收集神圣的月亮井水。它旨在将这充满祝福的液体带到黑海岸东部悬崖上那块奇异的红色水晶处。",h="空水瓶是一个简单的玻璃容器，是在奥伯丁提供的，用于收集神圣的月亮井水。它旨在将这充满祝福的液体带到黑海岸东部悬崖上那块奇异的红色水晶处。",kw={"倾泻圣水","奥伯丁","黑海岸","空水瓶","费伍德森林","月亮井","月亮井水瓶","红色水晶"},ang={["class:Druid"]="德鲁伊对月亮井怀有深深的敬意，依靠其未受污染的井水来研究异常现象，并净化从费伍德森林等被腐蚀土地侵蚀而来的奇异干扰。",["race:NightElf"]="处理神圣的月亮井水是卡多雷的神圣职责，他们将月亮井视为女神艾露恩祝福的圣洁水库。"},sec={{t="祝福之水的容器",b="研究黑海岸东部山脊上那块神秘红色水晶的哨兵和学者们需要纯净的月亮精华来测试其性质。由于普通的玻璃或烧瓶很容易污染圣水，这个密封的小瓶被专门交给了前往奥伯丁月亮井的调查人员。装满后，其中的液体会被带到山坡上，以观察外来的矿物对艾露恩的魔法有何反应。"},{t="探查费伍德森林的阴影",b="黑海岸以东的山脉与费伍德森林接壤，那是一片被恶魔腐蚀彻底毒害的领域。奥伯丁的守卫者怀疑悬崖附近那块不祥的深红色巨石与那片荒废的森林有着某种邪恶的联系。研究人员希望通过将月亮井水倾倒在水晶的晶格上，圣水能揭示水晶的内部结构，而不会引发内部所蕴含力量的灾难性释放。"}},faq={{q="空水瓶的用途是什么？",a="这是一个空容器，在奥伯丁交给你，用于直接从定居点的月亮井中汲取井水，这是分析在黑海岸东部高地上发现的奇异红色水晶所必需的。",al={"空水瓶用途","为什么我有空水瓶","如何使用水瓶"}},{q="应该在哪里装满水瓶？",a="它必须浸入位于奥伯丁的月亮井中。装满后，该物品将变为月亮井水瓶。",al={"哪里装满水瓶","空水瓶装水位置","水瓶装水地点"}},{q="为什么水晶需要月亮井水？",a="月亮井水蕴含着艾露恩强大且纯净的魔法。学者们相信将其浇在神秘的红色水晶上，会与其表面发生反应，并揭示有关其起源和组成的线索。",al={"为什么需要月亮井水","月亮井水对水晶的作用","红色水晶与月亮井水"}},{q="为什么奥伯丁的居民担心这块水晶？",a="这块水晶坐落在俯瞰费伍德森林的高脊附近，那是一片被燃烧军团严重腐蚀的森林。当地的观察者担心，如果这块水晶与那片被污染的荒野有关，它可能会对黑海岸构成严重威胁。",al={"水晶是否危险","黑海岸水晶危险性","为什么要调查红色水晶"}}},fx={["8160d8ef"]={q="什么是空水瓶？",a="这是一只普通的空玻璃瓶，在奥伯丁交给你，用来采集村中的月亮井之水。装满之后，你会用其中受祝福的水，测试那块靠在黑海岸山脉旁的神秘异界红色水晶。",al={"什么是空水瓶","空水瓶","采集月亮井之水的瓶子"}}},fp="16,215,27.424.0,24.452.1,44.200.0,32.121.0,45.199.0,56.227.0"}
P.entries["item:enchanted-gaea-seeds"] = {n="附有魔法的盖亚之种",s="附有魔法的盖亚之种是特别准备的植物种子，旨在为卡利姆多遭受破坏的土地带来复苏。它们通过德鲁伊魔法进行强化，并在烈日石居收集，直接播种在焦炭谷布满灰烬的土壤中，以抵御破坏并重新点燃自然生机。",h="附有魔法的盖亚之种是特别准备的植物种子，旨在为卡利姆多遭受破坏的土地带来复苏。它们通过德鲁伊魔法进行强化，并在烈日石居收集，直接播种在焦炭谷布满灰烬的土壤中，以抵御破坏并重新点燃自然生机。",kw={"焦炭谷","附有魔法的盖亚之种","盖亚之种","重生","石爪山脉","烈日石居","tammra windwhisper"},ang={["class:Druid"]="这些种子展现了德鲁伊培育重生循环的基本职责，积极地引导坚韧的生命回到这个被毁灭和野火所吞噬的领域。",["race:Tauren"]="对于烈日石居的舒哈鲁来说，播种这些附有魔法的种子是一种精神上的管理行为，旨在向大地母亲致敬并收复伤痕累累的土地。"},sec={{t="灰烬中的火花",b="附有魔法的盖亚之种代表了部落通过德鲁伊之道，试图修复石爪山脉所留下的深深创痕。原始的盖亚之种在烈日石居被收集并由塔姆拉·荒原进行仪式化的附魔后，它们便拥有了足够的韧性来克服普遍的腐蚀和元素枯萎。当这些种子被植入焦炭谷灰烬之下尚存的肥沃土堆时，它们能在恶劣的环境中扎根，在这片被敌对火元素和入侵鹰身人所占据的土地上锚定新的生命。"},{t="复苏的承诺",b="播种这些附有魔法的种子的目标远不止是简单的园艺；这是一场旨在扭转石爪山脉未来争夺战局势的积极行动。编织进外壳中的魔法使它们能够抵御残留的腐化，并为原生植物群建立立足点。随着它们的繁茂生长，恢复后的植被旨在安抚焦躁的火元素，挤压野性鹰身人的生存空间，并对抗由荆棘谷地精无休止的伐木作业所导致的肆虐森林砍伐。"}},faq={{q="附有魔法的盖亚之种有什么用途？",a="它们被播种在焦炭谷的肥沃土堆中。其目的是萌发出能够抵御环境腐化并开始治愈被火灾和战争摧毁的土地的坚韧植物。",al={"盖亚之种的用途","附有魔法的盖亚之种的作用","为什么要播种盖亚之种"}},{q="是谁创造或施法强化了这些种子？",a="原始的盖亚之种是从周围的荒野中收集而来，并被带到烈日石居的塔姆拉·荒原那里。她对这些种子进行附魔，使它们能够在焦炭谷充满灰烬的恶劣土壤中存活。",al={"谁制作了这些种子","tammra windwhisper的种子","盖亚之种是如何制作的"}},{q="为什么必须将它们播种在焦炭谷？",a="焦炭谷是石爪山脉生态破坏的中心，到处都是愤怒的火元素和鹰身人。直接将其种子播种在残存的土堆中，能引入至关重要的生命力，从而起到平息该地区混乱的作用。",al={"我该在哪里播种它们","为什么是焦炭谷","焦炭谷播种"}},{q="播下的种子面临着哪些威胁？",a="焦炭谷深受烈火中诞生的敌对火元素、在废墟中筑巢的侵略性血怒鹰身人，以及附近荆棘谷地精所带来的工业破坏的困扰。",al={"焦炭谷中的危险","是什么在摧毁这片土地"}}},fx={["2eba8b82"]={q="什么是附有魔法的盖亚之种？",a="附有魔法的盖亚之种是由烈日石居的塔姆拉·荒原准备的坚韧种子，经过魔法处理，能够抵御环境污染。它们是强大的重生催化剂，能在遭到破坏的土地上扎根，开启漫长的焦土复原过程。",al={"什么是附有魔法的盖亚之种","附有魔法的盖亚之种背景"}}},fp="20,320,20.549.0,22.493.0,39.206.0,37.200.0,45.253.0,36.204.0"}
P.entries["item:enchanted-resonite-crystal"] = {n="魔化共鸣水晶",s="魔化共鸣水晶是一种经过炼金术改造的矿物，由摩罗加尔在石爪山脉中注入了萨满魔法。它专门用于击碎束缚着一位沉睡的远古土灵Goggeroc的共鸣水晶桶。",h="魔化共鸣水晶是一种经过炼金术改造的矿物，由摩罗加尔在石爪山脉中注入了萨满魔法。它专门用于击碎束缚着一位沉睡的远古土灵Goggeroc的共鸣水晶桶。",kw={"土灵苏醒","魔化共鸣水晶","goggeroc","摩罗加尔","共鸣水晶桶","共鸣水晶","石爪山脉"},ang={["class:Shaman"]="这块水晶展示了元素操控如何能够破坏即便由泰坦造物所创造、束缚着活体岩石的远古大地魔法。",["faction:Horde"]="石爪山脉的平衡岌岌可危，摩罗加尔依靠部落勇士在远古威胁危及区域哨所之前将其消除。"},sec={{t="远古之石的粉碎者",b="从石爪山脉深处洞穴中收集的原始共鸣水晶拥有独特的谐振和大地属性。萨满祭司摩罗加尔意识到封印在地下暗桶中的沉睡生物所带来的危险，利用他的元素力量改造了这些原始矿物。最终制成的魔化共鸣水晶是一种精密的工具：当它撞击加强型的共鸣水晶桶时，会破坏其外壳，并强行唤醒巨大的土灵Goggeroc，此时他因长久的沉睡而神志不清。"},{t="Goggeroc的威胁",b="摩罗加尔认为，若任由一位远古土灵自由行动，将给石爪山脉乃至整个卡利姆多的脆弱平衡带来灾难。通过用魔化共鸣水晶击碎水晶桶，摩罗加尔旨在迫使该生物在虚弱状态下苏醒，从而获得一个短暂的机会窗口，在其完全恢复元素力量之前消灭Goggeroc。"}},faq={{q="魔化共鸣水晶有什么用途？",a="它用于击碎石爪山脉中狗头人出没的洞穴深处的共鸣水晶桶，从而释放出沉睡的土灵Goggeroc。",al={"魔化共鸣水晶用途","水晶有什么用","击碎共鸣水晶桶"}},{q="这块魔化水晶是谁制造的？",a="牛头人萨满祭司摩罗加尔制造了它，他将萨满力量注入原始共鸣水晶中，以削弱并暴露水晶桶内沉睡的实体。",al={"谁制造了水晶","摩罗加尔的水晶","魔化共鸣水晶制造者"}},{q="为什么要唤醒并消灭Goggeroc？",a="摩罗加尔担心，若任由一位远古土灵的无敌力量横行，将危及整个石爪山脉和卡利姆多。用水晶唤醒他会使他暂时虚弱，从而有可能将其击败。",al={"为什么要杀goggeroc","goggeroc危险吗","goggeroc的威胁"}},{q="在击败Goggeroc后，我该如何处理这块水晶？",a="你必须将魔化共鸣水晶带回给摩罗加尔，并告知他Goggeroc已被击杀。",al={"归还共鸣水晶","上交魔化共鸣水晶"}}},fx={ed58de6b={q="什么是魔化共鸣水晶？",a="这是一种经过改造的矿物护符，由烈日石居的摩罗加尔注入萨满祭司的力量。共鸣水晶是石爪山脉洞穴中天然生成的矿物。经过魔法改造后，这块水晶便成为专门用来击碎共鸣水晶桶的钥匙和锤子；沉睡的土灵巨人Goggeroc正被关在桶中。",al={"什么是魔化共鸣水晶","魔化共鸣水晶背景","共鸣水晶的含义"}},d1731b4b={q="摩罗加尔为什么想要魔化共鸣水晶？",a="摩罗加尔需要这块水晶，在土灵Goggeroc完全苏醒前将其释放并消灭。他担心一旦土灵挣脱束缚，便会带来无可匹敌的灾难，毁灭整个石爪山脉。击碎桶子会让Goggeroc在极度虚弱的状态下苏醒，这样你才有唯一可行的机会将它击倒。",al={"为什么想要魔化共鸣水晶","摩罗加尔为什么需要水晶","为什么需要魔化共鸣水晶"}}},fp="26,245,24.511.0,22.360.1,48.158.1,35.158.0,44.223.0,59.117.0"}
P.entries["item:encrypted-memorandum"] = {n="密文备忘录",s="《密文备忘录》是一份交给寒脊山谷新手潜行者的加密信件。尽管它伪装成公文，但实际上却是当地潜行者训练师索姆·哈格林发出的秘密邀请，号召流亡的无赖们团结一致。",h="《密文备忘录》是一份交给寒脊山谷新手潜行者的加密信件。尽管它伪装成公文，但实际上却是当地潜行者训练师索姆·哈格林发出的秘密邀请，号召流亡的无赖们团结一致。",kw={"安威玛尔","寒脊山谷","丹莫罗","密文备忘录","诺莫瑞根","潜行者训练师","索姆·哈格林"},ang={["class:Rogue"]="这封加密信件是你被传唤进入丹莫罗阴影中的正式凭证，它能让你直接与安威玛尔的当地训练师取得联系。",["race:Gnome"]="诺莫瑞根陷落后，侏儒潜行者作为难民生活在矮人中间，他们在这张便条中发现了一种关于团结与生存的静默邀约。"},sec={{t="隐秘的传唤",b="在熙熙攘攘的矮人避难所安威玛尔，潜行者必须保持低调。训练师索姆·哈格林并没有在大庭广众之下接触新兵，而是利用《密文备忘录》来建立联系。这份加密的羊皮纸伪装成来自远方上级的官方指令，确保初出茅庐的潜行者在不引起当地卫兵或多疑镇民注意的情况下，知道去哪里寻找指导。"},{t="寒脊山谷的情谊",b="密码之下隐藏着生存的实用信息。随着诺莫瑞根陷落，流离失所的侏儒被挤进丹莫罗冰雪覆盖的定居点，与他们的矮人盟友并肩生活，紧张局势一触即发。索姆利用这张便条建立起一种安静的同志情谊，提醒他的学生们，当替罪羊和偏见让他们被指责为每件丢失饰品的罪魁祸首时，同行们必须互相照应。"}},faq={{q="什么是《密文备忘录》？",a="这是一份交给寒脊山谷新手潜行者的加密羊皮纸，以官方公文为幌子，指示他们去寻求潜行者训练。",al={"什么是密文备忘录","备忘录物品","潜行者便条"}},{q="是谁写了这份备忘录？",a="它由驻扎在安威玛尔的潜行者训练师索姆·哈格林起草，他将其伪装成官方命令，以便谨慎地召集他的无赖同僚。",al={"谁写了备忘录","谁发送了密文备忘录","备忘录作者"}},{q="为什么要加密这份信息？",a="在寒脊山谷活动的潜行者要避免公众的审视。将邀请伪装成例行的官僚备忘录，可以防止当地当局和爱管闲事的旁观者注意到秘密的训练活动。",al={"为什么加密","为什么要编码","为什么它是加密的"}},{q="索姆·哈格林想要什么？",a="索姆想要提供战斗训练、指导和相互保护，并强调在拥挤的丹莫罗，小偷很快就会被指责偷窃物品，因此潜行者必须团结一致。",al={"索姆想要什么","为什么要寻找索姆","索姆的目的"}}},fx={["88db5375"]={q="为什么有人想要密文备忘录？",a="这份备忘录只写给你。寒脊山谷的潜行者训练师索姆·哈格林将它作为邀请，送给与你从事相同技艺的同道。它伪装成正式信函，目的是让你与他接触，同时不引起安威玛尔当地人的无谓注意。",al={"为什么想要密文备忘录","谁想要密文备忘录","密文备忘录的用途"}}},fp="20,279,18.422.0,20.439.1,33.159.0,26.156.0,29.198.0,28.187.0"}
P.entries["item:encrypted-parchment"] = {n="密文羊皮纸",s="密文羊皮纸是一封发给在试炼谷受训的兽人潜行者新手的加密密函。这封信由高内克递交，它指引有潜力的招募者悄悄进入大兽穴的阴影中，去见那位隐秘的训练师鲁瓦格。",h="密文羊皮纸是一封发给在试炼谷受训的兽人潜行者新手的加密密函。这封信由高内克递交，它指引有潜力的招募者悄悄进入大兽穴的阴影中，去见那位隐秘的训练师鲁瓦格。",kw={"杜隆塔尔","密文羊皮纸","高内克","兽人潜行者","鲁瓦格","碎手氏族","大兽穴","试炼谷"},ang={["class:Rogue"]="这张羊皮纸代表着你被引入部落的隐秘地下世界，它将你指引向隶属于碎手氏族的导师。",["race:Orc"]="虽然兽人文化通常推崇公开、荣耀的战斗，但这份密函欢迎那些在更安静、更致命的生存艺术方面拥有天赋的人。"},sec={{t="来自阴影的召唤",b="在试炼谷寻求证明自己武力的年轻兽人通常在阳光下公开战斗。然而，那些表现出潜行、欺诈和用刃技巧天赋的兽人会吸引一种截然不同的注意。当兽人潜行者新手在面对当地野兽完成了初步磨练后，高内克会将密文羊皮纸交给他们。这份消息并非公开通告，而是经过编码，以确保只有那些具备潜行洞察力的人才会响应召唤。"},{t="与碎手氏族的联系",b="解读这份羊皮纸会将新手引向被称为大兽穴的洞穴深处，避开其他氏族训练师的注视，找到鲁瓦格。在那里，招募者会得知这次召唤是代表碎手氏族安排的——这是一个在部落秘密网络中运作的组织。通过响应羊皮纸的召唤，潜行者迈出了进入间谍活动、暗影技巧和严密秘密世界的第一步。"}},faq={{q="密文羊皮纸的用途是什么？",a="它作为一封加密的召唤函，将兽人潜行者新手引荐给他们的职业训练师鲁瓦格，此人就潜伏在试炼谷的大兽穴中。",al={"什么是密文羊皮纸","羊皮纸的用途","为什么要有密文羊皮纸"}},{q="是谁把羊皮纸送给你的？",a="这份消息出自潜行者训练师鲁瓦格之手，不过是在你在试炼谷完成初步试炼后由高内克递交给你的。",al={"谁写了羊皮纸","羊皮纸发送者","谁给了我羊皮纸"}},{q="为什么消息要用暗语编写？",a="鲁瓦格和他在碎手氏族内的联络人更倾向于秘密行事，而非公开宣告。加密信息确保了只有适合潜行者这种隐秘之道的人，才会被引导进入他们隐藏的行列。",al={"为什么要加密","为什么加密","秘密信息"}},{q="这次召唤背后的组织是什么？",a="鲁瓦格透露，碎手氏族曾要求他留意有能力的招募者。他们提供潜行和间谍活动的训练，以便从阴影中为部落服务。",al={"谁想训练我","碎手氏族潜行者","哪个阵营发送了这封信"}},{q="巨魔潜行者可以使用这张羊皮纸吗？",a="不能。虽然巨魔潜行者也从试炼谷开始冒险，但他们的秘密召唤是以密文石板的形式呈现的，而不是这份羊皮纸。",al={"巨魔密文羊皮纸","巨魔也能用吗"}}},fx={["268fdb07"]={q="什么是密文羊皮纸？",a="密文羊皮纸是一封密信，专门送给在试炼谷证明了自身实力、前途可期的年轻兽人盗贼。信上使用盗贼黑话或密码书写，以免被窥探者发现；它指引你去寻找训练师鲁瓦格，他藏身于大兽穴的阴影之中。",al={"什么是密文羊皮纸","密文羊皮纸物品","这张羊皮纸是什么"}},fa1aab52={q="为什么要把密文羊皮纸交给你？",a="这份羊皮纸送到你手中，是因为你引起了碎手氏族的注意。碎手氏族是为部落效力的刺客与斥候组织。他们想让你加入其中，传授你致命的技艺，并确保你知道如何找到他们的秘密行动人员鲁瓦格。",al={"为什么需要密文羊皮纸","为什么是密文羊皮纸","密文羊皮纸的用途"}}},fp="19,237,26.478.0,26.406.0,47.146.0,31.142.0,37.203.0,40.169.0,36.151.0"}
P.entries["item:encrypted-rune"] = {n="密文符文",s="密文符文是一则编码过的召唤信息，会发给寒脊山谷中崭露头角的盗贼新秀。这封密件要求持有人解读其内容，并前往安威玛尔寻找盗贼训练师索姆·哈格林。",h="密文符文是一则编码过的召唤信息，会发给寒脊山谷中崭露头角的盗贼新秀。这封密件要求持有人解读其内容，并前往安威玛尔寻找盗贼训练师索姆·哈格林。",kw={"安威玛尔","密码","寒脊山谷","丹莫罗","密文符文","盗贼","索姆·哈格林"},ang={["class:Rogue"]="这枚符文标志着你与丹莫罗的盗贼网络建立的第一次正式接触，它将引导你步入潜行、快刀和生存艺术的殿堂。",["race:Dwarf"]="这枚符文在寒脊山谷中流传，召唤另一位铁炉堡的孩子去掌握阴影，并从地表之下守护氏族的利益。"},sec={{t="加密的召唤",b="在寒脊山谷隐蔽的雪盆地中，当地的恶棍和斥候很少采用大张旗鼓的招募方式。相反，那些展现出潜行和狡诈天赋的新手会悄悄收到一枚密文符文。这块刻有隐晦密码的石头传达了安威玛尔的盗贼导师索姆·哈格林的秘密邀请。它既是对盗贼行话读写能力的私人测试，也是对在丹莫罗严酷荒野中生存所需的阴影之术的引荐。"},{t="阴影之眼",b="解读符文会引导新晋盗贼前往索姆处，他正寻求在当地日益紧张的局势中加强山谷的隐秘力量。除了基础的刀剑技巧和潜行手法，索姆还强调警惕性和同志情谊，提醒新加入的盗贼，在这个局势紧绷的和平时期，他们这类人团结一致显得尤为重要。"}},faq={{q="什么是密文符文？",a="这是一种发送给寒脊山谷盗贼新手的编码信息，指示他们前往安威玛尔向索姆·哈格林报到并接受训练。",al={"这个符文是什么","密文符文的用途","这个符文有什么用"}},{q="是谁发送了密文符文？",a="这条信息来自驻扎在安威玛尔的盗贼训练师索姆·哈格林，他利用符文悄悄召集新兵，以免引起不必要的注意。",al={"谁写的","谁给的","符文发送者"}},{q="我应该把符文带到哪里去？",a="将解读后的指令带给索姆·哈格林，他就在寒脊山谷的安威玛尔室内。",al={"我该去哪","我该交给谁","索姆在哪里"}},{q="为什么信息要加密？",a="盗贼依靠隐秘、欺诈和秘密通讯。发送加密符文能确保只有具备解读密码能力的准盗贼才会响应召唤，从而让他们的行事方式不被外人窥见。",al={"为什么用密码","为什么是编码信息","为什么符文要保密"}}},fx={["1ca7ae1e"]={q="为什么要把密文符文寄给你？",a="安威玛尔的盗贼训练师索姆·哈格林寄来符文，以引起你这位寒脊山谷新秀盗贼的注意。丹莫罗的骚乱日益增多，他正在矮人和侏儒中物色能干的人手——他们懂得如何让刀锋保持冰冷、如何隐入阴影。他邀请你去找他，接受进一步训练。",al={"为什么有密文符文","索姆为什么寄来密文符文","密文符文的用途"}}},fp="14,223,15.503.0,19.341.0,27.145.0,28.165.0,29.107.0,29.209.0"}
P.entries["item:encrypted-scroll"] = {n="密文卷轴",s="密文卷轴是一份交给丧钟镇中崭露头角的亡灵盗贼新人的隐秘卷轴。它带有大卫·提亚斯的印章，指示接收者前往报到，以便在被遗忘者的秘密行动特工中接受正式训练。",h="密文卷轴是一份交给丧钟镇中崭露头角的亡灵盗贼新人的隐秘卷轴。它带有大卫·提亚斯的印章，指示接收者前往报到，以便在被遗忘者的秘密行动特工中接受正式训练。",kw={"大卫·提亚斯","丧钟镇","密文卷轴","被遗忘者盗贼","盗贼训练师","shadowstalkers","提瑞斯法林地"},ang={["class:Rogue"]="这份卷轴标志着你在被遗忘者盗贼骨干的注视下，开始潜行、开锁和阴险战斗的专业训练。",["race:Undead"]="对于丧钟镇刚复活的人来说，这份征召代表了一个尽早获得希尔瓦娜斯新兴王国中重要角色的机会。"},sec={{t="一份秘密征召",b="当刚苏醒的被遗忘者展现出潜行和诡计天赋时，他们很快就会被发掘。一旦斥候证明了自己有能力对抗在附近墓地徘徊的无脑天灾军团，就会在丧钟镇收到这份密文卷轴。卷轴上盖着盗贼训练师大卫·提亚斯的个人印章，指示持有者前往当地旅店寻找他。这起到了初步筛选的作用，指引这些初出茅庐的特工去学习效忠黑暗女王所需的纪律，而不是把第二次生命浪费在当个普通扒手上。"},{t="Shadowstalkers的注视",b="消息本身很简短，指示盗贼在深入提瑞斯法林地之前先在丧钟镇建立联系。提亚斯代表Shadowstalkers，即被遗忘者的秘密分支，关注着新出现的人才。为了在洛丹伦生存，被遗忘者严重依赖无声的利刃和狡猾的斥候来对抗血色十字军、幸存的联盟飞地和遗留的天灾军团残渣。响应这份加密的征召是加入那个秘密网络的第一步。"}},faq={{q="密文卷轴的用途是什么？",a="密文卷轴是发给刚复活的被遗忘者盗贼的入门征召令。它指示他们向丧钟镇旅店的大卫·提亚斯报到，以开始他们的专业盗贼训练。",al={"密文卷轴的作用","为什么要用密文卷轴","卷轴用途"}},{q="谁发送了密文卷轴？",a="该卷轴带有大卫·提亚斯的个人印章，他是驻扎在丧钟镇的常驻盗贼训练师，负责留意有前途的新兵。",al={"谁写的卷轴","卷轴发送者","卷轴来自谁"}},{q="大卫·提亚斯提到的Shadowstalkers是什么？",a="Shadowstalkers是一个由被遗忘者盗贼、斥候和刺客组成的秘密组织，在洛丹伦各地活动。提亚斯负责评估新人，以确定谁有资格最终加入他们的行列。",al={"谁是shadowstalkers","被遗忘者shadowstalkers","shadowstalkers组织"}},{q="读完密文卷轴后我该把它带到哪里？",a="读完卷轴后，直接把它带给大卫·提亚斯，他就在丧钟镇的旅店里潜伏着。",al={"哪里上交卷轴","把卷轴给谁","上交卷轴"}}},fx={["0c548ac5"]={q="什么是密文卷轴？",a="密文卷轴是一封谨慎送达丧钟镇新晋盗贼手中的加密信件。卷轴上盖有盗贼训练师大卫·提亚斯的私人印章，是一份初步召集令，也是一场保密能力测试；它指引有潜力的潜行人员前来报到，以便为被遗忘者执行更深入的侦察任务。",al={"什么是密文卷轴","这卷卷轴是什么","密文卷轴信息"}},["496fc5eb"]={q="大卫·提亚斯为什么要用密文卷轴联系你？",a="大卫·提亚斯用卷轴招募并考察新晋被遗忘者中的新秀。暗影追猎者和这个新生的国度需要精明能干的潜入者，而不是笨手笨脚的扒手。他悄悄召集有潜力的新人前往丧钟镇的酒馆，确保他们接受适当的训练，并走上为黑暗女王的情报网络效力的道路。",al={"大卫·提亚斯为什么寄来卷轴","为什么需要密文卷轴","为什么用密文卷轴联系我"}}},fp="16,243,16.574.0,26.501.0,44.197.0,31.145.0,53.200.0,54.114.0"}
P.entries["item:encrypted-sigil"] = {n="密文符记",s="密文符记是传递给幽影谷中刚刚苏醒的暗夜精灵潜行者的一种加密信物。它携带着弗拉胡恩·影语者传达的隐秘指令，指引新晋的特工在泰达希尔面临日益严峻的威胁之际，开启他们的训练。",h="密文符记是传递给幽影谷中刚刚苏醒的暗夜精灵潜行者的一种加密信物。它携带着弗拉胡恩·影语者传达的隐秘指令，指引新晋的特工在泰达希尔面临日益严峻的威胁之际，开启他们的训练。",kw={"奥达希尔","密文符记","弗拉胡恩·影语者","卡多雷潜行者","潜行者训练师","幽影谷","泰达希尔"},ang={["class:Rogue"]="这枚符记代表了暗夜精灵潜行者旅程的起点，旨在测试你解读指令并与当地导师建立联系的能力。",["race:NightElf"]="对于卡多雷而言，隐蔽的特工在这样一个脆弱的时代提供了至关重要的情报，而古老的林地边界正面临着来自部落的全新侵犯。"},sec={{t="隐藏的召唤",b="在幽影谷那受到庇护的山谷中，刚刚崭露头角的暗夜精灵侦察兵和潜行者会通过谨慎的方式得到联络。密文符记由一名沉默的信使代表弗拉胡恩·影语者直接交到初学者的手中。该符记以符合职业需求的方式掩盖了其内容，指引接受者前往奥达希尔附近向弗拉胡恩报到。对于影语者来说，能够阅读并交付这枚符记，证明了初学者能够遵循隐晦的指示并处理隐秘的信件。"},{t="阴影中的注视",b="弗拉胡恩利用这道召唤来强调在一个动荡的世界中潜行者所必需的重要性。随着暗夜精灵与远方部落之间的紧张局势日益加剧，影语者提醒他的新兵，公开的战争并不是他们的人民所面临的唯一危险。潜行者必须作为卡多雷早期预警的眼睛和无形的利刃，在泰达希尔全境搜集情报，并学会在威胁在世界之树的枝干上扎根之前就给予打击。"}},faq={{q="密文符记的用途是什么？",a="它是针对暗夜精灵潜行者新手的入门召唤。它携带着隐秘的指令，指引持有者前往奥达希尔附近向弗拉胡恩·影语者报到，从而开始正式的潜行者训练。",al={"符记有什么用","密文符记是干什么用的","为什么我会有密文符记"}},{q="是谁发送了密文符记？",a="这枚符记是由弗拉胡恩·影语者派发的，他是一位驻扎在幽影谷、奥达希尔树枝下的潜行者训练师。",al={"是谁写了这枚符记","是谁发送了密文符记","这枚符记来自谁"}},{q="弗拉胡恩·影语者找我有什么事？",a="弗拉胡恩希望评估你的准备情况，强调威胁暗夜精灵的日益增长的危险——包括部落引发的潜在不和——并提供基础的战斗指导。",al={"为什么弗拉胡恩需要我","弗拉胡恩任务","为什么要和弗拉胡恩谈话"}},{q="阅读符记后我应该把它带到哪里？",a="把它带给弗拉胡恩·影语者，你可以在幽影谷的奥达希尔大树中找到他。",al={"把密文符记带到哪里","弗拉胡恩位置","弗拉胡恩在哪里"}}},fx={f0a92b78={q="什么是密文符记？",a="密文符记是一封加密信件，送给在幽影谷踏上旅程、前途可期的暗夜精灵盗贼。符记上刻有隐秘文字，以防敏感信息被窥探者发现；这是当地盗贼训练师弗拉胡恩·影语者发出的正式召集令，他希望评估并指导新人，以应对族人面临的阴影挑战。",al={"什么是密文符记","密文符记背景","符记有什么用"}},["66ac44ca"]={q="弗拉胡恩·影语者为什么要你归还密文符记？",a="弗拉胡恩·影语者要你解读符记后带回给他，以确认你已收到召集令，也懂得谨慎遵循行事规程。交还信物可以证明你的身份，并表明你已准备好开始潜行、搜集情报和使用武器的正式训练。",al={"弗拉胡恩为什么要符记","为什么归还密文符记","谁要密文符记"}}},fp="15,259,16.498.0,19.443.0,43.205.0,30.126.0,43.195.0,45.96.0"}
P.entries["item:encrypted-tablet"] = {n="密文石板",s="密文石板是一份发送给正在试炼谷接受训练的暗矛巨魔潜行者新手的加密信息。它由潜行者训练师鲁瓦格书写，旨在召集有前途的扒手和斥候前往他在大兽穴内的岗位。",h="密文石板是一份发送给正在试炼谷接受训练的暗矛巨魔潜行者新手的加密信息。它由潜行者训练师鲁瓦格书写，旨在召集有前途的扒手和斥候前往他在大兽穴内的岗位。",kw={"杜隆塔尔","密文石板","潜行者训练师","鲁瓦格","破碎手氏族","大兽穴","试炼谷"},ang={["class:Rogue"]="这块刻有密码的石板代表了你正式加入部落潜行者行列的最初引导，它指引你前往大兽穴接受鲁瓦格的训练。",["race:Troll"]="在杜隆塔尔进行训练的暗矛巨魔会收到这块石板，作为他们的敏捷和潜行技巧已经引起谷地训练师注意的证明。"},sec={{t="隐藏的召唤",b="抵达试炼谷的巨魔潜行者新手会收到密文石板，作为他们的初始指令。这块刻有密码指令的石板直接指引他们去找鲁瓦格，这是一位居住在大兽穴阴影洞穴中的兽人训练师。当地的暗影特工并不公开传播公会事务，而是利用这些加密石板来测试新人的理解能力，并悄无声息地将新人才纳入正式的教导之下。"},{t="手之眼",b="破译石板将使新兵接触到部落更庞大的暗影网络。在向鲁瓦格报到后，斥候们会了解到他们的成长受到破碎手氏族等暗影组织的审视，这些组织希望通过谷地的训练师确保未来的扒手、间谍和刺客足够敏锐，以服务于新生的国家。"}},faq={{q="密文石板有什么用途？",a="密文石板是一份加密的传唤令，指示年轻的巨魔潜行者向鲁瓦格报到，他是驻扎在试炼谷大兽穴内的当地潜行者训练师。",al={"石板用途","密文石板的作用","为什么我会有密文石板"}},{q="是谁在石板上写下了这条信息？",a="这条信息由试炼谷的潜行者训练师鲁瓦格所写，他负责监督部落盗贼、扒手和刺客的训练。",al={"谁寄出了密文石板","石板作者","谁写的这个"}},{q="我在哪里可以找到鲁瓦格？",a="鲁瓦格位于杜隆塔尔试炼谷北侧山脊的大兽穴洞穴深处。",al={"鲁瓦格在哪里","鲁瓦格位置","寻找试炼谷潜行者训练师"}},{q="鲁瓦格提到的“手”是指什么？",a="“手”指的是破碎手氏族，这是一个在部落潜行者网络中运作的秘密组织。鲁瓦格需要向他们汇报从谷地涌现的新手特工的准备情况。",al={"什么是手","谁是手","与破碎手氏族的联系"}}},fx={["395214f3"]={q="什么是密文石板？",a="密文石板是一块加密的石板，专门在你开始试炼谷的训练时送到你手中。石板经过加密，以免内容被窥探者发现；它既是一份召集令，也会考验你的机敏，并指引你去找当地的盗贼训练师。",al={"密文石板","什么是密文石板","石板物品"}},["3f134c2e"]={q="为什么要找密文石板？",a="盗贼训练师鲁瓦格寄来石板，确保新来的无赖能找到他的巢穴。解读加密信息可以证明你具备盗贼所需的机敏，也能让你准确知道该去哪里寻求他的指导。",al={"为什么要密文石板","为什么需要石板","谁要密文石板"}}},fp="16,223,16.432.0,16.331.0,38.175.0,36.152.0,21.114.0,37.190.0"}
P.entries["item:essence-of-nightlash"] = {n="奈塔拉什的灵魂",s="奈塔拉什的灵魂是从死亡之田被打败的女妖奈塔拉什身上收集到的残留魔法余烬。对于高级执行官哈德瑞克来说，这是天灾军团对当地腐皮豺狼人的增援已被瓦解的铁证。",h="奈塔拉什的灵魂是从死亡之田被打败的女妖奈塔拉什身上收集到的残留魔法余烬。对于高级执行官哈德瑞克来说，这是天灾军团对当地腐皮豺狼人的增援已被瓦解的铁证。",kw={"女妖","死亡之田","尘埃","灵魂","哈德瑞克","奈塔拉什","腐皮","瑟伯切尔"},ang={["class:Mage"]="奥术师和学者经常会检查被摧毁的女妖的残留物，以研究幽灵亡灵是如何将亡灵魔法与物理世界联系在一起的。",["race:Undead"]="被遗忘者的士兵们认为消灭像奈塔拉什这样的女妖是至关重要的工作；作为曾经受天灾军团统治的受害者，消灭巫妖王的爪牙对于确保洛丹伦的安全至关重要。"},sec={{t="死亡之田的女妖",b="在银松森林北部一处被称为死亡之田的废弃农场，成群的亡灵腐皮豺狼人在天灾军团的指挥下建立了据点。最初的被遗忘者进攻屡屡受挫，原因并非凶猛的豺狼人，而是它们的幽灵指挥官：女妖奈塔拉什。她召唤哀嚎魔法强化了豺狼人的防线，并击溃了来自瑟伯切尔的部队。将其击杀会使她那非实体的躯体消散为尘埃，留下一块代表她彻底消亡的结晶状魔法精华。"},{t="天灾军团战败的证明",b="由于女妖死后不会留下实体的尸体，奈塔拉什的灵魂是证明这个邪恶灵魂已被消灭的唯一物理证据。瑟伯切尔的高级执行官哈德瑞克需要这种灵魂来确认天灾军团在当地的立足点已经瓦解，从而使被遗忘者能够最终稳固他们的北部防线，并压制腐皮豺狼人的威胁。"}},faq={{q="什么是奈塔拉什的灵魂？",a="这是天灾女妖奈塔拉什被击败后留下的结晶尘埃。由于幽灵没有实体，这种魔法残留物便成了她已死的证明。",al={"奈塔拉什的灵魂","奈塔拉什之尘","什么是奈塔拉什的灵魂"}},{q="奈塔拉什是谁？",a="奈塔拉什是一名效忠于天灾军团的女妖，她负责领导并强化在银松森林北部死亡之田活动的腐皮豺狼人。",al={"谁是奈塔拉什","奈塔拉什背景故事","女妖奈塔拉什"}},{q="谁需要这种灵魂？",a="瑟伯切尔的高级执行官哈德瑞克要求被遗忘者的勇士去取回它，以证明那个击溃他前线部队的女妖已被消灭。",al={"谁需要奈塔拉什的灵魂","谁来提交灵魂","高级执行官哈德瑞克"}},{q="为什么豺狼人要和女妖合作？",a="死亡之田的腐皮豺狼人屈服于亡灵瘟疫，沦为了天灾军团的奴隶。奈塔拉什是被派来监管它们并提供魔法支援，以对抗被遗忘者巡逻队的。",al={"豺狼人与天灾军团","腐皮天灾军团","为什么豺狼人会跟随女妖"}}},fx={["13c624cf"]={q="奈塔拉什的灵魂来自哪里？",a="这份灵魂精华来自女妖奈塔拉什本人。当你在亡者农场与她交战并将其消灭时，她的幽灵形体便会崩塌，灵魂精华化为尘土，只留下你收集到的残余。",al={"奈塔拉什的灵魂来源","如何获得奈塔拉什的灵魂","奈塔拉什的灵魂在哪里掉落"}}},fp="20,256,30.536.0,23.370.0,33.178.0,17.148.0,23.155.0,42.203.0"}
P.entries["item:essential-artificial"] = {n="基础模组",s="基础模组是一种多功能、标准化的机械组件，对侏儒技师和工程师来说至关重要。在诺莫瑞根那场惊慌失措的撤离行动中，这些零件被遗弃在仓库里，如今成为了流亡在铁炉堡、一心想要重建科技力量的侏儒们趋之若鹜的目标。",h="基础模组是一种多功能、标准化的机械组件，对侏儒技师和工程师来说至关重要。在诺莫瑞根那场惊慌失措的撤离行动中，这些零件被遗弃在仓库里，如今成为了流亡在铁炉堡、一心想要重建科技力量的侏儒们趋之若鹜的目标。",kw={"自动提取器","工程学组件","基础模组","诺莫瑞根","klockmort spannerspan","tinker town"},ang={["profession:Engineering"]="工程师们一定能体会到这种近乎通用的机械零件的优雅之处，它被设计成可以无缝集成到各种机械和实验设计中。",["race:Gnome"]="从诺莫瑞根的辐射走廊中回收的每一个组件，都能帮助流亡的侏儒在铁炉堡避难的同时，重建他们的技术优势。"},sec={{t="标准规格的独创性",b="在诺莫瑞根陷落之前，基础模组是日常侏儒工程学的基石。技师们将其描述为一种近乎通用的组件，被集成到这座地下城市各处的无数装置、发条奇迹和重型机械中。其标准化的特性使它成为那些寻求可靠、可互换模块化零件的铁匠和机械师不可或缺的材料。"},{t="深渊中的回收物",b="当穴居人入侵以及随后的辐射灾难迫使侏儒们进行绝望而恐慌的大撤离时，大量的这些组件就被遗弃在了原地。它们仍然存放在散布于诺莫瑞根更深处通道的蒸汽动力自动提取器中。在Tinker Town，工匠大师Klockmort Spannerspan正积极招募勇敢的冒险者深入那些受污染的废墟，回收这些零件，以便让研究和发明得以继续。"}},faq={{q="什么是基础模组？",a="这是一种标准化、高度通用的机械组件，被侏儒铁匠和技师广泛用于他们的实验、机器和装置中。",al={"什么是基础模组","基础模组物品","这个组件是什么"}},{q="为什么它们被遗弃在诺莫瑞根？",a="当穴居人入侵，整座城市被致命的辐射淹没时，侏儒们仓皇出逃。在撤离的混乱中，大量的日常组件就这样被遗留在了存储装置里。",al={"为什么它们在诺莫瑞根","为什么被遗弃"}},{q="谁想要回收这些组件？",a="Klockmort Spannerspan，一位常驻铁炉堡内Tinker Town的雄心勃勃的侏儒发明家，他寻求这些零件是为了支撑他在流亡期间进行的持续实验和技术研究。",al={"谁需要基础模组","谁在回收这些","klockmort spannerspan任务"}},{q="在废墟中哪里可以找到它们？",a="它们被存放在位于诺莫瑞根受污染区域深层的、被称为自动提取器的大型蒸汽动力机械容器中。",al={"我在哪里可以找到基础模组","自动提取器位置"}}},fx={["691fb1fc"]={q="基础模组从何而来？由谁制造？",a="基础模组是精密的机械零件，由诺莫瑞根的工匠和铁匠在这座伟大城市沦陷前设计制造。这些零件大量生产，用于侏儒科技，并储存在名为模组提取器的自动分发装置中；这些装置设在城市更深处的工业区。",al={"谁制造了基础模组","基础模组的来源","基础模组来自哪里"}}},fp="20,302,24.407.0,23.522.0,32.152.0,40.212.0,37.173.0,38.166.0"}
P.entries["item:etched-note"] = {n="风化便笺",s="风化便笺是一份正式的传唤书，递交给在纳拉其营地休整的有前途的牛头人年轻猎手。这封信由营地的猎人训练师兰卡·远箭所写，欢迎新手加入狩猎的传统，并召唤他们前来接受最初的教导。",h="风化便笺是一份正式的传唤书，递交给在纳拉其营地休整的有前途的牛头人年轻猎手。这封信由营地的猎人训练师兰卡·远箭所写，欢迎新手加入狩猎的传统，并召唤他们前来接受最初的教导。",kw={"纳拉其营地","风化便笺","兰卡·远箭","莫高雷","红云台地","牛头人猎人","训练师传唤"},ang={["class:Hunter"]="这封便笺标志着你正式加入猎人传统，承诺将教导你如何使用远程武器以及与平原上的野兽沟通。",["race:Tauren"]="背负着长者和血统的期望，收到这封便笺召唤你在前往遥远之地前，先掌握莫高雷的广袤草原。"},sec={{t="狩猎的召唤",b="在纳拉其营地安全的范围内，年轻的舒哈鲁（牛头人）很早便因其天生的倾向和家族血统而受到赏识。风化便笺是由信使代表常驻猎人导师兰卡·远箭递送的。它称猎人是部落的核心，同时也严厉地提醒他们，原始的本能必须通过严格的教导和对莫高雷荒野的深深敬畏来磨练。"},{t="舒哈鲁的传统",b="对于牛头人来说，狩猎不仅仅是一种实用的生存手段，它更是一种融入部落社会的荣誉神圣准则。这封信提醒读者，猎人融合了战士、萨满祭司和德鲁伊的角色，部落将期待他们的指引与保护。通过将这封信交给兰卡，学生迈出了学习武器制造、了解野兽，以及履行保卫和维持部落职责的第一步。"}},faq={{q="风化便笺的目的是什么？",a="它作为新手牛头人猎人的入门传唤书。阅读该便笺会引导持有人前往纳拉其营地向兰卡·远箭报到，开始他们正式的射术和野兽知识训练。",al={"便笺有什么用","风化便笺用途","为什么我收到了风化便笺"}},{q="是谁写的这封便笺？",a="这条讯息是由位于纳拉其营地的猎人训练师兰卡·远箭所写。他派遣信使穿过台地，去寻找准备好学习的年轻猎手。",al={"谁寄出了风化便笺","是谁写的","风化便笺作者"}},{q="为什么狩猎对牛头人如此重要？",a="狩猎是牛头人赖以生存、精神信仰和部落传统的基石。技术娴熟的猎人为族人提供食物和材料，同时与大地保持直接的平衡，并向他们击倒的野兽之灵致敬。",al={"牛头人猎人传说","为什么牛头人要狩猎","牛头人文化中的狩猎"}},{q="这封便笺应该带到哪里？",a="直接将便笺带给兰卡·远箭，他站在红云台地上的纳拉其营地内的凉亭和训练场附近。",al={"我该把便笺带到哪里","我该把它交给谁","风化便笺交付"}}},fx={["10b0f74a"]={q="什么是风化便笺？",a="风化便笺是一封书面召集令，专门送给抵达纳拉其营地的新手牛头人猎人。便笺上刻着营地猎人训练师兰卡·远箭的简短留言，提醒你猎人是部族的核心，并请你前往纳拉其营地找他，开始掌握狩猎之道。",al={"什么是风化便笺","风化便笺物品","莫高雷风化便笺"}},bd70af04={q="兰卡·远箭为什么要你把风化便笺带给他？",a="兰卡·远箭安排送来便笺，是为了把有潜力的年轻猎人直接招到自己麾下。他打算检验你的准备情况，并让你熟悉狩猎的重要传统——从使用远程武器到驯服野兽——确保你能够在莫高雷的平原上为部族效力、保护部族。",al={"为什么要交付风化便笺","兰卡为什么要风化便笺","风化便笺的用途"}}},fp="11,274,18.422.0,26.481.0,39.217.0,20.173.0,42.235.0,34.133.0"}
P.entries["item:etched-parchment"] = {n="风蚀羊皮纸",s="风蚀羊皮纸是一份下达给在杜隆塔尔试炼谷接受训练的新手猎人的书面传唤。它由高内克亲自递交，指引有志向的荒野潜行者去向巨魔训练师基沙寻求指导。",h="风蚀羊皮纸是一份下达给在杜隆塔尔试炼谷接受训练的新手猎人的书面传唤。它由高内克亲自递交，指引有志向的荒野潜行者去向巨魔训练师基沙寻求指导。",kw={"杜隆塔尔","风蚀羊皮纸","高内克","猎人","基沙","训练师","试炼谷"},ang={["class:Hunter"]="这份公文代表着一名猎人在杜隆塔尔的第一次成人礼，它正式将他们与基沙联系起来，以便开始学习追踪、远程武器和生存技能。",["faction:Horde"]="部落的每一位年轻战士都必须磨练自己的技艺；对于猎人而言，这张羊皮纸标志着他们迈出了供养氏族、守卫杜隆塔尔边境的第一步。"},sec={{t="狩猎的召唤",b="年轻的兽人和暗矛巨魔若想在部落中寻求自己的一席之地，他们的仪式便始于干旱的试炼谷盆地。当他们在对抗当地野兽证明自己的时候，高内克便作为一名警惕的监督者，引导新兵找到自己的天职。对于那些注定要使用弓、枪和獠牙的人，高内克会递给他们这份风蚀羊皮纸。上面写着基沙——一位渴望发现新锐目光与稳健之手的资深猎人训练师——发出的直接讯息。"},{t="第一课",b="带着羊皮纸去见基沙，标志着一名猎人在杜隆塔尔的训练真正开始。基沙强调，走上荒野之路绝非易事，就像奥术师钻研魔法或萨满祭司感应灵魂一样，想要驯服沙漠中的野兽，同样需要全心全意的投入。阅读这份羊皮纸并响应她的召唤，是新手们学习正确的射术与荒野求生知识的开端。"}},faq={{q="风蚀羊皮纸有什么用？",a="这是一份入门级的传唤函，旨在指引初到试炼谷的猎人前往寻找他们的职业训练师基沙。",al={"风蚀羊皮纸用途","风蚀羊皮纸有什么作用"}},{q="是谁发放这张羊皮纸？",a="驻扎在试炼谷大兽穴附近的高内克，会在年轻猎人抵达时将此纸条交给他们。",al={"谁发放风蚀羊皮纸","风蚀羊皮纸任务发布者"}},{q="谁写了风蚀羊皮纸？",a="这条讯息来自基沙，她是一位驻扎在试炼谷的巨魔猎人训练师，急切地想要培养新的射手。",al={"谁发送了风蚀羊皮纸","羊皮纸作者"}},{q="在哪里可以找到基沙？",a="基沙位于杜隆塔尔的试炼谷，她在训练场附近等待，准备指导新手兽人和巨魔猎人。",al={"基沙在哪里","寻找基沙"}}},fx={ddc4492f={q="什么是风蚀羊皮纸？",a="风蚀羊皮纸是一封书面召集令，专门送给抵达试炼谷的新手猎人。高内克把它交给你，上面直接召你去找当地的猎人训练师基沙，好让你开始学习如何在杜隆塔尔严酷的赤色荒地上生存，并掌握漫游其间的野兽。",al={"什么是风蚀羊皮纸","风蚀羊皮纸物品","风蚀羊皮纸介绍"}},f14a07d9={q="基沙为什么要你把风蚀羊皮纸还给她？",a="基沙并不会把羊皮纸当作珍贵遗物收藏；她用它正式召集初出茅庐的猎人前来。把羊皮纸交给她，便能确认你已应召而来，也已准备好接受弓术、射击以及如何与杜隆塔尔凶猛的掠食者共存等致命技艺的指导。",al={"为什么要带风蚀羊皮纸","基沙为什么要羊皮纸","风蚀羊皮纸的用途"}}},fp="16,229,21.455.0,16.408.0,33.127.0,29.123.0,31.129.0,28.131.0"}
P.entries["item:etched-rune"] = {n="风蚀符文",s="风蚀符文是一块刻字的石板，发给寒脊山谷中有志成为猎人的矮人。它就像一份来自猎人训练师索加斯·格瑞姆森的邀请函，指引新手前往安威玛尔寻找他，开始接受正式的荒野训练。",h="风蚀符文是一块刻字的石板，发给寒脊山谷中有志成为猎人的矮人。它就像一份来自猎人训练师索加斯·格瑞姆森的邀请函，指引新手前往安威玛尔寻找他，开始接受正式的荒野训练。",kw={"安威玛尔","寒脊山谷","丹莫罗","矮人猎人","风蚀符文","猎人训练","索加斯·格瑞姆森"},ang={["class:Hunter"]="该符文标志着你第一次正式受邀学习古老的矮人狩猎技艺，强调追踪、尊重动物伙伴，以及仅凭智慧在严酷的荒野中生存。",["race:Dwarf"]="刻字的石头和符文是矮人传授技艺和紧急指令的传统方式，即便是对于寒脊山谷雪地里的强悍流浪者也是如此。"},sec={{t="荒野的呼唤",b="这块刻着特殊矮人符文的小石板，会被分发给在寒脊山谷的积雪中展露天赋的新手。这是登山者兼猎人训练师索加斯·格瑞姆森发出的，鼓励这些初出茅庐的追踪者放下手头的户外任务，前往安威玛尔报到。阅读这块石板，标志着猎人从基础生存迈向理解荒野精深技艺的第一步——学习尊重丹莫罗的野兽、追踪山区掠食者、保养远程武器，并在严酷的环境中生存下来。"}},faq={{q="风蚀符文有什么用途？",a="该符文是矮人猎人的教学传唤。阅读石板上的标记，会指引持有者前往温暖的安威玛尔寻找索加斯·格瑞姆森，以接受猎人技艺的正式指导。",al={"风蚀符文的作用","风蚀符文的使用","为什么我有风蚀符文"}},{q="谁写下或发送了风蚀符文？",a="该符文由驻扎在安威玛尔的当地猎人训练师索加斯·格瑞姆森发送。他将这些刻字的石头交给在寒脊山谷附近活动、且表现出在冰封荒野中生存天赋的户外新手。",al={"谁发送了风蚀符文","谁给了我这个符文","风蚀符文的作者"}},{q="我阅读风蚀符文后该把它带到哪里？",a="将符文带到寒脊山谷安威玛尔的主旅店里。你会发现索加斯·格瑞姆森就站在熔炉和训练场附近，准备教你追踪、武器保养以及矮人狩猎的传统。",al={"我该把风蚀符文带到哪","提交风蚀符文","索加斯·格瑞姆森的位置"}}},fx={["455fa37e"]={q="什么是风蚀符文？",a="风蚀符文是一块刻有文字的石板，交给在寒脊山谷开始训练的新手矮人猎人。它不是普通的羊皮纸，而是一份刻有符文、经久不衰的召集讯息，体现了矮人根深蒂固的技艺与传统，也承载着荒野求生之道。",al={"什么是风蚀符文","风蚀符文物品","风蚀符文背景"}},["537b1d7a"]={q="索加斯·格瑞姆森为什么要你把风蚀符文带给他？",a="这枚符文是索加斯·格瑞姆森发出的正式训练召集令；他是安威玛尔的驻地猎人训练师。带上符文可以证明你已在山谷中展现了基本能力，并准备好接受追踪、武器维护和荒野传统方面的严格训练。",al={"索加斯为什么要符文","为什么要风蚀符文","风蚀符文召集令的用途"}}},fp="11,262,16.564.0,39.231.0,34.225.0,52.230.0"}
P.entries["item:etched-sigil"] = {n="风化符记",s="这是一枚交付给幽影谷初醒的暗夜精灵猎人的铭文信物。由林地信使携带，上面带着猎人训练师阿亚娜·远途从奥达希尔巨枝之巅发出的召唤。",h="这是一枚交付给幽影谷初醒的暗夜精灵猎人的铭文信物。由林地信使携带，上面带着猎人训练师阿亚娜·远途从奥达希尔巨枝之巅发出的召唤。",kw={"奥达希尔","阿亚娜·远途","风化符记","猎人","幽影谷","泰达希尔"},ang={["class:Hunter"]="这枚铭文护身符标志着卡多雷猎人在阿亚娜·远途的指导下，开启掌握弓箭和野兽之道旅程的起点。",["race:NightElf"]="这枚符记在幽影谷幽静的树冠下交付，它尊崇了致力于守护泰达希尔的暗夜精灵林务者们的古老传统。"},sec={{t="荒野的召唤",b="风化符记上雕刻着狩猎的印记，当新觉醒的暗夜精灵猎人踏入幽影谷时，他们会收到这枚信物。这枚信物是来自当地猎人训练师阿亚娜·远途的正式通知与欢迎，她居住在奥达希尔中空的枝干高处。符记指示新手前往寻找她，并由此开启关于射箭、荒野追踪以及暗夜精灵潜行者与野兽之间古老羁绊的终身教导。"}},faq={{q="风化符记的用途是什么？",a="该符记是一份直接的召唤，指示暗夜精灵猎人新手前往幽影谷的奥达希尔之巅寻找他们的训练师阿亚娜·远途，以开始关于生存、追踪和射箭的正式训练。",al={"风化符记有什么用","风化符记用途","我为什么会有这个符记"}},{q="是谁寄出了风化符记？",a="它是由阿亚娜·远途制作并派发的，她是负责照看幽影谷中羽翼未丰的林地潜行者的猎人训练师。",al={"谁寄出的风化符记","风化符记从哪里来"}},{q="符记应该被带到哪里？",a="它必须被带到位于幽影谷中心的奥达希尔巨树的高处，阿亚娜·远途正在那里等待。",al={"我该把风化符记带到哪里","我该把风化符记交给谁"}},{q="为什么暗夜精灵猎人收到的是符记而不是纸质信件？",a="卡多雷的传统更倾向于使用天然雕刻和刻有艾露恩及荒野神圣符号的耐用信物，而非普通的羊皮纸，这体现了猎人与森林之间的羁绊本质。",al={"为什么是符记而不是信件","符记是用什么做的"}}},fx={fbac1def={q="什么是风化符记？",a="风化符记是一件刻有召集令的信物，供幽影谷有志成为猎人的暗夜精灵使用。信使在你抵达泰达希尔时将它交到你手中，它是对阿亚娜·远途的正式引荐，邀请你在奥达希尔的树荫下开始射术与驯兽的正规训练。",al={"什么是风化符记","风化符记物品","风化符记介绍"}},e2d33d60={q="阿亚娜·远途为什么要你把风化符记带给她？",a="阿亚娜·远途寄来符记，是为了确保你知道去幽影谷何处寻求指导。在奥达希尔顶端把符记交还给她，可以证明你收到了她的消息，也准备好开始训练，学会以精准无误的技艺使用弓箭，并尊重卡利姆多的野生生灵。",al={"为什么要带风化符记","阿亚娜为什么要符记","谁要风化符记"}}},fp="12,209,20.452.0,40.206.0,27.129.0,32.137.0,68.195.0"}
P.entries["item:explosive-stick-of-gann"] = {n="加恩的雷管",s="加恩的雷管是加恩·石塔使用窃取的矮人蓝图所组装的一种定制爆破装置。它是专为破坏驻扎在南贫瘠之地巴尔莫丹的矮人飞行器而设计的。",h="加恩的雷管是加恩·石塔使用窃取的矮人蓝图所组装的一种定制爆破装置。它是专为破坏驻扎在南贫瘠之地巴尔莫丹的矮人飞行器而设计的。",kw={"巴尔莫丹","加恩的雷管","飞行器","加恩·石塔","勘探员卡兹戈姆","石塔部族","贫瘠之地"},ang={["profession:Engineering"]="这种武器展示了讽刺的一面：简单的窃取蓝图被用来对抗先进的矮人机械。",["race:Tauren"]="使用这种武器可以为流离失所的石塔部族复仇，并回击那些挖掘神圣卡利姆多土地的勘探者。"},sec={{t="复仇之武",b="当矮人勘探员卡兹戈姆带领铁炉堡的挖掘队进入卡利姆多南部时，矮人们驱逐了石塔牛头人，夷平了他们的神圣领地，并在那里建造了巴尔莫丹挖掘场。在复仇和告慰流离失所、倒下的族人的愿望驱动下，加恩·石塔夺回了卡兹戈姆的蓝图，打算利用矮人的工程技术来对抗侵略者。通过研究寻回的图纸，加恩组装了这种具有足够冲击力以摧毁重型机械的特制炸药。"},{t="瞄准飞行器",b="这种雷管是为单一目标而制造的：停在挖掘现场上方瞭望塔上的矮人飞行器。对加恩来说，这台机械飞行器不仅仅是空中交通工具或战争武器；它更是联盟在神圣的牛头人土地上展现统治力的傲慢象征。引爆炸药可以摧毁矮人前哨站基础设施的一个基石，并为失落的石塔部族进行关键的还击。"}},faq={{q="什么是加恩的雷管？",a="这是由牛头人加恩·石塔制作的爆破装置。加恩利用缴获的矮人蓝图，专门制造了它，用于破坏占领他祖传土地的勘探者们的机械设备。",al={"加恩的雷管","加恩的炸弹"}},{q="谁制造了这种炸药？",a="它由加恩·石塔组装，这是一位在巴尔莫丹的铁炉堡矮人摧毁其部族村庄并亵渎他们在南贫瘠之地的家园后，寻求复仇的牛头人。",al={"谁制作了这个","谁是加恩","加恩·石塔"}},{q="这枚炸药是用来炸毁什么的？",a="它旨在摧毁位于巴尔莫丹挖掘坑上方瞭望塔上的矮人飞行器。摧毁该飞行器将削弱该地点的侦察能力，并作为对石塔部族的一种象征性复仇。",al={"我该炸什么","飞行器目标","我在哪里使用它"}},{q="牛头人是怎么学会制造矮人炸药的？",a="加恩通过遵循从巴尔莫丹矮人挖掘队领袖——勘探员卡兹戈姆那里缴获的工程蓝图制作了这根雷管，将侵略者自己的技术反过来对付他们。",al={"加恩是如何制造它的","爆破蓝图","卡兹戈姆的计划"}}},fp="23,238,23.527.0,25.454.1,36.203.0,24.190.0,42.238.0,50.194.0"}
P.entries["item:faded-shadowhide-pendant"] = {n="不再发光的暗皮坠饰",s="这是一个曾经由赤脊山的暗皮豺狼人佩戴的失去光泽的护身符，被附魔以作为传递黑暗指令的媒介。持有它的人会惊讶地发现，这个坠饰中还携带了一条由法师塞欧克瑞图斯施加的延迟魔法信息。",h="这是一个曾经由赤脊山的暗皮豺狼人佩戴的失去光泽的护身符，被附魔以作为传递黑暗指令的媒介。持有它的人会惊讶地发现，这个坠饰中还携带了一条由法师塞欧克瑞图斯施加的延迟魔法信息。",kw={"艾尔文","豺狼人","morganth","坠饰","赤脊山","暗皮","塞欧克瑞图斯","阿祖拉之塔"},ang={["class:Mage"]="这个坠饰展示了魔法拦截的微妙之处，表明即使是粗糙或黑暗的附魔也可以被受过训练的法师解码和劫持。",["faction:Alliance"]="取回这个护身符有助于阿祖拉之塔削弱那些威胁艾尔文森林和湖畔镇安宁的暗皮豺狼人。"},sec={{t="破碎的联络网",b="在赤脊山游荡的暗皮豺狼人听命于一个名为Morganth的邪恶主人，通过附魔坠饰来协调他们的行动。大法师塞欧克瑞图斯在阿祖拉之塔的隐居处研究这些护身符时，设计了一种实验性法术来突破它们神秘的频率。虽然他的魔法广播花了数周才显现出来，但这个不再发光的暗皮坠饰证明了豺狼人的通讯线路是可以被劫持的，这为扰乱它们黑暗主人的控制开辟了一条道路。"},{t="法师的野心",b="亲自研究这个不再发光的暗皮坠饰能为塞欧克瑞图斯带来的不仅仅是拦截到的琐碎信息。通过检查附魔如何经受住他的入侵，这位法师希望将他的巫术改进为一种武器，能够直接通过赤脊山各地佩戴的任何匹配护身符投射出削弱性的攻击。将这件文物送回艾尔文森林的阿祖拉之塔是瓦解Morganth对该地区豺狼人控制的关键第一步。"}},faq={{q="不再发光的暗皮坠饰是什么？",a="这是一个附魔护身符，最初由赤脊山的暗皮豺狼人佩戴，用于接收它们的主人Morganth的指令。这个特定的坠饰已经被大法师塞欧克瑞图斯施加的拦截广播法术所改变。",al={"暗皮坠饰","这个坠饰是什么","塞欧克瑞图斯的坠饰"}},{q="为什么坠饰里会传出声音？",a="大法师塞欧克瑞图斯花了数月时间研究如何用魔法突破这些坠饰的通讯链接。你听到的声音是他数周前投射的法术回响，证明了他的咒语成功渗透进了豺狼人的网络。",al={"谁在说话","虚无的声音","塞欧克瑞图斯的声音"}},{q="塞欧克瑞图斯是谁？",a="塞欧克瑞图斯是居住在东艾尔文森林阿祖拉之塔的大法师。他致力于魔法研究，监视着边境赤脊山一带的黑暗威胁，尤其是那个流氓术士Morganth。",al={"塞欧克瑞图斯背景故事","大法师塞欧克瑞图斯","阿祖拉之塔法师"}},{q="Morganth是谁？",a="Morganth是一个在赤脊山活动的流氓且邪恶的施法者。他对当地的暗皮豺狼人氏族施加了黑暗的影响，通过这些附魔坠饰向它们发布命令。",al={"morganth的身份","谁是morganth","豺狼人之主"}},{q="塞欧克瑞图斯打算怎么处理这个坠饰？",a="塞欧克瑞图斯打算在他的实验室里研究这个坠饰的附魔。他的最终目标是找到一种跨网络投射削弱性魔法攻击的方法，使任何佩戴此类坠饰的豺狼人瞬间丧失行动能力。",al={"为什么塞欧克瑞图斯想要它","坠饰用途","将坠饰武器化"}}},fx={["6c0e263d"]={q="不再发光的暗皮坠饰来自哪里？由谁制造？",a="这枚坠饰源自赤脊山的暗皮豺狼人及其黑暗主宰、盗贼法师摩根斯。摩根斯制造或附魔了这些小饰物，将它们制成神秘媒介，以便把命令直接传达给受他控制的豺狼人群。",al={"谁制造了不再发光的暗皮坠饰","暗皮坠饰来自哪里","不再发光的暗皮坠饰的来源"}}},fp="24,240,16.500.0,19.447.1,37.240.0,40.241.0,18.210.0,16.189.0,49.212.0"}
P.entries["item:fallen-moonstone"] = {n="陨落的月亮石",s="陨落的月亮石是一种会发光的、带有魔法充能的石头，采集自灰谷坠星湖那宁静的水域。这些石头蕴含着神圣的月光能量，拥有强大的修复特性，能够恢复生命力并治愈严重的虚弱。",h="陨落的月亮石是一种会发光的、带有魔法充能的石头，采集自灰谷坠星湖那宁静的水域。这些石头蕴含着神圣的月光能量，拥有强大的修复特性，能够恢复生命力并治愈严重的虚弱。",kw={"灰谷","阿斯特兰纳","陨落的月亮石","坠星湖","月亮石","皮尔图拉斯·怀特姆恩","雷拉拉","shadethicket先知"},ang={["class:Priest"]="The Sisterhood of Elune的信徒们将这些石头发出的月光视为治愈之恩典的具象化体现。",["race:NightElf"]="对于卡多雷而言，与艾露恩光辉相连的圣物是神圣的守护工具，能在凡人的药物失效时提供神圣的治愈。"},sec={{t="夜空的馈赠",b="陨落的月亮石曾大量分布在阿斯特兰纳东南部的坠星湖沿岸和浅滩。暗夜精灵因其修复魔法和月亮祝福而对其倍加珍视，当普通药物疗效不足时，常寻求它们来辅助恢复。然而，当受到腐蚀的Shadethicket沼泽兽占领了湖泊后，采集它们变得十分危险。它们的首领，一只Shadethicket先知，将自己能找到的每一块石头都囤积在湖中心的一座小岛上，切断了当地卡多雷获取这一重要治疗来源的途径。"},{t="一位父亲的救赎",b="当年轻的雷拉拉·怀特姆恩在阿斯特兰纳身患重病时，普通的治疗手段退去了她的高烧，却让她变得虚弱不堪，仅剩一丝气息苦苦支撑。她的父亲，皮尔图拉斯·怀特姆恩意识到，唯有月亮石那浓缩的修复力量才能重焕她枯竭的生命力。从Shadethicket先知的囤积物中找回的一块石头，成为了拯救这孩子生命所需的火种。"}},faq={{q="什么是陨落的月亮石？",a="它是一种在灰谷坠星湖发现的稀有发光石。它充满了月亮魔法，拥有强大的修复能量，暗夜精灵用它来为极度虚弱者补充力量。",al={"陨落的月亮石是什么","陨落的月亮石背景故事","灰谷月亮石"}},{q="在哪里可以找到陨落的月亮石？",a="它们产自位于灰谷阿斯特兰纳东南部的坠星湖。虽然它们曾经自由地散布在湖底，但充满敌意的Shadethicket沼泽兽将它们收集起来，囤积在湖中心的一座小岛上。",al={"到哪里寻找陨落的月亮石","陨落的月亮石位置"}},{q="谁拥有坠星湖的月亮石？",a="Shadethicket先知，即栖息在坠星湖的受腐蚀沼泽兽的首领，将陨落的月亮石囤积在湖中间的一座小岛上。",al={"谁拥有陨落的月亮石","shadethicket先知月亮石"}},{q="皮尔图拉斯·怀特姆恩为什么需要陨落的月亮石？",a="他的幼女雷拉拉虽然从重病高烧中幸存下来，但变得极度虚弱，生命垂危。皮尔图拉斯意识到，仅仅依靠自然休养已不足以维持她的生命，需要借助月亮石的天生魔法来恢复她的活力。",al={"皮尔图拉斯·怀特姆恩的女儿","为什么需要月亮石","雷拉拉的治疗"}}},fp="16,264,22.557.0,20.413.1,27.206.0,34.221.0,48.162.0,52.243.0"}
P.entries["item:fandral-s-message"] = {n="范达尔的信",s="《范达尔的信》是大德鲁伊范达尔·鹿盔在达纳苏斯写的一封信件。它被托付给一名冒险者，要求将其跨海送到黑海岸的知识古树奥努手中。",h="《范达尔的信》是大德鲁伊范达尔·鹿盔在达纳苏斯写的一封信件。它被托付给一名冒险者，要求将其跨海送到黑海岸的知识古树奥努手中。",kw={"知识古树","奥伯丁","黑海岸","达纳苏斯","范达尔·鹿盔","范达尔的信","古树之林","奥努","神谕林地"},ang={["class:Druid"]="在达纳苏斯的塞纳里奥区和黑海岸的知识古树之间传递信件，体现了范达尔·鹿盔激进的驱动力与古老德鲁伊守护者耐心的传统主义之间对比鲜明的哲学。",["race:NightElf"]="递送这份急件标志着从泰达希尔树冠出发，返回卡利姆多大陆祖先森林的最早步伐之一。"},sec={{t="来自大德鲁伊的急件",b="这封密封的急件由大德鲁伊范达尔·鹿盔在塞纳里奥区撰写，是暗夜精灵德鲁伊代理领袖与居住在古树之林的受人尊敬的知识古树奥努之间的直接通信。在收到有关泰达希尔神谕林地状况的报告后，鹿盔毫不迟疑地派遣信使将消息传送到奥伯丁以南。递送任务需要旅行者渡海前往黑海岸，将新世界之树的心脏与更古老、阴影笼罩的大陆连接起来。"},{t="对比鲜明的节奏",b="虽然信件的确切内容仅在大德鲁伊与奥努之间知晓，但这次递送本身凸显了塞纳里奥议会内部气质上的细微差异。在接受文件时，奥努指出范达尔总是表现出一种不同寻常的不耐烦，急于推进那些古树认为应该自然发展的事务。对于黑海岸那些长寿的树人来说，范达尔的匆忙与大德鲁伊玛法里奥·怒风曾经体现的耐心智慧形成了鲜明对比。"}},faq={{q="什么是《范达尔的信》？",a="这是一封来自大德鲁伊范达尔·鹿盔的官方书面急件，旨在传达给居住在黑海岸古树之林的知识古树奥努。",al={"范达尔的信物品","范达尔的信","大德鲁伊的信件"}},{q="是谁发送了这封信，为什么？",a="大德鲁伊范达尔·鹿盔在达纳苏斯写下了这封信。在收到关于泰达希尔神谕林地的最新消息后，他发出了消息以通知奥努，后者一直在等待来自世界之树顶端的消息。",al={"谁写的这封信","为什么范达尔要发这封信"}},{q="这封信需要送到哪里？",a="这封信必须送到位于黑海岸、奥伯丁沿海定居点正南方的古树之林里的奥努手中。",al={"谁收到了这封信","去哪里递送这封信","范达尔的信目的地"}},{q="奥努对这封信有什么看法？",a="在收到信件后，奥努评论说范达尔似乎总是行色匆匆。这位古树观察到，自然有其既定的步调，并感叹珊多玛法里奥·怒风比范达尔更理解这一真理。",al={"奥努的反应","奥努说了什么"}}},fx={["22d06606"]={q="奥努为什么想要范达尔的信？",a="在黑海岸古树之林休憩的知识古树奥努，一直在等待大德鲁伊范达尔·鹿盔告知泰达希尔的状况。收到神谕林地的消息后，范达尔立即派你渡海送来这封信。奥努耐心地接过信件，同时静静感叹，这位躁动的大德鲁伊总是显得过于匆忙，与沙多·怒风昔日展现的耐心睿智相比，实在相去甚远。",al={"奥努为什么想要这封信","奥努为什么需要范达尔的信","为什么要递送范达尔的信"}}},fp="17,182,29.563.0,18.503.1,26.157.0,31.207.0,35.149.0,34.232.0"}
P.entries["item:fang-of-vagash"] = {n="瓦加什的牙齿",s="瓦加什的牙齿是从丹莫罗冰雪覆盖的悬崖峭壁中臭名昭著的野兽瓦加什身上取下的一颗巨大的掠食者牙齿。对于当地的牧民来说，它是这只威胁着他们珍贵公羊的劫掠怪物终于被杀死的有力证据。",h="瓦加什的牙齿是从丹莫罗冰雪覆盖的悬崖峭壁中臭名昭著的野兽瓦加什身上取下的一颗巨大的掠食者牙齿。对于当地的牧民来说，它是这只威胁着他们珍贵公羊的劫掠怪物终于被杀死的有力证据。",kw={"冻石农场","丹莫罗","瓦加什的牙齿","铁炉堡","保护兽群","公羊","瓦加什"},ang={["class:Hunter"]="在丹莫罗冰冻的悬崖上追踪像瓦加什这样的顶级掠食者，是对追踪、荒野生存和野兽杀戮能力的一次早期考验。",["race:Dwarf"]="冻石农场为矮人登山者和旅行者提供了必不可少的耐寒山羊。带回瓦加什的牙齿直接保护了铁炉堡最珍贵的坐骑品种。"},sec={{t="狩猎战利品",b="丹莫罗高耸的悬崖是严寒和凶猛掠食者的家园，但没有谁像瓦加什那样给当地农场造成了如此大的困扰。这只野兽潜伏在冻石农场上方的山脊中，经常在夜幕的掩护下潜入山下，屠杀珍贵的公羊。由于铁炉堡的军队兵力已经捉襟见肘，当地牧民无法指望城市卫队提供保护。杀死这只野兽并割下它的一颗凶残牙齿，是牧场再次安全的无可辩驳的证据。"}},faq={{q="瓦加什的牙齿有什么用？",a="这颗牙齿被带到丹莫罗冻石农场的饲养员那里，作为瓦加什已被清除的实物证明。作为回报，感激的牧场主会奖励保护了他们生计的猎人。",al={"瓦加什的牙齿用途","如何处理瓦加什的牙齿","上交瓦加什的牙齿"}},{q="瓦加什是谁？",a="瓦加什是一只异常致命的野兽，栖息在丹莫罗公羊牧场上方白雪皑皑的山丘中。它因在夜间袭击兽群而在当地矮人中恶名昭彰。",al={"瓦加什是什么","瓦加什在哪里","瓦加什背景故事"}},{q="为什么铁炉堡卫队没有杀死瓦加什？",a="铁炉堡的军队兵力已经捉襟见肘。由于没有多少士兵可以抽调去执行乡村巡逻任务，牧场主必须依靠路过的冒险者来对付危险的掠食者。",al={"为什么卫兵不帮忙","铁炉堡军队在哪里","登山者与瓦加什"}}},fx={fc16a334={q="瓦加什的牙齿是什么？",a="瓦加什的牙齿是一件巨大的战利品，取自瓦加什的口中。瓦加什是盘踞在丹莫罗山脊上的凶猛掠食者。这件战利品是确凿无疑的证据，证明这头凶恶野兽终于被猎杀。",al={"瓦加什的牙齿是什么","瓦加什牙齿的背景","瓦加什的牙齿"}},["695a78ed"]={q="瓦加什的牙齿来自哪里？",a="这颗牙齿并非人工制成，而是从瓦加什口中撬下的天然牙齿。这头凶暴的怪物在冻石农场上方的雪山中筑巢。",al={"哪里能找到瓦加什的牙齿","谁制作了瓦加什的牙齿","瓦加什牙齿的来历"}},f04ec442={q="鲁德拉·冻石为什么想要瓦加什的牙齿？",a="鲁德拉·冻石想要这颗牙齿，作为掠食者已死的实物证据。瓦加什夜间不断袭击农场，吞食珍贵的公羊，威胁着冻石家族的生计；而铁炉堡的守卫又分身乏术，无法保护他们。",al={"为什么想要瓦加什的牙齿","谁想要瓦加什的牙齿","鲁德拉·冻石与瓦加什的牙齿"}}},fp="14,246,18.521.0,36.207.0,14.195.0,45.173.0"}
P.entries["item:fangore-s-paw"] = {n="范高雷的爪子",s="范高雷的爪子是赤脊山影牙豺狼人部队指挥官范高雷中尉被砍下的手。它是湖畔镇的所罗门镇长确认豺狼人首领死亡的残酷证据。设立这份残酷的赏金是为了瓦解这位军阀对这座被围困城镇的威胁。",h="范高雷的爪子是赤脊山影牙豺狼人部队指挥官范高雷中尉被砍下的手。它是湖畔镇的所罗门镇长确认豺狼人首领死亡的残酷证据。设立这份残酷的赏金是为了瓦解这位军阀对这座被围困城镇的威胁。",kw={"范高雷","豺狼人","湖畔镇","摩根斯","爪子","赤脊山","影牙","所罗门"},ang={["faction:Alliance"]="除掉范高雷并带回他的爪子，为苦苦支撑的湖畔镇提供了关键的援助，该镇目前从暴风城获得的军事支持非常稀缺。"},sec={{t="堕落首领的战利品",b="Lieutenant Fangore acts as a primary field commander for the Shadowhide gnolls encroaching across the Redridge Mountains. Operating in direct service to the renegade mage Morganth, Fangore directs violent assaults against trade roads, outlying farms, and the defenses around Lake Everstill. Because gnoll raiders do not leave traditional uniforms, official seals, or banners to confirm their casualties, the township authorities rely on grim physical evidence. Magistrate Solomon specifically demanded Fangore's paw as unmistakable proof of his execution, allowing the town of Lakeshire to breathe slightly easier amid mounting surrounding perils."}},faq={{q="这只爪子属于谁？",a="这只爪子属于范高雷中尉，他是盘踞在赤脊山的影牙豺狼人部族中臭名昭著的头目。他在黑暗巫师摩根斯的指挥下组织袭击并率领部队。",al={"谁是范高雷","这是谁的爪子","范高雷身份"}},{q="为什么所罗门镇长想要这只爪子？",a="所罗门镇长发布了一份正式的通缉令，谴责范高雷是暴风城的邪恶敌人。他需要这只被砍下的爪子作为这位影牙中尉已被击杀的无可争辩的实物证据。",al={"为什么要收集范高雷的爪子","所罗门赏金证据","镇长证据"}},{q="范高雷中尉为谁工作？",a="范高雷效忠于摩根斯，这是一位叛逃的黑暗魔法实践者，他在东部的山中塔楼里威胁着湖畔镇，并指挥豺狼人针对王国进行活动。",al={"范高雷的主人","谁领导范高雷","摩根斯关系"}},{q="在哪里能找到范高雷中尉？",a="范高雷中尉在赤脊山的荒野中，隐藏在敌对的影牙豺狼人营地里。",al={"范高雷位置","范高雷在哪里","找到范高雷"}}},fx={["62ed4317"]={q="范高雷的爪子来自哪里？",a="这只爪子直接取自中尉范高雷的尸体。范高雷是盘踞在赤脊山的暗皮豺狼人中臭名昭著的首领。它不是人工制作的遗物或武器，而是在战斗中取得的一件断肢战利品，用以确认这名危险的豺狼人指挥官已被消灭。",al={"范高雷的爪子来历","范高雷的爪子来自哪里","谁制作了范高雷的爪子"}}},fp="13,321,28.647.0,28.209.0,41.207.0,38.171.0,34.119.0"}
P.entries["item:farren-s-report"] = {n="法尔林的报告",s="《法尔林的报告》是法尔林·奥里涅尔中尉在南海镇起草的一份官方公文，详细说明了他对当地娜迦的调查情况。法尔林利用这份文件向他以前的导师、身处Stormwind Keep的萨缪尔森少校求援，希望能获准调回首都。",h="《法尔林的报告》是法尔林·奥里涅尔中尉在南海镇起草的一份官方公文，详细说明了他对当地娜迦的调查情况。法尔林利用这份文件向他以前的导师、身处Stormwind Keep的萨缪尔森少校求援，希望能获准调回首都。",kw={"法尔林·奥里涅尔","法尔林的报告","萨缪尔森少校","娜迦","调职","雷德帕斯","南海镇","stormwind keep"},ang={["faction:Alliance"]="该文件突显了联盟军队内部的官僚手段，即在希尔斯布莱德的偏远驻地与军官们谋求调往暴风城安全岗位的私心之间产生了冲突。",["race:Human"]="对于联盟的人类来说，携带《法尔林的报告》追溯了被围困的南部避难所南海镇与暴风城王室宫廷之间源远流长的联系。"},sec={{t="离开南海镇的门票",b="法尔林·奥里涅尔中尉驻扎在饱受战火蹂躏的希尔斯布莱德丘陵海岸，他对当地的领导层和这个偏远的边境地区感到厌倦。在指派冒险者猎杀刺脊娜迦以收集其威胁的证据后，奥里涅尔将他的调查结果汇编成了一份正式报告。法尔林并没有将其提交给他的指挥官治安官雷德帕斯，而是打算将其直接发送给Stormwind Keep的卫兵队长萨缪尔森少校。作为萨缪尔森曾经的学生，法尔林希望这份文件能展示他的能力，并为他申请立即调回舒适的暴风城提供正当理由。"}},faq={{q="什么是《法尔林的报告》？",a="这是一份由法尔林·奥里涅尔中尉撰写的正式军事公文，总结了他针对侵扰南海镇海滩的刺脊娜迦所采取的行动。",al={"法尔林的报告","这份报告是什么","奥里涅尔的报告"}},{q="为什么法尔林想把这份报告送到暴风城？",a="法尔林想从南海镇调职，回到暴风城。他直接将报告寄给了他的前导师、暴风城卫兵队长萨缪尔森少校，希望能借此获得一次有利的调动。",al={"为什么要寄报告给暴风城","法尔林的目的","为什么要寄给萨缪尔森"}},{q="为什么法尔林要对雷德帕斯隐瞒这份报告？",a="法尔林想避免受到治安官雷德帕斯和当地领导层的审查，因为他们可能会对一名军官仅仅为了策划个人调往首都的安全地带而利用当地威胁的行为感到不满。",al={"为什么要对雷德帕斯保密","雷德帕斯的秘密"}},{q="萨缪尔森少校收到报告后有何反应？",a="萨缪尔森少校称赞他以前的学生在应对南海镇的娜迦问题上采取了主动，并承诺在下个月审查卫兵人事调动时会考虑这份报告。",al={"萨缪尔森的反应","提交调职申请"}}},fx={["97a8ff6b"]={q="法尔林的报告来自哪里？由谁撰写？",a="这份文件由法尔林·奥里涅尔中尉亲自在南海镇起草。法尔林驻扎在危机四伏的希尔斯布莱德丘陵前线，撰写报告，详细说明自己对付当地鱼人和纳迦的行动，希望引起首都高层的关注。",al={"谁写了法尔林的报告","法尔林的报告来历","谁制作了法尔林的报告"}}},fp="15,287,26.617.0,24.162.0,49.226.0,55.208.0,49.193.1"}
P.entries["item:fathom-core"] = {n="深渊之核",s="深渊之核是从黑暗深渊深处的一块淹没在水下的深渊之石中回收的特殊遗物。一旦被破译，它就能提供周边地区元素活动的全面记录。大地之环需要这件神器，以探明暮光之锤邪教正在灰谷之下进行何种黑暗仪式。",h="深渊之核是从黑暗深渊深处的一块淹没在水下的深渊之石中回收的特殊遗物。一旦被破译，它就能提供周边地区元素活动的全面记录。大地之环需要这件神器，以探明暮光之锤邪教正在灰谷之下进行何种黑暗仪式。",kw={"黑暗深渊","大地之环","深渊之核","深渊之石","耶努萨克雷","moonshrine ruins","暮光之锤","佐拉姆加前哨站"},ang={["class:Shaman"]="作为一件记录元素流向的神器，深渊之核引起了大地之环的极大兴趣，它展示了古老的遗物如何揭示元素的操纵。",["faction:Horde"]="回收这枚核心可以直接帮助耶努萨克雷，并巩固部落在佐拉姆加前哨站的立足点，以对抗暮光之锤的腐化计划。"},sec={{t="元素编年史",b="深渊之核静卧在Moonshrine Ruins中被水淹没的一块古老深渊之石内，作为记载元素现象的历史档案发挥作用。它记录并保存了随时间推移而发生的元素位移、扰动和涌动。对于驻扎在佐拉姆加前哨站的大地之环萨满祭司来说，获取这枚核心对于了解暮光之锤的邪教徒们如何操纵区域元素以达到他们的目的至关重要。"}},faq={{q="什么是深渊之核？",a="深渊之核是一种能够记录并叙述其周边所有元素活动详细历史的魔法装置。它被安置在Moonshrine Ruins内的一块古老深渊之石中。",al={"深渊之核的作用","深渊之核背景故事","它是什么"}},{q="深渊之核位于何处？",a="该核心位于灰谷海岸黑暗深渊的洞穴大厅深处。它被封装在Moonshrine Ruins水下的一块深渊之石中。",al={"深渊之核位置","哪里可以找到深渊之核","深渊之石位置"}},{q="谁想要深渊之核，为什么要得到它？",a="驻扎在佐拉姆加前哨站的大地之环萨满祭司耶努萨克雷正在寻找这枚核心。通过分析其对元素位移的记录，耶努萨克雷和他的组织希望能破译并抵消暮光之锤邪教在遗迹内的颠覆性活动。",al={"谁需要深渊之核","为什么耶努萨克雷想要深渊之核","大地之环深渊之核"}},{q="为什么暮光之锤对黑暗深渊感兴趣？",a="这些邪教徒在水下的遗迹中安营扎寨，意图胁迫和腐蚀当地的元素，试图将它们扭曲为邪恶的目的，并夺取这座地下神殿的完全控制权。",al={"暮光之锤黑暗深渊","黑暗深渊中的邪教徒"}}},fp="11,341,19.449.0,24.210.0,33.185.0,34.259.0,61.195.0"}
P.entries["item:feather-charm"] = {n="羽毛咒符",s="羽毛咒符是寒脊山谷雪原中霜鬃巨魔新手携带的粗糙魔法饰品。尽管它们是用简单的材料制作的，但其中蕴含着一种天生的魔法共鸣，引起了当地术士导师的注意。",h="羽毛咒符是寒脊山谷雪原中霜鬃巨魔新手携带的粗糙魔法饰品。尽管它们是用简单的材料制作的，但其中蕴含着一种天生的魔法共鸣，引起了当地术士导师的注意。",kw={"阿拉玛尔·格里姆","安威玛尔","寒脊山谷","丹莫罗","羽毛咒符","霜鬃新手","术士"},ang={["class:Warlock"]="对于丹莫罗的术士新手来说，从巨魔施法者手中夺取羽毛咒符是阿拉玛尔·格里姆在传授他们召唤小鬼的仪式之前进行的一项必要的纪律测试。",["race:Gnome"]="在安威玛尔活动的侏儒术士研究这些粗糙的巨魔护身符，以剖析原始霜鬃施法者所引导的纯粹、未经提炼的魔法。"},sec={{t="巨魔饰品与黑暗研究",b="居住在安威玛尔西南方雪洞中的霜鬃巨魔以领地意识强、行径野蛮而闻名，但他们的新手也会尝试原始的法术。这些年轻巨魔携带的羽毛咒符拥有一种微弱却难以忽视的魔法力量。在安威玛尔，术士导师阿拉玛尔·格里姆认为它们是一个有趣的研究课题——对于粗糙的巨魔工艺来说这很令人惊讶——并利用它们来作为刚入门的术士掌握召唤小鬼技能的试炼。"}},faq={{q="谁携带这些羽毛咒符？",a="它们由潜伏在寒脊山谷安威玛尔西南方雪洞中的霜鬃新手携带。",al={"羽毛咒符来自哪里","谁掉落羽毛咒符","霜鬃新手咒符"}},{q="为什么阿拉玛尔·格里姆想要它们？",a="阿拉玛尔·格里姆发现这些咒符内在的魔法引人入胜且值得研究，他指出这对巨魔手工艺品来说是相当出人意料的。他要求有抱负的术士从巨魔手中获取它们，以此在教授召唤小鬼之前测试他们的身体素质和魔法潜力。",al={"为什么阿拉玛尔需要咒符","阿拉玛尔·格里姆羽毛咒符","格里姆用它们做什么"}},{q="霜鬃巨魔是熟练的魔法使用者吗？",a="虽然霜鬃部族在很大程度上被视为粗野和敌对的，但他们的新手确实展示了初步的施法能力。他们携带的羽毛咒符集中了这种基础魔法，证明即使是他们刚入门的施法者也能驾驭奥术或萨满能量。",al={"霜鬃巨魔会使用魔法吗","霜鬃新手魔法"}},{q="这些咒符长什么样？",a="它们是简单的护身符，由羽毛和麻线编织而成，是霜鬃新手在丹莫罗寒冷的洞穴中进行早期魔法训练时制作的法术焦点。",al={"羽毛咒符描述","羽毛咒符外观"}}},fx={a2188847={q="羽毛咒符是什么？",a="羽毛咒符是丹莫罗霜鬃巨魔的见习者制作并随身携带的简陋魔法护符。这些饰物看似简单，出自原始的山地巨魔之手，实际上却能引导一种独特的魔法能量，因此引起了研究巨魔秘法的学者和施法者的注意。",al={"羽毛咒符是什么","羽毛咒符的背景","关于羽毛咒符"}},["6facee45"]={q="羽毛咒符来自哪里？由谁制作？",a="这些咒符由霜鬃部族初出茅庐的施法者制作，他们居住在安威玛尔西南方的冰冷洞穴中。年轻的巨魔见习者将自身初现的力量注入羽毛，并在寒脊山谷练习粗浅法术时将其作为施法媒介。",al={"谁制作羽毛咒符","羽毛咒符来自哪里","霜鬃羽毛咒符的来历"}}},fp="13,252,31.492.0,33.119.0,32.277.0,43.250.0,29.161.0"}
P.entries["item:fel-cone"] = {n="魔锥果",s="魔锥果是从泰达希尔的树枝上掉落的受腐蚀的种子荚，其果壳散发出的有害绿色烟雾清晰可见。尽管它们被黑暗能量污染且肮脏不堪，但当地的暗夜精灵守卫却想出了巧妙的方法，利用它们来对付附近的恶作剧者。",h="魔锥果是从泰达希尔的树枝上掉落的受腐蚀的种子荚，其果壳散发出的有害绿色烟雾清晰可见。尽管它们被黑暗能量污染且肮脏不堪，但当地的暗夜精灵守卫却想出了巧妙的方法，利用它们来对付附近的恶作剧者。",kw={"多兰纳尔","魔锥果","萨特","寻求赎罪","塞拉尔·刃叶","泰达希尔","赛恩·腐蹄"},ang={["class:Druid"]="看着健康的林地种子荚变成冒烟的邪能残余，对德鲁伊来说是种沉重的提醒，时刻警示着泰达希尔上下为脆弱的平衡所进行的抗争。",["race:NightElf"]="魔锥果的存在是泰达希尔根部深处病变的令人不安的征兆，证明即使是这棵世界之树，其幼嫩的枝干也无法免受恶魔腐蚀的侵害。"},sec={{t="树冠中的枯萎",b="泰达希尔虽然年轻，但腐蚀已经渗透进了它充满活力的树木之中。魔锥果是这种潜伏腐烂的直观证据——那些扭曲、掉落的松果中翻滚着污浊的绿色烟雾。这些果荚散落在多兰纳尔以东的树枝下，浸透了扭曲自然植物并使其触碰或食用都充满危险的污秽魔法。"},{t="苦涩的良药",b="当粗心的旅行者中了赛恩·腐蹄——一只诱骗路人为其效劳的潜伏萨特——的诡计后，当地的守护者会要求他们进行赎罪。塞拉尔·刃叶和哨兵们指示懊悔的冒险者收集这些有害的果实，并假装成无害的零食交给赛恩·腐蹄。种子中集中的腐蚀能量会引发奇特的转变，暂时将这只邪恶的萨特变成一只无害的青蛙。"}},faq={{q="什么是魔锥果？",a="魔锥果是从泰达希尔的树枝上掉落的受腐蚀的松果。它受到非自然魔法的污染，冒着诡异的绿色烟雾，并蕴含着不稳定的转化能量。",al={"什么是魔锥果","魔锥果背景故事","魔锥果是什么"}},{q="在哪里可以找到魔锥果？",a="它们可以在泰达希尔中心地带，多兰纳尔以东的树下森林地面上找到。",al={"魔锥果在哪里","魔锥果位置","如何找到魔锥果"}},{q="森林议会为什么要收集它们？",a="如果你无意中帮助了萨特赛恩·腐蹄去伤害自然的生物，森林议会会给你一个赎罪的机会。他们指示你收集魔锥果，并诱骗赛恩吃下它们作为教训。",al={"寻找赎罪果实","为什么要收集魔锥果","谁需要魔锥果"}},{q="吃下魔锥果会发生什么？",a="森林议会打算用这些果实给赛恩·腐蹄一个教训。预计他会把它们误认为无害的零食；当计划实施时，它们具体的效力就会显现出来。",al={"魔锥果有什么用","食用魔锥果","赛恩·腐蹄青蛙"}}},fx={["5dfa7f39"]={q="魔锥果来自哪里？由谁制作？",a="魔锥果并非凡人所造，而是受到腐化、自然从泰达希尔树木枝头落下的种子球果。它们散发出浓烈的绿色烟雾，表明侵蚀这棵伟大世界之树的黑暗腐化已深入种子和土壤。",al={"魔锥果来自哪里","谁制作了魔锥果","魔锥果的来历"}}},fp="8,264,20.376.0,17.455.1,19.191.0,29.114.0,55.219.1,42.192.1"}
P.entries["item:fel-moss"] = {n="魔苔",s="魔苔是一种在泰达希尔森林中蔓延的受污染植被。它携带着恶魔和腐蚀能量，随着敌对的Grell和Grellkin传播，对世界之树的野生生物和当地熊怪部落构成了险恶的威胁。",h="魔苔是一种在泰达希尔森林中蔓延的受污染植被。它携带着恶魔和腐蚀能量，随着敌对的Grell和Grellkin传播，对世界之树的野生生物和当地熊怪部落构成了险恶的威胁。",kw={"魔苔","gnarlpine","grell","grellkin","幽影谷","塔琳德拉","泰达希尔","ursal the mauler"},ang={["class:Druid"]="对于塞纳里奥议会的德鲁伊来说，魔苔代表着一种在泰达希尔蔓延的令人担忧的毒瘤，证明了新生的世界之树极易受到恶魔枯萎病的侵害。",["race:NightElf"]="暗夜精灵尊崇泰达希尔为他们的新家园，这使得魔苔的出现成为一个令人不安的预兆，暗示即使在他们神圣的枝干之上，和平依然遥不可及。"},sec={{t="世界之树上的枯萎病",b="泰达希尔的种植是为了恢复暗夜精灵的不朽并治愈自然世界，但腐蚀已经悄然侵入了它原始的枝干。魔苔是这种退化最明显的迹象之一。这种恶意生长物附着在并由盘踞在幽影谷的淘气Grell和Grellkin携带，散发出一种不自然、邪恶的魔法。森林守护者，比如树妖塔琳德拉，已经开始收集样本，以测量这种腐烂究竟渗透到了神圣林地的树冠多深的地方。"},{t="疯狂的种子",b="魔苔的危险不仅仅在于林地的腐烂；它还对生物的思想施加了恶毒的影响。原本居住在泰达希尔高地的温顺熊怪屈服于它的侵蚀，放弃了传统的居所，并结成了充满敌意的Gnarlpine部落。在像Ursal the Mauler这样的领袖的带领下，这些受折磨的生物被苔藓的邪恶力量驱使而发疯，突显出在大树内部扎根的日益严重的疾病。"}},faq={{q="什么是魔苔？",a="魔苔是一种在泰达希尔发现的邪恶的、受魔法腐蚀的植物物质。它注入了污秽的能量，附着在有害的生物身上，并将疯狂和物理腐蚀传播到周围的生态系统中。",al={"魔苔背景故事","什么是魔苔","魔苔的作用"}},{q="魔苔来自哪里？",a="在泰达希尔，冒险者从徘徊在幽影谷周围山坡上的扭曲的Grell和Grellkin身上收集魔苔。它源于在世界之树内部扎根的污秽腐蚀力量。",al={"如何获得魔苔","魔苔掉落","魔苔的来源"}},{q="魔苔如何影响熊怪？",a="魔苔起着腐蚀催化剂的作用。暴露在它的邪恶力量下会导致熊怪陷入狂暴的躁狂状态，将泰达希尔曾经和平的部落转变为极具攻击性和排外的Gnarlpine部落。",al={"熊怪腐化","为什么gnarlpine发疯","gnarlpine与魔苔"}},{q="谁在试图阻止魔苔的蔓延？",a="幽影谷的树妖塔琳德拉请求新晋的保卫者从Grellkin身上收集魔苔样本，以证实她对林地腐蚀的怀疑。她指引忧心忡忡的守护者前往多兰纳尔，寻找像阿斯瑞达斯·熊皮这样的德鲁伊。",al={"谁在研究魔苔","谁需要魔苔","塔琳德拉任务"}}},fx={["464589e1"]={q="塔琳德拉为什么想要魔苔？",a="塔琳德拉想要采集魔苔样本，以确认侵扰幽影谷的凶恶林精和林精族是否受其邪恶魔法驱使。她希望通过取得这些受污染的植物，判断腐化扩散到了何处，并了解附近瘤背熊怪所面临的威胁。",al={"为什么收集魔苔","塔琳德拉与魔苔","他们为什么想要魔苔"}}},fp="8,264,24.512.0,16.473.1,17.211.0,30.222.0,38.207.0,45.242.0"}
P.entries["item:felix-s-box"] = {n="菲利克斯的盒子",s="菲利克斯的盒子是一个装有菲利克斯个人物品的小容器，菲利克斯是一名在诺莫瑞根陷落后逃离的难民。在撤离到丹莫罗的混乱过程中，盒子丢失了，随后被当地的霜鬃巨魔抢走，并带到了安威玛尔西南部的营地。",h="菲利克斯的盒子是一个装有菲利克斯个人物品的小容器，菲利克斯是一名在诺莫瑞根陷落后逃离的难民。在撤离到丹莫罗的混乱过程中，盒子丢失了，随后被当地的霜鬃巨魔抢走，并带到了安威玛尔西南部的营地。",kw={"安威玛尔","寒脊山谷","丹莫罗","菲利克斯","菲利克斯的盒子","霜鬃巨魔","诺莫瑞根","难民"},ang={["profession:Engineering"]="这些找回的工具和容器代表了一位技师的生命线，突显了流离失所的侏儒工匠在失去装备时所面临的巨大困难。",["race:Gnome"]="对于在寒脊山谷开启冒险旅程的侏儒冒险者来说，找回菲利克斯的个人物品能为一位遭受诺莫瑞根撤离苦果的同胞流亡者带来直接的慰藉。"},sec={{t="在从诺莫瑞根撤离时丢失",b="当诺莫瑞根在试图清除穴居人威胁的行动失败后被辐射淹没时，菲利克斯加入了大批逃往寒脊山谷的侏儒撤离队伍。为了逃避辐射烟雾，惊慌失措的菲利克斯在雪路上丢掉了他最珍视的个人物品和制作工具。在他回来寻回这些东西之前，当地的霜鬃巨魔洗劫了路边的遗留物，并将他的盒子，连同他的箱子和一桶螺栓，拖回了安威玛尔西南部的简陋营地。"},{t="难民的困境",b="菲利克斯不习惯暴力，也不适应丹莫罗严酷的荒野环境，被迫在安威玛尔寻求过往冒险者的帮助，以取回他的物品。取回菲利克斯的盒子不仅仅是归还一个简单的容器，它还为一位在吞噬了他地下家园的灾难中失去一切的流离失所的工匠恢复了一丝正常生活和生计。"}},faq={{q="什么是菲利克斯的盒子？",a="这是一个装有菲利克斯个人物品的容器，菲利克斯是一位在城市遭受灾难性污染后逃离诺莫瑞根的侏儒工匠。",al={"菲利克斯的盒子","这是什么盒子","菲利克斯的盒子背景故事"}},{q="这个盒子怎么会落到霜鬃巨魔手里？",a="菲利克斯在逃离从诺莫瑞根涌出的放射性烟雾时丢弃了他的装备。在安威玛尔西南部丘陵巡逻的霜鬃巨魔搜刮了路边的装备，并将其拖回了他们的营地。",al={"为什么巨魔有菲利克斯的盒子","谁偷了菲利克斯的盒子","它是怎么丢失的"}},{q="菲利克斯是谁？",a="菲利克斯是一位目前居住在安威玛尔的平民侏儒难民，他因诺莫瑞根的陷落而受到创伤，如今在没有重要工具和个人物品的情况下流落他乡。",al={"菲利克斯","菲利克斯是谁"}},{q="菲利克斯还丢了什么物品？",a="除了盒子之外，霜鬃巨魔还抢走了菲利克斯的箱子和一桶螺栓，并将这三件物品分散在安威玛尔西南部的各个营地中。",al={"菲利克斯的其他物品","菲利克斯的财产","菲利克斯丢失的装备"}}},fx={["8f76c19d"]={q="菲利克斯为什么想拿回自己的盒子？",a="菲利克斯是流离失所的侏儒难民。诺莫瑞根遭辐射侵袭后，他在极度恐慌中逃离了这座城市。在仓皇逃命时，他的工具和个人物品被霜鬃巨魔抢走。如今，他只是个滞留在安威玛尔的普通工匠和难民，没有战斗本领闯入巨魔营地，却迫切需要拿回被盗的盒子和物品，重建生活。",al={"菲利克斯为什么想要盒子","为什么要找菲利克斯的盒子","菲利克斯的盒子有什么用"}}},fp="11,281,34.514.0,20.412.0,20.154.0,49.210.0,25.174.0,32.150.0"}
P.entries["item:felix-s-bucket-of-bolts"] = {n="菲利克斯的螺钉桶",s="“菲利克斯的螺钉桶”是一个装满备用五金件和工具的容器，其所有者是菲利克斯，一位逃离诺莫瑞根陷落的侏儒难民。在他逃往丹莫罗的途中，这个桶被当地的霜鬃巨魔抢走，并被拖进了他们附近的营地中。",h="“菲利克斯的螺钉桶”是一个装满备用五金件和工具的容器，其所有者是菲利克斯，一位逃离诺莫瑞根陷落的侏儒难民。在他逃往丹莫罗的途中，这个桶被当地的霜鬃巨魔抢走，并被拖进了他们附近的营地中。",kw={"安威玛尔","螺栓","丹莫罗","菲利克斯","霜鬃","诺莫瑞根","难民","巨魔","温德波特"},ang={["profession:Engineering"]="没有基本的五金件，任何工匠都无法工作，这使得一个简单的螺钉桶在丹莫罗的冰天雪地中重新开始生活时，成为了极其珍贵的财产。",["race:Gnome"]="每一个回收的零件桶都代表着从废墟中抢救出的一小部分诺莫瑞根，帮助难民在寒脊山谷建立新的立足点。"},sec={{t="难民散落的工具",b="当辐射在针对穴居人的灾难后淹没了诺莫瑞根时，成千上万的侏儒带着能携带的一切逃入了严寒的丹莫罗荒野。菲利克斯成功带着他至关重要的装备逃了出来，但在逃往安威玛尔的混乱中，他遭到了居住在城镇西南面岩架上的霜鬃巨魔的伏击。巨魔掠夺了他的财物，包括这个装满螺栓和零件的桶，使这位工匠在流亡中失去了从事本行所必需的基本材料。"}},faq={{q="“菲利克斯的螺钉桶”是什么？",a="这是一个沉重的容器，里面装满了金属螺栓、五金件和修理补给，属于菲利克斯，一位正在安威玛尔避难的流亡侏儒。",al={"螺钉桶","菲利克斯的桶","菲利克斯的螺钉桶"}},{q="是谁偷走了这个桶？",a="当菲利克斯从诺莫瑞根的灾难中逃离时，霜鬃巨魔偷走了这个桶以及他的其他个人物品。",al={"谁拿走了螺栓","巨魔偷走了桶","谁有菲利克斯的螺栓"}},{q="巨魔把它带到了哪里？",a="巨魔把它带回了寒脊山谷中安威玛尔西南方向岩架上的营地里。",al={"螺栓在哪里","桶的位置","菲利克斯的螺栓营地"}},{q="为什么这个桶对菲利克斯很重要？",a="侏儒难民逃离家园时几乎一无所有。对于像菲利克斯这样的工程师或工匠来说，基本的紧固件和零件是他们在远离诺莫瑞根的地方生存和重建生活的必需品。",al={"为什么菲利克斯需要螺栓","菲利克斯的重要性"}}},fp="23,265,27.541.0,32.156.0,21.131.0,29.103.0,38.199.0"}
P.entries["item:felix-s-chest"] = {n="菲利克斯的箱子",s="菲利克斯的箱子是一个容器，里面装的是被放逐的侏儒菲利克斯在逃离诺莫瑞根时遗失的个人物品。它被潜伏在寒脊山谷附近的霜鬃巨魔抢走，被遗弃在他们原始的山地营地中。",h="菲利克斯的箱子是一个容器，里面装的是被放逐的侏儒菲利克斯在逃离诺莫瑞根时遗失的个人物品。它被潜伏在寒脊山谷附近的霜鬃巨魔抢走，被遗弃在他们原始的山地营地中。",kw={"难民的困境","安威玛尔","寒脊山谷","菲利克斯","菲利克斯的箱子","霜鬃","诺莫瑞根"},ang={["race:Gnome"]="这个箱子令人沉痛地提醒着人们诺莫瑞根那次混乱的撤离，当时逃难的侏儒在荒野和投机取巧的拾荒者面前几乎失去了一切。"},sec={{t="难民的损失",b="当地下科技城市诺莫瑞根沦陷于穴居人的入侵和有毒的放射性尘埃时，成千上万的侏儒带着他们能拿走的财产逃向丹莫罗白雪皑皑的地表。菲利克斯成功逃离了被辐射的废墟，但在撤离的混乱中，当地的霜鬃巨魔在大路上搜刮物资，袭击了零散的幸存者。菲利克斯丢失了他主要的工具包和随身物品，他那结实的箱子被搬到了巨魔在安威玛尔西南方的峭壁上建立的简陋营地里。"}},faq={{q="菲利克斯的箱子里有什么？",a="这个箱子里装的是菲利克斯在逃离诺莫瑞根时设法抢救出来的个人物品和私人物件。在他匆忙逃离致命辐射时被遗弃，里面的东西对巨魔来说毫无用处，却是他过去生活仅存的遗迹。",al={"菲利克斯的箱子内容物","箱子里有什么","菲利克斯的箱子掉落物"}},{q="为什么霜鬃巨魔会有菲利克斯的物品？",a="霜鬃巨魔经常骚扰路人并在寒脊山谷进行搜刮。当迷失方向的侏儒难民为了逃离他们被毁的城市而散布在丹莫罗各处时，巨魔伏击了掉队者，并将他们丢弃的装备和行李搬回了自己的营地。",al={"为什么巨魔会有菲利克斯的箱子","谁偷了菲利克斯的箱子","巨魔 菲利克斯"}},{q="箱子位于哪里？",a="这个箱子位于寒脊山谷安威玛尔的西南方，和其它抢来的补给品一起放在一个霜鬃巨魔定居点的帐篷旁。",al={"菲利克斯的箱子在哪里","菲利克斯的箱子位置","寻找菲利克斯的箱子"}}},fx={cd14610d={q="菲利克斯的箱子是什么？",a="菲利克斯的箱子里装着菲利克斯的个人物品和工具。他是一名侏儒难民，如今在安威玛尔避难。诺莫瑞根遭辐射侵袭时，菲利克斯逃进了丹莫罗，却在混乱的逃亡途中把箱子弄丢，被霜鬃巨魔夺走。",al={"菲利克斯的箱子是什么","菲利克斯的箱子","菲利克斯的箱子属于谁"}},bcb95cf5={q="菲利克斯为什么想拿回他的箱子？",a="诺莫瑞根惨遭覆灭时，菲利克斯几乎身无分文地逃了出来。箱子里装着他的个人物品和实用工具，这些必需品能帮助他在寒脊山谷的矮人中间生存下来，重新开始生活。他没有战胜霜鬃巨魔的本领，只能依靠愿意帮忙的冒险者找回箱子。",al={"菲利克斯为什么想要他的箱子","为什么需要菲利克斯的箱子","为什么要找回菲利克斯的箱子"}}},fp="13,257,18.547.0,29.271.0,52.277.0,27.148.0"}
P.entries["item:felstalker-hoof"] = {n="地狱捕猎者的蹄子",s="地狱捕猎者的蹄子是一种从肆虐杜隆塔尔试炼谷火刃集会所的恶魔野兽身上获得的实质性信物。年轻的萨满祭司必须取回这些蹄子，作为学习与大地元素之灵沟通前的试炼，以证明他们已做好准备。",h="地狱捕猎者的蹄子是一种从肆虐杜隆塔尔试炼谷火刃集会所的恶魔野兽身上获得的实质性信物。年轻的萨满祭司必须取回这些蹄子，作为学习与大地元素之灵沟通前的试炼，以证明他们已做好准备。",kw={"火刃集会所","call of earth","坎纳甘·地鸣","杜隆塔尔","大地药剂","地狱捕猎者","地狱捕猎者的蹄子","试炼谷"},ang={["class:Shaman"]="猎杀恶魔并收集它们的蹄子是你迈向与大地之灵沟通的第一大步，这考验着你是否有驾驭大地图腾所必需的耐心和顽强毅力。",["faction:Horde"]="杜隆塔尔训练场中出现的恶魔地狱捕猎者，时刻提醒着人们火刃氏族对部落领地挥之不去的腐蚀。"},sec={{t="萨满的试炼",b="在阳光炙烤的试炼谷中，训练师坎纳甘·地鸣要求萨满新星去直面威胁杜隆塔尔的恶魔腐蚀。北部的火刃集会所窝藏着邪恶的仆从和恶魔地狱捕猎者。取下这些魔物的蹄子不仅仅是为了清除害虫，更是一场关于耐力、意志和精神的严格考验。只有征服这些混乱的野兽，有志向的萨满祭司才能证明自己有资格获得大地的秘密，并准备好与元素之灵直接沟通所需的仪式药剂。"}},faq={{q="地狱捕猎者的蹄子有什么用？",a="两只地狱捕猎者的蹄子需要带给试炼谷的坎纳甘·地鸣。它们是萨满祭司学徒拥有与大地元素沟通所需的力量与精神的证明。",al={"地狱捕猎者的蹄子有什么用","蹄子任务物品","为什么要获得地狱捕猎者的蹄子"}},{q="这些蹄子从哪里来？",a="它们是从位于杜隆塔尔试炼谷北部尽头的火刃集会所内部及周边出没的恶魔地狱捕猎者身上获取的。",al={"哪里可以获得地狱捕猎者的蹄子","地狱捕猎者的蹄子位置","谁掉落蹄子"}},{q="谁需要这些蹄子？",a="坎纳甘·地鸣，驻扎在试炼谷大兽穴附近的萨满祭司训练师，会在Call of Earth仪式中索要它们。",al={"谁需要地狱捕猎者的蹄子","谁负责收取蹄子","坎纳甘·地鸣任务"}},{q="任何冒险者都能收集这些蹄子吗？",a="地狱捕猎者的蹄子专门供正在进行元素试炼的萨满祭司搜集。战士、术士和潜行者在谷中各有各的试炼，不需要这些东西。",al={"非萨满职业可以获得蹄子吗","蹄子是萨满专属吗"}}},fx={["1af4909c"]={q="地狱捕猎者的蹄子是什么？",a="地狱捕猎者的蹄子是从杜隆塔尔火刃氏族教徒召唤出的恶魔地狱捕猎者身上取得的实物战利品。它并非制作材料，而是年轻萨满为证明自己的战斗本领、寻求与大地之灵沟通而取得的凭证。",al={"地狱捕猎者的蹄子是什么","地狱捕猎者的蹄子信息"}}},fp="15,260,16.552.0,37.208.0,32.161.0,26.131.0,40.197.0"}
P.entries["item:fenwick-s-head"] = {n="芬维克的头颅",s="芬维克的头颅是取自芬维克·萨罗斯的恐怖处决证明，这颗头颅是在洛丹米尔湖岸边获得的。被遗忘者潜行者在收到瓦里玛萨斯领主直接下达的命令后，以此作为任务目标。",h="芬维克的头颅是取自芬维克·萨罗斯的恐怖处决证明，这颗头颅是在洛丹米尔湖岸边获得的。被遗忘者潜行者在收到瓦里玛萨斯领主直接下达的命令后，以此作为任务目标。",kw={"死亡猎手","芬威克","洛丹米尔","梅内特·卡卡德","rogues' quarter","银松森林","萨罗斯","瓦里玛萨斯"},ang={["class:Rogue"]="获取芬维克的头颅是新兴被遗忘者潜行者职业生涯中的一个决定性里程碑，确立了他们作为死亡猎手的可靠性，并使他们能够获得进阶训练的资格。",["race:Undead"]="这次狩猎展示了被遗忘者对银松森林和洛丹米尔湖岸边竞争控制权的敌对亡灵派系的无情镇压。"},sec={{t="来自阴影的契约",b="在幽暗城的Rogues' Quarter，梅内特·卡卡德根据恐惧魔王瓦里玛萨斯直接传来的紧急情报采取行动。一名名为芬维克·萨罗斯的敌对亡灵领袖在银松森林的洛丹米尔湖沿岸腐朽码头附近建立了一个据点。为了防止这一威胁集结敌对亡灵对抗被遗忘者，卡卡德派遣有前途的死亡猎手去定位萨罗斯，消灭他，并割下他的头颅作为无法抵赖的击杀证明。"},{t="通过试炼",b="将芬维克的头颅交给卡卡德不仅仅是简单的悬赏交付；这对于死亡猎手特工来说是一场至关重要的试炼。提交这枚被斩下的战利品证明了该潜行者在渗透和刺杀方面的能力，从而开启了向被遗忘者大师学习更深入、更专业暗影艺术的大门。"}},faq={{q="芬维克·萨罗斯是谁？",a="芬维克·萨罗斯被瓦里玛萨斯领主认定为盘踞在银松森林的一名亡灵领袖。他在洛丹米尔湖破败码头附近的出现，标志着他已成为威胁被遗忘者在该地区利益的直接危险。",al={"芬威克是谁","芬维克·萨罗斯背景故事","萨罗斯是谁"}},{q="谁想要芬维克的头颅？",a="这颗头颅是由驻扎在幽暗城Rogues' Quarter的死亡猎手训练师梅内特·卡卡德索要的，以执行瓦里玛萨斯领主传达的紧急命令。",al={"谁想要这颗头颅","上交任务的对象","梅内特·卡卡德"}},{q="芬维克·萨罗斯在哪里？",a="根据死亡猎手斥候收集的情报，芬维克·萨罗斯潜伏在银松森林洛丹米尔湖岸边的破败码头旁。",al={"芬维克·萨罗斯的位置","芬威克在哪里","寻找芬威克"}},{q="为什么要割下他的头颅？",a="梅内特·卡卡德要求提供不可辩驳的物理证据，证明威胁已被彻底消除，然后才会让特工进行进阶的暗影训练。",al={"为什么要割下他的头颅","为什么要将他斩首"}}},fx={bc6d2652={q="芬维克的头颅来自哪里？",a="这颗被砍下的头颅取自芬威克·萨罗斯。他是一名亡灵首领，在银松森林洛丹米尔湖岸边腐朽的码头附近出现。这不是人工制作的物品，而是战场上取得的敌方指挥官阴森遗骸。",al={"芬维克的头颅来历","哪里能找到芬维克的头颅","谁拿着芬维克的头颅"}}},fp="14,205,27.472.0,17.334.0,24.229.0,25.171.0,33.158.0,29.160.0"}
P.entries["item:fey-dragon-scale"] = {n="灵龙的鳞片",s="灵龙的鳞片是一种闪烁着光芒的林地遗物，采自石爪峰周围那些行踪诡秘的妖精龙。暗矛部族的巫医金吉尔一直在寻找这种鳞片，并将其作为一种奇异的试剂，用来调制一种嘲弄暗夜精灵自然魔法的炼金药剂。",h="灵龙的鳞片是一种闪烁着光芒的林地遗物，采自石爪峰周围那些行踪诡秘的妖精龙。暗矛部族的巫医金吉尔一直在寻找这种鳞片，并将其作为一种奇异的试剂，用来调制一种嘲弄暗夜精灵自然魔法的炼金药剂。",kw={"妖精龙","灵龙的鳞片","森林魔法","金吉尔","玛拉卡金","纳尔塔萨","石爪峰"},ang={["faction:Horde"]="协助金吉尔可以巩固部落在石爪山脉的立足点，直接打击盘踞在更高山坡上的暗夜精灵势力。",["race:NightElf"]="妖精龙是卡多雷珍视的伙伴和森林守护者；看到它们的鳞片被拔下来，用作巨魔巫医致命的嘲弄工具，是对自然的一种亵渎。"},sec={{t="稀有的森林收获",b="妖精龙是一种神秘且难以捉摸的生物，与卡利姆多的野生林地紧密相连，尤其是在石爪峰周围那些未受破坏的森林中。它们的鳞片带着一种天然的魔法光泽，令人想起它们所守护的幽深树林。虽然暗夜精灵将它们视为无害的林地精灵和盟友并尊崇有加，但在外人眼中，它们只是一种稀有魔法原料的来源。"},{t="一种嘲弄的药剂",b="在部落的定居点玛拉卡金，巫医金吉尔调制出了一种邪恶的混合剂，用来戏仿卡多雷的神圣传统。通过将灵龙的鳞片与树液、猫科动物的胡须以及数十只骏马的眼睛混合在一起，金吉尔调制出了他戏称为“森林魔法”的东西。这根本不是什么温和的自然祝福，这种残忍的药剂是专门为他关在笼子里的那三名暗夜精灵准备的。"}},faq={{q="这种鳞片来自哪里？",a="这种鳞片采集自穿梭在石爪峰周围高地树林中的妖精龙，包括像狡诈的灵龙和纳尔塔萨这样行踪诡秘的生物。",al={"灵龙的鳞片掉落","哪里可以找到灵龙的鳞片","什么怪物掉落灵龙的鳞片"}},{q="为什么巫医金吉尔想要灵龙的鳞片？",a="玛拉卡金的巫医金吉尔要求得到这种鳞片，以及其他林地试剂，以便为他囚禁的暗夜精灵俘虏调制他那种嗤之以鼻的“森林魔法”。",al={"为什么金吉尔需要这个","鳞片的用途","金吉尔的森林魔法试剂"}},{q="当金吉尔完成他的药剂后会发生什么？",a="金吉尔计划对他俘虏的三名暗夜精灵使用调制好的药剂。当他实施该计划时，这些囚犯的命运就会揭晓。",al={"金吉尔用药剂做什么","金吉尔的魔法结果","金吉尔的囚犯"}}},fx={["9423a9c1"]={q="灵龙的鳞片是什么？",a="灵龙的鳞片是从石爪峰难以寻觅的仙女龙身上采集的鳞片，闪烁着虹彩般的光泽。这些神秘生物与荒野的自然能量息息相关。对炼金师或巫医而言，这种鳞片是强效的魔法试剂，蕴含着古老森林的原始精华。",al={"灵龙的鳞片是什么","灵龙鳞片的背景","关于灵龙的鳞片"}}},fp="16,269,21.382.0,20.403.1,32.169.0,54.170.0,44.141.1"}
P.entries["item:filled-amethyst-phial"] = {n="装满的紫水晶瓶",s="装满的紫水晶瓶中盛着从The Oracle Tree枝叶下的古老月亮井中取出的圣水。这是受科瑞萨斯·月怒之托收集的，这些纯净的水被塞纳里奥德鲁伊用来研究泰达希尔那令人不安的、不完美的生长状况。",h="装满的紫水晶瓶中盛着从The Oracle Tree枝叶下的古老月亮井中取出的圣水。这是受科瑞萨斯·月怒之托收集的，这些纯净的水被塞纳里奥德鲁伊用来研究泰达希尔那令人不安的、不完美的生长状况。",kw={"紫水晶瓶","科瑞萨斯·月怒","crown of the earth","装满的紫水晶瓶","月亮井","神谕林地","the oracle tree","泰达希尔"},ang={["class:Druid"]="塞纳里奥德鲁伊将月亮井尊为自然与星界能量的通道，他们使用像这个瓶子这样的净化容器来研究泰达希尔遭受污染的生态。",["race:NightElf"]="对于卡多雷来说，装满这个瓶子标志着一个严峻的现实：他们辉煌的新家园被守护巨龙所拒绝，而他们失去的永生也并未回归。"},sec={{t="The Oracle Tree之水",b="在泰达希尔西北方向的遥远之处坐落着神谕林地，岛上最古老、最强大的月亮井就静卧在巨大的The Oracle Tree之下。虽然遍布枝叶间的那些较小的月亮井满足了暗夜精灵们日常所需，但这座水井中却蕴含着艾露恩恩赐的原始精华。负责监测世界之树健康的德鲁伊们使用特制的紫水晶瓶来收集并保存这种强大的液体，以进行测试和仪式净化。"},{t="充满瑕疵的重生",b="将样本带回给科瑞萨斯·月怒有着一个沉重的目的。尽管大德鲁伊范达尔·鹿盔成功培育了泰达希尔以取代倒下的诺达希尔，但守护巨龙们拒绝赐福于它。没有诺兹多姆的祝福来恢复暗夜精灵的永生，也没有阿莱克丝塔萨来保护其生命力，泰达希尔的生长依然受到阻碍，并饱受腐蚀的困扰。从林地采集的样本表明，即使是岛上最神圣的泉水，也无法掩盖正在世界之树中蔓延的病态。"}},faq={{q="这个瓶子里的水来自哪里？",a="这些水是直接从神谕林地的月亮井中汲取的，该井位于泰达希尔西北部，巨大的The Oracle Tree根系之下。",al={"在哪里装水","月亮井位置","the oracle tree水井"}},{q="为什么神谕林地的月亮井很特别？",a="它被视为泰达希尔上建造的第一口、也是最强大的月亮井，蕴含着艾露恩力量的精华，并由古老的The Oracle Tree亲自守护。",al={"为什么去神谕林地","神谕月亮井的重要性"}},{q="是谁让你去收集这些水？",a="驻扎在多兰纳尔的暗夜精灵德鲁伊科瑞萨斯·月怒，指派年轻的冒险者去收集这些水，作为Crown of the Earth仪式的一部分。",al={"谁需要这个瓶子","科瑞萨斯任务"}},{q="为什么德鲁伊们要测试泰达希尔的月亮井？",a="泰达希尔在没有守护巨龙祝福的情况下被培育出来，这使其变得脆弱。德鲁伊们对月亮井进行采样，以监测世界之树的健康状况，目前它正显露出腐蚀和生长受阻的令人担忧的迹象。",al={"为什么要测试水质","泰达希尔的病症"}}},fx={d7e170ec={q="装满的紫水晶瓶是什么？",a="装满的紫水晶瓶中盛有圣水，取自神谕林地神谕之树下的月亮井。它是泰达希尔最初、力量最强大的月亮井，井水闪烁着光辉，蕴含着艾露恩恩泽的浓缩精华。这份样本对研究岛屿状况的卡多雷至关重要。",al={"装满的紫水晶瓶是什么","装满的紫水晶瓶物品","紫水晶瓶有什么用"}}},fp="21,266,24.487.0,16.525.1,45.161.0,44.178.0,34.153.0,50.224.0"}
P.entries["item:filled-blue-waterskin"] = {n="装满水的蓝色水囊",s="装满水的蓝色水囊中盛放着来自灰谷星尘废墟中远古喷泉的纯净之水。寻求与水之灵沟通的萨满祭司需要采集这份样本，作为他们试炼之路的重要试剂。",h="装满水的蓝色水囊中盛放着来自灰谷星尘废墟中远古喷泉的纯净之水。寻求与水之灵沟通的萨满祭司需要采集这份样本，作为他们试炼之路的重要试剂。",kw={"灰谷","brine","call of water","装满水的蓝色水囊","米斯特拉湖","星尘废墟","萨满任务"},ang={["class:Shaman"]="获取这神圣之水代表了你掌握水元素之旅的终点，需要你跨越敌对阵营边界，与大自然最纯净的源头进行沟通。",["faction:Horde"]="冒险进入灰谷的争夺领土对部落的入门者来说意味着真正的危险，迫使你进入暗夜精灵的祖传领地来完成神圣仪式。"},sec={{t="灰谷圣泉",b="进行Call of Water试炼的入门者会被指引向北，穿过贫瘠之地边境，进入灰谷茂密的森林。在灰谷与石爪山脉之间的群山旁，米斯特拉湖的彼端，坐落着星尘废墟——这是一处被凶猛的森林野兽所守卫的隐秘精灵圣地。在这片圣湖的中心有一座未经触碰的喷泉。用蓝色水囊从水池中汲取的水未受腐蚀或干旱的侵染，被萨满大师视为祭祀调和的珍品。"},{t="和谐仪式",b="这个容器中收集的水是Brine所需的最后一份样本，他是一位隐居在南贫瘠之地一座小山上的水元素专家。将这些水与从其他不同水井和泉水中收集的水混合，这种纯净的精华会被提炼成一种强效的祭品，足以显现并安抚水元素之灵，从而完成入门者的试炼。"}},faq={{q="在哪里收集水来装满这个水囊？",a="它需要从位于灰谷西南部、米斯特拉湖之外的星尘废墟中，湖中心的一座小喷泉里汲取。",al={"我在哪里装水","星尘废墟喷泉","水源位置"}},{q="谁需要这份水？",a="Brine，一位居住在贫瘠之地南部边缘的资深隐士，指示新手萨满去取这份水，作为Call of Water试炼的一部分。",al={"谁需要蓝色水囊","brine的水","call of water npc"}},{q="收集这份样本的目的是什么？",a="这是Brine酿造极其纯净之水所需的最后一种试剂，它能让有抱负的萨满与水元素之灵沟通并表达敬意。",al={"为什么我需要它","装满水的蓝色水囊有什么用"}},{q="收集水的地方危险吗？",a="是的。星尘废墟栖息着充满敌意的野生生物，包括当地的元素生物和凶猛的野兽，它们守卫着这片古老的精灵林地，抵御入侵者。",al={"星尘废墟危险吗","灰谷喷泉安全吗"}}},fx={["031dd284"]={q="装满水的蓝色水囊是什么？",a="装满水的蓝色水囊是一个皮革容器，里面装着从灰谷深处星尘废墟喷泉中收集的纯净泉水。它是萨满进行神圣的《水之召唤》试炼所需的必要元素样本之一。",al={"装满水的蓝色水囊是什么","装满水的蓝色水囊物品"}},eff34fc2={q="装满水的蓝色水囊来自哪里？由谁制作？",a="水囊本身是一个空袋子，由居住在南贫瘠之地的隐士布莱恩交给你。你向北前往古老的精灵领地灰谷，从星尘废墟湖心的神圣喷泉中汲取清水后，它便成为装满水的蓝色水囊。",al={"装满水的蓝色水囊来自哪里","谁制作了装满水的蓝色水囊","装满水的蓝色水囊的来源"}},["320c16da"]={q="布莱恩为什么想要装满水的蓝色水囊？",a="布莱恩需要这份样本，作为收集艾泽拉斯各地纯净水源的最后一部分。将它与此前收集的其他水源混合后，她会调制出一瓶纯净无瑕的水，供你进行萨满仪式下一阶段的成年礼。",al={"布莱恩为什么需要装满水的蓝色水囊","为什么有人想要装满水的蓝色水囊","装满水的蓝色水囊有什么用"}}},fp="21,233,26.515.0,17.372.0,51.160.0,24.155.0,46.178.0,50.164.0"}
P.entries["item:filled-brown-waterskin"] = {n="装满水的棕色水囊",s="装满水的棕色水囊中装有从贫瘠之地布莱恩小屋附近一处罕见池塘中汲取的淡水。这对于有志成为萨满祭司的人来说，是酿造与水之灵沟通所需的药水的第一步基础。",h="装满水的棕色水囊中装有从贫瘠之地布莱恩小屋附近一处罕见池塘中汲取的淡水。这对于有志成为萨满祭司的人来说，是酿造与水之灵沟通所需的药水的第一步基础。",kw={"贫瘠之地","布莱恩","棕色水囊","call of water","装满水的棕色水囊","野猪人","药水","萨满祭司任务"},ang={["class:Shaman"]="在“Call of Water”任务中，布莱恩会将取水作为第一个实践测试，教导你尊重围绕生命之水的脆弱平衡与激烈欲望。"},sec={{t="生命之水",b="在贫瘠之地的干旱广袤区域，地表水既是恩赐也是战场。位于布莱恩小屋下方的池塘提供了珍贵的水源，吸引了附近居住的绝望且充满防御性的野猪人。对于走上萨满祭司之路的入门者来说，装满这个简单的皮质水囊不仅仅是收集物资的任务；这更是一堂元素课程。通过接近池塘并亲眼目睹周围激烈的领地争夺，新手可以直观地观察到，这种维持沙漠生命的物质是如何驱使凡人生物走向暴力的。"}},faq={{q="装满水的棕色水囊有什么用？",a="它需要被直接带到位于南贫瘠之地布莱恩的小屋处。她利用收集到的水开始准备元素药水，这种药水能让萨满祭司感知并与水之灵沟通。",al={"棕色水囊用途","什么是装满水的棕色水囊","如何使用装满水的棕色水囊"}},{q="这水是从哪里来的？",a="它是从位于布莱恩与世隔绝的小屋下方的山脊下方的一个小淡水池中汲取的，那是一个被当地野猪人激烈争夺的绿洲。",al={"从哪里获得水","池塘位置","水源在哪里"}},{q="为什么野猪人要争夺这个水源？",a="在干旱的贫瘠之地，雨水极其罕见，使得任何池塘都成了巨大的财富。水极其稀缺，以至于野猪人在下雨时会举行盛宴，并会誓死守卫天然泉水，以防外人侵入。",al={"为什么野猪人会攻击","野猪人水源","为什么水对野猪人是神圣的"}}},fx={["52b5cef0"]={q="装满水的棕色水囊是什么？",a="这是一只简单的水囊，里面装着贫瘠之地干旱土地上、Brine小屋下方池塘里的淡水。这些水是萨满试炼的一部分，作为纯净的元素样本，证明即使是一小片水洼也能在干旱的沙漠中滋养生命、引发冲突。",al={"装满水的棕色水囊","装满水的棕色水囊是什么","棕色水囊是什么"}}},fp="22,235,21.593.0,44.210.0,32.153.0,49.211.0"}
P.entries["item:filled-cliffspring-falls-sampler"] = {n="盛满的峭壁之泉取样器",s="盛满的峭壁之泉取样器中装有取自黑海岸峭壁之泉源头的浑浊之水。这是受塞纳里奥议会之托所收集的样本，也是揭开当地鹿群中毒之谜的关键证据。",h="盛满的峭壁之泉取样器中装有取自黑海岸峭壁之泉源头的浑浊之水。这是受塞纳里奥议会之托所收集的样本，也是揭开当地鹿群中毒之谜的关键证据。",kw={"奥兰达利亚·夜歌","奥伯丁","塞纳里奥议会","峭壁之泉","黑海岸","德迪利特·星焰","毒水","取样器"},ang={["class:Druid"]="获取并分析这些受污染的水是联盟德鲁伊的一项重要试炼，构成了掌握“驱毒术”的调查基础。",["race:NightElf"]="对于黑海岸的暗夜精灵来说，保护峭壁之泉的源头对于维护奥伯丁的生态环境、抵御邪恶的外部污染至关重要。"},sec={{t="被污染的源头",b="峭壁之泉是黑海岸大部分地区的主要饮用水源，水流从东部高地倾泻而下，奔向大海。然而近来，依赖这些水源的野生生物——特别是当地的鹿群——却遭受了一种虚弱且非自然的疾病。应月光林地的德迪利特·星焰之请，德鲁伊学徒们直接从一个被充满敌意的纳迦占据的洞穴入口处获取了样本。小瓶中装着肉眼可见的腐臭液体，证实了该地区的主要淡水供应正受到主动污染。"},{t="治愈之路",b="这些污秽的样本被带到奥伯丁交给奥兰达利亚·夜歌，为塞纳里奥议会研究毒素提供了实物证据。奥兰达利亚没有简单地将其处理掉，而是利用这些受污染的水来分析污染物的成分。破译这些淤泥的确切属性，使德鲁伊们能够合成出治疗药膏，这是开发赋予修行者解毒之力的仪式中至关重要的一步。"}},faq={{q="盛满的峭壁之泉取样器里装的是什么？",a="它装有从黑海岸峭壁之泉附近的洞穴入口舀取的受污染的水。这些水明显变色，并携带了导致当地鹿群患病的毒素。",al={"取样器内容物","瓶子里装的是什么水","样本里有什么"}},{q="是谁要求获取这个水样本的？",a="塞纳里奥议会的德迪利特·星焰指示年轻的德鲁伊去收集样本，而奥伯丁的奥兰达利亚·夜歌则负责接收样本，以分析毒素并配制解药。",al={"谁需要这个水样本","我该把取样器交给谁","谁需要盛满的取样器"}},{q="为什么峭壁之泉如此重要？",a="峭壁之泉是黑海岸地区主要的饮用水源。任何引入泉水的污染都会扩散到当地的水道中，并影响整个荒野。",al={"为什么是峭壁之泉","峭壁之泉的重要性"}},{q="是什么导致了水质变坏？",a="水源来自一个近期被敌对纳迦占据的洞穴附近。它们的出现与源头被污染的时间相吻合，并在当地动物群中传播了非自然的疾病。",al={"是谁污染了水源","为什么泉水会被污染","纳迦与峭壁之泉"}}},fx={["57552b8f"]={q="盛满的峭壁之泉取样器来自哪里？由谁制作？",a="塞纳里奥议会的德迪利特·星焰在月光林地将空的玻璃取样管交给年轻的德鲁伊。你将它带到黑海岸峭壁之泉旁、娜迦盘踞的洞穴入口，从受污染的溪流中直接取水后，它便成为盛满的峭壁之泉取样器。",al={"盛满的峭壁之泉取样器的来源","谁制作了峭壁之泉取样器","在哪里获得峭壁之泉取样器"}}},fp="32,252,16.544.0,16.429.1,52.195.0,31.184.0,38.197.0,39.184.0"}
P.entries["item:filled-containment-coffer"] = {n="装满的封灵箱",s="装满的封灵箱是一种被遗忘者施法者用来囚禁不稳定魔法实体的附魔容器。通过使用显形卷轴来揭示并削弱药剂区的裂隙之卵，法师们可以将这些异常生物囚禁在加固的盒子里，以便安全地进行检查。",h="装满的封灵箱是一种被遗忘者施法者用来囚禁不稳定魔法实体的附魔容器。通过使用显形卷轴来揭示并削弱药剂区的裂隙之卵，法师们可以将这些异常生物囚禁在加固的盒子里，以便安全地进行检查。",kw={"阿尔杰农","安娜斯塔西娅·哈特威尔","apothecarium","奥术骚乱","显形卷轴","封灵箱","装满的封灵箱","裂隙之卵"},ang={["class:Mage"]="被遗忘者学徒将处理这些封灵箱作为防护系魔法的实践课程，学习如何揭示隐藏的魔法实体并将不稳定的奥术能量束缚在物理结界中。",["race:Undead"]="药剂区的安全对被遗忘者至关重要，因此调查并控制任何神秘的魔法缺口是当务之急。"},sec={{t="囚禁无形之物",b="当药剂区的阿尔杰农商店内出现无法解释的魔法骚乱时，被遗忘者法师安娜斯塔西娅·哈特威尔委托奥术修行者去捕捉造成骚乱的实体。由于这些裂隙生物完全由活体魔法能量构成且隐形游荡，普通的笼子根本毫无用处。施法者必须使用显形卷轴揭示这些实体的存在，在战斗中击败它们，然后将这些特制的封灵箱合上。密封的盒子能保护携带者免受波动的魔法反噬，同时保持样本完整，以便进行魔法解剖。"},{t="奥术取证",b="幽暗城内出现活体法力生物构成了严重的威胁。一旦被封入封灵箱，这些被俘的野兽就会被送回安娜斯塔西娅·哈特威尔和城里的学者手中。被遗忘者法师们最关心的是确认这些入侵究竟是艾泽拉斯魔法结构中的自然裂隙，还是针对王国的蓄意魔法袭击的前奏。"}},faq={{q="装满的封灵箱里有什么？",a="每个箱子里都装着一只被捕获的裂隙之卵，这是一种完全由原始魔法能量构成的隐形生物，出现在药剂区的阿尔杰农炼金商店内。",al={"箱子里有什么","箱子内容物","装满的箱子里的怪物"}},{q="如何装满封灵箱？",a="法师必须阅读显形卷轴使隐藏的生物现形，在战斗中击败它们，并在能量消散前使用一个空箱子将其囚禁。",al={"如何装满箱子","我该如何捕捉裂隙之卵","装满箱子"}},{q="幽暗城的谁需要这些装满的箱子？",a="幽暗城魔法区的著名法师训练师安娜斯塔西娅·哈特威尔要求提供这些密封的箱子，以调查威胁城市的骚乱。",al={"谁会接收这些箱子","箱子任务发布者","安娜斯塔西娅·哈特威尔的箱子"}},{q="为什么被遗忘者要研究这些生物？",a="幽暗城的学者需要查明这一异常现象是当地魔法流中的随机撕裂，还是敌对魔法势力精心策划的协同攻击。",al={"为什么研究裂隙之卵","幽暗城裂隙原因"}}},fx={d6cc8dac={q="装满的封灵箱是什么？",a="装满的封灵箱是一种附魔容器，法师用它来捕捉并禁锢纯粹由魔法能量构成的不稳定生物，例如裂隙生物。迫使生物现身并将其制服后，封灵箱便能安全地将它封存起来，以供运输和研究，同时避免其魔法精华消散。",al={"装满的封灵箱是什么","装满的封灵箱","封灵箱物品"}},["1e3ef013"]={q="装满的封灵箱来自哪里？由谁制作？",a="安娜斯塔西娅·哈特威尔等法师导师会提供这种空的封灵箱，它们是特制的奥术装置。熟练的法师追踪隐形魔法生物——例如潜伏在Apothecarium的Algernon商店周围的生物——迫使它们现身、削弱它们，再将它们封入箱中，封灵箱便装满了。",al={"谁制作了封灵箱","封灵箱的来源","封灵箱来自哪里"}}},fp="25,294,19.619.0,16.414.0,43.164.0,35.186.0,44.166.0,46.173.0"}
P.entries["item:filled-crystal-phial"] = {n="装满水的水晶瓶",s="装满水的水晶瓶中盛放着取自幽影谷，奥达希尔正北面月亮井的神圣井水。在特纳隆·雷拳的指示下采集这些井水，旨在让新手初步了解泰达希尔中所流动的神圣而又不稳定的力量。",h="装满水的水晶瓶中盛放着取自幽影谷，奥达希尔正北面月亮井的神圣井水。在特纳隆·雷拳的指示下采集这些井水，旨在让新手初步了解泰达希尔中所流动的神圣而又不稳定的力量。",kw={"奥达希尔","crown of the earth","水晶瓶","装满水的水晶瓶","月亮井","幽影谷","特纳隆·雷拳","永恒之井"},ang={["class:Druid"]="德鲁伊对月亮井水怀有深深的敬意，利用其恢复性能量来照料受腐蚀的植物并维持巨树的生命。",["race:NightElf"]="每一位在奥达希尔之下开始训练的年轻卡多雷都会装满这只瓶子，以此反思海加尔山的牺牲以及他们保护自然的圣洁职责。"},sec={{t="月亮井之水",b="为了让年轻的暗夜精灵在涉足广阔世界前做好准备，特纳隆·雷拳会派遣他们去收集幽影谷中那口月亮井的井水。这只瓶子里装的可不仅仅是普通的泉水；月亮井中注入了追溯至远古永恒之井的残留能量。尽管哨兵视这些地点为艾露恩受祝福的神龛，德鲁伊则引导其中的恢复性力量来照料自然，但远古的奥术魔法仍被严格禁止。汲取这些井水是了解海加尔山的牺牲以及呵护泰达希尔所需达到的微妙平衡的第一步。"}},faq={{q="装满水的水晶瓶里有什么？",a="瓶中装的是取自幽影谷奥达希尔北面月亮井的井水。这些井水带有远古永恒之井的残余，受到艾露恩之光的祝福，并由德鲁伊精心照料。",al={"瓶子里装的是什么水","瓶子内容物","水晶瓶里有什么"}},{q="是谁让你去装满瓶子的？",a="驻守在奥达希尔枝头的特纳隆·雷拳派遣初出茅庐的冒险者去取水，作为他们成人礼和历史教育的一部分。",al={"谁需要这个瓶子","谁发放水晶瓶任务","特纳隆·雷拳任务"}},{q="为什么特纳隆·雷拳需要这些水？",a="特纳隆将这一采集任务作为第三次战争后暗夜精灵历史的开篇课程，教导年轻的冒险者关于诺达希尔的牺牲、月亮井的力量以及对泰达希尔持续的管理。",al={"为什么要装满水晶瓶","crown of the earth的作用"}},{q="这些井水危险吗？",a="这些井水蕴含着根植于远古永恒之井的强大魔法。虽然德鲁伊和女祭司可以安全地使用它们进行祝福和治疗，但在远古时期，对这类井水的鲁莽奥术操纵曾引发了大灾难，因此至今仍被严格禁止。",al={"月亮井水是否危险","水中有魔法吗"}}},fx={e7bb2009={q="装满水的水晶瓶是什么？",a="装满水的水晶瓶是一只精致的水晶容器，里面装着从幽影谷月亮井中采集的水。瓶中盛放着纯净而神圣的液体，其中蕴含着永恒之井的古老力量，既是神圣的供品，也是关于你的族人如何持续守护精神传承的实践课程。",al={"装满水的水晶瓶是什么","装满水的水晶瓶","装满水的水晶瓶物品"}},e140e7c7={q="装满水的水晶瓶来自哪里？",a="特纳隆·雷拳会交给你一只空的水晶瓶。你将它直接浸入幽影谷奥达希尔正北方的神圣月亮井水中，就能制成装满水的水晶瓶。",al={"装满水的水晶瓶的来源","装满水的水晶瓶来自哪里","如何获得装满水的水晶瓶"}}},fp="20,265,22.622.0,40.195.0,31.165.0,43.227.0,25.253.0"}
P.entries["item:filled-cursed-ooze-jar"] = {n="被诅咒的软泥怪样本",s="“被诅咒的软泥怪样本”里装有从被腐蚀的费伍德森林中收集的被诅咒软泥怪的有害残余。它是应铁炉堡的侏儒学者拉里斯·空轮的要求而收集的，他旨在揭开艾泽拉斯各地软泥怪的原始起源。",h="“被诅咒的软泥怪样本”里装有从被腐蚀的费伍德森林中收集的被诅咒软泥怪的有害残余。它是应铁炉堡的侏儒学者拉里斯·空轮的要求而收集的，他旨在揭开艾泽拉斯各地软泥怪的原始起源。",kw={"被诅咒的软泥怪","探险者协会","费伍德森林","被诅咒的软泥怪样本","铁炉堡","拉里斯·空轮","软泥怪"},ang={["faction:Alliance"]="铁炉堡的联盟自然哲学家们时刻关注着被遗忘者的动向，并注意到皇家药剂师学会也在全艾泽拉斯范围内对收集软泥怪样本表现出了阴暗的兴趣。",["race:Gnome"]="拉里斯·空轮对软泥怪研究的痴迷有着深层的个人原因，他渴望为流离失所的侏儒带来荣耀，并向铁炉堡的矮人东道主证明他们的智力价值。"},sec={{t="一个奇特的样本",b="尽管大多数冒险者对卡利姆多各地四处爬行的肮脏水洼和腐蚀性软泥避之不及，但侏儒研究员拉里斯·空轮却将其视为一种生物学谜团。他注意到软泥怪出现在各种不同的环境中，并观察到被遗忘者药剂师在努力采集它们，于是空轮提出了一个颇具争议的理论：软泥怪可能是与艾泽拉斯的创造直接相关的原始分泌物。收集样本需要闯入费伍德森林那片被枯萎侵蚀的树林，击败一只被诅咒的软泥怪，并在它完全溶解前将酸性物质舀入一个空瓶中。"},{t="学术抱负",b="对于空轮来说，获得这些刺鼻的样本有着双重目的。除了追求自然科学之外，他希望一项重大发现能巩固他在以矮人为主导的探险者协会中的声誉。在诺莫瑞根遭遇毁灭性的陷落后，铁炉堡的许多侏儒难民都感到证明自己对矮人东道主价值的巨大压力，空轮相信，解开软泥怪的古老秘密将向所有人证明，欢迎侏儒并没有错。"}},faq={{q="这个瓶子从哪里来？",a="它通过在被腐蚀的费伍德森林土地上，对被击败的“被诅咒的软泥怪”的残骸使用“被诅咒的软泥怪采样瓶”来获得。",al={"哪里获得被诅咒的软泥怪采样瓶","如何获得被诅咒的软泥怪样本","软泥怪样本瓶位置"}},{q="谁需要这些软泥怪样本？",a="位于铁炉堡Hall of Explorers的侏儒研究员拉里斯·空轮，请求这些样本以推进他的自然历史研究。",al={"谁需要软泥怪样本瓶","拉里斯·空轮任务","谁交还软泥怪样本瓶"}},{q="为什么拉里斯·空轮要研究软泥怪？",a="他注意到自然界和皇家药剂师学会都对软泥怪非常感兴趣。他假设软泥怪可能是与艾泽拉斯生命的创造和发展紧密相连的古老分泌物，但他需要物理样本来验证他的理论。",al={"为什么要研究软泥怪","空轮的软泥怪理论","为什么是软泥怪"}},{q="为什么侏儒会在意探险者协会？",a="在诺莫瑞根陷落后，侏儒难民在铁炉堡的矮人中间寻求庇护。空轮希望通过探险者协会取得重大的科学突破，从而向他们的东道主证明庇护侏儒是正确的选择。",al={"为什么要加入探险者协会","铁炉堡的侏儒"}}},fx={b5982a20={q="被诅咒的软泥怪样本是什么？",a="这是一只经过特殊处理的样本容器，里面装着从费伍德森林被杀死的被诅咒的软泥怪身上采集的新鲜样本。这些污秽、腐化的软泥怪在受污染森林的恶魔腐朽之气中滋生，即使是少量残留物也不稳定且危险，必须用合适的玻璃容器才能安全处理。",al={"被诅咒的软泥怪样本是什么","被诅咒的软泥怪样本的用途","被诅咒的软泥怪样本"}}},fp="22,262,18.568.0,17.476.0,30.124.0,29.138.0,39.263.0,50.255.0"}
P.entries["item:filled-dreadmist-peak-sampler"] = {n="盛满的鬼雾峰取样器",s="盛满的鬼雾峰取样器是一个瓶子，里面装有从贫瘠之地北部的鬼雾峰顶的水池中提取的受污染的水。这些水是由部落的德鲁伊新手采集的，为塞纳里奥议会研究毒害该地区野生动物的邪恶疾病提供了所需的实物证据。",h="盛满的鬼雾峰取样器是一个瓶子，里面装有从贫瘠之地北部的鬼雾峰顶的水池中提取的受污染的水。这些水是由部落的德鲁伊新手采集的，为塞纳里奥议会研究毒害该地区野生动物的邪恶疾病提供了所需的实物证据。",kw={"火刃氏族","塞纳里奥议会","鬼雾峰","德鲁伊","盛满的鬼雾峰取样器","贫瘠之地","主要源头","图加·符文图腾"},ang={["class:Druid"]="回收这个样本是部落德鲁伊不可或缺的成人仪式，它教会了德鲁伊自然水道是如何传播腐化的，并为他们掌握治愈魔法做好了准备。",["faction:Horde"]="调查鬼雾峰揭露了火刃氏族在部落位于贫瘠之地的领地中心地带所带来的日益严重的威胁。"},sec={{t="受污染的源头",b="鬼雾峰的高耸峭壁上有天然的水池，其水汽历来影响着整个贫瘠之地北部的天气和降雨。当崇拜恶魔的火刃氏族在峰顶建立据点后，水质迅速恶化。塞纳里奥议会的德鲁伊们怀疑是恶魔仪式毒害了滋养周边草原的水汽，于是派遣新手使用专门的取样器采集样本。瓶中恶臭的液体证实了他们最担心的猜想，这种腐蚀性的恶臭足以让下方游荡的兽群染病。"},{t="治愈草原",b="这个邪恶的样本会被送到十字路口的图加·符文图腾手中，作为研制解毒剂的焦点。虽然火刃氏族被怀疑是污染水源的罪魁祸首，但分析样本的特性使塞纳里奥议会能够了解这种毒素的本质。通过隔离瓶中的污染物，德鲁伊们研制出了所需的草药疗法，以清除濒死瞪羚体内的毒素，并掌握了他们自身控制毒素的自然之力。"}},faq={{q="在哪里可以获得这个水样本？",a="样本采集自鬼雾峰的最高峰顶的一处水池，鬼雾峰是位于贫瘠之地十字路口西北方向的一座崎岖山峰。",al={"在哪里可以获得样本","鬼雾峰取样器位置","在哪里填充取样器"}},{q="为什么鬼雾峰的水会被污染？",a="火刃氏族占领了鬼雾峰的高处，在那里进行恶魔崇拜活动。德迪利特·星焰怀疑该教派污染了山顶的天然水源。",al={"为什么鬼雾峰的水有毒","谁污染了鬼雾峰","火刃氏族水源"}},{q="谁需要这个盛满的取样器？",a="它必须被送到图加·符文图腾手中。图加是一位驻扎在贫瘠之地十字路口的塞纳里奥德鲁伊，他正在调查困扰该地区野生动物的突发性疾病。",al={"我该把取样器交给谁","图加·符文图腾取样器","上交鬼雾峰之水"}},{q="这种被污染的水对贫瘠之地有什么影响？",a="鬼雾峰上空旷的山峰和水池自然地影响着当地的天气模式和水汽。当水源受到污染时，带毒的水汽便会笼罩在主路北侧的草原上，导致当地的瞪羚大面积患病。",al={"这些水有什么作用","贫瘠之地患病的瞪羚","鬼雾峰水汽的影响"}},{q="取样器在采集后有何用途？",a="图加·符文图腾会对恶臭液体进行分析，以辨别恶魔污染的确切属性，并利用这些知识调配出一种治疗软膏，供德鲁伊用来治疗患病的瞪羚。",al={"图加用它做什么","毒素的解药","关于毒素的研究"}}},fx={f843c928={q="盛满的鬼雾峰取样器是什么？",a="这是一只特制的小瓶，里面装着直接从鬼雾峰顶高处水池采集的受污染水样。塞纳里奥议会将它交给德鲁伊新兵，作为重要的实物证据，证明污秽的腐化正从高山泉水中渗出，并正在毁坏北部平原各处的野生生物。",al={"盛满的鬼雾峰取样器是什么","鬼雾峰取样器","德鲁伊的盛满取样器"}},["2e934816"]={q="盛满的鬼雾峰取样器来自哪里？由谁制作？",a="塞纳里奥议会在月光林地将空的玻璃取样瓶交给学习治疗疾病之术的年轻德鲁伊。你要亲自在贫瘠之地的鬼雾峰顶水池中将它装满。崇拜恶魔的火刃氏族教徒聚集在那里，污染着影响周边气候的天然水源。",al={"谁制作了鬼雾峰取样器","鬼雾峰取样器来自哪里","鬼雾峰取样器的来源"}},cb57b91c={q="图加·符文图腾为什么需要盛满的鬼雾峰取样器？",a="十字路口的图加·符文图腾急需这些水样，以研究影响贫瘠之地北部的疫病。瞪羚和当地动物正接连病倒。图加希望通过分析来自山峰的污秽样本，找出这种异常毒素，并调制出有效的草药疗方来治愈这片土地。",al={"图加为什么需要取样器","图加·符文图腾的鬼雾峰样本","为什么要取得盛满的鬼雾峰取样器"}}},fp="29,312,16.536.0,18.442.1,36.157.0,43.177.0,29.169.0,48.225.0,51.192.0"}
P.entries["item:filled-etched-phial"] = {n="装满水的蚀刻瓶",s="“装满水的蚀刻瓶”是一种华丽的树妖容器，里面装满了直接取自灰谷暗夜精灵月亮井的圣水。应雷霆崖牛头人的请求，这种圣水具备熄灭守护一件神圣半人马遗物的不灭之焰所需的罕见灵力。",h="“装满水的蚀刻瓶”是一种华丽的树妖容器，里面装满了直接取自灰谷暗夜精灵月亮井的圣水。应雷霆崖牛头人的请求，这种圣水具备熄灭守护一件神圣半人马遗物的不灭之焰所需的罕见灵力。",kw={"灰谷","树妖","蚀刻瓶","装满水的蚀刻瓶","加拉克","月亮井","劳恩·峭壁行者","千针石林","赞金·石蹄"},ang={["race:NightElf"]="暗夜精灵认为部落特工窃取树妖的瓶子并汲取月亮井水的行为，是对灰谷最神圣庇护所不可原谅的侵犯。",["race:Tauren"]="对牛头人而言，获取这种水是针对加拉克半人马的一次精心算计的打击，利用塞纳留斯之子共有的自然魔法来对付他们长期的部族宿敌。"},sec={{t="月亮井水与树妖工艺",b="Obtaining this phial demands infiltrating night elf territory deep within Ashenvale. The empty vessel must first be claimed from the dryads around Raynewood Retreat, whose delicate containers are crafted to hold pure restorative draughts. Filled subsequently at a sacred moonwell near the western bank of the Falfarren River, the phial captures water brimming with celestial, nature-bound power. To the night elves, taking this water uninvited is an act of blatant desecration, but the tauren see it as a vital necessity for addressing a regional threat further south."},{t="通往半人马巫术的关键",b="赞金·石蹄和劳恩·峭壁行者寻找这种特殊的水，是因为树妖和半人马之间存在着隐秘的神话渊源。这两个种族都将血统追溯到塞纳留斯，使得他们的魔法传统有着深刻而交织的共鸣。在千针石林，加拉克部族守护着一件古老的遗物，受某种追溯到半人马种族起源的不灭之火保护。由于拥有共同的原始根源，盛装在这种树妖瓶子里的月亮井圣水能够独一无二地穿透并熄灭那道保护之焰。"}},faq={{q="装满水的蚀刻瓶里装着什么？",a="它包含直接取自灰谷弗伦河附近的一座暗夜精灵月亮井的圣水。水被盛放在从林中树居附近的树妖那里取得的华丽玻璃瓶中。",al={"瓶中装的是什么水","蚀刻瓶里装的是什么"}},{q="牛头人为什么需要月亮井水？",a="劳恩·峭壁行者需要这种圣水来突破千针石林的加拉克半人马所维持的不灭保护之焰。由于树妖和半人马通过塞纳留斯拥有共同的血统，月亮井水可以用来驱散守护其遗物的古老结界。",al={"为什么要用月亮井水","劳恩为什么需要月亮井水"}},{q="空瓶来自哪里？",a="这种容器由欢笑姐妹携带，她们是游荡在灰谷中部林中树居周围树林的树妖。",al={"哪里可以找到蚀刻瓶","如何获得空瓶"}},{q="你要把装满水的蚀刻瓶交给谁？",a="在收集好圣水后，首先要将其带到雷霆崖High Rise的赞金·石蹄那里，他会指引你将其交给千针石林乱风岗的劳恩·峭壁行者。",al={"谁会接收这个瓶子","瓶子交还"}}},fp="19,303,31.568.0,24.563.1,39.197.0,38.279.1,37.126.0,46.198.0"}
P.entries["item:filled-jade-phial"] = {n="装满水的翡翠瓶",s="装满水的翡翠瓶中盛放着从星风村附近的月井中汲取的神圣之水。它被带回多兰纳尔，作为补充首都中心水域的持续仪式的一部分，同时年轻的暗夜精灵们可以在此学习他们族人的历史。",h="装满水的翡翠瓶中盛放着从星风村附近的月井中汲取的神圣之水。它被带回多兰纳尔，作为补充首都中心水域的持续仪式的一部分，同时年轻的暗夜精灵们可以在此学习他们族人的历史。",kw={"科瑞萨斯·月怒","crown of the earth","多兰纳尔","装满水的翡翠瓶","翡翠瓶","月井","星风村","泰达希尔"},ang={["class:Druid"]="照料月井使德鲁伊直接与维持达纳苏斯的复苏魔法，以及塞纳里奥议会为培育年轻的世界之树所做的持续努力联系在一起。",["race:NightElf"]="取水加深了年轻卡多雷对泰达希尔的神圣职责感，同时也传授了关于海加尔山之后失去永恒生命的关键历史。"},sec={{t="星风之水",b="达纳苏斯的德鲁伊依靠从泰达希尔各处汲取的神圣月井之水来补充他们的中心水井。特制的容器，例如科瑞萨斯·月怒在多兰纳尔委托年轻冒险者携带的翡翠瓶，经过协调可以安全地盛放这些纯净的水。通过向东前往星风村外的月井，初学者们在证明他们对维护世界之树的奉献精神的同时，收集了这些重要的水源。"},{t="历史课",b="将装满水的翡翠瓶带回多兰纳尔不仅仅是一个简单的差事；每一个补充好的容器都让卡多雷的口述历史增加了一个篇章。在收到装满水的瓶子后，科瑞萨斯·月怒会讲述第三次战争后那段绝望的时期——诺达希尔的燃烧、暗夜精灵永恒之生命的失去、背叛者的释放，以及珊多玛法里奥·怒风的突然失踪。"}},faq={{q="在哪里可以装满翡翠瓶？",a="翡翠瓶是通过与位于泰达希尔上多兰纳尔以东，星风村外的一口月井的神圣水域互动来装满的。",al={"我在哪里装满翡翠瓶","如何获得装满水的翡翠瓶","星风月井位置"}},{q="谁需要装满水的翡翠瓶？",a="驻扎在多兰纳尔定居点的暗夜精灵长者科瑞萨斯·月怒，指示旅行者们去取水，作为“Crown of the Earth”仪式任务的一部分。",al={"谁想要装满水的翡翠瓶","科瑞萨斯·月怒任务物品"}},{q="为什么要用这样的瓶子收集月井之水？",a="居住在达纳苏斯的德鲁伊必须定期补充他们的主要月井。他们使用像翡翠瓶这样特制的容器，安全地从泰达希尔偏远的月井中运输纯净的水。",al={"为什么要收集月井水","翡翠瓶有什么用"}},{q="上交此物品时，科瑞萨斯会分享什么历史？",a="在收到装满水的瓶子后，科瑞萨斯·月怒讲述了海加尔山之战后的黑暗余波，反思了暗夜精灵永恒之生命的失去、伊利丹·怒风的释放，以及珊多玛法里奥·怒风无法解释的失踪。",al={"科瑞萨斯告诉你什么","crown of the earth背景故事"}}},fx={["10c296e8"]={q="装满水的翡翠瓶是什么？",a="装满水的翡翠瓶是一只特制的翡翠容器，里面装着从星风村附近月亮井中直接汲取的圣水。这种圣水蕴含月之能量与自然的恩泽，对暗夜精灵维系泰达希尔的生命、举行精神仪式至关重要。",al={"装满水的翡翠瓶是什么","装满水的翡翠瓶的背景","装满水的翡翠瓶"}}},fp="17,256,20.463.0,19.412.0,31.151.0,35.166.0,54.214.0,55.258.0"}
P.entries["item:filled-pure-sample-jar"] = {n="纯净的样本",s="纯净的样本中装有从偏远荒野收集的、未受腐蚀的原始软泥怪样本。它是铁炉堡的侏儒学者拉里斯·空轮研究环境腐蚀如何改变生物物质的关键基准数据。",h="纯净的样本中装有从偏远荒野收集的、未受腐蚀的原始软泥怪样本。它是铁炉堡的侏儒学者拉里斯·空轮研究环境腐蚀如何改变生物物质的关键基准数据。",kw={"纯净的样本","粘稠软泥怪","铁炉堡","拉里斯·空轮","软泥怪","粘液","安戈洛环形山"},ang={["faction:Alliance"]="前往安戈洛环形山等极端地区的联盟探险家将至关重要的自然历史数据带回给驻扎在铁炉堡的学者们。",["race:Gnome"]="侏儒学者通过严谨的实证视角审视野外生物学；将受污染的费伍德森林软泥怪与纯净的安戈洛样本进行对比，正是标准学术方法的体现。"},sec={{t="寻找未受腐蚀的粘液",b="在研究艾泽拉斯各地的软泥怪时，侏儒研究员拉里斯·空轮发现了一种令人不安的现象：这些无定形的生物会吸收并反映其栖息地的魔法和环境腐蚀。在记录了费伍德森林中被污染的软泥怪后，拉里斯确定，要解读这种腐烂的本质，需要一个对照组。纯净的样本中装有从原始、未受污染的荒野（例如安戈洛环形山的原始生态系统）中采集的软泥怪，这为学者们提供了一个未受改变的样本，可以与那些患病和被腐蚀的菌株进行比较。"},{t="原始生态",b="由于软泥怪是极具可塑性的生物，真正的“纯净”样本无法在靠近现代文明、恶魔枯萎病或死灵法术残留的地方收集。栖息在安戈洛环形山未受驯化的盆地中的粘稠软泥怪相对隔绝于外界腐蚀，这使它们成为铁炉堡探求知识的人们理想的科学标准。"}},faq={{q="谁需要这些纯净的样本？",a="驻扎在铁炉堡的侏儒研究员拉里斯·空轮需要这些纯净的样本，以继续他对艾泽拉斯软泥怪种群的深入研究。",al={"拉里斯·空轮任务","谁需要纯净的样本","谁想要这些样本"}},{q="为什么拉里斯需要纯净的软泥怪而不是被污染的软泥怪？",a="拉里斯意识到，粘液会迅速适应并吸收其周围环境的特性，例如费伍德森林中的恶魔腐烂。为了了解这种腐蚀的程度和机制，他需要未受腐蚀的基准样本进行科学比较。",al={"为什么要纯净的软泥怪","为什么要纯净的样本","粘液研究目的"}},{q="在哪里可以收集到纯净的软泥怪样本？",a="纯净的样本是从栖息在安戈洛环形山原始荒野中的粘稠软泥怪身上收集的，那里的动植物群与外界的枯萎病隔绝。",al={"去哪里找纯净的软泥怪","纯净的样本位置","在哪里装满纯净的样本"}},{q="样本送到铁炉堡后会发生什么？",a="拉里斯利用这些样本进行关于适应性和环境复原力的实验室测试，并奖励那些冒险进入危险荒野取回样本的冒险者。",al={"拉里斯的任务奖励","拉里斯用它们做什么"}}},fx={["630b5cc1"]={q="纯净的样本是什么？",a="这是一只密封的玻璃容器，里面装着未受污染的软泥怪样本。与受到恶魔能量或疫病腐化的软泥怪不同，其中的物质代表着未受污染的软泥怪原始形态，经过妥善保存，可供学术研究。",al={"纯净的样本是什么","纯净的样本是什么意思","纯净的样本"}},e9b3a5fa={q="纯净的样本来自哪里？",a="拉里斯·空轮在铁炉堡制作并提供这些空容器。你要亲自在野外收集样本，将黏稠的残留物装入容器。安戈洛环形山等原始自然环境中，有未受污染的软泥怪繁衍生息。",al={"纯净的样本的来源","纯净样本来自哪里","谁制作了纯净的样本罐"}}},fp="22,263,30.573.0,18.354.0,29.145.0,54.263.0,41.172.0,57.157.0"}
P.entries["item:filled-red-waterskin"] = {n="装满水的红色水囊",s="装满水的红色水囊里装着从塔伦米尔村水井中汲取的纯净泉水。在被遗忘者占据的腐朽废墟中收集这些纯净之水，是年轻萨满寻求与水之灵沟通的一项至关重要的试炼。",h="装满水的红色水囊里装着从塔伦米尔村水井中汲取的纯净泉水。在被遗忘者占据的腐朽废墟中收集这些纯净之水，是年轻萨满寻求与水之灵沟通的一项至关重要的试炼。",kw={"布莱恩","call of water","空的红色水囊","装满水的红色水囊","萨普塔","萨满","塔伦米尔"},ang={["class:Shaman"]="携带这瓶水是对萨满能力的考验，即在世界上最腐朽、最悲伤的角落里，依然能够找到并尊重赋予生命的力量平衡。",["faction:Horde"]="拜访塔伦米尔将年轻的卡利姆多勇士带入了被遗忘者在东部王国对抗联盟势力的斗争核心。"},sec={{t="腐朽之地的一座灯塔",b="当隐士布莱恩在贫瘠之地训练萨满学习水之道时，会派遣学徒前往希尔斯布莱德丘陵的塔伦米尔进行漫长的旅途。在腐朽与死亡之中，城镇中央的水井却奇迹般地涌出清澈、未受污染的泉水。布莱恩认为这片不洁之地的圣洁遗迹象征着不屈的精神——她将这眼未受污染的泉水与大酋长萨尔在深重苦难中依然坚定不移的意志相提并论。采集这份样本证明了学徒无论身处何种恶劣环境，都对水的纯洁怀有敬畏之心。"}},faq={{q="装满水的红色水囊里有什么？",a="它装有直接从塔伦米尔中心公共水井中汲取的纯净、未受污染的泉水。",al={"里面是什么水","塔伦米尔的水","红色水囊的内容物"}},{q="为什么布莱恩想要塔伦米尔的水？",a="布莱恩认为该镇清新的泉水是幸存于被遗忘者腐朽之中的纯净奇迹遗迹。她需要这个神圣的样本作为酿造萨满水之试炼所需萨普塔的原料。",al={"为什么要去塔伦米尔","布莱恩为什么需要这个","红色水囊的用途"}},{q="在亡灵城镇中，水井是如何保持清洁的？",a="没人知道；这眼泉水似乎没有受到周围瘟疫的影响。布莱恩指出，居住在塔伦米尔的被遗忘者可能根本没有意识到或重视这处神圣遗迹的纯洁性。",al={"为什么水井没有被污染","塔伦米尔的水井有毒吗","塔伦米尔的神圣水井"}},{q="萨尔与这个任务有什么关系？",a="布莱恩将这眼幸存于荒废城镇中的清泉比作萨尔，萨尔在经历了巨大的苦难和囚禁后，依然保持强大且纯粹，并在黑暗时期指引着兽人人民。",al={"萨尔的类比","为什么要提到萨尔"}}},fx={c913c28c={q="装满水的红色水囊来自哪里？",a="你需要带着Brine在贫瘠之地交给你的空的红色水囊，一路前往希尔斯布莱德丘陵，从塔伦米尔村的水井中汲取纯净的水。Brine记得这口井是一处令人惊叹的淡水泉眼，竟然在被遗忘者的聚居地中顽强留存。",al={"装满水的红色水囊的来源","在哪里获得装满水的红色水囊","谁制作了装满水的红色水囊"}}},fp="20,255,26.577.0,40.108.0,43.206.0,47.212.0,37.191.0"}
P.entries["item:filled-tainted-ooze-jar"] = {n="被污染的软泥怪样本",s="被污染的软泥怪样本内含粘稠、受污染的软泥，这是直接从漫游在费伍德森林腐化丛林中的软泥怪残骸中采集而来的。这些样本被存放在特殊的容器中并运往铁炉堡，以支持关于艾泽拉斯生命起源的激进理论。",h="被污染的软泥怪样本内含粘稠、受污染的软泥，这是直接从漫游在费伍德森林腐化丛林中的软泥怪残骸中采集而来的。这些样本被存放在特殊的容器中并运往铁炉堡，以支持关于艾泽拉斯生命起源的激进理论。",kw={"探险者协会","费伍德森林","铁炉堡","拉里斯·空轮","皇家药剂师学会","软泥","被污染的软泥怪"},ang={["faction:Alliance"]="联盟侦察兵密切监视着被遗忘者的皇家药剂师学会；了解幽暗城为何要在各个大陆采集软泥是情报工作的重中之重。",["race:Gnome"]="对于居住在铁炉堡的侏儒难民来说，为探险者协会做出开创性的科学贡献对于证明他们的价值并报答诺莫瑞根悲剧后矮人们的款待至关重要。"},sec={{t="腐化之森的淤泥",b="漫游在卡利姆多北部的被污染的软泥怪带有费伍德森林深处残留的腐蚀。收集它们需要使用侏儒研究员提供的容器进行仔细密封。虽然大多数旅行者会完全避开这些有害的生物，但采集这些样本能为远离荒芜森林的自然哲学和生物学研究提供稀有的素材。"},{t="空轮的宏大理论",b="这些样本是受拉里斯·空轮委托采集的，他是一位在铁炉堡探险者大厅工作的雄心勃勃的侏儒学者。空轮对软泥无处不在的特性着迷，并注意到被遗忘者的皇家药剂师学会也一直在积极关注它们。他不顾主流学术界的怀疑，提出了一种理论：软泥和软泥怪可能是与艾泽拉斯本身创造有关的原始分泌物。他在诺莫瑞根悲剧性沦陷后试图通过获得这些样本，来证明自己在矮人学者中的地位。"}},faq={{q="被污染的软泥怪样本里装的是什么？",a="它装有一个从费伍德森林原生的被击败的被污染的软泥怪残骸中采集到的新鲜样本，并被密封在侏儒采集瓶中。",al={"瓶子里装的是什么","被污染的软泥怪样本内容物","什么是被污染的软泥怪"}},{q="谁需要这些软泥样本？",a="在铁炉堡探险者大厅与探险者协会共事的侏儒研究员拉里斯·空轮，请求获取这些样本以推进他的自然历史研究。",al={"谁需要软泥怪样本","拉里斯·空轮任务","谁想要被污染的软泥怪样本"}},{q="为什么拉里斯·空轮要研究软泥怪？",a="空轮观察到皇家药剂师学会也在收集软泥样本，因此下定决心要抢先揭开它们的本质。他持有一种非传统的理论，认为软泥怪是与艾泽拉斯创造有关的原始分泌物，他希望以此巩固自己在铁炉堡的科学声誉。",al={"为什么要研究软泥","空轮的软泥理论","为什么侏儒想要软泥怪"}},{q="这些样本是在哪里收集的？",a="它们是在费伍德森林通过击败被污染的软泥怪，并对它们的残骸使用空的采集瓶来收集的。",al={"去哪里找被污染的软泥怪","被污染的软泥怪样本位置","我在哪里填充瓶子"}}},fx={["297c9c04"]={q="被污染的软泥怪样本来自哪里？由谁制作？",a="这只罐子由铁炉堡的侏儒研究员拉里斯·空轮提供。他制作特制的空玻璃容器，用于安全收集不稳定的样本。冒险者在费伍德森林腐化的树林中杀死一只被污染的软泥怪，再用罐子刮取它的胶状残骸，这只罐子才会装满。",al={"被污染的软泥怪样本的来源","谁制作了被污染的软泥怪样本罐","被污染的软泥怪样本罐来自哪里"}}},fp="23,292,27.363.0,25.565.0,41.145.0,29.171.0,39.297.0,34.109.0"}
P.entries["item:filled-tourmaline-phial"] = {n="装满水的红玉瓶",s="装满水的红玉瓶盛装着取自泰达希尔南部阿里斯瑞恩之池边缘月井的魔法泉水。受科瑞萨斯·月怒所托，这些泉水被用于监测这棵正在生长中的世界之树的健康与平衡。",h="装满水的红玉瓶盛装着取自泰达希尔南部阿里斯瑞恩之池边缘月井的魔法泉水。受科瑞萨斯·月怒所托，这些泉水被用于监测这棵正在生长中的世界之树的健康与平衡。",kw={"科瑞萨斯·月怒","crown of the earth","装满水的红玉瓶","棘木熊怪","月井","阿里斯瑞恩之池","泰达希尔","红玉瓶"},ang={["class:Druid"]="对于德鲁伊来说，携带此瓶直接触及了大德鲁伊范达尔·鹿盔那充满争议的遗产，他是在珊多玛法里奥·怒风莫名失踪期间坚持种植泰达希尔的人。",["race:NightElf"]="月井之水是卡多雷重要的精神生命线，因此周围棘木树丛的腐化对他们的新家园来说是一个令人深感不安的凶兆。"},sec={{t="阿里斯瑞恩之水",b="红玉瓶是专门用来从达纳苏斯道路东南方、阿里斯瑞恩之池岸边的月井中汲取泉水的。由于棘木熊怪的突然暴动，从这座圣坛采集泉水变得危机四伏，这些曾经的和平邻居如今迅速堕落为狂暴的疯子。科瑞萨斯·月怒委托旅人们勇闯充满敌意的树丛去获取这些泉水，旨在诊断这片土地上日益加深的腐蚀。"},{t="泰达希尔之根",b="将药瓶带回多兰纳尔后，科瑞萨斯·月怒开始反思上方枝叶的起源。在珊多玛法里奥·怒风失踪后，大德鲁伊范达尔·鹿盔集结了黑海岸彼岸的塞纳里奥议会，种下了泰达希尔，希望能借此重获失去的永生。这只宝石镶嵌的药瓶中所携带的泉水，反映了那项神圣实验的现状——这一志向如今已被蔓延至野兽和熊怪身上的不明疾病所玷污。"}},faq={{q="装满水的红玉瓶有什么用？",a="这是一个魔法容器，里面装着多兰纳尔的科瑞萨斯·月怒所要求的月井水。他从泰达希尔各处的月井中收集泉水，以研究腐蚀的蔓延情况，并向新到达的守卫者们讲述世界之树的历史。",al={"装满水的红玉瓶用途","红玉瓶目的","为什么要装满药瓶"}},{q="红玉瓶所用的月井在哪里？",a="月井位于达纳苏斯正门东南方，坐落在泰达希尔西南部阿里斯瑞恩之池的岸边。该地区目前正受到狂暴的棘木熊怪的激烈争夺。",al={"去哪里装满红玉瓶","阿里斯瑞恩之池月井","阿里斯瑞恩水井位置"}},{q="为什么月井附近的熊怪会发动攻击？",a="棘木熊怪曾是与暗夜精灵共同生活的和平熊人，如今却沦为了肆虐泰达希尔的腐蚀的牺牲品。它们突然陷入毫无理智的暴行，是这棵年轻的世界之树所遭受的众多症状之一。",al={"棘木熊怪为何疯狂","阿里斯瑞恩熊怪敌意","狂暴的棘木熊怪"}},{q="科瑞萨斯·月怒是谁？",a="科瑞萨斯·月怒是一位驻扎在多兰纳尔的暗夜精灵学者和看护者。他指引年轻的冒险者们完成被称为Crown of the Earth的仪式，教导他们关于暗夜精灵的历史、泰达希尔的种植以及玛法里奥·怒风的失踪。",al={"科瑞萨斯职责","多兰纳尔的科瑞萨斯"}}},fx={["360c6167"]={q="装满水的红玉瓶是什么？",a="这是一只空的红玉瓶，里面装满了泰达希尔阿里斯瑞恩之池附近月亮井中神圣而发光的泉水。暗夜精灵德鲁伊使用不同矿石制成的瓶子，在岛上各处采集纯净的月亮井水，将每份样本分别保存，用于神圣仪式和净化土地。",al={"装满水的红玉瓶是什么","装满水的红玉瓶物品"}},b07aae52={q="装满水的红玉瓶来自哪里？",a="瓶子由多兰纳尔的科瑞萨斯·月怒提供。你要带着它前往达纳苏斯东南方，来到阿里斯瑞恩之池岸边的月亮井，从池中直接汲水。周围有躁动不安的Gnarlpine熊怪四处游荡。",al={"装满水的红玉瓶的来源","装满水的红玉瓶来自哪里"}},c83d83e7={q="科瑞萨斯·月怒为什么需要装满水的红玉瓶？",a="科瑞萨斯·月怒收集泰达希尔各处月亮井的泉水，以评估并守护这棵年轻世界之树的精神活力。随着腐化侵入枝干，令当地的Gnarlpine熊怪陷入疯狂，收集并检视各处的泉水有助于德鲁伊维持神圣的平衡，并弄清是什么祸害着他们的家园。",al={"科瑞萨斯为什么需要瓶子","装满水的红玉瓶的用途","为什么要收集月亮井水"}}},fp="23,279,20.507.0,23.503.1,45.246.0,55.206.0,49.247.0,26.278.0"}
P.entries["item:filled-vessel"] = {n="装满月亮井水的瓶子",s="装满月亮井水的瓶子中装有从泰达希尔各地神圣月亮井中汲取的净化之水。它由多兰纳尔的科瑞萨斯·月怒委托信使送达达纳苏斯的大德鲁伊范达尔·鹿盔手中，以辅助他研究世界之树的病症。",h="装满月亮井水的瓶子中装有从泰达希尔各地神圣月亮井中汲取的净化之水。它由多兰纳尔的科瑞萨斯·月怒委托信使送达达纳苏斯的大德鲁伊范达尔·鹿盔手中，以辅助他研究世界之树的病症。",kw={"塞纳里奥区","科瑞萨斯·月怒","crown of the earth","达纳苏斯","范达尔·鹿盔","装满月亮井水的瓶子","月亮井水","泰达希尔"},ang={["class:Druid"]="对于塞纳里奥的新手来说，运送这个瓶子标志着他们第一次正式执行前往大德鲁伊范达尔·鹿盔处的任务，让他们亲眼目睹了泰达希尔所面临的生态脆弱性。",["race:NightElf"]="瓶中的月亮井水代表了卡多雷新家园神圣的生命线，将艾露恩的魔法与这棵未经祝福的世界之树不确定的生长融合在了一起。"},sec={{t="神圣之水的汇集",b="泰达希尔是在没有巨龙守护者阿莱克丝塔萨和诺兹多姆祝福的情况下种植的，这使其巨大的枝干容易受到意想不到的腐蚀、奇异野兽和疯狂熊怪部落的侵害。为了监测和净化这些繁茂的枝干，暗夜精灵侍僧们被派往各地，从分布在枝干上的月亮井收集水样。科瑞萨斯·月怒将这些收集来的小瓶汇集成一个装满月亮井水的瓶子，并将其转送至首都。这些混合水样作为泰达希尔生命力的重要样本，交由大德鲁伊范达尔·鹿盔研究。他正在塞纳里奥区不知疲倦地工作，试图为这棵巨树普遍存在的缺陷寻找补救方法。"}},faq={{q="装满月亮井水的瓶子里有什么？",a="瓶子中装有从散布在泰达希尔各处的几口月亮井中收集的水，由多兰纳尔的科瑞萨斯·月怒汇集到一个容器中。",al={"瓶中物品","这是什么水","瓶子里有什么"}},{q="谁需要装满月亮井水的瓶子？",a="装满月亮井水的瓶子被送往大德鲁伊范达尔·鹿盔手中，他居住在达纳苏斯塞纳里奥区的顶层。",al={"我应该把装满月亮井水的瓶子交给谁","瓶子送到哪里","装满月亮井水的瓶子交接"}},{q="为什么范达尔·鹿盔需要这些水样？",a="泰达希尔缺乏巨龙守护者的传统祝福，导致奇异的腐蚀、具有攻击性的野生动物和疯狂的熊怪侵扰着它的枝干。鹿盔研究这些混合水样是为了诊断这棵树的缺陷，并为其病症寻求补救措施。",al={"为什么鹿盔需要水","鹿盔的月亮井水用途","为什么要收集月亮井水"}},{q="谁准备了这个瓶子？",a="驻扎在多兰纳尔的暗夜精灵科瑞萨斯·月怒，他将年轻冒险者收集来的小瓶汇入瓶中，然后将其送往达纳苏斯。",al={"谁制作了装满月亮井水的瓶子","谁提供了装满月亮井水的瓶子","科瑞萨斯与装满月亮井水的瓶子"}}},fp="13,265,29.675.0,33.159.0,28.121.0,51.256.0,24.155.0"}
P.entries["item:final-clue-to-sanders-treasure"] = {n="Final Clue to Sanders' Treasure",s="Final Clue to Sanders' Treasure是一张被威士忌浸染的纸条，塞在西部荒野海岸的一个旧罐子里。它提供了已故海盗Captain Sanders留下的最后指引，指引寻宝者直接进入公海，寻找他埋藏的战利品。",h="Final Clue to Sanders' Treasure是一张被威士忌浸染的纸条，塞在西部荒野海岸的一个旧罐子里。它提供了已故海盗Captain...",kw={"captain sanders","宝箱","线索","海盗","宝藏","西部荒野","威士忌罐"},ang={["class:Rogue"]="跟随一个死掉海盗的威士忌浸泡过的谜题进入公海是典型的恶棍行径，证明了西部荒野的海岸除了迪菲亚兄弟会的口袋，还有其他值得搜刮的东西。"},sec={{t="水手的临别赠言",b="这张模糊的羊皮纸散发着浓烈的酒味，标志着Captain Sanders在西部荒野留下的复杂线索终结。这位已故的海盗以在海岸线留下神秘指引而闻名，他将最后一张纸条藏在海岸边一个旧威士忌罐的深处。指示简单粗暴却直截了当：从瓶子的位置向正西方进入海浪，在冰冷的海浪中前进，直到到达一块孤独的近海岩石，那里放着他铁箍的宝箱。"}},faq={{q="最后一条线索写了什么？",a="尽管墨迹模糊且散发着浓烈的威士忌气味，纸条还是指示读者从威士忌罐所在位置面朝西方，径直走进海岸水域，向西游入大海，直到到达一个小小的近海岛屿，宝箱就藏在那里。",al={"线索文本","线索上写了什么","sanders的指引"}},{q="这条线索是在哪里发现的？",a="这条线索被塞在一个旧威士忌罐里，位于西部荒野的西海岸附近，是Captain Sanders散落在各处的线索链条中的第三步。",al={"我在哪里能找到最后一条线索","旧罐子位置","线索位置"}},{q="Captain Sanders是谁？",a="Captain Sanders是一位船长兼海盗，他的物品和藏宝图被冲上了西部荒野的海岸线。虽然Sanders本人已经去世，但他留下了散布在乡村各处的一系列隐藏纸条和标记，指引人们找到他的海盗宝藏。",al={"captain sanders是谁","sanders海盗传说","谁藏了宝藏"}},{q="这条线索最终通向哪里？",a="纸条指引你从西部荒野海岸向西游向大海中一座孤独的岛屿，Captain Sanders生锈的宝箱和埋藏的财宝就放在那里。",al={"宝箱在哪里","sanders的岛屿","岛屿位置"}}},fp="31,145,24.331.0,29.124.0,26.119.0,24.195.0,37.107.0"}
P.entries["item:fine-crab-chunks"] = {n="优质蟹肉",s="优质蟹肉是从游荡在黑海岸沙滩上的海岸甲壳类生物身上采集的上等肉块。由于其极佳的烹饪多用性而备受推崇，当地的海岸居民和饥肠辘辘的渔夫都竞相搜寻它们，以准备各种各样的海鲜佳肴。",h="优质蟹肉是从游荡在黑海岸沙滩上的海岸甲壳类生物身上采集的上等肉块。由于其极佳的烹饪多用性而备受推崇，当地的海岸居民和饥肠辘辘的渔夫都竞相搜寻它们，以准备各种各样的海鲜佳肴。",kw={"奥伯丁","螃蟹","黑海岸","硬壳潮汐爬行者","优质蟹肉","海洋的果实","古博·布拉普","礁石爬行者"},ang={["faction:Alliance"]="为奥伯丁的码头居民提供补给，有助于维持这座处于黑海岸阴郁险境中的脆弱联盟前哨站。",["profession:Cooking"]="任何有抱负的海岸厨师都会欣赏古博·布拉普对螃蟹的百科全书般的热情，这种热情涵盖了汤、沙拉、胡椒擦拭烤法以及铁炉堡风味蟹肉惊喜等地方美味。"},sec={{t="海洋的果实",b="多雾且崎岖的黑海岸布满了爬行的甲壳类生物，尤其是礁石爬行者和硬壳潮汐爬行者。虽然许多旅行者将这些披甲的海岸潜行者视为害虫或水边的攻击性威胁，但有进取心的美食家却认为它们的肉是海岸上最珍贵的馈赠。从这些生物身上收获的上等肉块鲜嫩多汁，几乎适用于任何可以想象的烹饪方法，从煮、烤到油炸和炖煮，应有尽有。"}},faq={{q="哪些生物会掉落优质蟹肉？",a="它们是从游荡在黑海岸岩石沙滩和潮汐浅滩上的礁石爬行者和硬壳潮汐爬行者身上收获的。",al={"优质蟹肉在哪里掉落","哪些螃蟹掉落蟹肉","蟹肉来源"}},{q="黑海岸有谁需要优质蟹肉？",a="古博·布拉普，一位驻扎在奥伯丁码头的狂热渔夫，一直在搜寻这些上等肉块。作为一名海鲜狂热爱好者，他视这些肉块为珍宝，用于制作各种精致的家常蟹肉料理。",al={"谁需要优质蟹肉","谁提交蟹肉","古博·布拉普 螃蟹"}},{q="你能把这些做成真正的饭菜吗？",a="虽然这些特定的生肉块主要是作为收集给古博·布拉普的补给品，而不是直接的烹饪配方材料，但当地的烹饪传统认为蟹肉用途极其广泛——适合烘焙、烧烤、水煮、煎炸，以及拌入沙拉或炖菜中。",al={"你能烹饪优质蟹肉吗","优质蟹肉能做什么","螃蟹食谱"}}},fx={a1097ca6={q="什么是优质蟹肉？",a="优质蟹肉是从黑海岸雾气笼罩的海岸边那些健壮螃蟹身上剔取的上等肉块。当地的美食爱好者十分珍视其鲜嫩多汁、用途广泛，认为它是真正的海中珍品，几乎适合任何烹饪方式。",al={"什么是优质蟹肉","优质蟹肉的背景"}},["09afcf23"]={q="优质蟹肉从哪里来？",a="这些上等肉块直接取自黑海岸沿岸活动的野生甲壳类生物，尤其是礁行蟹和硬壳潮行蟹。它们并非由凡人亲手制作，而是从适应寒冷浪涛的生物身上新鲜剔取的。",al={"优质蟹肉从哪里来","优质蟹肉的来源","优质蟹肉的来历"}},["1943045a"]={q="古博·布拉普为什么想要优质蟹肉？",a="古博·布拉普是一位驻守在奥伯丁码头的古怪渔夫，他对蟹肉着迷不已。他守着自己的鱼竿无法脱身，只能依靠旅行者收集新鲜蟹肉，好让他制作无穷无尽的蟹肉菜肴，从烘烤和炙烤的美食，到蟹肉沙拉和炖菜。",al={"古博为什么要蟹肉","谁想要优质蟹肉","为什么收集优质蟹肉"}}},fp="16,281,16.516.0,38.136.0,40.202.0,40.296.0"}
P.entries["item:fine-moonstalker-pelt"] = {n="优质月夜猛虎毛皮",s="优质月夜猛虎毛皮是从黑海岸南部游荡的最成熟的掠食性月夜猛虎身上剥下的厚实、原始的毛皮。奥伯丁的特伦希斯利用这些珍贵的毛皮编织出一件附魔斗篷，让搜寻者能够不被发觉地潜过森林中充满敌意的野兽。",h="优质月夜猛虎毛皮是从黑海岸南部游荡的最成熟的掠食性月夜猛虎身上剥下的厚实、原始的毛皮。奥伯丁的特伦希斯利用这些珍贵的毛皮编织出一件附魔斗篷，让搜寻者能够不被发觉地潜过森林中充满敌意的野兽。",kw={"奥伯丁","黑海岸","优质月夜猛虎毛皮","雌兽","月夜猛虎","雄兽","特伦希斯","沃科尔","急弯河"},ang={["class:Hunter"]="在急弯河附近追踪雄兽和雌兽，是对猎人在卡利姆多海岸面对一些最凶猛的掠食者时追踪技能的考验。",["race:NightElf"]="暗夜精灵尊重月夜猛虎神圣的凶猛，只有在为了援助像沃科尔这样陷入困境的同胞而万不得已时，才会取走它们的毛皮。"},sec={{t="族群领袖的毛皮",b="虽然普通的月夜猛虎徘徊在黑海岸雾气缭绕的森林中，但只有较年长的月夜猛虎雄兽和雌兽才拥有足够浓密且健康的皮毛，可以产出优质毛皮。这些强大的野猫在急弯河沿岸以及向南通往灰谷边界的地方建立领地，它们在那里极具耐心地进行狩猎。"},{t="欺诈斗篷",b="收集这些毛皮并非仅仅是为了战利品。特伦希斯需要五张完整的毛皮来制作一件附魔服装，供寻找失踪暗夜精灵沃科尔的旅行者使用。当用自然魔法编织和束缚在一起时，这些毛皮会形成一件伪装斗篷，将穿着者笼罩在幻象中，只要他们不采取攻击行动，就能在黑海岸的野生动物面前掩盖自身的存在。"}},faq={{q="什么生物会掉落优质月夜猛虎毛皮？",a="只有月夜猛虎族群中成熟的领袖才会掉落这些毛皮——具体来说是月夜猛虎雄兽和月夜猛虎雌兽。年轻或普通的月夜猛虎皮毛质量不够。",al={"什么掉落优质月夜猛虎毛皮","在哪里获得月夜猛虎毛皮","哪些猫科动物有毛皮"}},{q="在哪里可以找到成熟的月夜猛虎？",a="这些强大的野猫栖息在黑海岸南部，特别是急弯河河岸附近，以及沿森林道路向南前往灰谷的方向。",al={"雄兽和雌兽在哪里","月夜猛虎雄兽位置","月夜猛虎雌兽位置"}},{q="特伦希斯为什么需要这些毛皮？",a="特伦希斯使用五张毛皮来制作一件附魔斗篷。这件斗篷注入了魔法，旨在让救援者在寻找失踪的暗夜精灵沃科尔时，躲避掠食性野兽的视线。",al={"毛皮有什么用途","为什么要收集月夜猛虎毛皮","特伦希斯的毛皮任务"}},{q="完成后的斗篷能让你完全隐形吗？",a="斗篷投射出一种微妙的自然幻象来震慑野兽，但它很脆弱。特伦希斯警告说，除了与他人交谈之外，做任何其他事情都会破坏附魔效果并消除伪装。",al={"斗篷如何运作","斗篷幻象限制","斗篷打破潜行"}}},fx={["399f6830"]={q="什么是优质月夜猛虎毛皮？",a="优质月夜猛虎毛皮是从黑海岸荒野中成年月夜猛虎公兽和母兽身上剥取的上等皮毛。这些强悍的夜刃豹拥有厚实柔韧的皮毛，能够留存精妙的自然魔力，因此它们的毛皮远比年轻个体的粗糙皮毛珍贵，也更耐用。",al={"优质月夜猛虎毛皮","什么是月夜猛虎毛皮","优质毛皮"}},e53e751f={q="优质月夜猛虎毛皮从哪里来？",a="这些毛皮自然产自黑海岸海岸和森林中活动的成年月夜猛虎，尤其是急弯河附近以及更南边、靠近灰谷边界的区域。只有完全成年的月夜猛虎公兽和母兽，才能提供足够厚实、完好的皮毛，称得上优质毛皮。",al={"哪里能获得优质月夜猛虎毛皮","月夜猛虎毛皮来源","谁掉落优质月夜猛虎毛皮"}}},fp="21,275,25.348.0,20.387.1,45.191.0,43.172.0,36.195.0,54.197.0"}
P.entries["item:fire-tar"] = {n="火焰焦油",s="火焰焦油是一种不稳定的物质，由散布在东贫瘠之地的刺鬃猪人施法者收集。对于部落萨满来说，它是酿造火焰灵契的关键仪式组件，能使萨满与火焰元素进行灵魂沟通。",h="火焰焦油是一种不稳定的物质，由散布在东贫瘠之地的刺鬃猪人施法者收集。对于部落萨满来说，它是酿造火焰灵契的关键仪式组件，能使萨满与火焰元素进行灵魂沟通。",kw={"call of fire","火焰灵契","火焰焦油","猪人","刺鬃","萨满图腾","泰尔夫·祖拉姆","贫瘠之地"},ang={["class:Shaman"]="采集火焰焦油是重要的成年礼，它教会你如何在广阔的世界中寻找元素共鸣，从而酿造火焰灵契并获得你的火焰图腾。",["faction:Horde"]="获取火焰焦油需要年轻的部落冒险者离开杜隆塔尔，穿过怒水河进入贫瘠之地，去面对好战的刺鬃部族。"},sec={{t="刺鬃的药剂",b="火焰焦油几乎只由刺鬃猪人施法者携带，包括他们的地卜师、秘法师和荆棘编织者，这是一种与火焰高度契合的炼金物质。虽然贫瘠之地的刺鬃部族利用它进行残酷的魔法和仪式，但萨满导师们认为这是一种至关重要的世俗试剂，能够弥合凡人的感官与原始元素之怒之间的鸿沟。"},{t="火焰图腾之路",b="当年轻的兽人和巨魔萨满被派往位于杜隆塔尔岩壁高处的泰尔夫·祖拉姆处时，他们的任务是铸造自己的火焰图腾。泰尔夫需要两种与热量和火焰有关的关键元素来酿造火焰灵契：从火刃氏族邪教徒那里偷来的试剂袋，以及从刺鬃猪人那里采集的火焰焦油。喝下酿造好的灵契，萨满就能穿透面纱，感知到在附近山峰上等待他们的火焰元素之灵。"}},faq={{q="火焰焦油有什么用？",a="火焰焦油是带给杜隆塔尔的隐士萨满泰尔夫·祖拉姆的必要仪式原料。将其与从火刃氏族那里获得的试剂混合，可以酿造成火焰灵契——这是一种能让萨满观察并与火元素沟通，从而获得火焰图腾的药剂。",al={"火焰焦油用途","火焰焦油的作用","为什么需要火焰焦油"}},{q="谁携带火焰焦油？",a="它由东贫瘠之地的刺鬃部族猪人施法者携带，例如刺鬃地卜师、秘法师、荆棘编织者和祈水者。",al={"谁掉落火焰焦油","火焰焦油怪物","在哪获得火焰焦油"}},{q="为什么萨满需要与敌对施法者相关的原料？",a="灵契需要与相应元素深度融合的物质组件。由于刺鬃施法者和火刃氏族术士都能引导强烈的热量和破坏性的火焰，他们日常使用的材料中早已浸透了唤醒萨满元素视觉所需的火焰精华。",al={"为什么要用猪人的焦油","为什么要找术士和猪人"}},{q="泰尔夫·祖拉姆在哪里酿造火焰灵契？",a="泰尔夫·祖拉姆居住在俯瞰杜隆塔尔岩壁的一处高崖上，靠近剃刀岭和贫瘠之地之间的小路。他在那里指导入门者如何平衡火焰的破坏性和创造性本质。",al={"泰尔夫·祖拉姆在哪里","提交火焰焦油"}}},fx={["1e4fc5f4"]={q="什么是火焰焦油？",a="火焰焦油是一种易挥发的元素物质，由贫瘠之地剃刀沼地野猪人中的施法者携带。它蕴含着火焰的本源精华，是元素魔法使用者珍视的刺鼻沥青状物质，天生与火焰有着密切联系。",al={"什么是火焰焦油","火焰焦油信息","描述火焰焦油"}},["006bd002"]={q="火焰焦油从哪里来？由谁制造？",a="火焰焦油是从居住在贫瘠之地东部的剃刀沼地野猪人施法者身上收集的，其中包括地卜师、神秘学者和荆织者。泰尔夫·祖拉姆让学徒带来火焰焦油，作为制作他的火焰灵契的材料。",al={"谁制造火焰焦油","火焰焦油的来历","火焰焦油从哪里来"}}},fp="8,250,29.406.0,26.454.0,26.269.0,21.157.0,61.300.0,43.207.0"}
P.entries["item:fizzle-s-claw"] = {n="费索的爪子",s="费索的爪子是地精术士费索·暗风被切下的手。它取自他在雷霆山的营地，是给剃刀岭的部落指挥官的实物证明，表明一名危险的火刃氏族密谋者已被击杀。",h="费索的爪子是地精术士费索·暗风被切下的手。它取自他在雷霆山的营地，是给剃刀岭的部落指挥官的实物证明，表明一名危险的火刃氏族密谋者已被击杀。",kw={"火刃氏族","暗风","杜隆塔尔","费索·暗风","费索的爪子","奥戈尼尔·魂痕","剃刀岭","雷霆山"},ang={["class:Warlock"]="费索·暗风利用邪能来为颠覆性的火刃氏族效力，将其黑暗天赋转向直接反抗部落。",["faction:Horde"]="向剃刀岭呈上费索的爪子，表明了清洗杜隆塔尔境内威胁这个年轻国家脆弱安全的暗影邪教的持续决心。"},sec={{t="残酷的战利品",b="奥戈尼尔·魂痕负责铲除威胁兽人故土的暗影邪教，他认定费索·暗风是在雷霆山散布腐化的煽动者。索要费索的爪子并非出于野蛮，而是出于现实需要：部落需要确凿的证据，来确认一名在火刃氏族旗号下活动的秘密术士已被消灭。"},{t="雷霆山的威胁",b="雷霆山位于剃刀岭西北方，因此费索的邪教徒存在对周边地区构成了迫在眉睫的危险。通过切下这名地精的爪子并将其带回剃刀岭，部落侦察兵证实了这名术士的仪式以及他试图为火刃氏族建立立足点的企图已被挫败。"}},faq={{q="这只爪子属于谁？",a="这只爪子属于费索·暗风，一个投靠了名为火刃氏族的暗影邪教的奸诈地精术士。",al={"费索是谁","费索·暗风","爪子的主人"}},{q="为什么奥戈尼尔·魂痕需要费索的爪子？",a="奥戈尼尔·魂痕需要费索死亡的确凿证据。火刃氏族在暗影中运作，因此呈上这名地精术士的爪子可以确认，这个针对杜隆塔尔的特定威胁已被彻底清除。",al={"为什么需要爪子","奥戈尼尔·魂痕的爪子","死亡证明"}},{q="这只爪子是在哪里发现的？",a="它取自费索·暗风，他在杜隆塔尔的剃刀岭西北部的一处峡谷中藏有营地。",al={"费索的位置","费索在哪里","雷霆山的爪子"}},{q="火刃氏族在杜隆塔尔做什么？",a="火刃氏族是一个邪恶的邪教组织，企图通过恶魔腐化、黑暗巫术和内部动乱来破坏新生的兽人故土。像费索这样的术士建立秘密营地，试图在整个地区散布混乱。",al={"杜隆塔尔的火刃氏族","为什么邪教徒在雷霆山"}}},fx={["0fb0af8e"]={q="什么是费索的爪子？",a="费索的爪子是费索·暗风被砍下的手。他是一个背叛成性的地精术士，效忠于火刃氏族。它是血腥的实体证据，证明费索已命丧黄泉；剃刀岭的奥戈尼尔·魂痕借此确认，在雷霆山兴风作浪的邪教头目已被彻底铲除。",al={"什么是费索的爪子","费索的爪子物品","费索爪子的身份"}}},fp="13,242,13.376.0,27.317.0,29.127.0,44.219.0,25.135.0,43.220.0"}
P.entries["item:flagongut-s-fossil"] = {n="弗拉冈特的化石",s="弗拉冈特的化石是我们在湿地挖掘场中发现的一具古代标本。它被交托给矮人的探险者协会保管，考古学家弗拉冈特正试图利用名为雷鲁之石的神秘遗物，来破解其中蕴藏的秘密。",h="弗拉冈特的化石是我们在湿地挖掘场中发现的一具古代标本。它被交托给矮人的探险者协会保管，考古学家弗拉冈特正试图利用名为雷鲁之石的神秘遗物，来破解其中蕴藏的秘密。",kw={"挖掘","探险者协会","弗拉冈特","化石","雷鲁","雷鲁之石","湿地","维尔加"},ang={["faction:Alliance"]="从维尔加被毁的挖掘场中保护文物，可以防止宝贵的历史被野兽破坏，或被沼泽中的敌对势力掠夺。",["race:Dwarf"]="对于矮人探险家来说，像弗拉冈特的化石这样的东西不仅仅是好奇心驱使下的收藏品；它们是探险者协会致力于发掘的、通往远古过去的实体联系。"},sec={{t="挖掘与研究",b="这具古代化石是矮人在整个卡兹莫丹考察活动中的发现，它不仅仅是石化的岩石。考古学家弗拉冈特认为它蕴含着与世界深远古代有关的遗忘力量，与海对岸黑海岸发现的文物相当。为了在区域研究期间妥善保管，这具化石被存放在湿地南部山丘的维尔加挖掘场，由勘察员维尔加看守。"},{t="解开遗物之谜",b="当弗拉冈特发现雷鲁之石时，他意识到这就是解开化石之谜所需的关键钥匙。然而，在路上遭到杂色迅猛龙的伏击导致石头丢失。为了最终解开这个标本的秘密，弗拉冈特需要冒险者们从维尔加挖掘场取回化石，并从湿地的野生动物腹中找回那块石头。"}},faq={{q="什么是弗拉冈特的化石？",a="这是一具从湿地发掘出来的古代考古标本，由矮人探险者协会负责分析，旨在揭开世界远古历史的秘密。",al={"什么是化石","弗拉冈特的化石背景故事"}},{q="化石在哪里？",a="它位于维尔加挖掘场顶部的洞穴中，坐落在湿地的南部山区，由占领了挖掘场的杂色迅猛龙守卫着。",al={"化石位置","弗拉冈特的化石在哪里","维尔加化石洞穴"}},{q="为什么弗拉冈特想要拿回它？",a="弗拉冈特相信，结合雷鲁之石，他可以破解化石中潜藏的魔法秘密，并将其性质与在卡利姆多发现的类似文物进行比较。",al={"为什么弗拉冈特想要它","弗拉冈特会用它做什么"}},{q="它与黑海岸有什么联系？",a="弗拉冈特认为这件湿地标本与勘察员雷姆塔维尔在海对岸的黑海岸发现的化石有相似之处，他相信雷鲁之石可能解开这两件遗物中的力量。",al={"黑海岸的联系","雷姆塔维尔的化石"}}},fp="18,255,20.430.0,19.371.1,27.168.0,28.170.0,36.172.0,33.197.0"}
P.entries["item:flatland-cougar-femur"] = {n="平原狮的腿骨",s="平原狮的腿骨是一种致密的腿骨，取自徘徊在莫高雷金色草丛中的掠食性平原狮。它是牛头人传统民间疗法中的关键成分，用于对抗致命的毒液感染。",h="平原狮的腿骨是一种致密的腿骨，取自徘徊在莫高雷金色草丛中的掠食性平原狮。它是牛头人传统民间疗法中的关键成分，用于对抗致命的毒液感染。",kw={"血蹄村","腿骨","平原狮","茂尔·祈雨","玛兹拉纳切","莫高雷"},ang={["class:Hunter"]="在莫高雷摇曳的灌木丛中追踪平原狮需要敏锐的目光，这也考验着年轻猎人干净利落地击倒同为掠食者的猎物的能力。",["race:Tauren"]="对于莫高雷的牛头人来说，狩猎平原狮既是一场警惕性的考验，也是传统平原疗法重要材料的来源。"},sec={{t="毒咬的疗法",b="平原狮是莫高雷最危险的土生潜行者之一，它们能完美地融入干枯的灌木丛中，直到向毫无戒心的猎物猛扑过去。虽然猎人们经常采集狮皮和狮爪用于制皮和制作战利品，但它们富含骨髓的坚硬骨骼在当地医学中也具有实用价值。当血蹄村的牛头人茂尔·祈雨被可怕的陆行鸟玛兹拉纳切咬伤中毒后，他急需平原狮的腿骨以及其他当地野兽的身体部位。通过研磨或煮沸这种骨骼来提取其强效成分，可以制成一种解毒药膏，用于从化脓的伤口中吸出高热和坏死性毒液。"}},faq={{q="平原狮的腿骨有什么用途？",a="这种腿骨被血蹄村的茂尔·祈雨用来调制一种急救药方。茂尔被臭名昭著的陆行鸟玛兹拉纳切咬伤，需要这种骨髓和骨头来调制解毒剂，以免被那只野兽剧烈的毒液毒死。",al={"平原狮的腿骨用途","这个骨头有什么用","腿骨任务"}},{q="在哪里可以获得平原狮的腿骨？",a="它从徘徊在莫高雷中部和南部平原的平原狮身上采集而来，通常在血蹄村周围的山坡和高草丛附近出没。",al={"哪里可以找到腿骨","平原狮的腿骨位置","哪些怪物掉落它"}},{q="为什么茂尔·祈雨特别需要狮子的骨头？",a="牛头人草药师和萨满经常在传统的药膏和药剂中使用掠食性动物的坚硬骨骼和骨髓。人们相信莫高雷顶级掠食者的力量和韧性提供了中和强效毒素所需的复原基础。",al={"为什么需要狮子骨头","为什么是腿骨"}},{q="茂尔·祈雨是谁？",a="茂尔·祈雨是血蹄村的一名牛头人居民。在平原上游荡时，他遭遇了玛兹拉纳切——他祖父曾经对付过的传奇陆行鸟，虽然勉强逃脱，但肩膀却受了感染，中了毒。",al={"茂尔·祈雨","谁需要这个骨头"}}},fx={cc87b9fc={q="什么是平原狮的腿骨？",a="这是一根从莫高雷平原上游荡的掠食性平原狮身上取下的结实腿骨。这类骨头质地致密、坚韧，经常被部族医者和萨满寻来，用于制作传统药膏、敷剂和疗伤药。",al={"什么是平原狮的腿骨","平原狮的腿骨物品","平原狮腿骨是什么"}},["47eeaceb"]={q="平原狮的腿骨从哪里来？",a="它直接取自平原狮——这种精瘦的掠食者原生于莫高雷草原。它不是制成的工具，也不是酿制的药剂，而是猎人在起伏的平原上追踪野兽时获得的天然战利品。",al={"平原狮的腿骨来源","哪里能获得平原狮的腿骨","谁掉落狮子的腿骨"}}},fp="21,232,28.676.0,43.246.0,44.189.0,58.283.0,23.232.0"}
P.entries["item:flatland-prowler-claw"] = {n="平原徘徊者的爪子",s="平原徘徊者的爪子取自莫高雷草原上那些危险的猫科掠食者。对于有抱负的猎人来说，收集这些爪子是一种传统的成人礼，向雷霆崖的长者们证明自己的狡黠与战斗决心。",h="平原徘徊者的爪子取自莫高雷草原上那些危险的猫科掠食者。对于有抱负的猎人来说，收集这些爪子是一种传统的成人礼，向雷霆崖的长者们证明自己的狡黠与战斗决心。",kw={"平原徘徊者","平原徘徊者的爪子","猎人高地","梅洛·石蹄","莫高雷","斯考恩·白云","猎人之道","雷霆崖"},ang={["class:Hunter"]="击败潜行的徘徊者是对猎人野外感知能力的考验，这使得这些爪子成为雷霆崖猎人高地上汇聚的射手们眼中一种赢得尊重的象征。",["race:Tauren"]="对于牛头人来说，狩猎是一项光荣的精神传统。呈献平原掠食者的爪子，标志着一名新兵迈出了作为追踪者为部落服务的第一步。"},sec={{t="猎人的证明",b="平原徘徊者是游荡在莫高雷风吹草原上最狡猾且富有领地意识的掠食者之一。它们行动敏捷，擅长在高草丛中伏击猎物，对于旅行者来说是真正的威胁，也是对年轻猎人的一项值得一试的考验。收集它们锋利的爪子不仅是生存任务，更是一项公认的传统。斯考恩·白云建议有前途的游荡者收集这些战利品，并将其呈献给雷霆崖猎人高地上的梅洛·石蹄，以证明他们具备了追求猎人之道所必需的决心和野外生存技巧。"}},faq={{q="平原徘徊者的爪子有什么用途？",a="它们是技巧与勇气的实证。年轻的猎人需要带上四只这样的爪子前往雷霆崖猎人高地找梅洛·石蹄，以此证明他们已经准备好踏上猎人之道。",al={"徘徊者的爪子用途","为什么要获取徘徊者的爪子","猎人之道的爪子"}},{q="是谁让你去收集它们的？",a="资深猎人斯考恩·白云会指引有潜力的追踪者从莫高雷的徘徊者身上收集爪子作为证明，然后再去面见梅洛·石蹄。",al={"谁需要徘徊者的爪子","徘徊者的爪子任务发布者"}},{q="为什么平原徘徊者被视为一种合适的狩猎目标？",a="平原徘徊者是莫高雷平原上强壮、隐蔽且狡猾的食肉动物。成功追踪并战胜这种警觉的掠食者，证明了一名有志向的猎人具备牛头人传统所要求的耐心和战斗直觉。",al={"为什么要狩猎平原徘徊者","徘徊者危险吗"}}},fx={cc11ac90={q="什么是平原徘徊者的爪子？",a="这是一只从平原徘徊者身上取下的爪子。平原徘徊者是游荡在莫高雷草原上的一种掠食性野猫。对牛头人猎手而言，献上这些爪子能切实证明年轻猎人的机敏、耐心，以及日渐精进的追踪本领。",al={"平原徘徊者的爪子","什么是徘徊者的爪子"}},a7640831={q="平原徘徊者的爪子从哪里来？",a="这些爪子直接取自徘徊在莫高雷苍茫草原上的掠食性平原徘徊者。它们并非加工或制造而成，猎人必须在野外追踪并击败这些敏捷的野兽，才能将爪子完整取下。",al={"哪里能获得徘徊者的爪子","如何获得徘徊者的爪子"}},b4c8d82b={q="为什么有人想要平原徘徊者的爪子？",a="斯考恩·白云指引有志成为游侠的人收集这些爪子，以便在雷霆崖猎手高地之巅向梅洛·石蹄证明自己的实力。狩猎是牛头人文化中至高的荣誉之一，献上如此强悍、狡猾的掠食者的爪子，足以证明你已逐渐具备踏上猎手之路所需的本领和意志。",al={"为什么收集徘徊者的爪子","谁需要徘徊者的爪子","梅洛·石蹄为什么要爪子"}}},fp="21,268,16.571.0,41.207.0,29.178.0,52.245.0"}
P.entries["item:foreman-s-blackjack"] = {n="工头的木棒",s="“工头的木棒”是一根由重皮包裹的棍棒，借给来到试炼谷的部落新兵使用。工头们将它作为日常管教工具传下去，用来唤醒打瞌睡的苦工，并强制执行杜隆塔尔早期建设中那繁重的进度。",h="“工头的木棒”是一根由重皮包裹的棍棒，借给来到试炼谷的部落新兵使用。工头们将它作为日常管教工具传下去，用来唤醒打瞌睡的苦工，并强制执行杜隆塔尔早期建设中那繁重的进度。",kw={"木棒","杜隆塔尔","工头的木棒","懒惰的苦工","苦工","塔兹利尔","试炼谷"},ang={["faction:Horde"]="这根木棒突显了驯服杜隆塔尔所需的无情务实努力，在那里，想要在这片严酷的土地上定居，就需要每一位劳工不间断地工作。",["race:Orc"]="对于步入试炼谷的年轻兽人来说，挥舞这根木棒是部落等级制度的初级课程：那些没有战士力量或精神的人会被降级从事劳役，并被武力强行管束。"},sec={{t="兽人劳动工具",b="在杜隆塔尔荒凉的沙漠中建立一个新家园需要大量的木材储备，而这项劳作完全落在部落苦工的肩上。在试炼谷，工头塔兹利尔依靠“工头的木棒”来鞭策工作队。这种负重钝器并非为了造成致命打击，而是旨在为那些躲在谷中树荫下打盹的劳工提供一个惊人的警示。它鲜明地提醒着新部落中的苦工生活：艰苦、枯燥，并且在铁腕监督之下。"}},faq={{q="“工头的木棒”有什么用途？",a="监督者将这根木棒交给年轻的冒险者，用以管教试炼谷中睡觉的苦工。敲打打瞌睡的苦工会让他们猛然惊醒，并立刻回去砍伐和搬运木材。",al={"木棒用途","为何使用木棒","苦工棍棒"}},{q="这根木棒归谁所有？",a="它属于工头塔兹利尔，他是驻扎在试炼谷的劳工监督员，负责监管年轻兽人定居点所需原木的收集工作。",al={"谁提供木棒","工头木棒所有者"}},{q="为什么苦工总是会在工作中睡着？",a="兽人苦工在杜隆塔尔严酷的烈日下进行着无休止、筋疲力尽的伐木轮班。每当他们在谷中稀疏的树荫下找到休息处时，疲惫就会袭来，导致他们频繁地擅自打盹。",al={"为何苦工懒惰","懒惰的苦工睡觉"}},{q="完成任务后我能留下这根木棒吗？",a="不能。监督员要求在管教完偷懒者后立即归还工具，以确保未来的工头能随时用它来强制执行劳动定额。",al={"保留木棒","我能留下工头木棒吗"}}},fx={["4e7ef009"]={q="什么是工头的木棒？",a="工头的木棒是工头塔兹利尔在试炼谷使用的一根裹着重皮的沉重短棍。它是朴实无华的管教工具，目的不是在战斗中造成重伤，而是狠狠抽上一下，让昏昏欲睡的工人猛地清醒，重新站起来干活。",al={"什么是木棒","工头的木棒物品","什么是工头的木棒"}},["9e33a4a7"]={q="工头塔兹利尔为什么想要拿回木棒？",a="工头塔兹利尔靠木棒管理试炼谷的工队。没有它，他就很难逼迫那些疲惫又没干劲的苦工继续为部落砍伐和搬运木材。等你帮他把工人赶回岗位后，他就会要求你归还这件必不可少的工具。",al={"为什么要归还木棒","塔兹利尔为什么需要木棒","为什么想要木棒"}}},fp="19,261,22.544.0,41.211.0,24.159.0,48.220.0,50.174.0"}
P.entries["item:forged-steel-bars"] = {n="锻造好的钢锭",s="锻造好的钢锭是兽人铁匠瑟恩格瑞姆·火眼所有的精炼金属锭。它们在一次夜袭中被贪婪的刺鬃野猪人偷走。在贫瘠之地，这些钢锭是战士决心收回失窃财产的证明。",h="锻造好的钢锭是兽人铁匠瑟恩格瑞姆·火眼所有的精炼金属锭。它们在一次夜袭中被贪婪的刺鬃野猪人偷走。在贫瘠之地，这些钢锭是战士决心收回失窃财产的证明。",kw={"贫瘠之地","锻造好的钢锭","铁箱","刺鬃野猪人","被盗的铁箱","瑟恩格瑞姆·火眼"},ang={["class:Warrior"]="收回瑟恩格瑞姆被盗的钢材，证明了一个战士追踪窃贼并面对危险的野猪人族群的能力，作为回报，战士将获得定制武器。",["profession:Blacksmithing"]="这些精炼钢锭突显了粗糙的部落废金属与受过训练的部落铁匠所打造的高品质钢材之间的差距。"},sec={{t="被盗的金属",b="锻造好的钢锭是视力不佳的兽人铁匠瑟恩格瑞姆·火眼的高品质锻造原料，他在贫瘠之地北部设有一个营地。当地的刺鬃野猪人利用瑟恩格瑞姆视力衰退的弱点，用呼噜声和叫声分散了他的注意力，趁机窃走了装有钢锭的铁箱。由于不懂得精炼钢铁的工艺，野猪人将未开封的箱子丢弃在西北方营地的一辆破损货车旁，钢锭因此得以完好无损，等待着战士们将其取回。"}},faq={{q="这些锻造好的钢锭属于谁？",a="它们属于瑟恩格瑞姆·火眼，一位居住在贫瘠之地北部营地的兽人盔甲和武器锻造师。",al={"谁拥有钢锭","瑟恩格瑞姆的钢材","这是谁的钢材"}},{q="野猪人为什么要偷它们？",a="刺鬃野猪人袭击瑟恩格瑞姆的营地纯粹是为了掠夺财物。他们知道这位铁匠视力不佳，于是故意挑衅并分散他的注意力，好让部落的其他成员趁机偷走他的铁箱。",al={"为什么要偷钢材","野猪人的动机","刺鬃氏族的盗窃"}},{q="野猪人使用过这些钢材吗？",a="没有。正如瑟恩格瑞姆所料，刺鬃野猪人缺乏加工这种精炼钢材的冶金知识和技术。箱子依然完好地关闭着，被遗弃在他们营地的一辆破损货车旁。",al={"野猪人锻造过东西吗","野猪人怎么处理钢材"}},{q="瑟恩格瑞姆会用什么来报答送回钢锭的人？",a="作为勇闯野猪人营地并取回所有钢锭的报酬，瑟恩格瑞姆会奖励有志向的战士一件他亲手打造的武器。",al={"锻造好的钢锭奖励","交出钢锭能得到什么"}}},fx={["4e666297"]={q="什么是锻造好的钢锭？",a="这些钢锭是铁匠萨恩格瑞·火眼所有的一批精炼优质金属，存放在他营地的一只铁箱中，并被牢牢锁住。它们是用于锻造坚固武器的上等材料。尽管尚未加工成成品武器，其品质仍远胜贫瘠之地常见的粗劣废料。",al={"什么是锻造好的钢锭","锻造好的钢锭信息","被偷的钢锭"}}},fp="17,244,12.557.0,33.107.0,32.214.0,31.198.0,45.129.0"}
P.entries["item:fragments-of-rok-alim"] = {n="罗卡里姆的碎片",s="罗卡里姆的碎片是漫游在千针石林峡谷中的原始土元素破碎的石质遗骸。将它们带给位于老屋的多恩·平原行者，即是证明勇士已在单挑中击败这一远古恐惧无可辩驳的实物证据。",h="罗卡里姆的碎片是漫游在千针石林峡谷中的原始土元素破碎的石质遗骸。将它们带给位于老屋的多恩·平原行者，即是证明勇士已在单挑中击败这一远古恐惧无可辩驳的实物证据。",kw={"多恩·平原行者","元素","碎片","重击者","罗卡里姆","力量试炼","千针石林","老屋"},ang={["class:Shaman"]="罗卡里姆代表着一种远在现代萨满契约之前就与世界相连的古老土灵，他那不屈的本性使他成为了研究原始元素坚韧度的一个有趣案例。",["race:Tauren"]="克服艾泽拉斯原始过去的持久残余，与牛头人通过对抗大地上最强大的危险来考验和谐、坚韧和个人力量的传统紧密契合。"},sec={{t="远古力量的残余",b="虽然大多数元素在古神被放逐后便从艾泽拉斯消退了，但仍有少数元素拥有足够原始的力量，无需凡人魔法的召唤也能在地面上存活。重击者罗卡里姆正是这样一位幸存者，他徘徊在主干道以南的峡谷平原上。当地的半人马之所以认识他，是因为他那石质拳头砸碎任何愚蠢到闯入他路径之物时发出的雷鸣般轰响。击败这个原始世界的活体残余，便能获得致密、充满活力的岩石碎片——这正是证明其无与伦比体魄的绝佳战利品。"},{t="力量试炼",b="对于牛头人隐士多恩·平原行者来说，回收这些碎片是“力量试炼”决定性的环节。作为在老屋高处进行的一系列精神与武术仪式的一部分，该试炼要求受试者面对一个拥有不屈蛮力的实体。交付罗卡里姆受损的残骸，证明了冒险者拥有在卡利姆多最严酷的险境中生存所需的勇气与体魄。"}},faq={{q="什么是罗卡里姆的碎片？",a="它们是重击者罗卡里姆破碎的石质遗骸，这是一个徘徊在千针石林西北部峡谷中的远古土元素。它们作为击败该元素的证明。",al={"罗卡里姆的碎片","什么是罗卡里姆的碎片","罗卡里姆的石头"}},{q="谁需要这些石质碎片？",a="多恩·平原行者，一位居住在千针石林峡谷悬崖高处老屋的牛头人任务发布者，要求获得这些碎片来完成力量试炼。",al={"谁收集罗卡里姆的碎片","上交罗卡里姆的碎片","多恩·平原行者任务"}},{q="罗卡里姆为何重要？",a="不同于大多数必须由凡人法师召唤的现代元素，罗卡里姆自古神时代起就留存于世。峡谷中的半人马部族之所以给他取名“重击者”，是因为他那粉碎猎物时发出的拳头轰鸣声。",al={"罗卡里姆为何特别","罗卡里姆背景故事","谁是重击者罗卡里姆"}},{q="罗卡里姆在哪里可以找到？",a="罗卡里姆在千针石林的西北盆地漫游，在砂岩尖塔之间的区域主路以南徘徊。",al={"罗卡里姆位置","寻找重击者罗卡里姆","罗卡里姆在哪里刷新"}}},fx={ab6946f8={q="罗卡里姆的碎片从何而来？",a="这些碎片是重拳罗卡里姆身上崩落的石块。这个巨大的岩石元素生物游荡在千针石林西北部的峡谷底部。罗卡里姆并非由凡人施法者召唤而来，而是从上古之神时代存活至今的古老存在；即使它的主人已经陨落，它天生的力量仍足以使它留存于世。这些碎片并非由凡人亲手打造，而是直接从它活着的岩石躯体上敲下来的。",al={"罗卡里姆碎片的来历","罗卡里姆碎片从哪里来","谁制造了罗卡里姆碎片"}}},fp="21,278,28.570.0,18.449.0,35.188.0,32.176.0,28.253.0,24.131.0"}
P.entries["item:frostwolf-banner"] = {n="霜狼军旗",s="霜狼军旗是一面藏在奥特兰克山谷蛮爪洞穴深处的部落战旗。部落的新兵会被派去寻回它，作为一种唤醒战斗精神并获得氏族第一个徽记的祖传试炼。",h="霜狼军旗是一面藏在奥特兰克山谷蛮爪洞穴深处的部落战旗。部落的新兵会被派去寻回它，作为一种唤醒战斗精神并获得氏族第一个徽记的祖传试炼。",kw={"奥特兰克山谷","霜狼军旗","豺狼人","徽记","试炼场","拉格隆德","蛮爪洞穴"},ang={["faction:Horde"]="寻回这面旗帜标志着战士正式完成了血礼，并加入了拉格隆德麾下传奇的霜狼氏族。",["race:Orc"]="对于兽人而言，从野蛮的豺狼人手中夺回失落的氏族旗帜，是对霜狼氏族荣耀的致敬，也是对萨尔在奥特兰克山脉祖先遗产的传承。"},sec={{t="试炼之礼",b="对于来到奥特兰克山谷的部落战士而言，在霜狼氏族中获得真正的地位始于一场勇气的考验。拉格隆德会将新兵派往南方，进入潮湿且充满敌意的蛮爪洞穴，那是一个挤满了领地意识极强的豺狼人的巢穴。抵达深处并完好无损地带回旗帜，不仅展现了勇气，也证明了战士的战斗怒火已经觉醒，他们也将由此获得霜狼新兵的徽记。"}},faq={{q="为什么霜狼军旗会在豺狼人的洞穴里？",a="拉格隆德和氏族特意将军旗放置在蛮爪洞穴，以此作为一项入会测试。深入豺狼人的领地能迫使新战士摆脱安逸、直面危险，并唤醒他们的战斗精神。",al={"为什么军旗在蛮爪洞穴","豺狼人持有军旗","霜狼军旗位置"}},{q="我应该把霜狼军旗交给谁？",a="必须将旗帜送还给奥特兰克山谷的拉格隆德。正式将旗帜交给他，意味着新兵被正式接纳进入霜狼氏族的行列，并获得代表地位的徽记。",al={"谁需要霜狼军旗","军旗任务交还","拉格隆德 军旗"}},{q="为什么这面旗帜看起来不像常见的霜狼纹章？",a="虽然拉格隆德认可它作为氏族试炼旗帜，但其视觉标记与更古老的部落徽记相似，包括一些与旧部落早期兽人氏族相关的符号。",al={"暮光之锤符号军旗","军旗看起来不对劲","霜狼军旗设计"}}},fx={cf6c63b1={q="什么是霜狼军旗？",a="霜狼军旗是代表奥特兰克山谷中霜狼氏族的部族旗帜。旗帜上的纹章奇怪地更像古老的氏族图案，而不是他们惯用的徽记，但它仍是霜狼氏族在这片冰封山谷中存在与权威的荣誉象征。",al={"什么是霜狼军旗","霜狼军旗的背景","关于霜狼军旗"}},["518ec450"]={q="拉格隆德为什么想要找回霜狼军旗？",a="拉格隆德要求所有希望在奥特兰克山谷与霜狼氏族并肩作战的新人接受一场战斗仪式。从食人妖横行的蛮爪洞穴深处找回军旗，能够证明你的勇气，唤醒你的战士之魂，并让你获得氏族新兵的徽记。",al={"为什么找回霜狼军旗","拉格隆德为什么想要军旗","霜狼军旗的用途"}}},fp="16,231,17.460.0,48.235.0,40.179.0,57.180.0"}
P.entries["item:full-leaden-collection-phial"] = {n="装满的铅瓶",s="一个沉重的铅衬烧瓶，里面装满了从侵扰诺莫瑞根的穴居人身上采集的辐射性放射尘。发明家奥齐·电环索要这份危险的样本，希望能为患有辐射病的麻风侏儒合成解药——或者，也许是想调制出某种烈性朗姆酒。",h="一个沉重的铅衬烧瓶，里面装满了从侵扰诺莫瑞根的穴居人身上采集的辐射性放射尘。发明家奥齐·电环索要这份危险的样本，希望能为患有辐射病的麻风侏儒合成解药——或者，也许是想调制出某种烈性朗姆酒。",kw={"装满的铅瓶","诺莫瑞根药剂","诺莫瑞根","辐射穴居人","卡拉诺斯","铅质收集瓶","麻风侏儒","奥齐·电环"},ang={["profession:Engineering"]="当在实验室测试中处理挥发性、有毒的放射尘时，铅外壳展示了标准的侏儒安全规程。",["race:Gnome"]="对于丹莫罗的流亡侏儒来说，携带这种有毒样本不仅是对毒害他们家园的灾难的严峻提醒，也代表了恢复其被腐蚀族人的一种孤注一掷的希望。"},sec={{t="剧毒酿造",b="这个收集瓶的铅衬对于保护携带者免受诺莫瑞根随处可见的剧毒绿色放射尘的影响至关重要。这些放射尘源于大工匠梅卡托克的顾问们曾向地下走廊中注入有毒辐射，试图以此阻止穴居人的入侵，但这却酿成了一场灾难，导致穴居人和幸存的侏儒都被腐蚀，变成了疯狂的、受辐射感染的怪物。通过直接从辐射入侵者和掠夺者身上收集液体残渣，勇敢的冒险者为卡拉诺斯的流亡工匠（如奥齐·电环和拉兹·滑链）提供了实验治疗药物所需的原材料。"},{t="解药还是调配酒",b="虽然诺恩依然专注于收复这座城市，但奥齐·电环正通过疯狂的侏儒实验来解决放射尘问题。奥齐试图利用瓶中收集的液体来治疗一个被困的麻风侏儒——同时也希望能用这种混合物来治愈他自己的秃顶。在侏儒实验室科学中，奇迹般的解药与极其易挥发的饮料之间的界限依然十分危险。"}},faq={{q="为什么这个瓶子是铅做的？",a="铅衬层可以防止从诺莫瑞根受污染的穴居人身上采集到的强烈辐射性放射尘使将它带回卡拉诺斯的携带者患病或死亡。",al={"为什么使用铅瓶","为什么使用铅烧瓶","铅质收集瓶的用途"}},{q="谁需要这种受辐射的液体？",a="在卡拉诺斯工作的侏儒研究员奥齐·电环，在拉兹·滑链的协助下，需要这种辐射性放射尘来试验麻风病侏儒的治疗方法。",al={"谁需要这个瓶子","奥齐·电环的任务","谁来提交诺莫瑞根药剂"}},{q="瓶子里的辐射从何而来？",a="这种发光的绿色残渣直接采集自辐射入侵者和辐射掠夺者，这些穴居人在通往诺莫瑞根的受污染走廊中徘徊。",al={"如何装满瓶子","辐射穴居人的位置","绿色发光的来源"}},{q="奥齐真的能用它治好麻风侏儒吗？",a="奥齐的实验既混乱又不确定。他的调配物旨在治愈一个被俘的麻风侏儒并恢复他自己的头发，但侏儒科学通常需要反复测试和提纯样本，才能获得安全、一致的结果。",al={"解药有效吗","诺莫瑞根药剂的结果","麻风侏儒被治愈了吗"}}},fx={["32cc4509"]={q="装满的铅瓶是什么？",a="这是一只沉重的铅制屏蔽瓶，里面装着从诺莫瑞根受污染的穴居人身上直接采集的、发出绿光的放射性残留物。厚实的铅壳能防止危险的放射性残渣毒害携带者。",al={"铅瓶是什么","装满的铅瓶","这个瓶子是什么"}}},fp="28,287,12.609.0,18.425.1,30.174.0,32.172.0,48.163.0,50.235.0"}
P.entries["item:fungal-spores"] = {n="菌类孢子",s="菌类孢子采集自生长在贫瘠之地奇异绿洲周围的饱满蘑菇。这些孢子浸润了水域中神秘的生命能量，被皇家药剂师协会的研究人员视为珍宝，他们正在寻找强效试剂来调配化学药剂。",h="菌类孢子采集自生长在贫瘠之地奇异绿洲周围的饱满蘑菇。这些孢子浸润了水域中神秘的生命能量，被皇家药剂师协会的研究人员视为珍宝，他们正在寻找强效试剂来调配化学药剂。",kw={"药剂师赫布瑞姆","药剂师协会","贫瘠之地","十字路口","遗忘之池","菌类孢子","饱满蘑菇","甜水绿洲","死水绿洲"},ang={["profession:Herbalism"]="植物学家和采集者会注意到，由于贫瘠之地绿洲赋予生命的、改变性的水域，这些蘑菇发生了剧烈的生理变化。",["race:Undead"]="皇家药剂师协会重视独特的区域性试剂以支持其研究，而卡利姆多的变异真菌为他们提供了洛丹伦枯萎植被之外的另一种诱人选择。"},sec={{t="绿洲的活力",b="在贫瘠之地的干旱平原上，像遗忘之池、甜水绿洲和死水绿洲这样的翡翠绿洲都搏动着异常的活力。那里的水不仅仅能解渴，它还能积极地加速、改变并激发周围的植物和野生动物。生长在潮湿岸边的蘑菇变得肿胀，沉甸甸的，充满了承载着这种浓缩、多变生长潜力的孢子。对于博物学家来说，这是一种生态奇观；而对于皇家药剂师协会来说，这是等待武器化或提纯的优质植物标本。"},{t="被遗忘者炼金术",b="驻扎在各地的药剂师，例如十字路口的药剂师赫布瑞姆，不断采集当地特有的试剂送回实验室，或与雷霆崖的药剂师扎玛等远方的同事分享。孢子改变了的生理机能使它们在配制强效化学溶液时显得尤为珍贵。被遗忘者重视这些标本，正是因为它们天然的属性已经受到了卡利姆多地表下汹涌的神秘力量的影响而发生了改变。"}},faq={{q="在哪里可以找到这些孢子？",a="菌类孢子采集自贫瘠之地主要绿洲岸边生长的饱满蘑菇：遗忘之池、甜水绿洲和死水绿洲。",al={"孢子位置","哪里寻找菌类孢子","饱满蘑菇位置"}},{q="为什么被遗忘者对它们感兴趣？",a="这些孢子浸润了绿洲中改变过的、充满活力的生命能量。药剂师赫布瑞姆利用它们为皇家药剂师协会以及他在雷霆崖的同事药剂师扎玛酿造强效炼金药剂。",al={"为什么赫布瑞姆需要孢子","药剂师孢子用途","孢子有什么用"}},{q="为什么绿洲周围的蘑菇长得那么大？",a="贫瘠之地绿洲的水域拥有不同寻常的生命力，能够激发并改变周围的动植物，导致岸边的真菌因充满强效的变异孢子而肿胀。",al={"为什么蘑菇会变异","绿洲水域影响","绿洲之谜"}},{q="谁需要这些孢子？",a="驻扎在贫瘠之地十字路口的被遗忘者炼金师药剂师赫布瑞姆会委托冒险者去收集这些孢子用于他的研究。",al={"谁需要菌类孢子","孢子任务发布者","药剂师赫布瑞姆"}}},fx={["3c4c96db"]={q="这些菌类孢子是什么？",a="这是从贫瘠之地各处绿洲（如遗忘之池）周围生长的丰饶蘑菇上采集的强效孢子。绿洲水流中奇异而变异的生命能量滋养着这些真菌，使它们产生具有特殊生物特性的孢子，令炼金术士颇感兴趣。",al={"菌类孢子是什么","菌类孢子介绍","这些孢子是什么"}},["02f1bc1b"]={q="药剂师赫布瑞姆为什么想要菌类孢子？",a="十字路口的药剂师赫布瑞姆为皇家药剂师协会搜寻这些孢子。他发现绿洲真菌的变异特性对调配一种实验性药剂特别有用，并打算将药剂送给他在雷霆崖的同僚药剂师扎玛。",al={"赫布瑞姆为什么要孢子","为什么要菌类孢子","谁需要菌类孢子"}}},fp="13,268,21.570.0,16.495.0,29.168.0,40.228.0,52.197.0,24.146.0"}
P.entries["item:furen-s-instructions"] = {n="弗伦的材料清单",s="《弗伦的材料清单》是暴风城的军械大师弗伦·长须交给冒险者的一张手写羊皮纸。它详细列出了为大有可为的联盟勇士锻造火淬锁甲所必需的稀有且危险的试剂。",h="《弗伦的材料清单》是暴风城的军械大师弗伦·长须交给冒险者的一张手写羊皮纸。它详细列出了为大有可为的联盟勇士锻造火淬锁甲所必需的稀有且危险的试剂。",kw={"烧焦的奇美拉角","火淬锁甲","弗伦·长须","弗伦的材料清单","光滑的奇美拉角","剃刀沼泽","烧焦的蜘蛛牙","石爪山脉","燃素","湿地"},ang={["class:Warrior"]="这份清单代表了联盟勇士向重型锁甲过渡的成人礼，要求他们经历与凶猛野兽和邪恶野猪人的战斗考验。",["profession:Blacksmithing"]="弗伦的异域配方展示了大师级铁匠如何将野兽试剂与稀有炼金蒸馏物相结合，以锻造出超越普通凡铁的护甲。"},sec={{t="大师级铁匠的需求",b="弗伦·长须不会轻易交出非凡的护甲。在通过简单的锻造任务考验过勇士的决心后，这位矮人工匠提出只要冒险者能亲自找回稀有组件，他便愿意打造一套极其坚韧的锁甲。为了确保不出纰漏，弗伦提供了这份详细的清单，指派他的委托人横跨大陆进行一场艰苦的搜寻行动。"},{t="异域组件",b="这份清单概述了一段横跨东部王国和卡利姆多的危险旅程。制作淬火链甲需要几十个取自湿地阴冷洞穴的烧焦蜘蛛毒牙、取自石爪山脉火喷吐奇美拉的犄角，以及取自奇美拉首领本尊的一根光滑的奇美拉角。最后的炼金催化剂是一瓶极不稳定的燃素，它被深藏在剃刀沼泽的野猪人堡垒中。"}},faq={{q="什么是《弗伦的材料清单》？",a="这是一张由暴风城的铁匠弗伦·长须交给联盟勇士的手写清单。它概述了锻造一套火淬锁甲所需的特定异域材料。",al={"弗伦的材料清单","什么是弗伦的材料清单","弗伦清单"}},{q="谁是弗伦·长须？",a="弗伦·长须是驻扎在暴风城矮人区的一位矮人军械大师。他专门负责考验经验丰富的勇士，并为他们制作耐用的防护装备。",al={"弗伦是谁","弗伦·长须","弗伦 暴风城"}},{q="清单上的材料来自哪里？",a="这份清单让勇士们奔波四方：烧焦的蜘蛛毒牙是从湿地的蜘蛛身上取回的，烧焦的犄角和光滑的奇美拉角是从石爪山脉的奇美拉身上狩猎所得，而一瓶燃素必须从剃刀沼泽的Roogug那里夺取。",al={"我在哪里可以找到这些物品","弗伦材料位置","弗伦清单上的材料"}},{q="弗伦用这些材料锻造什么？",a="当所有危险的试剂和清单都交还给他后，弗伦会运用他的锻造秘法，为勇士锻造一件专门的火淬锁甲。",al={"弗伦制作什么护甲","火淬锁甲奖励","弗伦锻造奖励"}}},fp="20,156,24.290.0,17.417.0,29.159.0,23.147.0,45.191.0,43.117.0"}
P.entries["item:furen-s-notes"] = {n="弗伦的笔记",s="《弗伦的笔记》是一系列手抄卷宗，记录了弗伦·长须在暴风城发现的冶金与盔甲锻造心得。这些笔记是在他为老兵打造了坚固的防护装备后写下的，并被分发至联盟各处，旨在帮助同行匠人精进技艺。",h="《弗伦的笔记》是一系列手抄卷宗，记录了弗伦·长须在暴风城发现的冶金与盔甲锻造心得。这些笔记是在他为老兵打造了坚固的防护装备后写下的，并被分发至联盟各处，旨在帮助同行匠人精进技艺。",kw={"锻造","dwarven district","弗伦","弗伦·长须","弗伦的笔记","格里曼德·艾尔莫","克洛克摩特·斯派纳斯潘","马希尔"},ang={["class:Warrior"]="这些笔记是直接根据你在暴风城的职业盔甲试炼结果起草的，作为源于你前线战斗需求的实际创新证明。",["profession:Blacksmithing"]="这些卷宗代表了联盟各地矮人、精灵和侏儒工匠之间正在进行的专业盔甲锻造知识交流。"},sec={{t="大师的发现",b="每当弗伦·长须在暴风城的Dwarven District完成严苛的战士专业武器锻造工作后，他便会将在此过程中发现的方法和突破编纂成笔记。矮人冶金术在不断演进，弗伦会制作多份这些专著的副本，以便同僚们能够复制并拓展他的发现。这些文档记录了在回火、加固以及塑造能够抵御致命战斗打击的盔甲方面的实用进展。"},{t="分发至联盟各地",b="弗伦会将他的笔记分发给联盟工艺网络中值得信赖的联系人。虽然像格里曼德·艾尔莫这样的本地大师可能会对他声称曾教导过的同僚所传授的知识嗤之以鼻，但这些心得的价值却不容忽视。这些副本甚至被跨越无尽之海，送到了达纳苏斯战士区的暗夜精灵工匠（例如马希尔）手中，通过共同的军事需求，架起了不同祖传技艺之间的桥梁。"}},faq={{q="《弗伦的笔记》中包含什么内容？",a="这些笔记包含了弗伦·长须在为经验丰富的战士打造定制盔甲时，所研发的盔甲锻造技术和冶金发现的书面描述。",al={"什么是弗伦的笔记","弗伦的笔记里有什么","弗伦的笔记内容"}},{q="弗伦·长须是谁？",a="弗伦·长须是一位驻扎在暴风城Dwarven District的矮人大师级盔甲锻造师，以指导新晋战士和打造专业防御装备而闻名。",al={"这是谁写的","谁是弗伦","弗伦·长须"}},{q="为什么格里曼德·艾尔莫会对这些笔记感到生气？",a="格里曼德·艾尔莫是一位极度自负的武器和盔甲锻造师，他声称自己教给了这位矮人所知的一切。尽管对于他的前学生能教给他新知识这种暗示感到愤怒，格里曼德依然承认笔记中描述的技术值得一试。",al={"为什么格里曼德很生气","格里曼德·艾尔莫的反应","格里曼德的自负"}},{q="谁会收到《弗伦的笔记》的副本？",a="弗伦将他的著作副本发送给联盟各地值得信赖的同僚，包括暴风城的武器锻造师格里曼德·艾尔莫、达纳苏斯的暗夜精灵锻造师马希尔，以及铁炉堡的侏儒铁匠克洛克摩特·斯派纳斯潘。",al={"谁收到了弗伦的笔记","笔记发往何处","递送弗伦的笔记"}},{q="马希尔对这些笔记有何反应？",a="与暴风城那些粗鲁的铁匠不同，马希尔——一位身处达纳苏斯战士区的暗夜精灵铁匠——以开放的热情欢迎这些矮人的心得，他将弗伦的发现视为一项伟大的发现，并以此为荣，将其融入到自己的工作中。",al={"马希尔的反应","达纳苏斯的马希尔","马希尔怎么想"}}},fp="13,227,22.352.0,30.361.0,39.172.0,23.146.0,50.211.0,37.212.0,36.183.0"}
P.entries["item:furlbrow-s-deed"] = {n="法布隆的地契",s="法布隆的地契是属于农夫西奥多·法布隆和他的妻子维尔娜在西部荒野的土地的合法产权证明。它被迪菲亚潜行者抢走，用作伪造土地所有权凭证的模板，这体现了王国各地被迫背井离乡的诚实民众所面临的危险处境。",h="法布隆的地契是属于农夫西奥多·法布隆和他的妻子维尔娜在西部荒野的土地的合法产权证明。它被迪菲亚潜行者抢走，用作伪造土地所有权凭证的模板，这体现了王国各地被迫背井离乡的诚实民众所面临的危险处境。",kw={"地契","迪菲亚潜行者","农场","法布隆","西奥多","维尔娜","马车","西部荒野"},ang={["faction:Alliance"]="归还地契给那些因王国军力不足而被抛弃的流离失所的臣民带来了一丝慰藉。",["race:Human"]="窃取普通产权证明的行为凸显了迪菲亚潜行者对暴风城周边领土的社会秩序造成了多么严重的破坏。"},sec={{t="被盗的土地与伪造的凭证",b="这份文件由西奥多·法布隆签署，并由他的妻子维尔娜联合签署，确定了他们在西部荒野的家庭农场的所有权。当迪菲亚潜行者占领该地区时，强盗们强迫这对夫妇离开，并将这份文件带进了艾尔文森林。背面的潦草笔记显示，窃贼打算将这张正式文书用作模板，为其他房产伪造合法地契。失去家园和生计的法布隆一家被迫流落街头，在马车抛锚后被困在边界附近。"}},faq={{q="迪菲亚潜行者为什么要偷地契？",a="羊皮纸背面的笔记显示，迪菲亚暴徒打算研究上面的真实印章和签名，从而伪造他们自己的地契，使他们对西部荒野各地强占的宅地拥有合法的所有权。",al={"为什么要偷地契","强盗为什么想要地契","迪菲亚地契用途"}},{q="这份地契属于谁？",a="该地契在法律上属于农夫西奥多·法布隆和他的妻子维尔娜，他们是两名遭到歹徒骚扰并被赶出自己农场的西部荒野宅地主。",al={"谁拥有法布隆的地契","法布隆是谁","这是谁的地契"}},{q="在哪里可以找到法布隆夫妇？",a="这对夫妇位于西部荒野境内，就在从艾尔文森林延伸出来的主路旁，他们被困在抛锚的马车边上。",al={"法布隆夫妇在哪里","农夫法布隆的位置","在哪里归还地契"}},{q="既然法布隆夫妇已经逃离，为什么他们还在意这份地契？",a="虽然法布隆夫妇承认西部荒野对普通百姓来说已经变得过于危险，但保留合法的产权证明是他们有朝一日在和平恢复后夺回土地的唯一希望。",al={"为什么他们想要回地契","法布隆夫妇会回来吗"}}},fp="15,210,29.449.0,34.139.0,29.121.0,33.108.0,60.155.0"}
P.entries["item:furlbrow-s-pocket-watch"] = {n="法布隆的怀表",s="法布隆的怀表是西部荒野的农夫法布隆珍视的传家宝。这块怀表是他结婚时岳父送给他的，在迪菲亚潜行者夺取他们的南瓜农场时，他仓促间将怀表遗弃在了家里。",h="法布隆的怀表是西部荒野的农夫法布隆珍视的传家宝。这块怀表是他结婚时岳父送给他的，在迪菲亚潜行者夺取他们的南瓜农场时，他仓促间将怀表遗弃在了家里。",kw={"本尼·布兰科","迪菲亚潜行者","农夫法布隆","法布隆的怀表","被遗忘的传家宝","弗娜·法布隆","衣柜","西部荒野"},ang={["faction:Alliance"]="帮助法布隆夫妇找回他们丢失的传家宝，严酷地提醒着人们：暴风城王室在保护西部荒野勤劳的农夫免受有组织劫匪侵害方面，是多么彻底地失败了。"},sec={{t="废墟中的纪念品",b="当迪菲亚暴徒蜂拥进入法布隆南瓜田时，农夫法布隆和他的妻子维娜被迫在深夜弃家逃亡。在疯狂的逃生过程中，这位农夫落下了一块珍贵的怀表，那是他岳父送给他的结婚礼物。这件传家宝一直藏在被占领的农舍衣柜里，由本尼·布兰科率领的暴徒看守着。对于露宿在路边的这对流离失所的夫妇来说，找回这块怀表意味着保住了他们昔日生活中为数不多的、尚未被歹徒毁掉的遗物。"}},faq={{q="为什么这块怀表对农夫法布隆如此重要？",a="这块怀表是农夫法布隆结婚时岳父送给他的。在失去了土地、家园和生计之后，这块怀表成了这对夫妇仅存的、具有深厚情感价值的物品。",al={"为什么法布隆想要回他的表","法布隆怀表的重要性","是谁给了法布隆那块表"}},{q="怀表被放在哪里？",a="怀表被留在了法布隆农舍内的一个衣柜里，农舍位于主路西侧的南瓜田中央，法布隆夫妇目前正被困在那里。",al={"怀表在哪里","法布隆衣柜的位置","如何找到怀表"}},{q="谁在看守这块怀表？",a="被废弃的农舍已经被迪菲亚潜行者占据，确切地说是歹徒本尼·布兰科和他的同伙，他们就徘徊在衣柜附近。",al={"谁拿着法布隆的表","西部荒野的守表人","本尼·布兰科怀表"}},{q="是迪菲亚潜行者直接偷走了怀表吗？",a="不是。当歹徒袭击南瓜田时，法布隆夫妇惊慌失措地逃跑，农夫只是忘记把它带走而已。当农场被洗劫时，它一直隐藏在他们卧室的衣柜里。",al={"迪菲亚抢走怀表了吗","怀表是被偷的吗"}}},fp="23,194,23.421.0,56.197.0,31.138.0,26.107.0,40.185.0"}
P.entries["item:gaea-seed"] = {n="盖亚之种",s="盖亚之种是生长在石爪山脉暗色湖水边的坚韧植物内核。它们深受牛头人萨满的珍视，被赋予了元素祝福，能够帮助复苏饱受战争与工业蹂躏的土地。",h="盖亚之种是生长在石爪山脉暗色湖水边的坚韧植物内核。它们深受牛头人萨满的珍视，被赋予了元素祝福，能够帮助复苏饱受战争与工业蹂躏的土地。",kw={"焦炭谷","重生循环","大地母亲","盖亚之种","暗色湖","石爪山脉","烈日石居","塔姆拉·荒原"},ang={["class:Shaman"]="这些种子代表着切实的大地复原工作，展示了萨满仪式和大地母亲的祝福如何加速受损环境中的自然生长。",["race:Tauren"]="对于烈日石居的牛头人来说，培育盖亚之种是一种神圣的义务，旨在治愈因外部战争和木材开采而失衡的土地。"},sec={{t="复苏之种",b="盖亚之种原产于石爪山脉，自然漂浮或生长在暗色湖的岸边。虽然它们外表朴素——看起来像小而多纤维的椰子——但却蕴含着与生俱来的顽强生命力。随着工业开采和冲突使石爪山脉伤痕累累，萨满修行者将这些种子视为治愈受创大地的关键媒介。"},{t="大地母亲的祝福",b="在烈日石居，牛头人萨满塔姆拉·荒原收集盖亚之种，以抵御在群山间蔓延的破坏。通过传统的吟唱和元素仪式，萨满们将大地母亲的祝福注入这些休眠的种壳中。这种精神注入极大地加速了它们的自然生长，将简单的种子变成了坚韧的树苗，使它们能够在焦炭谷这样焦黑荒芜的土地上扎根。"}},faq={{q="在哪里可以找到盖亚之种？",a="盖亚之种散落在石爪山脉烈日石居以北山区的暗色湖岸边。",al={"盖亚之种位置","哪里可以找到盖亚之种","如何获得盖亚之种"}},{q="盖亚之种有什么用途？",a="塔姆拉·荒原在烈日石居收集它们以进行元素祝福。一旦被注入萨满力量，这些种子就会被用来恢复焦炭谷等受灾地区的植被。",al={"盖亚之种用途","为什么要收集盖亚之种","塔姆拉如何处理盖亚之种"}},{q="为什么萨满需要为种子注入祝福？",a="石爪山脉的部分地区因火灾、战争和伐木活动而严重退化。将大地母亲的力量引导至种子中可以加速它们的萌发，并增强其生命力，使其足以在恶劣、荒废的土壤中生长。",al={"为什么要祝福种子","萨满盖亚之种魔法"}},{q="盖亚之种长什么样？",a="它们位于暗色湖的水边，看起来像是岸边的小巧、棕色、圆形的种壳或椰子。",al={"盖亚之种外观","如何发现盖亚之种"}}},fx={["0f706426"]={q="盖亚之种是什么？",a="盖亚之种是一种坚韧的椰子状种核，原产于石爪山脉。它们天生坚韧，蕴含强大的植物生长潜能。牛头人萨满借助大地母亲的祝福引导这股力量，让遭受工业贪欲和战火蹂躏的土地重新焕发生机。",al={"盖亚之种是什么","盖亚之种介绍","什么是盖亚之种"}},e9a7441d={q="盖亚之种来自哪里？",a="盖亚之种是天然的植物奇珍，只生长在石爪山脉高处、烈日石居以北的暗色湖沿岸。它们并非由凡人制作，而是大地母亲赐予的自然馈赠，在湖岸边自然繁茂。",al={"谁制作了盖亚之种","盖亚之种来源","盖亚之种来自哪里"}},["3509f4c5"]={q="塔姆拉·荒原为什么想要盖亚之种？",a="烈日石居的萨满塔姆拉·荒原想用盖亚之种治愈伤痕累累的石爪山荒野。持续的伐木和战斗重创了这片区域，尤其是焦炭谷那片焦土。收集这些种子后，她便能将大地母亲的祝福和萨满之力注入其中，加速它们生长，重建这片荒芜之地。",al={"为什么收集盖亚之种","谁想要盖亚之种","为什么有人想要盖亚之种"}}},fp="9,234,18.363.0,28.435.1,27.137.0,29.204.0,39.235.0,29.128.0"}
P.entries["item:gaffer-jack"] = {n="小齿轮",s="“小齿轮”是一种特殊的工程学组件，用于精密的机械调节，例如校准stintle栓。怪诞的侏儒发明家维兹班恩·曲针在横跨海洋的旅途中，不慎将一箱小齿轮弄丢在了奥伯丁海岸外的波涛之下。",h="“小齿轮”是一种特殊的工程学组件，用于精密的机械调节，例如校准stintle栓。怪诞的侏儒发明家维兹班恩·曲针在横跨海洋的旅途中，不慎将一箱小齿轮弄丢在了奥伯丁海岸外的波涛之下。",kw={"奥伯丁","黑海岸","钓鱼","小齿轮","铁炉堡","stintle栓","维兹班恩·曲针"},ang={["profession:Engineering"]="同行技师们一定能体会到丢失小齿轮这种专用硬件时的那种沮丧心情，因为没有它们，像stintle栓这样精密的机械就无法校准。",["race:Gnome"]="离开铁炉堡的喧嚣去奥伯丁过平静的生活，这对侏儒来说也许有些非同寻常，但喝醉之后从船舷掉落整整一箱必要零件，却完全符合他的性格。"},sec={{t="遗失在海上",b="为了寻求远离铁炉堡那叮当作响的锻造车间和喧闹酒馆的安宁，侏儒技师维兹班恩·曲针预订了前往奥伯丁的船票。在远洋航行中因为喝得太多，维兹班恩一不小心，竟然把整整一箱小齿轮从栏杆上掉进了海里。这些小巧的机械紧固件沉入了黑海岸雾气弥漫的沿海水域，让他陷入了困境，无法校准他那至关重要的stintle栓。"},{t="沉没的打捞物",b="由于小齿轮洒落在沿岸的浪花中，它们偶尔会勾住那些在黑海岸沿海水域垂钓的耐心渔夫的鱼钩。找回这些丢失的组件让维兹班恩得以组装他那些古怪的装置，尽管从公海中捞出微小的金属零件依然是对非凡耐心和纯粹运气的考验。"}},faq={{q="小齿轮有什么用处？",a="根据侏儒技师维兹班恩·曲针的说法，小齿轮是用来校准他那些实验性发明所用的stintle栓的必备工程学组件。",al={"小齿轮用途","小齿轮的作用","小齿轮的使用"}},{q="它们是怎么掉进奥伯丁周围的海里的？",a="维兹班恩·曲针从东部王国乘船出发，想要寻求远离铁炉堡的安宁。在航行期间，他喝得酩酊大醉，不小心把那箱小齿轮掉进了黑海岸的水域里。",al={"为什么小齿轮在水里","谁弄丢了小齿轮","小齿轮丢失"}},{q="谁需要找回小齿轮？",a="正在奥伯丁港口城镇逗留的怪诞侏儒发明家维兹班恩·曲针需要拿回八个小齿轮，以便继续制造他那些奇怪的发明。",al={"谁需要小齿轮","小齿轮上交","谁回收小齿轮"}},{q="在哪里可以找到小齿轮？",a="它们沉在黑海岸的沿海地带，静静躺在海床上，垂钓者在沿岸浪花中钓鱼时偶尔会将它们钓上来。",al={"去哪找小齿轮","如何找到小齿轮","小齿轮位置"}}},fx={["1164a7e3"]={q="小齿轮是什么？",a="小齿轮是一种特殊的工程学零件，维兹班恩·曲针这样的技师会用到它。维兹班恩需要用它们来正确调校他的斯汀特尔插销，因此小齿轮是他发明工具箱里不可或缺的零件。",al={"小齿轮是什么","小齿轮的背景"}}},fp="11,291,11.493.0,14.379.0,31.165.0,51.233.0,33.161.0,32.143.0"}
P.entries["item:gallywix-s-head"] = {n="加里维克斯的头颅",s="加里维克斯的头颅是一个从总工头普兹克·加里维克斯身上割下来的战利品，他是活跃在贫瘠之地淤泥沼泽的荆棘谷地精的一名监工。这是基于奥格瑞玛的秘密潜行者组织碎手氏族所要求的处决证明，虽然十分恐怖，但确凿无疑。",h="加里维克斯的头颅是一个从总工头普兹克·加里维克斯身上割下来的战利品，他是活跃在贫瘠之地淤泥沼泽的荆棘谷地精的一名监工。这是基于奥格瑞玛的秘密潜行者组织碎手氏族所要求的处决证明，虽然十分恐怖，但确凿无疑。",kw={"贫瘠之地","加里维克斯","奥格瑞玛","普兹克","碎手氏族","申苏尔","淤泥沼泽","荆棘谷地精"},ang={["class:Rogue"]="取回加里维克斯的头颅证明了一名潜行者在代表碎手氏族进行秘密潜入、潜行和目标刺杀方面的致命能力。",["faction:Horde"]="清除像加里维克斯这样的荆棘谷地精领导人，可以遏制威胁到贫瘠之地和杜隆塔尔边境的掠夺性工业入侵。"},sec={{t="一份冷酷的清除证明",b="总工头普兹克·加里维克斯在淤泥沼泽北部的荆棘谷地精塔楼里指挥行动。有消息称荆棘谷地精正在策划一项宏大的计划，于是碎手氏族派遣特工去彻底摧毁该设施。带回普兹克·加里维克斯的头颅是向奥格瑞玛的申苏尔证明该监工已被处决的绝对证据，这能确保潜行者在公会中的地位。"},{t="淤泥沼泽入侵",b="获取加里维克斯头颅的任务伴随着一项指令，即取回被窃的赞吉尔的改良药剂并屠杀塔内被毒害的人员。通过刺杀高踞在塔顶的加里维克斯并将他的头颅带回大断崖，特工们证实了荆棘谷地精在贫瘠之地的宏大计划已被挫败。"}},faq={{q="这是谁的头颅？",a="这个头颅属于总工头普兹克·加里维克斯，他是一名负责监督荆棘谷地精在北贫瘠之地淤泥沼泽行动的地精监工。",al={"谁是加里维克斯","普兹克·加里维克斯","加里维克斯头颅的来历"}},{q="谁想要加里维克斯的头颅？",a="这个战利品要交给申苏尔，他是位于奥格瑞玛大断崖的一名潜行者训练师，也是碎手氏族的特工。",al={"把头颅交给谁","上交加里维克斯的头颅","申苏尔 头颅"}},{q="为什么碎手氏族想要他死？",a="普兹克·加里维克斯经营着淤泥沼泽北部的荆棘谷地精塔楼，荆棘谷地精在那里策划着一项宏大的计划，他还将最后一批赞吉尔的改良药剂存放在自己的保险箱里。碎手氏族对他发出死亡通牒，以破坏他们的行动并夺取药剂。",al={"为什么要杀加里维克斯","刺杀加里维克斯的原因"}},{q="普兹克·加里维克斯在哪里？",a="他就在北贫瘠之地淤泥沼泽以北的荆棘谷地精塔楼的最顶层。",al={"加里维克斯在哪里","加里维克斯的位置","淤泥沼泽塔楼首领"}}},fx={["862bd188"]={q="加里维克斯的头颅来自哪里？",a="这颗头颅来自地精主管大工头普兹克·加里维克斯。他负责管理荆棘谷地精在贫瘠之地淤泥沼泽北面高塔内的行动。奉破碎之手之命潜入据点并消灭其中的成员后，一名刺客在高塔顶部从大工头的尸体上割下头颅，以此证明行动已取得决定性胜利。",al={"如何获得加里维克斯的头颅","加里维克斯头颅的来源"}}},fp="15,275,27.425.0,24.346.1,19.150.0,26.134.0,42.290.0,32.119.0"}
P.entries["item:galvanized-horn"] = {n="光滑的奇美拉角",s="光滑的奇美拉角是一种坚硬的生物生长物，是从徘徊在卡利姆多焦灼峭壁上的可怕奇美拉族母身上采集而来的。这种坚韧的样本深受两大阵营的顶级护甲师青睐，是制作专业战士护甲的核心材料。",h="光滑的奇美拉角是一种坚硬的生物生长物，是从徘徊在卡利姆多焦灼峭壁上的可怕奇美拉族母身上采集而来的。这种坚韧的样本深受两大阵营的顶级护甲师青睐，是制作专业战士护甲的核心材料。",kw={"焦炭谷","奇美拉族母","火炼锁甲","弗伦·长须","光滑的奇美拉角","奥姆·石蹄","石爪山脉"},ang={["class:Warrior"]="猎杀族母并获取她的光滑的奇美拉角是对耐力和力量的考验，证明了战士在暴风城或雷霆崖的护甲大师眼中的勇气。",["profession:Blacksmithing"]="这种角证明了在极端环境中硬化的有机材料，其强度可以媲美甚至超过用于定制护甲加固件的加工金属。"},sec={{t="焦炭谷的战利品",b="奇美拉是一种凶猛的双头野兽，但徘徊在石爪山脉焦炭谷中的年长族母，其长角经过灰烬、火焰和生存环境的淬炼，变得异常坚硬。普通幼崽身上只会产出易碎的烧焦的奇美拉角，而族母的角却具有如同经过特殊处理的金属般天然回火的强度。暴风城的矮人护甲师弗伦·长须和雷霆崖的奥姆·石蹄都对这种角垂涎三尺，他们将其视为武勇的试金石，也是锻造卓越锁甲的关键材料。"}},faq={{q="光滑的奇美拉角来自哪里？",a="它取自栖息在石爪山脉西部的焦炭谷中的奇美拉族母。",al={"如何获取光滑的奇美拉角","怎样得到光滑的奇美拉角","光滑的奇美拉角掉落"}},{q="为什么铁匠需要这种特殊的角？",a="顶级护甲师看重这种角天然的密度和耐热特性，并用它来加固特制的锁甲和板甲。",al={"光滑的奇美拉角用途","光滑的奇美拉角使用"}},{q="谁会接受光滑的奇美拉角？",a="对于联盟战士，暴风城的弗伦·长须需要这种角来锻造火炼护甲。对于部落战士，雷霆崖的奥姆·石蹄则将其视为力量的证明，用以打造战士的头盔。",al={"谁需要光滑的奇美拉角","光滑的奇美拉角上交"}},{q="它和普通的烧焦的奇美拉角有什么区别？",a="普通的烧焦的奇美拉角很容易从较弱的幼年奇美拉身上采集到。而光滑的奇美拉角只产自成熟的族母，拥有更致密、经过回火的结构，适合进行大师级的锻造。",al={"烧焦的奇美拉角与光滑的奇美拉角对比","它和烧焦的奇美拉角有什么不同"}}},fp="15,162,26.406.0,39.107.0,38.129.0,32.203.0,47.175.0"}
P.entries["item:gargantuan-tumor"] = {n="巨大的瘤",s="巨大的瘤是从泰达希尔受到腐蚀的树妖橡木之拳身上撕下来的一块巨大的病变增生物。它是奥拉密斯湖周围生物遭受不自然疾病侵害的鲜明证据。",h="巨大的瘤是从泰达希尔受到腐蚀的树妖橡木之拳身上撕下来的一块巨大的病变增生物。它是奥拉密斯湖周围生物遭受不自然疾病侵害的鲜明证据。",kw={"腐蚀","巨大的瘤","奥拉密斯湖","橡木之拳","泰达希尔","树妖"},ang={["class:Druid"]="对于那些致力于培育泰达希尔幼嫩枝叶的德鲁伊来说，这个怪异的瘤是一个警示，提醒他们枝叶间的自然环境极易受到腐蚀的侵害。",["race:NightElf"]="看到一位受人尊敬的树妖长者沦为疯狂的枯萎怪物，突显了卡多雷的新家园所面临的日益严重的生态困境。"},sec={{t="湖泊之上的枯萎",b="在奥拉密斯湖的南岸附近，一个洞穴掩护着橡木之拳，它曾经是一位高贵的树妖长者，但如今已沦为邪恶折磨的牺牲品。这只生物身上长着巨大的增生物，显然是它导致了橡木之拳行为的扭曲，并将腐蚀扩散到了周围的野生动物身上。切除这个怪异的瘤不仅对于终结这只野兽备受折磨的狂暴状态至关重要，也能让当地的研究人员检查这种枯萎病，并了解这种邪恶的疾病是如何在这棵新生的世界之树的枝干中扎根的。"}},faq={{q="巨大的瘤来自哪里？",a="这个瘤是从橡木之拳身上取下的。橡木之拳是一只体型巨大的受腐蚀树妖，栖息在泰达希尔奥拉密斯湖南岸的一个洞穴中。",al={"瘤的来源","如何获得巨大的瘤","橡木之拳掉落物"}},{q="是什么导致了橡木之拳身上的瘤？",a="这是毒害奥拉密斯湖周围树妖和野生生物的奇怪腐蚀的外在症状。橡木之拳曾经是它族群中伟大的领袖，但最终完全屈服于这种致命的增生。",al={"为什么橡木之拳会长瘤","树妖疾病","奥拉密斯湖腐蚀"}},{q="谁想要研究这个瘤？",a="该地区的调查员需要这个瘤来研究折磨当地树妖的奇怪腐烂，希望能找出治疗或阻止这种枯萎病的方法。",al={"谁需要这个瘤","上交巨大的瘤","橡木之拳任务上交"}}},fx={b9b4574c={q="巨大的瘤是什么？",a="这是从橡树之心身上割下的一大块畸形赘生物。橡树之心是一位堕落的木爪长者，潜伏在奥拉密斯湖南岸的一处洞穴中。这个瘤明显正在毒害它，使它陷入疯狂，并助长了不自然的腐烂和疾病在当地水域及附近野生动物中的蔓延。",al={"巨大的瘤是什么","巨大的瘤","橡树之心的瘤"}}},fp="16,222,20.499.0,42.141.0,48.207.0,30.152.0"}
P.entries["item:garrick-s-head"] = {n="加瑞克的头颅",s="加瑞克的头颅是加瑞克·帕德福特的断头，他是一个在北郡山谷的北郡农场附近活动的臭名昭著的暴徒。这是用来领取北郡修道院当局悬赏的令人毛骨悚然的死亡证明。",h="加瑞克的头颅是加瑞克·帕德福特的断头，他是一个在北郡山谷的北郡农场附近活动的臭名昭著的暴徒。这是用来领取北郡修道院当局悬赏的令人毛骨悚然的死亡证明。",kw={"悬赏","维里副队长","艾尔文森林","加瑞克·帕德福特","加瑞克的头颅","北郡修道院","北郡山谷"},ang={["class:Rogue"]="消灭帕德福特向当地的恶棍表明，肆无忌惮的拦路抢劫将招致更致命、更专业的利刃的制裁。",["race:Human"]="取下帕德福特的头颅是年轻的暴风城新兵对艾尔文森林中日益蔓延的无法无天状态所打出的第一记决定性的打击。"},sec={{t="强盗的末路",b="数周以来，加瑞克·帕德福特和他的暴徒团伙骚扰着整个北郡山谷的当地农民和商人。利用暴风城王国防守吃紧的机会，加瑞克躲在北郡农场附近的一间棚屋里，洗劫过往的商队。由于当地卫兵被不断逼近的狗头人和迪菲亚兄弟会强盗牵制，维里副队长对帕德福特发出了悬赏，寻找有进取心的冒险者来消灭这个不法之徒，并提供他死亡的无可辩驳的证明。"}},faq={{q="加瑞克·帕德福特是谁？",a="加瑞克·帕德福特是一个恶毒的暴徒，他恐吓着北郡山谷的农民、农场和过往商贩。他在北郡修道院以东，河流对岸建立了一个带着一伙暴徒的小据点。",al={"加瑞克是谁","加瑞克·帕德福特背景故事","帕德福特是谁"}},{q="为什么要割下头颅才能领取赏金？",a="艾尔文森林的边境正义需要无可辩驳的证明。维里副队长和北郡当局在发放赏金之前，需要加瑞克死亡的有形证据。",al={"为什么要他的头","死亡证明","为什么要取下加瑞克的头"}},{q="加瑞克·帕德福特躲在哪里？",a="帕德福特在北郡修道院以东，北郡农场附近河流桥梁对面的一间小木棚屋里建立了营地。",al={"加瑞克在哪里","加瑞克棚屋位置","去哪里找加瑞克·帕德福特"}},{q="谁为加瑞克的头颅支付赏金？",a="驻扎在北郡修道院入口外的维里副队长发布了悬赏，并在收到头颅后支付报酬。",al={"谁想要加瑞克的头","上交加瑞克的头","谁上交了加瑞克的头"}}},fp="14,153,14.393.0,24.197.0,51.103.0,33.116.0,39.134.0"}
P.entries["item:gazlowe-s-ledger"] = {n="加兹鲁维的账本",s="加兹鲁维的账本是棘齿城地精大工头保存的一份关于贸易货物和库存的详细记录。它被用作核对从藏宝海湾运抵的货物与港口清单是否相符的会计账簿。",h="加兹鲁维的账本是棘齿城地精大工头保存的一份关于贸易货物和库存的详细记录。它被用作核对从藏宝海湾运抵的货物与港口清单是否相符的会计账簿。",kw={"藏宝海湾","迪兹维格","海盗","加兹鲁维","账本","棘齿城","货运","热砂财团"},ang={["class:Rogue"]="一位地精大工头的私人贸易账本为了解贫瘠之地沿岸的违禁品流动、贵重进口货物和海盗活动提供了一个有趣的视角。",["faction:Horde"]="棘齿城作为一个欢迎部落贸易的中立港口运营；帮助加兹鲁维追踪被盗货物可以与当地的热砂财团当局保持良好的关系。"},sec={{t="棘齿城的商业记录",b="管理像棘齿城这样繁忙的贸易港口需要一丝不苟的会计工作。加兹鲁维维护着这本私人账本，用来追踪进口板条箱、外运货物和仓库储备。当从藏宝海湾运来的货物久候不至时，加兹鲁维就会利用这本账本来核对他的预计库存与码头管理员迪兹维格在码头上保存的海运记录。"},{t="揭开盗窃之谜",b="通过将账本条目与迪兹维格的港口日志直接进行对比，地精们确认货物从未抵达港口仓库。这一差异证实了加兹鲁维的怀疑，即失踪的货物在海上就遭到了劫掠，矛头直接指向了在附近商旅海岸活动的南海海盗。"}},faq={{q="什么是加兹鲁维的账本？",a="这是加兹鲁维的个人库存账本，记录了在棘齿城预期收到和储存的货物。当有进港货物失踪时，加兹鲁维会将其送到码头，以便与码头记录进行核对。",al={"加兹鲁维的账本","棘齿城账本","加兹鲁维库存账簿"}},{q="谁需要查阅这本账本？",a="负责监督棘齿城码头的码头管理员迪兹维格会对照他的航运日志审查这本账本，以确定丢失的货物是被错放了还是从未卸货。",al={"我该把账本交给谁","账本接收人","迪兹维格账本"}},{q="账本中记录了什么货物失踪了？",a="加兹鲁维一直在等待他最后一批来自藏宝海湾的货物。迪兹维格在他的日志中没有发现任何异常，尽管他提到有一些来自安德麦的货物正等着加兹鲁维去领取。",al={"加兹鲁维丢失了什么","失踪的货运货物"}},{q="账本查阅后会发生什么？",a="一旦迪兹维格核实了货物从未通过码头，账本就会被归还给加兹鲁维，这证实了南海海盗很可能在海上拦截了这批货物。",al={"账本会怎么样","迪兹维格检查之后"}}},fx={d44950a4={q="加兹鲁维的账本从何而来？由谁保管？",a="这本账本属于加兹鲁维，他是棘齿城港口的地精头目。账本记录了他的个人货物清单，记载着棘齿城与藏宝海湾等其他地精贸易据点之间经由无尽之海运送的进出货物。",al={"谁制作了加兹鲁维的账本","加兹鲁维的账本从何而来","加兹鲁维账本的来源"}},c4547cde={q="为什么现在需要加兹鲁维的账本？",a="加兹鲁维怀疑一批迟迟未到的货物在藏宝海湾遭到了南海海盗的劫掠。在妄下结论之前，他需要你把账本送到码头上的码头管理员迪兹维格那里，让他将货物记录与港口日志进行核对，排除文书错误的可能。",al={"为什么要加兹鲁维的账本","为什么需要加兹鲁维的账本","加兹鲁维的账本有什么用"}}},fp="16,220,28.388.0,20.351.1,25.199.0,32.175.0,37.186.0,41.188.1"}
P.entries["item:gem-of-anacondra"] = {n="安娜科德拉宝石",s="安娜科德拉宝石是哀嚎洞穴内被腐化的蛇人首领所持有的四颗梦境宝石之一。它由安娜科德拉携带，作为她被击败以及梦魇在贫瘠之地蔓延受到遏制的切实证明。",h="安娜科德拉宝石是哀嚎洞穴内被腐化的蛇人首领所持有的四颗梦境宝石之一。它由安娜科德拉携带，作为她被击败以及梦魇在贫瘠之地蔓延受到遏制的切实证明。",kw={"梦境宝石","尖牙德鲁伊","安娜科德拉宝石","安娜科德拉","尖牙德鲁伊首领","纳拉·蛮鬃","哀嚎洞穴"},ang={["class:Druid"]="对于塞纳里奥德鲁伊来说，夺回这颗宝石是一项庄严的职责，旨在击倒一位向腐化的翡翠梦魇屈服了思想和形体的姐妹。",["race:Tauren"]="回收这颗宝石直接帮助了雷霆崖的纳拉·蛮鬃，消除了困扰长者高地舒哈鲁睡眠的黑暗幻象。"},sec={{t="腐化的焦点",b="当纳拉雷克斯陷入沉睡，试图为干旱的贫瘠之地带回水源与生命时，翡翠梦魇侵入了他的思想，扭曲了他最亲近的弟子。安娜科德拉和她的同谋者们抛弃了传统的道路，成为了尖牙德鲁伊，将他们崇高的恢复使命扭曲成了剧毒的幻觉。安娜科德拉宝石是这些蛇人首领所持有的四颗梦境宝石之一，它们汇聚了他们与翡翠梦境之间被腐化的联系，并将梦魇锚定在这个洞穴系统中。"},{t="清除幻象",b="纳拉·蛮鬃和雷霆崖的塞纳里奥德鲁伊圈发现，他们自己的睡眠也被尖牙德鲁伊首领们的幻象和邪恶面容所困扰。夺回安娜科德拉宝石——以及考布莱恩、皮萨斯和瑟芬迪斯的宝石——对于证实安娜科德拉已被击倒至关重要，这将使卡利姆多的平衡守护者们从沉重的梦魇中解脱出来。"}},faq={{q="安娜科德拉宝石是什么？",a="这是一颗由安娜科德拉携带的梦境宝石，她是居住在哀嚎洞穴内的扭曲的尖牙德鲁伊的四位首领之一。",al={"安娜科德拉宝石是什么","安娜科德拉宝石","安娜科德拉宝石有什么用"}},{q="谁需要这颗宝石？",a="位于雷霆崖长者高地的牛头人德鲁伊纳拉·蛮鬃，正在寻找这颗宝石以及其他三颗梦境宝石，以使她的思想从梦魇中解脱，并保护贫瘠之地。",al={"谁需要安娜科德拉宝石","在哪里上交安娜科德拉宝石","安娜科德拉宝石上交"}},{q="在哪里可以找到安娜科德拉宝石？",a="这颗宝石由安娜科德拉携带，她潜伏在贫瘠之地中部哀嚎洞穴蜿蜒的地下隧道中。",al={"哪里掉落","谁掉落安娜科德拉宝石","安娜科德拉位置"}},{q="为什么梦境宝石很重要？",a="这四颗宝石由尖牙德鲁伊的腐化首领持有。收集它们可以确认这些首领已被消灭，从而打破他们对该地区翡翠梦境腐化的控制。",al={"为什么有四颗宝石","梦境宝石的用途","尖牙德鲁伊首领的宝石"}}},fx={["2e0de493"]={q="安娜科德拉宝石来自哪里？是谁制作的？",a="安娜科德拉在哀嚎洞穴深处携带着这颗宝石。虽然不知道具体是哪位大师切割或附魔了它，但它是尖牙德鲁伊四位首领持有的梦境宝石之一。这些堕落的暗夜精灵曾属于一个致力于治愈贫瘠之地的高贵团体，如今却将他们对翡翠梦境的扭曲幻象注入这些石头。",al={"安娜科德拉宝石的来历","谁制作了安娜科德拉宝石","安娜科德拉从哪里得到宝石"}}},fp="16,241,17.531.0,20.388.1,29.139.0,19.183.0,40.149.0,33.205.0"}
P.entries["item:gem-of-cobrahn"] = {n="考布莱恩宝石",s="考布莱恩宝石是考布莱恩领主携带的一颗梦境宝石，他是哀嚎洞穴中尖牙德鲁伊的堕落领袖之一。它既是他受腐化梦境的焦点，也是纳拉·野鬃确认他已被击败所需的实物证明。",h="考布莱恩宝石是考布莱恩领主携带的一颗梦境宝石，他是哀嚎洞穴中尖牙德鲁伊的堕落领袖之一。它既是他受腐化梦境的焦点，也是纳拉·野鬃确认他已被击败所需的实物证明。",kw={"梦境宝石","尖牙德鲁伊","考布莱恩宝石","尖牙领袖","考布莱恩","纳拉·野鬃","哀嚎洞穴"},ang={["class:Druid"]="对于塞纳里奥德鲁伊来说，收回考布莱恩宝石标志着一位背弃自然和谐、投身翡翠梦魇的堕落兄弟的悲剧性但必要的终结。",["race:Tauren"]="雷霆崖的德鲁伊们密切注视着贫瘠之地；夺取考布莱恩的宝石直接保护了平原和狩猎场免受非自然腐化的侵袭。"},sec={{t="腐化梦境的焦点",b="当暗夜精灵德鲁伊纳拉雷克斯进入翡翠梦境试图恢复卡利姆多贫瘠的平原时，他的梦魇扭曲了哀嚎洞穴和他的弟子们。其中就包括考布莱恩，他放弃了塞纳里奥议会的和平之道，转而化身为蛇。考布莱恩领主携带着四颗梦境宝石之一，这些宝石巩固了这些领袖对地下水道的控制，他利用宝石引导扭曲的梦境，威胁要将贫瘠之地变成一片毒沼。"},{t="恢复平衡",b="在雷霆崖，牛头人德鲁伊纳拉·野鬃一直被尖牙德鲁伊叛徒所散发的梦魇所折磨。为了净化地下泉水并保护卡利姆多免受他们的幻象侵蚀，冒险者必须深入洞穴，杀死考布莱恩领主和他的三名同谋，并夺回他们的梦境宝石。将考布莱恩的宝石归还给塞纳里奥德鲁伊，可以终结他对沉睡中的纳拉雷克斯的腐化影响。"}},faq={{q="什么是考布莱恩宝石？",a="这是一颗由考布莱恩领主持有的梦境宝石，他是一位堕落的德鲁伊，领导着哀嚎洞穴内的尖牙德鲁伊。它充当了他被梦魇扭曲的力量的导管。",al={"考布莱恩宝石","什么是考布莱恩宝石"}},{q="谁想要考布莱恩宝石？",a="位于雷霆崖长者高地的牛头人德鲁伊纳拉·野鬃，索要这颗宝石以及另外三颗宝石，以终结尖牙德鲁伊的威胁。",al={"谁需要考布莱恩宝石","考布莱恩宝石上交","谁拿走考布莱恩宝石"}},{q="完成任务需要多少颗宝石？",a="需要四颗宝石：考布莱恩宝石、安娜科德拉宝石、皮萨斯宝石和瑟芬迪斯宝石，每一颗都由洞穴中的四位蛇形领袖之一持有。",al={"多少颗梦境宝石","尖牙德鲁伊领袖宝石","所有尖牙宝石"}},{q="考布莱恩领主是谁？",a="考布莱恩领主曾是纳拉雷克斯的弟子。当纳拉雷克斯的幻象变为梦魇时，考布莱恩和其他几位德鲁伊拥抱了蛇的形态，组成了尖牙德鲁伊。",al={"考布莱恩是谁","考布莱恩领主背景故事","考布莱恩"}}},fp="14,256,27.491.0,17.430.1,27.170.0,29.155.0,47.171.0,20.192.0"}
P.entries["item:gem-of-pythas"] = {n="皮萨斯宝石",s="皮萨斯宝石是哀嚎洞穴中尖牙德鲁伊领袖们所持有的四块受腐蚀的梦境宝石之一。它由考布莱恩持有，为扭曲这座地下绿洲并威胁贫瘠之地的梦魇提供了能量。",h="皮萨斯宝石是哀嚎洞穴中尖牙德鲁伊领袖们所持有的四块受腐蚀的梦境宝石之一。它由考布莱恩持有，为扭曲这座地下绿洲并威胁贫瘠之地的梦魇提供了能量。",kw={"贫瘠之地","梦境宝石","尖牙德鲁伊","皮萨斯宝石","皮萨斯","纳拉·野鬃","哀嚎洞穴"},ang={["class:Druid"]="对于塞纳里奥德鲁伊来说，回收这块宝石是一项沉重的职责，因为它象征着纳拉雷克斯的核心圈子彻底堕落成了蛇人般的怪物。",["race:Tauren"]="洞穴中扭曲的仪式威胁着贫瘠之地脆弱的平衡，因此回收这些宝石对于保护萨满和德鲁伊们的家园至关重要。"},sec={{t="梦魇的容器",b="当纳拉雷克斯进入翡翠梦境试图恢复贫瘠之地的生态时，他崇高的愿景被扭曲成了活生生的梦魇。他最亲信的追随者们随他一同堕落，自称为尖牙德鲁伊，试图将地表世界改造成一片剧毒丛林。皮萨斯携带着这块共鸣之石，它是锚定洞穴内腐蚀的四块梦境宝石之一。这块宝石既是他们邪恶计划的导管，也是证明皮萨斯那扭曲的幻梦终于被打破，足以向雷霆崖的德鲁伊们交差的凭证。"}},faq={{q="皮萨斯宝石有什么用？",a="这块宝石需要与考布莱恩、安娜科德拉和瑟芬迪斯的宝石一起带给雷霆崖的纳拉·野鬃。集齐它们，就完成了终结尖牙德鲁伊这些堕落领袖的任务。",al={"皮萨斯宝石用途","皮萨斯宝石做什么","皮萨斯宝石任务"}},{q="谁携带着这块宝石？",a="它由皮萨斯持有，这名堕落的暗夜精灵德鲁伊居住在贫瘠之地的哀嚎洞穴深处。",al={"谁掉落皮萨斯宝石","皮萨斯位置","在哪里获得皮萨斯宝石"}},{q="为什么雷霆崖的德鲁伊想要这块宝石？",a="纳拉·野鬃和雷霆崖的塞纳里奥德鲁伊们一直被哀嚎洞穴中散发出的腐蚀气息所困扰。获取这些宝石证明了四名反常的领袖已被击败，从而阻止了梦魇进一步蔓延至贫瘠之地。",al={"为什么纳拉需要宝石","纳拉·野鬃 皮萨斯"}},{q="还有其他像这样的宝石吗？",a="是的。皮萨斯是四名领袖之一。其他人——安娜科德拉、考布莱恩和瑟芬迪斯——每个人都在洞穴深处携带着属于自己的梦境宝石。",al={"其他梦境宝石","尖牙宝石","哀嚎洞穴宝石"}}},fx={["3d8d64d3"]={q="皮萨斯宝石是什么？",a="皮萨斯宝石是哀嚎洞穴中尖牙德鲁伊首领携带的四颗梦境宝石之一。这件遗物由皮萨斯领主持有，承载着腐化这些昔日高贵暗夜精灵的黑暗蛇形疯狂，将他们对翡翠梦境的扭曲幻象凝为实体。",al={"皮萨斯宝石","皮萨斯宝石是什么","这是什么宝石"}}},fp="13,235,25.518.0,35.209.0,21.111.0,48.259.0,35.159.0"}
P.entries["item:gem-of-serpentis"] = {n="瑟芬迪斯宝石",s="瑟芬迪斯宝石是由哀嚎洞穴中尖牙德鲁伊的四位首领之一，瑟芬迪斯所携带的一颗梦境宝石。它是重塑洞穴网络并威胁着贫瘠之地的扭曲梦魇的焦点媒介。",h="瑟芬迪斯宝石是由哀嚎洞穴中尖牙德鲁伊的四位首领之一，瑟芬迪斯所携带的一颗梦境宝石。它是重塑洞穴网络并威胁着贫瘠之地的扭曲梦魇的焦点媒介。",kw={"尖牙德鲁伊","瑟芬迪斯宝石","尖牙德鲁伊首领","瑟芬迪斯","纳拉·蛮鬃","贫瘠之地","哀嚎洞穴"},ang={["class:Druid"]="瑟芬迪斯和他的团伙所携带的梦境宝石，代表了在没有警惕的精神约束下与梦境进行深度恍惚交流所带来的可怕风险。",["race:Tauren"]="切断瑟芬迪斯对这颗宝石的控制，有助于将雷霆崖的萨满祭司和德鲁伊从扰乱他们莫高雷睡眠的黑暗幻象中解救出来。"},sec={{t="蛇形梦境之心",b="当纳拉雷克斯在哀嚎洞穴中的沉睡被翡翠梦魇吞噬时，他最忠诚的追随者们被扭曲成了狂热的尖牙德鲁伊。瑟芬迪斯是这伙人的四位首领之一。和其他三人一样，瑟芬迪斯携带一颗附魔的梦境宝石，将他们的集体意志锚定在这扭曲的幻象上。回收这颗宝石可以打破瑟芬迪斯对洞穴生态系统的控制，直接打击那些指挥着在贫瘠之地蔓延的腐化的首领。"},{t="雷霆崖的证明",b="雷霆崖长者高地上的牛头人德鲁伊，特别是纳拉·蛮鬃，饱受潜伏在草原之下的腐化所引起的梦魇的折磨。回收瑟芬迪斯宝石，以及考布拉恩、安娜科德拉和皮萨斯的宝石，提供了确凿的证据，证明这个堕落教派的首领们已经倒下，从而减轻了梦魇对莫高雷的塞纳里奥议会的控制。"}},faq={{q="瑟芬迪斯宝石从哪里来？",a="这颗宝石由瑟芬迪斯携带，他是尖牙德鲁伊的四位首领之一，居住在哀嚎洞穴蜿蜒的水道深处。",al={"瑟芬迪斯宝石掉落者","如何获得瑟芬迪斯宝石","瑟芬迪斯宝石位置"}},{q="这颗宝石有什么用途？",a="它是尖牙德鲁伊的首领们用来引导扭曲地下绿洲的梦魇的四颗焦点宝石之一。雷霆崖的纳拉·蛮鬃寻找它作为瑟芬迪斯已被击败的证明。",al={"为什么要收集瑟芬迪斯宝石","瑟芬迪斯宝石用途"}},{q="谁需要全部四颗梦境宝石？",a="驻扎在雷霆崖长者高地的德鲁伊纳拉·蛮鬃，请求冒险者为她带回考布拉恩、安娜科德拉、皮萨斯和瑟芬迪斯的宝石，以切断梦魇对该地区的控制。",al={"谁需要这些宝石","瑟芬迪斯宝石任务提交","尖牙德鲁伊首领任务提交"}},{q="携带这颗宝石之前的瑟芬迪斯是谁？",a="他最初是纳拉雷克斯的学徒，进入洞穴的目的是为了让贫瘠之地恢复生机，但翡翠梦魇将他崇高的抱负扭曲成了以蛇的形态重塑世界的狂热渴望。",al={"瑟芬迪斯背景故事","瑟芬迪斯是谁"}}},fx={["58ca37b7"]={q="瑟芬迪斯宝石是什么？",a="瑟芬迪斯宝石是哀嚎洞穴中尖牙德鲁伊首领持有的四颗梦境宝石之一。它由瑟芬迪斯领主亲自携带，是堕落德鲁伊的象征与工具；他们妄图将贫瘠之地扭曲成符合其黑暗幻象的模样。",al={"瑟芬迪斯宝石背景","瑟芬迪斯的宝石是什么","瑟芬迪斯领主的宝石"}}},fp="16,245,29.501.0,23.375.1,42.158.0,31.226.0,30.199.0,48.227.0"}
P.entries["item:gerenzo-s-mechanical-arm"] = {n="格雷苏的机械臂",s="格雷苏的机械臂是从石爪山脉的流亡工程师格雷苏·扳手哨手中切下的假肢。对于那些想要清除竞争对手的地精特工来说，这是他死亡的确凿证据。",h="格雷苏的机械臂是从石爪山脉的流亡工程师格雷苏·扳手哨手中切下的假肢。对于那些想要清除竞争对手的地精特工来说，这是他死亡的确凿证据。",kw={"手臂","峭壁湖","格雷苏","机械臂","斯布特瓦夫","石爪山脉","扳手哨手","吉兹·菲兹克斯"},ang={["profession:Engineering"]="这只手臂展示了两种工程传统截然不同的思维方式：侏儒甘愿为了机械精度而牺牲自己的生物构造，而地精则更倾向于外部增益和粗暴的火力。",["race:Gnome"]="格雷苏代表了侏儒创造力中残酷的一面，他将机械替换远远超越了常规医疗假肢的范畴，走向了病态的自我增殖。"},sec={{t="古怪的发明",b="格雷苏·扳手哨手将自我改造推向了怪诞的极端，他将嗡嗡作响的齿轮和金属直接移植到自己衰竭的身体上。这位流亡的侏儒盘踞在峭壁湖上方，用复杂的机械装置取代了原本的肢体。当地精技师吉兹·菲兹克斯为了给上级留下深刻印象而寻求除掉格雷苏时，这只独特的机械臂成为了唯一足以作为工程师死亡铁证的战利品。"},{t="侏儒哲学，地精批判",b="在地精看来，切掉一只功能完好的手臂仅仅为了换上机械假肢是毫无意义的。吉兹·菲兹克斯曾发表名言称，一个合格的地精工程师应该保留双臂，然后在身上加装第三只机械手臂。尽管存在哲学分歧，但上交这只断臂还是满足了斯布特瓦夫的要求，并帮助吉兹争取到了前往加基森或永恒之井工作的机会。"}},faq={{q="格雷苏的机械臂从哪里获得？",a="它是从格雷苏·扳手哨手身上取下的，此人一直在石爪山脉峭壁湖上方水车附近监督伐木和工程作业。",al={"谁掉落格雷苏的手臂","格雷苏的手臂位置","哪里获得格雷苏的机械臂"}},{q="为什么吉兹·菲兹克斯想要这只手臂？",a="吉兹需要向他的上级斯布特瓦夫提供格雷苏已死的铁证。由于格雷苏对自己进行了大量的身体改造，他那独特的假肢是无法伪造或混淆的。",al={"为什么吉兹想要手臂","手臂任务提交","格雷苏死亡证明"}},{q="为什么格雷苏要替换自己的手臂？",a="根据吉兹·菲兹克斯的说法，格雷苏的血肉似乎正在腐烂。出于绝望或对侏儒实验的痴迷，格雷苏移植了机械装置，用机械部件替换了他衰竭的肢体。",al={"为什么格雷苏是半机械人","格雷苏腐烂的血肉","为什么是机械手臂"}}},fx={["379afa91"]={q="格雷苏的机械臂是什么？",a="这是一条粗糙的赛博义肢，直接移植在格雷苏·扳哨的身上。他是一个患病的侏儒监工，潜伏在峭壁湖上方的水车附近。格雷苏没有保留自然血肉，而是用发条齿轮和金属护板改造了腐烂的躯体，这条精巧的机械肢体也因此成为他最显眼的特征。",al={"格雷苏的手臂是什么","格雷苏的手臂物品","格雷苏的机械臂"}}},fp="24,238,19.444.0,35.412.1,46.162.0,35.205.0,36.217.0"}
P.entries["item:ghost-hair-comb"] = {n="幽灵的梳子",s="幽灵的梳子是一件缠绕着盲眼玛丽灵魂幽灵发丝的诡异梳理工具。这把梳子由伊瓦夫人送给这位幽灵，它成为了一件令人悲剧性觉醒的工具，梳齿上缠绕的头发随后会被纺成不可思议的幽灵的发丝。",h="幽灵的梳子是一件缠绕着盲眼玛丽灵魂幽灵发丝的诡异梳理工具。这把梳子由伊瓦夫人送给这位幽灵，它成为了一件令人悲剧性觉醒的工具，梳齿上缠绕的头发随后会被纺成不可思议的幽灵的发丝。",kw={"盲眼玛丽","夜色镇","暮色森林","幽灵的梳子","幽灵的发丝","伊瓦夫人"},ang={["class:Priest"]="玛丽对这把梳子的痛苦反应反映了暮色森林中那些不安的亡者所共有的残留的凡人虚荣和深重的灵魂折磨。",["profession:Tailoring"]="从梳子上取下的空灵发丝代表了一种不可思议的纺织材料，它并非采自绵羊或蚕，而是直接从幽灵的悲伤中纺就而成。"},sec={{t="悲剧性的虚荣",b="夜色镇的伊瓦夫人将这把梳子送给了居住在暮色森林边缘一处孤寂破败住所中的缠绕之灵盲眼玛丽。当这把梳子被递到玛丽面前时，这位幽灵因极度的恐惧而退缩，突然面对了一个残酷的现实：她早已不再是生前那位美丽的女子。在悲伤与痛苦中，玛丽推开了梳子，上面留下了几缕她自己的幽灵发丝。"},{t="悲伤纺就",b="梳子被送回夜色镇的伊瓦夫人手中，梳齿间勾住的头发有着更为神秘的用途。伊瓦夫人收集这些精致的幽灵纤维，将它们纺成幽灵的发丝，这是一种神秘的制作材料，用于缝合和束缚暮色森林阴影领域中的神秘造物。"}},faq={{q="什么是幽灵的梳子？",a="这是一把由夜色镇的伊瓦夫人送给盲眼玛丽灵魂的梳子。在玛丽使用或将其抛弃后，上面会缠绕着她幽灵发丝，伊瓦夫人随后会将这些发丝纺成幽灵的发丝。",al={"幽灵的梳子","这把梳子是什么","伊瓦夫人的梳子"}},{q="为什么盲眼玛丽会尖叫并拒绝这把梳子？",a="这把梳子让盲眼玛丽想起了她失去的凡人美貌。接过梳子迫使她面对自己是一个可怕的幽灵怪物的事实，而不是她记忆中生前那位可爱的女性。",al={"为什么盲眼玛丽会尖叫","盲眼玛丽对梳子的反应","为什么玛丽扔掉梳子"}},{q="谁需要归还这把梳子？",a="居住在夜色镇的占卜师和女巫伊瓦夫人要求将这把梳子带回给她，以便她能收集上面残留的幽灵发丝。",al={"谁想要这把梳子","要把梳子带去哪里","把梳子还给谁"}},{q="幽灵的发丝有什么用途？",a="伊瓦夫人将从梳子上收集到的幽灵发丝纺成幽灵的发丝，这是一种在暮色森林进行神秘仪式和制作所需的特殊试剂。",al={"幽灵发丝的用途","什么是幽灵的发丝","幽灵的发丝的作用"}}},fp="15,247,15.431.0,16.300.1,28.194.0,47.202.0,28.167.0,32.157.0"}
P.entries["item:ghost-hair-thread"] = {n="幽灵的发丝",s="幽灵的发丝是一种稀有的超自然材料，由夜色镇的伊瓦夫人纺制而成。它被注入了强大的神秘力量，据说能束缚灵魂能量，甚至能将生命缝入无生命的物体中。隐士亚伯克隆比请求获得它，用以保护他那破旧的小屋免受不安的亡灵侵扰。",h="幽灵的发丝是一种稀有的超自然材料，由夜色镇的伊瓦夫人纺制而成。它被注入了强大的神秘力量，据说能束缚灵魂能量，甚至能将生命缝入无生命的物体中。隐士亚伯克隆比请求获得它，用以保护他那破旧的小屋免受不安的亡灵侵扰。",kw={"亚伯克隆比","夜色镇","暮色森林","幽灵的发丝","伊瓦夫人","乌鸦岭","灵魂"},ang={["class:Warlock"]="这种丝线束缚灵体和赋予无生命物质生命的能力，反映了灵魂操纵和构装体束缚的黑暗艺术。",["profession:Tailoring"]="虽然普通的裁缝使用羊毛、丝绸和魔纹布，但伊瓦夫人的幽灵丝线证明了织物可以直接由超自然精华纺制而成，从而承载附魔。"},sec={{t="来自灵界的纺织物",b="幽灵的发丝由夜色镇的占卜师伊瓦夫人纺制，它远非普通的裁缝用品。据伊瓦夫人所说，这种幽灵丝线具有多种神秘属性，从束缚邪恶灵魂到将生命缝入无生命物体，无所不能。其空灵的本质使其成为在充满诅咒的暮色森林中进行仪式和防御的宝贵材料。"},{t="亚伯克隆比的防御",b="隐居在乌鸦岭墓地以北一间破旧小屋里的隐士亚伯克隆比，请求旅行者从夜色镇取回这种丝线。他声称自己急需将丝线缠绕在窗户和门框上，以防止墓地中游荡的亡灵闯入家中。然而，考虑到这种丝线将生命缝入无生命物质的奇特能力，它最终的用途仍然是一个令人不安的谜团。"}},faq={{q="什么是幽灵的发丝？",a="这是一种由夜色镇的伊瓦夫人纺制的奥术制作材料。它拥有独特的神秘属性，能够束缚灵魂或将生命缝入无生命的物体中。",al={"幽灵的发丝","什么是幽灵的发丝","幽灵丝线"}},{q="为什么亚伯克隆比需要幽灵的发丝？",a="亚伯克隆比声称他需要这种丝线来布置他的窗户和门口，以此建立一道防御屏障，抵御乌鸦岭墓地附近徘徊的不安灵魂。",al={"亚伯克隆比的丝线","亚伯克隆比为何需要丝线","亚伯克隆比的防御"}},{q="谁制造了这种丝线？",a="夜色镇的常驻占卜师伊瓦夫人负责制造，并根据要求提供这种丝线。",al={"谁纺制幽灵的发丝","伊瓦夫人的丝线"}},{q="玩家可以用这种丝线进行裁缝制作吗？",a="不能。尽管它名字听起来像裁缝材料且具有魔法特性，但这是一种专门的任务物品，仅供交给亚伯克隆比使用，不能用于标准的制作配方。",al={"幽灵的发丝裁缝","我可以用幽灵的发丝进行制作吗"}}},fp="17,291,24.380.0,18.431.1,26.167.0,44.178.0,21.110.0,41.166.0"}
P.entries["item:ghoul-fang"] = {n="食尸鬼的牙齿",s="食尸鬼的牙齿是收集自徘徊在暮色森林荒芜林地和墓地中的不死生物的可怖战利品。在夜色镇，伊瓦夫人将它们视为制作防御护身符的关键材料，以帮助旅行者抵御日益逼近的黑暗。",h="食尸鬼的牙齿是收集自徘徊在暮色森林荒芜林地和墓地中的不死生物的可怖战利品。在夜色镇，伊瓦夫人将它们视为制作防御护身符的关键材料，以帮助旅行者抵御日益逼近的黑暗。",kw={"夜色镇","暮色森林","食尸鬼的牙齿","食尸鬼","伊瓦夫人","惩罚图腾","不死生物"},ang={["faction:Alliance"]="对于协助受困的夜色镇的联盟冒险者来说，收集这些牙齿有助于将暮色森林的恐怖力量转化为对抗日益蔓延的类似天灾军团的污染的生存工具。"},sec={{t="The Restless Dead 的战利品",b="暮色森林那阴暗的林地里爬满了贪婪的不死生物，从潜伏在坟墓附近的食尸鬼到游荡在树林里的腐烂尸体，应有尽有。从这些怪物身上取下牙齿既是一项残酷的工作，也是在面对威胁夜色镇边界的贪婪死者时幸存下来的证明。"},{t="奥术试剂",b="伊瓦夫人是居住在夜色镇的占卜师和神秘学家，她能预见那些敢于踏入暮色森林的旅行者周围萦绕着可怕的预兆。她将食尸鬼的牙齿中潜藏的死灵精华，与骷髅手指和蛛毒结合起来，以此为惩罚图腾附魔，将森林中的黑暗力量转化为抵御暴力袭击的护身符。"}},faq={{q="在哪里可以找到食尸鬼的牙齿？",a="它们是从遍布暮色森林的各类食尸鬼身上收集的，包括出没于墓地和偏僻小径的瘟疫传播者、食脑者、噬骨者、恶臭尸体、腐烂者和食肉者。",al={"食尸鬼的牙齿掉落位置","哪些怪物掉落食尸鬼的牙齿","食尸鬼的牙齿获取地点"}},{q="谁需要食尸鬼的牙齿？",a="居住在夜色镇的神秘学家伊瓦夫人需要这些材料，作为制作名为惩罚图腾的防御护身符的仪式的一部分。",al={"谁需要食尸鬼的牙齿","食尸鬼的牙齿任务提交","伊瓦夫人任务"}},{q="为什么伊瓦夫人需要它们？",a="伊瓦夫人感觉到旅行者面临着迫在眉睫的危险，因此她利用这些牙齿，配合骷髅手指和蛛毒来为一种防御图腾附魔，以惩罚那些攻击持有者的人。",al={"为什么需要食尸鬼的牙齿","惩罚图腾制作材料","伊瓦夫人用牙齿做什么"}}},fx={["7c703fef"]={q="食尸鬼的牙齿是什么？",a="食尸鬼的牙齿是从暮色森林中徘徊的不死食尸鬼口中撬下的尖牙。这些牙齿受到死灵腐化和噬肉欲望的污染，仍残留着一丝驱动不死生物的黑暗魔法，因此是制作护身符和进行神秘仪式的强力材料。",al={"食尸鬼的牙齿是什么","食尸鬼的牙齿背景","关于食尸鬼的牙齿"}},["87f3f6fc"]={q="食尸鬼的牙齿来自哪里？",a="这些牙齿来自暮色森林阴影中游荡的各种不死食尸鬼，例如瘟疫散播者、食脑者、啃骨者和食肉者。它们并非人工制作，而是直接从游荡死者的口中搜集而来。",al={"食尸鬼的牙齿来源","食尸鬼的牙齿来自哪里","谁会掉落食尸鬼的牙齿"}}},fp="10,263,29.285.0,15.364.0,31.211.0,22.140.0,30.175.0"}
P.entries["item:ghoul-rib"] = {n="食尸鬼的肋骨",s="食尸鬼的肋骨是从潜伏在暮色森林闹鬼的树丛和墓地中的亡灵身上收集而来的。隐士亚伯克隆比声称需要这些材料来建造一个怪诞的塑像，以抵御他小屋附近那些嗜肉的恐怖生物。",h="食尸鬼的肋骨是从潜伏在暮色森林闹鬼的树丛和墓地中的亡灵身上收集而来的。隐士亚伯克隆比声称需要这些材料来建造一个怪诞的塑像，以抵御他小屋附近那些嗜肉的恐怖生物。",kw={"亚伯克隆比","乞丐鬼屋","噬骨者","夜色镇","暮色森林","嗜肉食尸鬼","食尸鬼的肋骨","食尸鬼塑像","亡灵"},ang={["class:Paladin"]="处理不安亡灵被亵渎的骨头是令人厌恶的工作，但帮助一个与世隔绝的隐士对抗贪婪的怪物，符合保护生者免受暮色森林恐怖威胁的职责。",["class:Priest"]="将这些骨头束缚在一起的扭曲复生，反映了笼罩在暮色森林之上的深沉阴影，它将倒下的村民变成了贪婪的食腐者。"},sec={{t="一个可怕的护身符",b="被诅咒的暮色森林里爬满了凶残的亡灵，包括嗜肉食尸鬼、噬骨者、食脑者、腐烂者和瘟疫传播者等贪婪的食尸鬼。亚伯克隆比，一个住在乌鸦岭墓地北侧小屋里的古怪隐士，向路过的旅行者索要这些坚固但已腐烂的骨头。他声称居住在夜色镇守夜人的保护范围之外让他感到脆弱，而用食尸鬼的肋骨组装一个恐怖的塑像，可以充当稻草人吓跑那些游荡的亡灵。"},{t="对小屋的怀疑",b="虽然在敌对地区收集被杀亡灵的身体部位以求生存是很常见的事，但亚伯克隆比对食尸鬼解剖结构的特殊迷恋引起了人们的侧目。这位隐士并没有寻求夜色镇栅栏后的庇护，也没有依赖神圣的守卫，反而坚持收集原始的死灵废料来加固他那与世隔绝的家。"}},faq={{q="哪些生物携带食尸鬼的肋骨？",a="它们可以从暮色森林各处的各类食尸鬼身上收集到，包括嗜肉食尸鬼、噬骨者、食脑者、腐烂者和瘟疫传播者。这些怪物出没于整个森林的老墓地、路边废墟和废弃的家园中。",al={"食尸鬼的肋骨在哪里掉落","哪些食尸鬼有肋骨","食尸鬼的肋骨来源"}},{q="亚伯克隆比为什么要这些骨头？",a="亚伯克隆比声称他住得离夜色镇太远，无法依靠守夜人来保护。他要求提供这些肋骨是为了建造一个简陋的稻草人或塑像，以阻止游荡的亡灵撞击他的墙壁。",al={"为什么亚伯克隆比需要肋骨","食尸鬼塑像的用途","亚伯克隆比用肋骨做什么"}},{q="稻草人真的能吓走食尸鬼吗？",a="亡灵通常没有恐惧感，完全受无意识的饥饿或黑暗死灵驱使。认为无意识的食尸鬼会因为一个用骨头做的稻草人而逃跑的想法很不寻常，但亚伯克隆比坚持认为这能保证他家的安全。",al={"这个塑像有用吗","塑像能吓跑亡灵吗","食尸鬼怕稻草人吗"}},{q="亚伯克隆比的小屋在哪里？",a="亚伯克隆比住在暮色森林西部的一间破烂小屋里，就在乌鸦岭墓地的北面。",al={"亚伯克隆比的位置","隐士在哪里","去哪里上交食尸鬼的肋骨"}}},fx={["3e8ffb18"]={q="食尸鬼的肋骨是什么？",a="食尸鬼的肋骨顾名思义，就是从在暮色森林游荡的腐烂复生不死生物身上取下的骨头。这些残骸取自食肉者、食脑者和啃骨者等恶魔般的怪物，仍带有一丝污秽魔法的气息；正是这种魔法驱动着这片受诅森林中的行尸走肉。",al={"食尸鬼的肋骨信息","食尸鬼的肋骨是什么","食尸鬼的肋骨物品"}},f2829c95={q="食尸鬼的肋骨来自哪里？",a="这些肋骨直接来自出没于暮色森林阴暗道路和古墓中的各种食尸鬼。它们是天然的骸骨，而非制作而成的遗物，取自瘟疫散播者和腐烂者等不死怪物；这些怪物游荡在远离夜色镇相对安全地带的地方。",al={"食尸鬼的肋骨来源","食尸鬼的肋骨背景及获取地点","谁制作了食尸鬼的肋骨"}}},fp="9,237,15.545.0,27.334.1,32.255.0,38.206.0,40.237.0,37.95.0"}
P.entries["item:giant-crocolisk-skin"] = {n="巨型鳄鱼的皮",s="巨型鳄鱼的皮是取自湿地沼泽原生巨型爬行动物的厚重兽皮。由于这种皮深受米奈希尔港商人的青睐，被用于制皮工艺，因此采集它们是一项危险的工作，已经导致多名粗心大意的猎人受伤致残。",h="巨型鳄鱼的皮是取自湿地沼泽原生巨型爬行动物的厚重兽皮。由于这种皮深受米奈希尔港商人的青睐，被用于制皮工艺，因此采集它们是一项危险的工作，已经导致多名粗心大意的猎人受伤致残。",kw={"学徒的职责","鳄鱼","巨型鳄鱼的皮","詹姆斯·哈洛兰","米奈希尔港","湿地"},ang={["class:Hunter"]="沿着多雾的海岸线跟踪巨型鳄鱼，是对猎人追踪水生野兽能力以及避免被拖入沼泽水下的考验。"},sec={{t="危险的交易",b="湿地的沼泽和水道栖息着巨大的鳄鱼，它们的皮足够厚实，足以抵抗沼泽的潮湿腐烂。在米奈希尔港，像詹姆斯·哈洛兰这样的工匠依靠源源不断的皮料供应来制作坚韧的皮革制品。然而，从完全长成的巨型鳄鱼身上剥皮需要冒着深入水域的风险，并战胜凶猛的沼泽捕食者，这使得每一张收集到的兽皮都来之不易。"},{t="学徒的愚行",b="采集这些厚皮原本是哈洛兰年轻学徒的职责。由于缺乏击倒成年沼泽野兽的武力，这个男孩在北海岸遭到伏击。他被巨型鳄鱼抓伤，现在正躺在当地一位助产士的看护下，她说他或许能挺过来。这次袭击迫使哈洛兰雇佣经验丰富的冒险者去猎杀这些捕食者，并获取所需的兽皮。"}},faq={{q="巨型鳄鱼的皮有什么用途？",a="它们由米奈希尔港的商人詹姆斯·哈洛兰收购，他非常看重这些厚皮，因为它们可以用来制作能抵御沼泽地潮湿气候的坚固皮革制品。",al={"鳄鱼皮用途","为什么要收集巨型鳄鱼的皮","哈洛兰收购兽皮的目的"}},{q="去哪里寻找提供这种兽皮的鳄鱼？",a="巨型湿地鳄鱼潜伏在米奈希尔港北部的海岸和内陆沼泽水域，在当地鱼人定居点之外的浅滩徘徊。",al={"巨型鳄鱼位置","哪里寻找巨型鳄鱼","湿地鳄鱼海岸"}},{q="哈洛兰的学徒发生了什么事？",a="哈洛兰派他的学徒独自进入沼泽采集兽皮。学徒遭到了巨型鳄鱼的袭击并被抓伤，伤势严重，只能留在一位米奈希尔助产士的照顾下，她说他或许能挺过来。",al={"学徒受伤","哈洛兰的学徒","谁受了伤"}},{q="这些兽皮与幼年鳄鱼的皮相比如何？",a="幼年鳄鱼产出的皮更薄、更柔软。完全长成的巨型鳄鱼产出的兽皮要坚韧得多，也厚得多，但杀死一只巨型鳄鱼需要老练的战斗技巧。",al={"幼年鳄鱼皮与巨型鳄鱼皮的区别","鳄鱼皮的区别"}}},fx={["406c8fec"]={q="巨型鳄鱼的皮是什么？",a="这是从湿地沼泽中游荡的巨型鳄鱼身上剥下的厚实耐用的皮。皮革匠和工匠看重它的韧性与尺寸。要获取这样的皮毛并非易事，因为这些掠食者是水道中最凶猛的野兽之一。",al={"巨型鳄鱼的皮是什么","巨型鳄鱼皮","鳄鱼皮信息"}},bd43ba97={q="巨型鳄鱼的皮来自哪里？是谁制作的？",a="这种皮是从湿地沿海岸向北、鱼人窝棚以外的沼泽中生活的巨型鳄鱼身上剥下的。它并非由工匠制作，而是必须直接从这些巨型沼泽野兽的尸体上剥取。",al={"谁制作了巨型鳄鱼的皮","巨型鳄鱼的皮来自哪里","巨型鳄鱼的皮来源"}},c37602c5={q="詹姆斯·哈洛兰为什么需要巨型鳄鱼的皮？",a="米奈希尔港的工匠詹姆斯·哈洛兰需要这些皮来从事他的行当。他起初派年轻的学徒去收集，但那孩子遭饥饿的野兽撕咬，随后由一位助产士照料。于是哈洛兰转而求助经验丰富的冒险者，帮他取得材料并为学徒报仇。",al={"哈洛兰为什么要鳄鱼皮","谁需要巨型鳄鱼的皮","为什么需要巨型鳄鱼的皮"}}},fp="20,242,17.419.0,22.411.1,40.181.0,56.149.0,39.226.0,52.163.0"}
P.entries["item:gloom-weed"] = {n="阴暗草",s="阴暗草是一种生长在提瑞斯法林地受损土壤上的病态植物，通常生长在丧钟镇和布瑞尔之间的田野里。它最出名的原因是戈多经常采错这种植物，戈多是一个动作迟缓的被遗忘者憎恶，他总把阴暗草和炼金试剂厄运草搞混。",h="阴暗草是一种生长在提瑞斯法林地受损土壤上的病态植物，通常生长在丧钟镇和布瑞尔之间的田野里。它最出名的原因是戈多经常采错这种植物，戈多是一个动作迟缓的被遗忘者憎恶，他总把阴暗草和炼金试剂厄运草搞混。",kw={"憎恶","布瑞尔","厄运草","阴暗草","戈多","霍兰德大师","提瑞斯法林地"},ang={["profession:Herbalism"]="受过训练的草药师可以通过“寻找草药”感应到这种植物，这使得它在提瑞斯法阴暗的灌木丛中更容易被发现。",["race:Undead"]="对于离开丧钟镇的新生被遗忘者来说，去取阴暗草是了解憎恶劳动力缺陷和幽暗城炼金术士刻薄脾气的一次快捷课程。"},sec={{t="错误的收割",b="阴暗草在提瑞斯法林地的阴暗和腐朽中萌芽，在布瑞尔以西、索利丹农场以东的荒地上生长得十分茂盛。尽管名字听起来有些可怕，但这种植物其实相对无害，缺乏皇家药剂师协会所看重的强效炼金药效。它的主要名声源于憎恶戈多，他在道路上徘徊，试图用他那巨大而笨拙的手拔除杂草。由于误解了他主人的命令，戈多总是采集阴暗草，并请求容易上当的旅行者将成捆的阴暗草带回布瑞尔墓地的霍兰德大师那里，这让药剂师感到无比恼火。"}},faq={{q="阴暗草有什么用途？",a="对被遗忘者炼金术士来说，它几乎毫无价值。收集它纯粹是因为憎恶戈多把它误当成了他主人真正需要的草药——厄运草。",al={"阴暗草用途","阴暗草有什么用","谁需要阴暗草"}},{q="阴暗草生长在哪里？",a="它散布在提瑞斯法林地布瑞尔和丧钟镇之间的田野里，特别是在索利丹农场以东的道路沿线和草地上。",al={"哪里能找到阴暗草","阴暗草位置","阴暗草采集点"}},{q="戈多是谁，他为什么要采摘这种植物？",a="戈多是霍兰德大师派出去采集试剂的憎恶。因为他的缝合之手太笨拙，而且头脑简单，所以他一直在路上游荡，拔错植物，并请求路人协助他。",al={"戈多是谁","为什么戈多在采草","憎恶戈多"}},{q="霍兰德大师真正想要的是什么？",a="霍兰德大师需要厄运草来进行他在布瑞尔墓地的实验。当把阴暗草交给他时，他会对这个错误嗤之以鼻，并指引旅行者去采集他真正需要的东西。",al={"霍兰德大师的草药","霍兰德需要什么","厄运草与阴暗草"}}},fx={bc1ac336={q="阴暗草是什么？",a="阴暗草是一种普通、长相病恹恹的野生植物，生长在提瑞斯法林地受诅咒的土壤中，主要分布在布瑞尔与丧钟镇之间的道路和开阔地带。它没有魔力，也不具备有价值的炼金性质。说到底，它不过是一种常见的路边杂草——相当于提瑞斯法的雏菊——恰好能在这片受污染的乡野中茁壮生长。",al={"阴暗草是什么","阴暗草背景","阴暗草植物"}},defb981c={q="为什么有人想要阴暗草？",a="实际上几乎没人想要阴暗草。人们收集它的唯一原因，是在布瑞尔附近田野游荡的戈多是个糊涂的憎恶，完全误解了指令。他的主人、初级药剂师霍兰德派他去采集珍贵的末日草，用于被遗忘者的实验，但戈多迟钝的脑袋混淆了名字，结果让不知情的旅人去采毫无价值的阴暗草。",al={"谁想要阴暗草","为什么收集阴暗草","为什么采集阴暗草"}}},fp="10,278,18.640.0,28.177.0,27.164.0,38.220.0,38.181.0"}
P.entries["item:glowing-ember"] = {n="余烬",s="余烬是从杜隆塔尔山岩上被击败的次级火焰显像身上获取的、残留的元素核心。它是萨满祭司试炼中不可或缺的仪式试剂，用于点燃永恒烈焰神龛的火盆。",h="余烬是从杜隆塔尔山岩上被击败的次级火焰显像身上获取的、残留的元素核心。它是萨满祭司试炼中不可或缺的仪式试剂，用于点燃永恒烈焰神龛的火盆。",kw={"call of fire","火焰灵契","余烬","次级火焰显像","永恒烈焰神龛","泰尔夫·祖拉姆","眠炎火炬"},ang={["class:Shaman"]="获取这块燃烧的核心是一项决定性的成人仪式，迫使学徒在驾驭图腾之前，必须在活生生的烈焰面前考验自己的决心。"},sec={{t="烈焰之核",b="当一名萨满学徒饮下火焰灵契，并在泰尔夫·祖拉姆附近的山脊上面对炽热的灵魂时，他们会遭遇一只次级火焰显像。在这个元素生物被击败后，这块闷烧的残骸便是它实体形态剩下的唯一之物。余烬中依然跳动着原始的元素热量，携带着唤醒永恒烈焰神龛圣火盆所需的生命之火。"},{t="点燃火炬",b="Placing the Glowing Ember into the otherwise cool basin of the mountain brazier triggers a sudden, white-hot ignition. Feeding on the residue of the defeated elemental, the brazier allows the initiate to ignite the Torch of the Dormant Flame, binding the unruly essence of fire into a vessel they can carry down the mountain to prove their mastery over the elements."}},faq={{q="余烬从何而来？",a="余烬取自次级火焰显像的残骸，这是一种在杜隆塔尔永恒烈焰神龛上方的山顶处遭遇的敌对元素生物。",al={"如何获得余烬","余烬掉落","哪里可以找到余烬"}},{q="余烬有什么用？",a="学徒们将余烬放入永恒烈焰神龛的金属火盆中。它会产生一种强烈的、有节奏的火焰，用于点燃仪式的眠炎火炬。",al={"余烬有什么用","余烬用途","火盆余烬"}},{q="为什么萨满需要火焰灵契才能获得它？",a="山顶上的元素之灵处于凡人肉眼不可见的境界。饮用火焰灵契可以使萨满的感官与元素位面相协调，从而显现出次级火焰显像，使其能够被挑战。",al={"为什么需要灵契","看不到火焰元素","火焰灵契余烬"}},{q="是谁指引萨满寻找这块余烬？",a="居住在杜隆塔尔山岩中的隐士泰尔夫·祖拉姆会酿制火焰灵契，并指引萨满学徒完成击败火焰之灵的试炼。",al={"谁给予任务","泰尔夫·祖拉姆余烬","call of fire任务发布者"}}},fx={["8d7073a8"]={q="余烬是什么？",a="余烬是从杜隆塔尔一座俯瞰旷野的山峰上的次级火焰显现体身上收集来的燃烧残骸。它是一团浓缩的活火，在灵体被击败后留下，蕴含着足够的天然元素热能，能够点燃山顶神圣祭坛上沉寂的火焰。",al={"余烬是什么","余烬背景","余烬物品"}}},fp="13,250,17.396.0,18.366.1,39.165.0,27.176.0,49.217.0,39.155.0"}
P.entries["item:glowing-fruit"] = {n="发光的水果",s="发光的水果是一种异域发光植物，生长在泰达希尔枝干上奇特的叶簇中。它非自然的光芒以及与世界之树土壤产生的怪异反应，使其成为了自然学家们急于进行植物学研究的对象。",h="发光的水果是一种异域发光植物，生长在泰达希尔枝干上奇特的叶簇中。它非自然的光芒以及与世界之树土壤产生的怪异反应，使其成为了自然学家们急于进行植物学研究的对象。",kw={"植物学","德纳兰","发光的水果","奥拉密斯湖","植物","泰达希尔","树妖"},ang={["class:Druid"]="对于那些敏锐察觉泰达希尔脆弱平衡的德鲁伊来说，与土壤产生不规则反应的外来植物代表着对新生的世界之树潜在的干扰。",["profession:Herbalism"]="草药学家会立即注意到，这种果实奇异的荧光表明了外部种子品种与附魔土壤之间存在着一种异域且强大的相互作用。"},sec={{t="一份好奇的样本",b="这种大型圆形果实在泰达希尔上不寻常的叶簇下被发现，并散发着显眼的光芒。奥拉密斯湖的植物学家德纳兰认定它并非世界之树的本土植物，并推测其种子是从大洋彼岸的遥远大陆漂流而来的。无论它起源于何处，这种果实与泰达希尔肥沃且充满魔力的土壤产生了怪异的反应，这也证明了新生的世界之树对于外来且不可预测的植物群来说是多么脆弱。"}},faq={{q="什么是发光的水果？",a="这是一种在泰达希尔上不寻常的叶簇中发现的异域圆形果实。它散发出空灵的光芒，似乎与当地的土壤产生了异常的反应。",al={"发光的水果 泰达希尔","这是什么水果","奇异水果任务"}},{q="这种果实来自哪里？",a="据自然学家德纳兰称，这种果实并非泰达希尔的本土植物。他怀疑其种子是从大洋彼岸的遥远地区，或许是艾泽拉斯的东部王国漂流或被带到这里，随后在土壤中生根发芽。",al={"水果起源","种子来自哪里","它是本土植物吗"}},{q="谁想要检查发光的水果？",a="驻扎在奥拉密斯湖的暗夜精灵研究员德纳兰负责研究泰达希尔的枝干和生态系统。他对于那些与世界之树土壤产生反应的外来植物表现出了浓厚的兴趣。",al={"谁需要这种水果","我该把发光的水果带给谁","德纳兰 水果"}}},fp="13,250,18.441.0,26.168.0,31.228.0,39.200.0"}
P.entries["item:glowing-gem"] = {n="发光的宝石",s="发光的宝石是一块从灰谷水域的鱼人营地中回收的附魔之石。它最初由阵亡的侦察兵Teronis所寻找，是重铸Dartol所造的魔法杖的关键部件。",h="发光的宝石是一块从灰谷水域的鱼人营地中回收的附魔之石。它最初由阵亡的侦察兵Teronis所寻找，是重铸Dartol所造的魔法杖的关键部件。",kw={"阿斯特兰纳","净化之杖","dartol","发光的宝石","伊瑞斯湖","鱼人","莱恩·狼行者","莎尔蒂恩","teronis"},ang={["class:Druid"]="德鲁伊们对Teronis关于蔓延的腐蚀之力的研究以及他希望修复的圣物很感兴趣。",["race:NightElf"]="回收这块宝石并完成Teronis的任务有助于哨兵部队缅怀他们阵亡的侦察兵，并保护灰谷免受蔓延的腐蚀。"},sec={{t="Dartol遗失的圣物",b="发光的宝石是在法拉希姆湖附近出没的凶猛鱼人手中被发现的，它蕴含着潜藏的魔法能量。年轻的暗夜精灵Teronis从阿斯特兰纳出发去寻找它，意图拼凑出一件能够驱逐渗入灰谷森林的腐蚀之力的工具。虽然Teronis在湖边不幸身亡，但这块石头却在岸边的拾荒者手中保存完好。"},{t="重铸法杖",b="在找回这块石头以及Teronis的日志后，哨兵领袖莱恩·狼行者指引携带者将其带往东北方向的莎尔蒂恩，那是一位在附近月井守望的树妖。这位树妖掌握着将发光的宝石与Dartol所造法杖的其他遗失部件结合所需的古老知识，以确保这位阵亡侦察兵的工作没有白费。"}},faq={{q="发光的宝石是从哪里来的？",a="这块宝石由在灰谷西部的法拉希姆湖神龛周围的岸边和浅水中徘徊的鱼人携带，Teronis就是在那里阵亡的。",al={"发光的宝石位置","发光的宝石掉落者","如何获得发光的宝石"}},{q="Teronis为什么要寻找这块宝石？",a="Teronis当时正在调查净化灰谷日益严重的污秽的方法。根据他的研究，这块特定的宝石是重铸Dartol曾经设计的一根魔法杖所需的关键部件之一。",al={"teronis任务","teronis为何需要宝石","宝石的用途"}},{q="我应该把发光的宝石交给谁？",a="在阿斯特兰纳向莱恩·狼行者展示这块石头和Teronis的日志后，将发光的宝石带到东北方向伊瑞斯湖以东月井边的树妖莎尔蒂恩那里。",al={"谁需要发光的宝石","发光的宝石交任务","如何使用宝石"}},{q="Dartol的法杖是什么？",a="这是一件由Dartol创造的魔法仪器。它的部件散落在森林各处，而发光的宝石是重铸它所必需的。",al={"dartol的法杖","dartol制造了什么"}}},fx={["464fc9d6"]={q="发光的宝石是什么？",a="发光的宝石是一块附魔石头，是重制达图尔制作的法杖所需的材料。泰洛尼斯在研究灰谷的腐化时寻找过它，而莱恩·狼行者则负责寻找法杖剩余的部件。",al={"发光的宝石是什么","介绍一下发光的宝石","发光的宝石背景"}}},fp="11,235,22.432.0,17.368.1,37.149.0,37.201.0,37.169.0,26.138.0"}
P.entries["item:glowing-soul-gem"] = {n="发光的灵魂宝石",s="发光的灵魂宝石是北灰谷的Cult of the Dark Strand特工随身携带的一种黑暗仪式神器。这块石头被注入了暗影法术，禁锢着一名受害者的灵魂，为该邪教的邪恶勾当提供动力。",h="发光的灵魂宝石是北灰谷的Cult of the Dark Strand特工随身携带的一种黑暗仪式神器。这块石头被注入了暗影法术，禁锢着一名受害者的灵魂，为该邪教的邪恶勾当提供动力。",kw={"奥萨拉克斯","cult of the dark strand","dark strand","净化者德尔格伦","发光的灵魂宝石","迈斯特拉岗哨","奥迪拉兰","灵魂宝石"},ang={["class:Priest"]="牧师在观察灵魂宝石时，能感受到内部禁锢灵魂的痛苦，从而意识到净化该神器并让灵魂获得安息的迫切需要。",["class:Warlock"]="术士比任何人都更了解将灵魂禁锢在灵魂石中的技艺，他们认为Dark Strand的这种宝石是一种更粗糙、更具死灵性质的灵魂操控衍生品。"},sec={{t="黑暗法术的容器",b="在迈斯特拉岗哨东北方，奥迪拉兰废墟的阴影中，Cult of the Dark Strand的成员在他们暗影主宰的注视下施展着黑暗法术。在他们的队伍中，特工们携带着发光的灵魂宝石——这些容器经过附魔，旨在禁锢并折磨死者的灵魂。这些石头并非单纯的装饰品，而是魔法能量的导管，将受缚的灵魂固定在此，以服务于该邪教的暗影目的。"},{t="奥迪拉兰的秘密",b="为了瓦解Dark Strand在北卡利姆多各地的势力，位于迈斯特拉岗哨的净化者德尔格伦对这些神器进行了调查。解读发光的灵魂宝石上编织的附魔，不仅揭示了黑暗奥术公式，还让人听到了宝石内部禁锢的灵魂发出的哀嚎，从而暴露了将灰谷的邪教徒与奥萨拉克斯之塔的同伙联系在一起的邪恶实验。"}},faq={{q="什么是发光的灵魂宝石？",a="这是一种由Cult of the Dark Strand使用的附魔灵魂石。它被注入了暗影魔法，将灵魂禁锢在内以汲取其精华，从而为该邪教的邪恶法术提供能量。",al={"什么是灵魂宝石","黑海岸灵魂宝石","发光的灵魂宝石背景故事"}},{q="这个灵魂宝石从哪里来？",a="它是由北灰谷奥迪拉兰废墟中活动的Cult of the Dark Strand成员（包括他们的邪教徒、刺客、执行者和专家）随身携带的。",al={"谁掉落灵魂宝石","发光的灵魂宝石位置","奥迪拉兰宝石"}},{q="谁想要这个灵魂宝石，为什么要它？",a="驻扎在迈斯特拉岗哨的净化者德尔格伦正在寻找这种宝石。他相信解读其中的附魔将揭示该邪教力量的秘密来源，并揭露他们的阴谋。",al={"德尔格伦灵魂宝石","为什么德尔格伦需要灵魂宝石","迈斯特拉岗哨灵魂宝石"}},{q="解读灵魂宝石后会发生什么？",a="解除宝石上的附魔会释放出被禁锢其中的鬼魂，解放受折磨的灵魂，并揭露Dark Strand扭曲行径的深层内幕。",al={"灵魂宝石里有什么","灵魂宝石里的鬼魂"}}},fp="16,239,24.434.0,25.404.1,29.174.0,35.182.0,32.192.0,45.167.1"}
P.entries["item:glutton-shackle"] = {n="暴食者镣铐",s="暴食者镣铐是银松森林中月怒暴食者狼人佩戴的附魔束缚物。这些镣铐由疯狂的大法师阿鲁高所造，旨在引导魔法来增强他那本身存在缺陷的法术，并维持他那受到诅咒的狼人造物。",h="暴食者镣铐是银松森林中月怒暴食者狼人佩戴的附魔束缚物。这些镣铐由疯狂的大法师阿鲁高所造，旨在引导魔法来增强他那本身存在缺陷的法术，并维持他那受到诅咒的狼人造物。",kw={"阿鲁高","达拉尔·道恩维沃尔","暴食者镣铐","月怒暴食者","瑟伯切尔","银松森林","狼人"},ang={["class:Mage"]="法师们会对达拉尔·道恩维沃尔对阿鲁高拙劣技术的辛辣批评产生共鸣，因为使用物理附魔拐杖来稳定简单的变形术和召唤术被视为平庸巫师的标志。",["race:Undead"]="被遗忘者的特工将收集这些镣铐视为消灭狼人威胁的关键步骤，因为这种威胁已经直接侵犯到了瑟伯切尔的边界。"},sec={{t="脆弱法术的拐杖",b="对于被遗忘者那些受过训练的法师来说，在银松森林横行的野性狼人不仅仅是残暴的怪物，更是其奥术造诣严重不足的铁证。达拉尔·道恩维沃尔，驻扎在瑟伯切尔的一位成就卓著的奥术师，对大法师阿鲁高不屑一顾，认为他是一个不配加入肯瑞托的无能之辈。道恩维沃尔发现，阿鲁高依赖附魔遗物来弥补他那不稳定的法术。在银松森林北部游荡的重型月怒暴食者所佩戴的暴食者镣铐，正是用以加强束缚这些野兽的诅咒的魔法锚点。"},{t="被遗忘者对策的燃料",b="由于阿鲁高将原始的附魔直接绑定在这些沉重的铁环上，即使佩戴者被杀，它们依然保留着残余的魔法能量。道恩维沃尔要求被遗忘者的特工收集这些镣铐，以便研究其构造并吸取其中的魔法储备。通过分析嵌入金属中的粗糙附魔，被遗忘者希望能够解开狼人诅咒的谜团，并终结那位盘踞在影牙城堡的驯兽师。"}},faq={{q="什么是暴食者镣铐？",a="暴食者镣铐是银松森林中月怒暴食者狼人佩戴的附魔铁制束缚物。这些镣铐由大法师阿鲁高创造，旨在为佩戴者注入魔法增强，以支撑他那存在缺陷的法术。",al={"什么是暴食者镣铐","暴食者镣铐背景故事","狼人镣铐"}},{q="为什么达拉尔·道恩维沃尔想要暴食者镣铐？",a="达拉尔·道恩维沃尔需要这些镣铐来分析阿鲁高的粗糙附魔，并吸取其中残留的魔法能量。通过了解阿鲁高用来稳定其野兽的物品，被遗忘者可以更好地对抗他的魔法。",al={"为什么要收集镣铐","达拉尔·道恩维沃尔任务","瑟伯切尔的镣铐"}},{q="谁制造了这些镣铐？",a="它们是由大法师阿鲁高施法制造的。他曾是达拉然的一名巫师，为了对抗天灾军团而召唤了狼人，最终却失去了理智，利用魔法饰品将他的造物束缚在自己的意志之下。",al={"谁制造了镣铐","阿鲁高的镣铐","镣铐从哪里来"}},{q="佩戴这些镣铐的生物在哪里？",a="月怒暴食者在银松森林中部和北部的树林及废弃农场中游荡，经常与其他被腐化的月怒狼人成群结队地潜伏。",al={"暴食者在哪里刷新","月怒暴食者位置","银松森林狼人镣铐"}}},fp="15,238,25.593.0,33.466.1,26.221.0,48.227.0,25.198.0,53.166.0"}
P.entries["item:glyph-of-azora"] = {n="阿祖拉的铭文饰品",s="阿祖拉的铭文饰品是一种由法师塞欧克瑞图斯在阿祖拉之塔制造的奥术追踪装置。通过与阿祖拉之眼的神视力量相连，这些刻有铭文的石头使法师能够窥视远方，并探究敌人的思想。",h="阿祖拉的铭文饰品是一种由法师塞欧克瑞图斯在阿祖拉之塔制造的奥术追踪装置。通过与阿祖拉之眼的神视力量相连，这些刻有铭文的石头使法师能够窥视远方，并探究敌人的思想。",kw={"阿祖拉的铭文饰品","morganth","赤脊山","神视","石堡要塞","塞欧克瑞图斯","阿祖拉之塔","伊尔加拉之塔"},ang={["class:Mage"]="阿祖拉的铭文饰品展示了实用的奥术占卜，将标准的水晶神视扩展为定向心灵感应和远程感官中继。",["faction:Alliance"]="这些铭文饰品提供了关于赤脊山敌对行动的关键情报，追踪着叛逆术士Morganth和驻扎在石堡的黑石兽人。"},sec={{t="边境之眼",b="在艾尔文森林的塔楼中，法师塞欧克瑞图斯不知疲倦地监视着威胁王国的敌对势力。虽然他的水晶遗物——阿祖拉之眼能够进行远程视觉神视，但却无法深入洞察敌人的思想和计划。为了克服这一局限，塞欧克瑞图斯嵌入了被称为“阿祖拉的铭文饰品”的微型焦点。一旦安置在偏远地区的表面，这种铭文饰品就会成为他魔法的锚点，使他不仅能读取敌人的意图，还能跨越数英里投射声音，直接与外勤特工进行交流。"},{t="赤脊山的间谍活动",b="塞欧克瑞图斯将这些铭文饰品直接部署到赤脊山的敌对领地。第一个被安置在一尊俯瞰伊尔加拉之塔的古老狮子雕像上，那是他叛逆的对手、黑暗法师Morganth的据点。在探入Morganth的思想后，塞欧克瑞图斯发现这位叛逃法师与占据附近石堡要塞的黑石兽人之间存在意想不到的纠纷。第二个铭文饰品被带到要塞完好的瞭望塔高处，藏在一个废弃的酒罐里，以揭开Morganth和入侵者之间为何发生冲突。"}},faq={{q="阿祖拉的铭文饰品有什么用途？",a="它是由塞欧克瑞图斯制造的奥术中继器。虽然他的阿祖拉之眼可以进行远程视觉神视，但放置一个阿祖拉的铭文饰品可以建立一个锚点，让他能够读取敌人的思想和未来计划，并投射自己的声音与远方的盟友交谈。",al={"阿祖拉的铭文饰品有什么作用","为什么要使用阿祖拉的铭文饰品","阿祖拉的铭文饰品的用途"}},{q="谁制造了阿祖拉的铭文饰品？",a="它由塞欧克瑞图斯制造，这是一位居住在艾尔文森林东部边界阿祖拉之塔内的强大法师。",al={"谁制造了铭文饰品","阿祖拉的铭文饰品制造者","塞欧克瑞图斯的铭文饰品"}},{q="阿祖拉的铭文饰品被放置在哪里？",a="一个铭文饰品被安置在俯瞰伊尔加拉之塔的一尊风化狮子雕像的底座上。第二个铭文饰品被走私到石堡要塞的上层瞭望塔，并藏在一个空酒罐里，以便监视黑石兽人。",al={"铭文饰品放在哪里","铭文饰品放置地点","铭文饰品去向"}},{q="为什么塞欧克瑞图斯要监视伊尔加拉之塔？",a="伊尔加拉之塔被Morganth占据，他是一位危险的叛逆法师，也是塞欧克瑞图斯激烈的竞争对手。塞欧克瑞图斯使用铭文饰品来揭露Morganth的阴谋，以防他向该地区散布黑暗魔法。",al={"为什么要监视morganth","塞欧克瑞图斯与伊尔加拉","morganth的仇恨"}},{q="铭文饰品是如何让塞欧克瑞图斯与人交谈的？",a="该铭文饰品直接与阿祖拉之塔的奥术能量相连。一旦固定在目标表面，它就建立了一个双向管道，让塞欧克瑞图斯可以直接通过石头投射他虚无的声音。",al={"会说话的铭文饰品","铭文饰品中的塞欧克瑞图斯之声","铭文饰品能说话吗"}}},fp="14,182,22.424.0,21.503.1,42.206.0,31.107.0,37.168.0,49.150.0,55.141.0"}
P.entries["item:glyphic-letter"] = {n="雕文信件",s="雕文信件是一封带有凯尔登·布雷门奥术徽记的官方信函，凯尔登是北郡修道院的驻地法师训练师。当有前途的初学者在完成早期的驻军服务后，就会收到这封信，信中要求有志向的法师前往楼上，面对奥术学习的严苛现实。",h="雕文信件是一封带有凯尔登·布雷门奥术徽记的官方信函，凯尔登是北郡修道院的驻地法师训练师。当有前途的初学者在完成早期的驻军服务后，就会收到这封信，信中要求有志向的法师前往楼上，面对奥术学习的严苛现实。",kw={"奥术","艾尔文森林","雕文信件","凯尔登·布雷门","法师训练师","治安官玛克布莱德","北郡修道院"},ang={["class:Mage"]="这份带有标记的调度信标志着你正式加入联盟的奥术传统，召唤你到楼上师从凯尔登·布雷门。",["race:Human"]="北郡修道院在王国的历史上庇护了许多奥术学生，而这份召唤标志着你开始为暴风城的魔法学科服务。"},sec={{t="奥术召唤",b="雕文信件盖有法师训练师凯尔登·布雷门的个人徽记，在学徒展现出他们在北郡山谷的纪律性后，这封信会被交给他们。这封信是一份正式的邀请函，邀请他们离开基础的外勤职责，开始在修道院内进行专门的魔法指导。布雷门利用这份召唤来衡量学生的决心，确保任何涉足奥术的人都做好了充分准备，去面对危险的力量、不屈的审视，以及运用原始魔法力量所带来的负担。"}},faq={{q="什么是雕文信件？",a="这是一封由北郡修道院的驻地法师导师凯尔登·布雷门撰写并封缄的教学召唤信。它指引有志向的人类法师在修道院的上层房间找到他，进行正式的奥术学习。",al={"这封信是什么","雕文信件物品","凯尔登的信"}},{q="谁寄出了雕文信件？",a="这封信盖有北郡修道院驻地法师训练师凯尔登·布雷门的徽记。在学徒证明了自己对抗附近害虫的勇气后，驻军指挥部会将其移交给学徒。",al={"谁写的","谁给了我雕文信件","信件寄件人"}},{q="我应该把雕文信件带到哪里？",a="你需要把它带进北郡修道院。从治安官玛克布莱德身后的正门进去，走左边的走廊，登上楼梯，然后看向凯尔登·布雷门进行奥术教学的后室。",al={"去哪里","凯尔登·布雷门在哪里","凯尔登位置"}},{q="凯尔登为什么要召见年轻法师？",a="凯尔登希望考验你的决心。正如他在入门课程中所警告的那样，追求奥术意味着在挑战强大力量的同时招致恐惧和尊重，他需要知道他的学徒是否具备承受这种命运的意志。",al={"凯尔登为什么找我","法师训练师的原因","凯尔登想要什么"}}},fp="14,189,23.393.0,27.189.0,29.183.0,35.185.0,38.199.0"}
P.entries["item:glyphic-memorandum"] = {n="雕文备忘录",s="《雕文备忘录》是发给抵达寒脊山谷的新手法师的一份书面通知。它由法师训练师玛瑞克·斯托纳尔代笔，指示初出茅庐的施法者进入室内，开始接受正式的奥术指导。",h="《雕文备忘录》是发给抵达寒脊山谷的新手法师的一份书面通知。它由法师训练师玛瑞克·斯托纳尔代笔，指示初出茅庐的施法者进入室内，开始接受正式的奥术指导。",kw={"安威玛尔","寒脊山谷","丹莫罗","雕文备忘录","法师","玛瑞克·斯托纳尔"},ang={["class:Mage"]="对于在丹莫罗冒险的初学法师来说，这份便条标志着他们在玛瑞克·斯托纳尔指导下正式开启了奥术学徒生涯。",["race:Gnome"]="在流亡中开始旅程的侏儒法师们会受到训练师的提醒：专心学业，远离他们失落的家园诺莫瑞根。"},sec={{t="安威玛尔的召唤",b="初入寒脊山谷凛冽严寒的新手施法者在完成最初的任务后，会收到这封简短的信件。这份备忘录由当地的法师训练师玛瑞克·斯托纳尔撰写，召唤年轻的修行者前往安威玛尔的温暖避风港。玛瑞克的指导并非刻板的学术教条，而是直截了当的非正式建议：熟记咒语，存钱用于学习法术和在旅店买啤酒，并且离遭受辐射的诺莫瑞根废墟远远的。"}},faq={{q="什么是《雕文备忘录》？",a="这是一份提供给刚抵达寒脊山谷的新手法师的简短书面召唤信，指示他们前往安威玛尔内部寻找当地的奥术训练师。",al={"雕文备忘录","法师便条","什么是雕文备忘录"}},{q="这份备忘录是谁写的？",a="这份便条出自玛瑞克·斯托纳尔之手，他是一位驻扎在丹莫罗安威玛尔大厅内的侏儒法师训练师。",al={"谁写的","谁发送的雕文备忘录","便条作者"}},{q="当回应这份备忘录时，训练师给出了什么建议？",a="在出示这份便条时，玛瑞克提醒新手要学会克制，存钱学习法术和购买旅店的啤酒，并严禁靠近充满辐射的诺莫瑞根大厅。",al={"玛瑞克的建议","玛瑞克说了什么"}}},fx={c67a7a55={q="玛瑞克·斯托纳尔为什么要你把雕文备忘录带给他？",a="这份备忘录是给寒脊山谷初学法师的邀请与召见。将它交给安威玛尔的玛瑞克·斯托纳尔，就能与当地的法师训练师建立联系。他会借此向新手提供建议，提醒你远离沦陷的诺莫瑞根，并表示只要你有余钱，随时可以接受奥术正式训练。",al={"为什么要带上雕文备忘录","玛瑞克为什么要这份备忘录","为什么需要雕文备忘录"}}},fp="18,236,21.465.0,31.153.0,26.116.0,64.168.0"}
P.entries["item:glyphic-scroll"] = {n="雕文卷轴",s="雕文卷轴是送达给丧钟镇新复活的被遗忘者法师的征召令。它带有当地奥术训练师伊莎贝拉的印记，召唤初出茅庐的施法者前往那座被亵渎的教堂，在亡灵状态下磨练他们的技艺。",h="雕文卷轴是送达给丧钟镇新复活的被遗忘者法师的征召令。它带有当地奥术训练师伊莎贝拉的印记，召唤初出茅庐的施法者前往那座被亵渎的教堂，在亡灵状态下磨练他们的技艺。",kw={"奥术","丧钟镇","雕文卷轴","伊莎贝拉","法师","卷轴","提瑞斯法"},ang={["class:Mage"]="这份卷轴是被遗忘者法师收到的第一份正式征召，它强调了亡灵身份并不能让施法者摆脱奥术魔法那种腐蚀性的沉迷。",["race:Undead"]="对于被遗忘者而言，收复的奥术知识不仅仅是学术研究——它是确保他们主权不受天灾军团和活体敌人侵害的关键武器。"},sec={{t="来自教堂的征召",b="当一位刚苏醒的被遗忘者法师从丧钟镇墓地清理完无脑的天灾军团后，这封加盖印章的信件便在等着他们。卷轴上书写着该定居点的驻地法师训练师伊莎贝拉的印记，召唤接收者前往那座破败的教区圣所。对于新复活的法师来说，这不仅是他们在被遗忘者旗帜下进行奥术训练的入门向导，同时也提醒他们：虽然死亡让他们摆脱了凡人的软弱，但魔法力量那腐蚀性的诱惑依然如影随形。"}},faq={{q="什么是雕文卷轴？",a="这是一份发给丧钟镇新复活的被遗忘者法师的入门简报。它带有奥术训练师伊莎贝拉的个人印记，指示新晋的施法者向她报告，前往城镇教堂开始他们的魔法指导。",al={"该物品是什么","雕文卷轴用途","卷轴的作用"}},{q="谁发送了雕文卷轴？",a="该卷轴是以丧钟镇破败教堂内的法师训练师伊莎贝拉的名义送出的。她会联系任何有奥术天赋的新复活亡灵。",al={"谁写的","谁给我的","卷轴发送者"}},{q="为什么伊莎贝拉要训练新的被遗忘者法师？",a="伊莎贝拉寻找着那些有着共同死亡之痛、并渴望收复被窃家园与命运的同类。她训练他们培养足够的奥术力量来摧毁任何反对被遗忘者的人，同时也告诫他们不要屈服于魔法的成瘾性和腐蚀性。",al={"伊莎贝拉的目的","为什么要训练法师"}}},fp="14,233,25.552.0,27.247.0,29.195.0,51.285.0"}
P.entries["item:glyphic-tablet"] = {n="雕文石板",s="雕文石板是一块刻有文字的石板，授予那些在杜隆塔尔开始试炼的暗矛巨魔新手法师。它通过监工高内克之手送达，指引刚入门的施法者向巨魔训练师迈安寻求教导。",h="雕文石板是一块刻有文字的石板，授予那些在杜隆塔尔开始试炼的暗矛巨魔新手法师。它通过监工高内克之手送达，指引刚入门的施法者向巨魔训练师迈安寻求教导。",kw={"奥术","杜隆塔尔","雕文石板","高内克","迈安","巨魔法师","试炼谷"},ang={["class:Mage"]="这块石板标志着你在暗矛部族中奥术学习的开始，并传达了来自迈安的提醒：魔法的腐蚀诱惑是你最大的危险。",["race:Troll"]="暗矛法师接收这块石板，以开启他们在传统萨满之道和武技之路之外的修行。"},sec={{t="法师的首次召唤",b="在试炼谷，展现出奥术天赋的暗矛巨魔新兵会获赠雕文石板。当年轻的新兵们在红色峡谷附近处理早期任务时，高内克会将石板转交给他们，石板中包含着迈安的邀请——迈安是一位驻扎在大兽穴外围的经验丰富的巨魔训练师。对于奥术传统不同于人类或高等精灵学术学院的暗矛巨魔来说，这块石板是正式的修行号召。迈安通过这次会面不仅提供了奥术指导，还给出了一个严肃的警告：原始魔法具有腐蚀性和欺骗性，对施法者心智造成的危害远甚于任何敌方战士。"}},faq={{q="雕文石板的用途是什么？",a="它是一份书面召唤，指引新手巨魔法师向试炼谷当地的法师训练师迈安报到，以开始正规的施法训练。",al={"雕文石板有什么用","雕文石板的使用","为什么我有雕文石板"}},{q="雕文石板是谁发送的？",a="该石板由法师训练师迈安撰写，并由高内克在试炼谷内分发给年轻的巨魔新兵。",al={"谁写了雕文石板","谁给了我雕文石板"}},{q="为什么巨魔法师需要关于魔法的警告？",a="迈安强调奥术魔法具有内在的腐蚀性。她警告说，魔法会滋生傲慢，让施法者误以为自己无坚不摧，并告诫说奥术中那些看不见的危险远比物理对手更加致命。",al={"迈安说了什么","魔法危险吗"}},{q="其他部落种族能收到这块石板吗？",a="巨魔法师在试炼谷获得雕文石板。兽人法师则是通过Glyphic Parchment被召唤到迈安那里。",al={"兽人能获得雕文石板吗","雕文石板是巨魔专属吗"}}},fx={be25ec39={q="雕文石板是什么？",a="雕文石板是一封铭文信件，送给在试炼谷开始接受考验的巨魔新手法师。它由高内克转交给你，召你去见当地的法师训练师迈安，以便正式开始学习奥术。",al={"雕文石板是什么","雕文石板物品","关于雕文石板"}},["28b4f0b5"]={q="为什么有人想要雕文石板？",a="这块石板并非为了力量或财富而被寻求，而是用作正式的召见凭证和介绍信。它确保年轻的巨魔法师前去拜见迈安，后者会借此机会向他们发出重要警告，说明驾驭奥术魔法所固有的腐化危险。",al={"为什么要雕文石板","谁需要雕文石板","为什么保留雕文石板"}}},fp="14,246,22.655.0,42.171.0,29.123.0,46.233.0,42.128.0"}
P.entries["item:glyphs-of-summoning"] = {n="召唤铭文",s="召唤铭文是奥格瑞玛的术士学徒所使用的仪式铭文。它们摘录自古老的维尔加石板，允许施法者将虚空行者从虚空之中拉入召唤法阵，并将其束缚为己所用。",h="召唤铭文是奥格瑞玛的术士学徒所使用的仪式铭文。它们摘录自古老的维尔加石板，允许施法者将虚空行者从虚空之中拉入召唤法阵，并将其束缚为己所用。",kw={"cleft of shadow","甘鲁尔·血眼","召唤铭文","neeru fireblade","奥格瑞玛","维尔加石板","束缚仪式","虚空行者"},ang={["class:Warlock"]="这些铭文代表了部落术士必经的成人仪式，是他们证明自己能够驾驭虚空并获得虚空行者仆从的重要手段。"},sec={{t="暗影中缔结的契约",b="在Cleft of Shadow幽深的地下深处，黑暗魔法的研究远离了酋长守卫们的窥探。对于在甘鲁尔·血眼指导下渴望成为术士的学徒来说，驾驭虚空行者是他们修行过程中至关重要的一步。召唤铭文源自维尔加石板上记载的深奥知识，它连接了艾泽拉斯与虚空之间的界限。将这些铭文绘制在Neeru Fireblade帐篷里的召唤法阵中，可以撕开一道裂隙，将虚空生物拖入凡人的世界。这项仪式要求术士必须在战斗中征服被召唤的实体，之后甘鲁尔才会传授束缚它们的最终方法。"}},faq={{q="召唤铭文有什么用？",a="这些铭文是仪式用的符文，用于奥格瑞玛Neeru Fireblade帐篷内的召唤法阵中。当激活时，它们会从虚空中召唤出一个敌对的虚空行者，术士必须将其制服，才能掌握召唤它的技艺。",al={"召唤铭文的作用","召唤铭文的目的","如何使用召唤铭文"}},{q="召唤铭文从何而来？",a="它们由Cleft of Shadow的术士训练师甘鲁尔·血眼提供，其知识源自维尔加石板上的记载。",al={"哪里获得召唤铭文","谁提供召唤铭文"}},{q="召唤仪式在哪里进行？",a="仪式在Neeru Fireblade的帐篷内进行，该帐篷位于奥格瑞玛Cleft of Shadow的洞穴地面另一侧。",al={"在哪里召唤虚空行者","奥格瑞玛召唤法阵位置","neeru fireblade的法阵"}},{q="为什么术士必须击败被召唤的生物？",a="若不建立统治地位，术士便无法安全地控制恶魔或虚空生物。击败被召唤的实体证明了术士的意志力，并使甘鲁尔·血眼能够教授将此类生物束缚于其意志之下的秘诀。",al={"为什么要与虚空行者战斗","制服虚空行者"}}},fx={["094a8ca5"]={q="什么是召唤铭文？",a="召唤铭文是直接从维尔加石板上誊录下来的奥术与恶魔文字。甘鲁尔·血眼将它们交给在奥格瑞玛地下修习的术士学徒，其中记载着撕开帷幕、从虚空扭曲中召来敌对虚空行者并将其束缚所需的精确咒语。",al={"什么是召唤铭文","召唤铭文背景","召唤铭文是什么"}},fd669514={q="甘鲁尔·血眼为什么要收回召唤铭文？",a="甘鲁尔·血眼要求你带回铭文，并带上胜利的证明，这样他才能完成对你的训练。等你证明自己有力量召唤并制服狂暴的虚空行者后，甘鲁尔会借助铭文和你展现出的掌控力，教你如何将这类生物永久束缚在自己麾下。",al={"为什么归还召唤铭文","甘鲁尔为什么要召唤铭文","为什么有人要召唤铭文"}}},fp="19,252,23.679.0,42.244.0,43.142.0,40.126.0,53.246.0"}
P.entries["item:gnoam-sprecklesprocket"] = {n="小型高能发动机",s="小型高能发动机是一种从死亡矿井深处的斯尼德的伐木机中打捞出来的复杂动力源。侏儒工程师们寻求这个部件来为特制的钻探机增压，旨在实现他们夺回沦陷的家园诺莫瑞根的宏伟计划。",h="小型高能发动机是一种从死亡矿井深处的斯尼德的伐木机中打捞出来的复杂动力源。侏儒工程师们寻求这个部件来为特制的钻探机增压，旨在实现他们夺回沦陷的家园诺莫瑞根的宏伟计划。",kw={"死亡矿井","小型高能发动机","诺莫瑞根","陀螺钻探挖掘机","沉默的舒尼","斯尼德","斯尼德的伐木机"},ang={["profession:Engineering"]="该发动机是一个完好的动力源，能够为钻穿诺莫瑞根多岩石的地下边界所需的机械提供动力。",["race:Gnome"]="每回收一个部件，流亡的侏儒们就离钻入他们失落的家园并驱逐石腭怪侵扰的目标更近了一步。"},sec={{t="至关重要的动力源",b="小型高能发动机发现于迪菲亚兄弟会据点内的一台地精伐木机中，代表了紧凑型机械能领域的一项杰出成就。这个特制核心在由地精工头斯尼德驾驶的笨重机器深处运作，能提供足够的持续能量来驱动重型工业伐木和切割刀片。它的稳定性和强大的输出使其成为西部荒野地下隧道中一件无价的打捞品。"},{t="突入诺莫瑞根",b="在暴风城，侏儒发明家沉默的舒尼将死亡矿井的伐木机视为发起更大规模攻势的关键。侏儒部队寻求从占领诺莫瑞根的石腭怪大军手中夺回这座城市，但封闭的地下通道构成了难以逾越的障碍。通过利用小型高能发动机，舒尼打算为重型陀螺钻探挖掘机提供动力，这些机器能够直接钻透环绕这座失落科技之城的坚硬岩层，开辟一条出其不意的地下突击路线。"}},faq={{q="什么是小型高能发动机？",a="这是一种从死亡矿井深处发现的地精伐木机中提取出来的完好、高输出的机械动力源。它拥有足够的功率来运行重型地下钻探设备。",al={"小型高能发动机","这是什么发动机","物品是什么"}},{q="小型高能发动机从哪里来？",a="它是由斯尼德的伐木机中回收的，这是一种由地精工头斯尼德在死亡矿井的伐木场中操作的工业伐木机器。",al={"谁掉落它","如何获取小型高能发动机","伐木机掉落"}},{q="为什么沉默的舒尼需要它？",a="舒尼需要它的能量输出为陀螺钻探挖掘机提供动力。这些机器旨在钻穿诺莫瑞根的地下岩石边界，让联盟阵营的侏儒能够对石腭怪发起突袭。",al={"为什么舒尼想要这个","舒尼任务物品"}},{q="这个发动机是地精科技还是侏儒科技？",a="它是在死亡矿井中从一台正常运作的地精伐木机中回收的，而舒尼计划将其动力源用于侏儒的钻探机械中。资料来源并未说明是谁最初设计了这个部件。",al={"是地精科技吗","侏儒还是地精装置"}}},fp="22,263,20.458.0,20.512.0,35.186.0,48.149.0,35.234.0,45.206.0"}
P.entries["item:gnoll-paw"] = {n="豺狼人的爪子",s="豺狼人的爪子是采集自游荡在西部荒野草原上的河爪豺狼人的粗糙战利品。它们由人民民兵收集，作为巡逻队成功削减威胁当地农场的豺狼人部族数量的证明。",h="豺狼人的爪子是采集自游荡在西部荒野草原上的河爪豺狼人的粗糙战利品。它们由人民民兵收集，作为巡逻队成功削减威胁当地农场的豺狼人部族数量的证明。",kw={"丹努文","豺狼人的爪子","巡逻西部荒野","人民民兵","河爪","哨兵岭","西部荒野"},ang={["class:Hunter"]="追踪西部荒野开阔平原上好斗的河爪豺狼人部族，可以为猎人提供直接的猎物，同时也有助于保护农村前哨。",["faction:Alliance"]="对于联盟的勇士来说，接受人民民兵的赏金任务对于防止暴风城的西部粮仓完全落入流窜的野兽和有组织的强盗之手至关重要。"},sec={{t="民兵的赏金",b="由于皇家军队缺席，且王国对农村定居点的困境似乎视而不见，西部荒野的防御工作已经落到了普通市民和志愿军的肩上。以哨兵岭为基地的人民民兵一直在与歹徒、流氓机械装置以及好斗的鬣狗头豺狼人进行斗争。为了遏制豺狼人的威胁，丹努文队长设立了赏金，要求提供被杀野兽的实物证据。收集断掉的爪子是一项冷酷的必要措施，旨在确保受雇的冒险者确实是在荒野中巡逻，而不是在瞭望塔的阴影下偷懒。"},{t="协同的威胁",b="西部荒野的河爪豺狼人不仅仅是在平原上觅食的凶猛野兽。民兵中的观察员注意到，有令人不安的迹象表明，这些豺狼人与以死亡矿井为基地的迪菲亚盗贼有着密切的配合。通过恐吓偏远的农场和袭击过往的补给马车，豺狼人部族有效地掩护了强盗免受当地抵抗力量的干扰。通过带回它们的爪子来压制这些豺狼人，有助于保持哨兵岭和艾尔文森林之间不稳定的陆路交通畅通。"}},faq={{q="为什么丹努文队长需要豺狼人的爪子？",a="丹努文队长将这些爪子作为在西部荒野平原上成功巡逻的证明。由于民兵资源匮乏，且王国没有提供任何援助，只有当新兵上交了死掉豺狼人的实物证据时，才会支付赏金。",al={"为什么要收集爪子","丹努文豺狼人的爪子","豺狼人的爪子有什么用"}},{q="哪些豺狼人会掉落这些爪子？",a="它们是从游荡在整个西部荒野的草原、丘陵和废弃农场里的各种河爪豺狼人身上收集的。",al={"哪里获得豺狼人的爪子","哪些豺狼人有爪子","豺狼人的爪子位置"}},{q="这些豺狼人在西部荒野是单独行动的吗？",a="不。丹努文队长和民兵怀疑河爪豺狼人正在与以死亡矿井为基地的强盗和窃贼勾结，给当地农场造成了双重麻烦。",al={"豺狼人是否与迪菲亚兄弟会合作","豺狼人与死亡矿井的联系","谁指挥豺狼人"}},{q="为什么暴风城不处理豺狼人的威胁？",a="由于国内动荡和政治瘫痪，暴风城基本上已经放弃了西部荒野，任其自生自灭。乡村的防御几乎完全留给了当地农民和人民民兵。",al={"为什么没有暴风城军队","军队在哪里","为什么民兵要和豺狼人战斗"}}},fp="9,159,21.406.0,20.372.1,41.213.0,29.98.0,40.147.1,50.195.0"}
P.entries["item:gnomeregan-gumdrop"] = {n="诺莫瑞根橡皮糖",s="诺莫瑞根橡皮糖是一种在万圣节期间为了流离失所的侏儒而分发的季节性特色甜点。冒险者们收集这种糖果，是为了帮助暴风城孤儿院里生病的孩子耶斯帕尔庆祝节日。",h="诺莫瑞根橡皮糖是一种在万圣节期间为了流离失所的侏儒而分发的季节性特色甜点。冒险者们收集这种糖果，是为了帮助暴风城孤儿院里生病的孩子耶斯帕尔庆祝节日。",kw={"糖果","诺莫瑞根橡皮糖","万圣节","铁炉堡","耶斯帕尔","暴风城","塔瓦斯德·基瑟尔"},ang={["faction:Alliance"]="收集这种甜点需要穿梭于人类、矮人和侏儒社区之间，展现了节日庆典期间联盟各族之间紧密的联系。",["race:Gnome"]="即使没有收复自己的城市，侏儒们也为能够在万圣节期间让他们的招牌糖果出现在联盟各大主城而感到自豪。"},sec={{t="侏儒巧思的滋味",b="虽然联盟各地的旅店老板在万圣节期间都会分发当地的糖果，但流亡的诺莫瑞根侏儒并没有自己的完整主城旅店来经营。取而代之的是，居住在铁炉堡Mystic Ward的富有创造力的侏儒塔瓦斯德·基瑟尔，会把诺莫瑞根橡皮糖发给愿意配合他节日恶作剧的旅行者。尽管放射性灾难驱逐了他的族人，使他们离开了地下王国，但侏儒们仍然自豪地与整个联盟分享他们独特的糖果。"},{t="给耶斯帕尔的款待",b="由于耶斯帕尔生病并被关在暴风城大教堂广场的孤儿院里，他无法亲自前往各地去进行“不给糖就捣蛋”的活动。诺莫瑞根橡皮糖是四种重要的地区糖果之一——另外还有来自暴风城、铁炉堡和达纳苏斯的糖果——善良的旅行者们在联盟各大主城收集这些糖果，将节日的欢乐带给他。"}},faq={{q="诺莫瑞根橡皮糖是从哪里来的？",a="它由塔瓦斯德·基瑟尔提供，这是一位位于铁炉堡Mystic Ward的侏儒修理工。在万圣节期间，如果你为他表演恶作剧，他就会给你这种糖果。",al={"谁发放诺莫瑞根橡皮糖","如何获得橡皮糖","橡皮糖位置"}},{q="为什么这种糖果不是在诺莫瑞根分发的？",a="诺莫瑞根被穴居人占领并遭到辐射污染，迫使幸存的侏儒流亡。许多人，包括塔瓦斯德·基瑟尔，现在都和矮人一起住在铁炉堡。",al={"为什么在铁炉堡","为什么塔瓦斯德在铁炉堡"}},{q="这种糖果有什么用？",a="它是完成万圣节任务所需的四种节日甜点之一，任务是送给暴风城大教堂广场孤儿院里那个生病的孤儿耶斯帕尔。",al={"橡皮糖有什么用","耶斯帕尔的糖果"}},{q="还有什么其他糖果需要一起收集？",a="耶斯帕尔还需要暴风城杏仁糖、铁炉堡薄荷糖和达纳苏斯水果糖，每种糖果都分别在联盟的对应主城中收集。",al={"其他糖果","万圣节糖果"}}},fp="18,146,28.374.0,18.290.0,42.121.0,46.162.0,28.168.0,45.130.0"}
P.entries["item:gnomish-tools"] = {n="侏儒的工具",s="侏儒的工具是从戴林·普罗德摩尔海军上将舰队的沉船中打捞出来的复杂机械装置，这些沉船位于杜隆塔尔海岸外。部落一直在寻找这些打捞上来的设备，以研究联盟的工程技术，并将敌人的技术优势转化为自己的利益。",h="侏儒的工具是从戴林·普罗德摩尔海军上将舰队的沉船中打捞出来的复杂机械装置，这些沉船位于杜隆塔尔海岸外。部落一直在寻找这些打捞上来的设备，以研究联盟的工程技术，并将敌人的技术优势转化为自己的利益。",kw={"杜隆塔尔","工程学","加索克","侏儒的工具","普罗德摩尔","剃刀岭","流亡海岸","提拉加德城堡"},ang={["faction:Horde"]="回收丢失的联盟装备使部落能够研究敌人的设计，逆向工程外来机制，并防范未来的海上入侵。",["profession:Engineering"]="这些工具包展示了联盟修补匠精准而复杂的工艺，为发条装置和微型化技术提供了宝贵的见解。"},sec={{t="沉没的残骸",b="当戴林·普罗德摩尔海军上将率领库尔提拉斯和联盟军队登陆杜隆塔尔时，他的舰队携带了大量的现代化装备，其中包括由他们的侏儒盟友制造的精密装备。在提拉加德城堡以东的流亡海岸，普罗德摩尔的舰队遭到摧毁，这些精致的机械工具包便沉入了海底。如今，防水工具箱仍然散落在浅滩处腐烂的木材和长满藤壶的船体之间。"},{t="奥格瑞玛的注视",b="剃刀岭的监工加索克指派部落斥候从普罗德摩尔海军的水下坟墓中搜寻这些工具。兽人们意识到人类和侏儒拥有先进的工艺技术，特别是在攻城器械、造船和钟表机械方面。通过收集这些工具包并用商队运往奥格瑞玛的工匠和学者手中，部落意在拆解联盟的装置，学习如何对抗他们的战争机器，并将这些外来创新转化为自身的生存优势。"}},faq={{q="为什么杜隆塔尔海岸会有侏儒的工具？",a="当库尔提拉斯进攻杜隆塔尔时，这些工具就装在戴林·普罗德摩尔海军上将舰队的战舰上。当普罗德摩尔的无敌舰队在提拉加德城堡以东的流亡海岸被击溃并沉没时，它们的船载货物便散落在了海底。",al={"为什么这里有侏儒的工具","侏儒的工具的起源","工具是如何来到杜隆塔尔的"}},{q="部落为什么想要这些工具？",a="剃刀岭的加索克希望打捞这些工具，以便将它们送往奥格瑞玛。部落意识到联盟的工程师拥有复杂的机械知识，研究他们的工具可以帮助部落理解敌人的机器是如何运作的，以及如何制造更好的装备。",al={"为什么加索克想要工具","部落使用侏儒的工具的目的","这些工具是做什么用的"}},{q="这些工具在哪里可以找到？",a="它们被存放在散落于杜隆塔尔提拉加德城堡以东、流亡海岸沿线沉船内外的工具箱里。许多工具箱沉在水下或半掩埋在破碎的船体中。",al={"侏儒的工具的位置","哪里可以找到侏儒的工具","侏儒工具箱的位置"}}},fx={bc7dc32b={q="这些侏儒的工具是什么？",a="这些是联盟侏儒制造的专用机械器具。它们以精确和精巧的设计备受珍视，代表着艾泽拉斯最先进的工程技术之一。它们曾被装载在海军上将普라우德摩尔的战舰上，用于维护和修理联盟的先进机械；舰队覆灭后，这些工具散落在杜隆塔尔海岸附近的海底。",al={"什么是侏儒的工具","侏儒的工具信息","侏儒的工具是什么"}}},fp="13,293,14.485.0,17.521.0,53.259.0,36.280.0,26.201.0"}
P.entries["item:gold-dust"] = {n="金砂",s="金砂是由艾尔文森林矿洞中肆虐的狗头人筛分并囤积的珍贵金属碎屑。当普通的矿工还在寻找完整的矿脉时，当地的投机者愿意花大价钱，雇佣任何愿意从这些害虫手中抠出这些微粒的人。",h="金砂是由艾尔文森林矿洞中肆虐的狗头人筛分并囤积的珍贵金属碎屑。当普通的矿工还在寻找完整的矿脉时，当地的投机者愿意花大价钱，雇佣任何愿意从这些害虫手中抠出这些微粒的人。",kw={"艾尔文","法戈第","金砂","闪金镇","金牙","玉石矿洞","狗头人","雷米"},ang={["class:Rogue"]="与雷米这样可疑的人物进行这种未经精炼、无法追踪的砂金交易，是一个关于地下世界如何避开暴风城法官的视线洗白原生财富的生动案例。",["profession:Mining"]="当矿工们用鹤嘴锄和淘金盘寻找坚实的铜矿和锡矿脉时，狗头人的金砂证明了艾尔文森林的地下通道中蕴藏着比标准勘探报告所显示的更丰富的矿藏。"},sec={{t="一袋碎屑",b="在艾尔文森林的土壤之下，狗头人在法戈第矿洞和玉石矿洞的地下隧道中不停地挖掘。这些鼠辈并没有去精炼他们发现的矿石，而是经常将粗糙的金砂直接囤积在口袋和袋子里。这些细小、闪闪发光的碎屑代表了地下拾荒的苦力，虽然容易被正规的矿业财团所忽视，但却深受当地小贩和销赃者的垂涎，他们希望能从中悄悄获利，而不必支付官方的冶炼关税。"},{t="闪金镇的黑市",b="在闪金镇，雷米会积极地向过往的旅行者收购收集到的金砂。雷米声称能给出镇上最好的价格，并代表他那些不愿透露姓名的合伙人用金钱和可疑的代币交换成袋的原生金砂。通过利用富有冒险精神的雇佣兵直接从狗头人手中抢夺黄金，这些小巷里的掮客既能保持双手干净，又能就在暴风城卫兵的眼皮底下获得无法追踪的财富。"}},faq={{q="金砂从哪里来？",a="金砂由整个艾尔文森林的狗头人携带。矿工、隧道工、地卜师以及他们臭名昭著的首领金牙，在挖掘山丘时都会收集并囤积这些闪烁的微粒。",al={"如何获得金砂","金砂掉落","哪里寻找金砂"}},{q="哪些矿洞里携带金砂的狗头人最多？",a="位于闪金镇南部的法戈第矿洞和位于东北部的玉石矿洞，都挤满了携带金砂的狗头人。",al={"矿洞在哪里","金砂的最佳矿洞","矿洞位置"}},{q="在艾尔文森林里谁会购买金砂？",a="雷米，一个在闪金镇Lion's Pride Inn外活动的黑市商人，热衷于收购收集到的金砂袋，并以此交换金钱和他合伙人的代币。",al={"谁想要金砂","雷米金砂","上交金砂"}},{q="为什么狗头人携带的是金砂而不是金锭？",a="狗头人缺乏进行正规冶炼的纪律和基础设施。当他们用简陋的镐头挖掘岩壁时，散落的金砂会附着在他们的物品上，或者被装进他们作为闪亮饰品随身携带的小袋子里。",al={"为什么狗头人有金砂","狗头人黄金"}}},fp="9,140,22.262.0,24.319.1,31.158.0,53.109.0,36.153.0,44.214.0"}
P.entries["item:golm-fragment"] = {n="高尔姆碎片",s="高尔姆碎片是戈阿兹之石缺失的四块碎片之一，戈阿兹之石是在湿地挖掘场发现的一件古代遗物。冒险者们躲过凶猛的迅猛龙将其寻回，它能帮助矮人考古学家拼凑出神秘的泰坦铭文。",h="高尔姆碎片是戈阿兹之石缺失的四块碎片之一，戈阿兹之石是在湿地挖掘场发现的一件古代遗物。冒险者们躲过凶猛的迅猛龙将其寻回，它能帮助矮人考古学家拼凑出神秘的泰坦铭文。",kw={"挖掘场","戈阿兹之石","高尔姆碎片","揭示过去","湿地","维尔加"},ang={["faction:Alliance"]="找回这块碎片有助于探险者协会在挖掘场完全被迅猛龙占据之前，保住无价的古代知识。",["race:Dwarf"]="对于矮人来说，拼凑戈阿兹之石的碎片对于揭示他们的泰坦血统以及埋藏在卡兹莫丹的隐秘历史至关重要。"},sec={{t="戈阿兹之石的一块碎片",b="高尔姆碎片是在湿地南部挖掘场发现的，属于一块被称为戈阿兹之石的宏伟石板。勘察员维尔加在迅猛龙赶走探险者协会之前不久发现了这块石头，但发现其铭文在四个关键部位断裂了。挖掘场被占领时，高尔姆碎片被遗弃在泥土和倾倒的板条箱中，隐藏在一个古老的遗物箱里，直到勇敢的探险者们将其取回。"},{t="泰坦的秘密",b="当与阿多斯、莫德尔和内鲁碎片重新组合时，高尔姆碎片便能拼凑出一段神秘的泰坦文字，预示着“神圣计划”和“毁灭预言”。重组石板后，维尔加得以破译其中提及被锁在地下古代实体的几行文字，这证实了该遗址所蕴含的知识远比单纯的矮人遗产更为古老且危险。"}},faq={{q="高尔姆碎片有什么用？",a="它是勘察员维尔加在湿地挖掘场完成任务“揭示过去”所需四块石片中的一块，用于修复戈阿兹之石。",al={"高尔姆碎片用途","为何需要高尔姆碎片","高尔姆碎片任务"}},{q="在哪里可以找到高尔姆碎片？",a="它位于湿地南部丘陵地区，散落在被迅猛龙盘踞的挖掘场各处的古代遗物和松散土壤中。",al={"高尔姆碎片位置","寻找高尔姆碎片","高尔姆碎片在哪里"}},{q="戈阿兹之石拼好后写了什么？",a="维尔加初步翻译的内容提到了神圣计划和毁灭预言。他需要所有四块碎片才能继续解读残缺的泰坦文字。",al={"戈阿兹之石翻译","石板上写了什么","维尔加翻译"}},{q="还需要哪些其他碎片来完成石板？",a="除了高尔姆碎片，你还必须找回阿多斯、莫德尔和内鲁碎片才能完整拼凑石板。",al={"其他石板碎片","戈阿兹之石碎片","四块碎片"}}},fx={["523a83d7"]={q="什么是高尔姆碎片？",a="高尔姆碎片是从古代遗物戈阿兹之石上脱落的四块遗失碎片之一；这件遗物是在湿地的挖掘现场发现的。碎片上刻有古老铭文，补充了整块石板晦涩叙述的一部分。",al={"什么是高尔姆碎片","高尔姆碎片背景","高尔姆碎片是什么"}},["890266ad"]={q="高尔姆碎片来自哪里？是谁制作的？",a="这块碎片原本属于戈阿兹之石，很久以前以泰坦文字雕刻而成。矮人在湿地的挖掘现场进行考古发掘时将其出土，随后凶猛的迅猛龙袭击了该地区，并使石板碎片散落各处。",al={"谁制作了高尔姆碎片","高尔姆碎片的起源","高尔姆碎片来自哪里"}},["6695e471"]={q="勘察员维尔加为什么要高尔姆碎片？",a="勘察员维尔加需要高尔姆碎片和其他几块碎片一起拼成完整的戈阿兹之石。缺少它，译文就会戛然而止，关于神圣计划和注定应验的预言的重要细节也会因此缺失。",al={"维尔加为什么需要高尔姆碎片","谁想要高尔姆碎片","为什么寻找高尔姆碎片"}}},fp="13,266,25.462.0,21.363.1,35.155.0,37.137.0,44.157.1,52.98.0"}
P.entries["item:gordon-s-crate"] = {n="高顿的箱子",s="高顿的箱子是一批在幽暗城打包好的重型武器补给，专供驻扎在银松森林的被遗忘者部队使用。这批至关重要的补给物资需要直接运送到瑟伯切尔的偏远驻地。",h="高顿的箱子是一批在幽暗城打包好的重型武器补给，专供驻扎在银松森林的被遗忘者部队使用。这批至关重要的补给物资需要直接运送到瑟伯切尔的偏远驻地。",kw={"蝙蝠管理员","亡灵卫兵博迪瑞格","高顿的箱子","卡洛斯·拉佐克","迈克尔·加勒特","银松森林补给","瑟伯切尔","幽暗城"},ang={["faction:Horde"]="这次运送展示了被遗忘者飞行航线日益整合的趋势，使得补给和信使能够迅速穿过交战中的洛丹伦。",["race:Undead"]="每一批从首都运来的刀剑和装备，都巩固了希尔瓦娜斯女王在银松森林那摇摇欲坠的边境防线。"},sec={{t="银松森林的补给",b="为了维持被遗忘者对银松森林的控制，需要从幽暗城进行持续的后勤补给。高顿的箱子内装有旨在加强瑟伯切尔亡灵卫兵博迪瑞格防线的武器装备，以确保哨所的卫兵不会被森林中潜伏的狼人、野兽或人类残部打个措手不及。"},{t="蝙蝠管理员的航线",b="由于离开首都的陆路既危险又缓慢，贵重物资的运输必须依赖幽暗城的蝙蝠管理员。这批箱子会被交给位于城市Trade Quarter上方的蝙蝠训练师迈克尔·加勒特，他会将货物固定在受过训练的飞行蝙蝠背上，将其运回瑟伯切尔的卡洛斯·拉佐克的栖木处。"}},faq={{q="高顿的箱子里有什么？",a="箱子里装有从幽暗城征调的武器和重要的战斗补给，用于加强驻扎在银松森林的亡灵卫兵哨所。",al={"高顿的箱子内容物","箱子里装什么"}},{q="谁应该接收高顿的箱子？",a="瑟伯切尔的亡灵卫兵博迪瑞格负责接收这批箱子。运输该货物需要与幽暗城的蝙蝠管理员迈克尔·加勒特协调，以安排直飞航线。",al={"谁接收高顿的箱子","箱子运往何处"}},{q="为什么箱子是通过蝙蝠运输而不是由信使徒步运送？",a="银松森林依然处于交战状态，充满危险。使用像迈克尔·加勒特和卡洛斯·拉佐克这样的管理员所看管的训练有素的蝙蝠，可以确保快速的空中转运，从而避开陆路上的敌对威胁。",al={"为什么要空运箱子","蝙蝠运输箱子"}},{q="为什么迈克尔·加勒特要求你先去瑟伯切尔？",a="被遗忘者的蝙蝠会本能地返回首都，但为了安全抵达像瑟伯切尔这样的外围基地，旅行者必须先与当地的管理员卡洛斯·拉佐克建立联系，蝙蝠才能完成这段航程。",al={"为什么需要飞行点","蝙蝠飞行要求"}}},fx={df26763c={q="什么是高顿的箱子？",a="高顿的箱子里装着在幽暗城打包的重要武器和军用物资。这批物资专门准备通过蝙蝠管理员运往瑟伯切尔的偏远被遗忘者哨站。",al={"高顿的箱子","这是什么箱子"}},e23fc119={q="高顿的箱子来自哪里？是谁制作的？",a="箱子来自幽暗城。高顿在那里将驻军物资装进箱子，然后安排蝙蝠管理员运送。",al={"高顿的箱子来自哪里","谁打包了高顿的箱子","谁制作了高顿的箱子"}},a5301c7a={q="为什么有人想要高顿的箱子？",a="亡灵卫兵博迪瑞格和驻扎在瑟伯切尔的士兵急需这批物资。箱子里装有必要的武器，确保当地守卫银松森林的亡灵卫兵装备精良，不会在面对敌人时措手不及。",al={"为什么需要高顿的箱子","为什么要把高顿的箱子带到瑟伯切尔","谁需要高顿的箱子"}}},fp="14,240,23.322.0,23.309.0,30.150.0,42.163.0,65.209.0,66.220.0"}
P.entries["item:grape-manifest"] = {n="葡萄出货单",s="葡萄出货单是一份手写的账目，记录了北郡山谷中米莉·奥斯沃斯葡萄园的收成。它记录了在当地强盗占领农田后，被追回并送往北郡修道院地窖的新鲜水果。",h="葡萄出货单是一份手写的账目，记录了北郡山谷中米莉·奥斯沃斯葡萄园的收成。它记录了在当地强盗占领农田后，被追回并送往北郡修道院地窖的新鲜水果。",kw={"尼尔斯修士","艾尔文","葡萄出货单","米莉·奥斯沃斯","北郡修道院","葡萄园","葡萄酒"},ang={["profession:Cooking"]="对于厨师来说，这份清单代表了田间产量与修道院粮仓之间微妙的平衡，展示了当地食材如何维持整个修道院社区的运转。",["race:Human"]="这份文件突显了暴风城腹地早期的艰苦岁月，在那里，即使是修道院的生活和简单的收获，也需要武装防御来抵御四处游荡的亡命之徒。"},sec={{t="收成记录",b="北郡修道院长期以来依靠区域农业自给自足，其中包括像米莉·奥斯沃斯这样的当地农民所打理的肥沃葡萄园。当迪菲亚强盗进入山谷并抢走收成时，修道院的新鲜水果和酿造原料库存便陷入了危机。葡萄出货单作为官方确认文件，证明了这些板条箱已从田野中被追回。它详细记录了挽救下来的葡萄数量，以便修道院的军需官能够平衡库存，并准备发酵用的木桶。"},{t="修道院的酒窖管理员",b="尼尔斯修士负责管理北郡的食品和饮料，他特别喜欢在高高的钟楼静谧之处品尝修道院的陈酿。对他而言，收到这份清单不仅仅是行政文书工作，它还确保了修士们和来访的新兵不会口渴。对于修道院虔诚的修士们来说，每一桶被挽救的葡萄，既被视为后勤上的胜利，也被视为圣光赐予的默默祝福。"}},faq={{q="什么是葡萄出货单？",a="这是一份由米莉·奥斯沃斯编写的库存文件，记录了从她被占领的葡萄园中追回的收成。它追踪着送往北郡修道院的新鲜葡萄总量。",al={"什么是葡萄出货单","葡萄出货单物品"}},{q="谁会收到这份清单？",a="尼尔斯修士会收到它。他负责监管修道院的食物和葡萄酒储备，通常可以在北郡修道院的钟楼里找到他，他会在那里品尝陈酿。",al={"谁接收葡萄出货单","我该把葡萄出货单交给谁","葡萄出货单交给哪里"}},{q="为什么葡萄会有危险？",a="迪菲亚强盗袭击了北郡山谷，并将米莉·奥斯沃斯赶出了她的葡萄园，威胁到收成并切断了修道院的新鲜水果供应，直到有新兵介入干预。",al={"为什么葡萄需要被拯救","葡萄园强盗","米莉的收成发生了什么"}},{q="尼尔斯修士用这些葡萄做什么？",a="尼尔斯修士用它们来补充修道院的食物储备，并酿造新鲜的北郡葡萄酒，供驻地的修士和来访的守卫者使用。",al={"葡萄的用途是什么","修道院葡萄酒"}}},fp="14,173,23.388.0,20.332.0,27.185.0,26.142.0,30.184.0,43.153.0"}
P.entries["item:gray-bear-tongue"] = {n="灰熊的舌头",s="灰熊的舌头是从希尔斯布莱德丘陵的野熊身上采集到的一种原始试剂。塔伦米尔的皇家药剂师协会一直在搜寻这种材料，将其用作实验性毒素中的生物成分。",h="灰熊的舌头是从希尔斯布莱德丘陵的野熊身上采集到的一种原始试剂。塔伦米尔的皇家药剂师协会一直在搜寻这种材料，将其用作实验性毒素中的生物成分。",kw={"药剂师林度恩","大萨姆拉斯","受难药剂","灰熊的舌头","希尔斯布莱德丘陵","皇家药剂师协会","塔伦米尔"},ang={["race:Undead"]="从当地野生动物身上获取有机成分，能够直接支持皇家药剂师协会制造针对活人的新型瘟疫的任务。"},sec={{t="希尔斯布莱德的药剂师研究",b="塔伦米尔周围的荒野中栖息着丰富的本土动物，其中包括多种强壮的灰熊。虽然这些天生的掠食者对旅行者构成了持续的威胁，但被遗忘者却将它们视为可采集的原始炼金原料。药剂师林度恩通过研究当地的野生动物来分离强效的有机药剂，并使用灰熊的舌头这一沉重的肌肉组织及其分泌的体液，作为调制诸如受难药剂等致命溶液的基础成分。"}},faq={{q="谁需要灰熊的舌头？",a="驻扎在希尔斯布莱德丘陵塔伦米尔的被遗忘者哨所的药剂师林度恩，正在寻求这些舌头来酿造实验性的杀戮药剂。",al={"谁需要灰熊的舌头","药剂师林度恩 舌头","灰熊的舌头提交"}},{q="药剂师用这些舌头做什么？",a="林度恩正在开发一种名为受难药剂的致命药剂，旨在用它来瘟疫化希尔斯布莱德的活人居民。这些舌头与食苔蛛的毒液一样，是该药剂的主要有机成分之一。",al={"林度恩为什么需要舌头","灰熊的舌头用途","受难药剂配方"}},{q="哪些生物掉落这些舌头？",a="你可以从漫游在希尔斯布莱德丘陵的任何当地灰熊身上采集到，包括普通的灰熊、年长的灰熊、凶残的灰熊以及臭名昭著的野兽大萨姆拉斯。",al={"灰熊的舌头掉落","哪些熊有舌头","希尔斯布莱德的熊"}}},fx={["57051fe5"]={q="什么是灰熊的舌头？",a="它就是字面上的意思：从希尔斯布莱德丘陵四处游荡的野生灰熊身上刚割下来的舌头。大多数旅行者对此毫无兴趣，但被遗忘者中的炼金师和研究人员在调制新药剂时，会看重动物组织特有的化学性质。",al={"什么是灰熊的舌头","灰熊的舌头物品"}},["4de594f1"]={q="灰熊的舌头来自哪里？",a="这些舌头直接取自希尔斯布莱德丘陵塔伦米尔周围森林和山丘上的灰熊。猎人可以从普通灰熊、年长的灰熊、凶猛的变种，或大萨姆拉斯这类知名野兽身上取得舌头。",al={"灰熊的舌头来源","灰熊的舌头来自哪里","谁会掉落灰熊的舌头"}}},fp="16,229,32.479.0,28.151.0,47.220.0,35.192.0"}
P.entries["item:gregor-s-remains"] = {n="格里高的遗骸",s="格里高的遗骸是曾被天灾军团奴役的格里高·阿加曼德残留的骨骸。他曾是提瑞斯法林地最富有家族的一员，如今，一位曾经的磨坊工人为了从死后世界寻求清算往日的宿怨，正在寻找他的遗骸。",h="格里高的遗骸是曾被天灾军团奴役的格里高·阿加曼德残留的骨骸。他曾是提瑞斯法林地最富有家族的一员，如今，一位曾经的磨坊工人为了从死后世界寻求清算往日的宿怨，正在寻找他的遗骸。",kw={"阿加曼德","布瑞尔","库勒曼","家族死亡","farthing","格里高","磨坊","遗骸","天灾军团"},ang={["faction:Horde"]="清扫阿加曼德磨坊是对威胁提瑞斯法林地安全的残留天灾势力的一次直接打击。",["race:Undead"]="阿加曼德家族的悲剧是许多被遗忘者命运的缩影：普通百姓被贵族的傲慢所背叛，最终被遗弃在瘟疫的恐怖之中。"},sec={{t="毁灭的遗产",b="第三次战争之前，阿加曼德家族在提瑞斯法林地北部拥有巨额财富和广袤的土地。当亡灵天灾入侵洛丹伦时，家族长辈选择了傲慢而非逃离，他们加固了家族磨坊，并说服忠诚的劳工们誓死抵御亡灵。这次防御彻底失败了。庄园被践踏，那些坚守阵地的人遭到屠杀并被复活为亡灵。格里高·阿加曼德成为了巫妖王麾下又一个毫无心智的奴仆，在这片他家族曾经统治的磨坊中徘徊。"},{t="复仇的代价",b="对于那些摆脱了巫妖王控制并加入被遗忘者的幸存者来说，那场惨烈防御的记忆依然是一道痛苦的伤疤。驻扎在布瑞尔的磨坊前工人库勒曼·法席恩将灵魂被困在永恒腐朽中的原因归咎于阿加曼德家族的傲慢。收集格里高的遗骸让法席恩获得了一定程度的个人报复，也终结了这段由一位将家族引向毁灭的主人所书写的篇章。"}},faq={{q="格里高·阿加曼德是谁？",a="格里高·阿加曼德是阿加曼德家族的重要成员，该家族是第三次战争前提瑞斯法林地最富有的地主家族。当亡灵瘟疫降临时，他和他的家人选择固守庄园而非逃离，最终导致庄园内所有人被屠杀并复活。",al={"格里高背景故事","格里高是谁","格里高·阿加曼德"}},{q="为什么库勒曼·法席恩想要格里高的遗骸？",a="库勒曼·法席恩生前是阿加曼德家族雇佣的磨坊工人。他深恨该家族说服工人们留下来对抗天灾军团，正是这个愚蠢的决定让所有人沦为亡灵。将格里高的遗骸带给他，算是迟来的复仇。",al={"为什么库勒曼想要遗骸","库勒曼·法席恩的怨恨","为什么收集格里高的骨头"}},{q="格里高的遗骸在哪里可以找到？",a="这些遗骸是从位于提瑞斯法林地北部山丘中的阿加曼德磨坊里，那个复活后的格里高·阿加曼德身上回收的。",al={"格里高在哪里","格里高位置","阿加曼德磨坊 格里高"}},{q="阿加曼德家族是被遗忘者的一部分吗？",a="不是。与希尔瓦娜斯女王麾下获得自由的被遗忘者不同，格里高·阿加曼德和他的族人依然是被锁链束缚在天灾军团意志下的无心智奴仆。",al={"格里高是被遗忘者吗","阿加曼德家族是天灾吗","谁在控制格里高"}}},fx={["45ae8d93"]={q="格里高的遗骸从何而来？",a="这些遗骸是格里高·阿加曼德在提瑞斯法林地西部的阿加曼德磨坊遭到击杀后留下的残骸。天灾军团席卷洛丹伦时，他的家族加固了庄园，并敦促工人们留下来战斗，结果所有人都被屠杀，继而沦为亡灵。",al={"格里高的遗骸来源","谁制造了格里高的遗骸","格里高的遗骸从何而来"}},["6dd1de2a"]={q="什么是格里高的遗骸？",a="它们是格里高·阿加曼的实体遗骸，他是声名显赫的阿加曼家族继承人之一。格里高死于亡灵瘟疫后，成为天灾军团的无意识爪牙，在家族昔日繁荣的磨坊废墟中游荡，直到被彻底消灭。",al={"什么是格里高的遗骸","格里高的遗骸物品","格里高的遗骸是什么"}}},fp="16,246,16.557.0,22.424.0,23.299.0,48.276.0,33.135.0,38.148.0"}
P.entries["item:grelin-s-report"] = {n="格瑞林的报告",s="《格瑞林的报告》是一份由格瑞林·白须撰写的公文，详细说明了寒脊山谷的霜鬃巨魔局势。这份报告被托付给了一位冒险者，而非新手学徒，它是守卫安威玛尔的侦察兵与驻扎在卡拉诺斯的森内尔·白须之间的官方联系纽带。",h="《格瑞林的报告》是一份由格瑞林·白须撰写的公文，详细说明了寒脊山谷的霜鬃巨魔局势。这份报告被托付给了一位冒险者，而非新手学徒，它是守卫安威玛尔的侦察兵与驻扎在卡拉诺斯的森内尔·白须之间的官方联系纽带。",kw={"寒脊山谷","格瑞林·白须","格瑞林的报告","铁炉堡议会","卡拉诺斯","巡山人萨鲁斯","森内尔·白须"},ang={["race:Dwarf"]="携带这份报告，意味着矮人从安全的寒脊山谷训练场走向了保卫丹莫罗腹地的更广阔战场，并开始为铁炉堡效力。",["race:Gnome"]="运送格瑞林的信件，让侏儒难民在穿行丹莫罗的山间小径时，有机会向矮人巡山人证明自己的勇气。"},sec={{t="一份送往穴居人防线后的公文",b="《格瑞林的报告》在观察了寒脊山谷的霜鬃巨魔后得出结论：这些巨魔并未构成重大威胁，由当地驻扎的巡山人和领取议会资金的雇佣兵即可应付。格瑞林认为他的学徒笨手笨脚，无法承载如此重要的情报，于是雇佣了一名能干的旅行者带着文件穿过穴居人横行的寒脊山小径。这份文件就像是一张通行证，让持有人得以通过巡山人萨鲁斯的封锁线，证明持有人有紧急公务，需前往更广阔的丹莫罗雪原。"},{t="在卡拉诺斯引发不满",b="当这份报告被送到卡拉诺斯雷酒酿制厂的森内尔·白须手中时，它提供了旨在传达给铁炉堡的关键战地情报。森内尔带着几分自嘲的无奈指出，他的兄弟在文中多次借用了国王麦格尼·铜须的名义。格瑞林声称此举得到了国王的批准，而森内尔预料到这种诉诸王权的行为必然会触怒铁炉堡议会的权贵。"}},faq={{q="《格瑞林的报告》的目的是什么？",a="这份报告承载了格瑞林·白须对寒脊山谷霜鬃巨魔的评估，旨在将其传达给身在卡拉诺斯的兄弟森内尔。它向谷外的领导层保证，这些巨魔并未构成重大威胁，当地的巡山人和议会资助的雇佣兵完全有能力处理。",al={"什么是格瑞林的报告","为什么要寄送这份报告","格瑞林的报告的目的"}},{q="格瑞林为什么不能亲自去送？",a="格瑞林需要留在寒脊山谷监视巨魔。虽然他最初考虑过让学徒去送信，但考虑到穿过穴居人出没的隧道的旅途太过危险，他还是决定将这份重要的文件交给一位久经沙场的冒险者。",al={"为什么不亲自去送","为什么要托付给冒险者"}},{q="巡山人萨鲁斯为什么会让你带着报告通过？",a="巡山人萨鲁斯守卫着寒脊山谷外的隧道，以保护平民免受邪恶穴居人的侵害。持有《格瑞林的报告》证明你正在执行紧急的矮人防务公务，从而说服萨鲁斯放行。",al={"萨鲁斯为什么放我过去","隧道封锁","寒脊山小径的穴居人"}},{q="铁炉堡议会为什么会对这份报告感到恼火？",a="森内尔·白须指出，格瑞林在文件中多次借用了麦格尼国王的名义。绕过常规的外交辞令直接要求王室关注，往往会激怒铁炉堡议会的官僚们，尽管兄弟俩都认为那些政客需要当头棒喝。",al={"为什么议会生气","引起不满","森内尔的反应"}}},fx={cdcce173={q="什么是格瑞林的报告？",a="这是一份由格瑞林·白须在寒脊山谷撰写的书面报告，收件人是住在卡拉诺斯的兄弟森内尔·白须。报告详细记录了山谷里的见闻和亟待处理的事务。不过，格瑞林在报告中频繁搬出国王麦格尼·铜须的名号，足以让铁炉堡的参议员们对此议论纷纷。",al={"什么是格瑞林的报告","格瑞林的报告"}},["9a092709"]={q="格瑞林的报告从何而来？是谁写的？",a="这份文件由驻守寒脊山谷的格瑞林·白须起草。格瑞林没有把它托付给自己的学徒，而是决定交给一位可靠的旅行者，确保报告能安全地向东穿过通往丹莫罗腹地、遍布穴居人的隧道。",al={"谁写了格瑞林的报告","格瑞林的报告从何而来","谁制作了格瑞林的报告"}},["6be6ebf1"]={q="为什么有人需要格瑞林的报告？",a="他的兄弟森内尔·白须正在卡拉诺斯等候这份报告，以便汇总两人的发现，再将合并后的报告送往铁炉堡。这份文件对你本人也至关重要：出示白须家族公务的证明，是巡山人萨鲁斯允许你通过离开寒脊山谷、危机四伏且穴居人横行的隧道的唯一理由。",al={"为什么需要格瑞林的报告","森内尔为什么需要格瑞林的报告"}}},fp="15,291,26.564.0,29.414.0,39.279.0,36.253.0,57.230.0,50.280.0"}
P.entries["item:grelin-whitebeard-s-journal"] = {n="格瑞林·白须的日记",s="格瑞林·白须的日记是矮人侦察兵格瑞林·白须在寒脊山谷记录的一本个人实地笔记。这本笔记记录了当地霜鬃巨魔活动的关键情报，后来被霜鬃蛮兵格里克尼尔·寒冷抢走，并拖进了寒脊山谷的巨魔洞穴中。",h="格瑞林·白须的日记是矮人侦察兵格瑞林·白须在寒脊山谷记录的一本个人实地笔记。这本笔记记录了当地霜鬃巨魔活动的关键情报，后来被霜鬃蛮兵格里克尼尔·寒冷抢走，并拖进了寒脊山谷的巨魔洞穴中。",kw={"寒脊山谷","丹莫罗","霜鬃巨魔要塞","格瑞林·白须","格里克尼尔·寒冷","森内尔·白须","被偷的日记"},ang={["race:Dwarf"]="找回这本日记可以保障关于霜鬃巨魔威胁的重要矮人情报，这些威胁正在侵蚀铁炉堡训练场的大门。"},sec={{t="侦察兵手册",b="在观察寒脊山谷附近霜鬃巨魔的侵略性动向时，格瑞林·白须将他的发现勤勉地记录在这本皮装笔记中。这份文件包含了关于当地冬日巨魔的兵力、组织架构和威胁程度的原始实地观察记录。然而，在一次冲突或伏击中，这本日记被一个身上有着明显标记的巨魔蛮兵——格里克尼尔·寒冷抢走了，这迫使格瑞林招募路过的冒险者潜入巨魔洞穴，并在报告最终完成前将其夺回。"},{t="寄往森内尔的公文",b="从格里克尼尔手中夺回这本破旧的日记后，其中的笔记为格瑞林评估寒脊山谷的巨魔威胁已暂时得到遏制提供了依据。利用恢复的记录，格瑞林完成了关于霜鬃巨魔起义的书面公文，随后将其密封并托付给信使，送往身处丹莫罗远方的他的兄弟森内尔·白须手中。"}},faq={{q="是谁偷走了格瑞林·白须的日记？",a="这本日记是被格里克尼尔·寒冷抢走的，他是一个臭名昭著且身上有明显标记的霜鬃巨魔蛮兵，居住在寒脊山谷的巨魔洞穴深处。",al={"谁拿走了日记","谁拥有格瑞林的日记","格瑞林日记的窃贼"}},{q="日记里写了什么？",a="这本日记包含了格瑞林·白须关于当地霜鬃巨魔的直接侦察笔记，以及它们的威胁程度和寒脊山谷内部的安全状况。",al={"日记内容","日记里有什么","格瑞林·白须的笔记"}},{q="日记找回后会发生什么？",a="在找回他的笔记后，格瑞林利用这些记录撰写了一份关于巨魔局势的最终情报报告，随后他请求一名冒险者将其送到他的兄弟森内尔·白须手中。",al={"格瑞林用日记做什么","被偷的日记之后"}},{q="为什么这本日记对格瑞林如此重要？",a="没有这本笔记，格瑞林就无法为矮人当局和他的兄弟森内尔汇总一份关于霜鬃巨魔起义的准确侦察报告，这会导致寒脊山谷的防御处于不确定的状态。",al={"为什么格瑞林想要回它","日记的重要性"}}},fx={["15978139"]={q="什么是格瑞林·白须的日记？",a="这是驻守寒脊山谷的观察者格瑞林·白须所写的私人笔记。格瑞林在其中记录了当地霜鬃巨魔的活动情况，并撰写野外报告，详细说明山谷的防御状况。",al={"什么是格瑞林·白须的日记","格瑞林的日记","格瑞林的笔记本"}},["9ed18e74"]={q="格瑞林·白须的日记从何而来？是谁写的？",a="这本日记由矮人格瑞林·白须在守望寒脊山谷期间亲自编写。不过，它被霜鬃蛮兵格里克尼尔·寒风从他手中抢走，并带进了附近的巨魔洞穴深处。",al={"谁写了格瑞林的日记","格瑞林的日记从何而来","格瑞林日记的来源"}}},fp="27,297,16.570.0,17.417.1,38.153.0,31.175.0,44.195.1,43.195.0"}
P.entries["item:grell-earring"] = {n="劣魔耳环",s="劣魔耳环是居住在巴莎兰废墟中的野性生物搜刮并佩戴的粗糙饰品。乍看之下这些饰品平平无奇，但因为它们靠近古代遗物，敏感的灵魂可以借此追踪到将其困于折磨之中的残留魔法封印。",h="劣魔耳环是居住在巴莎兰废墟中的野性生物搜刮并佩戴的粗糙饰品。乍看之下这些饰品平平无奇，但因为它们靠近古代遗物，敏感的灵魂可以借此追踪到将其困于折磨之中的残留魔法封印。",kw={"阿斯特利安","巴莎兰","黑海岸","劣魔耳环","封印","邪恶小精灵","野性劣魔"},ang={["class:Mage"]="这些耳环展示了无生命的金属如何能被动吸收并长期保留古代防御封印的环境魔法特征。",["race:NightElf"]="看到神圣的精灵废墟被佩戴着搜刮来的黄铜饰品的小偷小精灵所占据，这是一种痛苦的提醒，让人意识到曾经宏伟的卡利姆多古老庄园已经没落到了何种地步。"},sec={{t="黄铜中的痕迹",b="潜伏在巴莎兰倒塌大理石建筑周围的野性劣魔和邪恶小精灵囤积了各种小饰品，经常用他们在废墟中搜刮的废料制作耳环。对于大多数凡人来说，这些物品只是毫无价值的垃圾。然而对于阿斯特利安来说——一个作为受折磨的幽灵被困在废墟中的古代暗夜精灵——它们却是探寻工具。通过仔细检查这些耳环吸收的共鸣魔法痕迹，阿斯特利安试图定位禁锢他幽灵形态的古代封印。"}},faq={{q="劣魔耳环从哪里来？",a="它们是从居住在黑海岸的暗夜精灵废墟巴莎兰的野性劣魔和邪恶小精灵的尸体上收集到的。",al={"劣魔耳环掉落","在哪里获得劣魔耳环","谁掉落劣魔耳环"}},{q="为什么阿斯特利安需要这些耳环？",a="阿斯特利安是一个被强大魔法囚禁在巴莎兰的古代灵魂。他利用这些耳环作为魔法导管，来探测附近那个将他的灵魂束缚了几个世纪的封印的痕迹。",al={"阿斯特利安的耳环","为什么要收集劣魔耳环","劣魔耳环的用途"}},{q="这些耳环如何帮助阿斯特利安寻找封印？",a="阿斯特利安希望通过在这些耳环上施展法术，来追踪那个将他的幽灵形态囚禁在巴莎兰的魔法封印。",al={"耳环有魔法吗","劣魔懂魔法吗"}},{q="阿斯特利安能从耳环中找到他需要的东西吗？",a="耳环本身并没有封印，但检查它们可以发现这些生物最近曾与封印接触过，从而将搜寻引导至周围废墟更深处。",al={"耳环起作用了吗","阿斯特利安的封印位置"}}},fx={f6dd1a4f={q="什么是劣魔耳环？",a="劣魔耳环是盘踞在黑海岸巴莎兰废墟中的野生劣魔和邪恶精灵佩戴的一种普通饰品。这些耳饰本身只是寻常小玩意，但它们是生物从废墟中搜寻而来，并吸收了废墟及生物接触过的遗物散发出的微弱魔法气息。",al={"什么是劣魔耳环","劣魔耳环背景"}}},fp="13,264,19.508.0,34.141.0,38.190.0,54.131.0,51.182.0"}
P.entries["item:grenka-s-claw"] = {n="格林卡的爪子",s="格林卡的爪子是一件从飞羽洞穴深处强大的鹰身人血叫者格林卡身上获取的战利品。将它交给老屋的多恩·平原行者，即是证明一位有志向的冒险者已经在峡谷高地经受住了严酷的体能考验，这是无可辩驳的证据。",h="格林卡的爪子是一件从飞羽洞穴深处强大的鹰身人血叫者格林卡身上获取的战利品。将它交给老屋的多恩·平原行者，即是证明一位有志向的冒险者已经在峡谷高地经受住了严酷的体能考验，这是无可辩驳的证据。",kw={"多恩·平原行者","血叫者格林卡","格林卡的爪子","鹰身人","飞羽洞穴","尖啸峡谷","耐力试炼","千针石林","老屋"},ang={["faction:Horde"]="肃清飞羽洞穴的深处并除掉血叫者格林卡，可以削弱时刻骚扰乱风岗周围旅者的鹰身人威胁。",["race:Tauren"]="多恩·平原行者长者视通过牛头人的智慧和磨砺来锻炼年轻的部落勇士为己任，以此让他们在面对更广阔、更残酷的世界之前做好准备。"},sec={{t="耐力试炼的战利品",b="在乱风岗以西的飞羽洞穴蜿蜒的洞窟中，鹰身人囤积食物，并暴力地抵御外来者以保护她们的领地。为了考验年轻勇士的身体韧性，多恩·平原行者派遣他们深入巢穴，摧毁兽群的食物储备。这种肆无忌惮的挑衅必然会招致血叫者格林卡的愤怒。斩下并带回她那邪恶的利爪，证明了一名战士能够经受住一波又一波愤怒鹰身人的攻击，并在她们族母的凶猛攻势下幸存。"}},faq={{q="格林卡的爪子有什么用？",a="这只爪子是多恩·平原行者的胜利证明。多恩·平原行者是一位居住在千针石林老屋的牛头人长者。将爪子交给他即完成了“耐力试炼”，证明你拥有在持久战斗中生存所需的体魄与韧性。",al={"格林卡的爪子用途","为什么需要格林卡的爪子","格林卡的爪子任务"}},{q="血叫者格林卡是谁？",a="血叫者格林卡是一位强大的鹰身人，她栖息在飞羽洞穴内，该洞穴位于千针石林南部悬崖边的尖啸峡谷。只有当入侵者通过摧毁她们储存的食物来威胁到族群时，她才会现身。",al={"格林卡是谁","血叫者格林卡背景故事","什么是格林卡"}},{q="拿到爪子后该交给谁？",a="将爪子带回位于千针石林悬崖上的老屋，交给多恩·平原行者。他会接受这件战利品，以核实你的体能试炼已顺利完成。",al={"格林卡的爪子交接地点","谁想要格林卡的爪子"}},{q="为什么多恩·平原行者指定要这个战利品？",a="多恩·平原行者引导年轻的旅者进行严格的试炼，以确保他们从精神上、意志上和体能上都做好了应对更大危险的准备。击杀格林卡并获取她的爪子，证明了一名战士既能忍受蜂拥而至的伏击，也能承受致命首领的直接猛攻。",al={"为什么多恩需要爪子","爪子的目的"}}},fx={cd538a11={q="什么是格林卡的爪子？",a="格林卡的爪子是从格林卡·血啸身上取得的实物战利品。她是一只强大的鹰身人，栖身于尖啸峡谷深处的飞羽洞穴。激怒她的族群并从其怒火下幸存后，你从这只凶恶的生物身上割下了这只爪子。它是无可辩驳的证明，表明一名有志成为冒险者的人拥有足够的耐力和战斗本领，能够经受住一场残酷的战斗考验。",al={"格林卡的爪子","什么是格林卡的爪子","关于格林卡的爪子"}}},fp="13,294,21.537.0,31.263.0,27.249.0,42.191.0,55.290.0"}
P.entries["item:grimtotem-satchel"] = {n="恐怖图腾背包",s="恐怖图腾背包是玛尔·恐怖图腾这位阵亡的牛头人在怒焰裂谷深处紧紧抓住的一个皮囊。即便在奥格瑞玛地下的岩洞中被穴居人淹没时，玛尔也在临死前拼命护住了这个背包。取回它并交给雷霆崖，便能揭示长者高地的长者之母玛加萨·野性图腾对她族人所携带的东西有着浓厚的兴趣。",h="恐怖图腾背包是玛尔·恐怖图腾这位阵亡的牛头人在怒焰裂谷深处紧紧抓住的一个皮囊。即便在奥格瑞玛地下的岩洞中被穴居人淹没时，玛尔也在临死前拼命护住了这个背包。取回它并交给雷霆崖，便能揭示长者高地的长者之母玛加萨·野性图腾对她...",kw={"长者高地","恐怖图腾","玛加萨·野性图腾","玛尔·恐怖图腾","怒焰裂谷","拉哈罗","背包","雷霆崖","穴居人"},ang={["faction:Horde"]="在一处萨尔首都下方的隧道深处发现一名已故的恐怖图腾信使，这表明怒焰裂谷的危险远不止是简单的野兽出没。",["race:Tauren"]="发现一名恐怖图腾成员在奥格瑞玛深处活动并向长者高地的玛加萨汇报，凸显了恐怖图腾在统一的牛头人部族内部微妙且不安的政治手段。"},sec={{t="垂死一握",b="这个简单的背包是在怒焰裂谷深处，玛尔·恐怖图腾残破的尸体下被发现的，他死前曾以一种凶猛的、钳子般的姿态紧紧抱着它。在被凶残的穴居人包围并杀害时，玛尔拼命想要保护它所携带的物品。那种宁可献出生命也要护住背包的坚定意志，说明里面的东西远比普通的干粮或补给重要得多。"},{t="长者之母的兴趣",b="将背包带给雷霆崖长者高地的拉哈罗，更大的谜团便随之展开。拉哈罗代表恐怖图腾氏族的族长玛加萨·野性图腾收下了这个背包。玛尔曾是玛加萨的仆从，有消息称他在死前于奥格瑞玛下方的洞穴中发现了某种奇特的东西；玛加萨专门安排了奖励以求将其安全取回，这表明恐怖图腾的高层在这些充斥着穴居人的裂谷中有着蓄意且隐秘的图谋。"}},faq={{q="在哪里可以找到恐怖图腾背包？",a="这个背包是在怒焰裂谷深处，即奥格瑞玛下方的火山洞穴中发现的。它被压在玛尔·恐怖图腾的尸体下，当他在洞穴中倒在穴居人手下时，背包正被他紧紧护在怀里。",al={"背包位置","背包在哪里","如何找到背包"}},{q="这个背包属于谁？",a="它属于玛尔·恐怖图腾，他是进入怒焰裂谷的恐怖图腾氏族成员。即便在死后，他的双臂依然紧紧包裹着这个背包，以保护其中的内容物免受来袭穴居人的破坏。",al={"背包拥有者","玛尔背包主人"}},{q="谁想取回这个背包？",a="背包被送交给了雷霆崖长者高地的拉哈罗。拉哈罗是在玛加萨·野性图腾的直接命令下收下背包的，她曾为任何取回她这位阵亡族人遗物的人悬赏。",al={"谁接收背包","谁上交背包","谁想要恐怖图腾背包"}},{q="为什么一个恐怖图腾成员会带着这个出现在奥格瑞玛下方？",a="玛尔·恐怖图腾是玛加萨·野性图腾的仆从，而玛加萨一直对怒焰裂谷很感兴趣。他进入裂谷是为了与穴居人交涉，并在那里发现了某种奇特的东西，但他没能活着走出洞穴向她展示。",al={"玛尔为什么在怒焰裂谷","恐怖图腾在奥格瑞玛做什么"}},{q="背包里有什么？",a="皮囊里的确切物品已被封存，并直接交给了雷霆崖的拉哈罗。玛加萨希望里面能有关于玛尔在裂谷中发现的那件奇特之物的线索。",al={"背包内容物","袋子里有什么"}}},fp="17,385,12.406.0,26.490.1,37.200.0,31.211.0,31.217.0,50.222.0,27.180.0"}
P.entries["item:grizzled-bear-heart"] = {n="灰熊的心脏",s="灰熊的心脏是一种从银松森林游荡的强壮灰熊身上采集的生物试剂。它是皇家药剂师学会研究The New Plague的严酷实验中不可或缺的重要成分。",h="灰熊的心脏是一种从银松森林游荡的强壮灰熊身上采集的生物试剂。它是皇家药剂师学会研究The New Plague的严酷实验中不可或缺的重要成分。",kw={"死亡配方","药剂师伦弗利尔","灰熊的心脏","大药剂师法拉尼尔","the new plague","老颚","皇家药剂师学会","银松森林","粘稠的血液"},ang={["class:Hunter"]="银松森林体型庞大的灰熊是危险的猎物，追踪像老颚这样的野兽以获取生物样本，是对猎人耐心和剥皮技能的考验。",["race:Undead"]="对于被遗忘者来说，采集这些器官直接有助于大药剂师法拉尼尔研制出对付阿尔萨斯的天灾军团和威胁洛丹伦的活人凡人的终极武器。"},sec={{t="用于The New Plague的试剂",b="皇家药剂师学会夜以继日地工作，试图研制出一种能够消灭天灾军团和活人的瘟疫。在银松森林的林地中，药剂师伦弗利尔发现，从灰熊的心脏中提取的一种独特毒素，如果与粘稠的血液混合，就能产生一种极为致命的混合物。信使和被遗忘者忠诚者们猎杀凶猛的灰熊、巨型灰熊以及臭名昭著的野兽老颚，将这些器官挖出来，直接送到幽暗城药剂师区的大药剂师法拉尼尔手中。"}},faq={{q="灰熊的心脏有什么用途？",a="灰熊的心脏是作为皇家药剂师学会的实验试剂被采集的。药剂师伦弗利尔发现，从这些心脏中提取的毒素可以蒸馏成一种致命的药剂，这是被遗忘者努力制造The New Plague工作的一部分。",al={"熊心有什么用","熊心任务","死亡试剂配方"}},{q="谁需要这些熊心？",a="银松森林的药剂师伦弗利尔指引旅行者们收集这些心脏，并与粘稠的血液一起直接交给幽暗城药剂师区的大药剂师法拉尼尔。",al={"谁需要熊心","法拉尼尔 熊心","我该把熊心交给谁"}},{q="灰熊的心脏来自哪里？",a="它们是从银松森林中游荡的各种灰熊身上割下来的，包括凶猛的灰熊、巨型灰熊以及强大的游荡野兽老颚。",al={"哪里能找到熊心","哪些熊掉落心脏","熊心位置"}},{q="为什么皇家药剂师学会需要天然的动物毒素？",a="该学会正在寻找强效的生物制剂，这种制剂不仅能污染和摧毁活体组织，也能破坏亡灵的生理结构。银松森林那些强壮灰熊的心脏组织中具有独特的化学特性，在与剧毒的蜘蛛血液混合时，能提供理想的反应基质。",al={"为什么药剂师使用熊毒","为什么瘟疫需要动物心脏"}}},fx={["9ca08a87"]={q="什么是灰熊的心脏？",a="这是从银松森林中游荡的凶猛灰熊身上采集的新鲜内脏。乍看之下，它只是普通的器官，但心脏含有一种天然且强韧的生物毒素，因此成为炼金实验中颇受青睐的试剂。",al={"什么是灰熊的心脏","熊心脏信息","灰熊的心脏背景"}}},fp="19,204,28.603.0,39.256.0,28.196.0,40.178.0,65.281.0"}
P.entries["item:grizzled-scalp"] = {n="灰色头皮",s="灰色头皮是剥取自黑海岸南部森林中漫游的灰色蓟熊身上那层厚实多毛的皮。虽然这看起来是一个奇怪的战利品，但古怪的侏儒技师维兹班恩·曲针却在搜集这些皮毛，用来供应他隐藏在荒野中的机械装置。",h="灰色头皮是剥取自黑海岸南部森林中漫游的灰色蓟熊身上那层厚实多毛的皮。虽然这看起来是一个奇怪的战利品，但古怪的侏儒技师维兹班恩·曲针却在搜集这些皮毛，用来供应他隐藏在荒野中的机械装置。",kw={"奥伯丁","525号嗡鸣机","黑海岸","灰色头皮","灰色蓟熊","蓟熊啤酒","维兹班恩·曲针"},ang={["profession:Engineering"]="嗡鸣机网络展示了侏儒将自动化酿酒蒸馏器伪装成野外维修通讯阵列的天赋。",["race:NightElf"]="暗夜精灵保护着黑海岸的野生动物，对于肆意的偷猎和这些破坏他们荒野的侏儒私酒蒸馏器，他们都持否定态度。"},sec={{t="奇特的酿造",b="在奥伯丁以南的道路上狩猎的旅行者们经常会遇到那些饱经风霜的灰色蓟熊，它们以粗糙而厚实的皮毛而闻名。虽然剥下危险捕食者的皮对荒野猎人来说是第二天性，但将四张头皮交给525号嗡鸣机却揭示了一个远没那么体面的目的。这台装置并不需要熊皮来进行工程维修或科学分析。相反，侏儒维兹班恩·曲针利用散布在黑海岸各处的嗡鸣机作为秘密酿酒厂。由于当地的暗夜精灵不赞成在他们的定居点内进行非法酿酒，维兹班恩只能依靠轻信的冒险者去收集熊头皮和其他奇怪的配料，来酿造他心爱的“蓟熊啤酒”。"}},faq={{q="我可以在哪里找到灰色头皮？",a="灰色头皮可以从奥伯丁以南的黑海岸主路沿线森林中的灰色蓟熊及其族母“大兽穴”那里获得。",al={"灰色头皮位置","谁掉落灰色头皮","蓟熊头皮"}},{q="灰色头皮有什么用途？",a="它们被存入525号嗡鸣机，这是一个隐藏在奥伯丁遥远南方的路边灌木丛中的自动化机械终端。",al={"灰色头皮用途","如何使用灰色头皮"}},{q="为什么525号嗡鸣机需要熊头皮？",a="维兹班恩·曲针秘密地使用他的嗡鸣机网络在暗夜精灵的监视下蒸馏私酒。这些灰色头皮是他自酿的蓟熊啤酒的配料。",al={"为什么维兹班恩需要头皮","525号嗡鸣机用途"}},{q="为什么维兹班恩要在他人的黑海岸荒野中隐藏他的酿酒厂？",a="居住在奥伯丁的暗夜精灵们不欢迎未经许可、吵闹的酒精贸易出现在他们神圣的树林里。维兹班恩将他的装置藏在荒野道路旁的灌木丛中，以确保他的私酒生意不被察觉。",al={"为什么隐藏嗡鸣机","维兹班恩黑海岸私酒"}}},fx={["903811df"]={q="什么是灰色头皮？",a="灰色头皮是从暮色森林荒野中游荡的强壮熊类身上剥取的、覆着厚毛的头皮。这些老练的野兽经受着北方严酷气候的考验，长出了坚韧而粗硬的皮毛。捕兽者和好奇的发明家都看重其独特的厚实质地。",al={"什么是灰色头皮","灰色头皮信息","介绍一下灰色头皮"}},e940f924={q="灰色头皮从何而来？",a="这些头皮来自黑海岸的成年荆棘熊，主要是灰色荆棘熊和凶猛的母穴熊。它们不是加工制品，而是直接从奥伯丁以南荒野中游荡的野兽身上取得的战利品。",al={"灰色头皮从何而来","灰色头皮的来源","谁会掉落灰色头皮"}}},fp="14,268,23.726.1,33.162.0,34.133.0,38.194.1,60.237.1"}
P.entries["item:gryshka-s-letter"] = {n="格雷什卡的信",s="《格雷什卡的信》是奥格瑞玛的旅店老板格雷什卡写给十字路口屠夫扎尔夫的一封感谢信。这封信是在收到一批新鲜肉类后寄出的，它既表达了谢意，也作为一种借口，教导年轻的部落信使如何使用双足飞龙管理员网络进行旅行。",h="《格雷什卡的信》是奥格瑞玛的旅店老板格雷什卡写给十字路口屠夫扎尔夫的一封感谢信。这封信是在收到一批新鲜肉类后寄出的，它既表达了谢意，也作为一种借口，教导年轻的部落信使如何使用双足飞龙管理员网络进行旅行。",kw={"贫瘠之地","十字路口","多拉斯","格雷什卡","格雷什卡的信","肉","奥格瑞玛","双足飞龙","扎尔夫"},ang={["faction:Horde"]="《格雷什卡的信》的投递标志着年轻部落冒险者的成年仪式，这是他们初次接触连接杜隆塔尔和贫瘠之地的双足飞龙飞行管理员网络。"},sec={{t="一位感激的旅店老板",b="当扎尔夫将一大捆处理好的牛排从贫瘠之地干旱的旷野运送到奥格瑞玛的中心酒馆时，旅店老板格雷什卡便写下了这封回信。除了对屠夫切下的肉表示满意之外，信中还流露出一种深情——尽管十分粗犷——对扎尔夫的赞赏，回忆起他因处理肉类而弄丢一根手指等滑稽的意外。格雷什卡在信的结尾带着亲昵的戏谑，打趣说即使他被工作弄得满身是血，看起来依然很帅气。"},{t="沿飞行路线的信使",b="携带《格雷什卡的信》为旅行者提供了一堂实用的部落后勤课。为了将羊皮纸送回十字路口，冒险者需要向奥格瑞玛高地上的双足飞龙管理员多拉斯汇报。通过证明旅行者已经向十字路口的迪弗拉克报到，多拉斯向初出茅庐的信使介绍了连接杜隆塔尔和贫瘠之地各个定居点的双足飞龙飞行路线。"}},faq={{q="是谁写了《格雷什卡的信》？",a="奥格瑞玛力量谷繁忙酒馆的经营者，旅店老板格雷什卡，在收到一批新鲜肉类后写下了这封信。",al={"谁写的这封信","格雷什卡的信作者","发件人"}},{q="这封信是写给谁的？",a="这封信是写给扎尔夫的，他是一位驻扎在贫瘠之地十字路口的屠夫，为格雷什卡供应肉类。",al={"收件人","谁收到格雷什卡的信","信寄往何处"}},{q="信里写了什么内容？",a="格雷什卡感谢了屠夫的高品质肉类，戏谑地回忆起他工作中弄丢一根手指的意外，并调侃说他即使流血时看起来也很有魅力。",al={"信件内容","格雷什卡说了什么","信件正文"}},{q="为什么多拉斯需要看这封信？",a="多拉斯是奥格瑞玛的双足飞龙管理员。格雷什卡让你去找他，这样他就可以为你预订飞往十字路口的双足飞龙，以此演示部落空中航线是如何运作的。",al={"为什么要给多拉斯看","双足飞龙管理员多拉斯","奥格瑞玛飞行管理员"}}},fx={["950e527c"]={q="什么是格雷什卡的信？",a="这是一封由奥格瑞玛的旅店老板格雷什卡亲笔写下的感谢信。她收到一批特别送到旅店的肉后写下此信，既是为了表达谢意，也是为了传达爱慕之情，并托人将信带回贫瘠之地。",al={"什么是格雷什卡的信","格雷什卡的信物品","关于格雷什卡的信"}},["0c09fbc7"]={q="为什么有人需要格雷什卡的信？",a="十字路口的屠夫扎尔夫正急切地等待消息，想知道他的上等肉品是否合格雷什卡的心意。格雷什卡希望有人送信，以表达由衷的谢意并回应他的情意；而风骑士管理员多拉斯则只需确认你的目的地，便能安排你乘坐飞行坐骑返回贫瘠之地。",al={"为什么要送格雷什卡的信","谁需要格雷什卡的信","扎尔夫为什么需要格雷什卡的信"}}},fp="16,325,20.483.0,30.447.0,27.149.0,31.118.0,34.181.0,38.174.0"}
P.entries["item:gunther-s-spellbook"] = {n="冈瑟尔的法术书",s="冈瑟尔的法术书是一本属于提瑞斯法林地一位神秘法师的私人奥术典籍。在比索·埃斯沙德施加了附魔之后，这本法术书成为了其他魔法使用者成功摆脱巫妖王控制的证明，尽管其主人与被遗忘者之间的真实历史仍未被揭开。",h="冈瑟尔的法术书是一本属于提瑞斯法林地一位神秘法师的私人奥术典籍。在比索·埃斯沙德施加了附魔之后，这本法术书成为了其他魔法使用者成功摆脱巫妖王控制的证明，尽管其主人与被遗忘者之间的真实历史仍未被揭开。",kw={"阿坎努斯","比索","达拉然","冈瑟尔","埃斯沙德","肯瑞托","法术书","提瑞斯法"},ang={["class:Mage"]="对于奥术使用者来说，这本典籍代表着被遗忘者当前的魔法领导层与荒野中那些特立独行的施法者之间，通过达拉然这一共同根源紧密相连。",["race:Undead"]="这本附魔书凸显了被遗忘者一直在努力招募那些自行摆脱巫妖王控制的强大独立亡灵。"},sec={{t="旧日情谊的信物",b="在第三次战争之前，冈瑟尔·阿坎努斯曾与比索·埃斯沙德和瑟莱·鸦爪作为肯瑞托的成员，一同在达拉然学习奥术。当亡灵天灾席卷洛丹伦时，冈瑟尔不幸战死并被复活为亡灵，但他最终成功夺回了自己的意志，摆脱了天灾军团的控制。由于认为自己孤立无援且时刻受到巫妖王爪牙的追捕，他始终对他者怀有深深的敌意。在法术书被找回后，比索·埃斯沙德在其书页上叠加了一道奥术附魔——这一刻意的魔法签名让冈瑟尔能够辨认出比索的存在，并意识到自己并非唯一拥有自由意志的法师。"}},faq={{q="这是谁的法术书？",a="它属于冈瑟尔·阿坎努斯，一位居住在提瑞斯法林地澈水湖一座孤岛上的强大亡灵法师。",al={"书的主人是谁","冈瑟尔书的主人","法术书的主人"}},{q="比索为什么要给这本法术书附魔？",a="比索在典籍上施加了一道个人法术，作为他依然存活于洛丹伦且已摆脱巫妖王控制的确凿证明，希望能以此说服冈瑟尔加入被遗忘者。",al={"为什么要给书附魔","比索在书上的法术","书的魔法"}},{q="为什么冈瑟尔在书被归还时表现得如此多疑？",a="冈瑟尔认为任何接近他隐居处的人都是天灾军团派来重新奴役他的爪牙，起初甚至认为The Adventurer只是个偷走他典籍的小偷。",al={"为什么冈瑟尔生气","冈瑟尔愤怒","冈瑟尔敌对"}},{q="冈瑟尔和比索是如何认识的？",a="很久以前，在瘟疫夺走他们之前，冈瑟尔、比索·埃斯沙德和瑟莱·鸦爪曾是达拉然城的好友与肯瑞托学徒，一同研习魔法。",al={"比索和冈瑟尔的过去","肯瑞托的联系","达拉然的朋友"}}},fp="19,348,22.651.1,24.124.1,37.199.0,52.175.0,43.167.1"}
